const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 6":["כָּל כֹּהֵן שֶׁיֵּשׁ בּוֹ מוּם בֵּין מוּם קָבוּעַ בֵּין מוּם עוֹבֵר לֹא יִכָּנֵס לַמִּקְדָּשׁ מִן הַמִּזְבֵּחַ וּלְפָנִים שֶׁנֶּאֱמַר (ויקרא כא כג) \"אֶל הַפָּרֹכֶת לֹא יָבֹא וְאֶל הַמִּזְבֵּחַ לֹא יִגַּשׁ\". וְאִם עָבַר וְנִכְנַס לוֹקֶה אַף עַל פִּי שֶׁלֹּא עָבַד. וְאִם עָבַד בַּמִּקְדָּשׁ פָּסַל וְחִלֵּל עֲבוֹדָה וְלוֹקֶה אַף עַל הָעֲבוֹדָה. שֶׁנֶּאֱמַר (ויקרא כא יז) \"אֲשֶׁר יִהְיֶה בוֹ מוּם לֹא יִקְרַב\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאַזְהָרָה זוֹ שֶׁלֹּא יִקְרַב לַעֲבוֹדָה:","וְכֵן בַּעַל מוּם עוֹבֵר שֶׁעָבַד פָּסַל וְלוֹקֶה שֶׁנֶּאֱמַר (ויקרא כא יח) \"כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לְבַעַל מוּם עוֹבֵר. וְאֵין בַּעֲלֵי מוּמִין שֶׁעָבְדוּ בְּמִיתָה אֶלָּא בְּמַלְקוֹת בִּלְבַד:","כָּל הַמּוּמִין כֻּלָּן אֶחָד שֶׁהָיוּ בּוֹ מִתְּחִלַּת בְּרִיָּתוֹ וְאֶחָד שֶׁנּוֹלְדוּ בּוֹ אַחַר כֵּן בֵּין עוֹבְרִין בֵּין שֶׁאֵינָן עוֹבְרִין הֲרֵי זֶה פָּסוּל עַד שֶׁיַּעֲבוֹרוּ:","מוּם קָבוּעַ כְּגוֹן שֶׁבֶר רֶגֶל אוֹ שֶׁבֶר יָד. וּמוּם עוֹבֵר כְּגוֹן גָּרָב אוֹ יַלֶּפֶת וְהִיא הַחֲזָזִית. וְלֹא הַמּוּמִין הַכְּתוּבִין בַּתּוֹרָה בִּלְבַד הֵן שֶׁפְּסוּלִין בְּכֹהֲנִים אֶלָּא כָּל הַמּוּמִין הַנִּרְאִין בַּגּוּף שֶׁנֶּאֱמַר (ויקרא כא יח) (ויקרא כא כא) \"כֹּל אֲשֶׁר בּוֹ מוּם\" מִכָּל מָקוֹם. וְאֵלּוּ הַכְּתוּבִים בַּתּוֹרָה דֻּגְמָא הֵן:","שְׁלֹשָׁה מִינֵי מוּמִין הֵם. יֵשׁ מוּמִין שֶׁהֵן פּוֹסְלִין הַכֹּהֵן מִלַּעֲבֹד וְהַבְּהֵמָה מִלִּקָּרֵב. [וְיֵשׁ מוּמִין שֶׁפּוֹסְלִין בָּאָדָם בִּלְבַד מִלַּעֲבֹד]. וְיֵשׁ מוּמִין שֶׁאֵין פּוֹסְלִין אֲבָל מִפְּנֵי מַרְאִית הָעַיִן אָמְרוּ שֶׁכָּל כֹּהֵן שֶׁיֵּשׁ בּוֹ אֶחָד מֵהֶן אֵינוֹ עוֹבֵד:","כָּל מִי שֶׁיֵּשׁ בּוֹ מוּם שֶׁפּוֹסֵל בָּאָדָם וּבַבְּהֵמָה וְעָבַד בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד עֲבוֹדָתוֹ פְּסוּלָה. וְאִם הָיָה מֵזִיד לוֹקֶה. וְכָל מִי שֶׁיֵּשׁ בּוֹ מוּם מִן הַמּוּמִין הַמְיֻחָדִין לָאָדָם וְעָבַד אַף עַל פִּי שֶׁהוּא לוֹקֶה לֹא חִלֵּל עֲבוֹדָתוֹ. וְאִם הָיָה בּוֹ דָּבָר מִדְּבָרִים שֶׁהֵם מִפְּנֵי מַרְאִית הָעַיִן אֵינוֹ לוֹקֶה וַעֲבוֹדָתוֹ כְּשֵׁרָה:","אֵין פּוֹסֵל בָּאָדָם אֶלָּא מוּמִין שֶׁבְּגָלוּי. אֲבָל מוּמִין שֶׁבַּחֲלַל הַגּוּף כְּגוֹן שֶׁנִּטַּל כֻּלְיָתוֹ שֶׁל אָדָם אוֹ טְחוֹל שֶׁלּוֹ אוֹ שֶׁנִּקְּבוּ מֵעָיו אַף עַל פִּי שֶׁנַּעֲשָׂה טְרֵפָה עֲבוֹדָתוֹ כְּשֵׁרָה שֶׁנֶּאֱמַר (ויקרא כא יט) \"שֶׁבֶר רָגֶל אוֹ שֶׁבֶר יָד\" מָה אֵלּוּ בְּגָלוּי אַף כּל בְּגָלוּי:","הֶעָרֵל הֲרֵי הוּא כְּבֶן נֵכָר שֶׁנֶּאֱמַר (יחזקאל מד ט) \"כָּל בֶּן נֵכָר עֶרֶל לֵב וְעֶרֶל בָּשָׂר\". לְפִיכָךְ עָרֵל שֶׁעָבַד חִלֵּל עֲבוֹדָתוֹ וְלוֹקֶה כְּזָר שֶׁעָבַד. אֲבָל אֵינוֹ חַיָּב מִיתָה:","כֹּהֵן שֶׁהָיָה נוֹשֵׂא נָשִׁים בַּעֲבֵרָה אֵינוֹ עוֹבֵד עַד שֶׁיַּדִּירוּהוּ בֵּית דִּין עַל דַּעַת רַבִּים כְּדֵי שֶׁלֹּא יִהְיֶה לוֹ הֲפָרָה שֶׁלֹּא יוֹסִיף לַחֲטֹא וְעוֹבֵד וְיוֹרֵד וּמְגָרֵשׁ. וְכֵן אִם הָיָה מִטַּמֵּא לְמֵתִים פָּסוּל עַד שֶׁיְּקַבֵּל עָלָיו בְּבֵית דִּין שֶׁלֹּא יִטַּמֵּא. וְאִם עָבַר וְעָבַד קֹדֶם שֶׁיַּדִּיר אוֹ שֶׁיְּקַבֵּל אַף עַל פִּי שֶׁהוּא נָשׂוּי בַּעֲבֵרָה לֹא חִלֵּל עֲבוֹדָה:","כֹּהֵן שֶׁעָבַד וְנִבְדַּק וְנִמְצָא חָלָל עֲבוֹדָתוֹ כְּשֵׁרָה לְשֶׁעָבַר וְאֵינוֹ עוֹבֵד לְהַבָּא. וְאִם עָבַד לֹא חִלֵּל שֶׁנֶּאֱמַר (דברים לג יא) \"בָּרֵךְ ה' חֵילוֹ וּפֹעַל יָדָיו תִּרְצֶה\" אַף חֻלִּין שֶׁבּוֹ תִּרְצֶה:","בֵּית דִּין הַגָּדוֹל הָיוּ יוֹשְׁבִין בְּלִשְׁכַּת הַגָּזִית. וְעִקַּר מַעֲשֵׂיהֶם הַתָּדִיר שֶׁהָיוּ יוֹשְׁבִין וְּדָנִין אֶת הַכְּהֻנָּה וּבוֹדְקִין הַכֹּהֲנִים בְּיוּחֲסִין וּבְמוּמִין. כָּל כֹּהֵן שֶׁנִּמְצָא פָּסוּל בְּיִחוּסוֹ לוֹבֵשׁ שְׁחוֹרִים וּמִתְעַטֵּף שְׁחוֹרִים וְיוֹצֵא מִן הָעֲזָרָה. וְכָל מִי שֶׁנִּמְצָא שָׁלֵם וְכָשֵׁר לוֹבֵשׁ לְבָנִים וְנִכְנָס וּמְשַׁמֵּשׁ עִם אֶחָיו הַכֹּהֲנִים:","מִי שֶׁנִּמְצָא כָּשֵׁר בְּיִחוּסוֹ וְנִמְצָא בּוֹ מוּם. יוֹשֵׁב בְּלִשְׁכַּת הָעֵצִים וּמְתַלֵּעַ עֵצִים לַמַּעֲרָכָה וְחוֹלֵק בְּקָדָשִׁים עִם אַנְשֵׁי בֵּית אָב שֶׁלּוֹ וְאוֹכֵל שֶׁנֶּאֱמַר (ויקרא כא כב) \"לֶחֶם אֱלֹהָיו מִקָּדְשֵׁי הַקָּדָשִׁים וּמִן הַקָּדָשִׁים יֹאכֵל\":"],"Mishneh Torah, Agents and Partners 8":["הַנּוֹתֵן בֵּיצִים לְבַעַל הַתַּרְנְגוֹלִים לְהוֹשִׁיב הַתַּרְנְגוֹלִים עֲלֵיהֶן עַד שֶׁיֵּצְאוּ הָאֶפְרוֹחִים וִיגַדֵּל אוֹתָן בַּעַל הַתַּרְנְגוֹלִים וְיִהְיֶה הָרֶוַח בֵּינֵיהֶם צָרִיךְ לְהַעֲלוֹת לוֹ שְׂכַר עֲמָלוֹ וּמְזוֹנוֹ. וְכֵן הַשָּׁם עֲגָלִים וּסְיָחִים עַל הָרוֹעֶה לִהְיוֹת מִתְעַסֵּק בָּהֶן שֶׁיַּגְדִּילוּ וְהַשָּׂכָר לָאֶמְצַע חַיָּב לְהַעֲלוֹת לוֹ שְׂכַר עֲמָלוֹ וּמְזוֹנוֹ בְּכָל יוֹם כְּפוֹעֵל בָּטֵל. וּמְגַדֵּל אוֹתָן עַד שֶׁיִּהְיוּ הָעֲגָלִים בְּנֵי שָׁלֹשׁ שָׁנִים וְהַחֲמוֹר עַד שֶׁתְּהֵא טוֹעֶנֶת. וְאֵינוֹ יָכוֹל לִמְכֹּר שֶׁלֹּא מִדַּעַת חֲבֵרוֹ בְּתוֹךְ זְמַן זֶה. וְכֵן הַשָּׁם בְּהֵמָה עַל הַמְפַטֵּם לִהְיוֹת מְפַטֵּם אוֹתָהּ וְהַשָּׂכָר לָאֶמְצַע צָרִיךְ לִתֵּן עֲמָלוֹ כְּפוֹעֵל בָּטֵל. וְאִם אָמַר לוֹ הֲרֵי הָרֹאשׁ וְהָאַלְיָה שֶׁלְּךָ בַּעֲמָלְךָ יֶתֶר עַל מַחֲצִית הַשָּׂכָר מֻתָּר. הָיוּ לַמְפַטֵּם בְּהֵמוֹת אֲחֵרוֹת שֶׁמְּפַטֵּם אוֹתָם עִם זוֹ הַשּׁוּמָא אֶצְלוֹ. וְכֵן אִם הָיוּ לוֹ עֲגָלִים וּסְיָחִין אֲחֵרִים אוֹ בֵּיצִים אֲחֵרוֹת שֶׁלּוֹ. הוֹאִיל וְהוּא מִתְעַסֵּק בְּשֶׁלּוֹ וּבְשֶׁל חֲבֵרוֹ אֲפִלּוּ לֹא הֶעֱלָה לוֹ אֶלָּא דָּבָר מוּעָט בְּכָל יְמֵי הַשֻּׁתָּפוּת הַזֹּאת דַּיּוֹ וְחוֹלֵק בְּשָׂכָר בְּשָׁוֶה. וְאִם הָיָה אֲרִיסוֹ הוֹאִיל וְהוּא מְטַפֵּל בְּשֶׁלּוֹ וּבְשֶׁל בַּעַל הַשָּׂדוֹת אֵין צָרִיךְ לְהַעֲלוֹת לוֹ כְּלוּם:","הַשָּׁם עֲגָלִים אוֹ סְיָחִין אוֹ הוֹשִׁיב תַּרְנְגוֹלִים אוֹ שָׁם בְּהֵמָה עַל הַפַּטָּם לְמַחֲצִית שָׂכָר וְלֹא הֶעֱלָה לוֹ שָׂכָר הֲרֵי דִּינוֹ כְּדִין הָעֵסֶק שֶׁל מָעוֹת. רוֹאִין בְּכַמָּה שָׁמִין הַבְּהֵמוֹת אוֹ הַבֵּיצִים וְכַמָּה הִרְוִיחוּ וְנוֹטֵל הַמִּתְעַסֵּק שְׁנֵי שְׁלִישֵׁי הַשָּׂכָר. וְאִם הִפְסִידוּ מְשַׁלֵּם שְׁלִישׁ הַהֶפְסֵד:","שָׁמִין פָּרָה וַחֲמוֹר וְכָל דָּבָר שֶׁדַּרְכּוֹ לַעֲשׂוֹת וְלֶאֱכל וְיִהְיֶה הַשָּׂכָר לָאֶמְצַע אַף עַל פִּי שֶׁזֶּה מִתְעַסֵּק הֲרֵי יֵשׁ לוֹ רֶוַח אַחֵר לְעַצְמוֹ בַּעֲבוֹדַת הַבְּהֵמוֹת שֶׁהֲרֵי שׂוֹכֵר אוֹתָהּ אוֹ עוֹבֵד בָּהּ וְנֶהֱנֶה בִּשְׂכָרָהּ וּבַעֲבוֹדָתָהּ. וְאֵין שָׁמִין עֵגֶל עִם אִמּוֹ וְלֹא סְיָח עִם אִמּוֹ שֶׁהָעֵגֶל וְהַסְּיָח אֵינוֹ עוֹשֶׂה כְּלוּם וְיֵשׁ בּוֹ עֵסֶק:","הַשָּׁם בְּהֵמָה לַחֲבֵרוֹ עַד מָתַי חַיָּב לְטַפֵּל בָּהּ. בַּאֲתוֹנוֹת שְׁמוֹנָה עָשָׂר חֹדֶשׁ. וּבְגוֹדְרוֹת וְהֵן הַצֹּאן וְהַבָּקָר אַרְבָּעָה וְעֶשְׂרִים חֹדֶשׁ. וְאִם בָּא לַחֲלֹק בְּתוֹךְ זְמַן זֶה חֲבֵרוֹ מְעַכֵּב עָלָיו מִפְּנֵי שֶׁנִּשְׁתַּתְּפוּ סְתָם לְפִי שֶׁאֵינוֹ דּוֹמֶה טְפִילָה שֶׁל שָׁנָה רִאשׁוֹנָה שֶׁהִיא מְרֻבָּה וְהָרֶוַח מוּעָט שֶׁאֵינָהּ מִשְׁתַּמֶּנֶת בַּתְּחִלָּה אֶלָּא בְּקֹשִׁי לִטְפִילָה שֶׁל שָׁנָה הָאַחֶרֶת שֶׁהִיא מוּעֶטֶת וְהָרֶוַח מְרֻבֶּה שֶׁהֲרֵי הִיא מִשְׁתַּמֶּנֶת הַרְבֵּה וּמוֹסֶפֶת בְּכָל יוֹם. לְפִיכָךְ מְעַכֵּב עָלָיו עַד סוֹף שָׁנָה שְׁנִיָּה. יָלְדָה הַבְּהֵמָה הַשּׁוּמָה אֶצְלוֹ הֲרֵי הַוָּלָד מִכְּלַל הָרֶוַח לָאֶמְצַע. מָקוֹם שֶׁנָּהֲגוּ לְגַדֵּל וַלְדוֹתָם יְגַדְּלוּ וְאַחַר כָּךְ יִמָּכְרוּ. מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לְגַדֵּל חַיָּב הַמִּתְעַסֵּק לְהִטַּפֵּל בַּוְּלָדוֹת בְּדַקָּה שְׁלֹשִׁים יוֹם וּבְגַסָּה חֲמִשִּׁים יוֹם וְחוֹלְקִין. רָצָה לְהִטַּפֵּל בָּהֶן יֶתֶר עַל זְמַן זֶה שָׁם אוֹתָן בִּפְנֵי שְׁלֹשָׁה בְּיוֹם שְׁלֹשִׁים וּבְיוֹם הַחֲמִשִּׁים וְכָל שֶׁיַּרְוִיחוּ אַחַר כָּךְ יִטּל הַמִּתְעַסֵּק שְׁלֹשָׁה חֲלָקִים וַחֲבֵרוֹ רְבִיעַ הָרֶוַח שֶׁהֲרֵי יֵשׁ לוֹ חֲצִי הַוָּלָד. וּמִפְּנֵי שֶׁנִּתְעַסֵּק בְּחֵצִי שֶׁל חֲבֵרוֹ נוֹטֵל חֲצִי אוֹתוֹ הַחֵצִי. הֲרֵי שְׁלֹשָׁה רְבָעִים. וְאִם לֹא הִתְנָה כֵּן בִּפְנֵי שְׁלֹשָׁה הֲרֵי מָחַל וְהַוְּלָדוֹת בֵּינֵיהֶן בְּשָׁוֶה כְּמוֹת שֶׁהֵן. מָקוֹם שֶׁנָּהֲגוּ לְהַעֲלוֹת שְׂכַר כַּתָּף לִמְעוֹת הָעֵסֶק מַעֲלִין וְיִהְיֶה כָּל הַשָּׂכָר שֶׁנּוֹטֵל הַמִּתְעַסֵּק בַּשָּׂכָר שֶׁנּוֹשֵׂא עַל כְּתֵפוֹ בִּכְלַל שְׂכַר הַמָּעוֹת. וְכֵן אִם דַּרְכָּן לְהַעֲלוֹת שְׂכַר בְּהֵמָה מַעֲלִין לוֹ. מָקוֹם שֶׁנָּהֲגוּ לְהַעֲלוֹת שְׂכַר וְלָדוֹת בִּשְׂכַר עֲמָלוֹ מַעֲלִין. וְכָל הַמִּתְעַסֵּק אוֹ הַמִּשְׁתַּתֵּף סְתָם לֹא יְשַׁנֶּה מִמִּנְהַג הַמְּדִינָה:","רְאוּבֵן שֶׁהָיְתָה לוֹ שָׂדֶה וְהוֹרִיד שִׁמְעוֹן לְתוֹכָהּ לְזָרְעָהּ אוֹ לְנָטְעָהּ וּלְהוֹצִיא עָלֶיהָ הוֹצָאוֹת וְלִמְכֹּר הַפֵּרוֹת וְכָל הַיָּתֵר עַל הַהוֹצָאָה יִהְיֶה בֵּינֵיהֶם בֵּין שֶׁהִתְנוּ שֶׁיַּחְלְקוּ בְּשָׁוֶה בֵּין שֶׁהִתְנוּ שֶׁיִּטּל רְאוּבֵן יֶתֶר בֵּין שֶׁהָיְתָה הַהוֹצָאָה כֻּלָּהּ מִשֶּׁל רְאוּבֵן בֵּין שֶׁהָיְתָה מִשֶּׁל שִׁמְעוֹן. בְּכָל זֶה מֻתָּר וְאֵין כָּאן אֲבַק רִבִּית. וְשִׁמְעוֹן הַמִּטַּפֵּל בַּעֲבוֹדַת הָאָרֶץ וּבַהוֹצָאָה וּבִמְכִירַת הַפֵּרוֹת הוּא הַנִּקְרָא אָרִיס. אָרִיס אוֹמֵר לְמֶחֱצָה יָרַדְתִּי וּבַעַל הַשָּׂדֶה אוֹמֵר לִשְׁלִישׁ הוֹרַדְתִּיו הוֹלְכִין אַחֵר מִנְהַג הַמְּדִינָה וְזֶה שֶׁטָּעַן שֶׁלֹּא כַּמִּנְהַג עָלָיו לְהָבִיא רְאָיָה:","בַּעַל שֶׁהוֹרִיד אֲרִיסִין בְּנִכְסֵי אִשְׁתּוֹ וְגֵרְשָׁהּ אִם הָיָה הַבַּעַל אָרִיס הוֹאִיל וְנִסְתַּלֵּק בַּעַל נִסְתַּלְּקוּ הֵם וְאֵין לָהֶם מִן הַהוֹצָאָה אֶלָּא שִׁעוּר הַשֶּׁבַח וּבִשְׁבוּעָה. וְאִם אֵין הַבַּעַל אָרִיס עַל דַּעַת [מִנְהַג] הָאָרֶץ יֵרְדוּ וְשָׁמִין לָהֶם כְּאָרִיס:","הָאַחִין אוֹ שְׁאָר הַיּוֹרְשִׁין שֶׁלֹּא חָלְקוּ יְרֻשַּׁת מוֹרִישָׁן אֶלָּא כֻּלָּן מִשְׁתַּמְּשִׁין בָּהּ בְּיַחַד הֲרֵי הֵן כְּשֻׁתָּפִין לְכָל דָּבָר. אֶחָד מִן הָאַחִין אוֹ מִן הַשֻּׁתָּפִין שֶׁנָּפַל לְאֻמְּנוּת הַמֶּלֶךְ הָרֶוַח לָאֶמְצַע. חָלָה אֶחָד מֵהֶן וְנִתְרַפֵּא נִתְרַפֵּא מִן הָאֶמְצַע. וְאִם חָלָה בִּפְשִׁיעָה כְּגוֹן שֶׁהָלַךְ בַּשֶּׁלֶג אוֹ בַּחַמָּה בִּימֵי הַחֹם עַד שֶׁחָלָה וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה מִתְרַפֵּא מִשֶּׁל עַצְמוֹ:"],"Mishneh Torah, Blessings 11":["כָּל הַבְּרָכוֹת כֻּלָּן פּוֹתֵחַ בָּהֶם בְּבָרוּךְ וְחוֹתֵם בָּהֶם בְּבָרוּךְ חוּץ מִבְּרָכָה אַחֲרוֹנָה שֶׁל קְרִיאַת שְׁמַע וּבְרָכָה הַסְּמוּכָה לַחֲבֵרְתָהּ וּבִרְכַּת הַפֵּרוֹת וְהַדּוֹמֶה לָהּ וּבִרְכַּת עֲשִׂיַּת הַמִּצְוֹת. וּמֵאֵלּוּ הַבְּרָכוֹת שֶׁאָמַרְנוּ שֶׁהֵן דֶּרֶךְ שֶׁבַח וְהוֹדָיָה יֵשׁ מֵהֶן פּוֹתֵחַ בְּבָרוּךְ וְאֵינוֹ חוֹתֵם בְּבָרוּךְ. וְיֵשׁ מֵהֶן שֶׁהוּא חוֹתֵם בְּבָרוּךְ וְאֵינוֹ פּוֹתֵחַ בְּבָרוּךְ, אֶלָּא מְעַט מִבִּרְכַּת הַמִּצְוֹת כְּגוֹן בִּרְכַּת סֵפֶר תּוֹרָה וְרוֹאֶה קִבְרֵי יִשְׂרָאֵל מֵאֵלּוּ שֶׁהֵן דֶּרֶךְ שֶׁבַח וְהוֹדָיָה. אֲבָל שְׁאָר בִּרְכוֹת הַמִּצְוֹת כֻּלָּן פּוֹתֵחַ בָּהֶן בְּבָרוּךְ וְאֵינוֹ חוֹתֵם:","יֵשׁ מִצְוֹת עֲשֵׂה שֶׁאָדָם חַיָּב לְהִשְׁתַּדֵּל וְלִרְדֹּף עַד שֶׁיַּעֲשֶׂה אוֹתָהּ כְּגוֹן תְּפִלִּין וְסֻכָּה וְלוּלָב וְשׁוֹפָר וְאֵלּוּ הֵן הַנִּקְרָאִין חוֹבָה. לְפִי שֶׁאָדָם חַיָּב עַל כָּל פָּנִים לַעֲשׂוֹת. וְיֵשׁ מִצְוָה שֶׁאֵינָהּ חוֹבָה אֶלָּא דּוֹמִין לִרְשׁוּת כְּגוֹן מְזוּזָה וּמַעֲקֶה שֶׁאֵין אָדָם חַיָּב לִשְׁכֹּן בְּבַיִת הַחַיָּב מְזוּזָה כְּדֵי שֶׁיַּעֲשֶׂה מְזוּזָה אֶלָּא אִם רָצָה לִשְׁכֹּן כָּל יָמָיו בְּאֹהֶל אוֹ בִּסְפִינָה יֵשֵׁב. וְכֵן אֵינוֹ חַיָּב לִבְנוֹת בַּיִת כְּדֵי לַעֲשׂוֹת מַעֲקֶה. וְכָל מִצְוֹת עֲשֵׂה שֶׁבֵּין אָדָם לַמָּקוֹם בֵּין מִצְוָה שֶׁאֵינָהּ חוֹבָה בֵּין מִצְוָה שֶׁהִיא חוֹבָה מְבָרֵךְ עָלֶיהָ קֹדֶם לַעֲשִׂיָּתָהּ:","וְכֵן כָּל הַמִּצְוֹת שֶׁהֵן מִדִּבְרֵי סוֹפְרִים בֵּין מִצְוָה שֶׁהִיא חוֹבָה מִדִּבְרֵיהֶם כְּגוֹן מִקְרָא מְגִלָּה וְהַדְלָקַת נֵר בְּשַׁבָּת וְהַדְלָקַת נֵר חֲנֻכָּה. בֵּין מִצְוֹת שֶׁאֵינָן חוֹבָה כְּגוֹן עֵרוּב וּנְטִילַת יָדַיִם. מְבָרֵךְ עַל הַכּל קדֶם לַעֲשִׂיָּתָן אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לַעֲשׂוֹת. וְהֵיכָן צִוָּנוּ בַּתּוֹרָה. שֶׁכָּתוּב בָּהּ (דברים יז יא) ״אֲשֶׁר יֹאמְרוּ לְךָ תַּעֲשֶׂה״. נִמְצָא עִנְיַן הַדְּבָרִים וְהֶצֵּעָן כָּךְ הוּא. אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו שֶׁצִּוָּה בָּהֶן לִשְׁמֹעַ מֵאֵלּוּ שֶׁצִּוָּנוּ לְהַדְלִיק נֵר שֶׁל חֲנֻכָּה אוֹ לִקְרוֹת אֶת הַמְּגִלָּה. וְכֵן שְׁאָר כָּל הַמִּצְוֹת שֶׁמִּדִּבְרֵי סוֹפְרִים:","וְלָמָּה אֵין מְבָרְכִין עַל נְטִילַת יָדַיִם בָּאַחֲרוֹנָה. מִפְּנֵי שֶׁלֹּא חִיְּבוּ בְּדָבָר זֶה אֶלָּא מִפְּנֵי הַסַּכָּנָה וּדְבָרִים שֶׁהֵם מִשּׁוּם סַכָּנָה אֵין מְבָרְכִין עֲלֵיהֶם. הָא לְמָה זֶה דּוֹמֶה לְמִי שֶׁסִּנֵּן אֶת הַמַּיִם וְאַחַר כָּךְ שָׁתָה בַּלַּיְלָה מִפְּנֵי סַכָּנַת עֲלוּקָה שֶׁאֵינוֹ מְבָרֵךְ וְצִוָּנוּ לְסַנֵּן אֶת הַמַּיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","העוֹשֶׂה מִצְוָה וְלֹא בֵּרֵךְ. אִם מִצְוָה שֶׁעֲדַיִן עֲשִׂיָּתָהּ קַיֶּמֶת מְבָרֵךְ אַחַר עֲשִׂיָּה וְאִם דָּבָר שֶׁעָבַר הוּא אֵינוֹ מְבָרֵךְ. כֵּיצַד. הֲרֵי שֶׁנִּתְעַטֵּף בְּצִיצִית אוֹ שֶׁלָּבַשׁ תְּפִלִּין אוֹ שֶׁיָּשַׁב בְּסֻכָּה וְלֹא בֵּרֵךְ תְּחִלָּה חוֹזֵר וּמְבָרֵךְ אַחַר שֶׁנִּתְעַטֵּף אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהִתְעַטֵּף בְּצִיצִית. וְכֵן מְבָרֵךְ אַחַר שֶׁלָּבַשׁ לְהָנִיחַ תְּפִלִּין. וְאַחַר שֶׁיָּשַׁב לֵישֵׁב בַּסֻּכָּה. וְכֵן כָּל כַּיּוֹצֵא בָּאֵלּוּ:","אֲבָל אִם שָׁחַט בְּלֹא בְּרָכָה אֵינוֹ חוֹזֵר אַחַר שְׁחִיטָה וּמְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל הַשְּׁחִיטָה. וְכֵן אִם כִּסָּה הַדָּם בְּלֹא בְּרָכָה אוֹ הִפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת אוֹ שֶׁטָּבַל וְלֹא בֵּרֵךְ אֵינוֹ חוֹזֵר וּמְבָרֵךְ אַחַר עֲשִׂיָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין לְךָ מִצְוָה שֶׁמְּבָרְכִין אַחַר עֲשִׂיָּתָהּ אֶלָּא טְבִילַת הַגֵּר בִּלְבַד שֶׁאֵינוֹ יָכוֹל לוֹמַר אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ שֶׁעֲדַיִן לֹא נִתְקַדֵּשׁ וְלֹא נִצְטַוָּה עַד שֶׁיִּטְבּל. לְפִיכָךְ אַחַר שֶׁיִּטְבּל מְבָרֵךְ עַל הַטְּבִילָה מִפְּנֵי שֶׁהָיָה דָּחוּי מֵעִקָּרוֹ וְלֹא הָיָה רָאוּי לְבָרֵךְ:","כָּל מִצְוָה שֶׁעֲשִׂיָּתָהּ הִיא גְּמַר חִיּוּבָהּ מְבָרֵךְ בִּשְׁעַת עֲשִׂיָּה. וְכָל מִצְוָה שֶׁיֵּשׁ אַחַר עֲשִׂיָּתָהּ צִוּוּי אַחֵר אֵינוֹ מְבָרֵךְ אֶלָּא בְּשָׁעָה שֶׁעוֹשֶׂה הַצִּוּוּי הָאַחֲרוֹן. כֵּיצַד. הָעוֹשֶׂה סֻכָּה אוֹ לוּלָב אוֹ שׁוֹפָר אוֹ צִיצִית אוֹ תְּפִלִּין אוֹ מְזוּזָה אֵינוֹ מְבָרֵךְ בִּשְׁעַת עֲשִׂיָּה אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לַעֲשׂוֹת סֻכָּה אוֹ לוּלָב אוֹ לִכְתֹּב תְּפִלִּין מִפְּנֵי שֶׁיֵּשׁ אַחַר עֲשִׂיָּתוֹ צִוּוּי אַחֵר. וְאֵימָתַי מְבָרֵךְ בְּשָׁעָה שֶׁיֵּשֵׁב בַּסֻּכָּה אוֹ כְּשֶׁיְּנַעֲנֵעַ הַלּוּלָב אוֹ כְּשֶׁיִּשְׁמַע קוֹל הַשּׁוֹפָר אוֹ כְּשֶׁיִּתְעַטֵּף בַּצִּיצִית וּבִשְׁעַת לְבִישַׁת תְּפִלִּין וּבִשְׁעַת קְבִיעַת מְזוּזָה. אֲבָל אִם עָשָׂה מַעֲקֶה מְבָרֵךְ בִּשְׁעַת עֲשִׂיָּה אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לַעֲשׂוֹת מַעֲקֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל מִצְוָה שֶׁהִיא מִזְּמַן לִזְמַן כְּגוֹן שׁוֹפָר וְסֻכָּה וְלוּלָב וּמִקְרָא מְגִלָּה וְנֵר חֲנֻכָּה. וְכֵן כָּל מִצְוָה וּמִצְוָה שֶׁהִיא קִנְיָן לוֹ כְּגוֹן צִיצִית וּתְפִלִּין וּמְזוּזָה וּמַעֲקֶה. וְכֵן מִצְוָה שֶׁאֵינָהּ תְּדִירָה וְאֵינָהּ מְצוּיָה בְּכָל עֵת שֶׁהֲרֵי הִיא דּוֹמָה לְמִצְוָה שֶׁהִיא מִזְּמַן לִזְמַן כְּגוֹן מִילַת בְּנוֹ וּפִדְיוֹן הַבֵּן, מְבָרֵךְ עָלֶיהָ בִּשְׁעַת עֲשִׂיָּתָהּ שֶׁהֶחֱיָנוּ. וְאִם לֹא בֵּרֵךְ עַל סֻכָּה וְלוּלָב וְכַיּוֹצֵא בָּהֶם שֶׁהֶחֱיָנוּ בִּשְׁעַת עֲשִׂיָּה מְבָרֵךְ עֲלֵיהֶן שֶׁהֶחֱיָנוּ בְּשָׁעָה שֶׁיֵּצֵא יְדֵי חוֹבָתוֹ בָּהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","אֶחָד הָעוֹשֶׂה מִצְוָה לְעַצְמוֹ וְאֶחָד הָעוֹשֶׂה אוֹתָהּ לַאֲחֵרִים מְבָרֵךְ קֹדֶם עֲשִׂיָּתָהּ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לַעֲשׂוֹת. אֲבָל אֵינוֹ מְבָרֵךְ שֶׁהֶחֱיָנוּ אֶלָּא עַל מִצְוָה שֶׁעוֹשֶׂה אוֹתָהּ לְעַצְמוֹ. הָיוּ לְפָנָיו מִצְוֹת הַרְבֵּה אֵינוֹ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל הַמִּצְוֹת אֶלָּא מְבָרֵךְ עַל כָּל אַחַת וְאַחַת בִּפְנֵי עַצְמָהּ:","כָּל הָעוֹשֶׂה מִצְוָה בֵּין שֶׁהָיְתָה חוֹבָה עָלָיו בֵּין שֶׁאֵינָהּ חוֹבָה עָלָיו אִם עָשָׂה אוֹתָהּ לְעַצְמוֹ מְבָרֵךְ לַעֲשׂוֹת. עָשָׂה אוֹתָהּ לַאֲחֵרִים מְבָרֵךְ עַל הָעֲשִׂיָּה:","כֵּיצַד. לָבַשׁ תְּפִלִּין מְבָרֵךְ לְהָנִיחַ תְּפִלִּין. נִתְעַטֵּף בְּצִיצִית מְבָרֵךְ לְהִתְעַטֵּף. יָשַׁב בְּסֻכָּה מְבָרֵךְ לֵישֵׁב בַּסֻּכָּה. וְכֵן הוּא מְבָרֵךְ לְהַדְלִיק נֵר שֶׁל שַׁבָּת וְלִגְמֹר אֶת הַהַלֵּל. וְכֵן אִם קָבַע מְזוּזָה לְבֵיתוֹ מְבָרֵךְ לִקְבֹּעַ מְזוּזָה. עָשָׂה מַעֲקֶה לְגַגּוֹ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לַעֲשׂוֹת מַעֲקֶה. הִפְרִישׁ תְּרוּמָה לְעַצְמוֹ מְבָרֵךְ לְהַפְרִישׁ. מָל אֶת בְּנוֹ מְבָרֵךְ לָמוּל אֶת הַבֵּן. שָׁחַט פִּסְחוֹ וַחֲגִיגָתוֹ מְבָרֵךְ לִשְׁחֹט:","אֲבָל אִם קָבַע מְזוּזָה לַאֲחֵרִים מְבָרֵךְ עַל קְבִיעַת מְזוּזָה. עָשָׂה לָהֶם מַעֲקֶה מְבָרֵךְ עַל עֲשִׂיַּת מַעֲקֶה. הִפְרִישׁ לָהֶם תְּרוּמָה מְבָרֵךְ עַל הַפְרָשַׁת תְּרוּמָה. מָל אֶת בֶּן חֲבֵרוֹ מְבָרֵךְ עַל הַמִּילָה. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ:","עָשָׂה הַמִּצְוָה לוֹ וְלַאֲחֵרִים כְּאֶחָד אִם הָיְתָה מִצְוָה שֶׁאֵינָהּ חוֹבָה מְבָרֵךְ עַל הָעֲשִׂיָּה. לְפִיכָךְ הוּא מְבָרֵךְ עַל מִצְוַת עֵרוּב. הָיְתָה חוֹבָה וְנִתְכַּוֵּן לְהוֹצִיא עַצְמוֹ מִידֵי חוֹבָה וּלְהוֹצִיא אֲחֵרִים מְבָרֵךְ לַעֲשׂוֹת. לְפִיכָךְ הוּא מְבָרֵךְ לִשְׁמֹעַ קוֹל שׁוֹפָר:","נָטַל אֶת הַלּוּלָב מְבָרֵךְ עַל נְטִילַת לוּלָב שֶׁכֵּיוָן שֶׁהִגְבִּיהוֹ יָצָא יְדֵי חוֹבָתוֹ. אֲבָל אִם בֵּרֵךְ קֹדֶם שֶׁיִּטּל מְבָרֵךְ לִטּל לוּלָב כְּמוֹ לֵישֵׁב בַּסֻּכָּה. מִכָּאן אַתָּה לָמֵד שֶׁהַמְבָרֵךְ אַחַר שֶׁעָשָׂה מְבָרֵךְ עַל הָעֲשִׂיָּה. אֲבָל נְטִילַת יָדַיִם וּשְׁחִיטָה הוֹאִיל וּבְדִבְרֵי הָרְשׁוּת הֵן אֲפִלּוּ שָׁחַט לְעַצְמוֹ מְבָרֵךְ עַל הַשְּׁחִיטָה וְעַל כִּסּוּי הַדָּם וְעַל נְטִילַת יָדַיִם. וְכָךְ הוּא מְבָרֵךְ עַל בִּעוּר חָמֵץ בֵּין שֶׁבָּדַק לְעַצְמוֹ בֵּין שֶׁבָּדַק לַאֲחֵרִים שֶׁמִּשָּׁעָה שֶׁגָּמַר בְּלִבּוֹ לְבַטֵּל נַעֲשֵׂית מִצְוַת הַבִּעוּר קֹדֶם שֶׁיִּבְדֹּק כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","כָּל דָּבָר שֶׁהוּא מִנְהָג אַף עַל פִּי שֶׁמִּנְהַג נְבִיאִים הוּא כְּגוֹן נְטִילַת עֲרָבָה בִּשְׁבִיעִי שֶׁל חַג וְאֵין צָרִיךְ לוֹמַר מִנְהַג חֲכָמִים כְּגוֹן קְרִיאַת הַלֵּל בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד שֶׁל פֶּסַח אֵין מְבָרְכִין עָלָיו. וְכֵן כָּל דָּבָר שֶׁיִּסְתַּפֵּק לְךָ אִם טָעוּן בְּרָכָה אִם לָאו עוֹשִׂין אוֹתוֹ בְּלֹא בְּרָכָה. וּלְעוֹלָם יִזָּהֵר אָדָם בִּבְרָכָה שֶׁאֵינָהּ צְרִיכָה וְיַרְבֶּה בַּבְּרָכוֹת הַצְּרִיכוֹת. וְכֵן דָּוִד אָמַר (תהילים קמה ב) ״בְּכָל יוֹם אֲבָרְכֶךָּ״:סְלִיק הִלְכוֹת בְּרָכוֹת"],"Mishneh Torah, Borrowing and Deposit 4":["הַמַּפְקִיד אֵצֶל חֲבֵרוֹ בְּחִנָּם וְנִגְנַב אוֹ אָבַד הֲרֵי זֶה נִשְׁבָּע וְנִפְטָר שֶׁנֶּאֱמַר (שמות כב ו) \"וְגֻנַּב מִבֵּית הָאִישׁ\" וְגוֹ' (שמות כב ז) \"וְנִקְרַב בַּעַל הַבַּיִת אֶל הָאֱלֹהִים אִם לֹא שָׁלַח יָדוֹ בִּמְלֶאכֶת רֵעֵהוּ\". וּמְגַלְגְּלִין עָלָיו בְּתוֹךְ הַשְּׁבוּעָה שֶׁלֹּא פָּשַׁע אֶלָּא שָׁמַר כְּדֶרֶךְ הַשּׁוֹמְרִין וְלֹא שָׁלַח בּוֹ יָד וְאַחַר נִגְנַב. שֶׁאִם נִגְנַב אַחַר שֶׁשָּׁלַח יָד בַּפִּקָּדוֹן חַיָּב בְּאַחֲרָיוּתוֹ:","הוֹאִיל וּפָטַר הַכָּתוּב אֶת שׁוֹמֵר חִנָּם מִן הַגְּנֵבָה קַל וָחֹמֶר מִן הָאֳנָסִין הַגְּדוֹלִים כְּגוֹן שְׁבוּרָה וּשְׁבוּיָה וּמֵתָה וְהוּא שֶׁלֹּא שָׁלַח יָד בַּפִּקָּדוֹן אֲבָל שָׁלַח יָד בַּפִּקָּדוֹן חַיָּב בְּאֳנָסָיו. כֵּיצַד דֶּרֶךְ הַשּׁוֹמְרִים. הַכּל לְפִי הַפִּקָּדוֹן. יֵשׁ פִּקָּדוֹן שֶׁדֶּרֶךְ שְׁמִירָתוֹ לְהַנִּיחוֹ בְּבֵית שַׁעַר כְּגוֹן הַקּוֹרוֹת וְהָאֲבָנִים. וְיֵשׁ פִּקָּדוֹן שֶׁדֶּרֶךְ שְׁמִירָתוֹ לְהַנִּיחוֹ בֶּחָצֵר כְּגוֹן חֲבִילוֹת פִּשְׁתָּן הַגְּדוֹלוֹת וְכַיּוֹצֵא בָּהֶן. וְיֵשׁ פִּקָּדוֹן שֶׁדֶּרֶךְ שְׁמִירָתוֹ לְהַנִּיחוֹ בַּבַּיִת כְּגוֹן שִׂמְלָה וְטַלִּית. וְיֵשׁ פִּקָּדוֹן שֶׁדֶּרֶךְ שְׁמִירָתוֹ לְהַנִּיחוֹ בְּתֵבָה אוֹ בְּמִגְדָּל וְנוֹעֵל עָלָיו כְּגוֹן בִּגְדֵי מֶשִׁי וּכְלֵי כֶּסֶף וּכְלֵי זָהָב וְכַיּוֹצֵא בָּהֶן:","הַשּׁוֹמֵר שֶׁהִנִּיחַ הַפִּקָּדוֹן בְּמָקוֹם שֶׁאֵינוֹ רָאוּי לוֹ וְנִגְנַב מִשָּׁם אוֹ אָבַד אֲפִלּוּ נֶאֱנַס שָׁם כְּגוֹן שֶׁנָּפְלָה דְּלֵקָה וְשָׂרַף כָּל הַבַּיִת הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב לְשַׁלֵּם. וְאַף עַל פִּי שֶׁהִנִּיחַ הַפִּקָּדוֹן עִם שֶׁלּוֹ אִם רָאוּי לִשְׁמִירָה פָּטוּר וְאִם אֵין הַמָּקוֹם רָאוּי לִשְׁמִירָה חַיָּב. בְּשֶׁלּוֹ הוּא רַשַּׁאי וְאֵינוֹ רַשַּׁאי בְּשֶׁל אֲחֵרִים:","הַכְּסָפִים וְהַדִּינָרִין אֵין לָהֶם שְׁמִירָה אֶלָּא בַּקַּרְקַע וְיִתֵּן עֲלֵיהֶם טֶפַח עָפָר. אוֹ יִטְמְנֵם בַּכֹּתֶל בַּטֶּפַח הַסָּמוּךְ לַקּוֹרָה. אֲבָל לֹא בְּאֶמְצַע הַכֹּתֶל שֶׁמָּא יַחְפְּרוּ הַגַּנָּבִים שָׁם וְיִגְנְבוּ. אֲפִלּוּ נָעַל עֲלֵיהֶם כָּרָאוּי בְּתֵבָה אוֹ הֶחְבִּיא אוֹתָם בְּמָקוֹם שֶׁאֵין אָדָם מַכִּירוֹ וְלֹא מַרְגִּישׁ בּוֹ הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב לְשַׁלֵּם. הוֹרוּ מִקְצָת הַמְּבִינִים שֶׁהוּא הַדִּין לְכָל דָּבָר שֶׁמַּשָּׂאוֹ קַל וְאֵין הַקַּרְקַע מְאַבֶּדֶת אוֹתוֹ בִּמְהֵרָה כְּגוֹן לְשׁוֹנוֹת שֶׁל כֶּסֶף וְאֵין צָרִיךְ לוֹמַר לְשׁוֹנוֹת שֶׁל זָהָב וַאֲבָנִים טוֹבוֹת שֶׁאֵין לָהֶם שְׁמִירָה אֶלָּא בַּקַּרְקַע. וְלָזֶה דַּעְתִּי נוֹטֶה:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ כְּסָפִים עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת אֵינוֹ חַיָּב לִטְרֹחַ וְלִקְבֹּר אוֹתָן עַד מוֹצָאֵי שַׁבָּת. וְאִם נִתְאַחֵר לְמוֹצָאֵי שַׁבָּת כְּדֵי לְקָבְרָן וְלֹא קְבָרָן וְנִגְנְבוּ אוֹ נֶאֶנְסוּ חַיָּב. וְאִם תַּלְמִיד חָכָם הוּא אֵינוֹ חַיָּב עַד שֶׁיִּשְׁהֵא אַחַר שֶׁיַּבְדִּיל כְּדֵי לְקָבְרָן:","הִפְקִיד אֵצֶל חֲבֵרוֹ כְּסָפִים בַּדֶּרֶךְ לְהוֹלִיכָם לְבֵיתוֹ אוֹ שֶׁשָּׁלַח עִמּוֹ מָעוֹת מִמָּקוֹם לְמָקוֹם צְרִיכִין שֶׁיִּהְיוּ צְרוּרִים וּמֻנָּחִים בְּיָדוֹ אוֹ קְשׁוּרִים כָּרָאוּי עַל בִּטְנוֹ מִכְּנֶגֶד פָּנָיו עַד שֶׁיַּגִּיעַ לְבֵיתוֹ וְיִקְבְּרֵם כָּרָאוּי. וְאִם לֹא קְשָׁרָן בַּדֶּרֶךְ הַזֹּאת אֲפִלּוּ נֶאֶנְסוּ חַיָּב לְשַׁלֵּם שֶׁהֲרֵי תְּחִלָּתוֹ בִּפְשִׁיעָה. מַעֲשֶׂה בְּאֶחָד שֶׁהִפְקִיד מָעוֹת אֵצֶל חֲבֵרוֹ וְהִנִּיחָם בִּמְחִצָּה שֶׁל קָנִים וְהָיוּ טְמוּנִים בָּעֳבִי הַמְּחִצָּה וְנִגְנְבוּ מִשָּׁם וְאָמְרוּ חֲכָמִים אַף עַל פִּי שֶׁזּוֹ שְׁמִירָה מְעֻלָּה לְעִנְיַן גְּנֵבָה אֵינָהּ שְׁמִירָה כָּרָאוּי לְעִנְיַן הָאֵשׁ וּמֵאַחַר שֶׁלֹּא טְמָנוֹ בְּקַרְקַע אוֹ בְּכֹתֶל בִּנְיָן פּוֹשֵׁעַ הוּא וְכָל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ בֵּין כֵּלִים בֵּין מָעוֹת וְאָמַר לוֹ תֵּן לִי פִּקְדוֹנִי וְאָמַר לוֹ הַשּׁוֹמֵר אֵינִי יוֹדֵעַ אָנָּה הִנַּחְתִּי פִּקָּדוֹן זֶה אוֹ בְּאֵי זֶה מָקוֹם קָבַרְתִּי הַכְּסָפִים הַמְתֵּן לִי עַד שֶׁאֲבַקֵּשׁ וְאֶמְצָא וְאַחְזִיר לְךָ הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב לְשַׁלֵּם מִיָּד:","כָּל הַמַּפְקִיד אֵצֶל בַּעַל הַבַּיִת בֵּין כֵּלִים בֵּין מָעוֹת עַל דַּעַת אִשְׁתּוֹ וּבָנָיו וּבְנֵי בֵּיתוֹ הַגְּדוֹלִים הוּא מַפְקִיד. אֲבָל אִם מְסָרָן לְבָנָיו וּבְנֵי בֵּיתוֹ הַקְּטַנִּים אוֹ לַעֲבָדָיו בֵּין גְּדוֹלִים בֵּין קְטַנִּים אוֹ לְאֶחָד מִקְּרוֹבָיו שֶׁאֵינָן שְׁרוּיִין עִמּוֹ בַּבַּיִת וְאֵין סוֹמְכִין עַל שֻׁלְחָנוֹ וְאֵין צָרִיךְ לוֹמַר אִם מְסָרָן לְאַחֵר הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב לְשַׁלֵּם אֶלָּא אִם כֵּן הֵבִיא הַשּׁוֹמֵר הַשֵּׁנִי רְאָיָה שֶׁלֹּא פָּשַׁע כְּמוֹ שֶׁבֵּאַרְנוּ. מַעֲשֶׂה בְּאֶחָד שֶׁהִפְקִיד מָעוֹת אֵצֶל חֲבֵרוֹ וּנְתָנָם הַשּׁוֹמֵר לְאִמּוֹ וְהֶחְבִּיאָה אוֹתָן וְלֹא טָמְנָה אוֹתָן וְנִגְנְבוּ וְאָמְרוּ חֲכָמִים אֵין הַשּׁוֹמֵר חַיָּב לְשַׁלֵּם מִפְּנֵי שֶׁנְּתָנָם לְאִמּוֹ שֶׁכָּל הַמַּפְקִיד עַל דַּעַת בָּנָיו וּבְנֵי בֵּיתוֹ הוּא מַפְקִיד וְאַף עַל פִּי שֶׁלֹּא אָמַר לָהּ פִּקָּדוֹן הֵם יֵשׁ לוֹ לִטְעֹן כָּל שֶׁכֵּן שֶׁהִיא נִזְהֶרֶת בָּהֶן אִם הָיְתָה סְבוּרָה שֶׁהֵן שֶׁלִּי. וְכֵן אֵין אִמּוֹ חַיֶּבֶת לְשַׁלֵּם שֶׁהֲרֵי לֹא אָמַר לָהּ שֶׁהֵן פִּקָּדוֹן. וְאָמְרוּ חֲכָמִים יִשָּׁבַע הַשּׁוֹמֵר שֶׁאוֹתָן הַמָּעוֹת עַצְמָן הֵן שֶׁנְּתָנָן לְאִמּוֹ וְתִשָּׁבַע הָאֵם שֶׁהֶחְבִּיאָה אוֹתָן וְנִגְנְבוּ וְיִפָּטְרוּ שְׁנֵיהֶם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִכָּאן אַתָּה לָמֵד שֶׁהַשּׁוֹמֵר שֶׁמָּסַר הַפִּקָּדוֹן לְאִשְׁתּוֹ וּבְנֵי בֵּיתוֹ וְהוֹדִיעָן שֶׁהוּא פִּקָּדוֹן וְלֹא שָׁמְרוּ כְּדֶרֶךְ הַשּׁוֹמְרִין שֶׁהֵן חַיָּבִין לְשַׁלֵּם לְבַעַל הַפִּקָּדוֹן וּבַעַל הַבַּיִת פָּטוּר שֶׁכָּל הַמַּפְקִיד עַל דַּעַת אִשְׁתּוֹ וּבָנָיו הוּא מַפְקִיד. מַעֲשֶׂה בְּאֶחָד שֶׁהִפְקִיד כְּשׁוּת אֵצֶל אֶחָד וְהָיָה לוֹ לַשּׁוֹמֵר כְּשׁוּת אַחֶרֶת וְאָמַר לְשַׁמָּשׁוֹ מִזֶּה הַכְּשׁוּת תַּשְׁלִיךְ לְתוֹךְ הַשֵּׁכָר וְהָלַךְ הַשַּׁמָּשׁ וְהִשְׁלִיךְ מִכְּשׁוּת שֶׁל פִּקָּדוֹן. אָמְרוּ חֲכָמִים שֶׁהַשַּׁמָּשׁ פָּטוּר שֶׁהֲרֵי לֹא אָמַר מִזֶּה הַשְׁלֵךְ וּמִזֶּה אַל תַּשְׁלֵךְ וְדִמָּה שֶׁהוּא מַרְאֶה מָקוֹם וְאֵינוֹ מַקְפִּיד עַל זֶה. וְכֵן בַּעַל הַבַּיִת פָּטוּר שֶׁהֲרֵי אָמַר לוֹ מִזֶּה הַשְׁלֵךְ וְאֵינוֹ מְשַׁלֵּם אֶלָּא דְּמֵי מַה שֶּׁנֶּהֱנָה בִּלְבַד. לְפִיכָךְ אִם נַעֲשָׂה הַשֵּׁכָר חֹמֶץ פָּטוּר מִלְּשַׁלֵּם. וּבֵין כָּךְ וּבֵין כָּךְ חַיָּב הַשּׁוֹמֵר שְׁבוּעָה שֶׁכָּךְ אֵרַע. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Creditor and Debtor 13":["מַלְוְה שֶׁבָּא לְהִפָּרַע בַּשְּׁטָר שֶׁבְּיָדוֹ שֶׁלֹּא בִּפְנֵי לוֶֹה אִם יְכוֹלִין בֵּית דִּין לִשְׁלֹחַ אֵלָיו וּלְהוֹדִיעוֹ עַד שֶׁיַּעֲמֹד עִמּוֹ בַּדִּין שׁוֹלְחִין וּמוֹדִיעִין לוֹ. וְאִם אִי אֶפְשָׁר לְהוֹדִיעוֹ בִּמְהֵרָה אוֹמְרִים לַמַּלְוֶה שֶׁיִּשָּׁבַע וְיִטּל מִנְּכָסָיו בֵּין מִן הַקַּרְקַע בֵּין מִן הַמִּטַּלְטְלִים. וְאֵין חוֹשְׁשִׁין לְשׁוֹבֵר. וְדִין זֶה תַּקָּנַת חֲכָמִים הוּא כְּדֵי שֶׁלֹּא יִהְיֶה כָּל אֶחָד וְאֶחָד נוֹטֵל מְעוֹתָיו שֶׁל חֲבֵרוֹ וְהוֹלֵךְ וְיוֹשֵׁב לוֹ בִּמְדִינָה אַחֶרֶת וְנִמְצָא נוֹעֵל דֶּלֶת בִּפְנֵי לוִֹין:","שָׁלֹשׁ רְאָיוֹת צָרִיךְ לְהָבִיא לְבֵית דִּין וְאַחַר כָּךְ יִפָּרַע שֶׁלֹּא בְּפָנָיו. רְאָיָה רִאשׁוֹנָה לְקַיֵּם הַשְּׁטָר שֶׁבְּיָדוֹ. רְאָיָה שְׁנִיָּה שֶׁבַּעַל חוֹבוֹ בִּמְדִינָה אַחֶרֶת וְאֵינוֹ מָצוּי בְּכָאן לַעֲמֹד עִמּוֹ בַּדִּין. רְאָיָה שְׁלִישִׁית שֶׁאֵלּוּ נְכָסִים שֶׁל פְּלוֹנִי הַלּוֶֹה הֵם:","מַלְוֶה שֶׁבָּא לְבֵית דִּין וְהֵבִיא מַשְׁכּוֹן בְּיָדוֹ וְאָמַר זֶה מַשְׁכּוֹנוֹ שֶׁל פְּלוֹנִי הוּא וַאֲנִי רוֹצֶה לְמָכְרוֹ וּלְהִפָּרַע חוֹבִי. אֵין בֵּית דִּין נִזְקָקִין לוֹמַר לוֹ הַמְתֵּן עַד שֶׁיָּבוֹא לוֶֹה וְיִטְעֹן שֶׁאִם רוֹצֶה לוֹמַר לָקוּחַ הוּא בְּיָדִי אוֹמֵר וּמַשִּׂיאִין לוֹ עֵצָה לְמָכְרוֹ בִּפְנֵי עֵדִים כְּדֵי שֶׁיֵּדַע לוֶֹה בְּכַמָּה נִמְכַּר. וְכֵן הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַמַּשְׁכּוֹן וּמֵת הַלּוֶֹה וְהַמַּלְוֶה בֵּין שֶׁמֵּת הַלּוֶֹה תְּחִלָּה בֵּין שֶׁמֵּת מַלְוֶה תְּחִלָּה הוֹאִיל וְהוּא נִפְרָע מִמַּה שֶּׁתַּחַת יָדוֹ וְאִלּוּ רָצָה לוֹמַר לָקוּחַ הוּא בְּיָדִי אוֹמֵר הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כְּדֶרֶךְ כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין. וּמִפְּנֵי מָה אֵינוֹ נִשְׁבָּע הֶסֵּת לְפִי שֶׁאֵינוֹ נִשְׁבָּע עַל עַצְמוֹ שֶׁל מַשְׁכּוֹן אֶלָּא עַל הַמָּמוֹן שֶׁלּוֹקֵחַ. שֶׁאִלּוּ אָמַר עַל עַצְמוֹ שֶׁל חֵפֶץ זֶה אַתָּה מְכַרְתּוֹ לִי אַתָּה נְתַתּוֹ לִי הָיָה נִשְׁבָּע הֶסֵּת וְנִפְטָר. אֲבָל אִם הָיוּ שָׁם עֵדִים שֶׁחֵפֶץ זֶה מַשְׁכּוֹן בְּיָדוֹ וְלֹא יָדְעוּ עַל כַּמָּה וְכַמָּה אֵינוֹ יָכוֹל לִטּל אֶלָּא בִּשְׁבוּעָה וְהוֹאִיל וְאֵין שָׁם עֵדִים וְיָכוֹל לוֹמַר שֶׁלִּי הוּא נֶאֱמָן לוֹמַר יֵשׁ לִי עָלָיו כָּךְ וְכָךְ בַּשְּׁבוּעָה עַצְמָהּ שֶׁהָיָה נִשְׁבָּע אִם הָיוּ שָׁם עֵדִים שֶׁהוּא מַשְׁכּוֹן. שֶׁאֵין אוֹמְרִין מִגּוֹ לְפָטְרוֹ מִשְּׁבוּעָה אֶלָּא לְפָטְרוֹ מִמָּמוֹן שֶׁלֹּא יַחְזִיר הַמַּשְׁכּוֹן עַד שֶׁיִּטּל מַה שֶּׁטָּעַן:","הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַמַּשְׁכּוֹן וְאָבַד אוֹ נִגְנַב בְּלֹא אֹנֶס שֶׁהֲרֵי הַמַּלְוֶה חַיָּב בִּדְמֵי הַמַּשְׁכּוֹן כְּמוֹ שֶׁבֵּאַרְנוּ. וְאָמַר הַמַּלְוֶה סֶלַע הִלְוֵיתִיךָ עָלָיו וּשְׁנֵי דִּינָרִין הָיָה שָׁוֶה. וְלוֶֹה אוֹמֵר סֶלַע הִלְוֵיתַנִי עָלָיו וְסֶלַע הָיָה שָׁוֶה. הֲרֵי הַמַּלְוֶה נִשְׁבָּע תְּחִלָּה שְׁבוּעַת הַשּׁוֹמְרִין שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְהַלּוֶֹה נִשְׁבָּע הֶסֵּת שֶׁהָיָה שָׁוֶה כְּנֶגֶד הַחוֹב וְנִפְטָר. אָמַר הַמַּלְוֶה סֶלַע הִלְוֵיתִיךָ עָלָיו וְשֶׁקֶל הָיָה שָׁוֶה וְהַלּוֶֹה אוֹמֵר סֶלַע הִלְוֵיתַנִי עָלָיו וּשְׁלֹשָׁה דִּינָרִין הָיָה שָׁוֶה יִשָּׁבַע הַמַּלְוֶה תְּחִלָּה שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְאַחַר כָּךְ יִשָּׁבַע הַלּוֶֹה כַּמָּה הָיָה שָׁוֶה שֶׁהֲרֵי הוֹדָה בְּמִקְצָת וִישַׁלֵּם הַדִּינָר. אָמַר הַלּוֶֹה סֶלַע הִלְוֵיתַנִי עָלָיו וּשְׁתַּיִם הָיָה שָׁוֶה וְהַמַּלְוֶה אוֹמֵר סֶלַע הִלְוֵיתִיךָ עָלָיו וְסֶלַע הָיָה שָׁוֶה יִשָּׁבַע הַמַּלְוֶה שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְכוֹלֵל בִּשְׁבוּעָתוֹ שֶׁהָיָה הַמַּשְׁכּוֹן כְּנֶגֶד הַחוֹב. אָמַר הַלּוֶֹה סֶלַע הִלְוֵיתַנִי עָלָיו וּשְׁתַּיִם הָיָה שָׁוֶה וְהַמַּלְוֶה אוֹמֵר סֶלַע הִלְוֵיתִיךָ עָלָיו וַחֲמִשָּׁה דִּינָרִין הָיָה שָׁוֶה יִשָּׁבַע הַמַּלְוֶה שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְיִכְלל שֶׁלֹּא הָיָה שָׁוֶה יֶתֶר עַל חֲמִשָּׁה דִּינָרִים וִישַׁלֵּם הַדִּינָר. סֶלַע הִלְוֵיתִיךָ עָלָיו וּשְׁנֵי דִּינָרִין הָיָה שָׁוֶה וְהַלּוֶֹה אוֹמֵר אֵינִי יוֹדֵעַ דָּמָיו יִשָּׁבַע מַלְוֶה שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְכוֹלֵל בִּשְׁבוּעָתוֹ שֶׁשְּׁנֵי דִּינָרִין הָיָה שָׁוֶה וִישַׁלֵּם הַלּוֶֹה שְׁאָר הַחוֹב שֶׁהֲרֵי הוּא יוֹדֵעַ בְּוַדַּאי שֶׁהוּא חַיָּב לוֹ וְאֵינוֹ יוֹדֵעַ אִם פְּרָעוֹ אִם לֹא פְּרָעוֹ. סֶלַע הִלְוֵיתַנִי עָלָיו וּשְׁתַּיִם הָיָה שָׁוֶה וְהַמַּלְוֶה אוֹמֵר אֵינִי יוֹדֵעַ דָּמָיו יִשָּׁבַע הַמַּלְוֶה שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְיִכְלל שֶׁאֵינוֹ יוֹדֵעַ שֶׁדָּמָיו יֶתֶר עַל הַחוֹב אֲפִלּוּ פְּרוּטָה אַחַת וְיִפָּטֵר שֶׁהֲרֵי לֹא חִיֵּב עַצְמוֹ בִּכְלוּם. אֲבָל אִם אָמַר הַמַּלְוֶה אֲנִי יוֹדֵעַ שֶׁהָיָה שָׁוֶה יֶתֶר עַל הַחוֹב אֲבָל אֵינִי יוֹדֵעַ כַּמָּה הֲרֵי זֶה מְשַׁלֵּם כָּל מַה שֶּׁטָּעַן הַלּוֶֹה בְּלֹא שְׁבוּעָה כְּמִי שֶׁאָמַר חֲמִשִּׁים יֵשׁ לְךָ בְּיָדִי וַחֲמִשִּׁים אֵינִי יוֹדֵעַ שֶׁהוּא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לְהִשָּׁבַע כְּמוֹ שֶׁיִּתְבָּאֵר. וְיֵשׁ לוֹ לְהַחֲרִים עַל מִי שֶׁטּוֹעֵן שֶׁקֶר:","הַמַּלְוֶה אֶת חֲבֵרוֹ וְקָבַע לוֹ זְמַן לְפָרְעוֹ אַף עַל פִּי שֶׁלֹּא קָנוּ מִיָּדוֹ אֵינוֹ יָכוֹל לְתָבְעוֹ עַד סוֹף הַזְּמַן בֵּין בְּמִלְוֶה עַל פֶּה בֵּין בְּמִלְוֶה בִּשְׁטָר בֵּין שֶׁהִלְוָהוּ עַל הַמַּשְׁכּוֹן בֵּין שֶׁמֵּת לוֶֹה בֵּין שֶׁמֵּת מַלְוֶה. וּסְתָם מִלְוֶה שְׁלֹשִׁים יוֹם בֵּין בִּשְׁטָר בֵּין עַל פֶּה בֵּין עַל הַמַּשְׁכּוֹן. וְאִם הִתְנָה שֶׁיִּתְבַּע בְּכָל זְמַן שֶׁיִּרְצֶה יֵשׁ לוֹ לְתָבְעוֹ בְּיוֹמוֹ שֶׁתְּנַאי מָמוֹן הוּא:","טָעַן הַמַּלְוֶה וְאָמַר הַיּוֹם סוֹף הַזְּמַן שֶׁקָּבַעְתִּי וְהַלּוֶֹה אוֹמֵר עַד עֲשָׂרָה יָמִים קָבַעְתָּ הַלּוֶֹה נִשְׁבָּע הֶסֵּת. וְאִם הָיָה שָׁם עֵד אֶחָד שֶׁהַיּוֹם סוֹף זְמַנּוֹ הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה כִּשְׁאָר הַטְּעָנוֹת. זֶה אוֹמֵר חֲמִשָּׁה יָמִים נִשְׁאָר מִן הַזְּמַן וְזֶה אוֹמֵר עֲשָׂרָה אוֹמְרִים לַמַּלְוֶה הַמְתֵּן עוֹד עַד סוֹף הַחֲמִשָּׁה וְיִשָּׁבַע הֶסֵּת שֶׁנִּשְׁאַר עוֹד חֲמִשָּׁה יָמִים:","הָיְתָה הַמִּלְוֶה בִּשְׁטָר וְטָעַן הַלּוֶֹה שֶׁזְּמַן קָבַעְתָּ לִי. יֵרָאֶה לִי שֶׁיִּשָּׁבַע בַּעַל חוֹב הֶסֵּת שֶׁלֹּא קָבַע לוֹ זְמַן וְיִטּל הַמַּלְוֶה מִיָּד:","הַמִּלְוֶה נִתְּנָה לִתָּבַע בְּכָל מָקוֹם. כֵּיצַד. הַמַּלְוֶה אֶת חֲבֵרוֹ בַּיִּשּׁוּב וּתְבָעוֹ בַּמִּדְבָּר אֵינוֹ יָכוֹל לִדְחוֹתוֹ אֶלָּא חַיָּב לִפְרֹעַ לוֹ בְּכָל מָקוֹם שֶׁיִּתְבָּעֶנּוּ. בָּא הַלּוֶֹה לְפָרְעוֹ בַּמִּדְבָּר הָרְשׁוּת בְּיַד הַמַּלְוֶה אִם רָצָה מְקַבֵּל וְאִם רָצָה אוֹמֵר לוֹ אֵינִי נִפְרָע אֶלָּא בַּיִּשּׁוּב כְּדֶרֶךְ שֶׁנָּתַתִּי לְךָ בְּיִשּׁוּב. וַהֲרֵי הֵן בִּרְשׁוּתוֹ עַד שֶׁיִּפְרָעֶנּוּ בַּיִּשּׁוּב:"],"Mishneh Torah, Creditor and Debtor 24":["כְּבָר בֵּאַרְנוּ שֶׁשְּׁטַר חוֹב שֶׁיֵּשׁ בּוֹ קִנְיָן כּוֹתְבִין אוֹתוֹ לַלּוֶֹה אַף עַל פִּי שֶׁאֵין הַמַּלְוֶה עִמּוֹ. וְכֵן כּוֹתְבִין שְׁטָר לַמּוֹכֵר אַף עַל פִּי שֶׁאֵין הַלּוֹקֵחַ עִמּוֹ. וְכֵן כּוֹתְבִין שׁוֹבֵר לַמַּלְוֶה אַף עַל פִּי שֶׁאֵין הַלּוֶֹה עִמּוֹ וְשׁוֹבֵר לְאִשָּׁה אַף עַל פִּי שֶׁאֵין בַּעְלָהּ עִמָּהּ וְגֵט לְאִישׁ אַף עַל פִּי שֶׁאֵין אִשְׁתּוֹ עִמּוֹ. אֲבָל אֵין כּוֹתְבִין שִׁטְרֵי אֵרוּסִין וְנִשּׂוּאִין וְשִׁטְרֵי אֲרִיסוּת וְקַבְּלָנוּת וּשְׁטַר בְּרֵרַת הַדַּיָּנִין אוֹ שְׁטַר טַעֲנַת בַּעֲלֵי דִּינִין וְכָל מַעֲשֵׂה בֵּית דִּין אֶלָּא מִדַּעַת שְׁנֵיהֶם. וְכָל הַשְּׁטָרוֹת הָאֵלּוּ צְרִיכִין לְהִזָּהֵר בְּתִקּוּנָן כִּשְׁאָר הַשְּׁטָרוֹת:","וּמִי נוֹתֵן שְׂכַר הַסּוֹפֵר. בְּשִׁטְרֵי הַלְוָאָה הַלּוֶֹה נוֹתֵן שָׂכָר. וּבְשִׁטְרֵי מִקָּח וּמִמְכָּר הַלּוֹקֵחַ נוֹתֵן שָׂכָר. וְהָאִשָּׁה נוֹתֶנֶת שְׂכַר הַגֵּט. וְהֶחָתָן נוֹתֵן שְׂכַר שְׁטַר הָאֵרוּסִין אוֹ הַנִּשּׂוּאִין. וְהַמְקַבֵּל וְכֵן הָאָרִיס אוֹ הַשָּׂכִיר נוֹתֵן שְׂכַר הַשְּׁטָר. אֲבָל שְׁטַר בְּרֵרַת הַדַּיָּנִין אוֹ טַעֲנוֹת בַּעֲלֵי דִּינִין שְׁנֵיהֶם נוֹתְנִין שָׂכָר:","אֶחָד הַשְּׁטָרוֹת הַנִּכְתָּבִין לְאֶחָד שֶׁלֹּא בִּפְנֵי חֲבֵרוֹ וְאֶחָד הַשְּׁטָרוֹת שֶׁאֵין כּוֹתְבִין אוֹתָן אֶלָּא מִדַּעַת שְׁנֵיהֶם וּשְׁנֵיהֶן עוֹמְדִין כְּגוֹן שְׁטָר שֶׁכּוֹתְבִין לַמַּלְוֶה אוֹ לַלּוֹקֵחַ כֻּלָּן צְרִיכִין שֶׁיִּהְיוּ הָעֵדִים מַכִּירִין הַשֵּׁמוֹת שׁבַּשְּׁטָר שֶׁזֶּה הוּא פְּלוֹנִי בֶּן פְּלוֹנִי וְזֶהוּ פְּלוֹנִי בֶּן פְּלוֹנִי שֶׁמָּא יָבוֹאוּ שְׁנַיִם וְיַעֲשׂוּ קְנוּנְיָא וִישַׁנּוּ שְׁמוֹתֵיהֶן בְּשֵׁמוֹת אֲחֵרִים וְיוֹדוּ זֶה לָזֶה:","כָּל מִי שֶׁהֻחְזַק שְׁמוֹ בָּעִיר שְׁלֹשִׁים יוֹם אֵין חוֹשְׁשִׁין לוֹ שֶׁמָּא שֵׁם אַחֵר יֵשׁ לוֹ וְהוּא שִׁנָּהוּ כְּדֵי לְרַמּוֹת וְלַעֲשׂוֹת קְנוּנְיָא שֶׁאִם אַתָּה אוֹמֵר כֵּן אֵין לַדָּבָר סוֹף. לְפִיכָךְ מִי שֶׁלֹּא הֻחְזַק שְׁמוֹ בָּעִיר שְׁלֹשִׁים יוֹם וּבָא וְאָמַר כִּתְבוּ עָלַי שְׁטָר שֶׁאֲנִי חַיָּב לִפְלוֹנִי אוֹ לָזֶה כָּךְ וְכָךְ דִּינָרִין. אֵין כּוֹתְבִין לוֹ עַד שֶׁיָּבִיא רְאָיָה שֶׁזֶּה שְׁמוֹ אוֹ יֻחְזַק:","כָּל שְׁטָר שֶׁיָּצָא לְפָנֵינוּ וְיִטְעֹן הַלּוֶֹה וְיֹאמַר אֵינִי חַיָּב כְּלוּם שֶׁמָּא רַמַּאי אַחֵר הֶעֱלָה שְׁמוֹ כִּשְׁמִי וְהוֹדָה לָזֶה אוֹ שֶׁאָמַר לֹא לָזֶה אֲנִי חַיָּב כְּלוּם אֶלָּא לְאַחֵר וְזֶה רַמַּאי הוּא וְהֶעֱלָה שְׁמוֹ כְּשֵׁם בַּעַל חוֹבִי. מֵאַחַר שֶׁלֹּא הֻחְזַק שָׁם שְׁנַיִם שֶׁשְּׁמוֹתֵיהֶן שָׁוִין אֵין חוֹשְׁשִׁין לִדְבָרָיו שֶׁחֲזָקָה הוּא שֶׁאֵין הָעֵדִים חוֹתְמִין עַל הַשְּׁטָר אֶלָּא אִם כֵּן מַכִּירִין אֵלּוּ הַנִּזְכָּרִים בּוֹ. וְכֵן חֲזָקָה שֶׁאֵין חוֹתְמִין עַל הַשְּׁטָר אֶלָּא אִם כֵּן נוֹדַע לָהֶם בְּוַדַּאי שָׁאֲלוּ שֶׁהֵעִידוּ עַל עַצְמָן גְּדוֹלִים וּבְנֵי דַּעַת. וְאֵין הָעֵדִים חוֹתְמִין עַל הַשְּׁטָר אֶלָּא אִם כֵּן יוֹדְעִים לִקְרוֹת וְלַחְתֹּם:","עֵדִים שֶׁאֵין יוֹדְעִין לַחְתֹּם וְקָרְעוּ לָהֶן נְיָר חָלָק וְחָתְמוּ עַל הָרָשׁוּם מַכִּין אוֹתָן מַכַּת מַרְדּוּת וְהַשְּׁטָר פָּסוּל:","רֹאשׁ בֵּית דִּין שֶׁהָיָה יוֹדֵעַ עִנְיַן הַשְּׁטָר וְקָרָא הַשְּׁטָר שֶׁלְּפָנָיו הַסּוֹפֵר שֶׁלּוֹ הוֹאִיל וְהוּא מַאֲמִין אוֹתוֹ וְאֵימָתוֹ עָלָיו הֲרֵי זֶה חוֹתֵם עַל הַשְּׁטָר אַף עַל פִּי שֶׁלֹּא קְרָאָהוּ הוּא בְּעַצְמוֹ. וְאֵין שְׁאָר הָעָם רַשָּׁאִין לַעֲשׂוֹת כֵּן עַד שֶׁיִּקְרָא הָעֵד הַשְּׁטָר מִלָּה מִלָּה:","שְׁנַיִם שֶׁהָיוּ בָּעִיר שֵׁם כָּל אֶחָד מֵהֶן יוֹסֵף בֶּן שִׁמְעוֹן אֵינָן יְכוֹלִין לְהוֹצִיא שְׁטַר חוֹב זֶה עַל זֶה וְלֹא אַחֵר יָכוֹל לְהוֹצִיא עֲלֵיהֶן שְׁטַר חוֹב אֶלָּא אִם כֵּן בָּאוּ עֵדֵי הַשְּׁטָר בְּעַצְמָן וְאָמְרוּ זֶהוּ הַשְּׁטָר שֶׁהֵעַדְנוּ עָלָיו וְזֶהוּ שֶׁהֵעַדְנוּ לוֹ בְּהַלְוָאָה. וְכֵן אֵין מְגָרְשִׁין נְשׁוֹתֵיהֶן אֶלָּא זֶה בִּפְנֵי זֶה. וְכֵן אִם נִמְצָא לְאֶחָד בֵּין שִׁטְרוֹתָיו שׁוֹבֵר שֶׁשְּׁטָרוֹ שֶׁל יוֹסֵף בֶּן שִׁמְעוֹן פָּרוּעַ שִׁטְרוֹת שְׁנֵיהֶן שֶׁעָלָיו פְּרוּעִין. וְכֵיצַד יַעֲשׂוּ אֵלּוּ שֶׁשְּׁמוֹתֵיהֶן שָׁוִין וּשְׁמוֹת אֲבִיהֶן שָׁוִין. יְשַׁלְּשׁוּ. הָיוּ שְׁמוֹת אֲבוֹת אֲבוֹתֵיהֶן שָׁוִין יִכְתְּבוּ סִימָנֵיהֶן. הָיוּ דּוֹמִין זֶה לָזֶה בְּצוּרָתָן יִכְתְּבוּ יִחוּסָן. הָיוּ שְׁנֵיהֶם לְוִיִּם שְׁנֵיהֶם כֹּהֲנִים יִכְתְּבוּ דּוֹרוֹת:","הוֹצִיא עָלָיו שְׁטָר שֶׁכָּתוּב בּוֹ אֲנִי פְּלוֹנִי בֶּן פְּלוֹנִי לָוִיתִי מִמְּךָ מָנֶה אַף עַל פִּי שֶׁאֵין בּוֹ שֵׁם הַמַּלְוֶה כָּל מִי שֶׁיָּצָא שְׁטָר זֶה מִתַּחַת יָדוֹ גּוֹבֶה בּוֹ וְאֵינוֹ יָכוֹל לִדְחוֹתוֹ וְלוֹמַר שֶׁל אַחֵר הוּא וְנָפַל. וְכֵן שְׁנֵי יוֹסֵף בְּנֵי שִׁמְעוֹן הַדָּרִין בְּעִיר אַחַת שֶׁהוֹצִיא אֶחָד מֵהֶן שְׁטַר חוֹב עַל אֶחָד מִבְּנֵי הָעִיר אֵינוֹ יָכוֹל לִדְחוֹתוֹ וְלוֹמַר לוֹ לִפְלוֹנִי שֶׁהוּא כְּשִׁמְךָ אֲנִי חַיָּב וּמִמֶּנּוּ נָפַל הַשְּׁטָר אֶלָּא הֲרֵי זֶה שֶׁיָּצָא מִתַּחַת יָדוֹ גּוֹבֶה וְאֵין חוֹשְׁשִׁין לִנְפִילָה:","שְׁנַיִם שֶׁהוֹצִיאוּ כָּל אֶחָד מִשְּׁנֵיהֶם שְׁטַר חוֹב עַל חֲבֵרוֹ אֵין הָאַחֲרוֹן יָכוֹל לוֹמַר לָרִאשׁוֹן אִלּוּ הָיִיתִי חַיָּב לְךָ הֵיאַךְ אַתָּה לוֶֹה מִמֶּנִּי אֶלָּא זֶה גּוֹבֶה חוֹבוֹ וְזֶה גּוֹבֶה חוֹבוֹ. הָיָה זֶה בְּמֵאָה וְזֶה בְּמֵאָה וְיֵשׁ לָזֶה עִידִית וְלָזֶה עִידִית אוֹ לָזֶה בֵּינוֹנִית וְלָזֶה בֵּינוֹנִית לָזֶה זִבּוּרִית וְלָזֶה זִבּוּרִית אֵין נִזְקָקִין לָהֶן אֶלָּא כָּל אֶחָד וְאֶחָד עוֹמֵד בְּשֶׁלּוֹ. הָיָה לָזֶה עִידִית וּבֵינוֹנִית וְלָזֶה זִבּוּרִית זֶה גּוֹבֶה מִן הַבֵּינוֹנִית וְזֶה גּוֹבֶה מִן הַזִּבּוּרִית:","הוֹצִיא שְׁטַר חוֹב עַל חֲבֵרוֹ וְהַלָּה מוֹצִיא שְׁטָר שֶׁמָּכַר לוֹ הַשָּׂדֶה אִם הָיוּ בְּמָקוֹם שֶׁנּוֹתֵן הַלּוֹקֵחַ הַמָּעוֹת וְאַחַר כָּךְ כּוֹתֵב לוֹ הַמּוֹכֵר אֶת הַשְּׁטָר הֲרֵי שְׁטַר חוֹבוֹ שֶׁל זֶה בָּטֵל שֶׁהֲרֵי אוֹמֵר לוֹ אִלּוּ הָיִיתִי חַיָּב לְךָ הָיָה לְךָ לִפְרֹעַ חוֹבְךָ. אֲבָל בְּמָקוֹם שֶׁכּוֹתְבִין וְאַחַר כָּךְ נוֹתְנִין הֲרֵי שְׁטַר הַחוֹב קַיָּם שֶׁהֲרֵי זֶה אוֹמֵר מָכַרְתִּי לְךָ אֶת הַשָּׂדֶה כְּדֵי שֶׁיִּהְיֶה לְךָ נְכָסִים יְדוּעִים שֶׁאֶגְבֶּה מֵהֶן חוֹב שֶׁלִּי:"],"Mishneh Torah, Daily Offerings and Additional Offerings 10":["בְּיוֹם הַכִּפּוּרִים מַקְרִיבִין מוּסָף כְּמוּסַף רֹאשׁ הַשָּׁנָה פַּר וְאַיִל. וְאַיִל זֶה נִקְרָא אֵיל הָעָם. וְשִׁבְעָה כְּבָשִׂים כֻּלָּן עוֹלוֹת. וּשְׂעִיר חַטָּאת וְהוּא נֶאֱכָל לָעֶרֶב:","וְעוֹד מַקְרִיבִין הַצִּבּוּר שְׂעִיר חַטָּאת וְהוּא נִשְׂרָף שֶׁבֶּן זוּגוֹ שָׂעִיר הַמִּשְׁתַּלֵּחַ:","בַּיּוֹם הָרִאשׁוֹן שֶׁל חַג הַסֻּכּוֹת מַקְרִיבִין מוּסַף הַיּוֹם שְׁלֹשָׁה עָשָׂר פָּרִים וּשְׁנֵי אֵילִים וְאַרְבָּעָה עָשָׂר כְּבָשִׂים כֻּלָּן עוֹלוֹת וּשְׂעִיר חַטָּאת נֶאֱכֶלֶת. וְכֵן כָּל יוֹם וְיוֹם מִשִּׁבְעַת יְמֵי הֶחָג מַקְרִיבִין שְׁנֵי אֵילִים וְאַרְבָּעָה עָשָׂר כְּבָשִׂים וּשְׂעִיר חַטָּאת:","אֲבָל הַפָּרִים פּוֹחֲתִין אֶחָד אֶחָד בְּכָל יוֹם. בַּשֵּׁנִי מַקְרִיבִין שְׁנֵים עָשָׂר. בַּשְּׁלִישִׁי אַחַד עָשָׂר. עַד שֶׁיִּמָּצֵא קָרְבַּן יוֹם שְׁבִיעִי פָּרִים שִׁבְעָה אֵילִים שְׁנַיִם כְּבָשִׂים אַרְבָּעָה עָשָׂר הַכּל עוֹלוֹת וּשְׂעִיר חַטָּאת:","בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת מַקְרִיבִין מוּסַף הַיּוֹם פַּר וְאַיִל וְשִׁבְעָה כְּבָשִׂים כֻּלָּן עוֹלוֹת וּשְׂעִיר חַטָּאת. וְזֶה מוּסָף בִּפְנֵי עַצְמוֹ:","כָּל שִׁבְעַת יְמֵי הֶחָג מְנַסְּכִין אֶת הַמַּיִם עַל גַּבֵּי הַמִּזְבֵּחַ. וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי. וְעִם נִסּוּךְ הַיַּיִן שֶׁל תָּמִיד שֶׁל שַׁחַר הָיָה מְנַסֵּךְ הַמַּיִם לְבַדּוֹ:","וְאִם עֵרָה הַמַּיִם לְתוֹךְ הַיַּיִן אוֹ הַיַּיִן לְתוֹךְ הַמַּיִם וְנִסֵּךְ שְׁנֵיהֶם מִכְּלִי אֶחָד יָצָא. וְאִם הִקְדִּים נִסּוּךְ הַמַּיִם לָזֶבַח אֲפִלּוּ נִסְּכָן בַּלַּיְלָה יָצָא. וּבְקֶרֶן דְּרוֹמִית מַעֲרָבִית הָיָה מְנַסֵּךְ לְמַעְלָה מֵחֲצִי הַמִּזְבֵּחַ וְהַכּל יוֹרֵד לַשִּׁיתִין כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד הָיוּ עוֹשִׂין. צְלוֹחִית שֶׁל זָהָב מַחְזֶקֶת שְׁלֹשָׁה לוֹגִין הָיָה מְמַלֵּא אוֹתָהּ מִן הַשִּׁילוֹחַ. הִגִּיעוּ לְשַׁעַר הַמַּיִם תָּקְעוּ וְהֵרִיעוּ וְתָקְעוּ. עָלָה לַכֶּבֶשׁ וּפָנָה לִשְׂמֹאלוֹ וְנוֹתֵן הַמַּיִם מִן הַצְּלוֹחִית לְתוֹךְ הַסֵּפֶל שֶׁהָיָה שָׁם. וּשְׁנֵי סְפָלִים שֶׁל כֶּסֶף הָיוּ שָׁם. מַעֲרָבִי הָיָה בּוֹ הַמַּיִם. וּמִזְרָחִי הָיָה בּוֹ הַיַּיִן שֶׁל נֶסֶךְ. וְהָיוּ מְנֻקָּבִין כְּמִין שְׁנֵי חֳטָמִין דַּקִּין. וְשֶׁל מַיִם הָיָה נֶקֶב שֶׁלּוֹ דַּק מִשֶּׁל יַיִן כְּדֵי שֶׁיִּכְלֶה הַמַּיִם עִם הַיַּיִן כְּאֶחָד:","זֶה שֶׁמְּנַסֵּךְ הַמַּיִם הָיוּ אוֹמְרִין לוֹ הַגְבֵּהַּ יָדְךָ. שֶׁפַּעַם אַחַת נִסֵּךְ אֶחָד עַל רַגְלָיו וּרְגָמוּהוּ כָּל הָעָם בְּאֶתְרוֹגֵיהֶן שֶׁאָמְרוּ צְדוֹקִי הוּא שֶׁהֵן אוֹמְרִין אֵין מְנַסְּכִין מַיִם:","כְּמַעֲשֵׂהוּ בְּחל כָּךְ מַעֲשֵׂהוּ בְּשַׁבָּת. אֶלָּא שֶׁהָיָה מְמַלֵּא מֵעֶרֶב שַׁבָּת חָבִית שֶׁל זָהָב וְאֵינָהּ מִכְּלֵי הַשָּׁרֵת וּמַנִּיחָהּ בַּלִּשְׁכָּה וּלְמָחָר מְמַלֵּא מִמֶּנָּה:","אִם נִשְׁפְּכָה אוֹ נִתְגַּלְּתָה מְמַלֵּא מִן הַכִּיּוֹר וּמְנַסֵּךְ:","בְּכָל יוֹם וְיוֹם מִימֵי הֶחָג הָיוּ אוֹמְרִים שִׁירָה בִּפְנֵי עַצְמָהּ עַל מוּסַף הַיּוֹם. בָּרִאשׁוֹן מִימֵי חֻלּוֹ שֶׁל מוֹעֵד הָיוּ אוֹמְרִין (תהילים כט א) \"הָבוּ לַה' בְּנֵי אֵלִים\". בַּשֵּׁנִי (תהילים נ טז) \"וְלָרָשָׁע אָמַר אֱלֹהִים\" וְגוֹ'. בַּשְּׁלִישִׁי (תהילים צד טז) \"מִי יָקוּם לִי עִם מְרֵעִים\". בָּרְבִיעִי (תהילים צד ח) \"בִּינוּ בֹּעֲרִים בָּעָם\" וְגוֹ'. בַּחֲמִישִׁי (תהילים פא ז) \"הֲסִירוֹתִי מִסֵּבֶל שִׁכְמוֹ\". בַּשִּׁשִּׁי (תהילים פב ה) \"יִמּוֹטוּ כָּל מוֹסְדֵי אָרֶץ\" וְגוֹ'. וְאִם חָל שַׁבָּת לִהְיוֹת בְּאֶחָד מֵהֶן יִמּוֹטוּ יִדָּחֶה:","כְּבָר בֵּאַרְנוּ שֶׁכָּל מִשְׁמְרוֹת כְּהֻנָּה עֶשְׂרִים וְאַרְבָּעָה. וְכֻלָּן עוֹבְדִין בְּשָׁוֶה בָּרְגָלִים. וּבְחַג הַסֻּכּוֹת הָיָה כָּל מִשְׁמָר מַקְרִיב פַּר אֶחָד אוֹ אַיִל אֶחָד אוֹ שְׂעִיר הַחַטָּאת. אֲבָל הַכְּבָשִׂים יֵשׁ מִשְׁמָר שֶׁמַּקְרִיב מֵהֶן שְׁנֵי כְּבָשִׂים. וְיֵשׁ מִשְׁמָר שֶׁמַּקְרִיב כֶּבֶשׂ אֶחָד. כֵּיצַד. בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג הָיוּ שָׁם שְׁלֹשָׁה עָשָׂר פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב בְּהֵמָה אַחַת מֵהֶם. נִשְׁאֲרוּ שָׁם אַרְבָּעָה עָשָׂר כְּבָשִׂים לִשְׁמוֹנֶה מִשְׁמָרוֹת. שִׁשָּׁה מִשְׁמָרוֹת מַקְרִיבִין שְׁנַיִם שְׁנַיִם וּשְׁנֵי מִשְׁמָרוֹת מַקְרִיבִין אֶחָד אֶחָד. בַּשֵּׁנִי הָיוּ שָׁם שְׁנֵים עָשָׂר פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב אֶחָד. נִשְׁאֲרוּ שָׁם אַרְבָּעָה עָשָׂר כְּבָשִׂים לְתִשְׁעָה מִשְׁמָרוֹת. חֲמִשָּׁה מַקְרִיבִין שְׁנַיִם שְׁנַיִם. וְאַרְבָּעָה מַקְרִיבִין אֶחָד אֶחָד. בַּשְּׁלִישִׁי הָיוּ שָׁם אַחַד עָשָׂר פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב אֶחָד. נִשְׁאֲרוּ אַרְבָּעָה עָשָׂר כְּבָשִׂים לַעֲשָׂרָה מִשְׁמָרוֹת. אַרְבָּעָה מַקְרִיבִין שְׁנַיִם שְׁנַיִם וְשִׁשָּׁה מַקְרִיבִין אֶחָד אֶחָד. בָּרְבִיעִי הָיוּ שָׁם עֲשָׂרָה פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב אֶחָד. נִשְׁאֲרוּ שָׁם אַרְבָּעָה עָשָׂר כְּבָשִׂים לְאַחַד עָשָׂר מִשְׁמָר. שְׁלֹשָׁה מַקְרִיבִין שְׁנַיִם שְׁנַיִם וּשְׁמוֹנָה מַקְרִיבִין אֶחָד אֶחָד. בַּחֲמִישִׁי הָיוּ שָׁם תִּשְׁעָה פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב אֶחָד. נִשְׁאֲרוּ שָׁם אַרְבָּעָה עָשָׂר כְּבָשִׂים לִשְׁנֵים עָשָׂר מִשְׁמָר. שְׁנֵי מִשְׁמָרוֹת מַקְרִיבִין שְׁנַיִם שְׁנַיִם וַעֲשָׂרָה מַקְרִיבִין אֶחָד אֶחָד. בַּשִּׁשִּׁי הָיוּ שְׁמוֹנָה פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. כָּל מִשְׁמָר מַקְרִיב אֶחָד. נִשְׁאֲרוּ שָׁם אַרְבָּעָה עָשָׂר כְּבָשִׂים לִשְׁלֹשָׁה עָשָׂר מִשְׁמָר. מִשְׁמָר אֶחָד מֵהֶן מַקְרִיב שְׁנֵי כְּבָשִׂים וּשְׁנֵים עָשָׂר מִשְׁמָר מַקְרִיבִין אֶחָד אֶחָד. בַּשְּׁבִיעִי הָיוּ שָׁם שִׁבְעָה פָּרִים וּשְׁנֵי אֵילִים וְשָׂעִיר. וְאַרְבָּעָה עָשָׂר כְּבָשִׂים כְּמִנְיַן הַמִּשְׁמָרוֹת. נִמְצָא כָּל מִשְׁמָר מַקְרִיב בְּהֵמָה אַחַת:","וְכָל מִי שֶׁהָיָה מַקְרִיב פַּר הַיּוֹם לֹא הָיָה מַקְרִיב פַּר לְמָחָר אֶלָּא חוֹזְרִין חֲלִילָה. בַּשְּׁמִינִי חוֹזְרִין לְפַיִס כֻּלָּן כְּאֶחָד כִּשְׁאָר הָרְגָלִים כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּיוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג שֶׁחָל לִהְיוֹת בְּשַׁבָּת הָיָה שָׁם מִנְחַת נְסָכִים שֶׁל מוּסָפִין וְשֶׁל תְּמִידִין שִׁשִּׁים וְאֶחָד עִשָּׂרוֹן וְלֹא הָיוּ מְעָרְבִין אוֹתוֹ:","וּלְעוֹלָם אֵין מְעָרְבִין נְסָכִים. אֶלָּא נִסְכֵּי הַפָּרִים לְבַדָּם וְנִסְכֵּי הָאֵילִים לְבַדָּם וְנִסְכֵּי כְּבָשִׂים לְבַדָּם. בֵּין בְּקָרְבְּנוֹת צִבּוּר בֵּין בְּקָרְבְּנוֹת יָחִיד:","וְכָל הַחֲלָבִים שֶׁל קָרְבָּנוֹת בֵּין קָרְבְּנוֹת צִבּוּר בֵּין קָרְבְּנוֹת יָחִיד אֵין מְעָרְבִין אוֹתָן זֶה בָּזֶה אֶלָּא מַקְטִירִין אֵימוּרֵי כָּל קָרְבָּן וְקָרְבָּן בִּפְנֵי עַצְמוֹ. וְאִם נִתְעָרְבוּ מַקְטִיר הַכּל כְּאֶחָד:","מְנָחוֹת שֶׁל נְסָכִים שֶׁנִּתְעָרְבוּ זוֹ בָּזוֹ אַחַר שֶׁנִּבְלַל כָּל מִין וּמִין בִּפְנֵי עַצְמוֹ כְּשֵׁרוֹת:","וְכֵיוָן שֶׁנִּבְלְלוּ הַמְּנָחוֹת וְנִתְעָרֵב שַׁמְנָן וְסָלְתָּן הֲרֵי זֶה מֻתָּר לְעָרֵב יַיִן שֶׁלָּהֶן לְכַתְּחִלָּה. וְכֵן אִם הִקְטִיר מְנָחוֹת שֶׁל נְסָכִים כָּל אַחַת וְאַחַת בִּפְנֵי עַצְמָהּ הֲרֵי זֶה מֻתָּר לְעָרֵב הַיַּיִן שֶׁלָּהֶן:","כְּשֶׁמְּעָרְבִין הַיַּיִן שֶׁל נְסָכִים יֵשׁ לוֹ לְעָרֵב יֵין נְסָכִים שֶׁל אֶמֶשׁ בְּשֶׁל יוֹם וְשֶׁל יָחִיד בְּשֶׁל צִבּוּר. וּכְשֶׁמְּעָרֵב מְעָרֵב יֵין נִסְכֵּי פָּרִים בְּיֵין נִסְכֵּי אֵילִים יֵין נִסְכֵּי כְּבָשִׂים בְּיֵין נִסְכֵּי כְּבָשִׂים. אֲבָל אֵין מְעָרְבִין יֵין נִסְכֵּי כְּבָשִׂים בְּיֵין נִסְכֵּי פָּרִים וְאֵילִים:","וּלְעוֹלָם אֵין מְעָרְבִין הַיַּיִן לְכַתְּחִלָּה אֶלָּא אַחַר שֶׁנִּתְעָרְבָה הַסּלֶת אוֹ אַחַר שֶׁהִקְטִירוּ כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Damages to Property 12":["הַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים וְנָפַל לְתוֹכוֹ שׁוֹר אוֹ חֲמוֹר וּמֵת אֲפִלּוּ הָיָה הַבּוֹר מָלֵא גִּזּוֹת שֶׁל צֶמֶר וְכַיּוֹצֵא בָּהֶן הֲרֵי בַּעַל הַבּוֹר חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם שֶׁנֶּאֱמַר (שמות כא לד) \"בַּעַל הַבּוֹר יְשַׁלֵּם\". וְאֶחָד שׁוֹר וַחֲמוֹר אוֹ שְׁאָר מִינֵי בְּהֵמָה חַיָּה וְעוֹף לֹא נֶאֱמַר (שמות כא לג) \"שׁוֹר וַחֲמוֹר\" אֶלָּא בָּהוֹוֶה:","אֶחָד הַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים אוֹ הַחוֹפֵר בּוֹר בִּרְשׁוּתוֹ וּפִתְחוֹ לִרְשׁוּת הָרַבִּים אוֹ פָּתַח לִרְשׁוּת חֲבֵרוֹ אוֹ שֶׁחָפַר וּפָתַח לִרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִיר בּוֹרוֹ הֲרֵי זֶה חַיָּב בִּנְזָקָיו. אֲבָל אִם הִפְקִיר רְשׁוּתוֹ וּבוֹרוֹ אוֹ שֶׁהִפְקִיר בּוֹרוֹ שֶׁבִּרְשׁוּתוֹ אוֹ הִקְדִּישׁוֹ הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (שמות כא לד) \"בַּעַל הַבּוֹר יְשַׁלֵּם\" מִי שֶׁיֵּשׁ לוֹ בְּעָלִים וְזֶה הֶפְקֵר וּבַתְּחִלָּה בִּרְשׁוּת חָפַר מִפְּנֵי שֶׁחָפַר בִּרְשׁוּתוֹ:","אֶחָד הַחוֹפֵר בּוֹר אוֹ שֶׁנֶּחְפַּר מֵאֵלָיו אוֹ שֶׁחֲפָרַתּוּ בְּהֵמָה אוֹ חַיָּה הוֹאִיל וְהוּא חַיָּב לְמַלְּאוֹתוֹ אוֹ לְכַסּוֹתוֹ וְלֹא עָשָׂה הֲרֵי זֶה חַיָּב בִּנְזָקָיו. ואֶחָד הַחוֹפֵר אוֹ הַלּוֹקֵחַ אוֹ שֶׁנִּתַּן לוֹ בְּמַתָּנָה שֶׁנֶּאֱמַר (שמות כא לד) \"בַּעַל הַבּוֹר יְשַׁלֵּם\" מִי שֶׁיֵּשׁ לוֹ בְּעָלִים מִכָּל מָקוֹם:","אֶחָד הַחוֹפֵר אוֹ הַמְגַלֶּה מָקוֹם שֶׁהָיָה מְכֻסֶּה שֶׁנֶּאֱמַר (שמות כא לג) \"כִי יִפְתַּח אִישׁ בּוֹר אוֹ כִּי יִכְרֶה\". וְאִם כִסָּהוּ כָּרָאוּי אַף עַל פִּי שֶׁהִתְלִיעַ מִתּוֹכוֹ וְנָפַל לְתוֹכוֹ שׁוֹר וּמֵת פָּטוּר שֶׁנֶּאֱמַר (שמות כא לג) \"וְלֹא יְכַסֶּנּוּ\" הָא אִם כִּסָּהוּ פָּטוּר. כִּסָּהוּ בְּדָבָר שֶׁיָּכוֹל לַעֲמֹד בִּפְנֵי שְׁוָרִים וְאֵינוֹ יָכוֹל לַעֲמֹד בִּפְנֵי גְּמַלִּים וְהָלְכוּ עָלָיו גְּמַלִּים וְנִתְרוֹעֵעַ וְהָלְכוּ עָלָיו שְׁוָרִים וְנָפְלוּ בּוֹ. אִם אֵין הַגְּמַלִּים מְצוּיִין בְּאוֹתוֹ מָקוֹם הֲרֵי זֶה פָּטוּר מִפְּנֵי שֶׁזֶּה אֹנֶס. וְאִם יָבוֹאוּ שָׁם גְּמַלִּים אֲפִלּוּ לִפְרָקִים הֲרֵי זֶה חַיָּב:","הִתְלִיעַ מִתּוֹכוֹ וְנָפְלוּ בּוֹ שְׁוָרִים אַף עַל פִּי שֶׁהַגְּמַלִּים מְצוּיִין שָׁם תָּמִיד וַהֲרֵי הוּא פּוֹשֵׁעַ לַגְּמַלִּים הוֹאִיל וּמֵחֲמָת שֶׁהִתְלִיעַ נָפְלוּ בּוֹ הַשְּׁוָרִים הֲרֵי זֶה פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹצֵא בּוֹר וְכִסָּהוּ וְחָזַר וְגִלָּהוּ בַּעַל הַבּוֹר חַיָּב וְזֶה הָאַחֲרוֹן פָּטוּר. סְתָמוֹ בְּעָפָר וְחָזַר וְהוֹצִיא אֶת כָּל הֶעָפָר זֶה הָאַחֲרוֹן חַיָּב שֶׁכֵּיוָן שֶׁסְּתָמוֹ בְּעָפָר נִסְתַּלְּקוּ מַעֲשֵׂה הָרִאשׁוֹן:","בּוֹר שֶׁל שְׁנֵי שֻׁתָּפִין וְעָבַר הָרִאשׁוֹן וְלֹא כִּסָּהוּ הַשֵּׁנִי וְלֹא כִּסָּהוּ הָרִאשׁוֹן חַיָּב עַד שֶׁיִּמְסֹר דִּלְיוֹ לַשֵּׁנִי. וּמִשֶּׁמָּסַר דִּלְיוֹ לַשֵּׁנִי לִדְלוֹת מִמֶּנּוּ נִפְטַר הָרִאשׁוֹן וְנִתְחַיֵּב הַשֵּׁנִי לְכַסּוֹתוֹ. כִּסָּהוּ הָרִאשׁוֹן וּבָא הַשֵּׁנִי וּמְצָאוֹ מְגֻלֶּה וְלֹא כִּסָּהוּ הַשֵּׁנִי חַיָּב. וְעַד אֵימָתַי יִהְיֶה הַשֵּׁנִי לְבַדּוֹ חַיָּב. עַד שֶׁיֵּדַע הָרִאשׁוֹן שֶׁהַבּוֹר מְגֻלֶּה וּכְדֵי שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים וִיכַסֶּנּוּ. וְכָל שֶׁיָּמוּת בּוֹ תּוֹךְ זְמַן זֶה הֲרֵי הַשֵּׁנִי לְבַדּוֹ חַיָּב בּוֹ וְכָל שֶׁיָּמוּת בּוֹ אַחַר זְמַן כָּזֶה שְׁנֵיהֶן חַיָּבִין לְשַׁלֵּם שֶׁהֲרֵי שְׁנֵיהֶן פָּשְׁעוּ בּוֹ:","הַמּוֹסֵר בּוֹרוֹ לְשׁוֹמֵר חַיָּב בִּנְזָקָיו. וְאִם מְסָרוֹ לְחֵרֵשׁ שׁוֹטֶה וְקָטָן אַף עַל פִּי שֶׁהָיָה מְכֻסֶּה הֲרֵי הַבְּעָלִים חַיָּבִין שֶׁהַבּוֹר עָשׂוּי לְהִתְגַּלּוֹת וְאֵלּוּ אֵין בָּהֶן דַּעַת:","הַמְכַסֶּה בּוֹרוֹ בְּדִלְיוֹ שֶׁל חֲבֵרוֹ וּבָא בַּעַל הַדְּלִי וְנָטַל דִּלְיוֹ בַּעַל הַבּוֹר חַיָּב:","אֶחָד הַחוֹפֵר בּוֹר אוֹ שִׁיחַ אוֹ מְעָרָה אוֹ חָרִיץ. וְלָמָּה נֶאֱמַר (שמות כא לג) \"בּוֹר\" עַד שֶׁיִּהְיֶה בּוֹ כְּדֵי לְהָמִית. וְכַמָּה כְּדֵי לְהָמִית עֹמֶק עֲשָׂרָה טְפָחִים אֲבָל אִם הָיָה פָּחוֹת מֵעֲשָׂרָה וְנָפַל לְתוֹכוֹ שׁוֹר אוֹ שְׁאָר בְּהֵמָה חַיָּה וְעוֹף וּמֵת פָּטוּר. וְאִם הֻזְּקוּ חַיָּב בַּעַל הַתַּקָּלָה נֵזֶק שָׁלֵם:","הָיָה עֹמֶק הַבּוֹר תִּשְׁעָה וּמֵהֶן טֶפַח אֶחָד מַיִם חַיָּב. שֶׁהַטֶּפַח שֶׁל מַיִם חָשׁוּב כְּעֹמֶק שְׁנֵי טְפָחִים בַּיַּבָּשָׁה. הָיָה עָמֹק שְׁמוֹנָה וּמֵהֶן שְׁנֵי טְפָחִים מַיִם אוֹ שֶׁהָיָה עָמְקוֹ שִׁבְעָה וּמֵהֶן שְׁלֹשָׁה טְפָחִים מַיִם וְנָפַל לְתוֹכוֹ שׁוֹר וְכַיּוֹצֵא בּוֹ וּמֵת אֵין מְחַיְּבִין אוֹתוֹ לְשַׁלֵּם. וְאִם תָּפַשׂ הַנִּזָּק אֵין מוֹצִיאִין מִיָּדוֹ שֶׁהַדְּבָרִים הָאֵלּוּ יֵשׁ בָּהֶן סָפֵק:","הַחוֹפֵר בּוֹר עָמֹק עֲשָׂרָה טְפָחִים וּבָא אַחֵר וְהִשְׁלִימוֹ לְעֶשְׂרִים וּבָא אַחֵר וְהִשְׁלִימוֹ לִשְׁלֹשִׁים כֻּלָּן חַיָּבִים. חָפַר הָרִאשׁוֹן פָּחוֹת מֵעֲשָׂרָה אֲפִלּוּ טֶפַח וּבָא הָאַחֲרוֹן וְהִשְׁלִימוֹ לַעֲשָׂרָה בֵּין שֶׁחָפַר בּוֹ טֶפַח אוֹ שֶׁהִגְבִּיהַּ בִּנְיָן עַל שְׂפָתוֹ טֶפַח זֶה הָאַחֲרוֹן חַיָּב. סָתַם טֶפַח שֶׁהוֹסִיף אוֹ שֶׁסָּתַר טֶפַח שֶׁבָּנָה הֲרֵי זֶה סָפֵק אִם כְּבָר נִסְתַּלֵּק מַעֲשֶׂה רִאשׁוֹן אוֹ עֲדַיִן לֹא נִסְתַּלֵּק:","חָפַר הָרִאשׁוֹן בּוֹר עָמֹק וּבָא הָאַחֲרוֹן וְהִרְחִיבוֹ וְנָפַל לְתוֹכוֹ שׁוֹר וּמֵת. אִם מֵחֲמַת הֶבְלוֹ מֵת הָאַחֲרוֹן פָּטוּר שֶׁהֲרֵי מִעֵט הֶבְלוֹ וְאִם מֵחֲמַת חֲבָטוֹ מֵת הָאַחֲרוֹן חַיָּב שֶׁהֲרֵי הוּא הִקְרִיב הֶזֵּק בּוֹר זֶה. וְכֵן אִם נָפַל הַשּׁוֹר מֵאוֹתוֹ הַצַּד שֶׁהִרְחִיב הָאַחֲרוֹן הָאַחֲרוֹן חַיָּב שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה אַף עַל פִּי שֶׁמֵּת מִן הַהֶבֶל. וְאִם מִן הַצַּד שֶׁחָפַר הָרִאשׁוֹן נָפַל הָרִאשׁוֹן חַיָּב שֶׁזֶּה הָאַחֲרוֹן מִעֵט הֶבְלוֹ:","בּוֹר שֶׁחִיְּבָה עָלָיו הַתּוֹרָה אֲפִלּוּ לֹא מֵתָה הַבְּהֵמָה אֶלָּא מֵהֶבְלוֹ וְאֵין צָרִיךְ לוֹמַר אִם מֵתָה מֵחֲבָטוֹ. לְפִיכָךְ אִם הָיָה עֹמֶק הַבּוֹר כְּרָחְבּוֹ אֵין לוֹ הֶבֶל. וְאִם לֹא נֶחְבְּטָה בּוֹ הַבְּהֵמָה וּמֵתָה פָּטוּר. הָיָה עָמְקוֹ יֶתֶר עַל רָחְבּוֹ יֵשׁ לוֹ הֶבֶל וְאִם מֵתָה בּוֹ הַבְּהֵמָה חַיָּב אַף עַל פִּי שֶׁלֹּא נֶחְבְּטָה בְּקַרְקָעִיתָהּ:","עָשָׂה תֵּל גָּבוֹהַּ בִּרְשׁוּת הָרַבִּים וְנֶחְבְּטָה בּוֹ הַבְּהֵמָה וּמֵתָה. אִם הָיָה גָּבוֹהַּ עֲשָׂרָה טְפָחִים חַיָּב לְשַׁלֵּם. וְאִם הָיָה פָּחוֹת מֵעֲשָׂרָה פָּטוּר עַל מִיתַת הַבְּהֵמָה. אֲבָל אִם הֻזְּקָה בִּלְבַד חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם. וַאֲפִלּוּ בְּתֵל גָּבוֹהַּ כָּל שֶׁהוּא אוֹ בַּחֲפִירָה כָּל שֶׁהִיא. שֶׁהַנֵּזֶק בְּכָל שֶׁהוּא דָּבָר מָצוּי וְיָדוּעַ וְאֵין הַמִּיתָה בְּכָל שֶׁהוּא מְצוּיָה וַהֲרֵי הוּא כְּמוֹ אֹנֶס:","וְכֵן אֵינוֹ חַיָּב עַל מִיתַת הַבְּהֵמָה בְּבוֹר אוֹ עַל חֲבִיטָתָהּ בְּתֵל. אֶלָּא אִם הָיִתָה הַבְּהֵמָה קְטַנָּה אוֹ חֵרֶשֶׁת אוֹ שׁוֹטָה אוֹ סוּמָא אוֹ שֶׁנָּפְלָה בַּלַּיְלָה. אֲבָל אִם הָיְתָה פִּקַּחַת וְנָפְלָה בַּיּוֹם וּמֵתָה פָּטוּר שֶׁזֶּה כְּמוֹ אֹנֶס מִפְּנֵי שֶׁדֶּרֶךְ הַבְּהֵמָה לִרְאוֹת וְלָסוּר מִן הַמִּכְשׁוֹלוֹת. וְכֵן אִם נָפַל לְתוֹכוֹ אָדָם וּמֵת אֲפִלּוּ הָיָה סוּמָא אוֹ שֶׁנָּפַל בַּלַּיְלָה בֵּין שֶׁהָיָה בֶּן חוֹרִין אוֹ עֶבֶד הֲרֵי זֶה פָּטוּר. וְאִם הֻזַּק בּוֹ הָאָדָם אוֹ הַבְּהֵמָה הַפִּקַּחַת חַיָּב נֵזֶק שָׁלֵם כְּמוֹ שֶׁבֵּאַרְנוּ:","נָפַל לְתוֹכוֹ שׁוֹר פְּסוּלֵי הַמֻּקְדָּשִׁין וּמֵת הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (שמות כא לד) \"וְהַמֵּת יִהְיֶה לּוֹ\" מִי שֶׁהַמֵּת שֶׁלּוֹ יָצָא זֶה שֶׁהוּא אָסוּר בַּהֲנָאָה וְדִינוֹ שֶׁיִּקָּבֵר:","הָיָה חוֹפֵר בַּבּוֹר וְנָפְלָה הַבְּהֵמָה בְּתוֹךְ הַבּוֹר מִקּוֹל הַחֲפִירָה וּמֵתָה. אִם נָפְלָה מִלְּפָנֶיהָ חַיָּב. מֵאַחֲרֶיהָ כְּגוֹן שֶׁנִּבְעֲתָה וְחָזְרָה עַל עֲקֵבָהּ לְאָחוֹר וְנָפְלָה וּמֵתָה פָּטוּר שֶׁנֶּאֱמַר (שמות כא לג) \"וְנָפַל\" עַד שֶׁיִּפּל דֶּרֶךְ נְפִילָה. נָפְלָה לְפָנֶיהָ מִקּוֹל הַחֲפִירָה חוּץ לַבּוֹר וּמֵתָה אֵין בֵּית דִּין מְחַיְּבִין אוֹתוֹ. וְאִם תָּפַשׂ הַנִּזָּק אֵין מוֹצִיאִין מִיָּדוֹ. וְאִם נָפְלָה לַאֲחוֹרֶיהָ חוּץ לַבּוֹר וּמֵתָה אוֹ הֻזְּקָה בַּעַל הַבּוֹר פָּטוּר:","שׁוֹר שֶׁדָּחַף בְּהֵמָה לְתוֹךְ הַבּוֹר וּמֵתָה. אִם מוּעָד הוּא בַּעַל הַבּוֹר מְשַׁלֵּם מֶחֱצָה וּבַעַל הַשּׁוֹר מֶחֱצָה. וְאִם תָּם הוּא בַּעַל הַשּׁוֹר מְשַׁלֵּם רְבִיעַ מִגּוּפוֹ וּבַעַל הַבּוֹר מְשַׁלֵּם שְׁלֹשָׁה חֲלָקִים מִן הַיָּפֶה שֶׁבִּנְכָסָיו. שֶׁבַּעַל הַנְּבֵלָה אוֹמֵר לְבַעַל הַבּוֹר פְּחַת נְבֵלָה זוֹ יֵשׁ לִי אֶצְלְךָ אַף עַל פִּי שֶׁהִיא גְּדוֹלָה וּפִקַּחַת כֵּיוָן שֶׁנִּדְחֲפָה הֲרֵי זוֹ כְּמִי שֶׁנָּפְלָה בַּלַּיְלָה כָּל שֶׁאֲנִי יָכוֹל לְהוֹצִיא מִבַּעַל הַשּׁוֹר אֲנִי מוֹצִיא וְהַשְּׁאָר אַתָּה חַיָּב לְשַׁלְּמוֹ:","וְכֵן הַמַּנִּיחַ אֶבֶן עַל פִּי הַבּוֹר וּבָא הַשּׁוֹר וְנִתְקַל בָּהּ וְנָפַל לַבּוֹר וּמֵת. הַמַּנִּיחַ אֶת הָאֶבֶן מְשַׁלֵּם מֶחֱצָה וּבַעַל הַבּוֹר מֶחֱצָה:","וְכֵן שׁוֹר שֶׁל הֶדְיוֹט וְשֶׁל פְּסוּלֵי הַמֻּקְדָּשִׁין שֶׁנָּגְחוּ כְּאֶחָד. אִם תָּם הוּא זֶה שֶׁל הֶדְיוֹט מְשַׁלֵּם חֲצִי נֵזֶק וְאִם מוּעָד נֵזֶק שָׁלֵם. שֶׁהַנִּזָק אוֹמֵר לוֹ כָּל שֶׁאוּכַל לְהוֹצִיא מִזֶּה אוֹצִיא וְהַשְּׁאָר מִמְּךָ וְזֶה הוֹאִיל וְהֶקְדֵּשׁ הוּא וּפָטוּר אַתָּה תְשַׁלֵּם לִי הַכּל:","מִי שֶׁהָיָה חוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים וְנָפַל עָלָיו שׁוֹר וַהֲרָגוֹ. בַּעַל הַשּׁוֹר פָּטוּר. וְאִם מֵת הַשּׁוֹר נוֹטֵל בַּעַל הַשּׁוֹר דְּמֵי שׁוֹרוֹ מִיּוֹרְשֵׁי בַּעַל הַבּוֹר:"],"Mishneh Torah, Defilement by Leprosy 10":["הַתּוֹלֵשׁ סִימָנֵי טֻמְאָה בֵּין כֻּלָּן בֵּין מִקְצָתָן. אוֹ הִכְוָה אֶת הַמִּחְיָה כֻּלָּהּ אוֹ מִקְּצָתָהּ. אוֹ הַקּוֹצֵץ הַנֶּגַע כֻּלּוֹ מִבְּשָׂרוֹ אוֹ מִן הַבֶּגֶד אוֹ מִן הַבַּיִת. בֵּין קֹדֶם שֶׁיָּבוֹא לַכֹּהֵן בֵּין בְּתוֹךְ הֶסְגֵּר אוֹ בְּתוֹךְ הֶחְלֵט אוֹ אַחַר הַפִּטּוּר הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כד ח) \"הִשָּׁמֶר בְּנֶגַע הַצָּרַעַת לִשְׁמֹר מְאֹד וְלַעֲשׂוֹת כְּכל אֲשֶׁר יוֹרוּ אֶתְכֶם הַכֹּהֲנִים הַלְוִיִּם כַּאֲשֶׁר צִוִּיתִם\", תִּשְׁמְרוּ שֶׁלֹּא יִתְלֹשׁ אוֹ שֶׁיָּקֹץ. אֲבָל אֵינוֹ לוֹקֶה עַד שֶׁיּוֹעִילוּ מַעֲשָׂיו וְאִם לֹא הוֹעִילוּ אֵינוֹ לוֹקֶה. כֵּיצַד. הָיְתָה בּוֹ בַּהֶרֶת וּבָהּ שָׁלֹשׁ שְׂעָרוֹת לְבָנוֹת וְתָלַשׁ אַחַת. כָּוָה מִקְצָת הַמִּחְיָה וְנִשְׁאַר מִמֶּנָּה כַּעֲדָשָׁה. אֵינוֹ לוֹקֶה שֶׁהֲרֵי הוּא טָמֵא כְּשֶׁהָיָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכֵן הַמְגַלֵּחַ אֶת הַנֶּתֶק לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יג לג) \"וְאֶת הַנֶּתֶק לֹא יְגַלֵּחַ\". וְאֵינוֹ חַיָּב עַד שֶׁיְּגַלֵּחַ כָּל הַנֶּתֶק בְּתַעַר. וּמֻתָּר לִמְצֹרָע לִשָּׂא בְּמוֹט עַל כְּתֵפוֹ שֶׁיֵּשׁ בָּהּ הַצָּרַעַת וְלִקְשֹׁר הַסִּיב עַל רַגְלוֹ וְאִם הָלְכוּ סִימָנֵי טֻמְאָה יֵלְכוּ וְהוּא שֶׁלֹּא נִתְכַּוֵּן לְכָךְ:","הַתּוֹלֵשׁ סִימָנֵי טֻמְאָה אוֹ שֶׁכָּוָה אֶת הַמִּחְיָה עַד שֶׁלֹּא בָּא אֵצֶל כֹּהֵן הֲרֵי זֶה טָהוֹר. וְכֵן אִם עָשָׂה כֵּן בִּימֵי הֶסְגֵּר הֲרֵי זֶה טָהוֹר לְאַחַר יְמֵי הֶסְגֵּר. וְאִם תְּלָשָׁן אַחַר שֶׁהֻחְלַט בָּהֶן הֲרֵי זֶה מֻחְלָט כְּשֶׁהָיָה וְאֵין לוֹ טָהֳרָה עַד שֶׁתִּפְרַח הַצָּרַעַת בְּכֻלּוֹ אוֹ עַד שֶׁתִּתְמַעֵט בַּהַרְתּוֹ מִכִּגְרִיס:","מִי שֶׁנִּקְצְצָה בַּהַרְתּוֹ כֻּלָּהּ שֶׁלֹּא בְּכַוָּנָה טָהוֹר. קְצָצָהּ בְּכַוָּנָה אִם קָצַץ כָּל הַבָּשָׂר הַחַי הַמַּקִּיפָהּ אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה אֵין לוֹ טָהֳרָה עוֹלָמִית. קְצָצָהּ בְּצִמְצוּם אֵין לוֹ טָהֳרָה עַד שֶׁתִּפְרַח בְּכֻלּוֹ:","הַתּוֹלֵשׁ שְׂעָרָה לְבָנָה אַחַת וְנָשְׁרָה הַשְּׁנִיָּה הֲרֵי זֶה טָהוֹר. הָיוּ שָׁלֹשׁ תָּלַשׁ שְׁתַּיִם וְנָשְׁרָה אַחַת הֲרֵי זֶה בְּטֻמְאָתוֹ. הָיְתָה בּוֹ מִחְיָה כַּעֲדָשָׁה כָּוָה חֶצְיָהּ וְהָלַךְ חֶצְיָהּ הֲרֵי זֶה טָהוֹר. הָיְתָה יְתֵרָה מִכַּעֲדָשָׁה כָּוָה הַמּוֹתָר וְהָלַךְ כַּעֲדָשָׁה הֲרֵי זֶה טָהוֹר. כָּוָה כַּעֲדָשָׁה וְהָלַךְ הַמּוֹתָר הֲרֵי זֶה טָמֵא:","מִי שֶׁהָיְתָה בַּהֶרֶת בְּעָרְלָתוֹ יָמוּל וְאַף עַל פִּי שֶׁהִיא מִילָה שֶׁלֹּא בִּזְמַנָּהּ שֶׁמִּצְוַת עֲשֵׂה דּוֹחָה אֶת לֹא תַּעֲשֶׂה בְּכָל מָקוֹם. וְאִם מָל וְהָלַךְ בְּעוֹר הָעָרְלָה סִימָן שֶׁהָיָה מֻחְלָט בּוֹ הֲרֵי זֶה חַיָּב בְּקָרְבַּן מְצֹרָע:","מִצְוַת עֲשֵׂה שֶׁיִּהְיֶה הַמְצֹרָע הַמֻּחְלָט מְכֻסֶּה רֹאשׁ כָּל יְמֵי חִלּוּטוֹ וְעוֹטֶה עַל שָׂפָם כְּאָבֵל וּפוֹרֵם בְּגָדָיו וּמוֹדִיעַ הָעוֹבְרִים עָלָיו שֶׁהוּא טָמֵא שֶׁנֶּאֱמַר (ויקרא יג מה) \"וְהַצָּרוּעַ אֲשֶׁר בּוֹ הַנֶּגַע\" וְגוֹ'. אֲפִלּוּ כֹּהֵן גָּדוֹל שֶׁנִּצְטָרֵעַ פּוֹרֵעַ וּפוֹרֵם שֶׁעֲשֵׂה דּוֹחֶה אֶת לֹא תַּעֲשֶׂה. וְאָסוּר בִּשְׁאִילַת שָׁלוֹם כָּל יְמֵי חִלּוּטוֹ כְּאָבֵל שֶׁנֶּאֱמַר (ויקרא יג מה) \"וְעַל שָׂפָם יַעְטֶה\" שֶׁיִּהְיוּ שְׂפָתָיו דְּבוּקוֹת. אֲבָל קוֹרֵא וְשׁוֹנֶה וְדוֹרֵשׁ. וְאָסוּר לְסַפֵּר וּלְכַבֵּס כָּל יְמֵי חִלּוּטוֹ. וְנוֹהֵג בְּכָל הַדְּבָרִים הָאֵלּוּ אֲפִלּוּ בְּשַׁבָּתוֹת וְיָמִים טוֹבִים. וַהֲרֵי הוּא מֻתָּר בִּרְחִיצָה וּבְסִיכָה וּבִנְעִילַת הַסַּנְדָּל וּבְתַשְׁמִישׁ הַמִּטָּה וְזוֹקֵף אֶת מִטָּתוֹ כִּשְׁאָר הָעָם:","דִּין הַמְצֹרָע שֶׁיִּהְיֶה לוֹ מוֹשָׁב לְבַדּוֹ חוּץ לָעִיר שֶׁנֶּאֱמַר (ויקרא יג מו) \"מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ\". וְדָבָר זֶה בַּעֲיָרוֹת הַמֻּקָּפוֹת חוֹמָה בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד:","הַמְצֹרַעַת אֵינָהּ פּוֹרַעַת וְאֵינָהּ פּוֹרֶמֶת וְלֹא עוֹטָה עַל שָׂפָם אֲבָל יוֹשֶׁבֶת הִיא מִחוּץ לָעִיר וּמוֹדִיעָה לַאֲחֵרִים שֶׁהִיא טְמֵאָה. וְלֹא הַמְצֹרָעִים בִּלְבַד אֶלָּא כָּל הַמְטַמְּאִים אֶת הָאָדָם חַיָּבִין לְהוֹדִיעַ לַכּל שֶׁהֵן טְמֵאִין כְּדֵי שֶׁיִּפְרְשׁוּ מֵהֶן שֶׁנֶּאֱמַר (ויקרא יג מה) \"וְטָמֵא טָמֵא יִקְרָא\", הַטָּמֵא מוֹדִיעַ שֶׁהוּא טָמֵא:","וְטֻמְטוּם וְאַנְדְּרוֹגִינוּס פּוֹרֵעַ וּפוֹרֵם וְעוֹטֶה עַל שָׂפָם מִפְּנֵי שֶׁהוּא סָפֵק:","אֶחָד מְצֹרָע מֻסְגָּר וְאַחַד מְצֹרָע מֻחְלָט לְעִנְיַן טֻמְאָה. וְאֵין בֵּין מְצֹרָע מֻסְגָּר לִמְצֹרָע מֻחְלָט לְעִנְיַן טֻמְאָה אֶלָּא פְּרִיעָה וּפְרִימָה וְתִגְלַחַת וְצִפֳּרִים שֶׁהַטָּהוֹר מִתּוֹךְ הֶסְגֵּר פָּטוּר מִן הַתִּגְלַחַת וּמִן הַצִּפֳּרִים וְהַטָּהוֹר מִתּוֹךְ הֶחְלֵט חַיָּב בָּהֶן. אֲבָל טֻמְאַת שְׁנֵיהֶן שָׁוָה בְּכָל דָּבָר:","הַמְצֹרָע אָב מֵאֲבוֹת הַטֻּמְאוֹת מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּעוֹ וּכְלֵי חֶרֶס בַּאֲוִירוֹ וּמְטַמֵּא אָדָם בְּמַשָּׂא וּמְטַמֵּא מִשְׁכָּב וּמוֹשָׁב אֲפִלּוּ תַּחַת אֶבֶן כְּזָב וּכְזָבָה שֶׁנֶּאֱמַר (ויקרא יג ו) \"וְכִבֶּס בְּגָדָיו וְטָהֵר\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁטָּהֵר מִלְּטַמֵּא מִשְׁכָּב וּמוֹשָׁב. וְאֶחָד הַמֻּסְגָּר וְאַחַד הַמֻּחְלָט בְּכָל אֵלּוּ:","חֻמְרָא יְתֵרָה יֵשׁ בִּמְצֹרָע שֶׁמְּטַמֵּא בְּבִיאָתוֹ לַבַּיִת בֵּין בִּימֵי הֶחְלֵט בֵּין בִּימֵי הֶסְגֵּר. כֵּיצַד. נִכְנַס לַבַּיִת נִטְמָא כָּל אֲשֶׁר בַּבַּיִת בֵּין אָדָם בֵּין כֵּלִים אַף עַל פִּי שֶׁלֹּא נָגַע בָּהֶן נַעֲשׂוּ רִאשׁוֹן לְטֻמְאָה שֶׁנֶּאֱמַר (ויקרא יג מו) \"מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ\" מַה הוּא טָמֵא אַף מוֹשָׁבוֹ טָמֵא. הָיָה עוֹמֵד תַּחַת הָאִילָן וְעָבַר אָדָם טָהוֹר תַּחַת הָאִילָן נִטְמָא. הָיָה הַטָּהוֹר עוֹמֵד תַּחַת הָאִילָן וְעָבַר הַמְצֹרָע תַּחְתָּיו לֹא טִמְּאָהוּ וְאִם עָמַד נִטְמָא שֶׁהֲרֵי נַעֲשָׂה לוֹ מוֹשָׁב. סָפֵק עָמַד סָפֵק לֹא עָמַד טָהוֹר. הִכְנִיס הַמְצֹרָע רֹאשׁוֹ וְרֻבּוֹ לַבַּיִת נִטְמָא כָּל שֶׁיֵּשׁ בְּתוֹכוֹ. נִכְנַס לְבֵית הַכְּנֶסֶת עוֹשִׂין לוֹ מְחִצָּה גָּבוֹהַּ עֲשָׂרָה טְפָחִים וּרְחָבָה אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת וְנִכְנַס רִאשׁוֹן וְיוֹצֵא אַחֲרוֹן. כְּדֵי שֶׁיִּהְיֶה מוֹשָׁבוֹ לְבַדּוֹ וְלֹא יַעֲמֹד עִם הָעָם בְּעִרְבּוּב וִיטַמֵּא אוֹתָם:"],"Mishneh Torah, Defilement by Leprosy 7":["מִי שֶׁהָיְתָה בּוֹ בַּהֶרֶת וְהֻחְלַט בְּאֶחָד מִסִּימָנֵי טֻמְאָה בֵּין בַּתְּחִלָּה בֵּין אַחַר הֶסְגֵּר. אוֹ שֶׁהֻסְגַּר וְאַחַר כָּךְ פָּרְחָה הַצָּרַעַת בְּכֻלּוֹ וְנֶהְפַּךְ לָבָן. בֵּין שֶׁנֶּהְפַּךְ מִתּוֹךְ הֶסְגֵּר בֵּין מִתּוֹךְ הֶחְלֵט הֲרֵי זֶה טָהוֹר. אֲבָל אִם הֻסְגַּר וְלֹא נוֹלַד לוֹ סִימַן טֻמְאָה וְנִפְטַר וּלְאַחַר הַפִּטּוּר פָּרְחָה הַצָּרַעַת בְּכֻלּוֹ הֲרֵי זֶה טָמֵא מֻחְלָט:","הַבָּא בַּתְּחִלָּה וְהוּא כֻּלּוֹ הָפַךְ לָבָן. אִם הָיְתָה בּוֹ מִחְיָה אוֹ שְׁתֵּי שְׂעָרוֹת לְבָנוֹת מַחְלִיטִין אוֹתוֹ. אִם אֵין שָׁם סִימַן טֻמְאָה מַסְגִּירִין אוֹתוֹ שָׁבוּעַ רִאשׁוֹן. נוֹלַד לוֹ שֵׂעָר לָבָן אוֹ מִחְיָה מַחְלִיטוֹ. לֹא נוֹלַד בּוֹ כְּלוּם מַסְגִּירוֹ שָׁבוּעַ שֵׁנִי. לֹא נוֹלַד לוֹ סִימַן טֻמְאָה הֲרֵי זֶה טָהוֹר. שֶׁדִּין בַּהֶרֶת זוֹ הַגְּדוֹלָה כְּדִין הַקְּטַנָּה. הֶחְלִיטוֹ בְּשֵׂעָר לָבָן שֶׁנּוֹלַד בּוֹ וְהִשְׁחִירוּ שְׁתֵּיהֶן אוֹ אַחַת מֵהֶן. הִקְצִירוּ שְׁתֵּיהֶן אוֹ אַחַת מֵהֶן. נִסְמַךְ הַשְּׁחִין לִשְׁתֵּיהֶן אוֹ לְאַחַת מֵהֶן. הִקִּיף הַשְּׁחִין אֶת שְׁתֵּיהֶן אוֹ אַחַת מֵהֶן. אוֹ שֶׁחִלְּקָן הַשְּׁחִין וּמִחְיַת הַשְּׁחִין וְהַמִּכְוָה וּמִחְיַת הַמִּכְוָה וְהַבֹּהַק. הֲרֵי זֶה טָהוֹר. נוֹלַד לוֹ שֵׂעָר לָבָן אַחֵר אוֹ מִחְיָה הֲרֵי זֶה טָמֵא מִפְּנֵי שֶׁבָּא כֻּלּוֹ לָבָן בַּתְּחִלָּה. אֶחָד שֶׁפָּרְחָה הַצָּרַעַת בְּכֻלּוֹ כְּאַחַת וְאֶחָד שֶׁפָּשְׂתָה וּפָרְחָה מְעַט מְעַט עַד שֶׁהִלְבִּין כֻּלּוֹ. אִם מִתּוֹךְ הֶסְגֵּר אוֹ מִתּוֹךְ הֶחְלֵט טָהוֹר. וְאִם אַחַר הַפִּטּוּר טָמֵא. וְאִם בַּתְּחִלָּה יַסְגִּיר. אֶחָד שֶׁהָיָה כֻּלּוֹ מַרְאֶה אֶחָד אוֹ שֶׁהָיָה כֻּלּוֹ לָבָן בְּאַרְבַּע הַמַּרְאוֹת שֶׁבַּלֹּבֶן וּבְאַרְבַּע שֶׁל פָּתוּךְ הַכּל מִצְטָרְפִין בֵּין לְטַהֲרוֹ בֵּין לְטַמְּאוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיְתָה בּוֹ בַּהֶרֶת כִּגְרִיס וּבָהּ מִחְיָה כַּעֲדָשָׁה וְהֻחְלַט בְּמִחְיָה וּפָרְחָה הַצָּרַעַת בְּכֻלּוֹ וְאַחַר כָּךְ הָלְכָה הַמִּחְיָה. אוֹ שֶׁהָלְכָה הַמִּחְיָה תְּחִלָּה וְאַחַר כָּךְ פָּרְחָה בְּכֻלּוֹ. הֲרֵי זֶה טָהוֹר וַאֲפִלּוּ נוֹלַד לוֹ שֵׂעָר לָבָן. נוֹלְדָה בּוֹ מִחְיָה טָמֵא שֶׁנֶּאֱמַר (ויקרא יג יד) \"וּבְיוֹם הֵרָאוֹת בּוֹ בָּשָׂר חַי יִטְמָא\". וְהוּא שֶׁתִּהְיֶה כַּעֲדָשָׁה מְרֻבַּעַת אוֹ יֶתֶר. הָיְתָה בּוֹ בַּהֶרֶת וּבָהּ שֵׂעָר לָבָן וְהֻחְלַט בְּשֵׂעָר לָבָן וְאַחַר כָּךְ פָּרְחָה בְּכֻלּוֹ אַף עַל פִּי שֶׁשֵּׂעָר לָבָן בִּמְקוֹמוֹ עוֹמֵד טָהוֹר. שֶׁנֶּאֱמַר וּבְיוֹם הֵרָאוֹת בּוֹ בָּשָׂר חַי יִטְמָא בְּמִחְיָה מִתְטַמֵּא זֶה שֶׁנֶּהְפַּךְ כֻּלּוֹ לָבָן אַחַר הֶחְלֵט אוֹ אַחַר הֶסְגֵּר. וְאֵינוֹ מִטַּמֵּא בְּשֵׂעָר לָבָן. הֶחְלִיטוֹ בְּפִשְׂיוֹן וְאַחַר כָּךְ פָּשְׂתָה וּפָרְחָה בְּכֻלּוֹ טָהוֹר. וְאִם נִרְאֵית בּוֹ מִחְיָה טָמֵא:","אַף רָאשֵׁי אֵיבָרִים שֶׁאֵינָן מִטַּמְּאִין מִשּׁוּם מִחְיָה שֶׁבְּתוֹךְ הַבַּהֶרֶת מִטַּמְּאִין וּמְעַכְּבִין אֶת הַנֶּהְפָּךְ כֻּלּוֹ לָבָן. כֵּיצַד. מֻחְלָט אוֹ מֻסְגָּר שֶׁהִלְבִּין כֻּלּוֹ בְּצָרַעַת חוּץ מִכַּעֲדָשָׁה בָּשָׂר חַי אֲפִלּוּ בְּרֹאשׁ אֶצְבָּעוֹ אוֹ בְּרֹאשׁ חָטְמוֹ וְכַיּוֹצֵא בָּהֶן הֲרֵי הוּא בְּטֻמְאָתוֹ. וְכֵן זֶה שֶׁנֶּהְפַּךְ כֻּלּוֹ לָבָן וְטָהַר אִם חָזַר בּוֹ כַּעֲדָשָׁה בָּשָׂר חַי אֲפִלּוּ בְּרֹאשׁ אֶחָד מִן הָאֵיבָרִים הֲרֵי זֶה מֻחְלָט. נֶהְפַּךְ כֻּלּוֹ לְמַרְאֵה צָרַעַת חוּץ מִכַּעֲדָשָׁה אֲפִלּוּ בְּרֹאשׁ אֶחָד מִן הָאֵיבָרִים שֶׁנֶּהְפַּךְ לְבֹהַק הֲרֵי זֶה טָמֵא מֻחְלָט שֶׁנֶּאֱמַר (ויקרא יג יג) \"וְהִנֵּה כִסְּתָה הַצָּרַעַת\", לֹא הַבֹּהַק. אֲפִלּוּ הָיְתָה מִקְצָת הָעֲדָשָׁה בָּשָׂר חַי וּמִקְצָתָהּ בֹּהַק הֲרֵי זוֹ סִימַן טֻמְאָה. נֶהְפַּךְ כֻּלּוֹ לְמַרְאֵה צָרַעַת וְטִהַר וְאַחַר כָּךְ חָזַר בּוֹ בָּשָׂר כְּמַרְאֵה הַבֹּהַק הֲרֵי זֶה טָהוֹר עַד שֶׁיֵּרָאֶה בּוֹ כַּעֲדָשָׁה בָּשָׂר חַי שֶׁנֶּאֱמַר (ויקרא יג יד) \"וּבְיוֹם הֵרָאוֹת בּוֹ בָּשָׂר חַי\", לֹא בֹּהַק. חָזַר בּוֹ כַּעֲדָשָׁה מִקְצָתָהּ בָּשָׂר חַי וּמִקְצָתָהּ בֹּהַק אֵינוֹ סִימַן טֻמְאָה וַהֲרֵי הוּא בְּטָהֳרָתוֹ:","כָּל טָמֵא שֶׁפָּרְחָה הַצָּרַעַת בְּכֻלּוֹ טָהוֹר. נִתְגַּלָּה מִמֶּנּוּ כַּעֲדָשָׁה בָּשָׂר חַי נִטְמָא. חָזַר וְנִתְכַּסָּה בְּצָרַעַת טָהוֹר. חָזַר וְנִתְגַּלָּה נִטְמָא אֲפִלּוּ מֵאָה פְּעָמִים. הִתְחִיל הַבָּשָׂר הַחַי לְהִתְגַּלּוֹת וַהֲרֵי הוּא מוֹסִיף וְהוֹלֵךְ וְהַצָּרַעַת מִתְמַעֶטֶת הֲרֵי זֶה בְּטֻמְאָתוֹ עַד שֶׁתִּתְמַעֵט הַבַּהֶרֶת מִכִּגְרִיס:","כָּל הָרָאוּי לִטַּמֵּא בְּנֶגַע הַבַּהֶרֶת מְעַכֵּב הַהוֹפֵךְ כֻּלּוֹ לָבָן וְכָל שֶׁאֵינוֹ רָאוּי לִטַּמֵּא בְּנֶגַע הַבַּהֶרֶת אֵינוֹ מְעַכֵּב. כֵּיצַד. פָּרְחָה בְּכֻלּוֹ אֲבָל לֹא בָּרֹאשׁ וּבַזָּקָן בַּשְּׁחִין וּבַמִּכְוָה הַמּוֹרְדִין. אוֹ שֶׁנִּשְׁאַר פָּחוֹת מִכַּעֲדָשָׁה בָּשָׂר חַי סָמוּךְ לַשְּׁחִין וְלַמִּכְוָה הַמּוֹרְדִין וְלָרֹאשׁ וְלַזָּקָן הֲרֵי זֶה טָהוֹר. חָזַר הָרֹאשׁ וְהַזָּקָן וְנִקְרְחוּ וְכֵן אִם חָיוּ הַשְּׁחִין וְהַמִּכְוָה וְהֶעֱלוּ צָרֶבֶת הֲרֵי זֶה טָמֵא עַד שֶׁתִּפְרַח הַצָּרַעַת בָּהֶן שֶׁהֲרֵי הֵן רְאוּיִין לְבַהֶרֶת. הָיוּ בָּהּ שְׁתֵּי בֶּהָרוֹת אַחַת יֵשׁ בָּהּ סִימַן טֻמְאָה וְאַחַת טְהוֹרָה וּפָרְחָה הַטְּהוֹרָה לַטְּמֵאָה וְאַחַר כָּךְ פָּרְחָה בְּכֻלּוֹ הֲרֵי זֶה טָהוֹר מִפְּנֵי שֶׁהָיָה מֻחְלָט בְּטֻמְאָה אַף עַל פִּי שֶׁהַטְּהוֹרָה הִיא שֶׁפָּרְחָה. וְלֹא עוֹד אֶלָּא אֲפִלּוּ הָיוּ אַחַת בִּשְׂפָתוֹ הָעֶלְיוֹנָה וְאַחַת בִּשְׂפָתוֹ הַתַּחְתּוֹנָה אוֹ בִּשְׁתֵּי אֶצְבְּעוֹתָיו אוֹ בִּשְׁנֵי רִיסֵי עֵינָיו וּכְשֶׁהֵן נִדְבָּקִין זֶה לָזֶה נִרְאִין שְׁתֵּי הַבֶּהָרוֹת כְּבַהֶרֶת אַחַת הוֹאִיל וּפָרְחָה בְּכֻלּוֹ טָהוֹר:","יֵשׁ מַרְאֶה נִגְעוֹ לְכֹהֵן וְנִשְׂכַּר מִפְּנֵי שֶׁהִקְדִּים לְהַרְאוֹתוֹ וְלֹא נִתְאַחֵר. וְיֵשׁ מַרְאֶה וּמַפְסִיד. כֵּיצַד. מִי שֶׁהָיָה מֻחְלָט וְהָלְכוּ לָהֶן סִימָנֵי טֻמְאָה וְלֹא הִסְפִּיק לְהַרְאוֹתוֹ לַכֹּהֵן עַד שֶׁפָּרְחָה בְּכֻלּוֹ טָהוֹר. וְאִלּוּ קָדַם וְהֶרְאָה לַכֹּהֵן וּפְטָרוֹ קֹדֶם שֶׁיַּהֲפֹךְ וְנֶהְפַּךְ אַחַר הַפִּטּוּר הָיָה מֻחְלָט כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה בּוֹ בַּהֶרֶת וְאֵין בָּהּ כְּלוּם וְלֹא הִסְפִּיק לְהַרְאוֹתוֹ לַכֹּהֵן עַד שֶׁפָּרְחָה בְּכֻלּוֹ הֲרֵי זֶה טָמֵא וְצָרִיךְ הֶסְגֵּר. וְאִלּוּ קָדַם וְהֶרְאָה לַכֹּהֵן וְהִסְגִּירוֹ קֹדֶם שֶׁיַּהֲפֹךְ וְנֶהְפַּךְ מִתּוֹךְ הֶסְגֵּר הָיָה טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement by a Corpse 18":["אָדָם שֶׁהֶאֱהִיל בְּיָדוֹ אַחַת עַל הַמֵּת וְהֶאֱהִיל בַּשְּׁנִיָּה עַל הַכֵּלִים אוֹ שֶׁנָּגַע בְּמֵת וְהֶאֱהִיל עַל הַכֵּלִים אִם יֵשׁ בְּיָדוֹ פּוֹתֵחַ טֶפַח הַכֵּלִים טְמֵאִין וְאִם לָאו טְהוֹרִין. וְכֵן שְׁנֵי בָּתִּים וּבָהֶם שְׁנֵי חֲצָאֵי זֵיתִים וּפָשַׁט יָדוֹ לְבַיִת זֶה וְיָדוֹ הַשְּׁנִיָּה לַבַּיִת הַשֵּׁנִי אִם יֵשׁ בְּיָדוֹ פּוֹתֵחַ טֶפַח עֵרֵב אֶת הַטֻּמְאָה וְנַעֲשָׂה הַכּל כְּאֹהֶל אֶחָד וְנִטְמָא הוּא וְהַבָּתִּים. וְאִם לָאו אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה:","אָדָם שֶׁהִשְׁקִיף בְּעַד הַחַלּוֹן וְהֶאֱהִיל עַל הַטֻּמְאָה מֵבִיא אֶת הַטֻּמְאָה לַבַּיִת וְנִטְמָא כָּל הַבַּיִת. הָיָה מֻטָּל עַל הָאַסְקֻפָּה וּמִקְצָתוֹ בְּתוֹךְ הַבַּיִת וּמִקְצָתוֹ בַּחוּץ וְהֶאֱהִילָה טֻמְאָה עַל מִקְצָתוֹ שֶׁבַּחוּץ הַבַּיִת טָמֵא. מִפְּנֵי שֶׁהָאָדָם חָלוּל וְיֵשׁ בּוֹ גֹּבַהּ טֶפַח וְכֵיוָן שֶׁהֶאֱהִילָה טֻמְאָה עָלָיו הֲרֵי זֶה כְּמַאֲהִיל עָלֶיהָ וּמֵבִיא אֶת הַטֻּמְאָה. וְכֵן אִם הָיְתָה טֻמְאָה בַּבַּיִת וְהֶאֱהִילוּ טְהוֹרִין עַל מִקְצָתוֹ שֶׁבַּחוּץ הֲרֵי אֵלּוּ טְמֵאִין מִפְּנֵי שֶׁהוּא כְּמַאֲהִיל עַל הַטֻּמְאָה וְהָאָדָם מֵבִיא וְאֵינוֹ חוֹצֵץ כְּמוֹ שֶׁבֵּאַרְנוּ:","נוֹשְׂאֵי הַמֵּת שֶׁעָבְרוּ בּוֹ תַּחַת הָאַכְסַדְרָה וְהֵגִיף אֶחָד מֵהֶן אֶת הַדֶּלֶת וּסְמָכוֹ בְּמַפְתֵּחַ כְּדֵי שֶׁלֹּא יִטַּמֵּא הַבַּיִת. וְכֵן אִם הָיָה אָדָם מִבִּפְנִים אוֹ מִבַּחוּץ סוֹמֵךְ הַדֶּלֶת. אִם יָכוֹל הַדֶּלֶת לַעֲמֹד בִּפְנֵי עַצְמוֹ הַבַּיִת טָהוֹר. וְאִם לָאו הַבַּיִת טָמֵא לְפִי שֶׁנִּמְצָא הָאָדָם הוּא שֶׁחָצַץ בִּפְנֵי הַטֻּמְאָה וְהָאָדָם וְהַכֵּלִים מְבִיאִין וְאֵינָן חוֹצְצִין כְּמוֹ שֶׁבֵּאַרְנוּ:","תַּנּוּר שֶׁהוּא עוֹמֵד בְּתוֹךְ הַבַּיִת וְעֵינוֹ קְמוּרָה לַחוּץ וְהֶאֱהִילוּ נוֹשְׂאֵי הַמֵּת עַל עֵינוֹ הַקְּמוּרָה הַתַּנּוּר טָמֵא וְהַבַּיִת טָהוֹר. שֶׁהֲרֵי אֵין הַתַּנּוּר גָּבוֹהַּ מֵעַל הָאָרֶץ כְּדֵי שֶׁיָּבִיא טֻמְאָה לַבַּיִת. מִגְדָּל הַבָּא בְּמִדָּה שֶׁהוּא עוֹמֵד בְּתוֹךְ הַפֶּתַח וְנִפְתַּח לַחוּץ טֻמְאָה בְּתוֹכוֹ הַבַּיִת טָהוֹר. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכוֹ טָמֵא שֶׁהֲרֵי הוּא פָּתוּחַ בְּתוֹךְ הַפֶּתַח וְדֶרֶךְ הַטֻּמְאָה לָצֵאת וְאֵין דַּרְכָּהּ לְהִכָּנֵס. הָיְתָה מוּכְנִי שֶׁלּוֹ מְשׁוּכָה לַאֲחוֹרָיו וְיוֹצֵאת פָּחוֹת מִטֶּפַח וְאֵינָהּ נִשְׁמֶטֶת וְטֻמְאָה שָׁם בְּתוֹכָהּ כְּנֶגֶד הַקּוֹרוֹת הַבַּיִת טָהוֹר שֶׁאַף עַל פִּי שֶׁהִיא יוֹצְאָה אֵינָהּ נִשְׁמֶטֶת וְאֵינָהּ יוֹצֵאת טֶפַח. וְהוּא שֶׁיִּהְיֶה בָּהּ טֶפַח עַל רוּם טֶפַח חָלוּל. אֲבָל אִם אֵין בַּמּוּכְנִי חֲלַל טֶפַח הֲרֵי הַטֻּמְאָה רְצוּצָה בְּתוֹךְ הַבַּיִת וְהַבַּיִת טָמֵא. הָיָה הַמִּגְדָּל עוֹמֵד בְּתוֹךְ הַבַּיִת וְהַטֻּמְאָה בְּתוֹכוֹ אוֹ בְּתוֹךְ הַתֵּבָה שֶׁלּוֹ אַף עַל פִּי שֶׁאֵין בִּיצִיאָתוֹ פּוֹתֵחַ טֶפַח הַבַּיִת טָמֵא. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכוֹ טָהוֹר שֶׁדֶּרֶךְ הַטֻּמְאָה לָצֵאת וְאֵין דַּרְכָּהּ לְהִכָּנֵס:","כֵּלִים שֶׁבֵּין הַמִּגְדָּל וּבֵין הָאָרֶץ שֶׁבֵּינוֹ וּבֵין הַכֹּתֶל וְשֶׁבֵּינוֹ וּבֵין הַקּוֹרוֹת אִם יֵשׁ שָׁם פּוֹתֵחַ טֶפַח טְמֵאִים וְאִם לָאו טְהוֹרִים שֶׁהֲרֵי אָנוּ רוֹאִים אֶת הַקּוֹרוֹת כְּאִלּוּ הֵן יוֹרְדוֹת וְסוֹתְמוֹת:","הָיְתָה טֻמְאָה תַּחַת הַמִּגְדָּל בֵּינוֹ וּבֵין הָאָרֶץ אוֹ בֵּינוֹ וּבֵין הַקּוֹרוֹת אוֹ בֵּינוֹ וּבֵין הַכֹּתֶל בֵּין שֶׁיֵּשׁ שָׁם חָלָל טֶפַח בֵּין שֶׁאֵין שָׁם הַבַּיִת טָמֵא. הָיָה עוֹמֵד בָּאֲוִיר וְטֻמְאָה בְּתוֹכוֹ כֵּלִים שֶׁבְּעָבְיוֹ טְהוֹרִים. טֻמְאָה בְּעָבְיוֹ כֵּלִים שֶׁבְּתוֹכוֹ טְהוֹרִים:","כָּל שִׁפּוּעֵי אֹהָלִים כְּאֹהָלִים. כֵּיצַד. אֹהֶל שֶׁהוּא שׁוֹפֵעַ וְיוֹרֵד וְכָלֶה עַד כְּאֶצְבַּע וְטֻמְאָה בָּאֹהֶל כֵּלִים שֶׁתַּחַת הַשִּׁפּוּעַ טְמֵאִים. טֻמְאָה תַּחַת הַשִּׁפּוּעַ כֵּלִים שֶׁבָּאֹהֶל טְמֵאִים. הַטֻּמְאָה מִתּוֹךְ הַשִּׁפּוּעַ הַנּוֹגֵעַ בּוֹ מִתּוֹכוֹ טָמֵא טֻמְאַת שִׁבְעָה וְהַנּוֹגֵעַ בַּשִּׁפּוּעַ מֵאַחֲרָיו טָמֵא טֻמְאַת עֶרֶב, נַעֲשָׂה הַשִּׁפּוּעַ מֵאַחֲרָיו כְּאִלּוּ הוּא כְּלִי שֶׁנָּגַע בָּאֹהֶל. הָיְתָה הַטֻּמְאָה עַל אֲחוֹרֵי הַשִּׁפּוּעַ הַנּוֹגֵעַ בּוֹ מֵאֲחוֹרָיו טָמֵא טֻמְאַת שִׁבְעָה וְהַנּוֹגֵעַ בַּשִּׁפּוּעַ בְּתוֹכוֹ טָמֵא טֻמְאַת עֶרֶב. כַּחֲצִי זַיִת מִתּוֹכוֹ וְכַחֲצִי זַיִת מֵאֲחוֹרָיו הַנּוֹגֵעַ בּוֹ בֵּין מִתּוֹכוֹ בֵּין מֵאֲחוֹרָיו טָמֵא טֻמְאַת עֶרֶב. וְהָאֹהֶל עַצְמוֹ טָמֵא טֻמְאַת שִׁבְעָה:","הָיָה כְּנַף הָאֹהֶל מְרֻדָּד עַל הָאָרֶץ וְטֻמְאָה תַּחַת כְּנַף הָאֹהֶל הַפָּרוּשׂ עַל הָאָרֶץ אוֹ עַל גַּבֵּי הַכָּנָף. טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת:"],"Mishneh Torah, Defilement by a Corpse 6":["עַצְמוֹת הַדָּג וְעוֹרוֹ הָעוֹשֶׂה מֵהֶן כֵּלִים אֵינָן מְקַבְּלִין טֻמְאָה כְּלָל לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים. וְכֵן יְרוֹקָה שֶׁעַל פְּנֵי הַמַּיִם וְכַיּוֹצֵא בָּהּ שֶׁכָּל מַה שֶּׁבַּיָּם טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת כֵּלִים. לְפִיכָךְ הָעוֹשֶׂה אֹהֶל מֵעוֹר הַדָּג אוֹ מִצֶּמֶר שֶׁגָּדֵל בַּיָּם. אֵין עַצְמוֹ שֶׁל אֹהֶל זֶה מְקַבֵּל טֻמְאָה אַף עַל פִּי שֶׁמֵּבִיא אֶת הַטֻּמְאָה לְכָל אֲשֶׁר יִהְיֶה תַּחְתָּיו כִּשְׁאָר אֹהָלִים:","כְּלֵי גְּלָלִים וּכְלֵי אֲבָנִים וּכְלֵי אֲדָמָה אֵינָן מְקַבְּלִין טֻמְאָה לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים בֵּין טֻמְאַת מֵת בֵּין שְׁאָר הַטֻּמְאוֹת. וְכֵן כְּלִי עֵץ הֶעָשׂוּי לְנַחַת כְּגוֹן הַתֵּבָה וְהַמִּגְדָּל וְהַכַּוֶּרֶת שֶׁהֵן מַחֲזִיקִין אַרְבָּעִים סְאָה בְּלַח וְיִהְיֶה לָהֶם שׁוּלַיִם אֵינָן מְקַבְּלִין טֻמְאָה כְּלָל לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים. וְאֵלּוּ הֵן הַנִּקְרָאִין כְּלִי עֵץ הַבָּא בְּמִדָּה:","כְּלֵי עֵץ פְּשׁוּטֵיהֶם טְהוֹרִים מְקַבְּלֵיהֶם טְמֵאִים. כְּלֵי חֶרֶשׂ פְּשׁוּטֵיהֶן טְהוֹרִין וּמְקַבְּלֵיהֶן טְמֵאִין וְאֵינָן טְמֵאִין אֶלָּא מֵאֲוִירָן אוֹ בְּהֶסֵּט הַזָּב. אֲפִלּוּ נָגַע כְּלִי חֶרֶשׂ בְּמֵת מִגַּבּוֹ אֵינוֹ מִתְטַמֵּא. וְאִם נִכְנְסָה טֻמְאָה מִן הַטֻּמְאוֹת בַּאֲוִירוֹ וְאַף עַל פִּי שֶׁלֹּא נָגְעָה בּוֹ נִטְמָא. הָיָה כְּלִי חֶרֶשׂ עִם הַמֵּת בְּאֹהֶל נִטְמָא שֶׁהֲרֵי הַטֻּמְאָה נִכְנְסָה בַּאֲוִירוֹ. וְאִם הָיָה מֻקָּף צָמִיד פָּתִיל הוּא וּמַה שֶּׁבְּתוֹכוֹ טָהוֹר כְּמוֹ שֶׁנִּתְפָּרֵשׁ בַּתּוֹרָה. שֶׁאֵין טֻמְאָה נִכְנְסָה לוֹ אֶלָּא מִפִּתְחוֹ וּבְהֶסֵּט הַזָּב. שֶׁהֲרֵי הוּא כְּמִי שֶׁנָּגַע בְּכֻלּוֹ:","הָעוֹשֶׂה גּוֹלֵל מִדָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה כְּגוֹן שֶׁהִנִּיחַ עַל גַּבֵּי הַקֶּבֶר אֶבֶן אוֹ כְּלִי אֲדָמָה אוֹ כְּלִי עֵץ הַבָּא בְּמִדָּה אוֹ כְּלִי חֶרֶשׂ הַמֻּקָּף צָמִיד פָּתִיל אוֹ עוֹר הַדָּג וְעַצְמוֹ וְכַיּוֹצֵא בְּאֵלּוּ הַנּוֹגֵעַ בָּהֶן טָמֵא טֻמְאַת שִׁבְעָה מִשּׁוּם נוֹגֵעַ בְּגוֹלֵל. וְאִם פֵּרְשׁוֹ מִלִּהְיוֹת גּוֹלֵל אוֹ שֶׁהֵסִיר אֶת הַמֵּת מִתַּחְתֵּיהֶן הֲרֵי הֵן טְהוֹרִין. וְכֵן בְּהֵמָה שֶׁכְּפָתָהּ וְעָשָׂה אוֹתָהּ גּוֹלֵל הַנּוֹגֵעַ בָּהּ טָמֵא טֻמְאַת שִׁבְעָה כָּל זְמַן שֶׁהִיא גּוֹלֵל. הִתִּיר הַבְּהֵמָה הֲרֵי הִיא טְהוֹרָה כִּשְׁאָר הַבְּהֵמוֹת. וְכֵן חָבִית שֶׁהִיא מְלֵאָה מַשְׁקִין מֻקֶּפֶת צָמִיד פָּתִיל וְעָשָׂה אוֹתָהּ גּוֹלֵל לְמֵת הַנּוֹגֵעַ בָּהּ טָמֵא טֻמְאַת שִׁבְעָה וְהֶחָבִית וְהַמַּשְׁקִין טְהוֹרִין:","קוֹרָה שֶׁעֲשָׂאָהּ גּוֹלֵל לְקֶבֶר בֵּין עוֹמֶדֶת בֵּין מֻטָּה עַל צִדָּה אֵין טָמֵא אֶלָּא כְּנֶגֶד פֶּתַח הַקֶּבֶר בִּלְבַד. וְהַנּוֹגֵעַ בַּקָּצֶה הַמֻּנָּח חוּץ לַקֶּבֶר טָהוֹר. עָשָׂה רֹאשָׁהּ גּוֹלֵל לְקֶבֶר וַהֲרֵי הִיא עוֹמֶדֶת עַל הַקֶּבֶר כְּמוֹ אִילָן הַנּוֹגֵעַ מִמֶּנָּה בְּאַרְבָּעָה טְפָחִים סָמוּךְ לַקֶּבֶר טָמֵא מִשּׁוּם גּוֹלֵל וּמֵאַרְבָּעָה וּלְמַעְלָה טָהוֹר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהוּא עָתִיד לָקֹץ אוֹתָהּ. אֲבָל אִם אֵינוֹ עָתִיד לָקֹץ אוֹתָהּ כֻּלָּהּ גּוֹלֵל:","שְׁתֵּי אֲבָנִים גְּדוֹלוֹת שֶׁל אַרְבָּעָה אַרְבָּעָה טְפָחִים שֶׁעֲשָׂאָן גּוֹלֵל הַמַּאֲהִיל עַל גַּבֵּי שְׁתֵּיהֶן טָמֵא. נִטְּלָה אַחַת מֵהֶן הַמַּאֲהִיל עַל גַּבֵּי שְׁנִיָּה טָהוֹר מִפְּנֵי שֶׁיֵּשׁ לַטֻּמְאָה דֶּרֶךְ שֶׁתֵּצֵא בּוֹ:","גַּל שֶׁל צְרוֹרוֹת שֶׁעֲשָׂאָהוּ גּוֹלֵל לְקֶבֶר אֵין טָמֵא אֶלָּא סֵדֶר הַפְּנִימִי שֶׁהוּא צָרְכּוֹ שֶׁל קֶבֶר. אֲבָל הַנּוֹגֵעַ בִּשְׁאָר הָאֲבָנִים טָהוֹר:","אָרוֹן שֶׁהוּא חָקוּק בַּסֶּלַע וְהִנִּיחוּ בּוֹ הַמֵּת וְכִסּוּהוּ בְּגוֹלֵל הַנּוֹגֵעַ בַּסֶּלַע בְּכָל מָקוֹם טָהוֹר וְהַנּוֹגֵעַ בַּגּוֹלֵל טָמֵא. לְמָה זֶה דּוֹמֶה לְבוֹר גָּדוֹל מָלֵא מֵתִים וְאֶבֶן גְּדוֹלָה עַל פִּיהָ שֶׁאֵין טָמֵא אֶלָּא כְּנֶגֶד חֲלָלָהּ. וְאִם בָּנָה נֶפֶשׁ עַל גַּבָּהּ הֲרֵי זוֹ כְּקֶבֶר סָתוּם וּמְטַמֵּא מִכָּל סְבִיבָיו. הָיְתָה הָאָרוֹן הַחֲקוּקָה בַּסֶּלַע רְחָבָה מִלְּמַטָּה וְצָרָה מִלְּמַעְלָה וְהַמֵּת בְּתוֹכָהּ הַנּוֹגֵעַ בָּהּ מִלְּמַטָּן טָהוֹר וּמִלְּמַעְלָן טָמֵא שֶׁהֲרֵי הַצְּדָדִין מִלְּמַעְלָה סָמְכוּ עַל גַּבֵּי הַמֵּת וְנַעֲשׂוּ כְּגוֹלֵל. הָיְתָה הָאָרוֹן רְחָבָה מִלְּמַעְלָה וְצָרָה מִלְּמַטָּה הַנּוֹגֵעַ בָּהּ מִכָּל מָקוֹם טָמֵא. הָיְתָה שָׁוָה הַנּוֹגֵעַ בָּהּ מִטֶּפַח הַסָּמוּךְ לְקַרְקָעִיתָהּ וּלְמַעְלָה טָמֵא מִטֶּפַח וּלְמַטָּה טָהוֹר. נִקֵּב אָרוֹן בַּסֶּלַע וְהִכְנִיס הַמֵּת בְּתוֹכָהּ כְּמוֹ נֶגֶר הַנּוֹגֵעַ בָּהּ מִכָּל מָקוֹם טָהוֹר חוּץ מִמְּקוֹם פִּתְחָהּ:","מְעָרָה שֶׁהַקֶּבֶר בְּתוֹכָהּ וְחָצֵר לִפְנֵי הַמְּעָרָה. בִּזְמַן שֶׁהֶחָצֵר לָאֲוִיר הָעוֹמֵד לְתוֹכָהּ טָהוֹר וּבִלְבַד שֶׁלֹּא יִגַּע בְּמַשְׁקוֹף הַמְּעָרָה. וּבִזְמַן שֶׁהֶחָצֵר מְקֹרָה אִם הָיָה בָּהּ [מְגֻלֶּה בְּצַד הַמְּעָרָה] אַרְבָּעָה טְפָחִים עַל אַרְבָּעָה טְפָחִים אוֹ יֶתֶר הַנִּכְנָס לְשָׁם טָהוֹר. הָיְתָה פְּחוּתָה מֵאַרְבָּעָה עַל אַרְבָּעָה הַנִּכְנָס לְשָׁם טָמֵא וְאַף עַל פִּי שֶׁלֹּא נָגַע בְּפֶתַח הַמְּעָרָה:"],"Mishneh Torah, Defilement of Foods 2":["כָּל הָאֳכָלִין הַגְּדֵלִין מִן הַקַּרְקַע אֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיֵּעָקְרוּ. אֲבָל כָּל זְמַן שֶׁהֵן מְחֻבָּרִין אֲפִלּוּ כְּשֹׁרֶשׁ קָטָן שֶׁיְּכוֹלִין לִחְיוֹת מִמֶּנּוּ אֵינָן מְקַבְּלִין טֻמְאָה:","יִחוּר שֶׁל תְּאֵנָה שֶׁנִּפְשַׁח וּמְעֹרֶה בִּקְלִפָּה שֶׁאֵינוֹ יָכוֹל לִחְיוֹת מִמֶּנָּה כָּל הָאֳכָלִין שֶׁבּוֹ מִתְטַמְּאִין. וְיֵשׁ בַּדָּבָר סָפֵק אִם הָיָה שְׁאָר הָאִילָן כְּמוֹ יָד לְזֶה הַיִּחוּר שֶׁנִּשְׁבַּר אוֹ לָאו:","יְרָקוֹת שֶׁיָּבְשׁוּ בְּאִבֵּיהֶן כְּגוֹן כְּרוּב וּדְלַעַת שֶׁיָּבְשׁוּ בְּאִבֵּיהֶן אֵינָן מִתְטַמְּאִין טֻמְאַת אֳכָלִין. לִקְּטָן לְיַבְּשָׁן הֲרֵי הֵן אֳכָלִין כְּשֶׁהָיוּ עַד שֶׁיִּיבְשׁוּ וְיֵעָשׂוּ כְּעֵץ:","אִילָן שֶׁנִּפְשַׁח וּבוֹ פֵּרוֹת הֲרֵי הֵן כִּתְלוּשִׁין. וְכֵן אִם יָבַשׁ הָאִילָן וּבוֹ פֵּרוֹת הֲרֵי הֵן כִּתְלוּשִׁין:","תְּאֵנִים שֶׁיָּבְשׁוּ בְּאִבֵּיהֶן מִטַּמְּאוֹת טֻמְאַת אֳכָלִין בִּמְקוֹמָן:","כָּל הָאֳכָלִין שֶׁהֵן מִבַּעֲלֵי חַיִּים אֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיָּמוּתוּ. שָׁחַט בְּהֵמָה חַיָּה וְעוֹף אַף עַל פִּי שֶׁעֲדַיִן הֵן מְפַרְכְּסִין מְקַבְּלִין טֻמְאָה. וְדָגִים מֵאֵימָתַי מְקַבְּלִין טֻמְאָה מִשֶּׁיָּמוּתוּ. נוֹלַד בָּהֶן טְרֵפָה וְנִתְטַמְּאוּ כְּשֶׁהֵן מִתְנַדְנְדִין הֲרֵי יֵשׁ בַּדָּבָר סָפֵק אִם הֵן חֲשׁוּבִין כְּמֵתִים הוֹאִיל וְנִטְרְפוּ אוֹ אֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיִּדְמוּ כְּאֶבֶן וְלֹא יִתְנַדְנְדוּ. הָאֵיבָר אוֹ הַבָּשָׂר הַמְדֻלְדָּלִין בִּבְהֵמָה אוֹ חַיָּה שֶׁאֵינָן יְכוֹלִין לִחְיוֹת אִם הֻכְשְׁרוּ מְקַבְּלִין טֻמְאָה בִּמְקוֹמָן מִפְּנֵי שֶׁהֵן חֲשׁוּבִין כְּאֹכֶל שֶׁפֵּרַשׁ. נִשְׁחֲטָה הַבְּהֵמָה הֻכְשְׁרוּ בִּשְׁחִיטָה. שֶׁהַבְּהֵמָה כֻּלָּהּ כְּמוֹ יָד לְאֵיבָר זֶה וְיָד שֶׁהֻכְשַׁר הֻכְשַׁר הָאֵיבָר כֻּלּוֹ כְּמוֹ שֶׁיִּתְבָּאֵר. וְיֵשׁ בַּדָּבָר סָפֵק אִם תִּהְיֶה הַבְּהֵמָה בְּחַיֶּיהָ כְּמוֹ יָד לָאֵיבָר אוֹ בָּשָׂר הַמְדֻלְדָּלִין בָּהּ:","הַשּׁוֹחֵט בְּהֵמָה חַיָּה וְעוֹף הֻכְשַׁר כָּל הַבָּשָׂר בַּדָּם שֶׁיָּצָא בַּשְּׁחִיטָה. לְפִיכָךְ אִם לֹא יָצָא מֵהֶן דָּם בַּשְּׁחִיטָה הֲרֵי כָּל בְּשָׂרָן צָרִיךְ הֶכְשֵׁר כְּכָל הָאֳכָלִין שֶׁלֹּא הֻכְשְׁרוּ:","אֳכָלִין שֶׁהֻכְשְׁרוּ כְּשֶׁהֵן מְחֻבָּרִין לַקַּרְקַע אוֹ שֶׁהֻכְשְׁרוּ בְּמַיִם הַמְחֻבָּרִים שֶׁבַּקַּרְקַע אֵינוֹ הֶכְשֵׁר עַד שֶׁיֻּכְשְׁרוּ אַחַר שֶׁנֶּעֶקְרוּ בַּמַּיִם הַתְּלוּשִׁין מִן הַקַּרְקַע אוֹ בִּשְׁאָר מַשְׁקִין שֶׁנֶּאֱמַר (ויקרא יא לד) \"בְכָל כְּלִי\" אֵינוֹ מַכְשִׁיר עַד שֶׁיִּתָּלֵשׁ מִן הַקַּרְקַע כְּעֵין הַמַּיִם שֶׁבַּכֵּלִים. שָׁאַב הַמַּיִם בִּכְלִי וּנְתָנָן בַּקַּרְקַע אֵינָן מַכְשִׁירִין:","קִּשּׁוּת שֶׁנְּטָעָהּ בֶּעָצִיץ וְהִגְדִּילָה אַף עַל פִּי שֶׁיָּצָאת חוּץ לֶעָצִיץ אֵינָהּ מְקַבֶּלֶת טֻמְאָה. וְעָצִיץ שֶׁהוּא נָקוּב כְּדֵי שֶׁיֵּצֵא בּוֹ שֹׁרֶשׁ קָטָן הֲרֵי הוּא כְּאֶרֶץ וְהַנָּטוּעַ בּוֹ אֵינוֹ מְקַבֵּל טֻמְאָה. וְכֵן אִם הָיוּ בּוֹ מַיִם אֵינָן מַכְשִׁירִין:","עָצִיץ שֶׁאֵינוֹ נָקוּב הֲרֵי הַנָּטוּעַ בּוֹ מְקַבֵּל טֻמְאָה. וְאִם הָיוּ מַיִם בְּתוֹכוֹ מַכְשִׁירִין:","כְּלֵי גְּלָלִים וּכְלֵי אֲדָמָה שֶׁהַשָּׁרָשִׁים יְכוֹלִין לִבְקֹעַ בָּהֶן וְלָצֵאת אֵינָן מַכְשִׁירִין אֶת הַזְּרָעִים. וְאַף עַל פִּי שֶׁאֵינָן נְקוּבִין הֲרֵי הֵן כִּנְקוּבִין:","עָצִיץ שֶׁמִּלְאָהוּ עָפָר עַד שְׂפָתוֹ אֵינוֹ חָשׁוּב כְּלִי אֶלָּא הֲרֵי הוּא כְּטַבְלָא שֶׁאֵין לָהּ שָׂפָה שֶׁאֵינוֹ כְּלִי קִבּוּל:","מַשְׁקִין טְמֵאִין שֶׁנָּפְלוּ עַל הָאֳכָלִין נִטְמְאוּ אַף עַל פִּי שֶׁנָּפְלוּ שֶׁלֹּא בִּרְצוֹן הַבְּעָלִים. שֶׁהֲרֵי הַטֻּמְאָה וְהַהֶכְשֵׁר בָּאִין כְּאַחַת. וְהוּא שֶׁלֹּא יִהְיוּ בַּקַּרְקַע:","כָּל אֹכֶל שֶׁנִּפְסַד וְנִסְרַח עַד שֶׁאֵינוֹ רָאוּי לְמַאֲכַל אָדָם אֵינוֹ מְקַבֵּל טֻמְאָה. וְכֵן מַשְׁקֶה שֶׁנִּסְרַח וְנִפְסַד וְאֵינוֹ רָאוּי לִשְׁתִיַּת אָדָם אֵינוֹ מְקַבֵּל טֻמְאָה כְּדֶרֶךְ שֶׁאֵינוֹ מַכְשִׁיר שֶׁנֶּאֱמַר (ויקרא יא לד) \"אֲשֶׁר יִשָּׁתֶה\":","הָעוֹר שֶׁשְּׁלָקוֹ וְהַשִּׁלְיָא שֶׁחָשַׁב עָלֶיהָ לַאֲכִילָה מִתְטַמְּאִין טֻמְאַת אֳכָלִים בִּפְנֵי עַצְמָן:","עוֹר הַחֲמוֹר שֶׁשְּׁלָקוֹ הֲרֵי זֶה סָפֵק אִם מִתְטַמֵּא טֻמְאַת אֳכָלִים בִּפְנֵי עַצְמוֹ מִפְּנֵי שֶׁשְּׁלָקוֹ אוֹ אֵינוֹ מִתְטַמֵּא מִפְּנֵי שֶׁהוּא מָאוּס הַרְבֵּה:","חִטִּים שֶׁבִּגְלָלֵי בָּקָר וּשְׂעוֹרִים שֶׁבִּגְלָלֵי הַבְּהֵמָה שֶׁלִּקְּטָן אֵין מְקַבְּלִין טֻמְאָה. וְאִם חָשַׁב עֲלֵיהֶן לַאֲכִילָה מִתְטַמְּאוֹת טֻמְאַת אֳכָלִין:","כָּל אֹכֶל שֶׁנִּטְמָא וְאַחַר שֶׁנִּטְמָא נִפְסַל וְנִסְרַח. אִם נִפְסַל מִלֶּאֱכל הַכֶּלֶב אוֹ שֶׁיָּבַשׁ כְּחֶרֶשׂ הֲרֵי זֶה טָהוֹר. וְאִם נִפְסַל מִלֶּאֱכל אָדָם וַעֲדַיִן הוּא רָאוּי לְכֶלֶב הֲרֵי זֶה טָמֵא כְּשֶׁהָיָה. וְכָל הָאֳכָלִין שֶׁנִּטְמְאוּ אֵין לָהֶן טָהֳרָה בְּמִקְוֶה:","זְרָעִים טְמֵאִים שֶׁזְּרָעָם הֲרֵי הַצּוֹמֵחַ מֵהֶן טָהוֹר. וַאֲפִלּוּ בְּדָבָר שֶׁאֵין זַרְעוֹ כָּלֶה. וְהוּא שֶׁהִשְׁרִישׁוּ. אֲבָל קֹדֶם הַשְׁרָשָׁה הֲרֵי הֵן בְּטֻמְאָתָן אֲפִלּוּ בְּדָבָר שֶׁזַּרְעוֹ כָּלֶה:","אֳכָלִין שֶׁמְּחֻבָּרִין לְכֵלִים בָּטְלוּ מִתּוֹרַת אֹכֶל. וְאִם נִטְמָא הַכְּלִי הֲרֵי הֵן מִתְטַמְּאִין בְּטֻמְאַת הַכְּלִי הוֹאִיל וְהֵן מְשַׁמְּשִׁין תַּשְׁמִישׁ עֵץ הֲרֵי הֵן כְּעֵץ:","כָּל מַשְׁקֶה שֶׁנִּטְמָא וְאַחַר שֶׁנִּטְמָא נִפְסַד וְנִסְרַח הֲרֵי זֶה בְּטֻמְאָתוֹ לְעוֹלָם שֶׁאֵין הַמַּשְׁקֶה יוֹצֵא עַל יְדֵי הַכֶּלֶב לְעוֹלָם. וְאֵין לְמַשְׁקֶה שֶׁנִּטְמָא טָהֳרָה חוּץ מִן הַמַּיִם בִּלְבַד שֶׁאִם הִטְבִּיל מַיִם טְמֵאִים בְּמִקְוֶה כֵּיוָן שֶׁצָּפוּ מֵי מִקְוֶה עֲלֵיהֶן טָהֲרוּ. וּמַטְבִּילִין חַמִּין בְּצוֹנֵן וְצוֹנֵן בְּחַמִּין וְרָעִים בְּיָפִים וְיָפִים בְּרָעִים:","מַקֵּל שֶׁהִיא מְלֵאָה מַשְׁקִין טְמֵאִים וְהִטְבִּיל מִקְּצָתָהּ בְּמִקְוֶה לֹא טָהֲרוּ הַמַּיִם שֶׁעַל מִקְּצָתָהּ עַד שֶׁיִּטְבּל אֶת כֻּלָּהּ:","שֶׁלֶג שֶׁנִּטְמָא וְהִשִּׁיק מִקְצָתוֹ לְמֵי מִקְוֶה הוֹאִיל וְטָהַר מִקְצָתוֹ טָהַר כֻּלּוֹ:","הַתֶּמֶד הַטָּמֵא בֵּין שֶׁנִּטְמָא אַחַר שֶׁתִּמְדּוֹ בֵּין שֶׁתִּמְדּוֹ בְּמַיִם טְמֵאִים עַד שֶׁלֹּא הֶחְמִיץ מַשִּׁיקוֹ בְּמִקְוֶה וְיִטְהַר שֶׁהֲרֵי הוּא כְּמַיִם. מִשֶּׁהֶחְמִיץ הֲרֵי הוּא כְּיַיִן וְאֵין לוֹ טָהֳרָה בְּמִקְוֶה:","קְדֵרָה שֶׁמִּלְאָהּ מַשְׁקִין כְּגוֹן דְּבַשׁ וְיַיִן וְכַיּוֹצֵא בָּהֶן וּנְתוּנָה בְּתוֹךְ הַמִּקְוֶה וּפָשַׁט הָרִאשׁוֹן לְטֻמְאָה אֶת יָדוֹ וְנָגַע בָּהּ הֲרֵי זֶה מְטַמֵּא אֶת הַמַּשְׁקִין אַף עַל פִּי שֶׁהִיא בְּתוֹךְ הַמִּקְוֶה וְנִטְמֵאת הַקְּדֵרָה מֵחֲמַת הַמַּשְׁקִין שֶׁבְּתוֹכָהּ אַף עַל פִּי שֶׁהִיא בְּתוֹךְ הַמִּקְוֶה. הָיְתָה מְלֵאָה מַיִם הַקְּדֵרָה טְהוֹרָה שֶׁאֵין הָרִאשׁוֹן מְטַמֵּא כְּלִי חֶרֶס לְעוֹלָם וְאֵין הַמַּיִם שֶׁבְּתוֹכָהּ טְמֵאִים מִפְּנֵי שֶׁהֵן מְעֹרָבִים בְּמֵי הַמִּקְוֶה. פָּשַׁט אַב הַטֻּמְאָה אֶת יָדוֹ וְנָגַע בָּהּ נִטְמֵאת הַקְּדֵרָה שֶׁאֵין הַמִּקְוֶה מְטַהֵר כְּלֵי חֶרֶס:","מֵי שְׁפִיכוֹת הֲרֵי הֵן בְּחֶזְקַת טֻמְאָה. יָרְדוּ עֲלֵיהֶן מֵי גְּשָׁמִים אִם רַבּוּ עֲלֵיהֶן הֲרֵי הֵן טְהוֹרִים. מֶחֱצָה לְמֶחֱצָה הַכּל טָמֵא בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת. אֵימָתַי בִּזְמַן שֶׁקָּדְמוּ מֵי שְׁפִיכָה אֲבָל קָדְמוּ מֵי גְּשָׁמִים וְיָרְדוּ עֲלֵיהֶן כָּל שֶׁהוּא מִמֵּי שְׁפִיכוֹת הַכּל טָמֵא שֶׁמַּשְׁקִין טְמֵאִין שֶׁיָּרְדוּ לִטְהוֹרִים מְטַמְּאִין בְּכָל שֶׁהוּא:","הַטּוֹרֵף אֶת גַּגּוֹ וְהַמְכַבֵּס אֶת כְּסוּתוֹ וַהֲרֵי הֵן מְנַטְּפִים יָרְדוּ עֲלֵיהֶן גְּשָׁמִים וְרַבּוּ הַנְּטִיפוֹת הֲרֵי רַבּוּ מֵי גְּשָׁמִים עֲלֵיהֶן וְהַנּוֹטְפִים מֵהֶן טְהוֹרִין:","הַסָּךְ שֶׁמֶן טָהוֹר וְנִטְמָא זֶה הָאָדָם וְטָבַל וַהֲרֵי הַשֶּׁמֶן עַל בְּשָׂרוֹ אִם הָיָה כְּדֵי סִיכַת אֵיבָר קָטָן הֲרֵי הוּא טָהוֹר כְּשֶׁהָיָה מִקֹּדֶם. סָךְ שֶׁמֶן טָמֵא וְטָבַל לֹא טָהַר הַשֶּׁמֶן שֶׁעָלָיו אֶלָּא אִם נִשְׁאַר מִמֶּנּוּ מַשְׁקֶה טוֹפֵחַ הֲרֵי הַשֶּׁמֶן בְּטֻמְאָתוֹ וְאִם לֹא נִשְׁאַר מִמֶּנּוּ כְּדֵי לְהַטְפִּיחַ מִמֶּנּוּ בָּטֵל בְּמִעוּטוֹ:"],"Mishneh Torah, Diverse Species 4":["מֻתָּר לִזְרֹעַ שְׁתֵּי שׁוּרוֹת זוֹ בְּצַד זוֹ שֶׁל קִשּׁוּאִין וּשְׁתֵּי שׁוּרוֹת בְּצִדָּן שֶׁל דְּלוּעִין. וּשְׁתֵּי שׁוּרוֹת שֶׁל פּוֹל הַמִּצְרִי. וְתֶלֶם בֵּין כָּל מִין וָמִין. אֲבָל לֹא יִזְרַע שׁוּרָה אַחַת שֶׁל קִשּׁוּאִין וְשׁוּרָה אַחַת שֶׁל דְּלוּעִין וְשׁוּרָה אַחַת שֶׁל פּוֹל הַמִּצְרִי אַף עַל פִּי שֶׁהַתֶּלֶם מַבְדִּיל בֵּין כָּל מִין וָמִין מִפְּנֵי שֶׁמִּינִין אֵלּוּ עָלִים שֶׁלָּהֶן אֲרֻכִּין וְנִמְשָׁכִין וּמִסְתַּבְּכִין. וְאִם זְרָעָן שׁוּרָה בְּצַד שׁוּרָה יִתְעָרֵב הַכּל וְנִרְאוּ כְּנִזְרָעִין בְּעִרְבּוּבְיָא:","הָיְתָה שָׂדֵהוּ זְרוּעָה מִין מִמִּינֵי יְרָקוֹת וּבִקֵּשׁ לִזְרֹעַ בְּתוֹכָהּ שׁוּרוֹת שׁוּרוֹת שֶׁל דְּלוּעִין עוֹקֵר מִן הַיָּרָק מָקוֹם שֶׁזּוֹרֵעַ בּוֹ שׁוּרָה שֶׁל דְּלוּעִין וּמַבְדִּיל בֵּינָהּ וּבֵין הַיָּרָק בְּתֶלֶם וּמַנִּיחַ מִן הַיָּרָק רֹחַב שְׁתֵּים עֶשְׂרֵה אַמָּה וְעוֹשֶׂה שׁוּרָה שְׁנִיָּה שֶׁל דְּלוּעִין וּמַבְדִּיל בֵּינָהּ וּבֵין הַיָּרָק בְּתֶלֶם. וְכֵן עַד מָקוֹם שֶׁיִּרְצֶה. שֶׁנִּמְצָא בֵּין כָּל שְׁתֵּי שׁוּרוֹת שֶׁל דְּלוּעִין שְׁתֵּים עֶשְׂרֵה אַמָּה. אֲבָל פָּחוֹת מִיכַּן אָסוּר מִפְּנֵי הֶעָלִין שֶׁמִּסְתַּבְּכִין מִיכַּן וּמִיכַּן בַּיָּרָק שֶׁבֵּינֵיהֶם וְנִרְאֶה הַכּל כְּאִלּוּ נִזְרַע בְּעִרְבּוּבְיָא:","הָיְתָה שׁוּרָה שֶׁל דְּלַעַת זְרוּעָה אֲפִלּוּ דְּלַעַת יְחִידִית וּבָא לִזְרֹעַ בְּצִדָּהּ תְּבוּאָה. מַרְחִיק בֵּית רֹבַע. שֶׁהֲרֵי נִמְשְׁכוּ עָלֶיהָ וְהֶחֱזִיקָה מָקוֹם גָּדוֹל. וְכָל דָּבָר שֶׁיִּהְיֶה בְּתוֹךְ בֵּית רֹבַע שֶׁמַּרְחִיקִין בֵּין שְׁנֵי הַמִּינִין עוֹלֶה מִן הַמִּדָּה כְּגוֹן הַקֶּבֶר וְהַסֶּלַע וְכַיּוֹצֵא בָּהֶן:","הַתֶּלֶם אוֹ אַמַּת הַמַּיִם שֶׁהֵן עֲמֻקִּים טֶפַח זוֹרְעִין לְתוֹכוֹ שְׁלֹשָׁה מִינֵי זְרָעִים אֶחָד עַל שְׂפַת הַתֶּלֶם מִיכַּן וְאֶחָד מִיכַּן וְאֶחָד בָּאֶמְצַע:","וּמֻתָּר לִנְטֹעַ שְׁנֵי מִינִין בְּתוֹךְ גֻּמָּא אַחַת. וַאֲפִלּוּ קִישׁוּת וּדְלַעַת. וְהוּא שֶׁיִּהְיֶה מִין זֶה נוֹטֶה מֵעַל שְׂפַת הַגֻּמָּא לְכָאן וְהַמִּין הָאַחֵר נוֹטֶה לַצַּד הַשֵּׁנִי וְיֵרָאוּ נִבְדָּלִין זֶה מִזֶּה. וְכֵן אִם נָטַע אַרְבָּעָה מִינִין בְּתוֹךְ הַגֻּמָּא וַהֲפָכָן לְאַרְבַּע רוּחוֹתֶיהָ הֲרֵי זֶה מֻתָּר:","הָרוֹצֶה לִזְרֹעַ שָׂדֵהוּ מֵשַּׁר מֵשַּׁר מִכָּל מִין וָמִין מַרְחִיק בֵּין כָּל מֵשַּׁר וּמֵשַּׁר שְׁתֵּי אַמּוֹת עַל שְׁתֵּי אַמּוֹת וּמֵצֵר וְהוֹלֵךְ עַד שֶׁלֹּא יִשָּׁאֵר בֵּינֵיהֶן בְּסוֹף הַמֵשַּׁר אֶלָּא כָּל שֶׁהוּא. שֶׁהֲרֵי הֵן נִרְאִין שֶׁלֹּא נִזְרְעוּ בְּעִרְבּוּבְיָא:","רָצָה לַעֲשׂוֹת שָׂדֵהוּ קָרַחַת קָרַחַת מִכָּל מִין וָמִין לֹא יַעֲשֶׂה בְּתוֹךְ כָּל בֵּית סְאָה יֶתֶר עַל תֵּשַׁע קָרָחוֹת כָּל קָרַחַת מֵהֶן בֵּית רֹבַע וְנִמְצָא רָחוֹק בֵּין קָרַחַת וְקָרַחַת קָרוֹב לְעֶשֶׂר אַמּוֹת פָּחוֹת רְבִיעַ. שֶׁכָּל בֵּית סְאָה חֲמִשִּׁים עַל חֲמִשִּׁים:","וּמַה בֵּין הַמֵשַּׁר לַקָּרַחַת שֶׁהַמֵשַּׁר אָרֹךְ וְהַקָּרַחַת מְרֻבַּעַת:","מִינֵי יְרָקוֹת שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶם אֶלָּא מְעַט מְעַט כְּמוֹ שֶׁבֵּאַרְנוּ מֻתָּר לִזְרֹעַ מֵהֶם אֲפִלּוּ חֲמִשָּׁה מִינִין בְּתוֹךְ עֲרוּגָה אַחַת שֶׁהִיא שִׁשָּׁה טְפָחִים עַל שִׁשָּׁה טְפָחִים. וְהוּא שֶׁיִּזְרַע אַרְבָּעָה מִינִין בְּאַרְבַּע רוּחוֹת הָעֲרוּגָה וְאֶחָד בָּאֶמְצַע. וְיַרְחִיק בֵּין כָּל מִין וָמִין כְּמוֹ טֶפַח וּמֶחֱצָה כְּדֵי שֶׁלֹּא יִינְקוּ זֶה מִזֶּה. אֲבָל יוֹתֵר עַל חֲמִשָּׁה מִינִין לֹא יִזְרַע אַף עַל פִּי שֶׁמְּרַחֵק בֵּינֵיהֶם לְפִי שֶׁמִּינִין הַרְבֵּה בַּעֲרוּגָה כָּזוֹ הֲרֵי הֵן כִּנְטוּעִין בְּעִרְבּוּבְיָא:","בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲרוּגָה שֶׁהִיא בְּחֻרְבָּה וְאֵין שָׁם זֶרַע חוּצָה לָהּ. אֲבָל עֲרוּגָה בֵּין עֲרוּגוֹת אָסוּר לִזְרֹעַ בָּהּ חֲמִשָּׁה מִינִין. שֶׁאִם יִזְרַע בְּכָל רוּחַ מֵעֲרוּגָה זוֹ וּבְכָל רוּחַ מֵעֲרוּגוֹתֶיהָ שֶׁסְּבִיבוֹתֶיהָ יֵרָאֶה הַכּל כִּמְעֹרָב. וְאִם הִטָּה עָלִין שֶׁבַּעֲרוּגָה זוֹ לְכָאן וְעָלִין שֶׁבַּעֲרוּגָה שֶׁבְּצִדָּהּ מִכָּאן עַד שֶׁיֵּרָאוּ מֻבְדָּלִים מֻתָּר. וְכֵן אִם עָשָׂה תֶּלֶם בֵּין כָּל עֲרוּגָה וַעֲרוּגָה מֻתָּר:","וְאָסוּר לִזְרֹעַ חוּץ לַעֲרוּגָה בְּלֹא תֶּלֶם וּבְלֹא נְטִיָּה וַאֲפִלּוּ כְּנֶגֶד הַקְּרָנוֹת שֶׁל עֲרוּגָה שֶׁאֵין בָּהֶן זֶרַע. גְּזֵרָה שֶׁמָּא יִזְרַע אַרְבַּעַת הַמִּינִין בְּאַרְבַּע זָוִיּוֹת עֲרוּגָה וְיִזְרַע מִינִין אֲחֵרִים חוּצָה לָהּ כְּנֶגֶד הַזָּוִיּוֹת וְנִמְצָא הַכּל כִּמְעֹרָב:","הָיְתָה הָעֲרוּגָה שִׁשָּׁה עַל שִׁשָּׁה וְהָיָה לָהּ גְּבוּל גָּבוֹהַּ טֶפַח וְרָחָב טֶפַח סָבִיב מֻתָּר לִזְרֹעַ בָּהּ אֲפִלּוּ שְׁמוֹנָה עָשָׂר מִינִין שְׁלֹשָׁה עַל כָּל גְּבוּל וּגְבוּל וְשִׁשָּׁה בָּאֶמְצַע. וְיַרְחִיק בֵּין כָּל מִין וָמִין טֶפַח וּמֶחֱצָה. וְלֹא יִזְרַע רֹאשׁ הַלֶּפֶת בְּתוֹךְ הַגְּבוּל שֶׁמָּא יְמַלְּאֵהוּ. יוֹתֵר עַל זֶה לֹא יִזְרַע:","וְאָסוּר לִזְרֹעַ בַּעֲרוּגָה מִינֵי זְרָעִים בְּעִנְיָן זֶה מִפְּנֵי שֶׁהֵן נִרְאִין כִּלְאַיִם. אֲבָל מִינֵי יְרָקוֹת הוֹאִיל וְאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶן אֶלָּא מְעַט מְעַט הֲרֵי זֶה מֻתָּר כְּמוֹ שֶׁבֵּאַרְנוּ:","גְּבוּל שֶׁהָיָה גָּבוֹהַּ טֶפַח וְזָרְעוּ בּוֹ מִינִין הַרְבֵּה כְּמוֹ שֶׁבֵּאַרְנוּ וְנִתְמַעֵט מִטֶּפַח מֵאַחַר שֶׁנִּזְרַע בּוֹ כָּשֵׁר שֶׁהָיָה כָּשֵׁר מִתְּחִלָּתוֹ:","הָרוֹצֶה לְמַלְּאוֹת כָּל גִּנָּתוֹ מִינֵי יְרָקוֹת רַבִּים וְלֹא יַרְחִיק בֵּינֵיהֶם עוֹשֶׂה כָּל הַגִּנָּה עֲרוּגוֹת מְרֻבָּעוֹת אֲפִלּוּ שִׁשָּׁה עַל שִׁשָּׁה. וְעוֹשֶׂה בְּכָל עֲרוּגָה חֲמִשָּׁה עִגּוּלִין. אַרְבָּעָה בְּאַרְבַּע רוּחוֹתֶיהָ וְאֶחָד בְּאֶמְצַע. וְזוֹרֵעַ מִין בְּכָל עִגּוּל וְזוֹרֵעַ אַרְבָּעָה מִינִים אֲחֵרִים בְּאַרְבָּעָה קַרְנוֹת עֲרוּגָה. נִמְצְאוּ תִּשְׁעָה מִינִין בְּכָל עֲרוּגָה וְהֵן נִרְאִין מֻבְדָּלִין זֶה מִזֶּה וְאֵינוֹ מַפְסִיד אֶלָּא מַה שֶּׁבֵּין הָעִגּוּלִין בִּלְבַד שֶׁהוּא מַנִּיחוֹ חָרֵב כְּדֵי שֶׁיֵּרָאוּ הָעִגּוּלִין מֻבְדָּלִין מִן הַקְּרָנוֹת וּמֻבְדָּלִין זֶה מִזֶּה. וְאִם רָצָה שֶׁלֹּא יַפְסִיד כְּלוּם אִם הָיוּ הָעִגּוּלִין זְרוּעִים שְׁתִי זוֹרֵעַ מַה שֶּׁבֵּינֵיהֶן עֵרֶב וְאִם הָיוּ זְרוּעִין עֵרֶב זוֹרֵעַ מַה שֶּׁבֵּינֵיהֶן שְׁתִי כְּדֵי שֶׁיֵּרָאוּ מֻבְדָּלִין:","מִכָּל אֵלּוּ הַדְּבָרִים נִתְבָּאֵר לְךָ שֶׁבִּזְמַן שֶׁיֵּשׁ בֵּין שְׁנֵי הַמִּינִין הַרְחָקָה הָרְאוּיָה לָהֶם כְּדֵי שֶׁלֹּא יִינְקוּ זֶה מִזֶּה אֵין חוֹשְׁשִׁין לְמַרְאִית הָעַיִן כְּמוֹ שֶׁבֵּאַרְנוּ. וּבִזְמַן שֶׁיֵּרָאוּ מֻבְדָּלִים זֶה מִזֶּה אֵין חוֹשְׁשִׁים לִינִיקָתָן אֲפִלּוּ הֵן זֶה בְּצַד זֶה כְּמוֹ שֶׁנִּתְבָּאֵר עַתָּה:"],"Mishneh Torah, Divorce 3":["כָּל גֵּט שֶׁלֹּא נִכְתַּב לְשֵׁם הָאִישׁ הַמְגָרֵשׁ וּלְשֵׁם הָאִשָּׁה הַמִּתְגָּרֶשֶׁת אֵינוֹ גֵּט. כֵּיצַד. סוֹפֵר שֶׁכָּתַב גֵּט לְלַמֵּד אוֹ לְהִתְלַמֵּד וּבָא הַבַּעַל וּמָצָא שֵׁם שֶׁנִּכְתַּב בְּגֵט זֶה כִּשְׁמוֹ וְשֵׁם הָאִשָּׁה כְּשֵׁם אִשְׁתּוֹ וְשֵׁם הָעִיר כְּשֵׁם עִירוֹ וּנְטָלוֹ וְגֵרֵשׁ בּוֹ אֵינוֹ גֵּט:","יֶתֶר עַל זֶה כָּתַב לְגָרֵשׁ אֵת אִשְׁתּוֹ וְנִמְלַךְ וּמָצָא בֶּן עִירוֹ וְאָמַר לוֹ שְׁמִי כְּשִׁמְךָ וְשֵׁם אִשְׁתִּי כְּשֵׁם אִשְׁתְּךָ וּנְטָלוֹ מִמֶּנּוּ וְגֵרֵשׁ בּוֹ אַף עַל פִּי שֶׁנִּכְתַּב לְשֵׁם גֵּרוּשִׁין אֵינוֹ גֵּט:","יֶתֶר עַל זֶה מִי שֶׁיֵּשׁ לוֹ שְׁתֵּי נָשִׁים שֶׁשְּׁמוֹתֵיהֶן שָׁווֹת וְכָתַב לְגָרֵשׁ אֶת הַגְּדוֹלָה וְנִמְלַךְ וְגֵרֵשׁ בּוֹ אֶת הַקְּטַנָּה אֵינוֹ גֵּט. אַף עַל פִּי שֶׁנִּכְתַּב לְשֵׁם הָאִישׁ הַמְגָרֵשׁ לֹא נִכְתַּב לְשֵׁם זוֹ שֶׁנִּתְגָּרְשָׁה בּוֹ:","יֶתֶר עַל כֵּן אָמַר לְסוֹפֵר כְּתֹב וְאֵי זוֹ שֶׁאֶרְצֶה אֲגָרֵשׁ בּוֹ וְכָתַב הַסּוֹפֵר עַל דַּעַת זוֹ וְגֵרֵשׁ בּוֹ אַחַת מֵהֶן הֲרֵי זֶה סָפֵק גֵּרוּשִׁין. וְכָל גֵּט שֶׁכְּתָבוֹ שֶׁלֹּא לִשְׁמָהּ אַף עַל פִּי שֶׁהֶעֱבִיר עָלָיו קֻלְמוֹס לִשְׁמָהּ אֵינוֹ גֵּט:","מִי שֶׁכָּתַב [גֵּט] לְגָרֵשׁ אֶת אִשְׁתּוֹ וְנִמְלַךְ וְלֹא גֵּרְשָׁהּ וְנִתְיַחֵד עִמָּהּ אַחַר שֶׁכְּתָבוֹ לֹא יְגָרְשֶׁנָהּ בְּאוֹתוֹ הַגֵּט פַּעַם אַחֶרֶת כְּשֶׁיִּרְצֶה לְגָרְשָׁהּ. וְאִם גֵּרְשָׁהּ בְּאוֹתוֹ הַגֵּט הַיָּשָׁן הֲרֵי זוֹ מְגֹרֶשֶׁת וְתִנָּשֵׂא בּוֹ לְכַתְּחִלָּה שֶׁהֲרֵי נִכְתַּב לִשְׁמָהּ וַהֲרֵי נָתַן לָהּ עַתָּה בְּעֵדִים כְּהִלְכָתוֹ. וְלָמָּה לֹא יְגָרְשֶׁנָהּ בּוֹ לְכַתְּחִלָּה גְּזֵרָה שֶׁמָּא יֹאמְרוּ גִּטָּהּ קוֹדֵם לִבְנָהּ:","אָמַר לְסוֹפֵר כְּתֹב גֵּט לִפְלוֹנִית וְיִהְיֶה עִמִּי לִכְשֶׁאֶשָּׂאֶנָּה אֲגָרְשֶׁנָּה בּוֹ וְנִכְתַּב וּנְשָׂאָהּ וְגֵרְשָׁהּ בּוֹ אֵינוֹ גֵּט. מִפְּנֵי שֶׁלֹּא הָיְתָה בַּת גֵּרוּשִׁין מִמֶּנּוּ כְּשֶׁנִּכְתַּב גֵּט זֶה וְנִמְצָא שֶׁנִּכְתַּב שֶׁלֹּא לְשֵׁם גֵּרוּשִׁין. אֲבָל אִם אָמַר לוֹ כְּתֹב אוֹתוֹ לַאֲרוּסָתִי לִכְשֶׁאֶשָּׂאֶנָּה אֲגָרְשֶׁנָּה וּכְנָסָהּ וְגֵרְשָׁהּ בּוֹ כָּשֵׁר. כְּתָבוֹ לִיבִמְתּוֹ וְאַחַר שֶׁיִּבְּמָהּ גֵּרְשָׁהּ בּוֹ הֲרֵי זֶה סְפֵק גֵּרוּשִׁין הוֹאִיל וְאֵינָהּ אִשְׁתּוֹ גְּמוּרָה כְּשֶׁכְּתָבוֹ:","מִפְּנֵי תַּקָּנַת סוֹפֵר הִתִּירוּ חֲכָמִים לְסוֹפֵר שֶׁיִּכְתֹּב טָפְסֵי גִּטִּין וְיַנִּיחַ מְקוֹם הָאִישׁ וּמְקוֹם הָאִשָּׁה וּמְקוֹם הַזְּמַן וּמְקוֹם הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם כְּדֵי שֶׁיִּכְתְּבֵם לְשֵׁם הָאִישׁ הַמְגָרֵשׁ וּלְשֵׁם הָאִשָּׁה הַמִּתְגָּרֶשֶׁת וְאַחַר כָּךְ יַחְתְּמוּ הָעֵדִים לִשְׁמוֹ וְלִשְׁמָהּ:","סוֹפֵר שֶׁכָּתַב הַגֵּט לִשְׁמוֹ וְלִשְׁמָהּ כְּהִלְכָתוֹ וְחָתְמוּ הָעֵדִים שֶׁלֹּא לִשְׁמָהּ הוֹאִיל וּמְסָרוּ לָהּ בְּעֵדִים הֲרֵי זֶה גֵּט. (אֶלָּא שֶׁהוּא פָּסוּל. וְלָמָּה אֵינוֹ בָּטֵל) לְפִי שֶׁאֵין הָעֵדִים חוֹתְמִין עַל הַגֵּט אֶלָּא מִפְּנֵי תִּקּוּן הָעוֹלָם. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם חָתְמוּ הָעֵדִים שֶׁלֹּא לִשְׁמָהּ הוֹאִיל וְהוּא כִּמְזֻיָּף מִתּוֹכוֹ הֲרֵי זֶה גֵּט בָּטֵל. וְכֵן אִם הָיָה אֶחָד מֵעֵדָיו פָּסוּל אוֹ שֶׁהָיָה בּוֹ עֵד אֶחָד בִּלְבַד כָּשֵׁר. אַף עַל פִּי שֶׁנִּמְסַר בְּעֵדִים הֲרֵי זֶה גֵּט בָּטֵל. וְלֹא יֵרָאֶה לִי דָּבָר זֶה אֶלָּא כִּמְזֻיָּף לֹא מְזֻיָּף וַדַּאי וְהוֹאִיל וְנִמְסַר בְּעֵדֵי מְסִירָה כְּשֵׁרִין הֲרֵי זֶה פָּסוּל מִדִּבְרֵיהֶם:","הַמֵּבִיא גֵּט וְאָבַד מִמֶּנּוּ וּמְצָאוֹ. אִם אָבַד מִמֶּנּוּ בְּמָקוֹם שֶׁאֵין הַשַּׁיָּרוֹת מְצוּיוֹת אֲפִלּוּ מְצָאוֹ לְאַחַר זְמַן מְרֻבֶּה הֲרֵי זֶה בְּחֶזְקַת שֶׁהַגֵּט שֶׁאָבַד מִמֶּנּוּ הוּא הַגֵּט שֶׁנִּמְצָא וְתִתְגָּרֵשׁ בּוֹ. אָבַד בְּמָקוֹם שֶׁהַשַּׁיָּרוֹת מְצוּיוֹת אִם מְצָאוֹ מִיָּד וַעֲדַיִן לֹא שָׁהָה אָדָם שָׁם מִן הָעוֹבְרִים אוֹ שֶׁמְּצָאוֹ בַּכְּלִי שֶׁהִנִּיחוֹ בּוֹ וְיֵשׁ לוֹ טְבִיעוּת עַיִן בְּאָרְכּוֹ וְרָחְבּוֹ שֶׁל גֵּט שֶׁהָיָה כָּרוּךְ הֲרֵי הוּא בְּחֶזְקָתוֹ וְתִתְגָּרֵשׁ בּוֹ:","הֻחְזַק בְּאוֹתוֹ הַמָּקוֹם אִישׁ אֶחָד שֶׁשְּׁמוֹ כִּשְׁמוֹ שֶׁבַּגֵּט חוֹשְׁשִׁים שֶׁמָּא גֵּט זֶה הַנִּמְצָא שֶׁל אוֹתוֹ הָאִישׁ הָאַחֵר הוּא הוֹאִיל וְעָבַר אָדָם שָׁם וְאַף עַל פִּי שֶׁלֹּא שָׁהָה. וְאִם נִתְגָּרְשָׁה בּוֹ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. אֲבָל אִם לֹא עָבַר אָדָם שָׁם הֲרֵי זֶה בְּחֶזְקָתוֹ אַף עַל פִּי שֶׁהֻחְזְקוּ שָׁם שְׁנַיִם שֶׁשְּׁמוֹתֵיהֶן שָׁוִין:","הָיָה לָעֵדִים בַּגֵּט סִימָן מֻבְהָק כְּגוֹן שֶׁאָמְרוּ נֶקֶב יֵשׁ בּוֹ בְּצַד אוֹת פְּלוֹנִית. אוֹ שֶׁאָמְרוּ מֵעוֹלָם לֹא חָתַמְנוּ אֶלָּא עַל גֵּט אֶחָד שֶׁיֵּשׁ בּוֹ שֵׁמוֹת כְּשֵׁמוֹת אֵלּוּ הֲרֵי זֶה בְּחֶזְקָתוֹ וְתִתְגָּרֵשׁ בּוֹ וְאַף עַל פִּי שֶׁמְּצָאוֹ אַחַר זְמַן מְרֻבֶּה וּבְמָקוֹם שֶׁהַשַּׁיָּרוֹת מְצוּיוֹת וְהֻחְזְקוּ שָׁם שְׁנַיִם שֶׁשְּׁמוֹתֵיהֶן שָׁוִין:","שְׁנַיִם שֶׁשָּׁלְחוּ שְׁנֵי גִּטִּין וְנִתְעָרְבוּ נוֹתְנִין שְׁנֵיהֶן לָזוֹ וּשְׁנֵיהֶן לָזוֹ בְּעֵדֵי מְסִירָה. לְפִיכָךְ אִם אָבַד אֶחָד מֵהֶן הֲרֵי הַשֵּׁנִי בָּטֵל:","מִי שֶׁהָיוּ לוֹ שְׁנֵי שֵׁמוֹת. וְכֵן אִשָּׁה שֶׁיֵּשׁ לָהּ שְׁנֵי שֵׁמוֹת. כְּשֶׁמְּגָרֵשׁ כּוֹתֵב שְׁמוֹ וּשְׁמָהּ שֶׁהֵן רְגִילִין בּוֹ וִידוּעִין בּוֹ בְּיוֹתֵר וְאוֹמֵר אִישׁ פְּלוֹנִי וְכָל שֵׁם שֶׁיֵּשׁ לוֹ גֵּרֵשׁ אִשָּׁה פְּלוֹנִית וְכָל שֵׁם שֶׁיֵּשׁ לָהּ. וְאִם כָּתַב חֲנִיכָתוֹ וַחֲנִיכָתָהּ כָּשֵׁר:","כָּתַב הַשֵּׁם שֶׁאֵינָם יְדוּעִים בּוֹ בְּיוֹתֵר וְכָתַב כָּל שֵׁם שֶׁיֵּשׁ לוֹ הֲרֵי זֶה פָּסוּל. שִׁנָּה שְׁמוֹ אוֹ שְׁמָהּ וְשֵׁם עִירוֹ אוֹ שֵׁם עִירָהּ אַף עַל פִּי שֶׁכָּתַב כָּל שֵׁם שֶׁיֵּשׁ לוֹ וְכָל שֵׁם שֶׁיֵּשׁ לָהּ אֵינוֹ גֵּט:","הַכּל כְּשֵׁרִין לִכְתֹּב אֶת הַגֵּט חוּץ מֵחֲמִשָּׁה. עַכּוּ\"ם וְעֶבֶד וְחֵרֵשׁ וְשׁוֹטֶה וְקָטָן. אֲפִלּוּ אִשָּׁה עַצְמָהּ כּוֹתֶבֶת אֶת גִּטָּהּ. יִשְׂרָאֵל שֶׁהֵמִיר לְעַכּוּ\"ם אוֹ שֶׁהוּא מְחַלֵּל שַׁבָּתוֹת בְּפַרְהֶסְיָא הֲרֵי הוּא כְּעַכּוּ\"ם לְכָל דְּבָרָיו:","וְלָמָּה אֵין כּוֹתְבִין אֵלּוּ הַחֲמִשָּׁה מִפְּנֵי שֶׁצָּרִיךְ הַכּוֹתֵב לִכְתֹּב לְשֵׁם הָאִישׁ הַמְגָרֵשׁ וּלְשֵׁם הָאִשָּׁה הַמִּתְגָּרֶשֶׁת וְהָעַכּוּ\"ם עַל דַּעַת עַצְמוֹ הוּא כּוֹתֵב. וְחֵרֵשׁ שׁוֹטֶה וְקָטָן אֵינָן בְּנֵי דֵּעָה. וְהָעֶבֶד אֵינוֹ בְּתוֹרַת גִּטִּין וְקִדּוּשִׁין לְפִיכָךְ הוּא פָּסוּל כְּעַכּוּ\"ם לְכָל דְּבָרָיו. וְאִם כָּתַב הַגֵּט אֶחָד מֵחֲמִשָּׁה אֵלּוּ אֵינוֹ גֵּט אַף עַל פִּי שֶׁחָתְמוּ בּוֹ עֵדִים כְּשֵׁרִים וְנִמְסַר לָהּ בִּכְשֵׁרִים:","כָּתַב אֶחָד מֵחֲמִשָּׁה אֵלּוּ טֹפֶס הַגֵּט וְהִנִּיחַ מָקוֹם הַתֹּרֶף שֶׁהוּא מְקוֹם הָאִישׁ וּמְקוֹם הָאִשָּׁה וּמְקוֹם הַזְּמַן וּמְקוֹם הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם וּכְתָבָן הַפִּקֵּחַ הַגָּדוֹל הַיִּשְׂרְאֵלִי לִשְׁמוֹ הֲרֵי זֶה גֵּט כָּשֵׁר:","מֻתָּר לְהָנִיחַ חֵרֵשׁ שׁוֹטֶה וְקָטָן לִכְתֹּב טֹפֶס הַגֵּט לְכַתְּחִלָּה וְהוּא שֶׁיִּהְיֶה גָּדוֹל הַפִּקֵּחַ עוֹמֵד עַל גַּבָּן. אֲבָל הָעַכּוּ\"ם וְהָעֶבֶד אֵין כּוֹתְבִין הַטֹּפֶס לְכַתְּחִלָּה וַאֲפִלּוּ יִשְׂרָאֵל עוֹמֵד עַל גַּבָּן שֶׁלֹּא הִתִּירוּ לִכְתֹּב טָפְסֵי גִּטִּין שֶׁלֹּא לִשְׁמָהּ לְכַתְּחִלָּה אֶלָּא מִפְּנֵי תַּקָּנַת סוֹפֵר כְּמוֹ שֶׁבֵּאַרְנוּ:","הַכּוֹתֵב גֵּט בְּשַׁבָּת אוֹ בְּיוֹם הַכִּפּוּרִים בִּשְׁגָגָה וּנְתָנוֹ לָהּ הֲרֵי זוֹ מְגֹרֶשֶׁת. כְּתָבוֹ וַחֲתָמוֹ בּוֹ בַּיּוֹם בְּזָדוֹן וּנְתָנוֹ לָהּ אֵינָהּ מְגֹרֶשֶׁת שֶׁהֲרֵי הָעֵדִים פְּסוּלִין מִן הַתּוֹרָה. כְּתָבוֹ בְּיוֹם טוֹב בְּזָדוֹן וְנִמְסַר לָהּ בִּפְנֵי עֵדִים כְּשֵׁרִים בְּיוֹם טוֹב הֲרֵי זֶה גֵּט פָּסוּל:"],"Mishneh Torah, Eruvin 6":["מִי שֶׁיָּצָא מִן הַמְּדִינָה בְּעֶרֶב שַׁבָּת וְהִנִּיחַ מְזוֹן שְׁתֵּי סְעֻדּוֹת רָחוֹק מִן הַמְּדִינָה בְּתוֹךְ הַתְּחוּם וְקָבַע שְׁבִיתָתוֹ שָׁם. אַף עַל פִּי שֶׁחָזַר לַמְּדִינָה וְלָן בְּבֵיתוֹ נֶחְשָׁב אוֹתוֹ כְּאִלּוּ שָׁבַת בְּמָקוֹם שֶׁהִנִּיחַ בּוֹ שְׁתֵּי הַסְּעֻדּוֹת. וְזֶה הוּא הַנִּקְרָא עֵרוּבֵי תְּחוּמִין:","וְיֵשׁ לוֹ לְהַלֵּךְ מִמְּקוֹם עֵרוּבוֹ לְמָחָר אַלְפַּיִם אַמָּה לְכָל רוּחַ. לְפִיכָךְ כְּשֶׁהוּא מְהַלֵּךְ מִמְּקוֹם עֵרוּבוֹ לְמָחָר אַלְפַּיִם אַמָּה כְּנֶגֶד הַמְּדִינָה אֵינוֹ מְהַלֵּךְ בַּמְּדִינָה אֶלָּא עַד סוֹף מִדָּתוֹ. וְאִם הָיְתָה הַמְּדִינָה מֻבְלַעַת בְּתוֹךְ מִדָּתוֹ תֵּחָשֵׁב הַמְּדִינָה כֻּלָּהּ כְּאַרְבַּע אַמּוֹת וְיַשְׁלִים מִדָּתוֹ חוּצָה לָהּ:","כֵּיצַד. הֲרֵי שֶׁהִנִּיחַ אֶת עֵרוּבוֹ בְּרִחוּק אֶלֶף אַמָּה מִבֵּיתוֹ שֶׁבַּמְּדִינָה לְרוּחַ מִזְרָח נִמְצָא מְהַלֵּךְ לְמָחָר מִמְּקוֹם עֵרוּבוֹ אַלְפַּיִם אַמָּה לְמִזְרָח. וּמְהַלֵּךְ מִמְּקוֹם עֵרוּבוֹ אַלְפַּיִם אַמָּה לְמַעֲרָב. אֶלֶף שֶׁמִּן הָעֵרוּב עַד בֵּיתוֹ וְאֶלֶף אַמָּה מִבֵּיתוֹ בְּתוֹךְ הַמְּדִינָה. וְאֵינוֹ מְהַלֵּךְ בַּמְּדִינָה אֶלָּא עַד סוֹף הָאֶלֶף. הָיָה מִבֵּיתוֹ עַד סוֹף הַמְּדִינָה פָּחוֹת מֵאֶלֶף אֲפִלּוּ אַמָּה אַחַת שֶׁנִּמְצֵאת מִדָּתוֹ כָּלְתָה חוּץ לַמְּדִינָה תֵּחָשֵׁב הַמְּדִינָה כֻּלָּהּ כְּאַרְבַּע אַמּוֹת וִיהַלֵּךְ חוּצָה לָהּ תְּשַׁע מֵאוֹת שֵׁשׁ וְתִשְׁעִים אַמָּה תַּשְׁלוּם הָאַלְפַּיִם:","לְפִיכָךְ אִם הִנִּיחַ עֵרוּבוֹ בְּרִחוּק אַלְפַּיִם אַמָּה מִבֵּיתוֹ שֶׁבַּמְּדִינָה הִפְסִיד אֶת כָּל הַמְּדִינָה כֻּלָּהּ. וְנִמְצָא מְהַלֵּךְ מִבֵּיתוֹ עַד עֵרוּבוֹ אַלְפַּיִם אַמָּה וּמֵעֵרוּבוֹ אַלְפַּיִם וְאֵינוֹ מְהַלֵּךְ מִבֵּיתוֹ בַּמְּדִינָה לְרוּחַ מַעֲרָב אֲפִלּוּ אַמָּה אַחַת. הַמַּנִּיחַ עֵרוּבוֹ בִּרְשׁוּת הַיָּחִיד אֲפִלּוּ הָיְתָה מְדִינָה גְּדוֹלָה כְּנִינְוֵה וַאֲפִלּוּ עִיר חֲרֵבָה אוֹ מְעָרָה הָרְאוּיָה לְדִיּוּרִין מְהַלֵּךְ אֶת כֻּלָּהּ וְחוּצָה לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ:","הַמַּנִּיחַ עֵרוּבוֹ בְּתוֹךְ הַמְּדִינָה שֶׁשָּׁבַת בָּהּ לֹא עָשָׂה כְּלוּם וְאֵין מוֹדְדִין לוֹ מִמְּקוֹם עֵרוּבוֹ אֶלָּא הֲרֵי הוּא כִּבְנֵי הַמְּדִינָה כֻּלָּן שֶׁיֵּשׁ לָהֶן אַלְפַּיִם אַמָּה לְכָל רוּחַ חוּץ לַמְּדִינָה. וְכֵן אִם נָתַן עֵרוּבוֹ בַּמְּקוֹמוֹת הַמִּצְטָרְפִין לָעִיר שֶׁמּוֹדְדִין הַתְּחוּם חוּץ מֵהֶם הֲרֵי זֶה כְּנוֹתְנוֹ בְּתוֹךְ הָעִיר. נָתַן עֵרוּבוֹ חוּץ לַתְּחוּם אֵינוֹ עֵרוּב:","אֵין מְעָרְבִין עֵרוּבֵי תְּחוּמִין אֶלָּא לִדְבַר מִצְוָה כְּגוֹן שֶׁהָיָה רוֹצֶה לֵילֵךְ לְבֵית הָאָבֵל אוֹ לְמִשְׁתֶּה שֶׁל נִשּׂוּאִין אוֹ לְהַקְבִּיל פְּנֵי רַבּוֹ אוֹ חֲבֵרוֹ שֶׁבָּא מִן הַדֶּרֶךְ וְכַיּוֹצֵא בְּאֵלּוּ. אוֹ מִפְּנֵי הַיִּרְאָה כְּגוֹן שֶׁהָיָה רוֹצֶה לִבְרֹחַ מִן הָעוֹבְדֵי כּוֹכָבִים אוֹ מִן הַלִּסְטִים וְכַיּוֹצֵא בָּזֶה. וְאִם עֵרֵב שֶׁלֹּא לְאֶחָד מִכָּל אֵלּוּ אֶלָּא לְדִבְרֵי הָרְשׁוּת הֲרֵי זֶה עֵרוּב:","כָּל שֶׁמִּשְׁתַּתְּפִין בּוֹ מְעָרְבִין בּוֹ עֵרוּבֵי תְּחוּמִין. וְכָל שֶׁאֵין מִשְׁתַּתְּפִין בּוֹ אֵין מְעָרְבִין בּוֹ תְּחוּמִין. וְכַמָּה שִׁעוּר עֵרוּבֵי תְּחוּמִין מְזוֹן שְׁתֵּי סְעֻדּוֹת לְכָל אֶחָד וְאֶחָד. וְאִם הָיָה לִפְתָּן כְּדֵי לֶאֱכל בּוֹ שְׁתֵּי סְעֻדּוֹת. כְּמוֹ הַשִּׁתּוּף:","וְצָרִיךְ שֶׁיִּהְיֶה הוּא וְעֵרוּבוֹ בְּמָקוֹם אֶחָד כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר לוֹ לְאָכְלוֹ בֵּין הַשְּׁמָשׁוֹת. לְפִיכָךְ אִם נִתְכַּוֵּן לִשְׁבֹּת בִּרְשׁוּת הָרַבִּים וְהִנִּיחַ עֵרוּבוֹ בִּרְשׁוּת הַיָּחִיד. אוֹ בִּרְשׁוּת הַיָּחִיד וְהִנִּיחַ עֵרוּבוֹ בִּרְשׁוּת הָרַבִּים אֵינוֹ עֵרוּב. שֶׁאִי אֶפְשָׁר לוֹ לְהוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים בֵּין הַשְּׁמָשׁוֹת אֶלָּא בַּעֲבֵרָה:","אֲבָל אִם נִתְכַּוֵּן לִשְׁבֹּת בִּרְשׁוּת הַיָּחִיד אוֹ בִּרְשׁוּת הָרַבִּים וְהִנִּיחַ עֵרוּבוֹ בְּכַרְמְלִית. אוֹ שֶׁנִּתְכַּוֵּן לִשְׁבֹּת בְּכַרְמְלִית וְהִנִּיחַ עֵרוּבוֹ בִּרְשׁוּת הַיָּחִיד אוֹ בִּרְשׁוּת הָרַבִּים הֲרֵי זֶה עֵרוּב. שֶׁבִּשְׁעַת קְנִיַּת הָעֵרוּב שֶׁהוּא בֵּין הַשְּׁמָשׁוֹת מֻתָּר לְהוֹצִיא וּלְהַכְנִיס מִכָּל אַחַת מִשְּׁתֵּי הָרְשׁוּיוֹת לְכַרְמְלִית לִדְבַר מִצְוָה. שֶׁכָּל דָּבָר שֶׁהוּא מִדִּבְרֵי סוֹפְרִים לֹא גָּזְרוּ עָלָיו בֵּין הַשְּׁמָשׁוֹת בִּמְקוֹם מִצְוָה אוֹ בִּשְׁעַת הַדְּחָק:","נְתָנוֹ בְּמִגְדָּל וְנָעַל וְאָבַד הַמַּפְתֵּחַ אִם יָכוֹל לְהוֹצִיאוֹ בְּלֹא עֲשִׂיַּת מְלָאכָה הֲרֵי זֶה עֵרוּב. שֶׁאֵין אָסוּר לַעֲשׂוֹת בֵּין הַשְּׁמָשׁוֹת בִּמְקוֹם מִצְוָה אֶלָּא מְלָאכָה. נְתָנוֹ בְּרֹאשׁ הַקָּנֶה אוֹ הַקֻּנְדָּס הַצּוֹמְחִין מִן הָאָרֶץ אֵינוֹ עֵרוּב גְּזֵרָה שֶׁמָּא יִתְלֹשׁ. וְאִם הָיוּ תְּלוּשִׁין וּנְעוּצִין הֲרֵי זֶה עֵרוּב:","כָּל הַמַּנִּיחַ עֵרוּבוֹ יֵשׁ לוֹ בִּמְקוֹם עֵרוּבוֹ אַרְבַּע אַמּוֹת. לְפִיכָךְ הַמַּנִּיחַ עֵרוּבֵי תְּחוּמִין שֶׁלּוֹ בְּסוֹף הַתְּחוּם וְנִתְגַּלְגֵּל הָעֵרוּב וְיָצָא חוּץ לַתְּחוּם בְּתוֹךְ שְׁתֵּי אַמּוֹת הֲרֵי זֶה עֵרוּב וּכְאִלּוּ לֹא יָצָא מִמְּקוֹמוֹ. וְאִם יָצָא חוּץ לִשְׁתֵּי אַמּוֹת אֵינוֹ עֵרוּב שֶׁהֲרֵי נַעֲשָׂה חוּץ לַתְּחוּם וְהַמַּנִּיחַ עֵרוּבוֹ חוּץ לַתְּחוּם אֵינוֹ עֵרוּב מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לְהַגִּיעַ אֶל עֵרוּבוֹ:","נִתְגַּלְגֵּל הָעֵרוּב וְיָצָא שְׁתֵּי אַמּוֹת חוּץ לַתְּחוּם אוֹ אָבַד אוֹ נִשְׂרַף אוֹ שֶׁהָיָה תְּרוּמָה וְנִטְמֵאת מִבְּעוֹד יוֹם אֵינוֹ עֵרוּב. מִשֶּׁחֲשֵׁכָה הֲרֵי זֶה עֵרוּב. שֶׁקְּנִיַּת הָעֵרוּב בֵּין הַשְּׁמָשׁוֹת. וְאִם סָפֵק הֲרֵי זֶה עֵרוּב שֶׁסְּפֵק הָעֵרוּב כָּשֵׁר. לְפִיכָךְ אִם נֶאֱכַל הָעֵרוּב בֵּין הַשְּׁמָשׁוֹת הֲרֵי זֶה עֵרוּב:","אָמְרוּ לוֹ שְׁנַיִם צֵא וְעָרֵב עָלֵינוּ. אֶחָד עֵרֵב עָלָיו מִבְּעוֹד יוֹם וְאֶחָד עֵרֵב עָלָיו בֵּין הַשְּׁמָשׁוֹת. וְזֶה שֶׁעֵרֵב עָלָיו מִבְּעוֹד יוֹם נֶאֱכַל עֵרוּבוֹ בֵּין הַשְּׁמָשׁוֹת וְזֶה שֶׁעֵרֵב עָלָיו בֵּין הַשְּׁמָשׁוֹת נֶאֱכַל עֵרוּבוֹ מִשֶּׁחֲשֵׁכָה שְׁנֵיהֶם קָנוּ עֵרוּב. שֶׁבֵּין הַשְּׁמָשׁוֹת סָפֵק הוּא וּסְפֵק הָעֵרוּב כָּשֵׁר. אַף עַל פִּי כֵן סָפֵק חֲשֵׁכָה סָפֵק לֹא חֲשֵׁכָה אֵין מְעָרְבִין עֵרוּבֵי תְּחוּמִין לְכַתְּחִלָּה וְאִם עֵרֵב הֲרֵי זֶה עֵרוּב:","נָפַל עַל הָעֵרוּב גַּל מִבְּעוֹד יוֹם אִם יָכוֹל לְהוֹצִיאוֹ בְּלֹא עֲשִׂיַּת מְלָאכָה הֲרֵי זֶה כָּשֵׁר שֶׁמֻּתָּר לְהוֹצִיאוֹ בֵּין הַשְּׁמָשׁוֹת שֶׁהִיא שְׁעַת קְנִיַּת הָעֵרוּב. וְאִם נָפַל עָלָיו גַּל מִשֶּׁחֲשֵׁכָה הֲרֵי זֶה עֵרוּב וְאַף עַל פִּי שֶׁאִי אֶפְשָׁר לְהוֹצִיאוֹ אֶלָּא בַּעֲשִׂיַּת מְלָאכָה. סָפֵק מִבְּעוֹד יוֹם נָפַל אוֹ מִשֶּׁחֲשֵׁכָה הֲרֵי זֶה כָּשֵׁר שֶׁסְּפֵק הָעֵרוּב כָּשֵׁר:","אֲבָל אִם עֵרֵב בִּתְרוּמָה שֶׁהִיא סָפֵק טְמֵאָה אֵינוֹ עֵרוּב שֶׁאֵינָהּ סְעֻדָּה הָרְאוּיָה. וְכֵן אִם הָיוּ לְפָנָיו שְׁתֵּי כִּכָּרוֹת שֶׁל תְּרוּמָה אַחַת טְהוֹרָה וְאַחַת טְמֵאָה וְאֵינוֹ יוֹדֵעַ אֵי זוֹ הִיא מִשְּׁתֵּיהֶן וְאָמַר עֵרוּבִי בַּטְּהוֹרָה בְּכָל מָקוֹם שֶׁהוּא אֵינוֹ עֵרוּב. שֶׁאֵין כָּאן סְעֻדָּה הָרְאוּיָה לַאֲכִילָה:","אָמַר כִּכָּר זֶה הַיּוֹם חֹל וּלְמָחָר קֹדֶשׁ וְעֵרֵב בָּהּ הֲרֵי זֶה עֵרוּב. שֶׁבֵּין הַשְּׁמָשׁוֹת עֲדַיִן לֹא נִתְקַדְּשָׁה וַדַּאי וּרְאוּיָה הָיְתָה מִבְּעוֹד יוֹם. אֲבָל אִם אָמַר הַיּוֹם קֹדֶשׁ וּלְמָחָר חֹל אֵין מְעָרְבִין בָּהּ שֶׁאֵינָהּ רְאוּיָה עַד שֶׁתֶּחְשַׁךְ. וְכֵן אִם הִפְרִישׁ תְּרוּמָה וְהִתְנָה עָלֶיהָ שֶׁלֹּא תִּהְיֶה תְּרוּמָה עַד שֶׁתֶּחְשַׁךְ אֵין מְעָרְבִין בָּהּ. שֶׁהֲרֵי הִיא טֶבֶל כָּל בֵּין הַשְּׁמָשׁוֹת וְצָרִיךְ שֶׁתִּהְיֶה הַסְּעֻדָּה רְאוּיָה מִבְּעוֹד יוֹם:","הַנּוֹתֵן עֵרוּבוֹ בְּבֵית הַקְּבָרוֹת אֵינוֹ עֵרוּב לְפִי שֶׁבֵּית הַקְּבָרוֹת אָסוּר בַּהֲנָיָה וְכֵיוָן שֶׁרוֹצֶה בְּקִיּוּם הָעֵרוּב שָׁם אַחַר קְנִיָּה הֲרֵי נֶהֱנֶה בּוֹ. נְתָנוֹ בְּבֵית הַפְּרָס הֲרֵי זֶה עֵרוּב וַאֲפִלּוּ הָיָה כֹּהֵן מִפְּנֵי שֶׁיָּכוֹל לִכָּנֵס שָׁם בְּמִגְדָּל הַפּוֹרֵחַ אוֹ שֶׁיְּנַפֵּחַ וְהוֹלֵךְ:","רַבִּים שֶׁרָצוּ לְהִשְׁתַּתֵּף בְּעֵרוּבֵי תְּחוּמִין מְקַבְּצִין כֻּלָּן עֵרוּבָן שְׁתֵּי סְעֻדּוֹת לְכָל אֶחָד וְאֶחָד וּמַנִּיחִין אוֹתוֹ בִּכְלִי אֶחָד בְּמָקוֹם שֶׁיִּרְצוּ. וְאִם עָשָׂה אֶחָד עֵרוּב עַל יְדֵי כֻּלָּן צָרִיךְ לְזַכּוֹת לָהֶן עַל יְדֵי אַחֵר. וְצָרִיךְ לְהוֹדִיעָם שֶׁאֵין מְעָרְבִין לוֹ לָאָדָם עֵרוּבֵי תְּחוּמִין אֶלָּא לְדַעְתּוֹ שֶׁמָּא אֵינוֹ רוֹצֶה לְעָרֵב בְּאוֹתָהּ הָרוּחַ שֶׁרָצָה זֶה. וְאִם הוֹדִיעוֹ מִבְּעוֹד יוֹם אַף עַל פִּי שֶׁלֹּא רָצָה אֶלָּא מִשֶּׁתֶּחְשַׁךְ הֲרֵי זֶה עֵרוּב. וְאִם לֹא הוֹדִיעוֹ עַד שֶׁחֲשֵׁכָה אֵינוֹ יוֹצֵא בּוֹ שֶׁאֵין מְעָרְבִין מִשֶּׁתֶּחְשַׁךְ:","כָּל הַזּוֹכֶה בְּעֵרוּבֵי חֲצֵרוֹת מְזַכִּין עַל יָדוֹ בְּעֵרוּבֵי תְּחוּמִין. וְכָל מִי שֶׁאֵין מְזַכִּין עַל יָדוֹ עֵרוּבֵי חֲצֵרוֹת אֵין מְזַכִּין עַל יָדוֹ עֵרוּבֵי תְּחוּמִין:","נוֹתֵן אָדָם מָעָה לְבַעַל הַבַּיִת כְּדֵי שֶׁיִּקַּח לוֹ פַּת וִיעָרֵב לוֹ בָּהּ עֵרוּבֵי תְּחוּמִין. אֲבָל אִם נָתַן לְחֶנְוָנִי אוֹ לְנַחְתּוֹם וְאָמַר לוֹ זְכֵה לִי בְּמָעָה זוֹ אֵינוֹ עֵרוּב. וְאִם אָמַר לוֹ עַרֵב עָלַי בְּמָעָה זוֹ הֲרֵי זֶה לוֹקֵחַ בָּהּ פַּת אוֹ אֹכֶל מִן הָאֳכָלִין וּמְעָרֵב עָלָיו. וְאִם נָתַן לוֹ כְּלִי וְאָמַר לוֹ תֵּן לִי בָּזֶה אֹכֶל וּזְכֵה לִי בּוֹ הֲרֵי זֶה לוֹקֵחַ אֹכֶל וּמְעָרֵב עָלָיו בּוֹ:","מְעָרֵב אָדָם עֵרוּבֵי תְּחוּמִין עַל יְדֵי בְּנוֹ וּבִתּוֹ הַקְּטַנִּים וְעַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים בֵּין מִדַּעְתָּן בֵּין שֶׁלֹּא מִדַּעְתָּן. לְפִיכָךְ אִם עֵרֵב עֲלֵיהֶן וְעֵרְבוּ לְעַצְמָן יוֹצְאִין בְּשֶׁל רַבָּן. אֲבָל אֵינוֹ מְעָרֵב לֹא עַל יְדֵי בְּנוֹ וּבִתּוֹ הַגְּדוֹלִים וְלֹא עַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הָעִבְרִים וְלֹא עַל יְדֵי אִשְׁתּוֹ אֶלָּא מִדַּעְתָּן. וְאַף עַל פִּי שֶׁהֵן אוֹכְלִין אֶצְלוֹ עַל שֻׁלְחָנוֹ. וְאִם עֵרֵב עֲלֵיהֶן וְשָׁמְעוּ וְשָׁתְקוּ וְלֹא מִחוּ יוֹצְאִין בְּעֵרוּבוֹ. עֵרֵב עַל אֶחָד מֵהֶן וְעֵרְבוּ הֵן לְעַצְמָן אֵין לְךָ מְחָאָה גְּדוֹלָה מִזּוֹ וְיוֹצְאִין בְּעֵרוּב עַצְמָן. קָטָן בֵּן שֵׁשׁ שָׁנִים אוֹ פָּחוֹת יוֹצֵא בְּעֵרוּב אִמּוֹ וְאֵין צָרִיךְ לְהַנִּיחַ עָלָיו מְזוֹן שְׁתֵּי סְעֻדּוֹת לְעַצְמוֹ:","הָרוֹצֶה לְשַׁלֵּחַ עֵרוּבוֹ בְּיַד אַחֵר לְהַנִּיחוֹ לוֹ בְּמָקוֹם שֶׁהוּא רוֹצֶה לִקְבֹּעַ שְׁבִיתָתוֹ שָׁם הָרְשׁוּת בְּיָדוֹ. וּכְשֶׁהוּא מְשַׁלְּחוֹ אֵינוֹ מְשַׁלְּחוֹ בְּיַד חֵרֵשׁ שׁוֹטֶה וְקָטָן וְלֹא בְּיַד מִי שֶׁאֵינוֹ מוֹדֶה בְּמִצְוַת עֵרוּב. וְאִם שָׁלַח אֵינוֹ עֵרוּב. וְאִם שְׁלָחוֹ בְּיַד אֶחָד מֵאֵלּוּ הַפְּסוּלִין לְהוֹלִיכוֹ לְאָדָם כָּשֵׁר כְּדֵי שֶׁיּוֹלִיכוֹ הַכָּשֵׁר וְיַנִּיחוֹ בִּמְקוֹם הָעֵרוּב הֲרֵי זֶה כָּשֵׁר. וַאֲפִלּוּ שְׁלָחוֹ עַל הַקּוֹף אוֹ עַל הַפִּיל. וְהוּא שֶׁיִּהְיֶה עוֹמֵד מֵרָחוֹק עַד שֶׁיִּרְאֶה זֶה הַפָּסוּל אוֹ הַבְּהֵמָה שֶׁהִגִּיעוּ אֵצֶל הַכָּשֵׁר שֶׁאָמַר לוֹ לְהוֹלִיךְ אֶת הָעֵרוּב. וְכֵן רַבִּים שֶׁנִּשְׁתַּתְּפוּ בְּעֵרוּבֵי תְּחוּמִין וְרָצוּ לִשְׁלֹחַ עֵרוּבָן בְּיַד אַחֵר הֲרֵי אֵלּוּ מְשַׁלְּחִין:","אֶחָד אוֹ רַבִּים שֶׁאָמְרוּ לְאֶחָד צֵא וַעֲרֵב עָלֵינוּ וְעֵרֵב עֲלֵיהֶן בְּאֵי זֶה רוּחַ שֶׁרָצָה הֲרֵי זֶה עֵרוּב וְיוֹצְאִין בּוֹ שֶׁהֲרֵי לֹא יִחֲדוּ לוֹ רוּחַ. הָאוֹמֵר לַחֲבֵרוֹ עָרֵב עָלַי בִּתְמָרִים וְעֵרֵב עָלָיו בִּגְרוֹגָרוֹת. בִּגְרוֹגָרוֹת וְעֵרֵב עָלָיו בִּתְמָרִים. אָמַר לוֹ הַנִּיחַ עֵרוּבִי בְּמִגְדָּל וְהִנִּיחוֹ בְּשׁוֹבָךְ. בְּשׁוֹבָךְ וְהִנִּיחוֹ בְּמִגְדָּל. בַּבַּיִת וְהִנִּיחוֹ בַּעֲלִיָּה בַּעֲלִיָּה וְהִנִּיחוֹ בַּבַּיִת אֵינוֹ עֵרוּב. אֲבָל אִם אָמַר לוֹ עָרֵב עָלַי סְתָם וְעֵרֵב עָלָיו בֵּין בִּגְרוֹגָרוֹת בֵּין בִּתְמָרִים בֵּין בַּבַּיִת בֵּין בַּעֲלִיָּה הֲרֵי זֶה עֵרוּב:","כְּשֵׁם שֶׁמְּבָרְכִין עַל עֵרוּבֵי חֲצֵרוֹת וְשִׁתּוּפֵי מְבוֹאוֹת כָּךְ מְבָרְכִין עַל עֵרוּבֵי תְּחוּמִין. וְאוֹמֵר בְּזֶה הָעֵרוּב יִהְיֶה מֻתָּר לִי לְהַלֵּךְ לְמָקוֹם זֶה אַלְפַּיִם אַמָּה לְכָל רוּחַ. וְאִם הָיָה אֶחָד מְעָרֵב עַל יְדֵי רַבִּים אוֹמֵר בְּזֶה הָעֵרוּב יִהְיֶה מֻתָּר לִפְלוֹנִי אוֹ לִבְנֵי מָקוֹם פְּלוֹנִי אוֹ לִבְנֵי עִיר זוֹ לְהַלֵּךְ מִמָּקוֹם זֶה אַלְפַּיִם אַמָּה לְכָל רוּחַ:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 10":["מִצְוַת עֲשֵׂה לִתֵּן לַכֹּהֵן רֵאשִׁית הַגֵּז שֶׁנֶּאֱמַר (דברים יח ד) \"וְרֵאשִׁית גֵּז צֹאנְךָ תִּתֶּן לּוֹ\". וּלְוִיִּם בִּכְלַל יִשְׂרָאֵל בְּמִצְוָה זוֹ. וְאֵין לְרֵאשִׁית הַגֵּז זוֹ שִׁעוּר מִן הַתּוֹרָה. וּמִדִּבְרֵי סוֹפְרִים שֶׁלֹּא יִפְחֹת מֵאֶחָד מִשִּׁשִּׁים. וְאֵינָהּ נוֹהֶגֶת אֶלָּא בָּאָרֶץ בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת כְּרֵאשִׁית הַדָּגָן. וְנוֹהֵג בְּחֻלִּין אֲבָל לֹא בְּמֻקְדָּשִׁין:","כֵּיצַד. הֲרֵי שֶׁהִקְדִּישׁ בְּהֵמוֹת לְבֶדֶק הַבַּיִת וּגְזָזָן יָכוֹל יִהְיֶה חַיָּב לִפְדּוֹת וְלִתֵּן לַכֹּהֵן. אוֹ הִקְדִּישׁ בְּהֵמָה חוּץ מִגִּזָּתָהּ יָכוֹל יִהְיֶה חַיָּב בְּרֵאשִׁית הַגֵּז. תַּלְמוּד לוֹמַר (דברים יח ד) \"צֹאנְךָ\". אֵין אֵלּוּ צֹאנוֹ:","כָּל הַקֳדָשִׁים שֶׁקָּדַם מוּם קָבוּעַ לְהֶקְדֵּשָׁן וְנִפְדּוּ חַיָּבִין בְּרֵאשִׁית הַגֵּז. אֲבָל אִם קָדַם הֶקְדֵּשָׁן אֶת מוּמָן אוֹ שֶׁקָּדַם מוּם עוֹבֵר לְהֶקְדֵּשָׁן וְאַחַר כָּךְ נוֹלַד לָהֶן מוּם קָבוּעַ וְנִפְדּוּ פְּטוּרִים מֵרֵאשִׁית הַגֵּז:","אֵין חַיָּבִין בְּרֵאשִׁית הַגֵּז אֶלָּא הַכְּבָשִׂים בִּלְבַד. זְכָרִים כִּנְקֵבוֹת שֶׁהַצֶּמֶר שֶׁלָּהֶן הוּא הָרָאוּי לִבְגָדִים. הָיָה צִמְרָן קָשֶׁה וְאֵינוֹ רָאוּי לִלְבִישָׁה פְּטוּרִין מֵרֵאשִׁית הַגֵּז. שֶׁאֵין מַתָּנָה זוֹ לַכֹּהֵן אֶלָּא כְּדֵי לִלְבּשׁ מִמֶּנָּה:","כֵּיוָן שֶׁזִּכָּה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְרוּמוֹת שֶׁהֵן לַחְמוֹ וְיֵינוֹ. וְזִכָּה לוֹ בְּמַתְּנוֹת בְּהֵמָה וְקָדְשֵׁי מִקְדָּשׁ שֶׁהַבָּשָׂר שֶׁלּוֹ. זִכָּה לוֹ בְּרֵאשִׁית הַגֵּז לִלְבוּשׁוֹ. וּבְגֵזֶל הַגֵּר וְהַחֲרָמִים וּשְׂדֵה אֲחֻזָּה וּפִדְיוֹן בְּכוֹרוֹת לְהוֹצָאוֹתָיו וּשְׁאָר צְרָכָיו. שֶׁהֲרֵי אֵין לוֹ חֵלֶק בְּנַחֲלָה וּבַבִּזָּה:","הָיָה הַצֶּמֶר שֶׁלָּהֶן אָדֹם אוֹ שָׁחֹר אוֹ שָׁחוּם חַיָּבוֹת בְּרֵאשִׁית הַגֵּז. אֲבָל אִם גָּזַז הַצֶּמֶר וּצְבָעוֹ קֹדֶם שֶׁיִּתֵּן נִפְטָר מֵרֵאשִׁית הַגֵּז. הִלְבִּינוֹ קֹדֶם שֶׁיִּתֵּן חַיָּב לְהַפְרִישׁ אַחַר שֶׁלִּבְּנוֹ. הַתּוֹלֵשׁ צֶמֶר רְחֵלִים בְּיָדוֹ וְלֹא גָּזַז חַיָּב בְּרֵאשִׁית הַגֵּז:","רֵאשִׁית הַגֵּז נוֹהֵג בְּכִלְאַיִם וּבִכְוִי וּבִטְרֵפָה. אֲבָל הַגּוֹזֵז אֶת הַמֵּתָה פָּטוּר:","הַמַּפְרִישׁ רֵאשִׁית הַגֵּז וְאָבַד חַיָּב בְּאַחֲרָיוּתָן עַד שֶׁיִּתֵּן לַכֹּהֵן. הָאוֹמֵר כָּל גִּזּוֹתַי רֵאשִׁית דְּבָרָיו קַיָּמִין:","הַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל עַכּוּ\"ם אַחַר שֶׁגְּזָזָן הָעַכּוּ\"ם פָּטוּר מֵרֵאשִׁית הַגֵּז. לָקַח הַצֹּאן לְגִזָּתָן חַיָּב אַף עַל פִּי שֶׁגָּדְלָה הַגִּזָּה בִּרְשׁוּת הָעַכּוּ\"ם. וְאַף עַל פִּי שֶׁחוֹזְרִין הַצֹּאן לְעַכּוּ\"ם אַחַר גְּזִיזָה. הוֹאִיל וְהַגּוֹזֵז יִשְׂרָאֵל וְהַגְּזִיזוֹת שֶׁלּוֹ חַיָּב שֶׁאֵין הַחִיּוּב אֶלָּא בִּשְׁעַת הַגִּזָּה:","הַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל חֲבֵרוֹ אִם שִׁיֵּר הַמּוֹכֵר מְעַט מִצֹּאנוֹ לְהִגָּזֵז הַמּוֹכֵר חַיָּב לְהַפְרִישׁ מִן הַמְּשֹׁאָר עַל הַכּל. וְאַף עַל פִּי שֶׁלֹּא הִתְחִיל הַמּוֹכֵר לִגְזֹז. חֲזָקָה אֵין אָדָם מוֹכֵר מַתְּנוֹת כְּהֻנָּה. וְאִם לֹא שִׁיֵּר כְּלוּם הַלּוֹקֵחַ חַיָּב לְהַפְרִישׁ:","הָיוּ שְׁנֵי מִינֵי גִּזָּה כְּגוֹן גִּזָּה לְבָנָה וְגִזָּה שְׁחוּמָה אוֹ גִּזַּת זְכָרִים וְגִזַּת נְקֵבוֹת. וּמָכַר מִין זֶה וְהִנִּיחַ הַמִּין הָאַחֵר. זֶה נוֹתֵן לְעַצְמוֹ וְזֶה נוֹתֵן לְעַצְמוֹ. [זֶה נוֹתֵן לְעַצְמוֹ] עַל מַה שֶּׁלָּקַח וְזֶה נוֹתֵן לְעַצְמוֹ עַל מַה שֶּׁשִּׁיֵּר:","גֵּר שֶׁנִּתְגַּיֵּר וְהָיוּ לוֹ גִּזּוֹת וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נִתְגַּיֵּר נִגְזְזוּ אוֹ מִשֶּׁנִּתְגַּיֵּר הֲרֵי זֶה פָּטוּר. וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","כַּמָּה צֹאן יִהְיֶה לוֹ וְיִהְיוּ חַיָּבוֹת בְּרֵאשִׁית הַגֵּז. אֵין פָּחוֹת מֵחָמֵשׁ. וְהוּא שֶׁיִּהְיֶה בַּגִּזָּה שֶׁלָּהֶן אֵין פָּחוֹת מִמִּשְׁקַל שִׁשִּׁים סֶלַע. וְתִהְיֶה גִּזַּת כָּל אַחַת מֵחֲמִשְּׁתָּן אֵין פָּחוֹת מִמִּשְׁקַל י\"ב סֶלַע. הָיְתָה אַחַת מֵהֶם גּוֹזֶזֶת פָּחוֹת מִי\"ב סֶלַע אַף עַל פִּי שֶׁחֲמִשְּׁתָּן גּוֹזְזוֹת שִׁשִּׁים סֶלַע אוֹ יֶתֶר הֲרֵי אֵלּוּ פְּטוּרִין מֵרֵאשִׁית הַגֵּז:","הַשֻּׁתָּפִין חַיָּבִין בְּרֵאשִׁית הַגֵּז. וְהוּא שֶׁיִּהְיֶה בְּחֵלֶק כָּל אֶחָד מֵהֶן כַּשִּׁעוּר. אֲבָל חָמֵשׁ צֹאן בִּלְבַד שֶׁל שְׁנֵי שֻׁתָּפִין פְּטוּרִין:","רֵאשִׁית הַגֵּז מִצְוָתָהּ בַּתְּחִלָּה וְאִם הִפְרִישׁ בֵּין בָּאֶמְצַע בֵּין בַּסּוֹף יָצָא. הָיוּ לוֹ חָמֵשׁ צֹאן וְגָזַז אַחַת מֵהֶן בִּלְבַד וּמָכַר גִּזָּתָהּ. וְאַחַר כָּךְ גּוֹזֵז שְׁנִיָּה וּמָכַר גִּזָּתָהּ. וְאַחַר כָּךְ גּוֹזֵז שְׁלִישִׁית וּמָכַר גִּזָּתָהּ. הַכּל מִצְטָרְפוֹת לְרֵאשִׁית הַגֵּז. וְחַיָּב אֲפִלּוּ לְאַחַר כַּמָּה שָׁנִים. וְיֵשׁ לוֹ לְהַפְרִישׁ מִן הֶחָדָשׁ עַל הַיָּשָׁן וּמִזֶּה עַל זֶה. אֲבָל אִם הָיְתָה רָחֵל אַחַת וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ וְאַחַר כָּךְ קָנָה שְׁנִיָּה וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ אֵינָן מִצְטָרְפוֹת:","מִי שֶׁהָיוּ לוֹ גִּזּוֹת רַבּוֹת שֶׁל רֵאשִׁית הַגֵּז וְרוֹצֶה לְחַלֵּק לַכֹּהֲנִים. לֹא יִתֵּן לְכָל אֶחָד וְאֶחָד פָּחוֹת מִמִּשְׁקַל חָמֵשׁ סְלָעִים מְלֻבָּן כְּדֵי בֶּגֶד קָטָן. לֹא שֶׁיְּלַבְּנוֹ וְאַחַר כָּךְ יִתֵּן לוֹ אֶלָּא יִתֵּן לוֹ מִצֶּמֶר הַגִּזָּה כְּשֶׁהוּא צוֹאִי. כְּדֵי שֶׁיִּהְיֶה בּוֹ אַחַר הַלִּבּוּן חָמֵשׁ סְלָעִים אוֹ יֶתֶר שֶׁנֶּאֱמַר (דברים יח ד) \"תִּתֵּן לוֹ\" שֶׁיִּהְיֶה בּוֹ כְּדֵי מַתָּנָה הַמּוֹעֶלֶת:","רֵאשִׁית הַגֵּז חֻלִּין לְכָל דָּבָר. לְפִיכָךְ אֲנִי אוֹמֵר שֶׁנּוֹתְנִים אוֹתוֹ לְכֹהֶנֶת אַף עַל פִּי שֶׁהִיא נְשׂוּאָה לְיִשְׂרָאֵל כְּמַתְּנוֹת בְּהֵמָה. וְיֵרָאֶה לִי שֶׁדִּין שְׁנֵיהֶן אֶחָד הוּא:"],"Mishneh Torah, Firstlings 2":["כָּל הַמּוּמִים הַקְּבוּעִים הַפּוֹסְלִין אֶת הַקֳדָשִׁים וְנִפְדִּים עֲלֵיהֶן. אִם נָפַל אֶחָד מֵהֶן בִּבְכוֹר הֲרֵי זֶה נִשְׁחָט עָלָיו בְּכָל מָקוֹם. וּכְבָר בֵּאַרְנוּ אוֹתָן הַמּוּמִין בְּהִלְכוֹת אִסּוּרֵי מִזְבֵּחַ שֶׁהָרָאוּי מֵהֶן לִהְיוֹת בְּזָכָר שִׁשִּׁים וְשִׁבְעָה:","וְכָל הַדְּבָרִים שֶׁמָּנִינוּ שָׁם שֶׁאֵין הַקָּרְבָּן מִן הַמֻּבְחָר וְאֵין הַקָּדָשִׁים קְרֵבִין בָּהֶן וְלֹא נִפְדִּין עֲלֵיהֶן כָּךְ אֵין הַבְּכוֹר נִשְׁחָט עֲלֵיהֶן וְלֹא קָרֵב אֶלָּא יִהְיֶה עוֹמֵד עַד שֶׁיִּוָּלֵד לוֹ מוּם קָבוּעַ. וְכֵן אִם נוֹלָד בִּבְכוֹר מוּם עוֹבֵר הֲרֵי זֶה אֵינוֹ נִשְׁחָט בְּכָל מָקוֹם וְלֹא קָרֵב אֶלָּא יִהְיֶה רוֹעֶה עַד שֶׁיִּפּל בּוֹ מוּם קָבוּעַ וְיִשָּׁחֵט עָלָיו:","וְכֵן אִם נֶעֶבְדָה בּוֹ עֲבֵרָה. אוֹ שֶׁהָרַג בְּעֵד אֶחָד. אוֹ עַל פִּי הַבְּעָלִים. אוֹ שֶׁהֻקְצָה אוֹ נֶעֱבָד. יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מִזְבֵּחַ:","יוֹצֵא דֹּפֶן וְהַבָּא אַחֲרָיו שְׁנֵיהֶן אֵינָן בְּכוֹר. הָרִאשׁוֹן מִפְּנֵי שֶׁאֵינוֹ פֶּטֶר רֶחֶם וְהָאַחֲרוֹן מִפְּנֵי שֶׁקְּדָמוֹ אַחֵר. אֲפִלּוּ יָצְאָה נְקֵבָה דֶּרֶךְ דֹּפֶן וְזָכָר דֶּרֶךְ רֶחֶם אֵינוֹ בְּכוֹר:","בְּכוֹר שֶׁהוּא אַנְדְּרוֹגִינוּס אֵין בּוֹ קְדֻשָּׁה כְּלָל. וַהֲרֵי הוּא כִּנְקֵבָה שֶׁאֵין בּוֹ לַכֹּהֵן כְּלוּם. וְעוֹבְדִים בּוֹ וְגוֹזְזִים אוֹתוֹ כִּשְׁאָר הַחֻלִּין. נוֹלַד טֻמְטוּם הֲרֵי זֶה סְפֵק בְּכוֹר וְיֵאָכֵל בְּמוּמוֹ לִבְעָלָיו. בֵּין שֶׁהֵטִיל מַיִם מִמְּקוֹם זִכְרוּת בֵּין שֶׁהֵטִיל מִמְּקוֹם נַקְבוּת:","רָחֵל שֶׁיָּלְדָה כְּמִין עֵז. אוֹ עֵז שֶׁיָּלְדָה כְּמִין רָחֵל פָּטוּר מִן הַבְּכוֹרָה שֶׁנֶּאֱמַר (במדבר יח יז) \"אַךְ בְּכוֹר שׁוֹר\" עַד שֶׁיִּהְיֶה הוּא שׁוֹר וּבְכוֹרוֹ שׁוֹר. וְאִם הָיָה בּוֹ מִקְצָת סִימָנֵי אִמּוֹ הֲרֵי זֶה בְּכוֹר וְהוּא בַּעַל מוּם קָבוּעַ שֶׁאֵין לְךָ מוּם גָּדוֹל מִשִּׁנּוּי בְּרִיָּתוֹ. אֲפִלּוּ פָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹר וְיֵשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה הֲרֵי זֶה בְּכוֹר לַכֹּהֵן הוֹאִיל וּמִין הַחֲמוֹר יֵשׁ בּוֹ דִּין בְּכוֹר. אֲבָל אִם יָלְדָה מִין סוּס אוֹ גָּמָל אַף עַל פִּי שֶׁיֵּשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה הֲרֵי הוּא סְפֵק בְּכוֹר לְפִיכָךְ יֵאָכֵל לַבְּעָלִים. וְאִם תְּפָסוֹ כֹּהֵן אֵין מוֹצִיאִין מִיָּדוֹ:","הַמַּטִּיל מוּם בִּבְכוֹר הוֹאִיל וְעָשָׂה עֲבֵרָה קוֹנְסִין אוֹתוֹ וְאֵינוֹ נִשְׁחָט עַל מוּם זֶה עַד שֶׁיִּפּל בּוֹ מוּם אַחֵר מֵאֵלָיו. וְאִם מֵת זֶה הַחוֹטֵא מֻתָּר לִבְנוֹ לְשָׁחֳטוֹ עַל מוּם שֶׁעָשָׂה אָבִיו שֶׁלֹּא קָנְסוּ בְּנוֹ אַחֲרָיו:","הִרְגִּיל לַבְּכוֹר שֶׁיִּפּל בּוֹ מוּם כְּגוֹן שֶׁנָּתַן דְּבֵלָה עַל אָזְנוֹ עַד שֶׁבָּא כֶּלֶב וּנְטָלָהּ וְחָתַךְ אָזְנוֹ. אוֹ שֶׁהָלַךְ בֵּין בַּרְזֶל וַעֲשָׁשִׁיּוֹת שֶׁל זְכוּכִית כְּדֵי שֶׁתִּקָּטַע יָדוֹ וְנִקְטְעָה. אוֹ שֶׁאָמַר לְנָכְרִי לְהַטִּיל בּוֹ מוּם. הֲרֵי זֶה לֹא יִשְׁחֹט עָלָיו. זֶה הַכְּלָל כָּל מוּם שֶׁנַּעֲשָׂה לְדַעְתּוֹ אָסוּר לוֹ לִשְׁחֹט עָלָיו וְאִם נַעֲשָׂה שֶׁלֹּא לְדַעְתּוֹ הֲרֵי זֶה שׁוֹחֵט עָלָיו:","אָמַר אִלּוּ נָפַל בִּבְכוֹר זֶה מוּם הָיִיתִי שׁוֹחֲטוֹ וְשָׁמַע הַנָּכְרִי וְעָשָׂה בּוֹ מוּם הֲרֵי זֶה שׁוֹחֵט עָלָיו שֶׁהֲרֵי לֹא נַעֲשָׂה בְּדַעְתּוֹ:","רְאִינוּהוּ שֶׁעָשָׂה מַעֲשֶׂה הַמַּרְגִּיל לְהַטִּיל בּוֹ מוּם וְנָפַל בּוֹ מוּם וְאֵין אָנוּ יוֹדְעִין אִם נִתְכַּוֵּן לְמוּם זֶה אוֹ לֹא נִתְכַּוֵּן. הֲרֵי זֶה לֹא יִשְׁחֹט עָלָיו. כֵּיצַד. כְּגוֹן שֶׁנָּתַן לוֹ שְׂעוֹרִים בְּמָקוֹם דָּחוּק מְסֹרָג בְּקוֹצִים וְכֵיוָן שֶׁאָכַל נֶחְלַק שְׂפָתוֹ אֲפִלּוּ הָיָה חָבֵר הֲרֵי זֶה לֹא יִשְׁחֹט עָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיָה בְּכוֹר רוֹדֵף אֶת הָאָדָם וּבָעֲטוֹ כְּדֵי לְטָרְדוֹ וַאֲפִלּוּ בָּעַט בּוֹ מִפְּנֵי שֶׁרְדָפוֹ מִקֹּדֶם וְנַעֲשָׂה בּוֹ מוּם בִּבְעִיטָה זוֹ הֲרֵי זֶה יִשְׁחַט עָלָיו:","קְטַנִּים שֶׁהִטִּילוּ מוּם בִּבְכוֹר דֶּרֶךְ שְׂחוֹק וְכֵן הַנָּכְרִי שֶׁעָשָׂה לְדַעְתּוֹ הֲרֵי זֶה יִשְׁחֹט עָלָיו. וְאִם עָשׂוּ כְּדֵי לְהַתִּירוֹ לֹא יִשְׁחֹט עָלָיו:","בְּכוֹר שֶׁאֲחָזוֹ דָּם יַקִּיז. וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לַעֲשׂוֹת בּוֹ מוּם. וְאִם נַעֲשָׂה בּוֹ מוּם בְּהַקָּזָה זוֹ הֲרֵי זֶה נִשְׁחַט עָלָיו:","מֻתָּר לְהַטִּיל מוּם בִּבְכוֹר קֹדֶם שֶׁיֵּצֵא לַאֲוִיר הָעוֹלָם וְיִשְׁחַט עָלָיו. בַּמֶּה דְּבָרִים אֲמוּרִים בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם בַּיִת מִפְּנֵי שֶׁסּוֹפוֹ לְהֵאָכֵל בְּמוּמוֹ. אֲבָל בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם אָסוּר:","עֵד שֶׁהֵעִיד מִפִּי עֵד אַחַר שֶׁמּוּם זֶה נָפַל שֶׁלֹּא לְדַעַת נֶאֱמָן. אֲפִלּוּ אִשָּׁה נֶאֱמֶנֶת לוֹמַר בְּפָנַי נָפַל מוּם זֶה מֵאֵלָיו וְיִשְׁחַט עָלָיו:","כָּל הַמּוּמִין הָרְאוּיִין לָבוֹא בִּידֵי אָדָם נֶאֱמָן הָרוֹעֶה עֲלֵיהֶן לוֹמַר מֵאֲלֵיהֶן נָפְלוּ וְלֹא נַעֲשׂוּ בְּכַוָּנָה וְיִשְׁחַט עֲלֵיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הָרוֹעֶה יִשְׂרָאֵל וְהַבְּכוֹר בְּיַד הַכֹּהֵן. אֲבָל אִם הָיָה הָרוֹעֶה כֹּהֵן וְהַבְּכוֹר עֲדַיִן הוּא בְּיַד בְּעָלָיו הַיִּשְׂרְאֵלִי. הֲרֵי זֶה אֵינוֹ נֶאֱמָן וְחוֹשְׁדִין אוֹתוֹ שֶׁמָּא הוּא הִטִּיל בּוֹ מוּם כְּדֵי שֶׁיִּתְּנֶנּוּ לוֹ:","כֹּהֵן שֶׁהֵעִיד לְכֹהֵן אַחֵר שֶׁמּוּם זֶה מֵאֵלָיו נָפַל נֶאֱמָן וְאֵין חוֹשְׁשִׁין לָהֶן שֶׁמָּא הֵם גּוֹמְלִים זֶה אֶת זֶה. שֶׁכָּל הַכֹּהֲנִים חֲשׁוּדִין לְהַטִּיל מוּם בִּבְכוֹר כְּדֵי לְאָכְלוֹ בַּחוּץ וּלְפִיכָךְ אֵין נֶאֱמָנִין עַל יְדֵי עַצְמָן. אֲבָל חֲבֵרוֹ מֵעִיד לוֹ, שֶׁאֵין אָדָם חוֹטֵא לְאַחֵר. אֲפִלּוּ בָּנָיו וּבְנֵי בֵּיתוֹ שֶׁל כֹּהֵן מְעִידִין לוֹ עַל הַבְּכוֹר אֲבָל לֹא אִשְׁתּוֹ מִפְּנֵי שֶׁהִיא כְּגוּפוֹ:","בְּכוֹר שֶׁהָיָה בְּיַד כֹּהֵן וְנָפַל בּוֹ מוּם וְהֵעִיד עָלָיו עֵד אֶחָד שֶׁזֶּה הַמּוּם מֵאֵלָיו נָפַל וְאֵין אָנוּ יוֹדְעִים אִם מוּם זֶה שׁוֹחֲטִין עָלָיו אֶת הַבְּכוֹר אוֹ אֵין שׁוֹחֲטִין עָלָיו וּבָא הַכֹּהֵן שֶׁהוּא בְּיָדוֹ וְאָמַר הֶרְאֵיתִי מוּם זֶה לְמֻמְחֶה וְהִתִּירוֹ לִשְׁחִיטָה הֲרֵי זֶה נֶאֱמָן. וְאֵין חוֹשְׁשִׁין שֶׁמָּא לֹא הֶרְאָהוּ וְשֶׁמָּא בְּכוֹר תָּם הוּא שֶׁלֹּא נֶחְשְׁדוּ לִשְׁחֹט קָדָשִׁים בַּחוּץ מִפְּנֵי שֶׁהוּא עֲוֹן כָּרֵת כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן נֶאֱמָן הַכֹּהֵן לוֹמַר עַל בְּכוֹר בַּעַל מוּם בְּכוֹר זֶה נְתָנוֹ לִי יִשְׂרָאֵל בְּמוּמוֹ וְלֹא נָפַל בִּרְשׁוּתִי כְּדֵי לָחוּשׁ לוֹ שֶׁמָּא הוּא הִטִּילוֹ. שֶׁהַדָּבָר עָשׂוּי לְהִגָּלוֹת וְהוּא מִתְיָרֵא שֶׁמָּא יִשְׁאֲלוּ בְּעָלָיו וְיֹאמַר תָּמִים הָיָה בְּעֵת שֶׁנְּתָנוּהוּ לוֹ:"],"Mishneh Torah, Forbidden Foods 14":["כָּל אִסּוּרֵי מַאֲכָלוֹת שֶׁבַּתּוֹרָה שִׁעוּרָן בִּכְזַיִת בֵּינוֹנִי בֵּין לְמַלְקוֹת בֵּין לְכָרֵת בֵּין לְמִיתָה בִּידֵי שָׁמַיִם. וּכְבָר בֵּאַרְנוּ שֶׁכָּל הַמְחֻיָּב כָּרֵת אוֹ מִיתָה בִּידֵי שָׁמַיִם עַל מַאֲכָל לוֹקֶה:","וְשִׁעוּר זֶה עִם כָּל הַשִּׁעוּרִין הֲלָכָה לְמשֶׁה מִסִּינַי הֵם. וְאָסוּר מִן הַתּוֹרָה לֶאֱכל כָּל שֶׁהוּא מִדָּבָר הָאָסוּר. אֲבָל אֵינוֹ לוֹקֶה אֶלָּא עַל כְּזַיִת. וְאִם אָכַל כָּל שֶׁהוּא פָּחוֹת מִכַּשִּׁעוּר מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","כְּזַיִת שֶׁאָמַרְנוּ חוּץ מִשֶּׁל בֵּין הַשִּׁנַּיִם. אֲבָל מַה שֶּׁל בֵּין הַחֲנִיכַיִם מִצְטָרֵף לְמַה שֶּׁבָּלַע שֶׁהֲרֵי נֶהֱנָה גְּרוֹנוֹ מִכְּזַיִת. אֲפִלּוּ אָכַל כַּחֲצִי זַיִת וֶהֱקִיאוֹ וְחָזַר וְאָכַל אוֹתוֹ חֲצִי זַיִת עַצְמוֹ שֶׁהֵקִיא חַיָּב. שֶׁאֵין הַחִיּוּב אֶלָּא עַל הֲנָאַת הַגָּרוֹן בִּכְזַיִת מִדָּבָר הָאָסוּר:","כְּזַיִת חֵלֶב אוֹ נְבֵלָה אוֹ פִּגּוּל אוֹ נוֹתָר וְכַיּוֹצֵא בָּהֶן שֶׁהִנִּיחוֹ בַּחַמָּה וְנִתְמַעֵט. הָאוֹכְלוֹ פָּטוּר. חָזַר וְהִנִּיחוֹ בַּגְּשָׁמִים וְנִתְפַּח חַיָּבִין עָלָיו כָּרֵת אוֹ מַלְקוֹת. הָיָה פָּחוֹת מִכְּזַיִת מִבַּתְּחִלָּה וְנִתְפַּח וְעָמַד עַל כְּזַיִת אָסוּר וְאֵין לוֹקִין עָלָיו:","כְּבָר בֵּאַרְנוּ שֶׁכָּל אִסּוּרִין שֶׁבַּתּוֹרָה אֵין מִצְטָרְפִין זֶה עִם זֶה לִכְזַיִת. חוּץ מִבְּשַׂר נְבֵלָה עִם בְּשַׂר טְרֵפָה וְאִסּוּרֵי נָזִיר שֶׁיִּתְבָּאֲרוּ בִּמְקוֹמָן. וַחֲמֵשֶׁת מִינֵי תְּבוּאָה וּקְמָחִין שֶׁלָּהֶן וְהַבְּצֵקוֹת שֶׁלָּהֶן הַכּל מִצְטָרְפִים לִכְזַיִת בֵּין לְאִסּוּר חָמֵץ בְּפֶסַח. בֵּין לְאִסּוּר חָדָשׁ מִלִּפְנֵי הָעֹמֶר. בֵּין לְאִסּוּרֵי מַעֲשֵׂר שֵׁנִי וּתְרוּמוֹת:","יֵרָאֶה לִי שֶׁכָּל הַחַיָּב בִּתְרוּמָה וּמַעַשְׂרוֹת מִצְטָרֵף לִכְזַיִת בְּטֶבֶל מִפְּנֵי שֶׁהוּא שֵׁם אֶחָד. הָא לְמַה זֶּה דּוֹמֶה לְנִבְלַת הַשּׁוֹר וְנִבְלַת הַשֶּׂה וְנִבְלַת הַצְּבִי שֶׁהֵן מִצְטָרְפִין לִכְזַיִת כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹכֵל אֲכִילָה גְּדוֹלָה מִדָּבָר אָסוּר אֵין מְחַיְּבִין אוֹתוֹ מַלְקוֹת אוֹ כָּרֵת עַל כָּל כְּזַיִת וּכְזַיִת אֶלָּא חִיּוּב אֶחָד לְכָל הָאֲכִילָה. וְאִם הָיוּ הָעֵדִים מַתְרִים בּוֹ בִּשְׁעַת אֲכִילָה עַל כָּל כְּזַיִת וּכְזַיִת חַיָּב עַל כָּל הַתְרָאָה וְהַתְרָאָה וְאַף עַל פִּי שֶׁהִיא אֲכִילָה אַחַת וְלֹא הִפְסִיק:","הָאוֹכֵל כִּשְׂעוֹרָה אוֹ כְּחַרְדָּל מֵאֶחָד מִכָּל מַאֲכָלוֹת הָאֲסוּרִים וְשָׁהָה מְעַט וְחָזַר וְאָכַל כְּחַרְדָּל. וְכֵן עַד שֶׁהִשְׁלִים כְּזַיִת. בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד. אִם שָׁהָה מִתְּחִלָּה וְעַד סוֹף כְּדֵי אֲכִילַת שָׁלֹשׁ בֵּיצִים יִצְטָרֵף הַכּל וַהֲרֵי הוּא חַיָּב כָּרֵת אוֹ מַלְקוֹת אוֹ קָרְבָּן כְּמוֹ שֶׁאָכַל כְּזַיִת בְּבַת אַחַת. וְאִם שָׁהָה יֶתֶר מִזֶּה מִתְּחִלָּה וְעַד סוֹף אַף עַל פִּי שֶׁלֹּא שָׁהָה בֵּינֵיהֶן אֶלָּא אָכַל כְּחַרְדָּל אַחַר כְּחַרְדָּל הוֹאִיל וְלֹא הִשְׁלִים כְּזַיִת אֶלָּא בְּיֶתֶר מִכְּדֵי אֲכִילַת פְּרָס אֵינָן מִצְטָרְפִין וּפָטוּר:","וְכֵן הַשּׁוֹתֶה רְבִיעִית שֶׁל סְתָם יֵינָם מְעַט מְעַט. אוֹ שֶׁהִמְחָה אֶת הֶחָמֵץ בְּפֶסַח אוֹ אֶת הַחֵלֶב וּגְמָעוֹ מְעַט מְעַט. אוֹ שֶׁשָּׁתָה מִן הַדָּם מְעַט מְעַט. אִם שָׁהָה מִתְּחִלָּה וְעַד סוֹף כְּדֵי שְׁתִיַּת רְבִיעִית מִצְטָרְפִין. וְאִם לָאו אֵין מִצְטָרְפִין:","כָּל הָאֳכָלִין הָאֲסוּרִין אֵינוֹ חַיָּב עֲלֵיהֶם עַד שֶׁיֹּאכַל אוֹתָן דֶּרֶךְ הֲנָאָה חוּץ מִבָּשָׂר בְּחָלָב וְכִלְאֵי הַכֶּרֶם לְפִי שֶׁלֹּא נֶאֱמַר בָּהֶן אֲכִילָה אֶלָּא הוֹצִיא אִסּוּר אֲכִילָתָן בְּלָשׁוֹן אַחֶרֶת בִּלְשׁוֹן בִּשּׁוּל וּבִלְשׁוֹן הֶקְדֵּשׁ לֶאֱסוֹר אוֹתָן וַאֲפִלּוּ שֶׁלֹּא כְּדֶרֶךְ הֲנָיָה:","כֵּיצַד. הֲרֵי שֶׁהִמְחָה אֶת הַחֵלֶב וּגְמָעוֹ כְּשֶׁהוּא חַם עַד שֶׁנִּכְוָה גְּרוֹנוֹ מִמֶּנּוּ אוֹ שֶׁאָכַל חֵלֶב חַי. אוֹ שֶׁעֵרֵב דְּבָרִים מָרִים כְּגוֹן רֹאשׁ וְלַעֲנָה לְתוֹךְ יֵין נֶסֶךְ אוֹ לְתוֹךְ קְדֵרָה שֶׁל נְבֵלָה וַאֲכָלָן כְּשֶׁהֵן מָרִין. אוֹ שֶׁאָכַל אֹכֶל הָאָסוּר אַחַר שֶׁהִסְרִיחַ וְהִבְאִישׁ וּבָטַל מֵאֹכֶל אָדָם הֲרֵי זֶה פָּטוּר. וְאִם עֵרֵב דָּבָר מַר בְּתוֹךְ קְדֵרָה שֶׁל בָּשָׂר בְּחָלָב אוֹ בְּיֵין כִּלְאֵי הַכֶּרֶם וַאֲכָלוֹ חַיָּב:","הָאוֹכֵל מַאֲכָל מִמַּאֲכָלוֹת הָאֲסוּרוֹת דֶּרֶךְ שְׂחוֹק אוֹ כְּמִתְעַסֵּק. אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לְגוּף הָאֲכִילָה. הוֹאִיל וְנֶהֱנָה חַיָּב כְּמִי שֶׁמִּתְכַּוֵּן לְעַצְמָהּ שֶׁל אֲכִילָה. וַהֲנָיָה הַבָּאָה לוֹ לְאָדָם בְּעַל כָּרְחוֹ בְּאִסּוּר מִכָּל הָאִסּוּרִין אִם נִתְכַּוֵּן אָסוּר וְאִם לֹא נִתְכַּוֵּן מֻתָּר:","הָאוֹכֵל מַאֲכָל אָסוּר לְתֵאָבוֹן אוֹ מִפְּנֵי הָרָעָב חַיָּב. וְאִם הָיָה תּוֹעֶה בַּמִּדְבָּר וְאֵין לוֹ מַה יֹּאכַל אֶלָּא דְּבַר אִסּוּר הֲרֵי זֶה מֻתָּר מִפְּנֵי סַכָּנַת נְפָשׁוֹת:","עֻבָּרָה שֶׁהֵרִיחָה מַאֲכָל אָסוּר כְּגוֹן בְּשַׂר קֹדֶשׁ אוֹ בְּשַׂר חֲזִיר. מַאֲכִילִין אוֹתָהּ מִן הַמָּרָק. אִם נִתְיַשְּׁבָה דַּעְתָּהּ מוּטָב. וְאִם לָאו מַאֲכִילִין אוֹתָהּ פָּחוֹת מִכַּשִּׁעוּר. וְאִם לֹא נִתְיַשְּׁבָה דַּעְתָּהּ מַאֲכִילִין אוֹתָהּ עַד שֶׁתִּתְיַשֵּׁב דַּעְתָּהּ:","וְכֵן הַחוֹלֶה שֶׁהֵרִיחַ דָּבָר שֶׁיֵּשׁ בּוֹ חֹמֶץ וְכַיּוֹצֵא בּוֹ מִדְּבָרִים שֶׁמְּעַרְעֲרִין אֶת הַנֶּפֶשׁ דִּינוֹ כְּעֻבָּרָה:","מִי שֶׁאָחֲזוֹ בֻּלְמוֹס מַאֲכִילִין אוֹתוֹ דְּבָרִים הָאֲסוּרִים מִיָּד עַד שֶׁיֵּאוֹרוּ עֵינָיו. וְאֵין מְחַזְּרִין עַל דָּבָר הַמֻּתָּר אֶלָּא מְמַהֲרִין בַּנִּמְצָא. וּמַאֲכִילִין אוֹתוֹ הַקַּל הַקַּל תְּחִלָּה. אִם הֵאִירוּ עֵינָיו דַּיּוֹ. וְאִם לָאו מַאֲכִילִין אוֹתוֹ הֶחָמוּר:","כֵּיצַד. הָיוּ לְפָנֵינוּ טֶבֶל וּנְבֵלָה מַאֲכִילִין אוֹתוֹ נְבֵלָה תְּחִלָּה שֶׁהַטֶּבֶל בְּמִיתָה. נְבֵלָה וּסְפִיחֵי שְׁבִיעִית מַאֲכִילִין אוֹתוֹ סְפִיחֵי שְׁבִיעִית שֶׁאֲסוּרִין מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת שְׁמִטָּה. טֶבֶל וּשְׁבִיעִית מַאֲכִילִין אוֹתוֹ שְׁבִיעִית. טֶבֶל וּתְרוּמָה אִם אִי אֶפְשָׁר לְתַקֵּן הַטֶּבֶל מַאֲכִילִין אוֹתוֹ טֶבֶל שֶׁאֵינוֹ קָדוֹשׁ כִּתְרוּמָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כְּבָר בֵּאַרְנוּ שֶׁאֵין אִסּוּר חָל עַל אִסּוּר אֶלָּא אִם הָיוּ שְׁנֵי הָאִסּוּרִין בָּאִין כְּאַחַת אוֹ שֶׁהָיָה אִסּוּר מוֹסִיף אוֹ אִסּוּר כּוֹלֵל. לְפִיכָךְ יֵשׁ אוֹכֵל כְּזַיִת אֶחָד וְלוֹקֶה עָלָיו חָמֵשׁ מַלְקִיּוֹת. וְהוּא שֶׁהִתְרוּ בּוֹ בַּחֲמִשָּׁה אִסּוּרִין שֶׁנִּתְקַבְּצוּ בּוֹ. כֵּיצַד. כְּגוֹן טָמֵא שֶׁאָכַל כְּזַיִת חֵלֶב שֶׁנּוֹתַר מִן הַמֻּקְדָּשִׁים בְּיוֹם הַכִּפּוּרִים לוֹקֶה מִשּׁוּם אוֹכֵל חֵלֶב. וּמִשּׁוּם אוֹכֵל נוֹתָר. וּמִשּׁוּם אוֹכֵל בְּיוֹם הַכִּפּוּרִים. וּמִשּׁוּם טָמֵא שֶׁאָכַל קֹדֶשׁ. וּמִשּׁוּם שֶׁנֶּהֱנָה מִן הַקֹּדֶשׁ וּמָעַל:","וְלָמָּה חָל כָּאן אִסּוּר עַל אִסּוּר. שֶׁבְּהֵמָה זוֹ הָיָה חֶלְבָּהּ אָסוּר בַּאֲכִילָה וּמֻתָּר בַּהֲנָיָה. הִקְדִּישָׁהּ נֶאֱסַר חֶלְבָּהּ בַּהֲנָיָה וּמִתּוֹךְ שֶׁנּוֹסַף בּוֹ אִסּוּר הֲנָיָה נוֹסַף עָלָיו אִסּוּר קָדָשִׁים. וַעֲדַיִן הָיָה חֵלֶב זֶה מֻתָּר לְגָבוֹהַּ וְאָסוּר לְהֶדְיוֹט. נַעֲשָׂה נוֹתָר מִתּוֹךְ שֶׁנּוֹסַף בּוֹ אִסּוּר לְגָבוֹהַּ נֶאֱסַר לְהֶדְיוֹט. וְהָאוֹכֵל הַזֶּה הָיָה מֻתָּר בִּבְשַׂר הַבְּהֵמָה וְאָסוּר בְּחֶלְבָּהּ. נִטְמָא נֶאֱסַר אַף בִּבְשָׂרָהּ נוֹסַף לוֹ אִסּוּר עַל הַחֵלֶב. בָּא יוֹם הַכִּפּוּרִים כָּלַל כָּל הָאֳכָלִין. וּמִתּוֹךְ שֶׁנֶּאֱסַר אַף בְּחֻלִּין נוֹסַף אִסּוּרוֹ בְּחֵלֶב זֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Forbidden Intercourse 1":["הַבָא עַל אַחַת מִכָּל הָעֲרָיוֹת הָאֲמוּרוֹת בַּתּוֹרָה בְּמֵזִיד חַיָּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא יח כט) \"כִּי כָּל אֲשֶׁר יַעֲשֶׂה מִכּל הַתּוֹעֵבוֹת הָאֵלֶּה וְנִכְרְתוּ הַנְּפָשׁוֹת\" וְגוֹ' שְׁנֵיהֶם הַבּוֹעֵל וְהַנִּבְעֶלֶת. וְאִם הָיוּ שׁוֹגְגִין חַיָּבִין חַטָּאת קְבוּעָה. וְיֵשׁ מִן הָעֲרָיוֹת שֶׁהוּא בְּמִיתַת בֵּית דִּין יֶתֶר עַל הַכָּרֵת הַשָּׁוֶה בְּכֻלָּן:","אוֹתָן הָעֲרָיוֹת שֶׁיֵּשׁ בָּהֶן מִיתַת בֵּית דִּין אִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה וְלֹא פָּרְשׁוּ מִמַּעֲשֵׂיהֶם מְמִיתִין אוֹתָן מִיתָה הָאֲמוּרָה בָּהֶן:","וַאֲפִלּוּ הָיָה הָעוֹבֵר תַּלְמִיד חָכָם אֵין מְמִיתִין וְלֹא מַלְקִין עַד שֶׁתִּהְיֶה שָׁם הַתְרָאָה. שֶׁלֹּא נִתְּנָה הַתְרָאָה בְּכָל מָקוֹם אֶלָּא לְהַבְחִין בֵּין שׁוֹגֵג לְמֵזִיד:","הָעֲרָיוֹת שֶׁיֵּשׁ בָּהֶן מִיתַת בֵּית דִּין מֵהֶן שֶׁמִּיתָתָן בִּסְקִילָה. וּמֵהֶן שֶׁמִּיתָתָן בִּשְׂרֵפָה. וּמֵהֶן שֶׁמִּיתָתָן בְּחֶנֶק. וְאֵלּוּ שֶׁמִּיתָתָן בִּסְקִילָה. הַבָּא עַל אִמּוֹ. וְעַל אֵשֶׁת אָבִיו. וְעַל אֵשֶׁת בְּנוֹ וְהִיא הַנִּקְרֵאת כַּלָּתוֹ. וְהַשּׁוֹכֵב עִם זָכָר. וְהַשּׁוֹכֵב עִם בְּהֵמָה. וְהָאִשָּׁה הַמְּבִיאָה אֶת הַבְּהֵמָה עָלֶיהָ:","וְאֵלּוּ הֵן הָעֲרָיוֹת שֶׁמִּיתָתָן בִּשְׂרֵפָה. הַבָּא עַל בַּת אִשְׁתּוֹ בְּחַיֵּי אִשְׁתּוֹ. וְעַל בַּת בִּתָּהּ. וְעַל בַּת בְּנָהּ. וְעַל אֵם אִשְׁתּוֹ. וְעַל אֵם אִמָּהּ. וְעַל אֵם אָבִיהָ. וְהַבָּא עַל בִּתּוֹ. וְעַל בַּת בִּתּוֹ. וְעַל בַּת בְּנוֹ:","אֵין לְךָ עֶרְוָה בְּחֶנֶק אֶלָּא אֵשֶׁת אִישׁ בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כ י) \"מוֹת יוּמַת הַנֹּאֵף וְהַנֹּאָפֶת\" וּמִיתָה הָאֲמוּרָה בַּתּוֹרָה סְתָם הִיא חֶנֶק. וְאִם הָיְתָה בַּת כֹּהֵן הִיא בִּשְׂרֵפָה וּבוֹעֲלָהּ בְּחֶנֶק שֶׁנֶּאֱמַר (ויקרא כא ט) \"וּבַת אִישׁ כֹּהֵן כִּי תֵחֵל לִזְנוֹת\" (ויקרא כא ט) \"בָּאֵשׁ תִּשָּׂרֵף\". וְאִם הָיְתָה נַעֲרָה מְאֹרָשָׂה שְׁנֵיהֶם בִּסְקִילָה שֶׁנֶּאֱמַר (דברים כב כד) \"כִּי תִּהְיֶה נַעֲרָה בְתוּלָה\" וְגוֹ' (דברים כב כד) \"וּסְקַלְתֶּם אֹתָם בָּאֲבָנִים\". וְכָל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה(ויקרא כ יג) (ויקרא כ טז) \"מוֹת יוּמְתוּ דְּמֵיהֶם בָּם\" הֲרֵי הֵן בִּסְקִילָה:","שְׁאָר הָעֲרָיוֹת כֻּלָּן בְּכָרֵת בִּלְבַד וְאֵין בָּהֶם מִיתַת בֵּית דִּין. לְפִיכָךְ אִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה בֵּית דִּין מַלְקִין אוֹתָן. שֶׁכָּל חַיָּבֵי כְּרֵתוֹת לוֹקִין:","הַבָּא עַל אַחַת מֵחַיָּבֵי לָאוִין בְּמֵזִיד. הוּא לוֹקֶה וְהִיא. וְאִם בְּשׁוֹגֵג פְּטוּרִין מִכְּלוּם. וְהַבָּא עַל אַחַת מֵהַשְּׁנִיּוֹת בְּמֵזִיד מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם. אֲבָל הַבָּא עַל אַחַת מֵחַיָּבֵי עֲשֵׂה אֵינוֹ לוֹקֶה. וְאִם הִכּוּ אוֹתָם בֵּית דִּין מַכַּת מַרְדּוּת כְּדֵי לְהַרְחִיק מִן הָעֲבֵרָה הָרְשׁוּת בְּיָדָם:","אָנוּס פָּטוּר מִכְּלוּם מִן הַמַּלְקוֹת וּמִן הַקָּרְבָּן וְאֵין צָרִיךְ לוֹמַר מִן הַמִּיתָה שֶׁנֶּאֱמַר (דברים כב כו) \"וְלַנַּעֲרָה לֹא תַעֲשֶׂה דָבָר\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנֶּאֱנַס הַנִּבְעָל. אֲבָל הַבּוֹעֵל אֵין לוֹ אֹנֶס שֶׁאֵין קִשּׁוּי אֶלָּא לְדַעַת. וְאִשָּׁה שֶׁתְּחִלַּת בִּיאָתָהּ בְּאֹנֶס וְסוֹפָהּ בְּרָצוֹן פְּטוּרָה מִכְּלוּם שֶׁמִּשֶּׁהִתְחִיל לִבְעל בְּאֹנֶס אֵין בְּיָדָהּ שֶׁלֹּא תִּרְצֶה שֶׁיֵּצֶר הָאָדָם וְטִבְעוֹ כּוֹפֶה אוֹתָהּ לִרְצוֹת:","הַמַּכְנִיס רֹאשׁ הָעֲטָרָה בִּלְבַד הוּא הַנִּקְרָא מְעָרֶה מִלְּשׁוֹן (ויקרא כ יח) \"אֶת מְקֹרָהּ הֶעֱרָה\". וְהַמַּכְנִיס כָּל הָאֵיבָר הוּא הַנִּקְרָא גּוֹמֵר. וּבְכָל הַבִּיאוֹת הָאֲסוּרוֹת אֶחָד הַמְעָרֶה וְאֶחָד הַגּוֹמֵר וְאַף עַל פִּי שֶׁלֹּא הוֹצִיא שִׁכְבַת זֶרַע וְאַף עַל פִּי שֶׁפֵּרַשׁ וְלֹא גָּמַר כֵּיוָן שֶׁהִכְנִיס רֹאשׁ הָעֲטָרָה נִתְחַיְּבוּ שְׁנֵיהֶם מִיתַת בֵּית דִּין אוֹ כָּרֵת אוֹ מַלְקוֹת אוֹ מַכַּת מַרְדּוּת. (וְאֶחָד הַבָּא עַל הָעֶרְוָה כְּדַרְכָּהּ וְאֶחָד הַבָּא עָלֶיהָ שֶׁלֹּא כְּדַרְכָּהּ) מִשֶּׁיְּעָרֶה בָּהּ יִתְחַיְּבוּ שְׁנֵיהֶן מִיתָה אוֹ כָּרֵת אוֹ מַלְקוֹת אוֹ מַכַּת מַרְדּוּת בֵּין שֶׁהָיוּ שׁוֹכְבִין בֵּין שֶׁהָיוּ עוֹמְדִים עַל הַכְנָסַת הָעֲטָרָה הוּא הַחִיּוּב:","כָּל הַבָּא בִּיאָה אֲסוּרָה בְּלֹא קִשּׁוּי. אֶלָּא שֶׁהָיָה הָאֵיבָר שֶׁלּוֹ מְדֻלְדָּל כְּמוֹ אֵיבָר הַמֵּתִים כְּגוֹן הַחוֹלִים. אוֹ מִי שֶׁנּוֹלַד כָּךְ כְּגוֹן סְרִיס חַמָּה אַף עַל פִּי שֶׁהִכְנִיס אֶת הָאֵיבָר בְּיָדוֹ אֵינוֹ חַיָּב לֹא כָּרֵת וְלֹא מַלִקוֹת וִאֵין צָרִיךְ לוֹמַר מִיתָה. שֵׁאֵין זוֹ בִּיאָה. אֲבָל פּוֹסֵל הוּא מִן הַתִּרוּמָה. וּבֵית דִּין מַכִּין אֵת שִׁנֵיהֵם מַכַּת מַרִדּוּת:","הַבָּא עַל עֶרְוָה מִן הָעֲרָיוֹת כְּמִתְעַסֵּק אַף עַל פִּי שֶׁאֵין כַּוָּנָתוֹ לְכָךְ חַיָּב. וְכֵן בְּחַיָּבֵי לָאוִין וּבִשְׁנִיּוֹת. אֲבָל הַבָּא עַל עֶרְוָה מִן הָעֲרָיוֹת וְהִיא מֵתָה פָּטוּר מִכְּלוּם. וְאֵין צָרִיךְ לוֹמַר בְּחַיָּבֵי לָאוִין שֶׁהוּא פָּטוּר. וְהַבָּא עַל הַטְּרֵפָה אוֹ שֶׁשָּׁכַב עִם בְּהֵמָה טְרֵפָה חַיָּב. חַי הוּא אַף עַל פִּי שֶׁסּוֹפוֹ לָמוּת מֵחלִי זֶה. וַאֲפִלּוּ שָׁחַט בָּהּ שְׁנֵי סִימָנִין וַעֲדַיִן הִיא מְפַרְכֶּסֶת הַבָּא עָלֶיהָ חַיָּב עַד שֶׁתָּמוּת אוֹ עַד שֶׁיַּתִּיז רֹאשָׁהּ:","כָּל אִשָּׁה אֲסוּרָה מֵאֵלּוּ אִם הָיְתָה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד וָמַעְלָה גָּדוֹל הַבָּא עָלֶיהָ חַיָּב מִיתָה אוֹ כָּרֵת אוֹ מַלְקוֹת וְהִיא פְּטוּרָה מִכְּלוּם אֶלָּא אִם כֵּן הָיְתָה גְּדוֹלָה. וְאִם הָיְתָה פְּחוּתָה מִזֶּה הֲרֵי שְׁנֵיהֶן פְּטוּרִין שֶׁאֵין בִּיאָתָהּ בִּיאָה. וְכֵן אִשָּׁה גְּדוֹלָה שֶׁבָּא עָלֶיהָ קָטָן אִם הָיָה בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וָמַעְלָה הִיא חַיֶּבֶת כָּרֵת אוֹ מִיתָה אוֹ מַלְקוֹת וְהוּא פָּטוּר. וְאִם הָיָה בֶּן תֵּשַׁע שָׁנִים וּלְמַטָּה שְׁנֵיהֶם פְּטוּרִין:","הַבָּא עַל הַזָּכָר אוֹ הֵבִיא זָכָר עָלָיו כֵּיוָן שֶׁהֶעֱרָה אִם הָיוּ שְׁנֵיהֶם גְּדוֹלִים נִסְקָלִים שֶׁנֶּאֱמַר (ויקרא יח כב) \"וְאֶת זָכָר לֹא תִשְׁכָּב\" בֵּין שֶׁהָיָה בּוֹעֵל אוֹ נִבְעָל. וְאִם הָיָה קָטָן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וָמַעְלָה זֶה שֶׁבָּא עָלָיו אוֹ הֱבִיאוֹ עַל עַצְמוֹ נִסְקָל וְהַקָּטָן פָּטוּר. וְאִם הָיָה הַזָּכָר בֶּן תֵּשַׁע אוֹ פָּחוֹת שְׁנֵיהֶן פְּטוּרִין וְרָאוּי לְבֵית דִּין לְהַכּוֹת הַגָּדוֹל מַכַּת מַרְדּוּת לְפִי שֶׁשָּׁכַב עִם זָכָר וְאַף עַל פִּי שֶׁהוּא פָּחוֹת מִבֶּן תֵּשַׁע:","[אֶחָד הַבָּא עַל הַזָּכָר אוֹ] הַבָּא עַל אַנְדְּרוֹגִינוּס דֶּרֶךְ זִכְרוּתוֹ חַיָּב. [וְאִם בָּא עָלָיו דֶּרֶךְ נְקֵבוּתוֹ פָּטוּר] וְהַטֻּמְטוּם סָפֵק הוּא לְפִיכָךְ הַבָּא עַל הַטֻּמְטוּם אוֹ עַל אַנְדְּרוֹגִינוּס [דֶּרֶךְ נְקֵבוּתוֹ] מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת וְהָאַנְדְּרוֹגִינוּס מֻתָּר לִשָּׂא אִשָּׁה:","הַבָּא עַל הַבְּהֵמָה אוֹ שֶׁהֵבִיא בְּהֵמָה עָלָיו שְׁנֵיהֶן נִסְקָלִין שֶׁנֶּאֱמַר (ויקרא יח כג) \"וּבְכָל בְּהֵמָה לֹא תִתֵּן שְׁכָבְתְּךָ\" בֵּין שֶׁרִבְּעָהּ אוֹ הֱבִיאָהּ עָלָיו. וְאֶחָד בְּהֵמָה וְאֶחָד חַיָּה וָעוֹף הַכּל בִּסְקִילָה. וְלֹא חִלַּק הַכָּתוּב בִּבְהֵמָה בֵּין גְּדוֹלָה לִקְטַנָּה שֶׁנֶּאֱמַר וּבְכָל בְּהֵמָה אֲפִלּוּ בְּיוֹם לֵדָתָהּ (הַבָּא עָלֶיהָ בֵּין כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ) כֵּיוָן שֶׁהֶעֱרָה בָּהּ אוֹ שֶׁהֶעֶרְתָה בּוֹ חַיָּב:","קָטָן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל הַבְּהֵמָה אוֹ הֱבִיאָהּ עָלָיו הִיא נִסְקֶלֶת עַל יָדוֹ וְהוּא פָּטוּר. הָיָה בֶּן תֵּשַׁע אוֹ פָּחוֹת אֵין סוֹקְלִין אֶת הַבְּהֵמָה. וְכֵן קְטַנָּה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד שֶׁהֵבִיאָה בְּהֵמָה וְחַיָּה עָלֶיהָ בֵּין בְּהֵמָה גְּדוֹלָה בֵּין בְּהֵמָה קְטַנָּה כֵּיוָן שֶׁהֶעֶרְתָה בָּהּ הַבְּהֵמָה (בֵּין כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ) הַבְּהֵמָה נִסְקֶלֶת וְהִיא פְּטוּרָה. וְאִם הָיְתָה גְּדוֹלָה שְׁנֵיהֶן נִסְקָלִין. וְאִם הָיְתָה מִבַּת שָׁלֹשׁ שָׁנִים וּלְמַטָּה אֵין הַבְּהֵמָה נִסְקֶלֶת:","וְכֵן הַשּׁוֹכֵב עִם הַבְּהֵמָה בִּשְׁגָגָה וְהָאִשָּׁה שֶׁהֵבִיאָה אֶת הַבְּהֵמָה עָלֶיהָ בִּשְׁגָגָה אֵין הַבְּהֵמָה נִסְקֶלֶת עַל יָדָן וְאַף עַל פִּי שֶׁהֵן גְּדוֹלִים. כָּל הָעֲרָיוֹת כֻּלָּן שֶׁהָיָה אֶחָד גָּדוֹל וְאֶחָד קָטָן הַקָּטָן פָּטוּר וְהַגָּדוֹל חַיָּב כְּמוֹ שֶׁבֵּאַרְנוּ. אֶחָד עֵר וְאֶחָד יָשֵׁן הַיָּשֵׁן פָּטוּר. אֶחָד מֵזִיד וְאֶחָד שׁוֹגֵג הַמֵּזִיד חַיָּב וְהַשּׁוֹגֵג מֵבִיא קָרְבָּן. אֶחָד אָנוּס וְאֶחָד בְּרָצוֹן הָאָנוּס פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין הָעֵדִים נִזְקָקִין לִרְאוֹת הַמְנָאֲפִים שֶׁהֶעֱרוּ זֶה בָּזֶה וְהִכְנִיס כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת. אֶלָּא מִשֶּׁיִּרְאוּ אוֹתָן דְּבוּקִין זֶה עִם זֶה כְּדֶרֶךְ כָּל הַבּוֹעֲלִין הֲרֵי אֵלּוּ נֶהֱרָגִין בִּרְאִיָּה זוֹ. וְאֵין אוֹמְרִים שֶׁמָּא לֹא הֶעֱרָה, מִפְּנֵי שֶׁחֶזְקַת צוּרָה זוֹ שֶׁהֶעֱרָה:","מִי שֶׁהֻחְזַק בִּשְׁאֵר בָּשָׂר דָּנִין בּוֹ עַל פִּי הַחֲזָקָה. אַף עַל פִּי שֶׁאֵין שָׁם רְאָיָה בְּרוּרָה שֶׁזֶּה קָרוֹב. וּמַלְקִין וְשׂוֹרְפִין וְסוֹקְלִין וְחוֹנְקִין עַל חֲזָקָה זוֹ. כֵּיצַד. הֲרֵי שֶׁהֻחְזַק שֶׁזּוֹ אֲחוֹתוֹ אוֹ בִּתּוֹ אוֹ אִמּוֹ וּבָא עָלֶיהָ בְּעֵדִים הֲרֵי זֶה לוֹקֶה אוֹ נִשְׂרָף אוֹ נִסְקָל וְאַף עַל פִּי שֶׁאֵין שָׁם רְאָיָה בְּרוּרָה שֶׁזּוֹ הִיא אֲחוֹתוֹ אוֹ אִמּוֹ אוֹ בִּתּוֹ אֶלָּא בַּחֲזָקָה בִּלְבַד. וּמַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁבָּאת לִירוּשָׁלַיִם וְתִינוֹק מֻרְכָּב לָהּ עַל כְּתֵפָהּ וְהִגְדִּילַתּוּ בְּחֶזְקַת שֶׁהוּא בְּנָהּ וּבָא עָלֶיהָ וֶהֱבִיאוּהָ לְבֵית דִּין וּסְקָלוּהָ. רְאָיָה לְדִין זֶה מַה שֶּׁדָּנָה תּוֹרָה בִּמְקַלֵּל אָבִיו וּמַכֶּה אָבִיו שֶׁיּוּמַת. וּמִנַּיִן לָנוּ רְאָיָה בְּרוּרָה שֶׁזֶּה אָבִיו, אֶלָּא בַּחֲזָקָה, כָּךְ שְׁאָר קְרוֹבִים בַּחֲזָקָה:","אִישׁ וְאִשָּׁה שֶׁבָּאוּ מִמְּדִינַת הַיָּם הוּא אוֹמֵר זֹאת אִשְׁתִּי וְהִיא אוֹמֶרֶת זֶה בַּעְלִי. אִם הֻחְזְקָה בָּעִיר שְׁלֹשִׁים יוֹם שֶׁהִיא אִשְׁתּוֹ הוֹרְגִין עָלֶיהָ. אֲבָל בְּתוֹךְ הַשְּׁלֹשִׁים יוֹם אֵין הוֹרְגִין עָלֶיהָ מִשּׁוּם אֵשֶׁת אִישׁ:","הָאִשָּׁה שֶׁהֻחְזְקָה נִדָּה בִּשְׁכוּנוֹתֶיהָ בַּעְלָהּ לוֹקֶה עָלֶיהָ מִשּׁוּם נִדָּה. הַמְקַנֵּא לְאִשְׁתּוֹ וְנִסְתְּרָה וּבָא עֵד אֶחָד וְהֵעִיד שֶׁנִּטְמְאָה וְהָיָה בַּעְלָהּ כֹּהֵן וּבָא עָלֶיהָ אַחַר כָּךְ הֲרֵי זֶה לוֹקֶה עָלֶיהָ מִשּׁוּם זוֹנָה. אַף עַל פִּי שֶׁעִקַּר הָעֵדוּת בְּעֵד אֶחָד כְּבָר הֻחְזְקָה בְּזוֹנָה:","הָאָב שֶׁאָמַר בִּתִּי זוֹ מְקֻדֶּשֶׁת הִיא לָזֶה אַף עַל פִּי שֶׁהוּא נֶאֱמָן וְתִנָּשֵׂא לוֹ אִם זִנְּתָה אֵינָהּ נִסְקֶלֶת עַל פִּיו עַד שֶׁיִּהְיוּ שָׁם עֵדִים שֶׁנִּתְאָרְסָה בִּפְנֵיהֶם. וְכֵן הָאִשָּׁה שֶׁאָמְרָה מְקֻדֶּשֶׁת אֲנִי אֵינָהּ נֶהֱרֶגֶת עַל פִּיהָ עַד שֶׁיִּהְיוּ שָׁם עֵדִים אוֹ תֻּחְזַק:"],"Mishneh Torah, Forbidden Intercourse 20":["כָּל כֹּהֲנִים בַּזְּמַן הַזֶּה בַּחֲזָקָה הֵם כֹּהֲנִים וְאֵין אוֹכְלִין אֶלָּא בְּקָדְשֵׁי הַגְּבוּל. וְהוּא שֶׁתִּהְיֶה תְּרוּמָה שֶׁל דִּבְרֵיהֶם. אֲבָל תְּרוּמָה שֶׁל תּוֹרָה וְחַלָּה שֶׁל תּוֹרָה אֵין אוֹכֵל אוֹתָהּ אֶלָּא כֹּהֵן מְיֻחָס:","אֵי זֶהוּ כֹּהֵן מְיֻחָס כָּל שֶׁהֵעִידוּ לוֹ שְׁנֵי עֵדִים שֶׁהוּא כֹּהֵן בֶּן פְּלוֹנִי הַכֹּהֵן וּפְלוֹנִי בֶּן פְּלוֹנִי הַכֹּהֵן עַד אִישׁ שֶׁאֵינוֹ צָרִיךְ בְּדִיקָה וְהוּא הַכֹּהֵן שֶׁשִּׁמֵּשׁ עַל גַּבֵּי הַמִּזְבֵּחַ. שֶׁאִלּוּ לֹא בָּדְקוּ בֵּית דִּין הַגָּדוֹל אַחֲרָיו לֹא הָיוּ מְנִיחִין אוֹתוֹ לַעֲבֹד. לְפִיכָךְ אֵין בּוֹדְקִין מֵהַמִּזְבֵּחַ וָמַעְלָה וְלֹא מִן הַסַּנְהֶדְרִין וָמַעְלָה. שֶׁאֵין מְמַנִּין בַּסַּנְהֶדְרִין אֶלָּא כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים מְיֻחָסִין:","חַלָּה בַּזְּמַן הַזֶּה וַאֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אֵינָהּ שֶׁל תּוֹרָה שֶׁנֶּאֱמַר (במדבר טו יח) \"בְּבֹאֲכֶם אֶל הָאָרֶץ\" בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְצַתְכֶם. וּכְשֶׁעָלוּ בִּימֵי עֶזְרָא לֹא עָלוּ כֻּלָּם. וְכֵן תְּרוּמָה בַּזְּמַן הַזֶּה שֶׁל דִּבְרֵי סוֹפְרִים וּלְפִיכָךְ אוֹכְלִים אוֹתָהּ הַכֹּהֲנִים שֶׁבִּזְמַנֵּינוּ שֶׁהֵן בַּחֲזָקָה:","מִי שֶׁהֵעִידוּ עָלָיו [שְׁנֵי] עֵדִים שֶׁרָאוּהוּ שֶׁהָיָה אוֹכֵל בִּתְרוּמָה שֶׁל תּוֹרָה הֲרֵי זֶה מְיֻחָס. וְאֵין מַעֲלִין לְיוּחֲסִין לֹא מִנְּשִׂיאַת כַּפַּיִם וְלֹא מִקְּרִיאָה בַּתּוֹרָה רִאשׁוֹן וְלֹא מֵחִלּוּק תְּרוּמָה בְּבֵית הַגְּרָנוֹת וְלֹא עַל פִּי עֵד אֶחָד:","כֹּהֵן מְיֻחָס שֶׁאָמַר בְּנִי זֶה כֹּהֵן הוּא אֵין מַעֲלִין אוֹתוֹ לְיוּחֲסִין עַל פִּיו עַד שֶׁיָּבִיא עֵדִים שֶׁהוּא בְּנוֹ:","כֹּהֵן מְיֻחָס שֶׁיָּצָא הוּא וְאִשְׁתּוֹ שֶׁיָּדַעְנוּ שֶׁהִיא כְּשֵׁרָה לִמְדִינָה אַחֶרֶת וּבָא הוּא וְהִיא וּבָנִים כְּרוּכִין אַחֲרֵיהֶן וְאָמַר אִשָּׁה שֶׁיָּצָאת עִמִּי הִיא זוֹ וְאֵלּוּ בָּנֶיהָ אֵינוֹ צָרִיךְ לְהָבִיא עֵדִים לֹא עַל הָאִשָּׁה וְלֹא עַל הַבָּנִים. מֵתָה וְאֵלּוּ בָּנֶיהָ צָרִיךְ לְהָבִיא עֵדִים שֶׁאֵלּוּ בָּנָיו. וְאֵינוֹ צָרִיךְ לְהָבִיא עֵדִים עַל אִמָּן שֶׁהִיא כְּשֵׁרָה. מִפְּנֵי שֶׁכְּבָר הֻחְזַק שֶׁיָּצְאָה מֵעִמָּנוּ כְּאִשָּׁה כְּשֵׁרָה:","יָצָא כֹּהֵן מְיֻחָס לִמְדִינָה אַחֶרֶת וּבָא הוּא וְאִשְׁתּוֹ וּבָנָיו וְאָמַר אִשָּׁה זוֹ נָשָׂאתִי וְאֵלּוּ בָּנֶיהָ צָרִיךְ לְהָבִיא רְאָיָה שֶׁאִשָּׁה זוֹ כְּשֵׁרָה. וְאֵינוֹ מֵבִיא עֵדִים שֶׁאֵלּוּ בָּנֶיהָ. וְהוּא שֶׁיִּהְיוּ כְּרוּכִין אַחֲרֶיהָ. וְאִם בָּא בִּשְׁתֵּי נָשִׁים וְהֵבִיא רְאָיָה עַל הָאַחַת אַף עַל פִּי שֶׁהַבָּנִים קְטַנִּים וּכְרוּכִין אַחֲרֶיהָ צָרִיךְ לְהָבִיא רְאָיָה עֲלֵיהֶם שֶׁמָּא בָּנָיו מִן הָאַחֶרֶת הֵם וְנִכְרְכוּ אַחַר זוֹ הַמְיֻחֶסֶת:","בָּא הוּא וּבָנָיו וְאָמַר אִשָּׁה נָשָׂאתִי וָמֵתָה וְאֵלּוּ בָּנֶיהָ מֵבִיא עֵדִים שֶׁאוֹתָהּ הָאִשָּׁה כְּשֵׁרָה הָיְתָה וְאֵלּוּ בָּנֶיהָ. וְכַדִּין הַזֶּה דָּנִין בְּיִשְׂרָאֵל מְיֻחָס וּבְלֵוִי מְיֻחָס. וְאַחַר כָּךְ נָעִיד עַל בְּנוֹ זֶה שֶׁהוּא מְיֻחָס כְּדֵי שֶׁיִּהְיֶה רָאוּי לְסַנְהֶדְרִין:","אֵין מַעֲלִין מִשְּׁטָרוֹת לִכְהֻנָּה. כֵּיצַד. הֲרֵי שֶׁהָיָה כָּתוּב בִּשְׁטָר פְּלוֹנִי כֹּהֵן לָוָה מִפְּלוֹנִי וְהִלְוָהוּ כָּךְ וְכָךְ וְהָעֵדִים מִלְּמַטָּה אֵין מַחֲזִיקִין בָּהֶם כֹּהֵן זֶה שֶׁהוּא מְיֻחָס שֶׁמָּא לֹא הֵעִידוּ אֶלָּא עַל הַמִּלְוֶה. בַּמֶּה דְּבָרִים אֲמוּרִים לְעִנְיַן יִחוּס. אֲבָל לַחֲזָקָה שֶׁיִּהְיֶה כֹּהֵן כְּכֹהֲנֵי זְמַן זֶה וְיֹאכַל תְּרוּמָה וְחַלָּה שֶׁל דִּבְרֵי סוֹפְרִים וּבִשְׁאָר קָדְשֵׁי הַגְּבוּל מַעֲלִין מִן הַשְּׁטָרוֹת וְעַל פִּי עֵד אֶחָד וּמִנְּשִׂיאוּת כַּפַּיִם וּמִקְּרִיאָה בַּתּוֹרָה רִאשׁוֹן:","וְכֵן כָּל כֹּהֵן שֶׁאָמַר בְּנִי זֶה כֹּהֵן נֶאֱמָן לְהַאֲכִילוֹ בִּתְרוּמָה וְלִהְיוֹתוֹ בְּחֶזְקַת כֹּהֵן וְאֵינוֹ צָרִיךְ לְהָבִיא רְאָיָה לֹא עַל הַבָּנִים וְלֹא עַל הָאִשָּׁה:","שְׁנַיִם שֶׁבָּאוּ לִמְדִינָה זֶה אוֹמֵר אֲנִי וַחֲבֵרִי כֹּהֵן וְזֶה אוֹמֵר אֲנִי וַחֲבֵרִי כֹּהֵן אַף עַל פִּי שֶׁנִּרְאִין כְּגוֹמְלִין זֶה אֶת זֶה הֲרֵי אֵלּוּ נֶאֱמָנִין וּשְׁנֵיהֶם בְּחֶזְקַת כֹּהֲנִים. וְכֵן עֵד שֶׁאָמַר רָאִיתִי זֶה שֶׁנָּשָׂא כַּפָּיו אוֹ שֶׁאָכַל בִּתְרוּמָה אוֹ שֶׁחָלַק עַל הַגֹּרֶן אוֹ שֶׁקָּרָא בַּתּוֹרָה רִאשׁוֹן וְקָרָא אַחֲרָיו לֵוִי מַחֲזִיקִין אוֹתוֹ בִּכְהֻנָּה עַל פִּיו. וְכֵן אִם הֵעִיד שֶׁזֶּה קָרָא שֵׁנִי בַּתּוֹרָה אַחַר כֹּהֵן מַחֲזִיקִין אוֹתוֹ בִּלְוִיָּה:","הֵעִיד שֶׁרָאָה זֶה שֶׁחָלַק עִם אָחִיו בְּבֵית דִּין תְּרוּמָה שֶׁהִנִּיחַ לָהֶן אֲבִיהֶן הַכֹּהֵן אֵין מַעֲלִין אוֹתוֹ לִכְהֻנָּה בְּעֵדוּת זוֹ. שֶׁמָּא חָלָל הוּא וְלָקַח חֵלֶק יְרֻשָּׁתוֹ מִתְּרוּמָה לְמָכְרָהּ:","מִי שֶׁבָּא בַּזְּמַן הַזֶּה וְאָמַר כֹּהֵן אֲנִי אֵינוֹ נֶאֱמָן וְאֵין מַעֲלִין אוֹתוֹ לִכְהֻנָּה עַל פִּי עַצְמוֹ וְלֹא יִקְרָא בַּתּוֹרָה רִאשׁוֹן וְלֹא יִשָּׂא אֶת כַּפָּיו וְלֹא יֹאכַל בְּקָדְשֵׁי הַגְּבוּל עַד שֶׁיִּהְיֶה לוֹ עֵד אֶחָד. אֲבָל אוֹסֵר עַצְמוֹ בִּגְרוּשָׁה וְזוֹנָה וַחֲלָלָה וְאֵינוֹ מִטַּמֵּא לְמֵתִים. וְאִם נָשָׂא אוֹ נִטְמָא לוֹקֶה. וְהַנִּבְעֶלֶת לוֹ סְפֵק חֲלָלָה:","וְאִם הָיָה מֵסִיחַ לְפִי תֻּמּוֹ נֶאֱמָן. כֵּיצַד. מַעֲשֶׂה בְּאֶחָד שֶׁהָיָה מֵסִיחַ לְפִי תֻּמּוֹ וְאָמַר זָכוּר אֲנִי כְּשֶׁהָיִיתִי תִּינוֹק וְהָיִיתִי מֻרְכָּב עַל כְּתֵפוֹ שֶׁל אָבִי הוֹצִיאוּנִי מִבֵּית הַסֵּפֶר וְהִפְשִׁיטוּנִי כֻּתָּנְתִּי וְהִטְבִּילוּנִי לֶאֱכל תְּרוּמָה לָעֶרֶב וַחֲבֵרַי בּוֹדְלִין מִמֶּנִּי וְהָיוּ קוֹרְאִין אוֹתִי יוֹחָנָן אוֹכֵל חַלּוֹת וְהֶעֱלָהוּ רַבֵּנוּ הַקָּדוֹשׁ לִכְהֻנָּה עַל פִּי עַצְמוֹ:","נֶאֱמָן גָּדוֹל לוֹמַר זָכוּר אֲנִי כְּשֶׁהָיִיתִי תִּינוֹק וְרָאִיתִי פְּלוֹנִי טוֹבֵל וְאוֹכֵל בִּתְרוּמָה לָעֶרֶב וּמַחֲזִיקִין אוֹתוֹ בִּכְהֻנָּה בְּעֵדוּתוֹ. מִי שֶׁבָּא בַּזְּמַן הַזֶּה וְאָמַר כֹּהֵן אֲנִי וְעֵד אֶחָד מֵעִיד לוֹ שֶׁאֲנִי יוֹדֵעַ שֶׁאָבִיו שֶׁל זֶה כֹּהֵן אֵין מַעֲלִין אוֹתוֹ לִכְהֻנָּה בְּעֵדוּת זֶה שֶׁמָּא חָלָל הוּא עַד שֶׁיָּעִיד שֶׁזֶּה כֹּהֵן הוּא. אֲבָל אִם הֻחְזַק אָבִיו כֹּהֵן אוֹ שֶׁבָּאוּ שְׁנַיִם וְהֵעִידוּ שֶׁאָבִיו שֶׁל זֶה כֹּהֵן הֲרֵי הוּא בְּחֶזְקַת אָבִיו:","מִי שֶׁהֻחְזַק אָבִיו כֹּהֵן וְיָצָא עָלָיו קוֹל שֶׁהוּא בֶּן גְּרוּשָׁה אוֹ חֲלוּצָה חוֹשְׁשִׁין לוֹ וּמוֹרִידִין אוֹתוֹ. בָּא עֵד אֶחָד אַחַר כָּךְ וְהֵעִיד שֶׁהוּא כָּשֵׁר מַעֲלִין אוֹתוֹ לִכְהֻנָּה עַל פִּיו. בָּאוּ שְׁנַיִם עֵדִים אַחַר כָּךְ וְהָעִידוּ שֶׁהוּא חָלָל מוֹרִידִין אוֹתוֹ מִן הַכְּהֻנָּה. בָּא עֵד אֶחָד וְהֵעִיד שֶׁהוּא כָּשֵׁר מַעֲלִין אוֹתוֹ לִכְהֻנָּה שֶׁזֶּה הָאַחֲרוֹן מִצְטָרֵף לְעֵד רִאשׁוֹן וַהֲרֵי שְׁנַיִם מְעִידִין שֶׁהוּא כָּשֵׁר וּשְׁנַיִם מְעִידִים שֶׁהוּא פָּסוּל יִדָּחוּ אֵלּוּ וְאֵלּוּ וְיִדָּחֶה הַקּוֹל שֶׁהַשְּׁנַיִם כְּמֵאָה וְיִשָּׁאֵר כֹּהֵן בְּחֶזְקַת אָבִיו:","אִשָּׁה שֶׁלֹּא שָׁהֲתָה שְׁלֹשָׁה חֳדָשִׁים אַחַר בַּעְלָהּ וְיָלְדָה. וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לְרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לְאַחֲרוֹן וְהָיָה אֶחָד מֵהֶן כֹּהֵן וְהַשֵּׁנִי יִשְׂרָאֵל הֲרֵי זֶה סְפֵק כֹּהֵן. וְכָךְ אִם נִתְעָרֵב וְלַד כֹּהֵן בִּוְלַד יִשְׂרָאֵל וְהִגְדִּילוּ הַתַּעֲרוֹבוֹת כָּל אֶחָד מֵהֶן סְפֵק כֹּהֵן. וְנוֹתְנִין עֲלֵיהֶן חֻמְרֵי יִשְׂרָאֵל וְחֻמְרֵי כֹּהֲנִים. נוֹשְׂאִין נָשִׁים הָרְאוּיוֹת לִכְהֻנָּה וְאֵין מִטַּמְּאִים לְמֵתִים וְלֹא אוֹכְלִין בִּתְרוּמָה. וְאִם נָשְׂאוּ גְּרוּשָׁה מוֹצִיאִין וְאֵינָן לוֹקִין:","שְׁנֵי כֹּהֲנִים שֶׁנִּתְעָרְבוּ וַלְדוֹתֵיהֶם. אוֹ אֵשֶׁת כֹּהֵן שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ שְׁלֹשָׁה חֳדָשִׁים וְנִשֵּׂאת לְכֹהֵן אַחֵר וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן. נוֹתְנִין לוֹ עַל הַוָּלָד חֻמְרֵי שְׁנֵיהֶם. הוּא אוֹנֵן עֲלֵיהֶם וְהֵן אוֹנְנִין עָלָיו. הוּא אֵין מְטַמֵּא לָהֶם וְהֵם אֵינָן מְטַמְּאִין לוֹ. וְעוֹלֶה בְּמִשְׁמָרוֹ שֶׁל זֶה וְשֶׁל זֶה. וְאֵין חוֹלֵק. וְאִם הָיוּ שְׁנֵיהֶם בְּמִשְׁמָר אֶחָד וּבֵית אָב אֶחָד נוֹטֵל חֵלֶק אֶחָד:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהֵן בָּאִין מִכֹּחַ נִשּׂוּאִין. אֲבָל בִּזְנוּת גָּזְרוּ חֲכָמִים שֶׁמְּשַׁתְּקִין אוֹתוֹ מִדִּין כְּהֻנָּה כְּלָל הוֹאִיל וְאֵינוֹ יוֹדֵעַ אָבִיו הַוַּדַּאי שֶׁנֶּאֱמַר (במדבר כה יג) \"וְהָיְתָה לּוֹ וּלְזַרְעוֹ אַחֲרָיו\" עַד שֶׁיִּהְיֶה זַרְעוֹ מְיֻחָס אַחֲרָיו:","כֵּיצַד. עֲשָׂרָה כֹּהֲנִים שֶׁפֵּרַשׁ אֶחָד מֵהֶם וּבָעַל שֶׁהֲרֵי הַוָּלָד כֹּהֵן וַדַּאי וְאַף עַל פִּי כֵן הוֹאִיל וְאֵינוֹ יוֹדֵעַ אָבִיו שֶׁיִּתְיַחֵס לוֹ מְשַׁתְּקִין אוֹתוֹ מִדִּין כְּהֻנָּה. וְאֵינוֹ עוֹבֵד וְלֹא אוֹכֵל וְלֹא חוֹלֵק. וְאִם נִטְמָא לְמֵתִים אוֹ נָשָׂא גְּרוּשָׁה לוֹקֶה שֶׁאֵין כָּאן סְפֵק הֶתֵּר:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 11":["אֵין הוֹלְכִין בְּחֻקּוֹת הָעוֹבְדֵי כּוֹכָבִים וְלֹא מִדַּמִּין לָהֶן לֹא בְּמַלְבּוּשׁ וְלֹא בְּשֵׂעָר וְכַיּוֹצֵא בָּהֶן שֶׁנֶּאֱמַר (ויקרא כ כג) \"וְלֹא תֵלְכוּ בְּחֻקּוֹת הַגּוֹי\". וְנֶאֱמַר (ויקרא יח ג) \"וּבְחֻקֹּתֵיהֶם לֹא תֵלֵכוּ\". וְנֶאֱמַר (דברים יב ל) \"הִשָּׁמֶר לְךָ פֶּן תִּנָּקֵשׁ אַחֲרֵיהֶם\". הַכּל בְּעִנְיָן אֶחָד הוּא מַזְהִיר שֶׁלֹּא יִדְמֶה לָהֶן. אֶלָּא יִהְיֶה הַיִּשְׂרָאֵל מֻבְדָּל מֵהֶן וְיָדוּעַ בְּמַלְבּוּשׁוֹ וּבִשְׁאָר מַעֲשָׂיו כְּמוֹ שֶׁהוּא מֻבְדָּל מֵהֶן בְּמַדָּעוֹ וּבְדֵעוֹתָיו. וְכֵן הוּא אוֹמֵר (ויקרא כ כו) \"וָאַבְדִּל אֶתְכֶם מִן הָעַמִּים\". לֹא יִלְבַּשׁ בְּמַלְבּוּשׁ הַמְיֻחָד לָהֶן. וְלֹא יְגַדֵּל צִיצִית רֹאשׁוֹ כְּמוֹ צִיצִית רֹאשָׁם. וְלֹא יְגַלֵּחַ מִן הַצְּדָדִין וְיַנִּיחַ הַשֵּׂעָר בָּאֶמְצַע כְּמוֹ שֶׁהֵן עוֹשִׂין וְזֶה הַנִּקְרָא בְּלוֹרִית. וְלֹא יְגַלֵּחַ הַשֵּׂעָר מִכְּנֶגֶד פָּנָיו מֵאֹזֶן לְאֹזֶן וְיַנִּיחַ הַפֶּרַע מִלְּאַחֲרָיו כְּדֶרֶךְ שֶׁעוֹשִׂין הֵן. וְלֹא יִבְנֶה מְקוֹמוֹת כְּבִנְיַן הֵיכָלוֹת שֶׁל עַכּוּ\"ם כְּדֵי שֶׁיִּכָּנְסוּ בָּהֶן רַבִּים כְּמוֹ שֶׁהֵן עוֹשִׂין. וְכָל הָעוֹשֶׂה אַחַת מֵאֵלּוּ וְכַיּוֹצֵא בָּהֶן לוֹקֶה:","עַכּוּ\"ם שֶׁהָיָה מִסְתַּפֵּר מִיִּשְׂרָאֵל כֵּיוָן שֶׁהִגִּיעַ לִבְלוֹרִיתוֹ קָרוֹב שָׁלֹשׁ אֶצְבָּעוֹת לְכָל רוּחַ שׁוֹמֵט אֶת יָדוֹ:","יִשְׂרָאֵל שֶׁהָיָה קָרוֹב לַמַּלְכוּת וְצָרִיךְ לֵישֵׁב לִפְנֵי מַלְכֵיהֶם וְהָיֳה לוֹ גְּנַאי לְפִי שֶׁלֹּא יִדְמֶה לָהֶן הֲרֵי זֶה מֻתָּר לִלְבּשׁ בְּמַלְבּוּשֵׁיהֶן וּלְגַלֵּחַ כְּנֶגֶד פָּנָיו כְּדֶרֶךְ שֶׁהֵן עוֹשִׂין:","אֵין מְנַחֲשִׁין כְּעַכּוּ\"ם שֶׁנֶּאֱמַר (ויקרא יט כו) \"לֹא תְנַחֲשׁוּ\". כֵּיצַד הוּא הַנַּחַשׁ. כְּגוֹן אֵלּוּ שֶׁאוֹמְרִים הוֹאִיל וְנָפְלָה פִּתִּי מִפִּי אוֹ נָפַל מַקְלִי מִיָּדִי אֵינִי הוֹלֵךְ לְמָקוֹם פְּלוֹנִי הַיּוֹם שֶׁאִם אֵלֵךְ אֵין חֲפָצַיי נַעֲשִׂים. הוֹאִיל וְעָבַר שׁוּעָל מִימִינִי אֵינִי יוֹצֵא מִפֶּתַח בֵּיתִי הַיּוֹם שֶׁאִם אֵצֵא יִפְגָּעֵנִי אָדָם רַמַּאי. וְכֵן אֵלּוּ שֶׁשּׁוֹמְעִים צִפְצוּף הָעוֹף וְאוֹמְרִים יִהְיֶה כָּךְ וְלֹא יִהְיֶה כָּךְ. טוֹב לַעֲשׂוֹת דָּבָר פְּלוֹנִי וְרַע לַעֲשׂוֹת דָּבָר פְּלוֹנִי. וְכֵן אֵלּוּ שֶׁאוֹמְרִים שְׁחֹט תַּרְנְגוֹל זֶה שֶׁקָּרָא עַרְבִית. שְׁחֹט תַּרְנְגלֶת זוֹ שֶׁקָּרְאָה כְּמוֹ תַּרְנְגוֹל. וְכֵן הַמֵּשִׂים סִימָנִים לְעַצְמוֹ אִם יֶאֱרַע לִי כָּךְ וְכָךְ אֶעֱשֶׂה דָּבָר פְּלוֹנִי וְאִם לֹא יֶאֱרַע לִי לֹא אֶעֱשֶׂה, כֶּאֱלִיעֶזֶר עֶבֶד אַבְרָהָם. וְכֵן כָּל כַּיּוֹצֵא בַּדְּבָרִים הָאֵלּוּ הַכּל אָסוּר. וְכָל הָעוֹשֶׂה מַעֲשֶׂה מִפְּנֵי דָּבָר מִדְּבָרִים אֵלּוּ לוֹקֶה:","מִי שֶׁאָמַר דִּירָה זוֹ שֶׁבָּנִיתִי סִימָן טוֹב הָיְתָה עָלַי. אִשָּׁה זוֹ שֶׁנָּשָׂאתִי וּבְהֵמָה זוֹ שֶׁקָּנִיתִי מְבֹרֶכֶת הָיְתָה מֵעֵת שֶׁקְּנִיתִיהָ עָשַׁרְתִּי. וְכֵן הַשּׁוֹאֵל לְתִינוֹק אֵי זֶה פָּסוּק אַתָּה לוֹמֵד אִם אָמַר לוֹ פָּסוּק מִן הַבְּרָכוֹת יִשְׂמַח וְיֹאמַר זֶה סִימָן טוֹב כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן מֻתָּר הוֹאִיל וְלֹא כִּוֵּן מַעֲשָׂיו וְלֹא נִמְנַע מִלַּעֲשׂוֹת אֶלָּא עָשָׂה זֶה סִימָן לְעַצְמוֹ לְדָבָר שֶׁכְּבָר הָיָה הֲרֵי זֶה מֻתָּר:","אֵיזֶהוּ קוֹסֵם זֶה הָעוֹשֶׂה מַעֲשֶׂה מִשְּׁאָר הַמַּעֲשִׂיּוֹת כְּדֵי שֶׁיִּשּׁוֹם וְתִפָּנֶה מַחֲשַׁבְתּוֹ מִכָּל הַדְּבָרִים עַד שֶׁיֹּאמַר דְּבָרִים שֶׁעֲתִידִים לִהְיוֹת וְיֹאמַר דָּבָר פְּלוֹנִי עָתִיד לִהְיוֹת אוֹ אֵינוֹ הוֹוֶה אוֹ שֶׁיֹּאמַר שֶׁרָאוּי לַעֲשׂוֹת כֵּן וְהִזָּהֲרוּ מִכָּךְ. יֵשׁ מִן הַקּוֹסְמִין שֶׁמְּשַׁמְּשִׁים בְּחל אוֹ בַּאֲבָנִים. וְיֵשׁ מִי שֶׁגּוֹהֵר לָאָרֶץ וְיָנוּעַ וְצוֹעֵק. וְיֵשׁ מִי שֶׁמִּסְתַּכֵּל בְּמַרְאָה שֶׁל בַּרְזֶל אוֹ בַּעֲשָׁשִׁית וּמְדַמִּין וְאוֹמְרִים. וְיֵשׁ מִי שֶׁנּוֹשֵׂא מַקֵּל בְּיָדוֹ וְנִשְׁעָן עָלָיו וּמַכֶּה בּוֹ עַד שֶׁתִּפָּנֶה מַחֲשַׁבְתּוֹ וּמְדַבֵּר. הוּא שֶׁהַנָּבִיא אוֹמֵר (הושע ד יב) \"עַמִּי בְּעֵצוֹ יִשְׁאָל וּמַקְלוֹ יַגִּיד לוֹ\":","אָסוּר לִקְסֹם וְלִשְׁאל לְקוֹסֵם אֶלָּא שֶׁהַשּׁוֹאֵל לְקוֹסֵם מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת אֲבָל הַקּוֹסֵם עַצְמוֹ אִם עָשָׂה מַעֲשֶׂה מִכָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן לוֹקֶה שֶׁנֶּאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ\" וְגוֹ' (דברים יח י) \"קֹסֵם קְסָמִים\":","אֵיזֶהוּ מְעוֹנֵן אֵלּוּ נוֹתְנֵי עִתִּים שֶׁאוֹמְרִים בְּאִצְטַגְנִינוּת יוֹם פְּלוֹנִי טוֹב יוֹם פְּלוֹנִי רַע יוֹם פְּלוֹנִי רָאוּי לַעֲשׂוֹת בּוֹ מְלָאכָה פְּלוֹנִית שָׁנָה פְּלוֹנִית אוֹ חֹדֶשׁ פְּלוֹנִי רַע לְדָבָר פְּלוֹנִי:","אָסוּר לְעוֹנֵן אַף עַל פִּי שֶׁלֹּא עָשָׂה מַעֲשֶׂה אֶלָּא הוֹדִיעַ אוֹתָן הַכְּזָבִים שֶׁהַכְּסִילִים מְדַמִּין שֶׁהֵן דִּבְרֵי אֱמֶת וְדִבְרֵי חֲכָמִים. וְכָל הָעוֹשֶׂה מִפְּנֵי הָאִצְטַגְנִינוּת וְכִוֵּן מְלַאכְתּוֹ אוֹ הֲלִיכָתוֹ בְּאוֹתוֹ הָעֵת שֶׁקָּבְעוּ הֹבְרֵי שָׁמַיִם הֲרֵי זֶה לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יט כו) \"לֹא תְעוֹנֵנוּ\". וְכֵן הָאוֹחֵז אֶת הָעֵינַיִם וּמְדַמֶּה בִּפְנֵי הָרוֹאִים שֶׁעוֹשֶׂה מַעֲשֵׂה תִּמָּהוֹן וְהוּא לֹא עָשָׂה הֲרֵי זֶה בִּכְלַל מְעוֹנֵן וְלוֹקֶה:","אֵיזֶהוּ חוֹבֵר זֶה שֶׁמְּדַבֵּר בִּדְבָרִים שֶׁאֵינָן לְשׁוֹן עַם וְאֵין לָהֶן עִנְיָן וּמַעֲלֶה עַל דַּעְתּוֹ בְּסִכְלוּתוֹ שֶׁאוֹתָן הַדְּבָרִים מוֹעִילִין. עַד שֶׁהֵן אוֹמְרִים שֶׁהָאוֹמֵר כָּךְ וְכָךְ עַל הַנָּחָשׁ אוֹ עַל הָעַקְרָב אֵינוֹ מַזִּיק וְהָאוֹמֵר כָּךְ וְכָךְ עַל הָאִישׁ אֵינוֹ נִזּוֹק. וּמֵהֶן אוֹחֵז בְּיָדוֹ בְּעֵת שֶׁמְּדַבֵּר מַפְתֵּחַ אוֹ סֶלַע וְכַיּוֹצֵא בַּדְּבָרִים הָאֵלּוּ הַכּל אָסוּר. וְהַחוֹבֵר עַצְמוֹ שֶׁאָחַז בְּיָדוֹ כְּלוּם אוֹ שֶׁעָשָׂה מַעֲשֶׂה עִם דִּבּוּרוֹ אֲפִלּוּ הֶרְאָה בְּאֶצְבָּעוֹ הֲרֵי זֶה לוֹקֶה שֶׁנֶּאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ\" וְגוֹ' (דברים יח יא) \"וְחֹבֵר חָבֶר\". אֲבָל אִם אָמַר דְּבָרִים בִּלְבַד וְלֹא הֵנִיד לֹא אֶצְבַּע וְלֹא רֹאשׁ וְלֹא הָיָה בְּיָדוֹ כְּלוּם. וְכֵן אָדָם שֶׁאָמַר עָלָיו הֶחָבֵר אוֹתָן הַקּוֹלוֹת וְהוּא יוֹשֵׁב לְפָנָיו וּמְדַמֶּה שֶׁיֵּשׁ לוֹ בָּזֶה הֲנָאָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִפְּנֵי שֶׁנִּשְׁתַּתֵּף בְּסִכְלוּת הַחֹבֵר. וְכָל אוֹתָן הַקּוֹלוֹת וְהַשֵּׁמוֹת הַמְשֻׁנִּים הַמְכֹעָרִים לֹא יָרֵעוּ וְגַם הֵיטֵב אֵין אוֹתָם:","מִי שֶׁנְּשָׁכוֹ עַקְרָב אוֹ נָחָשׁ מֻתָּר לִלְחשׁ עַל מְקוֹם הַנְּשִׁיכָה וַאֲפִלּוּ בְּשַׁבָּת כְּדֵי לְיַשֵּׁב דַּעְתּוֹ וּלְחַזֵּק לִבּוֹ. אַף עַל פִּי שֶׁאֵין הַדָּבָר מוֹעִיל כְּלוּם הוֹאִיל וּמְסֻכָּן הוּא הִתִּירוּ לוֹ כְּדֵי שֶׁלֹּא תִּטָּרֵף דַּעְתּוֹ עָלָיו:","הַלּוֹחֵשׁ עַל הַמַּכָּה וְקוֹרֵא פָּסוּק מִן הַתּוֹרָה. וְכֵן הַקּוֹרֵא עַל הַתִּינוֹק שֶׁלֹּא יִבָּעֵת וְהַמַּנִּיחַ סֵפֶר תּוֹרָה אוֹ תְּפִלִּין עַל הַקָּטָן בִּשְׁבִיל שֶׁיִּישַׁן. לֹא דַּי לָהֶם שֶׁהֵם בִּכְלַל מְנַחֲשִׁים וְחוֹבְרִים אֶלָּא שֶׁהֵן בִּכְלַל הַכּוֹפְרִים בַּתּוֹרָה שֶׁהֵן עוֹשִׂין דִּבְרֵי תּוֹרָה רְפוּאַת גּוּף וְאֵינָן אֶלָּא רְפוּאַת נְפָשׁוֹת שֶׁנֶּאֱמַר (משלי ג כב) \"וְיִהְיוּ חַיִּים לְנַפְשֶׁךָ\". אֲבָל הַבָּרִיא שֶׁקָּרָא פְּסוּקִין וּמִזְמוֹר מִתְּהִלִּים כְּדֵי שֶׁתָּגֵן עָלָיו זְכוּת קְרִיאָתָן וְיִנָּצֵל מִצָּרוֹת וּמִנְּזָקִים הֲרֵי זֶה מֻתָּר:","אֵיזֶהוּ דּוֹרֵשׁ אֶל הַמֵּתִים זֶה הַמַּרְעִיב אֶת עַצְמוֹ וְהוֹלֵךְ וְלָן בְּבֵית הַקְּבָרוֹת כְּדֵי שֶׁיָּבוֹא מֵת בַּחֲלוֹם וְיוֹדִיעוֹ מַה שֶּׁשָּׁאַל עָלָיו. וְיֵשׁ אֲחֵרִים שֶׁהֵם לוֹבְשִׁים מַלְבּוּשִׁים יְדוּעִים וְאוֹמְרִים דְּבָרִים וּמַקְטִירִין קְטֹרֶת יְדוּעָה וִישֵׁנִים לְבַדָּן כְּדֵי שֶׁיָּבוֹא מֵת פְּלוֹנִי וִיסַפֵּר עִמּוֹ בַּחֲלוֹם. כְּלָלוֹ שֶׁל דָּבָר כָּל הָעוֹשֶׂה כְּדֵי שֶׁיָּבוֹא הַמֵּת וְיוֹדִיעוֹ לוֹקֶה שֶׁנֶּאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר\" וְגוֹ' (דברים יח יא) \"וְדֹרֵשׁ אֶל הַמֵּתִים\":","אָסוּר לִשְׁאל בַּעַל אוֹב אוֹ בַּעַל יִדְּעֹנִי שֶׁנֶּאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר\" וְגוֹ' (דברים יח יא) \"וְשֹׁאֵל אוֹב וְיִדְּעֹנִי\". נִמְצֵאתָ לָמֵד שֶׁבַּעַל אוֹב וְיִדְּעֹנִי עַצְמָן בִּסְקִילָה וְהַנִּשְׁאָל בָּהֶן בְּאַזְהָרָה וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְאִם כִּוֵּן מַעֲשָׂיו וְעָשָׂה כְּפִי מֵאֲמָרָן לוֹקֶה:","הַמְכַשֵּׁף חַיָּב סְקִילָה וְהוּא שֶׁעָשָׂה מַעֲשֵׂה כְּשָׁפִים. אֲבָל הָאוֹחֵז אֶת הָעֵינַיִם וְהוּא שֶׁיֵּרָאֶה שֶׁעָשָׂה וְהוּא לֹא עָשָׂה לוֹקֶה מַכַּת מַרְדּוּת. מִפְּנֵי שֶׁלָּאו זֶה שֶׁנֶּאֱמַר בִּמְכַשֵּׁף בִּכְלַל (דברים יח י) \"לֹא יִמָּצֵא בְךָ\" הוּא וְלָאו שֶׁנִּתַּן לְאַזְהָרַת מִיתַת בֵּית דִּין הוּא וְאֵין לוֹקִין עָלָיו שֶׁנֶּאֱמַר (שמות כב יז) \"מְכַשֵּׁפָה לֹא תְחַיֶּה\":","וּדְבָרִים הָאֵלּוּ כֻּלָּן דִּבְרֵי שֶׁקֶר וְכָזָב הֵן וְהֵם שֶׁהִטְעוּ בָּהֶן עוֹבְדֵי כּוֹכָבִים הַקַּדְמוֹנִים לְגוֹיֵי הָאֲרָצוֹת כְּדֵי שֶׁיִּנְהֲגוּ אַחֲרֵיהֶן. וְאֵין רָאוּי לְיִשְׂרָאֵל שֶׁהֵם חֲכָמִים מְחֻכָּמִים לְהִמָּשֵׁךְ בַּהֲבָלִים אֵלּוּ וְלֹא לְהַעֲלוֹת עַל לֵב שֶׁיֵּשׁ תּוֹעֶלֶת בָּהֶן. שֶׁנֶּאֱמַר (במדבר כג כג) \"כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל\". וְנֶאֱמַר (דברים יח יד) \"כִּי הַגּוֹיִם הָאֵלֶּה אֲשֶׁר אַתָּה יוֹרֵשׁ אוֹתָם אֶל מְעֹנְנִים וְאֶל קֹסְמִים יִשְׁמָעוּ וְאַתָּה לֹא כֵן\" וְגוֹ'. כָּל הַמַּאֲמִין בִּדְבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן וּמְחַשֵּׁב בְּלִבּוֹ שֶׁהֵן אֱמֶת וּדְבַר חָכְמָה אֲבָל הַתּוֹרָה אֲסָרָתַן אֵינָן אֶלָּא מִן הַסְּכָלִים וּמְחֻסְּרֵי הַדַּעַת וּבִכְלַל הַנָּשִׁים וְהַקְּטַנִּים שֶׁאֵין דַּעְתָּן שְׁלֵמָה. אֲבָל בַּעֲלֵי הַחָכְמָה וּתְמִימֵי הַדַּעַת יֵדְעוּ בִּרְאָיוֹת בְּרוּרוֹת שֶׁכָּל אֵלּוּ הַדְּבָרִים שֶׁאָסְרָה תּוֹרָה אֵינָם דִּבְרֵי חָכְמָה אֶלָּא תֹּהוּ וְהֶבֶל שֶׁנִּמְשְׁכוּ בָּהֶן חַסְרֵי הַדַּעַת וְנָטְשׁוּ כָּל דַּרְכֵי הָאֱמֶת בִּגְלָלָן. וּמִפְּנֵי זֶה אָמְרָה תּוֹרָה כְּשֶׁהִזְהִירָה עַל כָּל אֵלּוּ הַהֲבָלִים (דברים יח יג) \"תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךָ\":"],"Mishneh Torah, Foundations of the Torah 2":["הָאֵל הַנִּכְבָּד וְהַנּוֹרָא הַזֶּה מִצְוָה לְאָהֳבוֹ וּלְיִרְאָה אוֹתוֹ שֶׁנֶּאֱמַר (דברים ו ה) \"וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךָ\". וְנֶאֱמַר (דברים ו יג) \"אֶת ה' אֱלֹהֶיךָ תִּירָא\":","וְהֵיאַךְ הִיא הַדֶּרֶךְ לְאַהֲבָתוֹ וְיִרְאָתוֹ. בְּשָׁעָה שֶׁיִּתְבּוֹנֵן הָאָדָם בְּמַעֲשָׂיו וּבְרוּאָיו הַנִּפְלָאִים הַגְּדוֹלִים וְיִרְאֶה מֵהֶן חָכְמָתוֹ שֶׁאֵין לָהּ עֵרֶךְ וְלֹא קֵץ מִיָּד הוּא אוֹהֵב וּמְשַׁבֵּחַ וּמְפָאֵר וּמִתְאַוֶּה תַּאֲוָה גְּדוֹלָה לֵידַע הַשֵּׁם הַגָּדוֹל. כְּמוֹ שֶׁאָמַר דָּוִד (תהילים מב ג) \"צָמְאָה נַפְשִׁי לֵאלֹהִים לְאֵל חָי\". וּכְשֶׁמְּחַשֵּׁב בַּדְּבָרִים הָאֵלּוּ עַצְמָן מִיָּד הוּא נִרְתָּע לַאֲחוֹרָיו וִיפַחֵד וְיוֹדֵעַ שֶׁהוּא בְּרִיָּה קְטַנָּה שְׁפָלָה אֲפֵלָה עוֹמֶדֶת בְּדַעַת קַלָּה מְעוּטָה לִפְנֵי תְּמִים דֵּעוֹת. כְּמוֹ שֶׁאָמַר דָּוִד (תהילים ח ד) \"כִּי אֶרְאֶה שָׁמֶיךָ מַעֲשֵׂי אֶצְבְּעֹתֶיךָ\" (תהילים ח ה) \"מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ\". וּלְפִי הַדְּבָרִים הָאֵלּוּ אֲנִי מְבָאֵר כְּלָלִים גְּדוֹלִים מִמַּעֲשֵׂה רִבּוֹן הָעוֹלָמִים כְּדֵי שֶׁיִּהְיוּ פֶּתַח לַמֵּבִין לֶאֱהֹב אֶת הַשֵּׁם. כְּמוֹ שֶׁאָמְרוּ חֲכָמִים בְּעִנְיַן אַהֲבָה שֶׁמִּתּוֹךְ כָּךְ אַתָּה מַכִּיר אֶת מִי שֶׁאָמַר וְהָיָה הָעוֹלָם:","כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ נֶחְלָק לִשְׁלֹשָׁה חֲלָקִים. מֵהֶן בְּרוּאִים שֶׁהֵן מְחֻבָּרִים מִגּלֶם וְצוּרָה וְהֵם הוִֹים וְנִפְסָדִים תָּמִיד כְּמוֹ גּוּפוֹת הָאָדָם וְהַבְּהֵמָה וְהַצְּמָחִים וְהַמַּתָּכוֹת. וּמֵהֶן בְּרוּאִים שֶׁהֵן מְחֻבָּרִים מִגּלֶם וְצוּרָה אֲבָל אֵינָן מִשְׁתַּנִּין מִגּוּף לְגוּף וּמִצּוּרָה לְצוּרָה כְּמוֹ הָרִאשׁוֹנִים אֶלָּא צוּרָתָן קְבוּעָה לְעוֹלָם בְּגָלְמָם וְאֵינָן מִשְׁתַּנִּין כְּמוֹ אֵלּוּ. וְהֵם הַגַּלְגַּלִּים וְהַכּוֹכָבִים שֶׁבָּהֶן. וְאֵין גָּלְמָם כִּשְׁאָר גְּלָמִים וְלֹא צוּרָתָם כִּשְׁאָר צוּרוֹת. וּמֵהֶן בְּרוּאִים צוּרָה בְּלֹא גּלֶם כְּלָל וְהֵם הַמַּלְאָכִים. שֶׁהַמַּלְאָכִים אֵינָם גּוּף וּגְוִיָּה אֶלָּא צוּרוֹת נִפְרָדוֹת זוֹ מִזּוֹ:","וּמַהוּ זֶה שֶׁהַנְּבִיאִים אוֹמְרִים שֶׁרָאוּ הַמַּלְאָךְ אֵשׁ וּבַעַל כְּנָפַיִם. הַכּל בְּמַרְאֵה הַנְּבוּאָה וְדֶרֶךְ חִידָה. לוֹמַר שֶׁאֵינוֹ גּוּף וְאֵינוֹ כָּבֵד כַּגּוּפוֹת הַכְּבֵדִים. כְּמוֹ שֶׁנֶּאֱמַר (דברים ד כד) \"כִּי ה' אֱלֹהֶיךָ אֵשׁ אֹכְלָה הוּא\" וְאֵינוֹ אֵשׁ אֶלָּא מָשָׁל. וּכְמוֹ שֶׁנֶּאֱמַר (תהילים קד ד) \"עשֶֹׁה מַלְאָכָיו רוּחוֹת\":","וּבַמֶּה יִפָּרְדוּ הַצּוּרוֹת זוֹ מִזּוֹ וַהֲרֵי אֵינָן גּוּפִין. לְפִי שֶׁאֵינָן שָׁוִין בִּמְצִיאוּתָן אֶלָּא כָּל אֶחָד מֵהֶן לְמַטָּה מִמַּעֲלָתוֹ שֶׁל חֲבֵרוֹ. וְהוּא מָצוּי מִכֹּחוֹ זֶה לְמַעְלָה מִזֶּה וְהַכּל נִמְצָאִים מִכֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְטוּבוֹ. וְזֶהוּ שֶׁרָמַז שְׁלֹמֹה בְּחָכְמָתוֹ וְאָמַר (קהלת ה ז) \"כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר\":","זֶה שֶׁאָמַרְנוּ לְמַטָּה מִמַּעֲלָתוֹ שֶׁל חֲבֵרוֹ אֵינָהּ מַעֲלַת מָקוֹם. כְּמוֹ אָדָם שֶׁיּוֹשֵׁב לְמַעְלָה מֵחֲבֵרוֹ. אֶלָּא כְּמוֹ שֶׁאוֹמְרִין בִּשְׁנֵי חֲכָמִים שֶׁאֶחָד גָּדוֹל מֵחֲבֵרוֹ בְּחָכְמָה שֶׁהוּא לְמַעְלָה מִמַּעֲלָתוֹ שֶׁל זֶה. וּכְמוֹ שֶׁאוֹמְרִין בְּעִלָּה שֶׁהִיא לְמַעְלָה מִן הֶעָלוּל:","שִׁנּוּי שְׁמוֹת הַמַּלְאָכִים עַל שֵׁם מַעֲלָתָם הוּא. וּלְפִיכָךְ נִקְרָאִים חַיּוֹת הַקֹּדֶשׁ וְהֵם לְמַעְלָה מִן הַכּל וְאוֹפַנִּים וְאֶרְאֶלִּים וְחַשְׁמַלִּים וּשְׂרָפִים וּמַלְאָכִים וֵאלֹהִים וּבְנֵי אֱלֹהִים וּכְרוּבִים וְאִישִׁים. כָּל אֵלּוּ עֲשָׂרָה הַשֵּׁמוֹת שֶׁנִּקְרְאוּ בָּהֶן הַמַּלְאָכִים עַל שֵׁם עֶשֶׂר מַעֲלוֹת שֶׁלָּהֶן הֵן, וּמַעֲלָה שֶׁאֵין לְמַעְלָה מִמֶּנָּה אֶלָּא מַעֲלַת הָאֵל בָּרוּךְ הוּא הִיא מַעֲלַת הַצּוּרָה שֶׁנִּקְרֵאת חַיּוֹת. לְפִיכָךְ נֶאֱמַר בַּנְּבוּאָה שֶׁהֵן תַּחַת כִּסֵּא הַכָּבוֹד. וּמַעֲלָה עֲשִׂירִית הִיא מַעֲלַת הַצּוּרָה שֶׁנִּקְרֵאת אִישִׁים וְהֵם הַמַּלְאָכִים הַמְדַבְּרִים עִם הַנְּבִיאִים וְנִרְאִים לָהֶם בְּמַרְאֵה הַנְּבוּאָה. לְפִיכָךְ נִקְרְאוּ אִישִׁים שֶׁמַּעֲלָתָם קְרוֹבָה לְמַעֲלַת דַּעַת בְּנֵי אָדָם:","וְכָל הַצּוּרוֹת הָאֵלּוּ חַיִּים וּמַכִּירִין אֶת הַבּוֹרֵא וְיוֹדְעִים אוֹתוֹ דֵּעָה גְּדוֹלָה עַד לִמְאֹד. כָּל צוּרָה וְצוּרָה לְפִי מַעֲלָתָהּ לֹא לְפִי גָּדְלָהּ. אֲפִלּוּ מַעֲלָה הָרִאשׁוֹנָה אֵינָהּ יְכוֹלָה לְהַשִּׂיג אֲמִתַּת הַבּוֹרֵא כְּמוֹ שֶׁהוּא אֶלָּא דַּעְתָּהּ קְצָרָה לְהַשִּׂיג וְלֵידַע אֲבָל מַשֶּׂגֶת וְיוֹדַעַת יוֹתֵר מִמַּה שֶּׁמַּשֶּׂגֶת וְיוֹדַעַת צוּרָה שֶׁלְּמַטָּה מִמֶּנָּה. וְכֵן כָּל מַעֲלָה וּמַעֲלָה עַד מַעֲלָה עֲשִׂירִית גַּם הִיא יוֹדַעַת הַבּוֹרֵא דֵּעָה שֶׁאֵין כֹּחַ בְּנֵי הָאָדָם הַמְחֻבָּרִים מִגּלֶם וְצוּרָה יָכוֹל לְהַשִּׂיג וְלֵידַע כְּמוֹתָהּ. וְהַכּל אֵינָן יוֹדְעִין הַבּוֹרֵא כְּמוֹ שֶׁהוּא יוֹדֵעַ עַצְמוֹ:","כָּל הַנִּמְצָאִים חוּץ מִן הַבּוֹרֵא מִצּוּרָה הָרִאשׁוֹנָה עַד יַתּוּשׁ קָטָן שֶׁיִּהְיֶה בְּטַבּוּר הָאָרֶץ הַכּל מִכֹּחַ אֲמִתָּתוֹ נִמְצְאוּ. וּלְפִי שֶׁהוּא יוֹדֵעַ עַצְמוֹ וּמַכִּיר גְּדֻלָּתוֹ וְתִפְאַרְתּוֹ וַאֲמִתָּתוֹ הוּא יוֹדֵעַ הַכּל וְאֵין דָּבָר נֶעֱלָם מִמֶּנּוּ:","הַקָּדוֹשׁ בָּרוּךְ הוּא מַכִּיר אֲמִתּוֹ וְיוֹדֵעַ אוֹתָהּ כְּמוֹ שֶׁהִיא. וְאֵינוֹ יוֹדֵעַ בְּדֵעָה שֶׁהִיא חוּץ מִמֶּנּוּ כְּמוֹ שֶׁאָנוּ יוֹדְעִין. שֶׁאֵין אָנוּ וְדַעְתֵּנוּ אֶחָד אֲבָל הַבּוֹרֵא יִתְבָּרַךְ הוּא וְדַעְתּוֹ וְחַיָּיו אֶחָד מִכָּל צַד וּמִכָּל פִּנָּה וּבְכָל דֶּרֶךְ יִחוּד. שֶׁאִלְמָלֵי הָיָה חַי בַּחַיִּים וְיוֹדֵעַ בְּדֵעָה חוּץ מִמֶּנּוּ הָיוּ שָׁם אֱלֹהוּת הַרְבֵּה הוּא וְחַיָּיו וְדַעְתּוֹ, וְאֵין הַדָּבָר כֵּן אֶלָּא אֶחָד מִכָּל צַד וּמִכָּל פִּנָּה וּבְכָל דֶּרֶךְ יִחוּד. נִמְצֵאתָ אַתָּה אוֹמֵר הוּא הַיּוֹדֵעַ וְהוּא הַיָּדוּעַ וְהוּא הַדֵּעָה עַצְמָהּ הַכּל אֶחָד. וְדָבָר זֶה אֵין כֹּחַ בַּפֶּה לְאָמְרוֹ וְלֹא בָּאֹזֶן לְשָׁמְעוֹ וְלֹא בְּלֵב הָאָדָם לְהַכִּירוֹ עַל בֻּרְיוֹ. וּלְפִיכָךְ אוֹמֵר חֵי פַרְעֹה וְחֵי נַפְשְׁךָ וְאֵין אוֹמֵר חֵי ה' אֶלָּא חַי ה'. שֶׁאֵין הַבּוֹרֵא וְחַיָּיו שְׁנַיִם כְּמוֹ חַיֵּי הַגּוּפִים הַחַיִּים אוֹ כְּחַיֵּי הַמַּלְאָכִים. לְפִיכָךְ אֵינוֹ מַכִּיר הַבְּרוּאִים וְיוֹדְעָם מֵחֲמַת הַבְּרוּאִים כְּמוֹ שֶׁאָנוּ יוֹדְעִין אוֹתָם אֶלָּא מֵחֲמַת עַצְמוֹ יְדָעֵם. לְפִיכָךְ מִפְּנֵי שֶׁהוּא יוֹדֵעַ עַצְמוֹ יוֹדֵעַ הַכּל שֶׁהַכּל נִסְמָךְ לוֹ בַּהֲוָיָתוֹ:","דְּבָרִים אֵלּוּ שֶׁאָמַרְנוּ בְּעִנְיָן זֶה בִּשְׁנֵי פְּרָקִים אֵלּוּ כְּמוֹ טִפָּה מִן הַיָּם הֵם מִמַּה שֶּׁצָּרִיךְ לְבָאֵר בְּעִנְיָן זֶה. וּבֵאוּר כָּל הָעִקָּרִים שֶׁבִּשְׁנֵי פְּרָקִים אֵלּוּ הוּא הַנִּקְרָא מַעֲשֵׂה מֶרְכָּבָה:","צִוּוּ חֲכָמִים הָרִאשׁוֹנִים שֶׁלֹּא לִדְרשׁ בִּדְבָרִים אֵלּוּ אֶלָּא לְאִישׁ אֶחָד בִּלְבַד וְהוּא שֶׁיִּהְיֶה חָכָם וּמֵבִין מִדַּעְתּוֹ וְאַחַר כָּךְ מוֹסְרִין לוֹ רָאשֵׁי הַפְּרָקִים וּמוֹדִיעִין אוֹתוֹ שֶׁמֶץ מִן הַדָּבָר וְהוּא מֵבִין מִדַּעְתּוֹ וְיֵדַע סוֹף הַדָּבָר וְעָמְקוֹ. וּדְבָרִים אֵלּוּ דְּבָרִים עֲמֻקִּים הֵם עַד לִמְאֹד וְאֵין כָּל דַּעַת וְדַעַת רְאוּיָה לְסָבְלָן. וַעֲלֵיהֶם אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ דֶּרֶךְ מָשָׁל (משלי כז כו) \"כְּבָשִׂים לִלְבוּשֶׁךָ\" כָּךְ אָמְרוּ חֲכָמִים בְּפֵרוּשׁ מָשָׁל זֶה דְּבָרִים שֶׁהֵן כִּבְשׁוֹנוֹ שֶׁל עוֹלָם יִהְיוּ לִלְבוּשְׁךָ כְּלוֹמַר לְךָ לְבַדְּךָ וְאַל תִּדְרשׁ אוֹתָם בָּרַבִּים. וַעֲלֵיהֶם אָמַר (משלי ה יז) \"יִהְיוּ לְךָ לְבַדֶּךָ וְאֵין לְזָרִים אִתָּךְ\". וַעֲלֵיהֶם אָמַר (שיר השירים ד יא) \"דְּבַשׁ וְחָלָב תַּחַת לְשוֹנֵךְ\", כָּךְ פֵּרְשׁוּ חֲכָמִים הָרִאשׁוֹנִים דְּבָרִים שֶׁהֵן כִּדְבַשׁ וְחָלָב יִהְיוּ תַּחַת לְשׁוֹנְךָ:"],"Mishneh Torah, Gifts to the Poor 10":["חַיָּבִין אָנוּ לְהִזָּהֵר בְּמִצְוַת צְדָקָה יוֹתֵר מִכָּל מִצְוֹת עֲשֵׂה. שֶׁהַצְּדָקָה סִימָן לַצַּדִּיק זֶרַע אַבְרָהָם אָבִינוּ שֶׁנֶּאֱמַר (בראשית יח יט) \"כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו\" (בראשית יח יט) \"לַעֲשׂוֹת צְדָקָה\". וְאֵין כִּסֵּא יִשְׂרָאֵל מִתְכּוֹנֵן וְדַת הָאֱמֶת עוֹמֶדֶת אֶלָּא בִּצְדָקָה שֶׁנֶּאֱמַר (ישעיה נד יד) \"בִּצְדָקָה תִּכּוֹנָנִי\". וְאֵין יִשְׂרָאֵל נִגְאָלִין אֶלָּא בִּצְדָקָה שֶׁנֶּאֱמַר (ישעיה א כז) \"צִיּוֹן בְּמִשְׁפָּט תִּפָּדֶה וְשָׁבֶיהָ בִּצְדָקָה\":","לְעוֹלָם אֵין אָדָם מַעֲנִי מִן הַצְּדָקָה וְאֵין דָּבָר רַע וְלֹא הֶזֵּק נִגְלָל בִּשְׁבִיל הַצְּדָקָה שֶׁנֶּאֱמַר (ישעיה לב יז) \"וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם.\" כָּל הַמְרַחֵם מְרַחֲמִין עָלָיו שֶׁנֶּאֱמַר (דברים יג יח) \"וְנָתַן לְךָ רַחֲמִים וְרִחַמְךָ וְהִרְבֶּךָ\". וְכָל מִי שֶׁהוּא אַכְזָרִי וְאֵינוֹ מְרַחֵם יֵשׁ לָחוּשׁ לְיַחֲסוֹ. שֶׁאֵין הָאַכְזָרִיּוּת מְצוּיָה אֶלָּא בְּעַכּוּ\"ם שֶׁנֶּאֱמַר (ירמיה נ מב) \"אַכְזָרִי הֵמָּה וְלֹא יְרַחֵמוּ\". וְכָל יִשְׂרָאֵל וְהַנִּלְוֶה עֲלֵיהֶם כְּאַחִים הֵם שֶׁנֶּאֱמַר (דברים יד א) \"בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם\" וְאִם לֹא יְרַחֵם הָאָח עַל הָאָח מִי יְרַחֵם עָלָיו. וּלְמִי עֲנִיֵּי יִשְׂרָאֵל נוֹשְׂאִין עֵינֵיהֶן. הֲלְעַכּוּ\"ם שֶׁשּׂוֹנְאִין אוֹתָן וְרוֹדְפִים אַחֲרֵיהֶן. הָא אֵין עֵינֵיהֶן תְּלוּיוֹת אֶלָּא לַאֲחֵיהֶן:","כָּל הַמַּעֲלִים עֵינָיו מִן הַצְּדָקָה הֲרֵי זֶה נִקְרָא בְּלִיַּעַל כְּמוֹ שֶׁנִּקְרָא עוֹבֵד עַכּוּ\"ם בְּלִיַּעַל. וּבְעַכּוּ\"ם הוּא אוֹמֵר (דברים יג יד) \"יָצְאוּ אֲנָשִׁים בְּנֵי בְלִיַּעַל\" וּבְמַעֲלִים עֵינָיו מִן הַצְּדָקָה הוּא אוֹמֵר (דברים טו ט) \"הִשָּׁמֶר לְךָ פֶּן יִהְיֶה דָבָר עִם לְבָבְךָ בְלִיַּעַל\". וְנִקְרָא רָשָׁע שֶׁנֶּאֱמַר (משלי יב י) \"וְרַחֲמֵי רְשָׁעִים אַכְזָרִי\". וְנִקְרָא חוֹטֵא שֶׁנֶּאֱמַר (דברים טו ט) \"וְקָרָא עָלֶיךָ אֶל ה' וְהָיָה בְךָ חֵטְא\". וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לְשַׁוְעַת עֲנִיִּים שֶׁנֶּאֱמַר שַׁוְעַת עֲנִיִּים אַתָּה תִשְׁמַע. לְפִיכָךְ צָרִיךְ לְהִזָּהֵר בְּצַעֲקָתָם שֶׁהֲרֵי בְּרִית כְּרוּתָה לָהֶם שֶׁנֶּאֱמַר (שמות כב כו) \"וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי\":","כָּל הַנּוֹתֵן צְדָקָה לְעָנִי בְּסֵבֶר פָּנִים רָעוֹת וּפָנָיו כְּבוּשׁוֹת בַּקַּרְקַע אֲפִלּוּ נָתַן לוֹ אֶלֶף זְהוּבִים אִבֵּד זְכוּתוֹ וְהִפְסִידָהּ. אֶלָּא נוֹתֵן לוֹ בְּסֵבֶר פָּנִים יָפוֹת וּבְשִׂמְחָה וּמִתְאוֹנֵן עִמּוֹ עַל צָרָתוֹ שֶׁנֶּאֱמַר (איוב ל כה) \"אִם לֹא בָכִיתִי לִקְשֵׁה יוֹם עָגְמָה נַפְשִׁי לָאֶבְיוֹן\". וּמְדַבֵּר לוֹ דִּבְרֵי תַּחֲנוּנִים וְנִחוּמִים שֶׁנֶּאֱמַר (איוב כט יג) \"וְלֵב אַלְמָנָה אַרְנִן\":","שָׁאַל הֶעָנִי מִמְּךָ וְאֵין בְּיָדְךָ כְּלוּם לִתֵּן לוֹ פַּיְּסֵהוּ בִּדְבָרִים. וְאָסוּר לִגְעֹר בְּעָנִי אוֹ לְהַגְבִּיהַּ קוֹלוֹ עָלָיו בִּצְעָקָה. מִפְּנֵי שֶׁלִּבּוֹ נִשְׁבָּר וְנִדְכֶּא וַהֲרֵי הוּא אוֹמֵר (תהילים נא יט) \"לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה\". וְאוֹמֵר (ישעיה נז טו) \"לְהַחֲיוֹת רוּחַ שְׁפָלִים וּלְהַחֲיוֹת לֵב נִדְכָּאִים\". וְאוֹי לְמִי שֶׁהִכְלִים אֶת הֶעָנִי אוֹי לוֹ. אֶלָּא יִהְיֶה לוֹ כְּאָב בֵּין בְּרַחֲמִים בֵּין בִּדְבָרִים שֶׁנֶּאֱמַר (איוב כט טז) \"אָב אָנֹכִי לָאֶבְיוֹנִים\":","הַכּוֹפֶה אֲחֵרִים לִתֵּן צְדָקָה וּמְעַשֶּׂה אוֹתָן שְׂכָרוֹ גָּדוֹל מִשְּׂכַר הַנּוֹתֵן שֶׁנֶּאֱמַר (ישעיה לב יז) \"וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם\". וְעַל גַּבָּאֵי צְדָקָה וְכַיּוֹצֵא בָּהֶם אוֹמֵר (דניאל יב ג) \"וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים\":","שְׁמוֹנֶה מַעֲלוֹת יֵשׁ בַּצְּדָקָה זוֹ לְמַעְלָה מִזּוֹ. מַעֲלָה גְּדוֹלָה שֶׁאֵין לְמַעְלָה מִמֶּנָּה זֶה הַמַּחֲזִיק בְּיַד יִשְׂרָאֵל שֶׁמָּךְ וְנוֹתֵן לוֹ מַתָּנָה אוֹ הַלְוָאָה אוֹ עוֹשֶׂה עִמּוֹ שֻׁתָּפוּת אוֹ מַמְצִיא לוֹ מְלָאכָה כְּדֵי לְחַזֵּק אֶת יָדוֹ עַד שֶׁלֹּא יִצְטָרֵךְ לַבְּרִיּוֹת לִשְׁאל. וְעַל זֶה נֶאֱמַר (ויקרא כה לה) \"וְהֶחֱזַקְתָּ בּוֹ גֵּר וְתוֹשָׁב וָחַי עִמָּךְ\" כְּלוֹמַר הַחֲזֵק בּוֹ עַד שֶׁלֹּא יִפּל וְיִצְטָרֵךְ:","פָּחוֹת מִזֶּה הַנּוֹתֵן צְדָקָה לָעֲנִיִּים וְלֹא יָדַע לְמִי נָתַן וְלֹא יָדַע הֶעָנִי מִמִּי לָקַח. שֶׁהֲרֵי זוֹ מִצְוָה לִשְׁמָהּ. כְּגוֹן לִשְׁכַּת חֲשָׁאִים שֶׁהָיְתָה בַּמִּקְדָּשׁ. שֶׁהָיוּ הַצַּדִּיקִים נוֹתְנִין בָּהּ בַּחֲשַׁאי וְהָעֲנִיִּים בְּנֵי טוֹבִים מִתְפַּרְנְסִין מִמֶּנָּה בַּחֲשַׁאי. וְקָרוֹב לָזֶה הַנּוֹתֵן לְתוֹךְ קֻפָּה שֶׁל צְדָקָה. וְלֹא יִתֵּן אָדָם לְתוֹךְ קֻפָּה שֶׁל צְדָקָה אֶלָּא אִם כֵּן יוֹדֵעַ שֶׁהַמְמֻנֶּה נֶאֱמָן וְחָכָם וְיוֹדֵעַ לְהַנְהִיג כַּשּׁוּרָה כְּרַבִּי חֲנַנְיָה בֶּן תְּרַדְיוֹן:","פָּחוֹת מִזֶּה שֶׁיֵּדַע הַנּוֹתֵן לְמִי יִתֵּן וְלֹא יֵדַע הֶעָנִי מִמִּי לָקַח. כְּגוֹן גְּדוֹלֵי הַחֲכָמִים שֶׁהָיוּ הוֹלְכִין בַּסֵּתֶר וּמַשְׁלִיכִין הַמָּעוֹת בְּפִתְחֵי הָעֲנִיִּים. וְכָזֶה רָאוּי לַעֲשׂוֹת וּמַעֲלָה טוֹבָה הִיא אִם אֵין הַמְמֻנִּין בִּצְדָקָה נוֹהֲגִין כַּשּׁוּרָה:","פָּחוֹת מִזֶּה שֶׁיֵּדַע הֶעָנִי מִמִּי נָטַל וְלֹא יֵדַע הַנּוֹתֵן. כְּגוֹן גְּדוֹלֵי הַחֲכָמִים שֶׁהָיוּ צוֹרְרִים הַמָּעוֹת בִּסְדִינֵיהֶן וּמַפְשִׁילִין לַאֲחוֹרֵיהֶן וּבָאִין הָעֲנִיִּים וְנוֹטְלִין כְּדֵי שֶׁלֹּא יִהְיֶה לָהֶן בּוּשָׁה:","פָּחוֹת מִזֶּה שֶׁיִּתֵּן לוֹ בְּיָדוֹ קֹדֶם שֶׁיִּשְׁאַל:","פָּחוֹת מִזֶּה שֶׁיִּתֵּן לוֹ אַחַר שֶׁיִּשְׁאַל:","פָּחוֹת מִזֶּה שֶׁיִּתֵּן לוֹ פָּחוֹת מִן הָרָאוּי בְּסֵבֶר פָּנִים יָפוֹת:","פָּחוֹת מִזֶּה שֶׁיִּתֵּן לוֹ בְּעֶצֶב:","גְּדוֹלֵי הַחֲכָמִים הָיוּ נוֹתְנִין פְּרוּטָה לְעָנִי קֹדֶם כָּל תְּפִלָּה וְאַחַר כָּךְ מִתְפַּלְּלִין שֶׁנֶּאֱמַר (תהילים יז טו) \"אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ\":","הַנּוֹתֵן מְזוֹנוֹת לְבָנָיו וְלִבְנוֹתָיו הַגְּדוֹלִים שֶׁאֵינוֹ חַיָּב בִּמְזוֹנוֹתֵיהֶן כְּדֵי לְלַמֵּד הַזְּכָרִים תּוֹרָה וּלְהַנְהִיג הַבָּנוֹת בְּדֶרֶךְ יְשָׁרָה וְלֹא יִהְיוּ מְבֻזּוֹת. וְכֵן הַנּוֹתֵן מְזוֹנוֹת לְאָבִיו וּלְאִמּוֹ הֲרֵי זֶה בִּכְלַל הַצְּדָקָה. וּצְדָקָה גְּדוֹלָה הִיא שֶׁהַקָּרוֹב קוֹדֵם. וְכָל הַמַּאֲכִיל וּמַשְׁקֶה עֲנִיִּים וִיתוֹמִים עַל שֻׁלְחָנוֹ הֲרֵי זֶה קוֹרֵא אֶל ה' וְיַעֲנֵהוּ וּמִתְעַנֵּג שֶׁנֶּאֱמַר (ישעיה נח ט) \"אָז תִּקְרָא וַה' יַעֲנֶה\":","צִוּוּ חֲכָמִים שֶׁיִּהְיוּ בְּנֵי בֵּיתוֹ שֶׁל אָדָם עֲנִיִּים וִיתוֹמִים בִּמְקוֹם הָעֲבָדִים. מוּטָב לוֹ לְהִשְׁתַּמֵּשׁ בְּאֵלּוּ וְיֵהָנוּ בְּנֵי אַבְרָהָם יִצְחָק וְיַעֲקֹב מִנְּכָסָיו וְלֹא יֵהָנוּ בָּהֶם זֶרַע חָם. שֶׁכָּל הַמַּרְבֶּה עֲבָדִים בְּכָל יוֹם וָיוֹם מוֹסִיף חֵטְא וְעָוֹן בָּעוֹלָם. וְאִם יִהְיוּ עֲנִיִּים בְּנֵי בֵּיתוֹ בְּכָל שָׁעָה וְשָׁעָה מוֹסִיף זְכֻיּוֹת וּמִצְוֹת:","לְעוֹלָם יִדְחֹק אָדָם עַצְמוֹ וְיִתְגַּלְגֵּל בְּצַעַר וְאַל יִצְטָרֵךְ לַבְּרִיּוֹת וְאַל יַשְׁלִיךְ עַצְמוֹ עַל הַצִּבּוּר. וְכֵן צִוּוּ חֲכָמִים וְאָמְרוּ עֲשֵׂה שַׁבַּתְּךָ חֹל וְאַל תִּצְטָרֵךְ לַבְּרִיּוֹת. וַאֲפִלּוּ הָיָה חָכָם וּמְכֻבָּד וְהֶעֱנִי יַעֲסֹק בְּאֻמְּנוּת וַאֲפִלּוּ בְּאֻמְּנוּת מְנֻוֶּלֶת וְלֹא יִצְטָרֵךְ לַבְּרִיּוֹת. מוּטָב לִפְשֹׁט עוֹר בְּהֵמוֹת נְבֵלוֹת וְלֹא יֹאמַר לָעָם חָכָם גָּדוֹל אֲנִי כֹּהֵן אֲנִי פַּרְנְסוּנִי. וּבְכָךְ צִוּוּ חֲכָמִים. גְּדוֹלֵי הַחֲכָמִים הָיוּ מֵהֶם חוֹטְבֵי עֵצִים וְנוֹשְׂאֵי הַקּוֹרוֹת וְשׁוֹאֲבֵי מַיִם לַגִּנּוֹת וְעוֹשֵׂי הַבַּרְזֶל וְהַפֶּחָמִים וְלֹא שָׁאֲלוּ מִן הַצִּבּוּר וְלֹא קִבְּלוּ מֵהֶם כְּשֶׁנָּתְנוּ לָהֶם:","כָּל מִי שֶׁאֵינוֹ צָרִיךְ לִטּל וּמְרַמֶּה אֶת הָעָם וְנוֹטֵל אֵינוֹ מֵת מִן הַזִּקְנָה עַד שֶׁיִּצְטָרֵךְ לַבְּרִיּוֹת. וַהֲרֵי הוּא בִּכְלַל (ירמיה יז ה) \"אָרוּר הַגֶּבֶר אֲשֶׁר יִבְטַח בָּאָדָם\". וְכָל מִי שֶׁצָּרִיךְ לִטּל וְאֵינוֹ יָכוֹל לִחְיוֹת אֶלָּא אִם כֵּן נוֹטֵל כְּגוֹן זָקֵן אוֹ חוֹלֶה אוֹ בַּעַל יִסּוּרִין וּמֵגִיס דַּעְתּוֹ וְאֵינוֹ נוֹטֵל הֲרֵי זֶה שׁוֹפֵךְ דָּמִים וּמִתְחַיֵּב בְּנַפְשׁוֹ וְאֵין לוֹ בְּצַעֲרוֹ אֶלָּא חַטָּאוֹת וַאֲשָׁמוֹת. וְכָל מִי שֶׁצָּרִיךְ לִטּל וְצִעֵר וְדָחַק אֶת הַשָּׁעָה וְחָיָה חַיֵּי צַעַר כְּדֵי שֶׁלֹּא יַטְרִיחַ עַל הַצִּבּוּר אֵינוֹ מֵת מִן הַזִּקְנָה עַד שֶׁיְּפַרְנֵס אֲחֵרִים מִשֶּׁלּוֹ. וְעָלָיו וְעַל כָּל כַּיּוֹצֵא בָּזֶה נֶאֱמַר (ירמיה יז ז) \"בָּרוּךְ הַגֶּבֶר אֲשֶׁר יִבְטַח בַּה'\": סְלִיקוּ לְהוּ הִלְכוֹת מַתְּנוֹת עֲנִיִּים בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Heave Offerings 12":["אָסוּר לְטַמֵּא אֶת הַתְּרוּמָה שֶׁל אֶרֶץ יִשְׂרָאִל כִּשְׁאָר הַקָּדָשִׁים וְלֹא יְבִיאֶנָּה לִידֵי טֻמְאָה וְלֹא יַפְסִידֶנָּה אֶלָּא אוֹכֵל הַטְּהוֹרָה וּמַדְלִיק הַטְּמֵאָה. וּמֻתָּר לְטַמֵּא תְּרוּמַת חוּצָה לָאָרֶץ בְּטֻמְאוֹת שֶׁל תּוֹרָה. וְאַף עַל פִּי שֶׁאֵינָהּ טְמֵאָה אֶלָּא בְּאֶרֶץ הָעַמִּים שֶׁהִיא מִדִּבְרֵיהֶם מִפְּנֵי שֶׁעִקַּר חִיּוּבָהּ מִדִּבְרֵיהֶם. לְפִיכָךְ נִדָּה קוֹצָה לָהּ חַלָּה בְּחוּצָה לָאָרֶץ שֶׁאֵינָהּ מֻזְהֶרֶת אֶלָּא לְאָכְלָהּ לֹא לִגַּע בָּהּ כְּמוֹ שֶׁבֵּאַרְנוּ:","תְּרוּמָה שֶׁנִּטְמֵאת בְּסָפֵק לֹא אוֹכְלִים וְלֹא שׂוֹרְפִין אֶלָּא תִּהְיֶה מֻנַּחַת עַד שֶׁתִּטְמָא טֻמְאָה וַדָּאִית וְתִשָּׂרֵף. וְיֵשׁ שָׁם סְפֵיקוֹת שֶׁשּׂוֹרְפִין עֲלֵיהֶן אֶת הַתְּרוּמָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן טֻמְאָה וְטָהֳרָה:","חָבִית שֶׁל תְּרוּמָה שֶׁנּוֹלַד לָהּ סְפֵק טֻמְאָה הֲרֵי זֶה לֹא יְחַדֵּשׁ בָּהּ דָּבָר. לֹא יְזִיזֶנָּה מִמְּקוֹמָהּ וְלֹא יְגַלֶּנָּה אֶלָּא יַנִּיחֶנָּה עַד שֶׁתִּטָּמֵא וַדַּאי וְתִשָּׂרֵף. וְאֵין חוֹשְׁשִׁין שֶׁמָּא תֵּאָכֵל:","חָבִית שֶׁנִּשְׁבְּרָה בַּגַּת הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה טְמֵאָה. אִם יָכוֹל לְהַצִּיל מִמֶּנָּה רְבִיעִית בְּטָהֳרָה יַצִּיל וְאִם לָאו יַצִּיל בְּיָדָיו בְּלֹא נְטִילַת יָדַיִם וְאַף עַל פִּי שֶׁהוּא מְטַמְּאָהּ כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיָן טָהֳרוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּחָבִית שֶׁל יַיִן וְהוּא שֶׁיִּהְיֶה בַּגַּת הַתַּחְתּוֹנָה פָּחוֹת מִמֵּאָה שֶׁהֲרֵי יִדָּמַע הַכּל וְיִפָּסֵל. אֲבָל אִם הָיָה בַּתַּחְתּוֹנָה מֵאָה בְּזוֹ הֶחָבִית שֶׁהֲרֵי הִיא עוֹלָה בְּאַחַת וּמֵאָה. אוֹ שֶׁהָיְתָה חָבִית שֶׁל שֶׁמֶן. תֵּרֵד וְתִטָּמֵא וְאַל יְטַמְּאֶנָּה בְּיָדָיו שֶׁהֲרֵי הַכּל רָאוּי לְהַדְלָקָה וְאֵין שָׁם הֶפְסֵד מְרֻבֶּה. וְכֵן חָבִית שֶׁמֶן שֶׁנִּשְׁפְּכָה אִם יָכוֹל לְהַצִּיל רְבִיעִית בְּטָהֳרָה יַצִּיל וְאִם לָאו יַצִּיל בְּטֻמְאָה. שֶׁכֵּיוָן שֶׁנִּשְׁבְּרָה הֶחָבִית אֵינוֹ מֻזְהָר שֶׁלֹּא לְהַצִּיל בְּטֻמְאָה מִפְּנֵי שֶׁהוּא בָּהוּל:","הָיָה עוֹבֵר מִמָּקוֹם לְמָקוֹם וּבְיָדוֹ כִּכָּרוֹת שֶׁל תְּרוּמָה. אָמַר לוֹ הַנָּכְרִי תֵּן לִי אַחַת מֵהֶן וְאִם לָאו הֲרֵינִי נוֹגֵעַ בְּכֻלָּן וּמְטַמְּאָן יַנִּיחַ לְפָנָיו אַחַת עַל הַסֶּלַע וְאַל יִתְּנֶנָּה לְתוֹךְ יָדוֹ כְּדֵי שֶׁלֹּא יְטַמֵּא הַתְּרוּמָה בְּיָדַיִם:","הַתִּלְתָּן וְהַכַּרְשִׁינִין שֶׁל תְּרוּמָה הוֹאִיל וְאֵינוֹ מַאֲכַל אָדָם הֲרֵי זֶה מֻתָּר לַעֲשׂוֹת כָּל מַעֲשֵׂיהֶן בְּטֻמְאָה. וְאֵינוֹ נִזְהָר אֶלָּא בְּעֵת שְׁרִיָּתָן בְּמַיִם. שֶׁאִם שָׁרָה אוֹתָם בְּטֻמְאָה הֲרֵי טִמֵּא אוֹתָם בְּיָדַיִם. אֲבָל אַחַר הַשְּׁרִיָּה אֵינוֹ נִזְהָר. לֹא בְּעֵת שֶׁשָּׁף הַכַּרְשִׁינִין וְלֹא בְּעֵת שֶׁמַּאֲכִילָן לִבְהֵמָה. לְפִיכָךְ נוֹתְנִין תְּרוּמַת תִּלְתָּן וְכַרְשִׁינִין לְכֹהֵן עַם הָאָרֶץ:","אֵין מַפְקִידִין תְּרוּמָה אֵצֶל כֹּהֵן עַם הָאָרֶץ מִפְּנֵי שֶׁלִּבּוֹ גַּס בָּהּ לְאָכְלָהּ. אֲבָל מַפְקִידִין אוֹתוֹ אֵצֶל יִשְׂרָאֵל עַם הָאָרֶץ בִּכְלִי חֶרֶשׂ הַמֻּקָּף צְמִיד פָּתִיל. וּבִלְבַד שֶׁלֹּא יִהְיוּ פֵּרוֹת מֻכְשָׁרִין. גְּזֵרָה שֶׁלֹּא תְּסִיטֵם אִשְׁתּוֹ נִדָּה:","אֵין עוֹשִׂין לְעַם הָאָרֶץ תְּרוּמַת זֵיתָיו בְּטָהֳרָה. אֲבָל עוֹשִׂין לוֹ זֵיתֵי חֻלִּין בְּטָהֳרָה מִשּׁוּם כְּדֵי חַיָּיו שֶׁל בָּדָד (לְבַד). וְכֵיצַד עוֹשֶׂה. נוֹטֵל כְּדֵי הַתְּרוּמָה וּמַנִּיחָהּ בִּכְלִי שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה כְּגוֹן כְּלִי אֲבָנִים. וּכְשֶׁיָּבוֹא עַם הָאָרֶץ לִטּל הַחֻלִּין וְהַתְּרוּמָה אוֹמְרִין לוֹ הִזָּהֵר שֶׁמָּא תִּגַּע בַּתְּרוּמָה שֶׁלֹּא תַּחֲזֹר לְטִבְלָהּ:","יִשְׂרָאֵל שֶׁעוֹשֶׂה פֵּרוֹתָיו בְּטֻמְאָה אֵין בּוֹצְרִין עִמּוֹ. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין דּוֹרְכִין עִמּוֹ מִפְּנֵי הַתְּרוּמָה שֶׁתֵּעָשֶׂה בְּטֻמְאָה. אֲבָל מוֹלִיכִין עִמּוֹ חָבִיּוֹת לַגַּת וּמְבִיאִין מִן הַגַּת:","זֵיתִים וַעֲנָבִים שֶׁנִּטְמְאוּ סוֹחֲטָן וְעוֹשֶׂה אוֹתָן תְּרוּמָה. וְאִם נִטְמְאוּ אַחַר שֶׁנַּעֲשׂוּ תְּרוּמָה וְסוֹחֲטָן פָּחוֹת פָּחוֹת מִכַּבֵּיצָה הֲרֵי הַמַּשְׁקֶה הַיּוֹצֵא מֵהֶן מֻתָּר בִּשְׁתִיָּה לַכֹּהֲנִים. וַאֲפִלּוּ לִנְסָכִים הָיָה רָאוּי שֶׁהַמַּשְׁקֶה כְּאִלּוּ הוּא מֻפְקָד בְּתוֹךְ הָאֹכֶל. וְלֹא אָמְרוּ פָּחוֹת פָּחוֹת מִכְּבֵיצָה אֶלָּא גְּזֵרָה שֶׁמָּא יַעֲשֶׂה יוֹתֵר מִכַּבֵּיצָה וְנִמְצָא הַמַּשְׁקֶה מִתְּטַמֵּא בִּכְבֵיצָה. וְאִם הָיוּ פֵּרוֹת אֵלּוּ שְׁלִישִׁי לְטֻמְאָה דּוֹרְכָן בְּגַת וּבְבֵית הַבַּד וְהַמַּשְׁקֶה תְּרוּמָה טְהוֹרָה. שֶׁאֵין שְׁלִישִׁי עוֹשֶׂה רְבִיעִי בִּתְרוּמָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן טָהֳרוֹת:","פַּת תְּרוּמָה שֶׁנִּטְמֵאת מַשְׁלִיכָהּ לְבֵין הָעֵצִים עַד שֶׁיִּשְׂרְפֶנָּה. וְכֵן שֶׁמֶן שֶׁנִּטְמָא נוֹתְנוֹ בִּכְלִי מָאוּס עַד שֶׁיַּדְלִיק כְּדֵי שֶׁלֹּא יִהְיֶה תַּקָּלָה לַאֲחֵרִים וְיֹאכְלוּהוּ. וְחִטִּים שֶׁנִּטְמְאוּ שׁוֹלְקָן וּמַנִּיחָן בִּכְלִי מָאוּס כְּדֵי שֶׁלֹּא יִהְיוּ רְאוּיִין לַאֲכִילָה וְאַחַר כָּךְ יַסִּיק בָּהֶן תַּנּוּר וְכִירַיִם. וּמַשְׁקִין שֶׁאֵין רְאוּיִין לְהַדְלָקָה שֶׁנִּטְמְאוּ כְּגוֹן הַיַּיִן קוֹבְרִין אוֹתָן:","יֵין תְּרוּמָה שֶׁנִּתְגַּלָּה הוֹאִיל וְאָסוּר בִּשְׁתִיָּה יִשָּׁפֵךְ. וְכֵן תְּאֵנִים וַעֲנָבִים וְקִשּׁוּאִים וְדִלּוּעִין וַאֲבַטִּיחִין וּמְלָפְפוֹנוֹת שֶׁל תְּרוּמָה שֶׁנִּמְצְאוּ מְנֻקָּרוֹת הֲרֵי אֵלּוּ אֲסוּרִין בַּאֲכִילָה מִפְּנֵי סַכָּנַת נְפָשׁוֹת. מַה יַּעֲשֶׂה בָּהֶן יַשְׁלִיךְ לַיָּם אוֹ יִקָּבְרוּ:","עִסָּה שֶׁנִּלּוֹשָׁה בְּמַיִם מְגֻלִּים אַף עַל פִּי שֶׁהִיא תְּרוּמָה תִּשָּׂרֵף:","אָסוּר לְכֹהֵן לִטּל תְּרוּמָה אוֹ שְׁאָר מַתָּנוֹת שֶׁלּוֹ עַד שֶׁיַּפְרִישׁוּ אוֹתָם הַבְּעָלִים שֶׁנֶּאֱמַר (במדבר יח יב) \"רֵאשִׁיתָם אֲשֶׁר יִתְּנוּ לַה' לְךָ נְתַתִּים\" וְנֶאֱמַר (במדבר יח יט) \"אֲשֶׁר יָרִימוּ בְנֵי יִשְׂרָאֵל לַה' נָתַתִּי לְךָ\" עַד שֶׁיָּרִימוּ וְאַחַר כָּךְ יִזְכֶּה בָּהֶם. וְלֹא יִטְלֵם אַחַר שֶׁהוּרְמוּ אֶלָּא מִדַּעַת בְּעָלִים שֶׁהֲרֵי הֵם שֶׁל בְּעָלִים לִתְּנָן לְכָל כֹּהֵן שֶׁיִּרְצוּ שֶׁנֶּאֱמַר (במדבר ה י) \"וְאִישׁ אֶת קֳדָשָׁיו לוֹ יִהְיוּ\". וְאִם לָקַח שֶׁלֹּא מִדַּעַת בְּעָלִים זָכָה בָּהֶן שֶׁאֵין לַבְּעָלִים מֵהֶן אֶלָּא טוֹבַת הֲנָאָה וְטוֹבַת הֲנָאָה אֵינָהּ מָמוֹן:","כֹּהֵן שֶׁנָּתְנוּ לוֹ תְּרוּמָה וּמָצָא בָּהּ דְּבָרִים אֲחֵרִים הֲרֵי אֵלּוּ אֲסוּרִים מִשּׁוּם גֵּזֶל שֶׁמָּא אֲחֵרִים הִנִּיחוּם שָׁם עַד שֶׁיִּטְּלוּם:","אֵין יִשְׂרָאֵל חַיָּבִין לְהִטָּפֵל בַּתְּרוּמָה וְלַהֲבִיאָהּ מִן הַגֹּרֶן לָעִיר וּמִן הַמִּדְבָּר לַיִּשּׁוּב אֶלָּא כֹּהֲנִים יוֹצְאִין לָגֳרָנוֹת וְיִשְׂרָאֵל נוֹתְנִים לָהֶם חֶלְקָן שָׁם. וְאִם לֹא יָצְאוּ הֲרֵי זֶה מַפְרִישׁ וּמַנִּיחָהּ בַּגֹּרֶן. וְאִם הָיְתָה חַיָּה אוֹ בְּהֵמָה אוֹכַלְתָּהּ שָׁם וְאֵינָהּ מִשְׁתַּמֶּרֶת שָׁם מֵהֶם הִתְקִינוּ חֲכָמִים שֶׁיִּטָפֵל בָּהּ וִיבִיאֶנָּה לָעִיר וְיִטּל שְׂכַר הֲבָאָתָהּ מִכֹּהֵן. שֶׁאִם הִפְרִישָׁהּ וְהִנִּיחָהּ לִבְהֵמָה וּלְחַיָּה הֲרֵי זֶה חִלּוּל הַשֵּׁם:","אָסוּר לְכֹהֲנִים וּלְוִיִּם לְסַיֵּעַ בְּבֵית הַגֳּרָנוֹת כְּדֵי לִטּל מַתְּנוֹתֵיהֶן. וְכָל הַמְסַיֵּעַ חִלֵּל קֹדֶשׁ הַשֵּׁם. וַעֲלֵיהֶם נֶאֱמַר (מלאכי ב ח) \"שִׁחַתֶּם בְּרִית הַלֵּוִי\". וְאָסוּר לְיִשְׂרָאֵל לְהַנִּיחוֹ שֶׁיְּסַיְּעֵהוּ אֶלָּא נוֹתֵן לָהֶם חֶלְקָן בְּכָבוֹד:","נָתַן תְּרוּמָה לְכֹהֵן עַל מְנָת לְהַחֲזִירָהּ יָצָא יְדֵי נְתִינָה. וְאָסוּר לַעֲשׂוֹת כֵּן מִפְּנֵי שֶׁנִּמְצָא כִּמְסַיֵּעַ בְּבֵית הַגֳּרָנוֹת. וְכֵן אָסוּר לָהֶן שֶׁיַּחְטְפוּ תְּרוּמוֹת וּמַעַשְׂרוֹת וַאֲפִלּוּ לִשְׁאל חֶלְקָן בְּפִיהֶן אָסוּר אֶלָּא נוֹטְלִין בְּכָבוֹד. שֶׁעַל שֻׁלְחַן הַמָּקוֹם הֵם אוֹכְלִין וְעַל שֻׁלְחָנוֹ הֵם שׁוֹתִים וּמַתָּנוֹת אֵלּוּ לַה' הֵם וְהוּא זִכָּה לָהֶן שֶׁנֶּאֱמַר (במדבר יח ח) \"וַאֲנִי נָתַתִּי לְךָ אֶת מִשְׁמֶרֶת תְּרוּמֹתָי\":","לֹא יִתֵּן אָדָם תְּרוּמָה לְשׁוֹמֵר גִּתּוֹ. וְלֹא בְּכוֹר לְשׁוֹמֵר עֶדְרוֹ. וְלֹא מַתָּנוֹת לְרוֹעֵה בְּהֶמְתּוֹ. וְאִם נָתַן חִלֵּל אֶלָּא אִם כֵּן נָתַן לָהֶם שְׂכַר שְׁמִירָתָן תְּחִלָּה. וְרַשַּׁאי יִשְׂרָאֵל לוֹמַר לְיִשְׂרָאֵל אַחֵר הָא לְךָ סֶלַע זוֹ וְתֵן תְּרוּמָה אוֹ בְּכוֹר אוֹ שְׁאָר מַתָּנוֹת לִפְלוֹנִי הַכֹּהֵן בֶּן בִּתִּי אוֹ בֶּן אֲחוֹתִי. וְכָל כַּיּוֹצֵא בָּזֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הַבְּעָלִים רוֹצִים לִתֵּן אוֹתָם לְאֶחָד מִשְּׁנֵי כֹּהֲנִים אֵלּוּ אוֹ לְאֶחָד מִשְּׁנֵי לְוִיִּים אֵלּוּ בְּחִנָּם וְאָמַר לוֹ חֲבֵרוֹ הֵא לְךָ וְתֵן לָזֶה. אֲבָל הַבְּעָלִים שֶׁאָמְרוּ לַכֹּהֵן אוֹ לַלֵּוִי הֵא לְךָ חֵלֶק זֶה בְּטוֹבַת הֲנָאָה הֲרֵי זֶה אָסוּר. וְכֵן אָסוּר לַעֲשׂוֹת סְחוֹרָה בִּתְרוּמוֹת אַף עַל פִּי שֶׁהוּא לוֹקֵחַ מִכֹּהֵן וּמוֹכֵר לְכֹהֵן:","עֲשָׂרָה אֵין חוֹלְקִין לָהֶן תְּרוּמָה בְּבֵית הַגֳּרָנוֹת אַף עַל פִּי שֶׁהֵן אוֹכְלִין אוֹתָהּ אוֹ מַאֲכִילִין אוֹתָהּ. וְאֵלּוּ הֵן. הַחֵרֵשׁ. וְהַשּׁוֹטֶה. וְהַקָּטָן שֶׁאֵין בּוֹ דַּעַת לִפְרשׁ חֻקּוֹ. מִפְּנֵי שֶׁאֵין בְּאֵלּוּ דַּעַת. וְהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס מִפְּנֵי שֶׁהֵן בְּרִיָּה בִּפְנֵי עַצְמָן. וְהָעֶבֶד שֶׁמָּא יִרְאוּהוּ הָעוֹבְרִים בַּשָּׂדֶה וְיָעִידוּ עָלָיו שֶׁהוּא כֹּהֵן. וְהֶעָרֵל וְהַטָּמֵא מִפְּנֵי שֶׁהֵן מְאוּסִין. וְהָאִשָּׁה שֶׁמָּא תִּתְגָּרֵשׁ וּמִפְּנֵי הַיִּחוּד. וְהַנּוֹשֵׂא אִשָּׁה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ קָנְסוּ אוֹתוֹ שֶׁלֹּא יַחֲלֹק בְּבֵית הַגֳּרָנוֹת עַד שֶׁיְּגָרְשֶׁנָּה. וְכֻלָּן מְשַׁלְּחִין לָהֶן לְבָתֵּיהֶן וְחוֹלְקִין לָהֶן כִּשְׁאָר קָדְשֵׁי הַגְּבוּל. חוּץ מִן הַנּוֹשֵׂא אִשָּׁה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ וְהַטָּמֵא וְהֶעָרֵל שֶׁאֵין מְשַׁלְּחִין לָהֶן כְּלָל:"],"Mishneh Torah, Hiring 1":["אַרְבָּעָה שׁוֹמְרִים נֶאֶמְרוּ בַּתּוֹרָה וּשְׁלֹשָׁה דִּינִין יֵשׁ לָהֶם. וְאֵלּוּ הֵן הָאַרְבָּעָה שׁוֹמְרִין. שׁוֹמֵר חִנָּם. וְהַשּׁוֹאֵל. וְנוֹשֵׂא שָׂכָר. וְהַשּׂוֹכֵר:","וְאֵלּוּ הֵן שְׁלֹשָׁה דִּינִין שֶׁלָּהֶן. שׁוֹמֵר חִנָּם שֶׁנִּגְנַב הַפִּקָּדוֹן מִמֶּנּוּ אוֹ אָבַד וְאֵין צָרִיךְ לוֹמַר אִם נֶאֱנַס הַפִּקָּדוֹן אֹנֶס גָּדוֹל כְּגוֹן שֶׁהָיְתָה בְּהֵמָה וּמֵתָה אוֹ נִשְׁבֵּית הֲרֵי זֶה נִשְׁבָּע שֶׁשָּׁמַר כְּדֶרֶךְ הַשּׁוֹמְרִין וּפָטוּר שֶׁנֶּאֱמַר (שמות כב ו) \"וְגֻנַּב מִבֵּית הָאִישׁ\" וְגוֹ' (שמות כב ז) \"וְנִקְרַב בַּעַל הַבַּיִת אֶל הָאֱלֹהִים\". הַשּׁוֹאֵל מְשַׁלֵּם הַכּל בֵּין שֶׁאָבַד דָּבָר הַשָּׁאוּל אוֹ נִגְנַב בֵּין שֶׁאֵרְעוֹ אֹנֶס גָּדוֹל מִזֶּה כְּגוֹן שֶׁמֵּתָה הַבְּהֵמָה הַשְּׁאוּלָה אוֹ נִשְׁבְּרָה אוֹ נִשְׁבֵּית שֶׁכָּךְ כָּתוּב בְּשׁוֹאֵל (שמות כב יג) \"וְנִשְׁבַּר אוֹ מֵת בְּעָלָיו אֵין עִמּוֹ שַׁלֵּם יְשַׁלֵּם\". נוֹשֵׂא שָׂכָר אוֹ הַשּׂוֹכֵר שְׁנֵיהֶם דִּין אֶחָד יֵשׁ לָהֶן אִם נִגְנַב אוֹ אָבַד הַדָּבָר הַשָּׂכוּר אוֹ שֶׁנָּטַל שָׂכָר עַל שְׁמִירָתוֹ הֲרֵי אֵלּוּ מְשַׁלְּמִים. וְאִם אֵרְעוֹ אֹנֶס גָּדוֹל מִזֶּה כְּגוֹן שֶׁהָיְתָה בְּהֵמָה וּמֵתָה אוֹ נִשְׁבְּרָה אוֹ נִשְׁבֵּית אוֹ נִטְרְפָה הֲרֵי אֵלּוּ נִשְׁבָּעִין שֶׁנֶּאֶנְסָה וּפְטוּרִין שֶׁנֶּאֱמַר (שמות כב ט) \"וּמֵת אוֹ נִשְׁבַּר אוֹ נִשְׁבָּה אֵין רֹאֶה\" (שמות כב י) \"שְׁבֻעַת ה'\" וְגוֹ' וּכְתִיב (שמות כב יא) \"אִם גָּנֹב יִגָּנֵב מֵעִמּוֹ יְשַׁלֵּם לִבְעָלָיו\" וְגוֹ'. נִמְצֵאתָ אוֹמֵר שׁוֹמֵר חִנָּם נִשְׁבָּע עַל הַכּל. וְהַשּׁוֹאֵל מְשַׁלֵּם אֶת הַכּל חוּץ מִן הַמֵּתָה בִּשְׁעַת מְלָאכָה כְּמוֹ שֶׁיִּתְבָּאֵר. נוֹשֵׂא שָׂכָר וְהַשּׂוֹכֵר מְשַׁלְּמִין אֶת הָאֲבֵדָה וְאֶת הַגְּנֵבָה וְנִשְׁבָּעִין עַל הָאֳנָסִין הַגְּדוֹלִים כְּגוֹן שְׁבוּרָה וּשְׁבוּיָה וּמֵתָה וּטְרֵפָה. אוֹ שֶׁאָבַד הַדָּבָר בִּסְפִינָה שֶׁטָּבְעָה בַּיָּם אוֹ נִלְקַח בְּלִסְטִים מְזֻיָּן וְכָל כַּיּוֹצֵא בְּאֵלּוּ מִשְּׁאָר אֳנָסִין הַגְּדוֹלִים:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ בֵּין בְּחִנָּם בֵּין בְּשָׂכָר אוֹ הִשְׁאִילוֹ אוֹ הִשְׂכִּירוֹ אִם שָׁאַל הַשּׁוֹמֵר אֶת הַבְּעָלִים עִם הַדָּבָר שֶׁלָּהֶן אוֹ שְׂכָרָן הֲרֵי הַשּׁוֹמֵר פָּטוּר מִכְּלוּם. אֲפִלּוּ פָּשַׁע בַּדָּבָר שֶׁשָּׁמַר וְאָבַד מֵחֲמַת הַפְּשִׁיעָה הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (שמות כב יד) \"אִם בְּעָלָיו עִמּוֹ לֹא יְשַׁלֵּם אִם שָׂכִיר הוּא בָּא בִּשְׂכָרוֹ\". בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁשָּׁאַל הַבְּעָלִים אוֹ שְׂכָרָן בְּעֵת שֶׁנָּטַל הַחֵפֶץ אַף עַל פִּי שֶׁאֵין הַבְּעָלִים שָׁם עִמּוֹ בְּעֵת הַגְּנֵבָה וְהָאֲבֵדָה אוֹ בְּעֵת שֶׁנֶּאֱנַס. אֲבָל נָטַל הַחֵפֶץ וְנַעֲשָׂה עָלָיו שׁוֹמֵר תְּחִלָּה וְאַחַר כָּךְ שָׂכַר הַבְּעָלִים אוֹ שְׁאָלָן אַף עַל פִּי שֶׁהָיוּ הַבְּעָלִים עוֹמְדִין שָׁם בְּעֵת שֶׁנֶּאֱנַס הַדָּבָר הַשָּׁמוּר הֲרֵי זֶה מְשַׁלֵּם שֶׁנֶּאֱמַר (שמות כב יג) \"בְּעָלָיו אֵין עִמּוֹ שַׁלֵּם יְשַׁלֵּם\" מִפִּי הַשְּׁמוּעָה לָמְדוּ הָיָה עִמּוֹ בִּשְׁעַת הַשְׁאָלָה אַף עַל פִּי שֶׁאֵינוֹ בְּעֵת הַגְּנֵבָה וְהַמִּיתָה פָּטוּר לֹא הָיָה עִמּוֹ בִּשְׁעַת הַשְׁאָלָה אַף עַל פִּי שֶׁהָיָה עִמּוֹ בְּעֵת הַמִּיתָה אוֹ הַשְּׁבִיָּה חַיָּב. וְהוּא הַדִּין לִשְׁאָר הַשּׁוֹמְרִים שֶׁכֻּלָּן בִּבְעָלִים פְּטוּרִין אֲפִלּוּ פְּשִׁיעָה בִּבְעָלִים פָּטוּר:","כָּל שׁוֹמֵר שֶׁפָּשַׁע בִּתְחִלָּתוֹ אַף עַל פִּי שֶׁנֶּאֱנַס בְּסוֹפוֹ חַיָּב כְּמוֹ שֶׁיִּתְבָּאֵר. וְאֵין הַשּׁוֹאֵל רַשַּׁאי לְהַשְׁאִיל אֲפִלּוּ שָׁאַל סֵפֶר תּוֹרָה שֶׁכָּל שֶׁקּוֹרֵא בּוֹ עוֹשֶׂה מִצְוָה לֹא יַשְׁאִילֶנּוּ לְאַחֵר. וְכֵן אֵין הַשּׂוֹכֵר רַשַּׁאי לְהַשְׂכִּיר אֲפִלּוּ הִשְׂכִּירוֹ סֵפֶר תּוֹרָה לֹא יַשְׂכִּירֶנּוּ לְאַחֵר שֶׁהֲרֵי זֶה אוֹמֵר לוֹ אֵין רְצוֹנִי שֶׁיִּהְיֶה פִּקְדוֹנִי בְּיַד אַחֵר. עָבַר הַשּׁוֹמֵר וּמָסַר לַשּׁוֹמֵר הַשֵּׁנִי אִם יֵשׁ עֵדִים שֶׁשְּׁמָרָהּ הַשּׁוֹמֵר הַשֵּׁנִי כְּדֶרֶךְ הַשּׁוֹמְרִין וְנֶאֱנַס פָּטוּר הַשּׁוֹמֵר הָרִאשׁוֹן שֶׁהֲרֵי יֵשׁ עֵדִים שֶׁנֶּאֱנַס. וְאִם אֵין שָׁם עֵדִים חַיָּב הַשּׁוֹמֵר הָרִאשׁוֹן לְשַׁלֵּם לַבְּעָלִים מִפְּנֵי שֶׁמָּסַר לְשׁוֹמֵר אַחֵר וְיַעֲשֶׂה הוּא דִּין עִם הַשּׁוֹמֵר הַשֵּׁנִי. אֲפִלּוּ הָיָה הָרִאשׁוֹן שׁוֹמֵר חִנָּם וּמָסַר לְשׁוֹמֵר שָׂכָר חַיָּב שֶׁהֲרֵי יֵשׁ לְבַעַל הַחֵפֶץ לוֹמַר לוֹ אַתָּה נֶאֱמָן אֶצְלִי לְהִשָּׁבַע וְזֶה אֵינוֹ נֶאֱמָן. לְפִיכָךְ אִם הָיָה דֶּרֶךְ הַבְּעָלִים לְהַפְקִיד תָּמִיד דָּבָר זֶה אֵצֶל הַשּׁוֹמֵר הַשֵּׁנִי הֲרֵי זֶה הַשּׁוֹמֵר הָרִאשׁוֹן פָּטוּר מִלְּשַׁלֵּם שֶׁהֲרֵי הוּא אוֹמֵר לַבְּעָלִים זֶה הַדָּבָר שֶׁהִפְקַדְתֶּם אֶצְלִי אוֹ הִשְׁאַלְתֶּם אֶמֶשׁ הֱיִיתֶם מַפְקִידִין אוֹתוֹ אֵצֶל זֶה שֶׁהִפְקַדְתִּי אֲנִי אֶצְלוֹ. וְהוּא שֶׁלֹּא יְמַעֵט שְׁמִירָתוֹ. כֵּיצַד יְמַעֵט שְׁמִירָתוֹ. כְּגוֹן שֶׁהָיָה מֻפְקָד אֶצְלוֹ בְּשָׂכָר וְהִפְקִידוֹ אֵצֶל אוֹתוֹ הַשֵּׁנִי בְּחִנָּם אוֹ שֶׁהָיָה שָׁאוּל אֶצְלוֹ וְהִפְקִידוֹ אֵצֶל אוֹתוֹ הַשֵּׁנִי בְּשָׂכָר הוֹאִיל וּמִעֵט שְׁמִירָתוֹ פּוֹשֵׁעַ הוּא וּמְשַׁלֵּם. אַף עַל פִּי שֶׁשָּׁאַל אוֹ שֶׁשָּׂכַר בַּבְּעָלִים הֲרֵי הוּא הוֹצִיא הַדָּבָר הַשָּׁמוּר מִיָּדוֹ לְיַד שׁוֹמֵר אַחֵר:","וְאִם הֵבִיא הַשּׁוֹמֵר הַשֵּׁנִי הָרְאָיָה שֶׁיִּפָּטֵר בָּהּ שׁוֹמֵר רִאשׁוֹן כְּדִין שְׁמִירָתוֹ הֲרֵי זֶה פָּטוּר. כֵּיצַד. שׁוֹמֵר שָׂכָר שֶׁנָּתַן הַבְּהֵמָה הַשְּׁמוּרָה אֶצְלוֹ לְשׁוֹמֵר חִנָּם אִם הֵבִיא הַשּׁוֹמֵר הַשֵּׁנִי עֵדִים שֶׁמֵּתָה הַבְּהֵמָה כְּדַרְכָּהּ הֲרֵי הַשּׁוֹמֵר הָרִאשׁוֹן פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שׁוֹמֵר שֶׁמָּסַר לְשׁוֹמֵר אַחֵר וְהוֹסִיף בִּשְׁמִירָתוֹ וּמֵתָה הַהֲנָאָה לַבְּעָלִים. כֵּיצַד. הַשּׂוֹכֵר פָּרָה מֵחֲבֵרוֹ וְהִשְׁאִילָהּ לְאַחֵר וּמֵתָה כְּדַרְכָּהּ בְּיַד הַשּׁוֹאֵל הוֹאִיל וְהַשּׁוֹאֵל חַיָּב בַּכּל יַחְזִירוּ דְּמֵי הַפָּרָה לַבְּעָלִים שֶׁאֵין זֶה הַשּׂוֹכֵר עוֹשֶׂה סְחוֹרָה בְּפָרָתוֹ שֶׁל חֲבֵרוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הָיָה בְּיָדוֹ פִּקָּדוֹן וּשְׁלָחוֹ בְּיַד אַחֵר לִבְעָלָיו הוֹאִיל וְהַשּׁוֹמֵר הָרִאשׁוֹן חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיַּגִּיעַ לְיַד הַבְּעָלִים אִם בָּא לַחְזֹר וּלְהַחְזִיר הַפִּקָּדוֹן מִיַּד הַשּׁוֹמֵר הַשֵּׁנִי מַחְזִיר. וְאִם הֻחְזַק הַשּׁוֹמֵר הָרִאשׁוֹן כַּפְרָן אֵינוֹ יָכוֹל לְהַחְזִיר הַפִּקָּדוֹן מִיַּד הַשּׁוֹמֵר הַשֵּׁנִי אַף עַל פִּי שֶׁעֲדַיִן הַפִּקָּדוֹן בְּאַחֲרָיוּתוֹ שֶׁל רִאשׁוֹן:"],"Mishneh Torah, Hiring 9":["הַשׂוֹכֵר אֶת הַפּוֹעֲלִים וְאָמַר לָהֶם לְהַשְׁכִּים וּלְהַעֲרִיב מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לְהַשְׁכִּים וְשֶׁלֹּא לְהַעֲרִיב אֵינוֹ יָכוֹל לְכוּפָן. מָקוֹם שֶׁנָּהֲגוּ לָזוּן יָזוּן. לְסַפֵּק בִּגְרוֹגָרוֹת אוֹ בִּתְמָרִים וְכַיּוֹצֵא בָּהֶן לְפוֹעֲלִים יְסַפֵּק הַכֹּל כְּמִנְהַג הַמְּדִינָה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל וְאָמַר לוֹ כְּאֶחָד וְכִשְׁנַיִם מִבְּנֵי הָעִיר רוֹאִין הַפָּחוּת שֶׁבַּשְּׂכִירוּת וְהַיָּתֵר שֶׁבַּשְּׂכִירוּת וּמְשַׁמְּנִין בֵּינֵיהֶן:","אָמַר לִשְׁלוּחוֹ צֵא וּשְׂכֹר לִי פּוֹעֲלִים בִּשְׁלֹשָׁה וְהָלַךְ וּשְׂכָרָן בְּאַרְבָּעָה אִם אָמַר לָהֶם הַשָּׁלִיחַ שְׂכַרְכֶם עָלַי נוֹתֵן לָהֶם אַרְבָּעָה וְנוֹטֵל מִבַּעַל הַבַּיִת שְׁלֹשָׁה וּמַפְסִיד אֶחָד מִכִּיסוֹ. אָמַר לָהֶם שְׂכַרְכֶם עַל בַּעַל הַבַּיִת נוֹתֵן לָהֶם בַּעַל הַבַּיִת כְּמִנְהַג הַמְּדִינָה. הָיָה בַּמְּדִינָה מִי שֶׁנִּשְׂכַּר בִּשְׁלֹשָׁה וּמִי שֶׁנִּשְׂכַּר בְּאַרְבָּעָה אֵינוֹ נוֹתֵן לָהֶם אֶלָּא שְׁלֹשָׁה וְיֵשׁ לָהֶם תַּרְעֹמֶת עַל הַשָּׁלִיחַ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאֵין מְלַאכְתָּן נִכֶּרֶת אֲבָל הָיְתָה מְלַאכְתָּן נִכֶּרֶת וַהֲרֵי הִיא שָׁוָה אַרְבָּעָה נוֹתֵן לָהֶם בַּעַל הַבַּיִת אַרְבָּעָה שֶׁאִלּוּ לֹא אָמַר לָהֶם שְׁלוּחוֹ אַרְבָּעָה לֹא טָרְחוּ וְעָשׂוּ שָׁוֶה אַרְבָּעָה. אָמַר לוֹ בַּעַל הַבַּיִת שְׂכֹר לִי בְּאַרְבָּעָה וְהָלַךְ הַשָּׁלִיחַ וְשָׂכַר בִּשְׁלֹשָׁה אַף עַל פִּי שֶׁהֲרֵי מְלַאכְתָּן שָׁוָה אַרְבָּעָה אֵין לָהֶם אֶלָּא שְׁלֹשָׁה שֶׁהֲרֵי קִבְּלוּ עַל עַצְמָן וְיֵשׁ לָהֶם תַּרְעֹמֶת עַל הַשָּׁלִיחַ. אָמַר לוֹ בַּעַל הַבַּיִת בִּשְׁלֹשָׁה וְהָלַךְ הַשָּׁלִיחַ וְאָמַר לָהֶם בְּאַרְבָּעָה וְאָמְרוּ הֲרֵינוּ כְּמָה שֶּׁאָמַר בַּעַל הַבַּיִת אֵין דַּעְתָּם אֶלָּא שֶׁיִּתֵּן בַּעַל הַבַּיִת יֶתֶר עַל אַרְבָּעָה לְפִיכָךְ שָׁמִין מַה שֶּׁעָשׂוּ אִם שָׁוָה אַרְבָּעָה נוֹטְלִין אַרְבָּעָה מִבַּעַל הַבַּיִת וְאִם אֵינוֹ יָדוּעַ אוֹ אֵינוֹ שָׁוֶה אֵין לָהֶם אֶלָּא שְׁלֹשָׁה. אָמַר לוֹ בַּעַל הַבַּיִת בְּאַרְבָּעָה וְהָלַךְ הַשָּׁלִיחַ וְאָמַר לָהֶם בִּשְׁלֹשָׁה וְאָמְרוּ לוֹ כְּמָה שֶׁאָמַר בַּעַל הַבַּיִת אַף עַל פִּי שֶׁמְּלַאכְתָּן שָׁוֶה אַרְבָּעָה אֵין לָהֶם אֶלָּא שְׁלֹשָׁה שֶׁהֲרֵי שָׁמְעוּ שְׁלֹשָׁה וְקִבְּלוּ עֲלֵיהֶם:","הַשּׂוֹכֵר אֶת הַפּוֹעֲלִים וְהִטְעוּ אֶת בַּעַל הַבַּיִת אוֹ בַּעַל הַבַּיִת הִטְעָה אוֹתָם אֵין לָהֶם זֶה עַל זֶה אֶלָּא תַּרְעֹמֶת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָלְכוּ. אֲבָל הָלְכוּ הַחַמָּרִין וְלֹא מָצְאוּ תְּבוּאָה. פּוֹעֲלִים וּמָצְאוּ שָׂדֶה כְּשֶׁהִיא לָחָה. אוֹ שֶׁשָּׂכַר לְהַשְׁקוֹת הַשָּׂדֶה וּמְצָאוּהָ שֶׁנִּתְמַלְּאָה מַיִם. אִם בִּקֵּר בַּעַל הַבַּיִת מְלַאכְתּוֹ מִבָּעֶרֶב וּמָצָא שֶׁצְּרִיכָה פּוֹעֲלִים אֵין לַפּוֹעֲלִים כְּלוּם מַה בְּיָדוֹ לַעֲשׂוֹת. וְאִם לֹא בִּקֵּר נוֹתֵן לָהֶם שְׂכָרָן כְּפוֹעֵל בָּטֵל שֶׁאֵינוֹ דּוֹמֶה הַבָּא טָעוּן לְבָא רֵיקָן וְעוֹשֶׂה מְלָאכָה לְבַטֵּל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הִתְחִילוּ בִּמְלָאכָה. אֲבָל אִם הִתְחִיל הַפּוֹעֵל בַּמְּלָאכָה וְחָזַר בּוֹ אֲפִלּוּ בַּחֲצִי הַיּוֹם חוֹזֵר שֶׁנֶּאֱמַר (ויקרא כה נה) \"כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים\" וְלֹא עֲבָדִים לַעֲבָדִים. וְכֵיצַד דִּין הַפּוֹעֵל שֶׁחָזַר בּוֹ אַחַר שֶׁהִתְחִיל. שָׁמִין לוֹ מַה שֶּׁעָשָׂה וְנוֹטֵל. וְאִם קַבְּלָן הוּא שָׁמִין לוֹ מַה שֶּׁעָתִיד לַעֲשׂוֹת. בֵּין שֶׁהוּזְלוּ בְּעֵת שֶׁשְּׂכָרָן בֵּין לֹא הוּזְלוּ בֵּין שֶׁהוּזְלָה מְלָאכָה אַחַר כֵּן בֵּין לֹא הוּזְלָה שָׁמִין לוֹ מַה שֶּׁעָתִיד לַעֲשׂוֹת. כֵּיצַד. קִבֵּל מִמֶּנּוּ קָמָה לִקְצֹר בִּשְׁתֵּי סְלָעִים קָצַר חֶצְיָהּ וְהִנִּיחַ חֶצְיָהּ. בֶּגֶד לֶאֱרֹג בִּשְׁתֵּי סְלָעִים אָרַג חֶצְיוֹ וְהִנִּיחַ חֶצְיוֹ. שָׁמִין לוֹ מַה שֶּׁעָתִיד לַעֲשׂוֹת. אִם הָיָה שָׁוֶה שִׁשָּׁה דִּינָרִין נוֹתֵן לוֹ שֶׁקֶל אוֹ יִגְמְרוּ אֶת מְלַאכְתָּן. וְאִם הָיָה הַנִּשְׁאָר יָפֶה שְׁנַיִם דִּינָרִין אֵינוֹ נוֹתֵן לָהֶן אֶלָּא סֶלַע שֶׁהֲרֵי לֹא עָשׂוּ אֶלָּא חֲצִי מְלָאכָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵינוֹ אָבוּד אֲבָל בְּדָבָר הָאָבוּד כְּגוֹן פִּשְׁתָּנוֹ לְהַעֲלוֹת מִן הַמִּשְׁרָה אוֹ שֶׁשָּׂכַר חֲמוֹר לְהָבִיא חֲלִילִין לְמֵת אוֹ לְכַלָּה וְכַיּוֹצֵא בָּהֶן אֶחָד פּוֹעֵל וְאֶחָד קַבְּלָן אֵינוֹ יָכוֹל לַחְזֹר בּוֹ אֶלָּא אִם כֵּן נֶאֱנַס כְּגוֹן שֶׁחָלָה אוֹ שָׁמַע שֶׁמֵּת לוֹ מֵת. וְאִם לֹא נֶאֱנַס וְחָזַר בּוֹ שׂוֹכֵר עֲלֵיהֶן אוֹ מַטְעָן. כֵּיצַד מַטְעָן. אוֹמֵר לָהֶם סֶלַע קָצַצְתִּי לָכֶם בּוֹאוּ וּטְלוּ שְׁתַּיִם עַד שֶׁיִּגְמְרוּ מְלַאכְתָּן וְלֹא יִתֵּן לָהֶם אֶלָּא מַה שֶּׁפָּסַק תְּחִלָּה וַאֲפִלּוּ נָתַן לָהֶם הַשְּׁתַּיִם מַחְזִיר מֵהֶן הַתּוֹסֶפֶת. כֵּיצַד שׂוֹכֵר עֲלֵיהֶן. שׂוֹכֵר פּוֹעֲלִים אֲחֵרִים וְגוֹמְרִים מְלַאכְתָּן שֶׁלֹּא תֹּאבַד וְכָל שֶׁיּוֹסִיף לְאֵלּוּ הַפּוֹעֲלִין הָאֲחֵרִים עַל מַה שֶּׁפָּסַק לָרִאשׁוֹנִים נוֹטֵל מִן הָרִאשׁוֹנִים. עַד כַּמָּה עַד כְּדֵי שְׂכָרָן שֶׁל רִאשׁוֹנִים. וְאִם הָיָה לָהֶם מָמוֹן תַּחַת יָדוֹ שׂוֹכֵר לְהַשְׁלִים הַמְּלָאכָה עַד אַרְבָּעִים וַחֲמִשִּׁים זוּז בְּכָל יוֹם לְכָל פּוֹעֵל אַף עַל פִּי שֶׁשָּׂכַר הַפּוֹעֵל שְׁלֹשָׁה אוֹ אַרְבָּעָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵין שָׁם פּוֹעֲלִים לִשְׂכֹּר בִּשְׂכָרָן לְהַשְׁלִים הַמְּלָאכָה אֲבָל יֵשׁ פּוֹעֲלִים לִשְׂכֹּר בִּשְׂכָרָן וְאָמְרוּ לוֹ צֵא וּשְׂכֹר מֵאֵלּוּ לְהַשְׁלִים מְלַאכְתְּךָ וְלֹא תֹּאבַד בֵּין שׂוֹכֵר בֵּין קַבְּלָן אֵין לוֹ עֲלֵיהֶן אֶלָּא תַּרְעֹמֶת וְשָׁמִין לַשּׂוֹכֵר מַה שֶּׁעָשָׂה וְלַקַּבְּלָן מַה שֶּׁעָתִיד לַעֲשׂוֹת:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל וְנֶאֱחָז לַעֲבוֹדַת הַמֶּלֶךְ לֹא יֹאמַר לוֹ הֲרֵינִי לְפָנֶיךָ אֶלָּא נוֹתֵן לוֹ שְׂכַר מַה שֶּׁעָשָׂה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לְהַשְׁקוֹת אֶת הַשָּׂדֶה מִזֶּה הַנָּהָר וּפָסַק הַנָּהָר בַּחֲצִי הַיּוֹם אִם אֵין דַּרְכּוֹ לְהַפְסִיק אֵין לָהֶן אֶלָּא שְׂכַר מַה שֶּׁעָשׂוּ. וְכֵן אִם דַּרְכּוֹ שֶׁיַּפְסִיקוּ אוֹתוֹ בְּנֵי הָעִיר וְהִפְסִיקוּהוּ בַּחֲצִי הַיּוֹם אֵין לָהֶן אֶלָּא שְׂכַר מַה שֶּׁעָשׂוּ שֶׁהֲרֵי יָדְעוּ הַפּוֹעֲלִים דַּרְכּוֹ שֶׁל נָהָר. וְאִם דַּרְכּוֹ לְהַפְסִיק מֵאֵלָיו נוֹתֵן לָהֶם שְׂכַר כָּל הַיּוֹם מִפְּנֵי שֶׁהָיָה לוֹ לְהוֹדִיעָם. שְׂכָרָן לְהַשְׁקוֹת הַשָּׂדֶה וּבָא הַמָּטָר וְהִשְׁקָה אֵין לָהֶן אֶלָּא מַה שֶּׁעָשׂוּ. בָּא הַנָּהָר וְהִשְׁקָה נוֹתֵן לָהֶן כָּל שְׂכָרָן. מִן הַשָּׁמַיִם נִסְתַּיְּעוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּפוֹעֵל. אֲבָל מִי שֶׁפָּסַק עִם אֲרִיסוֹ שֶׁאִם יַשְׁקֶה שָׂדֶה זוֹ אַרְבַּע פְּעָמִים בְּיוֹם יִטּל חֲצִי הַפֵּרוֹת וְכָל הָאֲרִיסִין שֶׁהֵן מַשְׁקִין שְׁתֵּי פְּעָמִים אֵינָן נוֹטְלִין אֶלָּא רְבִיעַ הַפֵּרוֹת וּבָא הַמָּטָר וְלֹא הֻצְרַךְ לִדְלוֹת וּלְהַשְׁקוֹת נוֹטֵל חֲצִי הַפֵּרוֹת כְּמוֹ שֶׁפָּסַק עִמּוֹ שֶׁהָאָרִיס כְּשֻׁתָּף וְאֵינוֹ כְּפוֹעֵל:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לַעֲשׂוֹת מְלָאכָה כָּל הַיּוֹם וְשָׁלְמָה הַמְּלָאכָה בַּחֲצִי הַיּוֹם אִם יֵשׁ לוֹ מְלָאכָה אַחֶרֶת כְּמוֹתָהּ אוֹ קַלָּה מִמֶּנָּה עוֹשֶׂה שְׁאָר הַיּוֹם. וְאִם אֵין לוֹ מַה יַּעֲשֶׂה נוֹתֵן לוֹ שְׂכָרוֹ כְּפוֹעֵל בָּטֵל. וְאִם הָיָה מִן הַחוֹפְרִים אוֹ עוֹבְדֵי אֲדָמָה וְכַיּוֹצֵא בָּהֶן שֶׁדַּרְכּוֹ לִטְרֹחַ הַרְבֵּה וְאִם לֹא יַעֲשֶׂה בִּמְלָאכָה יֶחֱלֶה נוֹתֵן לוֹ כָּל שְׂכָרוֹ:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לְהָבִיא לוֹ שְׁלִיחוּת מִמָּקוֹם לְמָקוֹם וְהָלַךְ וְלֹא מָצָא שָׁם מַה יָּבִיא נוֹתֵן לוֹ שְׂכָרוֹ מִשָּׁלֵם. שְׂכָרוֹ לְהָבִיא קָנִים לַכֶּרֶם וְהָלַךְ וְלֹא מָצָא וְלֹא הֵבִיא נוֹתֵן לוֹ שְׂכָרוֹ מִשָּׁלֵם. שְׂכָרוֹ לְהָבִיא כְּרוּב וּדוֹרְמַסְקְנִין לַחוֹלֶה וְהָלַךְ וּמְצָאוֹ שֶׁמֵּת אוֹ הִבְרִיא לֹא יֹאמַר לוֹ טל מַה שֶּׁהֵבֵאתָ בִּשְׂכָרְךָ אֶלָּא נוֹתֵן לוֹ כָּל שְׂכָרוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לַעֲשׂוֹת עִמּוֹ בְּשֶׁלּוֹ וְהֶרְאָהוּ בְּשֶׁל חֲבֵרוֹ נוֹתֵן כָּל שְׂכָרוֹ וְחוֹזֵר וְלוֹקֵחַ מֵחֲבֵרוֹ מַה שֶּׁנֶּהֱנָה בְּזוֹ הַמְּלָאכָה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לַעֲשׂוֹת עִמּוֹ בְּתֶבֶן וְקַשׁ וְכַיּוֹצֵא בָּהֶן וְאָמַר לוֹ טל מַה שֶּׁעָשִׂיתָ בִּשְׂכָרְךָ אֵין שׁוֹמְעִין לוֹ. וְאִם מִשֶּׁקִּבֵּל עָלָיו אָמַר לוֹ הֵילָךְ שְׂכָרְךָ וַאֲנִי אֶטּל אֶת שֶׁלִּי אֵין שׁוֹמְעִין לוֹ:","מְצִיאַת הַפּוֹעֵל לְעַצְמוֹ אַף עַל פִּי שֶׁאָמַר לוֹ עֲשֵׂה עִמִּי מְלָאכָה הַיּוֹם. וְאֵין צָרִיךְ לוֹמַר אִם אָמַר לוֹ עֲדֹר עִמִּי הַיּוֹם. אֲבָל אִם שְׂכָרוֹ לִלְקֹט מְצִיאוֹת כְּגוֹן שֶׁחָסַר הַנָּהָר וּשְׂכָרוֹ לִלְקֹט הַדָּגִים הַנִּמְצָאִין בַּאֲגַם הֲרֵי מְצִיאָתוֹ לְבַעַל הַבַּיִת וַאֲפִלּוּ מָצָא כִּיס מָלֵא דִּינָרִין:"],"Mishneh Torah, Immersion Pools 3":["וְאֵלוּ חוֹצְצִין בְּכֵלִים. הַזֶּפֶת וְהַחֵמָר וְכַיּוֹצֵא בָּהֶן. הַזֶּפֶת שֶׁבַּכּוֹס וְשֶׁבַּצְּלוֹחִית מִתּוֹכָן חוֹצְצִין מֵאֲחוֹרֵיהֶן אֵינָן חוֹצְצִין. בַּמֶּה דְּבָרִים אֲמוּרִים מִבֵּית הָאֻמָּן. אֲבָל מִבַּעַל הַבַּיִת בֵּין מִתּוֹכָן בֵּין מֵאֲחוֹרֵיהֶן חוֹצְצִין. הַזֶּפֶת שֶׁבַּתַּמְחוּי וְשֶׁבַּקְּעָרָה בֵּין מִתּוֹכָן בֵּין מֵאֲחוֹרֵיהֶן בֵּין מִבַּעַל הַבַּיִת בֵּין מִבֵּית הָאֻמָּן חוֹצְצִין:","הַמּוֹר וְהַקּוֹמוֹס בֵּין בְּכוֹס בֵּין בִּצְלוֹחִית בֵּין בְּתַמְחוּי וּקְעָרָה בֵּין מִבַּעַל הַבַּיִת בֵּין מִבֵּית הָאֻמָּן בֵּין מִתּוֹכָן בֵּין מֵאֲחוֹרֵיהֶן חוֹצְצִין. הָיָה זֶפֶת אוֹ חֵמָר וְכַיּוֹצֵא בָּהֶן עַל הַטַּבְלָא וְעַל הַשֻּׁלְחָן וְעַל הַדַּרְגָּשׁ אִם הָיוּ נְקִיִּים חוֹצְצִין מִפְּנֵי שֶׁמַּקְפִּיד עֲלֵיהֶן. וְעַל הַבְּלוּסִין אֵינָן חוֹצְצִין מִפְּנֵי שֶׁאֵינוֹ מַקְפִּיד עֲלֵיהֶן:","הָיוּ עַל מִטּוֹת בַּעַל הַבַּיִת חוֹצְצִין עַל מִטּוֹת שֶׁל עָנִי אֵינָן חוֹצְצִין. עַל אֻכַּף בַּעַל הַבַּיִת חוֹצֵץ וְעַל זַקָּקִין אֵינוֹ חוֹצֵץ. עַל הַמִּרְדַּעַת מִשְּׁנֵי צְדָדִין חוֹצֵץ:","הָיוּ זֶפֶת אוֹ חֵמָר וְכַיּוֹצֵא בָּהֶן עַל בִּגְדֵי תַּלְמִידֵי חֲכָמִים אֲפִלּוּ מִצַּד אֶחָד חוֹצֵץ מִפְּנֵי שֶׁמַּקְפִּידִין עַל מַלְבּוּשָׁן לִהְיוֹת נָקִי. עַל בִּגְדֵי עַמֵּי הָאָרֶץ מִשְּׁנֵי צְדָדִין חוֹצֵץ מִצַּד אֶחָד אֵינוֹ חוֹצֵץ:","הָיוּ עַל הַמִּטְפָּחוֹת שֶׁל זַפָּתִים וְשֶׁל יוֹצְרִים וְשֶׁל מְפַסְּלֵי אִילָנוֹת אֵינָן חוֹצְצִין:","טַבָּח שֶׁהָיָה דָּם עַל בְּגָדָיו אֵינוֹ חוֹצֵץ מִפְּנֵי שֶׁאֵינוֹ מַקְפִּיד:","מוֹכֵר רְבָב שֶׁהָיָה רְבָב עַל בִּגְדוֹ אֵינוֹ חוֹצֵץ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הָיָה הַטַּבָּח מוֹכֵר רְבָב וְהָיָה עַל בִּגְדוֹ דָּם וּרְבָב הֲרֵי זֶה סָפֵק אִם חוֹצֵץ מִפְּנֵי שֶׁהֵן שְׁנַיִם וּמַקְפִּיד אוֹ אֵינוֹ חוֹצֵץ שֶׁהֲרֵי מְלַאכְתּוֹ הִיא וְאֵינוֹ מַקְפִּיד:","הָיָה הַזֶּפֶת אוֹ הַחֵמָר וְכַיּוֹצֵא בָּהֶן עַל הַסַּנְדָּל מִתּוֹכוֹ. מִלְּמַעְלָה חוֹצֵץ מִלְּמַטָּה אֵינוֹ חוֹצֵץ. עַל הַסַּפְסָל מִלְּמַעְלָה אוֹ מִן הַצְּדָדִין חוֹצֵץ מִלְּמַטָּה אֵינוֹ חוֹצֵץ:","לִכְלוּכֵי צוֹאָה שֶׁבַּכִּסֵּא וְשֶׁבַּקַּתֵּדְרָה הַמְכֻבָּשִׁין בֵּין מִתּוֹכָן בֵּין מֵאֲחוֹרֵיהֶן בֵּין מִלְּמַטָּה בֵּין מִן הַצְּדָדִין אֵינָן חוֹצְצִין מִפְּנֵי שֶׁהַמַּיִם מַעֲבִירִין אוֹתָן. אֲבָל לִכְלוּכֵי שְׁמָרִים שֶׁבַּכּוֹס וְשֶׁבַּצְּלוֹחִית וְהַמּוֹךְ שֶׁבַּשֵּׁיר וְשֶׁבַּזּוֹג. וְהַטִּיט וְהַבָּצֵק שֶׁעַל יַד הַקּוֹרְדוֹם וְשֶׁעַל יַד הַמַּגְרֵפָה [אֵינָן חוֹצְצִין. הִגְלִידוּ] חוֹצְצִין:","דָּבָר בָּרוּר הוּא שֶׁכָּל מָקוֹם שֶׁאָמַרְנוּ בְּזֶפֶת וּבְחֵמָר וְכַיּוֹצֵא בָּהֶן שֶׁאֵינָן חוֹצְצִין בְּכֵלִים מִפְּנֵי שֶׁאֵינוֹ מַקְפִּיד הוּא לְפִיכָךְ אִם הָיָה רֹב הַכְּלִי חָפוּי בְּזֶפֶת אוֹ בְּחֵמָר וְכַיּוֹצֵא בָּהֶן לֹא עָלְתָה לוֹ טְבִילָה כְּמוֹ שֶׁבֵּאַרְנוּ אַף עַל פִּי שֶׁאֵינוֹ מַקְפִּיד. אֵין בְּדָבָר זֶה הֶפְרֵשׁ בִּכְלִי מִן הַכֵּלִים אֶלָּא כָּל הַכֵּלִים שָׁוִין בְּדָבָר זֶה:","כָּל יְדוֹת הַכֵּלִים שֶׁהֵן חֲלוּלִין שֶׁהִכְנִיסָן שֶׁלֹּא כְּדַרְכָּן. אוֹ שֶׁהִכְנִיסָן כְּדַרְכָּן וְלֹא מֵרְקָן. אוֹ שֶׁהָיוּ שֶׁל מַתֶּכֶת וְנִשְׁבְּרוּ. לֹא עָלְתָה לָהֶן טְבִילָה:","כְּלִי שֶׁהָפַךְ פִּיו לְמַטָּה וְהִטְבִּילוֹ כְּאִלּוּ לֹא טָבַל מִפְּנֵי שֶׁאֵין הַמַּיִם נִכְנָסִין בְּכֻלּוֹ. הָיָה בּוֹ מָקוֹם שֶׁאֵין הַמַּיִם נִכְנָסִין בּוֹ עַד שֶׁיַּטֶּנּוּ עַל צִדּוֹ לֹא עָלְתָה לוֹ טְבִילָה עַד שֶׁיַּטֶּנּוּ עַל צִדּוֹ:","כְּלִי שֶׁהוּא צַר מִכָּאן וּמִכָּאן וְרָחָב בָּאֶמְצַע אֵינוֹ טָהוֹר עַד שֶׁיַּטֶּנּוּ עַל צִדּוֹ:","צְלוֹחִית שֶׁפִּיהָ שׁוֹקֵעַ אֵינָהּ טְהוֹרָה עַד שֶׁיַּטֶּנָּה עַל צִדָּהּ:","קַלְמָרִין אֵינָהּ טְהוֹרָה עַד שֶׁיִּקָּבֶנָּה מִצִּדָּהּ כְּדֵי שֶׁיִּכָּנְסוּ הַמַּיִם לָעַקְמוּמִיּוּת שֶׁבָּהּ:","בְּהֵמָה שֶׁהָיָה הַשֵּׁיר שֶׁעָלֶיהָ רָפוּי וְנִטְמָא מַטְבִּילִין אוֹתוֹ בִּמְקוֹמוֹ:","לֹא יַטְבִּיל אָדָם אֶת הַקֻּמְקוּם בְּפֶחָמִין שֶׁבּוֹ אֶלָּא אִם כֵּן שִׁפְשֵׁף:","כְּלִי שֶׁהוּא מָלֵא מַשְׁקִין וְהִטְבִּילוֹ כְּאִלּוּ לֹא טָבַל. הָיָה מָלֵא מַיִם וְהִטְבִּילוֹ הֲרֵי הַמַּיִם וְהַכְּלִי טְהוֹרִין כְּאַחַת מִפְּנֵי שֶׁהַמַּיִם יֵשׁ לָהֶן טָהֳרָה בְּמִקְוֶה כְּמוֹ שֶׁבֵּאַרְנוּ בְּטֻמְאַת אֳכָלִין וּמַשְׁקִין. הָיָה הַכְּלִי מָלֵא מֵי רַגְלַיִם רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא מַיִם. הָיָה בּוֹ מֵי חַטָּאת אִם הָיָה רֹב הַכְּלִי פָּנוּי כְּדֵי שֶׁיִּרְבּוּ מֵי מִקְוֶה עַל מֵי חַטָּאת שֶׁבְּתוֹכוֹ הֲרֵי זֶה טָהוֹר. וְאִם לָאו עֲדַיִן הוּא בְּטֻמְאָתוֹ וּכְאִלּוּ הֵן שְׁאָר מַשְׁקִין שֶׁחוֹצְצִין בֵּין גּוּף הַכְּלִי וּבֵין מֵי הַמִּקְוֶה:","כְּלִי שֶׁתּוֹכוֹ טָהוֹר וְגַבּוֹ טָמֵא וְהָיָה מָלֵא יַיִן לָבָן אוֹ חָלָב וְהִטְבִּילוֹ. הוֹלְכִין אַחַר הָרֹב אִם הָיָה רֹב הַכְּלִי פָּנוּי כְּדֵי שֶׁיִּרְבּוּ הַמַּיִם בְּתוֹכוֹ טָהוֹר מִפְּנֵי שֶׁטֻּמְאָתוֹ מִדִּבְרֵיהֶן. אֲבָל אִם הָיָה בּוֹ יַיִן אָדֹם אוֹ שְׁאָר מַשְׁקִין לֹא עָלְתָה לוֹ טְבִילָה:","לָגִין שֶׁהוּא מָלֵא מַיִם טְמֵאִין וְהָיָה עַל פִּיו טִיט טוֹפֵחַ וְהָיָה הַטִּיט שׁוֹקֵעַ בַּמַּיִם וְהִטְבִּילוֹ טָהוֹר. וְאִם הָיָה טִיט הַיָּוִן וְכַיּוֹצֵא בּוֹ כְּאִלּוּ לֹא טָבַל. וְכֵן טַבַּעַת שֶׁנְּתָנָהּ בִּלְבֵנָה שֶׁל טִיט טוֹפֵחַ וְהִטְבִּילָהּ טְהוֹרָה. וְאִם הָיָה טִיט יָוֵן כְּאִלּוּ לֹא טְבָלָהּ:","אֵלּוּ שֶׁאֵין צְרִיכִין שֶׁיָּבוֹאוּ הַמַּיִם בָּהֶן. סְתָם קִשְׁרֵי בִּגְדֵי עֲנִיִּים, וְאִם הִקְפִּיד עֲלֵיהֶן חוֹצְצִין. וְקִשְׁרֵי בִּגְדֵי בַּעֲלֵי בָּתִּים סְתָמָן חוֹצְצִין, וְאִם אֵינוֹ מַקְפִּיד עֲלֵיהֶן אֵינָן חוֹצְצִין. וְקִשְׁרֵי נִימֵי הַבְּגָדִים שֶׁנִּקְשְׁרוּ מֵאֲלֵיהֶן. וְחֵבֶט הַסַּנְדָּל. וּתְפִלָּה שֶׁל רֹאשׁ בִּזְמַן שֶׁהַקְּצִיצָה דְּבוּקָה עִם הָרְצוּעָה שֶׁבָּהּ וַחֲזָקָה. וּתְפִלָּה שֶׁל זְרוֹעַ בִּזְמַן שֶׁאֵינָהּ עוֹלָה וְיוֹרֶדֶת. וְאָזְנֵי הַחֵמֶת וְהַתּוּרְמִיל. וְכָל כַּיּוֹצֵא בְּאֵלּוּ מִקְּשָׁרִים וּתְפָרִים שֶׁאֵינוֹ עָתִיד לְהַתִּירָם:","וְאֵלּוּ שֶׁצְּרִיכִין שֶׁיָּבוֹאוּ בָּהֶן הַמַּיִם. הַקְּשָׁרִים שֶׁבְּפִתְחֵי הֶחָלוּק שֶׁהֵן עֲשׂוּיִין לוּלָאוֹת. וְכֵן קִשְׁרֵי לוּלָאוֹת שֶׁבַּכָּתֵף. וְשָׂפָה שֶׁל סָדִין צָרִיךְ לְמַתֵּחַ. וּתְפִלָּה שֶׁל רֹאשׁ בִּזְמַן שֶׁאֵינָהּ קְבוּעָה בִּרְצוּעָה. וְשֶׁל זְרוֹעַ בִּזְמַן שֶׁהִיא עוֹלָה וְיוֹרֶדֶת. וּשְׁנָצִים שֶׁל סַנְדָּל. וְקִשְׁרֵי נִימֵי הַבְּגָדִים שֶׁקְּשָׁרָן. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הַמְּקוֹמוֹת שֶׁהוּא עָתִיד לְגַלּוֹתָן וּלְמָתְחָן. הַסַּלִּין שֶׁל גַּת וְשֶׁל בַּד אִם הָיוּ חֲזָקִים צָרִיךְ לְחַטֵּט וְאִם הָיוּ רָפִים צָרִיךְ לְנַעֵר. הַכַּר וְהַכֶּסֶת שֶׁל עוֹר צְרִיכִים שֶׁיָּבוֹאוּ בָּהֶן הַמַּיִם:","כֶּסֶת עֲגֻלָּה. וְהַכַּדּוּר. וְהָאִמּוּם. וְהַקָּמֵעַ. וְהַתְּפִלָּה. אֵינָן צְרִיכִין שֶׁיָּבוֹאוּ הַמַּיִם לַחֲלָלָן. זֶה הַכְּלָל כָּל שֶׁאֵין דַּרְכּוֹ לְהוֹצִיא וּלְהַכְנִיס טוֹבֵל סָתוּם:","הַמַּטְבִּיל בְּגָדִים הַמְכֻבָּסִין צְרִיכִין שֶׁיִּכָּנְסוּ בָּהֶן הַמַּיִם עַד שֶׁיְּבַעְבְּעוּ. הִטְבִּילָן נְגוּבִין עַד שֶׁיְּבַעְבְּעוּ וְיָנוּחוּ מִבִּעֲבּוּעָן:","כָּל יְדוֹת הַכֵּלִים שֶׁהֵן אֲרֻכִּים יוֹתֵר מִכְּדֵי צָרְכָּן וְעָתִיד לְקָצְצָן מַטְבִּילָן עַד מְקוֹם הַמִּדָּה. כֵּיצַד. שַׁלְשֶׁלֶת דְּלִי גָּדוֹל אַרְבָּעָה טְפָחִים וְקָטָן עֲשָׂרָה. מַטְבִּיל מִן הַשַּׁלְשֶׁלֶת עַד מִדָּה זוֹ בִּלְבַד וְהַשְּׁאָר טָהוֹר:","כְּלִי טָמֵא שֶׁנָּתַן בְּתוֹכוֹ כֵּלִים אֲחֵרִים וְהִטְבִּיל הַכּל עָלְתָה לָהֶן טְבִילָה אַף עַל פִּי שֶׁפִּי הַכְּלִי צַר בְּיוֹתֵר שֶׁהֲרֵי הַמַּיִם נִכְנָסִין לוֹ וּמִתּוֹךְ שֶׁעָלְתָה טְבִילָה לַכְּלִי הַגָּדוֹל עָלְתָה טְבִילָה לַכֵּלִים שֶׁבְּתוֹכוֹ. וְאִם הִטָּהוּ עַל צִדּוֹ וְהִטְבִּיל לֹא עָלְתָה לָהֶן טְבִילָה עַד שֶׁיִּהְיֶה פִּיו רָחָב כִּשְׁפוֹפֶרֶת הַנּוֹד. וְכֵן אִם הָיָה הַכְּלִי טָהוֹר וְנָתַן לְתוֹכוֹ כֵּלִים טְמֵאִים וְהִטְבִּילָן לֹא עָלְתָה לָהֶן טְבִילָה עַד שֶׁיִּהְיֶה פִּיו רָחָב כִּשְׁפוֹפֶרֶת הַנּוֹד. בַּמֶּה דְּבָרִים אֲמוּרִים לִתְרוּמָה. אֲבָל לְקֹדֶשׁ אֵין מַטְבִּילִין כֵּלִים לְתוֹךְ כֵּלִים טְהוֹרִין כְּלָל וַאֲפִלּוּ הָיוּ בְּסַל אוֹ בְּקֻפָּה כְּמוֹ שֶׁבֵּאַרְנוּ לְמַעְלָה בִּמְקוֹמוֹ:"],"Mishneh Torah, Inheritances 4":["הָאוֹמֵר זֶה בְּנִי אוֹ זֶה אָחִי אוֹ זֶה אֲחִי אָבִי אוֹ שְׁאָר הַיּוֹרְשִׁין אוֹתוֹ. אַף עַל פִּי שֶׁהוֹדָה בַּאֲנָשִׁים שֶׁאֵינָן מֻחְזָקִין שֶׁהֵן קְרוֹבָיו הֲרֵי זֶה נֶאֱמָן וְיִירָשֶׁנּוּ בֵּין שֶׁאָמַר כְּשֶׁהוּא בָּרִיא בֵּין שֶׁאָמַר כְּשֶׁהוּא שְׁכִיב מֵרַע. אֲפִלּוּ נִשְׁתַּתֵּק וְכָתַב בִּכְתַב יָדוֹ שֶׁזֶּה יוֹרְשׁוֹ בּוֹדְקִין אוֹתוֹ כְּדֶרֶךְ שֶׁבּוֹדְקִין לְגִטִּין:","הָיִינוּ מֻחְזָקִין בָּזֶה שֶׁהוּא אָחִיו אוֹ בֶּן דּוֹדוֹ וְאָמַר אֵינוֹ אָחִי וְאֵינוֹ בֶּן דּוֹדִי אֵינוֹ נֶאֱמָן. אֲבָל נֶאֱמָן הוּא עַל מִי שֶׁהֻחְזַק שֶׁהוּא בְּנוֹ לוֹמַר אֵינוֹ בְּנִי וְלֹא יִירָשֶׁנּוּ. וְיֵרָאֶה לִי שֶׁאֲפִלּוּ הָיוּ לַבֵּן בָּנִים אַף עַל פִּי שֶׁאֵינוֹ נֶאֱמָן עָלָיו לוֹמַר אֵינוֹ בְּנִי לְעִנְיַן יִחוּס וְאֵין מַחֲזִיקִין אוֹתוֹ מַמְזֵר עַל פִּיו. נֶאֱמָן הוּא לְעִנְיַן יְרֻשָּׁה וְלֹא יִירָשֶׁנּוּ:","הָאוֹמֵר זֶה בְּנִי וְחָזַר וְאָמַר עַבְדִּי הוּא אֵינוֹ נֶאֱמָן. אָמַר עַבְדִּי וְחָזַר וְאָמַר בְּנִי אַף עַל פִּי שֶׁהוּא מְשַׁמְּשׁוֹ כְּעֶבֶד נֶאֱמָן שֶׁזֶּה שֶׁאָמַר עַבְדִּי כְּלוֹמַר שֶׁהוּא לִי כְּעֶבֶד. וְאִם הָיוּ קוֹרִין לוֹ עֶבֶד בֶּן מֵאָה זוּז וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁאֵין אוֹמְרִין אוֹתָן בְּיִחוּד אֶלָּא לַעֲבָדִים הֲרֵי זֶה אֵינוֹ נֶאֱמָן:","הָיָה עוֹבֵר עַל בֵּית הַמֶּכֶס וְאָמַר בְּנִי הוּא זֶה וְחָזַר אַחַר כָּךְ וְאָמַר עַבְדִּי נֶאֱמָן. שֶׁלֹּא אָמַר בְּנִי אֶלָּא לְהַבְרִיחַ מִן הַמֶּכֶס. אָמַר בְּבֵית הַמּוֹכֵס עַבְדִּי הוּא וְחָזַר וְאָמַר בְּנִי הוּא אֵינוֹ נֶאֱמָן:","הָעֲבָדִים וְהַשְּׁפָחוֹת אֵין קוֹרִין לָהֶן אַבָּא פְּלוֹנִי וְאִמָּא פְּלוֹנִית שֶׁלֹּא יָבוֹא מִן הַדָּבָר תַּקָּלָה וְנִמְצָא זֶה הַבֵּן נִפְגָּם. לְפִיכָךְ אִם הָיוּ הָעֲבָדִים וְהַשְּׁפָחוֹת חֲשׁוּבִין בְּיוֹתֵר וְיֵשׁ לָהֶן קוֹל וְכָל הַקָּהָל מַכִּירִין אוֹתָן וְאֶת בְּנֵי וְעַבְדֵי אֲדוֹנֵיהֶם כְּגוֹן עַבְדֵי הַנָּשִׂיא הֲרֵי אֵלּוּ מֻתָּר לִקְרוֹת לָהֶן אַבָּא וְאִמָּא:","מִי שֶׁהָיְתָה לוֹ שִׁפְחָה וְהוֹלִיד מִמֶּנָּה בֵּן וְהָיָה נוֹהֵג בּוֹ מִנְהַג בָּנִים. אוֹ שֶׁאָמַר בְּנִי הוּא וּמְשֻׁחְרֶרֶת הִיא אִמּוֹ. אִם תַּלְמִיד חָכָם הוּא אוֹ אָדָם כָּשֵׁר שֶׁהוּא בָּדוּק בְּדִקְדוּקֵי מִצְוֹת הֲרֵי זֶה יִירָשֶׁנּוּ. וְאַף עַל פִּי כֵן אֵינוֹ נוֹשֵׂא בַּת יִשְׂרָאֵל עַד שֶׁיָּבִיא רְאָיָה שֶׁנִּשְׁתַּחְרְרָה אִמּוֹ וְאַחַר כָּךְ יָלְדָה שֶׁהֲרֵי הֻחְזְקָה שִׁפְחָה בְּפָנֵינוּ. וְאִם מִשְּׁאָר הֶדְיוֹטוֹת הוּא וְאֵין צָרִיךְ לוֹמַר אִם הָיָה מִן הַמַּפְקִירִין עַצְמָן לְכָךְ הֲרֵי זֶה בְּחֶזְקַת עֶבֶד לְכָל דָּבָר וְאֶחָיו מֵאָבִיו מוֹכְרִין אוֹתוֹ. וְאִם אֵין לְאָבִיו בֵּן חוּץ מִמֶּנּוּ אֵשֶׁת אָבִיו מִתְיַבֶּמֶת. וְזֶה הוּא הַדִּין שֶׁיֵּרָאֶה לִי שֶׁהוּא הוֹלֵךְ עַל עִקְּרֵי הַקַּבָּלָה. וְיֵשׁ מִי שֶׁלֹּא חִלֵּק בֵּין כְּשֵׁרִים לִשְׁאָר הָעָם אֶלָּא לְעִנְיָן שֶׁלֹּא יִמְכְּרוּהוּ אֶחָיו בִּלְבַד. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁאֲפִלּוּ לְיָרְשׁוֹ לֹא נַחְלֹק בְּיִשְׂרָאֵל וְאֵין רָאוּי לִסְמֹךְ עַל דָּבָר זֶה:","כָּל הַיּוֹרְשִׁין יוֹרְשִׁין בַּחֲזָקָה. כֵּיצַד. עֵדִים שֶׁהֵעִידוּ שֶׁזֶּה מֻחְזָק לָנוּ שֶׁהוּא בְּנוֹ שֶׁל פְּלוֹנִי אוֹ אָחִיו. אַף עַל פִּי שֶׁאֵינָן עֵדֵי יִחוּס וְלֹא יָדְעוּ אֲמִתַּת הַיּוּחֲסִין הֲרֵי אֵלּוּ יוֹרְשִׁין בְּעֵדוּת זוֹ:","יַעֲקֹב שֶׁמֵּת וְהִנִּיחַ רְאוּבֵן וְשִׁמְעוֹן וְלֹא הֻחְזַק לוֹ בֵּן אֶלָּא שְׁנֵיהֶם. תָּפַס רְאוּבֵן לֵוִי מִן הַשּׁוּק וְאָמַר גַּם זֶה אָחִינוּ הוּא וְשִׁמְעוֹן אוֹמֵר אֵינִי יוֹדֵעַ. הֲרֵי שִׁמְעוֹן נוֹטֵל חֲצִי הַמָּמוֹן וּרְאוּבֵן שְׁלִישׁ שֶׁהֲרֵי הוֹדָה שֶׁהֵם שְׁלֹשָׁה אַחִין וְלֵוִי נוֹטֵל שְׁתוּת. מֵת לֵוִי יַחְזֹר הַשְּׁתוּת לִרְאוּבֵן. נָפְלוּ לְלֵוִי נְכָסִים אֲחֵרִים יַחְלְקוּ אוֹתָן רְאוּבֵן וְשִׁמְעוֹן שֶׁהֲרֵי רְאוּבֵן מוֹדֶה לְשִׁמְעוֹן שֶׁלֵּוִי זֶה אֲחִיהֶן. הִשְׁבִּיחַ הַשְּׁתוּת מֵאֵלָיו וְאַחַר כָּךְ מֵת לֵוִי. אִם שֶׁבַח מַגִּיעַ לַכְּתֵפַיִם הוּא כְּגוֹן עֲנָבִים שֶׁהִגִּיעוּ לְהִבָּצֵר. הֲרֵי הַשֶּׁבַח הַזֶּה כִּנְכָסִים שֶׁנָּפְלוּ לוֹ מֵאֲחֵרִים וְיַחְלְקוּ בָּהֶן. וְאִם עֲדַיִן לֹא הִגִּיעוּ לְהִבָּצֵר הֲרֵי הֵן שֶׁל רְאוּבֵן לְבַדּוֹ. אָמַר שִׁמְעוֹן אֵין לֵוִי זֶה אָחִי וְנָטַל לֵוִי בְּחֵלֶק רְאוּבֵן כְּמוֹ שֶׁבֵּאַרְנוּ וְאַחַר כָּךְ מֵת לֵוִי לֹא יִירַשׁ שִׁמְעוֹן מִמֶּנּוּ כְּלוּם אֶלָּא רְאוּבֵן לְבַדּוֹ יִירַשׁ הַשְּׁתוּת עִם שְׁאָר נְכָסִים אֲחֵרִים שֶׁהִנִּיחַ לֵוִי. וְהוּא הַדִּין בְּכָל הַיּוֹרְשִׁין שֶׁיּוֹדוּ מִקְצָתָן בְּיוֹרְשִׁין אֲחֵרִים שֶׁלֹּא יוֹדוּ מִקְצָתָן:"],"Mishneh Torah, Kings and Wars 4":["רְשׁוּת יֵשׁ לַמֶּלֶךְ לִתֵּן מַס עַל הָעָם לִצְרָכָיו אוֹ לְצֹרֶךְ הַמִּלְחָמוֹת. וְקוֹצֵב לוֹ מֶכֶס וְאָסוּר לְהַבְרִיחַ מִן הַמֶּכֶס. שֶׁיֵּשׁ לוֹ לִגְזֹר שֶׁכָּל מִי שֶׁיִּגְנֹב הַמֶּכֶס יִלָּקַח מָמוֹנוֹ אוֹ יֵהָרֵג שֶׁנֶּאֱמַר (שמואל א ח יז) \"וְאַתֶּם תִּהְיוּ לוֹ לַעֲבָדִים\". וּלְהַלָּן הוּא אוֹמֵר (דברים כ יא) \"יִהְיוּ לְךָ לָמַס וַעֲבָדוּךָ\". מִכָּאן שֶׁנּוֹתֵן מַס וְקוֹצֵב מֶכֶס וְדִינָיו בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן דִּין. שֶׁכָּל הָאָמוּר בְּפָרָשַׁת מֶלֶךְ מֶלֶךְ זוֹכֶה בּוֹ:","וְשׁוֹלֵחַ בְּכָל גְּבוּל יִשְׂרָאֵל וְלוֹקֵחַ מִן הָעָם הַגִּבּוֹרִים וְאַנְשֵׁי חַיִל וְעוֹשֶׂה מֵהֶן חַיִל לְמֶרְכַּבְתּוֹ וּבְפָרָשָׁיו וּמַעֲמִיד מֵהֶן עוֹמְדִים לְפָנָיו. וּמַעֲמִיד מֵהֶן אֲנָשִׁים לָרוּץ לְפָנָיו. שֶׁנֶּאֱמַר (שמואל א ח יא) \"וְשָׂם לוֹ בְּמֶרְכַּבְתּוֹ וּפָרָשָׁיו וְרָצוּ לִפְנֵי מֶרְכַּבְתּו\"ֹ. וְלוֹקֵחַ מִן הַיָּפִים שֶׁבָּהֶם לִהְיוֹת שַׁמָּשִׁים וְעוֹמְדִים לְפָנָיו שֶׁנֶּאֱמַר (שמואל א ח טז) \"וְאֶת בַּחוּרֵיכֶם הַטּוֹבִים\" (שמואל א ח טז) \"יִקָּח וְעָשָׂה לִמְלַאכְתּוֹ\":","וְכֵן לוֹקֵחַ מִן בַּעֲלֵי הָאֻמָּנֻיּוֹת כָּל מַה שֶּׁהוּא צָרִיךְ וְעוֹשִׂין לוֹ מְלַאכְתּוֹ וְנוֹתֵן שְׂכָרָן. וְלוֹקֵחַ כָּל הַבְּהֵמוֹת וְהָעֲבָדִים וְהַשְּׁפָחוֹת לִמְלַאכְתּוֹ וְנוֹתֵן שְׂכָרָן אוֹ דְּמֵיהֶן. שֶׁנֶּאֱמַר (שמואל א ח יב) \"וְלַחֲרשׁ חֲרִישׁוֹ וְלִקְצֹר קְצִירוֹ וְלַעֲשׂוֹת כְּלֵי מִלְחַמְתּוֹ וּכְלֵי רִכְבּוֹ\". (שמואל א ח טז) \"וְאֶת עַבְדֵיכֶם וְאֶת שִׁפְחוֹתֵיכֶם וְאֶת בַּחוּרֵיכֶם הַטּוֹבִים וְאֶת חֲמוֹרֵיכֶם יִקָּח וְעָשָׂה לִמְלַאכְתּוֹ\":","וְכֵן לוֹקֵחַ מִכָּל גְּבוּל יִשְׂרָאֵל נָשִׁים וּפִילַגְשִׁים. נָשִׁים בִּכְתֻבָּה וְקִדּוּשִׁין. וּפִילַגְשִׁים בְּלֹא כְּתֻבָּה וּבְלֹא קִדּוּשִׁין. אֶלָּא בְּיִחוּד בִּלְבַד קוֹנֶה אוֹתָהּ וּמֻתֶּרֶת לוֹ. אֲבָל הַהֶדְיוֹט אָסוּר בְּפִילֶגֶשׁ אֶלָּא בְּאָמָה הָעִבְרִיָּה בִּלְבַד אַחַר יִעוּד. וְיֵשׁ לוֹ [רְשׁוּת] לַעֲשׂוֹת הַפִּילַגְשִׁים שֶׁלּוֹקֵחַ לְאַרְמוֹנוֹ טַבָּחוֹת וְאוֹפוֹת וְרַקָּחוֹת. שֶׁנֶּאֱמַר (שמואל א ח יג) \"וְאֶת בְּנוֹתֵיכֶם יִקָּח לְרַקָּחוֹת וּלְטַבָּחוֹת וּלְאֹפוֹת\":","וְכֵן כּוֹפֶה אֶת הָרְאוּיִין לִהְיוֹת שָׂרִים וּמְמַנֶּה אוֹתָם שָׂרֵי אֲלָפִים וְשָׂרֵי חֲמִשִּׁים. שֶׁנֶּאֱמַר (שמואל א ח יב) \"וְלָשׂוּם לוֹ שָׂרֵי אֲלָפִים וְשָׂרֵי חֲמִשִּׁים\":","וְלוֹקֵחַ הַשָּׂדוֹת וְהַזֵּיתִים וְהַכְּרָמִים לַעֲבָדָיו כְּשֶׁיֵּלְכוּ לַמִּלְחָמָה וְיִפְשְׁטוּ עַל מְקוֹמוֹת אֵלּוּ אִם אֵין לָהֶם מַה יֹּאכְלוּ אֶלָּא מִשָּׁם. וְנוֹתֵן דְּמֵיהֶן. שֶׁנֶּאֱמַר (שמואל א ח יד) \"וְאֶת שְׂדוֹתֵיכֶם וְאֶת כַּרְמֵיכֶם וְזֵיתֵיכֶם הַטּוֹבִים יִקָּח וְנָתַן לַעֲבָדָיו\":","וְיֵשׁ לוֹ מַעֲשֵׂר מִן הַזְּרָעִים וּמִן הָאִילָנוֹת וּמִן הַבְּהֵמָה. שֶׁנֶּאֱמַר (שמואל א ח טו) \"וְזַרְעֵיכֶם וְכַרְמֵיכֶם יַעְשֹׂר\" וְגוֹ'. (שמואל א ח יז) \"צֹאנְכֶם יַעְשֹׂר\":","הַמֶּלֶךְ הַמָּשִׁיחַ נוֹטֵל מִכָּל הָאֲרָצוֹת שֶׁכּוֹבְשִׁין יִשְׂרָאֵל חֵלֶק אֶחָד מִשְּׁלֹשָׁה עָשָׂר. וְדָבָר זֶה חֹק לוֹ וּלְבָנָיו עַד עוֹלָם:","כָּל הֲרוּגֵי הַמֶּלֶךְ מָמוֹנָן לַמֶּלֶךְ. וְכָל הַמַּמְלָכוֹת שֶׁכּוֹבֵשׁ הֲרֵי אוֹצְרוֹת הַמְּלָכִים לַמֶּלֶךְ. וּשְׁאָר הַבִּזָּה שֶׁבּוֹזְזִין בּוֹזְזִין וְנוֹתְנִין לְפָנָיו וְהוּא נוֹטֵל מֶחֱצָה בָּרֹאשׁ. וּמַחֲצִית הַבִּזָּה חוֹלְקִין אוֹתָהּ כָּל אַנְשֵׁי הַצָּבָא בְּיַחַד עִם הָעָם הַיּוֹשְׁבִין עַל הַכֵּלִים בַּמַּחֲנֶה לְשָׁמְרָם חוֹלְקִין בְּשָׁוֶה. שֶׁנֶּאֱמַר (שמואל א ל כד) \"כִּי כְּחֵלֶק הַיֹּרֵד בַּמִּלְחָמָה וּכְחֵלֶק הַיּשֵׁב עַל הַכֵּלִים יַחְדָּו יַחֲלֹקוּ\":","כָּל הָאָרֶץ שֶׁכּוֹבֵשׁ הֲרֵי הִיא שֶׁלּוֹ וְנוֹתֵן לַעֲבָדָיו וּלְאַנְשֵׁי הַמִּלְחָמָה כְּפִי מַה שֶּׁיִּרְצֶה. וּמַנִּיחַ לְעַצְמוֹ כְּפִי מַה שֶּׁיִּרְצֶה. וּבְכָל אֵלּוּ הַדְּבָרִים דִּינוֹ דִּין. וּבְכָל יִהְיוּ מַעֲשָׂיו לְשֵׁם שָׁמַיִם. וְתִהְיֶה מְגַמָּתוֹ וּמַחְשַׁבְתּוֹ לְהָרִים דַּת הָאֱמֶת. וּלְמַלְּאוֹת הָעוֹלָם צֶדֶק. וְלִשְׁבֹּר זְרוֹעַ הָרְשָׁעִים וּלְהִלָּחֵם מִלְחֲמוֹת ה'. שֶׁאֵין מַמְלִיכִין מֶלֶךְ תְּחִלָּה אֶלָּא לַעֲשׂוֹת מִשְׁפָּט וּמִלְחָמוֹת. שֶׁנֶּאֱמַר (שמואל א ח כ) \"וּשְׁפָטָנוּ מַלְכֵּנוּ וְיָצָא לְפָנֵינוּ וְנִלְחַם אֶת מִלְחֲמֹתֵנוּ\":"],"Mishneh Torah, Leavened and Unleavened Bread 7":["מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה לְסַפֵּר בְּנִסִּים וְנִפְלָאוֹת שֶׁנַּעֲשׂוּ לַאֲבוֹתֵינוּ בְּמִצְרַיִם בְּלֵיל חֲמִשָּׁה עָשָׂר בְּנִיסָן שֶׁנֶּאֱמַר (שמות יג ג) \"זָכוֹר אֶת הַיּוֹם הַזֶּה אֲשֶׁר יְצָאתֶם מִמִּצְרַיִם\" כְּמוֹ שֶׁנֶּאֱמַר (שמות כ ח) \"זָכוֹר אֶת יוֹם הַשַּׁבָּת\". וּמִנַּיִן שֶׁבְּלֵיל חֲמִשָּׁה עָשָׂר תַּלְמוּד לוֹמַר (שמות יג ח) \"וְהִגַּדְתָּ לְבִנְךָ בַּיּוֹם הַהוּא לֵאמֹר בַּעֲבוּר זֶה\" בְּשָׁעָה שֶׁיֵּשׁ מַצָּה וּמָרוֹר מֻנָּחִים לְפָנֶיךָ. וְאַף עַל פִּי שֶׁאֵין לוֹ בֵּן. אֲפִלּוּ חֲכָמִים גְּדוֹלִים חַיָּבִים לְסַפֵּר בִּיצִיאַת מִצְרִים וְכָל הַמַּאֲרִיךְ בִּדְבָרִים שֶׁאֵרְעוּ וְשֶׁהָיוּ הֲרֵי זֶה מְשֻׁבָּח:","מִצְוָה לְהוֹדִיעַ לַבָּנִים וַאֲפִלּוּ לֹא שָׁאֲלוּ שֶׁנֶּאֱמַר (שמות יג ח) \"וְהִגַּדְתָּ לְבִנְךָ\". לְפִי דַּעְתּוֹ שֶׁל בֵּן אָבִיו מְלַמְּדוֹ. כֵּיצַד. אִם הָיָה קָטָן אוֹ טִפֵּשׁ אוֹמֵר לוֹ בְּנִי כֻּלָּנוּ הָיִינוּ עֲבָדִים כְּמוֹ שִׁפְחָה זוֹ אוֹ כְּמוֹ עֶבֶד זֶה בְּמִצְרַיִם וּבַלַּיְלָה הַזֶּה פָּדָה אוֹתָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא וַיּוֹצִיאֵנוּ לְחֵרוּת. וְאִם הָיָה הַבֵּן גָּדוֹל וְחָכָם מוֹדִיעוֹ מַה שֶּׁאֵרַע לָנוּ בְּמִצְרַיִם וְנִסִּים שֶׁנַּעֲשׂוּ לָנוּ עַל יְדֵי משֶׁה רַבֵּנוּ הַכֹּל לְפִי דַּעְתּוֹ שֶׁל בֵּן:","וְצָרִיךְ לַעֲשׂוֹת שִׁנּוּי בַּלַּיְלָה הַזֶּה כְּדֵי שֶׁיִּרְאוּ הַבָּנִים וְיִשְׁאֲלוּ וְיֹאמְרוּ מַה נִּשְׁתַּנָּה הַלַּיְלָה הַזֶּה מִכָּל הַלֵּילוֹת עַד שֶׁיָּשִׁיב לָהֶם וְיֹאמַר לָהֶם כָּךְ וְכָךְ אֵרַע וְכָךְ וְכָךְ הָיָה. וְכֵיצַד מְשַׁנֶּה. מְחַלֵּק לָהֶם קְלָיוֹת וֶאֱגוֹזִים וְעוֹקְרִים הַשֻּׁלְחָן מִלִּפְנֵיהֶם קֹדֶם שֶׁיֹּאכְלוּ וְחוֹטְפִין מַצָּה זֶה מִיַּד זֶה וְכַיּוֹצֵא בִּדְבָרִים הָאֵלּוּ. אֵין לוֹ בֵּן אִשְׁתּוֹ שׁוֹאַלְתּוֹ. אֵין לוֹ אִשָּׁה שׁוֹאֲלִין זֶה אֶת זֶה מַה נִּשְׁתַּנָּה הַלַּיְלָה הַזֶּה. וַאֲפִלּוּ הָיוּ כֻּלָּן חֲכָמִים. הָיָה לְבַדּוֹ שׁוֹאֵל לְעַצְמוֹ מַה נִּשְׁתַּנָּה הַלַּיְלָה הַזֶּה:","וְצָרִיךְ לְהַתְחִיל בִּגְנוּת וּלְסַיֵּם בְּשֶׁבַח. כֵּיצַד. מַתְחִיל וּמְסַפֵּר שֶׁבַּתְּחִלָּה הָיוּ אֲבוֹתֵינוּ בִּימֵי תֶּרַח וּמִלְּפָנָיו כּוֹפְרִים וְטוֹעִין אַחַר הַהֶבֶל וְרוֹדְפִין אַחַר עֲבוֹדַת אֱלִילִים. וּמְסַיֵּם בְּדַת הָאֱמֶת שֶׁקֵּרְבָנוּ הַמָּקוֹם לוֹ וְהִבְדִּילָנוּ מֵהָאֻמּוֹת וְקֵרְבָנוּ לְיִחוּדוֹ. וְכֵן מַתְחִיל וּמוֹדִיעַ שֶׁעֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְרַיִם וְכָל הָרָעָה שֶׁגְּמָלָנוּ וּמְסַיֵּם בַּנִּסִּים וּבַנִּפְלָאוֹת שֶׁנַּעֲשׂוּ לָנוּ וּבְחֵרוּתֵנוּ. וְהוּא שֶׁיִּדְרשׁ מֵ\"אֲרַמִּי אֹבֵד אָבִי\" (דברים כו ה) עַד שֶׁיִּגְמֹר כָּל הַפָּרָשָׁה. וְכָל הַמּוֹסִיף וּמַאֲרִיךְ בִּדְרַשׁ פָּרָשָׁה זוֹ הֲרֵי זֶה מְשֻׁבָּח:","כָּל מִי שֶׁלֹּא אָמַר שְׁלֹשָׁה דְּבָרִים אֵלּוּ בְּלֵיל חֲמִשָּׁה עָשָׂר לֹא יָצָא יְדֵי חוֹבָתוֹ וְאֵלּוּ הֵן. פֶּסַח מַצָּה וּמָרוֹר. פֶּסַח עַל שׁוּם שֶׁפָּסַח הַמָּקוֹם עַל בָּתֵּי אֲבוֹתֵינוּ בְּמִצְרַיִם שֶׁנֶּאֱמַר (שמות יב כז) \"וַאֲמַרְתֶּם זֶבַח פֶּסַח הוּא לַה'\" וְגוֹ'. מָרוֹר עַל שׁוּם שֶׁמֵּרְרוּ הַמִּצְרִיִּים אֶת חַיֵּי אֲבוֹתֵינוּ בְּמִצְרַיִם. מַצָּה עַל שֵׁם שֶׁנִּגְאֲלוּ. וּדְבָרִים הָאֵלּוּ כֻּלָּן נִקְרָאִין הַגָּדָה:","בְּכָל דּוֹר וָדוֹר חַיָּב אָדָם לְהַרְאוֹת אֶת עַצְמוֹ כְּאִלּוּ הוּא בְּעַצְמוֹ יָצָא עַתָּה מִשִּׁעְבּוּד מִצְרַיִם שֶׁנֶּאֱמַר (דברים ו כג) \"וְאוֹתָנוּ הוֹצִיא מִשָּׁם\" וְגוֹ'. וְעַל דָּבָר זֶה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ כְּלוֹמַר כְּאִלּוּ אַתָּה בְּעַצְמְךָ הָיִיתָ עֶבֶד וְיָצָאתָ לְחֵרוּת וְנִפְדֵּיתָ:","לְפִיכָךְ כְּשֶׁסּוֹעֵד אָדָם בַּלַּיְלָה הַזֶּה צָרִיךְ לֶאֱכל וְלִשְׁתּוֹת וְהוּא מֵסֵב דֶּרֶךְ חֵרוּת. וְכָל אֶחָד וְאֶחָד בֵּין אֲנָשִׁים בֵּין נָשִׁים חַיָּב לִשְׁתּוֹת בַּלַּיְלָה הַזֶּה אַרְבָּעָה כּוֹסוֹת שֶׁל יַיִן. אֵין פּוֹחֲתִין לוֹ מֵהֶם. וַאֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה לֹא יִפְחֲתוּ לוֹ מֵאַרְבָּעָה כּוֹסוֹת. שִׁעוּר כָּל כּוֹס מֵהֶן רְבִיעִית:","אֲפִלּוּ עָנִי שֶׁבְּיִשְׂרָאֵל לֹא יֹאכַל עַד שֶׁיָּסֵב. אִשָּׁה אֵינָהּ צְרִיכָה הֲסִיבָה. וְאִם אִשָּׁה חֲשׁוּבָה הִיא צְרִיכָה הֲסִיבָה. וּבֵן אֵצֶל אָבִיו וְהַשַּׁמָּשׁ בִּפְנֵי רַבּוֹ צְרִיכִין הֲסִיבָה. אֲבָל תַּלְמִיד בִּפְנֵי רַבּוֹ אֵינוֹ מֵסֵב אֶלָּא אִם כֵּן נָתַן לוֹ רַבּוֹ רְשׁוּת. וַהֲסִיבַת יָמִין אֵינָהּ הֲסִיבָה. וְכֵן הַמֵּסֵב עַל עָרְפּוֹ אוֹ עַל פָּנָיו אֵין זוֹ הֲסִיבָה. וְאֵימָתַי צְרִיכִין הֲסִיבָה בִּשְׁעַת אֲכִילַת כְּזַיִת מַצָּה וּבִשְׁתִיַּת אַרְבָּעָה כּוֹסוֹת הָאֵלּוּ. וּשְׁאָר אֲכִילָתוֹ וּשְׁתִיָּתוֹ אִם הֵסֵב הֲרֵי זֶה מְשֻׁבָּח וְאִם לָאו אֵינוֹ צָרִיךְ:","אַרְבָּעָה כּוֹסוֹת הָאֵלּוּ צָרִיךְ לִמְזֹג אוֹתָן כְּדֵי שֶׁתִּהְיֶה שְׁתִיָּה עֲרֵבָה הַכֹּל לְפִי הַיַּיִן וּלְפִי דַּעַת הַשּׁוֹתֶה. וְלֹא יִפְחֹת בְּאַרְבַּעְתָּן מֵרְבִיעִית יַיִן חַי. שָׁתָה אַרְבָּעָה כּוֹסוֹת אֵלּוּ מִיַּיִן שֶׁאֵינוֹ מָזוּג יָצָא יְדֵי אַרְבָּעָה כּוֹסוֹת וְלֹא יָצָא יְדֵי חֵרוּת. שָׁתָה אַרְבָּעָה כּוֹסוֹת מְזוּגִין בְּבַת אַחַת יְדֵי חֵרוּת יָצָא יְדֵי אַרְבָּעָה כּוֹסוֹת לֹא יָצָא. וְאִם שָׁתָה מִכָּל כּוֹס מֵהֶן רֻבּוֹ יָצָא:","כָּל כּוֹס וְכוֹס מֵאַרְבָּעָה כּוֹסוֹת הַלָּלוּ מְבָרֵךְ עָלָיו בְּרָכָה בִּפְנֵי עַצְמָהּ. וְכוֹס רִאשׁוֹן אוֹמֵר עָלָיו קִדּוּשׁ הַיּוֹם. כּוֹס שֵׁנִי קוֹרֵא עָלָיו אֶת הַהַגָּדָה. כּוֹס שְׁלִישִׁי מְבָרֵךְ עָלָיו בִּרְכַּת הַמָּזוֹן. כּוֹס רְבִיעִי גּוֹמֵר עָלָיו אֶת הַהַלֵּל וּמְבָרֵךְ עָלָיו בִּרְכַּת הַשִּׁיר. וּבֵין הַכּוֹסוֹת הָאֵלּוּ אִם רָצָה לִשְׁתּוֹת שׁוֹתֶה. בֵּין שְׁלִישִׁי לִרְבִיעִי אֵינוֹ שׁוֹתֶה:","הַחֲרֹסֶת מִצְוָה מִדִּבְרֵי סוֹפְרִים זֵכֶר לַטִּיט שֶׁהָיוּ עוֹבְדִין בּוֹ בְּמִצְרַיִם. וְכֵיצַד עוֹשִׂין אוֹתָהּ. לוֹקְחִין תְּמָרִים אוֹ גְּרוֹגָרוֹת אוֹ צִמּוּקִין וְכַיּוֹצֵא בָּהֶן וְדוֹרְסִין אוֹתָן וְנוֹתְנִין לְתוֹכָן חֹמֶץ וּמְתַבְּלִין אוֹתָן בְּתַבְלִין כְּמוֹ טִיט בְּתֶבֶן וּמְבִיאִין אוֹתָהּ עַל הַשֻּׁלְחָן בְּלֵילֵי הַפֶּסַח:","אֲכִילַת מָרוֹר אֵינָהּ מִצְוָה מִן הַתּוֹרָה בִּפְנֵי עַצְמָהּ אֶלָּא תְּלוּיָה הִיא בַּאֲכִילַת הַפֶּסַח. שֶׁמִּצְוַת עֲשֵׂה אַחַת לֶאֱכל בְּשַׂר הַפֶּסַח עַל מַצָּה וּמְרוֹרִים. וּמִדִּבְרֵי סוֹפְרִים לֶאֱכל הַמָּרוֹר לְבַדּוֹ בְּלַיִל זֶה אֲפִלּוּ אֵין שָׁם קָרְבַּן פֶּסַח:","מְרוֹרִים הָאֲמוּרִים בַּתּוֹרָה הֵן הַחֲזֶרֶת וְהָעֳלָשִׁין וְהַתַּמְכָא וְהָחַרְחְבִינָא וְהַמָּרוֹר. כָּל אֶחָד מֵחֲמֵשֶׁת מִינֵי יָרָק אֵלּוּ נִקְרָא מָרוֹר. וְאִם אָכַל מֵאֶחָד מֵהֶן אוֹ מֵחֲמִשְּׁתָּן כְּזַיִת יָצָא וְהוּא שֶׁיְּהוּ לַחִין. וְיוֹצְאִין בְּקֶלַח שֶׁלָּהֶן אֲפִלּוּ יָבֵשׁ. וְאִם שְׁלָקָן אוֹ כְּבָשָׁן אוֹ בִּשְּׁלָן אֵין יוֹצְאִין בָּהֶן:"],"Mishneh Torah, Marriage 10":["הָאֲרוּסָה אֲסוּרָה לְבַעְלָהּ מִדִּבְרֵי סוֹפְרִים כָּל זְמַן שֶׁהִיא בְּבֵית אָבִיהָ. וְהַבָּא עַל אֲרוּסָתוֹ בְּבֵית חָמִיו מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וַאֲפִלּוּ אִם קִדְּשָׁהּ בְּבִיאָה אָסוּר לוֹ לָבוֹא עָלֶיהָ בִּיאָה שְׁנִיָּה בְּבֵית אָבִיהָ עַד שֶׁיָּבִיא אוֹתָהּ לְתוֹךְ בֵּיתוֹ וְיִתְיַחֵד עִמָּהּ וְיַפְרִישֶׁנָּהּ לוֹ. וְיִחוּד זֶה הוּא הַנִּקְרָא כְּנִיסָה לַחֻפָּה וְהוּא הַנִּקְרָא נִשּׂוּאִין בְּכָל מָקוֹם. וְהַבָּא עַל אֲרוּסָתוֹ לְשֵׁם נִשּׂוּאִין אַחַר שֶׁקִּדְּשָׁהּ מִשֶּׁיְּעָרֶה בָּהּ קְנָאָהּ וְנַעֲשֵׂית נְשׂוּאָה וַהֲרֵי הִיא אִשְׁתּוֹ לְכָל דָּבָר:","כֵּיוָן שֶׁנִּכְנְסָה הָאֲרוּסָה לַחֻפָּה הֲרֵי זוֹ מֻתֶּרֶת לָבֹא עָלֶיהָ בְּכָל עֵת שֶׁיִּרְצֶה וַהֲרֵי הִיא אִשְׁתּוֹ גְּמוּרָה לְכָל דָּבָר. וּמִשֶּׁתִּכָּנֵס לַחֻפָּה נִקְרֵאת נְשׂוּאָה אַף עַל פִּי שֶׁלֹּא נִבְעֲלָה וְהוּא שֶׁתִּהְיֶה רְאוּיָה לִבְעִילָה. אֲבָל אִם הָיְתָה נִדָּה אַף עַל פִּי שֶׁנִּכְנְסָה לַחֻפָּה וְנִתְיַחֵד עִמָּהּ לֹא גָּמְרוּ הַנִּשּׂוּאִין וַהֲרֵי הִיא כַּאֲרוּסָה עֲדַיִן:","וְצָרִיךְ לְבָרֵךְ בִּרְכַּת חֲתָנִים בְּבֵית הֶחָתָן קֹדֶם הַנִּשּׂוּאִין וְהֵן שֵׁשׁ בְּרָכוֹת וְאֵלּוּ הֵן. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכּל בָּרָא לִכְבוֹדוֹ. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם יוֹצֵר הָאָדָם. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם דְּמוּת תַּבְנִיתוֹ וְהִתְקִין לוֹ מִמֶּנּוּ בִּנְיַן עֲדֵי עַד בָּרוּךְ אַתָּה ה' יוֹצֵר הָאָדָם. שׂוֹשׂ תָּשִׂישׂ וְתָגֵל עֲקָרָה בְּקִבּוּץ בָּנֶיהָ לְתוֹכָהּ בְּשִׂמְחָה בָּרוּךְ אַתָּה ה' מְשַׂמֵּחַ צִיּוֹן בְּבָנֶיהָ. שַׂמֵּחַ תְּשַׂמַּח רֵעִים הָאֲהוּבִים כְּשַׂמֵּחֲךָ יְצִירְךָ בְּגַן עֵדֶן מִקֶּדֶם בָּרוּךְ אַתָּה ה' מְשַׂמֵּחַ חָתָן וְכַלָּה. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּרָא שָׂשׂוֹן וְשִׂמְחָה חָתָן וְכַלָּה גִּילָה רִנָּה דִּיצָה וְחֶדְוָה אַהֲבָה אַחֲוָה שָׁלוֹם וְרֵעוּת מְהֵרָה ה' אֱלֹהֵינוּ יִשָּׁמַע בְּעָרֵי יְהוּדָה וּבְחוּצוֹת יְרוּשָׁלַיִם קוֹל שָׂשׂוֹן קוֹל שִׂמְחָה קוֹל חָתָן קוֹל כַּלָּה קוֹל מִצְהֲלוֹת חֲתָנִים מֵחֻפָּתָם וּנְעָרִים מִמִּשְׁתֵּה מַנְגִּינָתָם בָּרוּךְ אַתָּה ה' מְשַׂמֵּחַ הֶחָתָן עִם הַכַּלָּה:","וְאִם הָיָה שָׁם יַיִן מֵבִיא כּוֹס שֶׁל יַיִן וּמְבָרֵךְ עַל הַיַּיִן תְּחִלָּה וּמְסַדֵּר אֶת כֻּלָּן עַל הַכּוֹס וְנִמְצָא מְבָרֵךְ שֶׁבַע בְּרָכוֹת. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהָבִיא הֲדַס עִם הַיַּיִן וּמְבָרֵךְ עַל הַהֲדַס אַחַר הַיַּיִן וְאַחַר כָּךְ מְבָרֵךְ הַשֵּׁשׁ:","וְאֵין מְבָרְכִין בִּרְכַּת חֲתָנִים אֶלָּא בַּעֲשָׂרָה גְּדוֹלִים וּבְנֵי חוֹרִין וְחָתָן מִן הַמִּנְיָן:","הַמְאָרֵס אֶת הָאִשָּׁה וּבֵרֵךְ בִּרְכַּת חֲתָנִים וְלֹא נִתְיַחֵד עִמָּהּ בְּבֵיתוֹ עֲדַיִן אֲרוּסָה הִיא שֶׁאֵין בִּרְכַּת חֲתָנִים עוֹשָׂה הַנִּשּׂוּאִין אֶלָּא כְּנִיסָה לַחֻפָּה. אֵרֵס וְכָנַס לַחֻפָּה וְלֹא בֵּרֵךְ בִּרְכַּת חֲתָנִים הֲרֵי זוֹ נְשׂוּאָה גְּמוּרָה וְחוֹזֵר וּמְבָרֵךְ אֲפִלּוּ אַחַר כַּמָּה יָמִים. וְלֹא תִּנָּשֵׂא נִדָּה עַד שֶׁתִּטְהַר. וְאֵין מְבָרְכִין לָהּ בִּרְכַּת חֲתָנִים עַד שֶׁתִּטְהַר. וְאִם עָבַר וְנָשָׂא וּבֵרֵךְ אֵינוֹ חוֹזֵר וּמְבָרֵךְ:","וְצָרִיךְ לִכְתֹּב כְּתֻבָּה קֹדֶם כְּנִיסָה לַחֻפָּה וְאַחַר כָּךְ יִהְיֶה מֻתָּר בְּאִשְׁתּוֹ וְהֶחָתָן נוֹתֵן שְׂכַר הַסּוֹפֵר. וְכַמָּה הוּא כּוֹתֵב לָהּ. אִם הָיְתָה בְּתוּלָה אֵין כּוֹתְבִין לָהּ פָּחוֹת מִמָּאתַיִם דִּינָרִים וְאִם בְּעוּלָה אֵין כּוֹתְבִין לָהּ פָּחוֹת מִמֵּאָה דִּינָרִים [ד.] וְזֶה הוּא הַנִּקְרָא עִקַּר כְּתֻבָּה. וְאִם רָצָה לְהוֹסִיף לָהּ אֲפִלּוּ כִּכַּר זָהָב מוֹסִיף. וְדִין הַתּוֹסֶפֶת וְדִין הָעִקָּר אֶחָד הוּא לְרֹב הַדְּבָרִים. לְפִיכָךְ כָּל מָקוֹם שֶׁנֶּאֱמַר בּוֹ כְּתֻבָּה סְתָם הוּא הָעִקָּר וְהַתּוֹסֶפֶת כְּאֶחָד. וַחֲכָמִים הֵם שֶׁתִּקְּנוּ כְּתֻבָּה לָאִשָּׁה כְּדֵי שֶׁלֹּא תִּהְיֶה קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ:","דִּינָרִים אֵלּוּ לֹא תִּקְּנוּ אוֹתָם מִן הַכֶּסֶף הַטָּהוֹר אֶלָּא מִמַּטְבֵּעַ שֶׁהָיָה בְּאוֹתָן הַיָּמִים שֶׁהָיָה שִׁבְעָה חֲלָקִים נְחשֶׁת וְאֶחָד כֶּסֶף עַד שֶׁיִּהְיֶה בַּסֶּלַע חֲצִי זוּז כֶּסֶף. וְנִמְצָא מָאתַיִם דִּינָרִים שֶׁל בְּתוּלָה חֲמִשָּׁה וְעֶשְׂרִים זוּזִין שֶׁל כֶּסֶף טָהוֹר וּמֵאָה דִּינָרִים שֶׁל בְּעוּלָה שְׁנֵים עָשָׂר זוּזִים וּמֶחֱצָה. וּמִשְׁקַל כָּל זוּז שֵׁשׁ וְתִשְׁעִים שְׂעוֹרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת עֵרוּבִין. וְהַדִּינָר הוּא הַנִּקְרָא זוּז בְּכָל מָקוֹם בֵּין שֶׁיִּהְיֶה מִן הַכֶּסֶף הַטָּהוֹר בֵּין שֶׁיִּהְיֶה מִמַּטְבֵּעַ אוֹתָן הַיָּמִים:","אֵין פּוֹחֲתִין לִבְתוּלָה מִמָּאתַיִם וְלִבְעוּלָה מִמֵּאָה. וְכָל הַפּוֹחֵת בְּעִילָתוֹ בְּעִילַת זְנוּת. אֶחָד הַכּוֹתֵב אֶת הַכְּתֻבָּה בִּשְׁטָר וְאֶחָד שֶׁהֵעִידוּ עָלָיו עֵדִים וְקָנוּ מִיָּדוֹ שֶׁהוּא חַיָּב לָהּ מֵאָה אוֹ מָאתַיִם הֲרֵי זֶה מֻתָּר. וְכֵן אִם נָתַן לָהּ מִטַּלְטְלִין כְּנֶגֶד כְּתֻבָּתָהּ הֲרֵי זֶה מֻתָּר לִבְעל עַד שֶׁיִּהְיֶה לוֹ פְּנַאי לִכְתֹּב:","הַכּוֹנֵס אֶת הָאִשָּׁה וְלֹא כָּתַב לָהּ כְּתֻבָּה. אוֹ שֶׁכָּתַב וְאָבַד שְׁטַר הַכְּתֻבָּה. אוֹ שֶׁמָּחֲלָה כְּתֻבָּתָהּ לְבַעְלָהּ. אוֹ שֶׁמָּכְרָה לוֹ כְּתֻבָּתָהּ. חוֹזֵר וְכוֹתֵב לָהּ עִקַּר כְּתֻבָּה אִם רָצָה לְקַיְּמָהּ. לְפִי שֶׁאָסוּר לוֹ לְאָדָם לִשְׁהוֹת עִם אִשְׁתּוֹ אֲפִלּוּ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה. אֲבָל הַמּוֹכֶרֶת כְּתֻבָּתָהּ לַאֲחֵרִים בְּטוֹבַת הֲנָאָה אֵינוֹ צָרִיךְ לִכְתֹּב לָהּ כְּתֻבָּה אַחֶרֶת. שֶׁלֹּא תִּקְּנוּ כְּתֻבָּה אֶלָּא כְּדֵי שֶׁלֹּא תְּהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ. וְאִם הוֹצִיא זֶה מְשַׁלֵּם כְּתֻבָּתָהּ לַלּוֹקֵחַ כְּדֶרֶךְ שֶׁהָיָה מְשַׁלֵּם לָהּ אִם לֹא מָכְרָה:","הַמְאָרֵס אֶת הָאִשָּׁה וְכָתַב לָהּ כְּתֻבָּה וְלֹא נִכְנְסָה לַחֻפָּה עֲדַיִן אֲרוּסָה הִיא וְאֵינָהּ נְשׂוּאָה שֶׁאֵין הַכְּתֻבָּה עוֹשָׂה נִשּׂוּאִין. וְאִם מֵת אוֹ גֵּרְשָׁהּ גּוֹבָה עִקַּר כְּתֻבָּתָהּ מִבְּנֵי חוֹרִין וְאֵינָהּ גּוֹבָה תּוֹסֶפֶת כְּלָל הוֹאִיל וְלֹא כְּנָסָהּ. אֲבָל אִם אֵרֵס אִשָּׁה וְלֹא כָּתַב לָהּ כְּתֻבָּה וָמֵת אוֹ גֵּרְשָׁהּ וְהִיא אֲרוּסָה אֵין לָהּ כְּלוּם וַאֲפִלּוּ הָעִקָּר שֶׁלֹּא תִּקְּנוּ לָהּ עִקַּר כְּתֻבָּה עַד שֶׁתִּנָּשֵׂא אוֹ עַד שֶׁיִּכְתֹּב. וְהַמְאָרֵס אֶת בִּתּוֹ וְכָתַב לָהּ כְּתֻבָּה וָמֵת אוֹ גֵּרְשָׁהּ כְּשֶׁהָיְתָה נַעֲרָה כְּתֻבָּתָהּ לְאָבִיהָ כְּמוֹ שֶׁבֵּאַרְנוּ [לְמַעְלָה בְּפֶרֶק שְׁלִישִׁי]:","וְכֵן תִּקְּנוּ חֲכָמִים שֶׁכָּל הַנּוֹשֵׂא בְּתוּלָה יִהְיֶה שָׂמֵחַ עִמָּהּ שִׁבְעַת יָמִים. אֵינוֹ עוֹסֵק בִּמְלַאכְתּוֹ וְלֹא נוֹשֵׂא וְנוֹתֵן בַּשּׁוּק אֶלָּא אוֹכֵל וְשׁוֹתֶה וְשָׂמֵחַ. בֵּין שֶׁהָיָה בָּחוּר בֵּין שֶׁהָיָה אַלְמוֹן. וְאִם הָיְתָה בְּעוּלָה אֵין פָּחוֹת מִשְּׁלֹשָׁה יָמִים. שֶׁתַּקָּנַת חֲכָמִים הִיא לִבְנוֹת יִשְׂרָאֵל שֶׁיִּהְיֶה שָׂמֵחַ עִם הַבְּעוּלָה שְׁלֹשָׁה יָמִים בֵּין בָּחוּר בֵּין אַלְמוֹן:","יֵשׁ לוֹ לְאָדָם לִשָּׂא נָשִׁים רַבּוֹת כְּאַחַת בְּיוֹם אֶחָד וּמְבָרֵךְ בִּרְכַּת חֲתָנִים לְכֻלָּן כְּאַחַת. אֲבָל לְשִׂמְחָה צָרִיךְ לִשְׂמֹחַ עִם כָּל אַחַת שִׂמְחָה הָרְאוּיָה לָהּ. עִם בְּתוּלָה שִׁבְעָה. עִם בְּעוּלָה שְׁלֹשָׁה. וְאֵין מְעָרְבִין שִׂמְחָה בְּשִׂמְחָה:","מֻתָּר לְאָרֵס בְּכָל יוֹם חֹל אֲפִלּוּ בְּתִשְׁעָה בְּאָב בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. אֲבָל אֵין נוֹשְׂאִין נָשִׁים לֹא בְּעֶרֶב שַׁבָּת וְלֹא בְּאֶחָד בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יָבוֹא לִידֵי חִלּוּל שַׁבָּת בְּתִקּוּן הַסְּעֵדָּה שֶׁהֶחָתָן טָרוּד בַּסְּעֻדָּה. וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לִשָּׂא אִשָּׁה בְּשַׁבָּת. וַאֲפִלּוּ בְּחֻלּוֹ שֶׁל מוֹעֵד אֵין נוֹשְׂאִין נָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ לְפִי שֶׁאֵין מְעָרְבִין שִׂמְחָה בְּשִׂמְחָה שֶׁנֶּאֱמַר (בראשית כט כז) \"מַלֵּא שְׁבֻעַ זֹאת וְנִתְּנָה לְךָ גַּם אֶת זֹאת\". וּשְׁאָר הַיָּמִים מֻתָּר לִשָּׂא אִשָּׁה בְּכָל יוֹם שֶׁיִּרְצֶה וְהוּא שֶׁיִּטְרַח בִּסְעֻדַּת נִשּׂוּאִין שְׁלֹשָׁה יָמִים קֹדֶם הַנִּשּׂוּאִין:","מָקוֹם שֶׁאֵין בֵּית דִּין יוֹשְׁבִין בּוֹ אֶלָּא בְּשֵׁנִי וּבַחֲמִישִׁי בִּלְבַד בְּתוּלָה נִשֵּׂאת בְּיוֹם רְבִיעִי שֶׁאִם הָיְתָה לוֹ טַעֲנַת בְּתוּלִים יַשְׁכִּים לְבֵית דִּין. וּמִנְהַג חֲכָמִים שֶׁהַנּוֹשֵׂא אֶת הַבְּעוּלָה יִשָּׂאֶנָּה בַּחֲמִישִׁי כְּדֵי שֶׁיִּהְיֶה שָׂמֵחַ עִמָּהּ חֲמִישִׁי וְעֶרֶב שַׁבָּת וְשַׁבָּת וְיוֹצֵא לִמְלַאכְתּוֹ יוֹם רִאשׁוֹן:","הַמְאָרֵס אֶת בִּתּוֹ קְטַנָּה וּתְבָעָהּ הַבַּעַל לְנִשּׂוּאִין. בֵּין הִיא בֵּין אָבִיהָ יְכוֹלִין לְעַכֵּב שֶׁלֹּא תִּנָּשֵׂא עַד שֶׁתַּגְדִּיל וְתֵעָשֶׂה נַעֲרָה וְאִם רָצָה לְכָנְסָהּ כּוֹנֵס. וְאֵין רָאוּי לַעֲשׂוֹת כֵּן:","אֵרְסָהּ וְשָׁהָה כַּמָּה שָׁנִים וּתְבָעָהּ לְנִשּׂוּאִין וַהֲרֵי הִיא נַעֲרָה נוֹתְנִין לָהּ י\"ב חֹדֶשׁ מִיּוֹם הַתְּבִיעָה לְפַרְנֵס אֶת עַצְמָהּ וּלְתַקֵּן מַה שֶּׁהִיא צְרִיכָה לָהּ וְאַחַר כָּךְ תִּנָּשֵׂא. תְּבָעָהּ אַחַר שֶׁבָּגְרָה נוֹתְנִין לָהּ י\"ב חֹדֶשׁ מִיּוֹם הַבֶּגֶר. וְכֵן אִם קִדְּשָׁהּ בְּיוֹם הַבֶּגֶר נוֹתְנִין לָהּ י\"ב חֹדֶשׁ מִיּוֹם הַקִּדּוּשִׁין שֶׁהוּא יוֹם הַבֶּגֶר. קִדְּשָׁהּ אַחַר שֶׁבָּגְרָה אִם עָבְרוּ עָלֶיהָ י\"ב חֹדֶשׁ בְּבַגְרוּתָהּ וּלְאַחַר כָּךְ נִתְקַדְּשָׁה אֵין נוֹתְנִין לָהּ אֶלָּא שְׁלֹשִׁים יוֹם מִיּוֹם הַתְּבִיעָה. וְכֵן הַמְאָרֵס אֶת הַבְּעוּלָה נוֹתְנִין לָהּ שְׁלֹשִׁים יוֹם מִיּוֹם הַתְּבִיעָה:","כְּשֵׁם שֶׁנּוֹתְנִין זְמַן לָאִשָּׁה מִשֶּׁתְּבָעָהּ הַבַּעַל לְפַרְנֵס אֶת עַצְמָהּ וְאַחַר כָּךְ תִּנָּשֵׂא כָּךְ נוֹתְנִין זְמַן לָאִישׁ לְפַרְנֵס אֵת עַצְמוֹ מִשֶּׁתָּבְעָה הָאִשָּׁה אוֹתוֹ. וְכַמָּה נוֹתְנִין לוֹ כְּמוֹ שֶׁנּוֹתְנִין לָהּ אִם י\"ב חֹדֶשׁ י\"ב חֹדֶשׁ וְאִם שְׁלֹשִׁים יוֹם שְׁלֹשִׁים יוֹם:","הִגִּיעַ זְמַן שֶׁנָּתְנוּ לָאִישׁ וְלֹא נְשָׂאָהּ נִתְחַיֵּב בִּמְזוֹנוֹתֶיהָ אַף עַל פִּי שֶׁלֹּא כָּנַס. וְאִם הִגִּיעַ הַזְּמַן בְּאֶחָד בְּשַׁבָּת אוֹ בְּעֶרֶב שַׁבָּת אֵינוֹ מַעֲלֶה לָהּ מְזוֹנוֹת בְּאוֹתוֹ הַיּוֹם מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לִכְנֹס. וְכֵן אִם חָלָה הוּא אוֹ הִיא אוֹ שֶׁפֵּרְסָה נִדָּה כְּשֶׁהִגִּיעַ הַזְּמַן אֵינוֹ מַעֲלֶה לָהּ מְזוֹנוֹת שֶׁהֲרֵי אֵינָהּ רְאוּיָה לְהִנָּשֵׂא עַד שֶׁתִּטְהַר אוֹ עַד שֶׁתַּבְרִיא. וְכֵן הוּא אֵינוֹ יָכוֹל לִשָּׂא אִשָּׁה עַד שֶׁיַּבְרִיא:"],"Mishneh Torah, Marriage 21":["מְצִיאַת הָאִשָּׁה וּמַעֲשֵׂה יָדֶיהָ לְבַעְלָהּ. וּמַה הִיא עוֹשָׂה לוֹ. הַכּל כְּמִנְהַג הַמְּדִינָה. מָקוֹם שֶׁדַּרְכָּן לֶאֱרֹג אוֹרֶגֶת. לִרְקֹם רוֹקֶמֶת. לִטְווֹת צֶמֶר אוֹ פִּשְׁתִּים טוֹוָה. וְאִם לֹא הָיָה דֶּרֶךְ נְשֵׁי הָעִיר לַעֲשׂוֹת כָּל הַמְּלָאכוֹת הָאֵלּוּ אֵינוֹ כּוֹפָהּ אֶלָּא לִטְווֹת הַצֶּמֶר בִּלְבַד. שֶׁהַפִּשְׁתָּן מַזִּיק אֶת הַפֶּה וְאֶת הַשְּׂפָתַיִם וְהַטְּוִיָּה הִיא הַמְּלָאכָה הַמְיֻחֶדֶת לְנָשִׁים שֶׁנֶּאֱמַר (שמות לה כה) \"וְכָל אִשָּׁה חַכְמַת לֵב בְּיָדֶיהָ טָווּ\":","דָּחֲקָה עַצְמָהּ וְעָשְׂתָה יוֹתֵר מִן הָרָאוּי לָהּ הַמּוֹתָר לַבַּעַל. הָיָה לוֹ מָמוֹן הַרְבֵּה אֲפִלּוּ הָיָה לָהּ כַּמָּה שְׁפָחוֹת אֵינָהּ יוֹשֶׁבֶת לְבַטָּלָה בְּלֹא מְלָאכָה שֶׁהַבַּטָּלָה מְבִיאָה לִידֵי זִמָּה. אֲבָל אֵין כּוֹפִין אוֹתָהּ לַעֲשׂוֹת מְלָאכָה כָּל הַיּוֹם כֻּלּוֹ אֶלָּא לְפִי רֹב הַמָּמוֹן מְמַעֶטֶת בִּמְלָאכָה:","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁלֹּא תַּעֲשֶׂה מְלָאכָה כְּלָל יוֹצִיא וְיִתֵּן כְּתֻבָּה שֶׁהַבַּטָּלָה מְבִיאָה לִידֵי זִמָּה. וְכֵן כָּל אִשָּׁה רוֹחֶצֶת לְבַעְלָהּ פָּנָיו יָדָיו וְרַגְלָיו וּמוֹזֶגֶת לוֹ אֶת הַכּוֹס וּמַצַּעַת לוֹ אֶת הַמִּטָּה וְעוֹמֶדֶת וּמְשַׁמֶּשֶׁת בִּפְנֵי בַּעְלָהּ כְּגוֹן שֶׁתִּתֵּן לוֹ מַיִם אוֹ כְּלִי אוֹ תִּטּל מִלְּפָנָיו וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲבָל אֵינָהּ עוֹמֶדֶת וּמְשַׁמֶּשֶׁת בִּפְנֵי אָבִיו אוֹ בִּפְנֵי בְּנוֹ:","וּמְלָאכוֹת אֵלּוּ עוֹשָׂה אוֹתָן הִיא בְּעַצְמָהּ וַאֲפִלּוּ הָיוּ לָהּ כַּמָּה שְׁפָחוֹת אֵין עוֹשִׂין מְלָאכוֹת אֵלּוּ לַבַּעַל אֶלָּא אִשְׁתּוֹ:","יֵשׁ מְלָאכוֹת אֲחֵרוֹת שֶׁהָאִשָּׁה עוֹשָׂה לְבַעְלָהּ בִּזְמַן שֶׁהֵן עֲנִיִּים וְאֵלּוּ הֵן. אוֹפָה הַפַּת בַּתַּנּוּר, וְעֶזְרָא תִּקֵּן שֶׁתִּהְיֶה אִשָּׁה מַשְׁכֶּמֶת וְאוֹפָה כְּדֵי שֶׁתִּהְיֶה הַפַּת מְצוּיָה לָעֲנִיִּים. וּמְבַשֶּׁלֶת אֶת הַתַּבְשִׁילִין. וּמְכַבֶּסֶת אֶת הַבְּגָדִים. וּמֵינִיקָה אֶת בְּנָהּ. וְנוֹתֶנֶת תֶּבֶן לִפְנֵי בְּהֶמְתּוֹ אֲבָל לֹא לִפְנֵי בְּקָרוֹ. וּמְטַחֶנֶת. כֵּיצַד מְטַחֶנֶת. יוֹשֶׁבֶת בָּרֵחַיִם וּמְשַׁמֶּרֶת הַקֶּמַח וְאֵינָהּ טוֹחֶנֶת. אוֹ מְחַמֶּרֶת אַחַר הַבְּהֵמָה כְּדֵי שֶׁלֹּא יִבָּטְלוּ הָרֵחַיִם. וְאִם הָיָה דַּרְכָּן לִטְחֹן בְּרֵחַיִם שֶׁל יָד טוֹחֶנֶת:","בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲנִיִּים אֲבָל אִם הִכְנִיסָה לוֹ שִׁפְחָה אַחַת אוֹ נְכָסִים שֶׁרָאוּי לִקְנוֹת מֵהֶן שִׁפְחָה אַחַת אוֹ שֶׁהָיְתָה לוֹ שִׁפְחָה אַחַת אוֹ שֶׁהָיָה לוֹ מָמוֹן כְּדֵי לִקְנוֹת מִמֶּנּוּ שִׁפְחָה אַחַת אֵינָהּ מְטַחֶנֶת וְלֹא אוֹפָה וְלֹא מְכַבֶּסֶת וְלֹא נוֹתֶנֶת תֶּבֶן לִפְנֵי בְּהֶמְתּוֹ. הִכְנִיסָה לוֹ שְׁתֵּי שְׁפָחוֹת אוֹ נְכָסִים הָרְאוּיִין לִקְנוֹת מֵהֶן שְׁתֵּי שְׁפָחוֹת אוֹ שֶׁהָיוּ לוֹ שְׁתֵּי שְׁפָחוֹת אוֹ שֶׁהָיָה רָאוּי לִקְנוֹת שְׁתֵּי שְׁפָחוֹת אֵינָהּ מְבַשֶּׁלֶת וְאֵינָהּ מֵינִיקָה אֶת בְּנָהּ אֶלָּא נוֹתֶנֶת אוֹתוֹ לַשִּׁפְחָה לְהֵינִיק:","נִמְצְאוּ כָּל הַמְּלָאכוֹת שֶׁכָּל אִשָּׁה עוֹשָׂה אוֹתָן לְבַעְלָהּ חָמֵשׁ מְלָאכוֹת. טוֹוָה וְרוֹחֶצֶת פָּנָיו יָדָיו וְרַגְלָיו וּמוֹזֶגֶת אֶת הַכּוֹס וּמַצַּעַת אֶת הַמִּטָּה וְעוֹמֶדֶת וּמְשַׁמֶּשֶׁת בְּפָנָיו. וְהַמְּלָאכוֹת שֶׁמִּקְצָת הַנָּשִׁים עוֹשׂוֹת אוֹתָן וּמִקְצָתָן אֵינָן עוֹשׂוֹת שֵׁשׁ מְלָאכוֹת. מְטַחֶנֶת וּמְבַשֶּׁלֶת וְאוֹפָה וּמְכַבֶּסֶת וּמֵינִיקָה וְנוֹתֶנֶת תֶּבֶן לִפְנֵי בְּהֶמְתּוֹ:","כָּל מְלָאכוֹת שֶׁהָאִשָּׁה עוֹשָׂה לְבַעְלָהּ נִדָּה עוֹשֶׂה לְבַעְלָהּ חוּץ מִמְּזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו גְּזֵרָה מִשּׁוּם הִרְהוּר שֶׁמָּא יָבוֹא לִבְעל. לְפִיכָךְ מַצַּעַת מִטָּתוֹ כְּשֶׁהִיא נִדָּה שֶׁלֹּא בְּפָנָיו וּמוֹזֶגֶת אֶת הַכּוֹס וְאֵינָהּ נוֹתֶנֶת אוֹתוֹ בְּיָדוֹ כְּדַרְכָּהּ תָּמִיד אֶלָּא מַנַּחַת אוֹתוֹ עַל הָאָרֶץ אוֹ עַל הַכְּלִי אוֹ עַל הַשֻּׁלְחָן וְהוּא נוֹטְלוֹ:","הָאִשָּׁה שֶׁשָּׁבְרָה כֵּלִים בְּעֵת שֶׁעָשְׂתָה מְלָאֲכוֹתֶיהָ בְּתוֹךְ בֵּיתָהּ פְּטוּרָה וְאֵין זֶה מִן הַדִּין אֶלָּא תַּקָּנָה שֶׁאִם אֵין אַתָּה אוֹמֵר כֵּן אֵין שָׁלוֹם בְּתוֹךְ הַבַּיִת לְעוֹלָם אֶלָּא נִמְצֵאת נִזְהֶרֶת וְנִמְנַעַת מֵרֹב הַמְּלָאכוֹת וְנִמְצֵאת קְטָטָה בֵּינֵיהֶם:","כָּל אִשָּׁה שֶׁתִּמָּנַע מִלַּעֲשׂוֹת מְלָאכָה מִן הַמְּלָאכוֹת שֶׁהִיא חַיֶּבֶת לַעֲשׂוֹתָן כּוֹפִין אוֹתָהּ וְעוֹשָׂה אֲפִלּוּ בְּשׁוֹט. טָעַן הוּא שֶׁאֵינָהּ עוֹשָׂה וְהִיא אוֹמֶרֶת שֶׁאֵינָהּ נִמְנַעַת מִלַּעֲשׂוֹת מוֹשִׁיבִין אִשָּׁה בֵּינֵיהֶן אוֹ שְׁכֵנִים. וְדָבָר זֶה כְּפִי מַה שֶּׁיִּרְאֶה הַדַּיָּן שֶׁאֶפְשָׁר בַּדָּבָר:","הָאִשָּׁה כָּל זְמַן שֶׁהִיא מֵינִיקָה אֶת בְּנָהּ פּוֹחֲתִין לָהּ מִמַּעֲשֵׂה יָדֶיהָ וּמוֹסִיפִין לָהּ עַל מְזוֹנוֹתֶיהָ יַיִן וּדְבָרִים שֶׁיָּפִין לְחָלָב. פָּסְקוּ לָהּ מְזוֹנוֹת הָרְאוּיוֹת לָהּ וַהֲרֵי הִיא מִתְאַוָּה לֶאֱכל יוֹתֵר אוֹ לֶאֱכל מַאֲכָלוֹת אֲחֵרוֹת מִפְּנֵי חֳלִי הַתַּאֲוָה שֶׁיֵּשׁ לָהּ בְּבִטְנָהּ הֲרֵי זוֹ אוֹכֶלֶת מִשֶּׁלָּהּ כָּל מַה שֶּׁתִּרְצֶה וְאֵין הַבַּעַל יָכוֹל לְעַכֵּב וְלוֹמַר שֶׁאִם תֹּאכַל יוֹתֵר מִדַּאי אוֹ תֹּאכַל מַאֲכָלִים רָעִים יָמוּת הַוָּלָד מִפְּנֵי שֶׁצַּעַר גּוּפָהּ קוֹדֵם:","יָלְדָה תְּאוֹמִים אֵין כּוֹפִין אוֹתָהּ לְהֵינִיק שְׁנֵיהֶם אֶלָּא מֵינִיקָה אֶחָד וְשׂוֹכֵר הַבַּעַל מֵינִיקָה לַשֵּׁנִי. הֲרֵי שֶׁרָצְתָה הָאִשָּׁה לְהֵינִיק בֶּן חֲבֵרְתָהּ עִם בְּנָהּ הַבַּעַל מְעַכֵּב וְאֵינוֹ מַנִּיחָה אֶלָּא לְהֵינִיק בְּנוֹ בִּלְבַד:","נָדְרָה שֶׁלֹּא לְהֵינִיק אֶת בְּנָהּ כּוֹפֶה אוֹתָהּ וּמֵינִיקָתוֹ עַד שֶׁיִּהְיֶה בֶּן כ\"ד חֹדֶשׁ אֶחָד הַזָּכָר וְאֶחָד הַנְּקֵבָה. הִיא אוֹמֶרֶת אֲנִי אֵינִיק אֶת בְּנִי וְהוּא אֵינוֹ רוֹצֶה שֶׁתֵּינִיק אִשְׁתּוֹ כְּדֵי שֶׁלֹּא תִּתְנַוֵּל אַף עַל פִּי שֶׁיֵּשׁ לָהּ כַּמָּה שְׁפָחוֹת שׁוֹמְעִין לָהּ שֶׁצַּעַר הוּא לָהּ לִפְרשׁ מִבְּנָהּ:","הָיְתָה עֲנִיָּה שֶׁהִיא חַיֶּבֶת לְהֵינִיק אֶת בְּנָהּ וַהֲרֵי הוּא עָשִׁיר שֶׁרָאוּי לוֹ שֶׁלֹּא תֵּינִיק אִשְׁתּוֹ אַף עַל פִּי שֶׁאֵין לוֹ שְׁפָחוֹת אִם לֹא רָצְתָה לְהֵינִיק שׂוֹכֵר מֵינִיקָה אוֹ קוֹנֶה שִׁפְחָה מִפְּנֵי שֶׁהָאִשָּׁה עוֹלָה עִם בַּעְלָהּ וְאֵינָהּ יוֹרֶדֶת:","הִיא אוֹמֶרֶת רָאוּי הוּא לִשְׂכֹּר אוֹ לִקְנוֹת שִׁפְחָה וְהוּא אוֹמֵר אֵינוֹ רָאוּי. עָלֶיהָ לְהָבִיא רְאָיָה וְאֵין כָּאן מָקוֹם לִשְׁבוּעָה:","הָאִשָּׁה שֶׁנִּתְגָּרְשָׁה אֵין כּוֹפִין אוֹתָהּ לְהֵינִיק. אֶלָּא אִם רָצְתָה נוֹתֵן לָהּ שְׂכָרָהּ וּמֵינִיקָתוֹ. וְאִם לֹא רָצְתָה נוֹתֶנֶת לוֹ אֶת בְּנוֹ וְהוּא מְטַפֵּל בּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הֵינִיקָה אוֹתוֹ עַד שֶׁהִכִּירָהּ. אֲבָל אִם הִכִּירָהּ וַאֲפִלּוּ הוּא סוּמָא אֵין מַפְרִישִׁין אוֹתוֹ מֵאִמּוֹ מִפְּנֵי סַכָּנַת הַוָּלָד. אֶלָּא כּוֹפִין אוֹתָהּ וּמֵינִיקָה אוֹתוֹ בְּשָׂכָר עַד כ\"ד חֹדֶשׁ:","הַגְּרוּשָׁה אֵין לָהּ מְזוֹנוֹת אַף עַל פִּי שֶׁהִיא מֵינִיקָה אֶת בְּנָהּ אֲבָל נוֹתֵן לָהּ יוֹתֵר עַל שְׂכָרָהּ דְּבָרִים שֶׁהַקָּטָן צָרִיךְ לָהֶן מִכְּסוּת וּמַאֲכָל וּמַשְׁקֶה וְסִיכָה וְכַיּוֹצֵא בָּזֶה. אֲבָל הַמְעֵבֶּרֶת אֵין לָהּ כְּלוּם. שָׁלְמוּ חֳדָשָׁיו וּגְמָלַתּוּ אִם רָצְתָה הַמְגֹרֶשֶׁת שֶׁיִּהְיֶה בְּנָהּ אֶצְלָהּ אֵין מַפְרִישִׁין אוֹתוֹ מִמֶּנָּה עַד שֶׁיִּהְיֶה בֶּן שֵׁשׁ שָׁנִים גְּמוּרוֹת. אֶלָּא כּוֹפִין אֶת אָבִיו וְנוֹתֵן לוֹ מְזוֹנוֹת וְהוּא אֵצֶל אִמּוֹ. וְאַחַר שֵׁשׁ שָׁנִים יֵשׁ לָאָב לוֹמַר אִם הוּא אֶצְלִי אֶתֵּן לוֹ מְזוֹנוֹת וְאִם הוּא אֵצֶל אִמּוֹ לֹא אֶתֵּן לוֹ מְזוֹנוֹת. וְהַבַּת אֵצֶל אִמָּהּ לְעוֹלָם וַאֲפִלּוּ לְאַחַר שֵׁשׁ:","כֵּיצַד. הָיָה הָאָב רָאוּי לִצְדָקָה מוֹצִיאִין מִמֶּנּוּ הָרָאוּי לוֹ בְּעַל כָּרְחוֹ וְזָנִין אוֹתָהּ וְהִיא אֵצֶל אִמָּהּ וַאֲפִלּוּ נִשֵּׂאת הָאֵם לְאַחֵר בִּתָּהּ אֶצְלָהּ וְאָבִיהָ זָן אוֹתָהּ מִשּׁוּם צְדָקָה עַד שֶׁיָּמוּת הָאָב וְתִזּוֹן מִנְּכָסָיו אַחַר מוֹתוֹ בִּתְנָאֵי כְּתֻבָּה וְהִיא אֵצֶל אִמָּהּ. וְאִם לֹא רָצְתָה הָאֵם שֶׁיִּהְיוּ בָּנֶיהָ אֶצְלָהּ אַחַר שֶׁגְּמָלָתָן אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת הָרְשׁוּת בְּיָדָהּ וְנוֹתֶנֶת אוֹתָן לַאֲבִיהֶן אוֹ מַשְׁלֶכֶת אוֹתָן לַקָּהָל אִם אֵין לָהֶן אָב וְהֵן מְטַפְּלִין בָּהֶן:"],"Mishneh Torah, Mourning 1":["מִצְוַת עֲשֵׂה לְהִתְאַבֵּל עַל הַקְּרוֹבִים. שֶׁנֶּאֱמַר (ויקרא י יט) \"וְאָכַלְתִּי חַטָּאת הַיּוֹם הַיִּיטַב בְּעֵינֵי ה'\". וְאֵין אֲבֵלוּת מִן הַתּוֹרָה אֶלָּא בְּיוֹם רִאשׁוֹן בִּלְבַד שֶׁהוּא יוֹם הַמִּיתָה וְיוֹם הַקְּבוּרָה. אֲבָל שְׁאָר הַשִּׁבְעָה יָמִים אֵינוֹ דִּין תּוֹרָה. אַף עַל פִּי שֶׁנֶּאֱמַר בַּתּוֹרָה (בראשית נ י) \"וַיַּעַשׂ לְאָבִיו אֵבֶל שִׁבְעַת יָמִים\" נִתְּנָה תּוֹרָה וְנִתְחַדְּשָׁה הֲלָכָה. וּמשֶׁה רַבֵּנוּ תִּקֵּן לָהֶם לְיִשְׂרָאֵל שִׁבְעַת יְמֵי אֲבֵלוּת וְשִׁבְעַת יְמֵי הַמִּשְׁתֶּה:","מֵאֵימָתַי יִתְחַיֵּב אָדָם בָּאֵבֶל. מִשֶּׁיִּסָּתֵם הַגּוֹלֵל. אֲבָל כָּל זְמַן שֶׁלֹּא נִקְבַּר הַמֵּת אֵינוֹ אָסוּר בְּדָבָר מִן הַדְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶן. וּמִפְּנֵי טַעַם זֶה רָחַץ דָּוִד וְסָךְ כְּשֶׁמֵּת הַיֶּלֶד טֶרֶם שֶׁיִּקָּבֵר:","הֲרוּגֵי מַלְכוּת שֶׁאֵין מְנִיחִין אוֹתָן לְהִקָּבֵר מֵאֵימָתַי מַתְחִילִין לְהִתְאַבֵּל עֲלֵיהֶן וְלִסְפֹּר שִׁבְעָה וּשְׁלֹשִׁים מִשֶּׁיִּתְיָאֲשׁוּ לִשְׁאל לַמֶּלֶךְ לְקָבְרָן. אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ מִלִּגְנֹב אוֹתָן:","מִי שֶׁטָּבַע בַּנָּהָר אוֹ מִי שֶׁאֲכָלַתּוּ חַיָּה רָעָה. מִשֶּׁנִּתְיָאֲשׁוּ לְבַקֵּשׁ. מְצָאוּהוּ אֵיבָרִים אֵיבָרִים אֵין מוֹנִין לוֹ עַד שֶׁיִּמָּצֵא רֹאשׁוֹ וְרֻבּוֹ אוֹ יִתְיָאֲשׁוּ מִלְּבַקֵּשׁ:","מִי שֶׁדַּרְכָּן לִשְׁלֹחַ הַמֵּת לִמְדִינָה אַחֶרֶת לְקָבְרוֹ וְאֵינָם יוֹדְעִים מָתַי יִקָּבֵר מֵעֵת שֶׁיַּחְזְרוּ פְּנֵיהֶן מִלְּלַוּוֹתוֹ מַתְחִילִין לִמְנוֹת שִׁבְעָה וּשְׁלֹשִׁים וּמַתְחִילִין לְהִתְאַבֵּל:","הַנְּפָלִים אֵין מִתְאַבְּלִין עֲלֵיהֶן. וְכָל שֶׁלֹּא שָׁהָה שְׁלֹשִׁים יוֹם בָּאָדָם הֲרֵי זֶה נֵפֶל. אֲפִלּוּ מֵת בְּיוֹם שְׁלֹשִׁים אֵין מִתְאַבְּלִין עָלָיו:","וְאִם נוֹדַע בְּוַדַּאי שֶׁנּוֹלַד לְתִשְׁעָה חֳדָשִׁים גְּמוּרִים אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד מִתְאַבְּלִים עָלָיו:","בֶּן תִּשְׁעָה חֳדָשִׁים שֶׁנּוֹלַד מֵת וּבֶן שְׁמוֹנָה שֶׁמֵּת אֲפִלּוּ לְאַחַר שְׁלֹשִׁים. וּמִי שֶׁיָּצָא מְחֻתָּךְ אוֹ מְרֻסָּס אַף עַל פִּי שֶׁכָּלוּ לוֹ חֳדָשָׁיו. הֲרֵי זֶה נֵפֶל וְאֵין מִתְאַבְּלִין עֲלֵיהֶן וְלֹא מִתְעַסְּקִין עִמָּהֶם:","כָּל הֲרוּגֵי מַלְכוּת אַף עַל פִּי שֶׁנֶּהֶרְגוּ בְּדִין הַמֶּלֶךְ וְהַתּוֹרָה נָתְנָה לוֹ רְשׁוּת לְהָרְגָן. הֲרֵי אֵלּוּ מִתְאַבְּלִין עֲלֵיהֶן וְאֵין מוֹנְעִין מֵהֶן כָּל דָּבָר. וּמָמוֹנָם לַמֶּלֶךְ. וְנִקְבָּרִין בְּקִבְרֵי אֲבוֹתֵיהֶן. אֲבָל כָּל הֲרוּגֵי בֵּית דִּין אֵין מִתְאַבְּלִין עֲלֵיהֶן אֲבָל אוֹנְנִין. שֶׁאֵין אֲנִינוּת אֶלָּא בַּלֵּב. וְאֵין נִקְבָּרִין עִם אֲבוֹתֵיהֶן עַד שֶׁיִּתְאַכֵּל הַבָּשָׂר. וּמָמוֹנָם לְיוֹרְשֵׁיהֶם:","כָּל הַפּוֹרְשִׁין מִדַּרְכֵי צִבּוּר וְהֵם הָאֲנָשִׁים שֶׁפָּרְקוּ עֹל הַמִּצְוֹת מֵעַל צַוָּארָן וְאֵין נִכְלָלִין בִּכְלַל יִשְׂרָאֵל בַּעֲשִׂיַּת הַמִּצְוֹת וּבִכְבוֹד הַמּוֹעֲדוֹת וִישִׁיבַת בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת אֶלָּא הֲרֵי הֵן כִּבְנֵי חוֹרִין לְעַצְמָן [כִּשְׁאָר הָאֻמּוֹת] וְכֵן הָאֶפִּיקוֹרוֹסִין [וְהַמּוּמָרִים] וְהַמּוֹסְרִין כָּל אֵלּוּ אֵין מִתְאַבְּלִין עֲלֵיהֶן. אֶלָּא אֲחֵיהֶם וּשְׁאָר קְרוֹבֵיהֶם לוֹבְשִׁין לְבָנִים וּמִתְעַטְּפִים לְבָנִים וְאוֹכְלִים וְשׁוֹתִים וּשְׂמֵחִים שֶׁהֲרֵי אָבְדוּ שׂוֹנְאָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וַעֲלֵיהֶם הַכָּתוּב אוֹמֵר (תהילים קלט כא) \"הֲלוֹא מְשַׂנְאֶיךָ ה' אֶשְׂנָא\":","הַמְאַבֵּד עַצְמוֹ לָדַעַת אֵין מִתְעַסְּקִין עִמּוֹ לְכָל דָּבָר וְאֵין מִתְאַבְּלִין עָלָיו וְאֵין מַסְפִּידִין אוֹתוֹ. אֲבָל עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִין עָלָיו בִּרְכַּת אֲבֵלִים וְכָל דָּבָר שֶׁהוּא כָּבוֹד לַחַיִּים. וְאֵי זֶהוּ הַמְאַבֵּד עַצְמוֹ לָדַעַת. לֹא שֶׁעָלָה לַגַּג וְנָפַל וּמֵת אֶלָּא הָאוֹמֵר הֲרֵינִי עוֹלֶה לְרֹאשׁ הַגַּג. רָאוּהוּ שֶׁעָלָה מִיָּד דֶּרֶךְ כַּעַס אוֹ שֶׁהָיָה מֵצֵר וְנָפַל וּמֵת. הֲרֵי זֶה בְּחֶזְקַת שֶׁאִבֵּד עַצְמוֹ לָדַעַת. אֲבָל אִם רָאוּהוּ חָנוּק וְתָלוּי בָּאִילָן אוֹ הָרוּג וּמֻשְׁלָךְ עַל גַּב סֵיפוֹ הֲרֵי זֶה בְּחֶזְקַת כָּל הַמֵּתִים וּמִתְעַסְּקִין עִמּוֹ וְאֵין מוֹנְעִין מִמֶּנּוּ דָּבָר:"],"Mishneh Torah, Mourning 8":["אָבֵל חַיָּב לִקְרֹעַ עַל מֵתוֹ שֶׁנֶּאֱמַר (ויקרא י ו) \"וּבִגְדֵיכֶם לֹא תִפְרֹמוּ וְלֹא תָמֻתוּ\" הָא אַחֵר חַיָּב לִפְרֹם. וְאֵין קְרִיעָה אֶלָּא מְעֻמָּד. שֶׁנֶּאֱמַר (שמואל ב יג לא) \"וַיָּקָם הַמֶּלֶךְ וַיִּקְרַע אֶת בְּגָדָיו\". וּמֵהֵיכָן קוֹרֵעַ. מִלְּפָנָיו. וְהַקּוֹרֵעַ מֵאַחֲרָיו אוֹ מִן הַצְּדָדִין אוֹ מִלְּמַטָּה לֹא יָצָא יְדֵי חוֹבַת קְרִיעָה. אֶלָּא כֹּהֵן גָּדוֹל שֶׁהוּא פּוֹרֵם מִלְּמַטָּה:","כַּמָּה שִׁעוּר הַקֶּרַע. טֶפַח. וְאֵין צָרִיךְ לְהַבְדִּיל שְׂפַת הַבֶּגֶד. וּמֻתָּר לוֹ לִקְרֹעַ בִּכְלִי. וְיֵשׁ לוֹ לִקְרֹעַ בִּפְנִים שֶׁלֹּא בִּפְנֵי אָדָם. לְפִיכָךְ יֵשׁ לוֹ לְהַכְנִיס יָדוֹ בִּפְנִים וְקוֹרֵעַ בְּצִנְעָה. וְאֵינוֹ חַיָּב לִקְרֹעַ אֶלָּא בֶּגֶד הָעֶלְיוֹן בִּלְבַד:","כָּל שִׁבְעַת יְמֵי אֲבֵלוּת הַקֶּרַע לְפָנִים וְאִם בָּא לְהַחְלִיף מַחְלִיף וְאֵינוֹ קוֹרֵעַ קֶרַע אַחֵר. שֶׁכָּל קֶרַע שֶׁאֵינוֹ בִּשְׁעַת חִמּוּם אֵינוֹ קֶרַע. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר הַמֵּתִים חוּץ מֵאָבִיו וְאִמּוֹ. אֲבָל עַל אָבִיו וְעַל אִמּוֹ קוֹרֵעַ עַד שֶׁמְּגַלֶּה אֶת לִבּוֹ. וּמַבְדִּיל שְׂפַת הַבֶּגֶד וְאֵינוֹ קוֹרֵעַ בִּכְלִי אֶלָּא בְּיָדוֹ מִבַּחוּץ בִּפְנֵי כָּל הָעָם וְקוֹרֵעַ כָּל הַבְּגָדִים שֶׁעָלָיו. וּבֶגֶד הַזֵּעָה הַדָּבוּק לִבְשָׂרוֹ אֵינוֹ מְעַכֵּב. וְאִם הֶחְלִיף בֶּגֶד אַחֵר חַיָּב לִקְרֹעַ כָּל שִׁבְעָה. וְכֵן עַל אָבִיו וְעַל אִמּוֹ חוֹלֵץ כְּתֵפוֹ וּמוֹצִיא זְרוֹעוֹ מִן הֶחָלוּק עַד שֶׁיִּתְגַּלֶּה כְּתֵפוֹ וּזְרוֹעוֹ. וְהוֹלֵךְ כָּךְ לִפְנֵי הַמִּטָּה. וְאַחַר שֶׁיִּקָּבֵר אָבִיו וְאִמּוֹ אֵינוֹ חַיָּב לַחְלֹץ:","קוֹרְעִין לְקָטָן מִפְּנֵי עָגְמַת נֶפֶשׁ. וְחוֹלֶה שֶׁמֵּת לוֹ מֵת אֵין מְקַרְעִין לוֹ וְלֹא מוֹדִיעִין לוֹ שֶׁלֹּא תִּטָּרֵף עָלָיו דַּעְתּוֹ. וּמְשַׁתְּקִין אֶת הַנָּשִׁים מִפָּנָיו:","וְקוֹרֵעַ אָדָם עַל חָמִיו וְעַל חֲמוֹתוֹ מִפְּנֵי כְּבוֹד אִשְׁתּוֹ. וְכֵן הָאִשָּׁה קוֹרַעַת עַל חָמִיהָ וְעַל חֲמוֹתָהּ מִפְּנֵי כְּבוֹד בַּעְלָהּ:","מִי שֶׁאֵין לוֹ חָלוּק לִקְרֹעַ וְנִזְדַּמֵּן לוֹ חָלוּק בְּתוֹךְ שִׁבְעָה קוֹרֵעַ. לְאַחַר שִׁבְעָה אֵינוֹ קוֹרֵעַ. וְעַל אָבִיו וְעַל אִמּוֹ אֲפִלּוּ לְאַחַר שִׁבְעָה קוֹרֵעַ כָּל שְׁלֹשִׁים יוֹם. וְכָל הַיּוֹצֵא בְּבֶגֶד קָרוּעַ לִפְנֵי מֵתִים כְּלוֹמַר שֶׁהוּא קָרַע עַתָּה עֲלֵיהֶן. הֲרֵי זֶה גּוֹנֵב דַּעַת הַבְּרִיּוֹת וְזִלְזֵל בִּכְבוֹד הַחַיִּים וְהַמֵּתִים:","הָאוֹמֵר לַחֲבֵרוֹ הַשְׁאִילֵנִי חֲלוּקְךָ וַאֲבַקֵּר אֶת אָבִי שֶׁהוּא חוֹלֶה וְהָלַךְ וּמְצָאוֹ שֶׁמֵּת. קוֹרֵעַ וּמְאַחֶה וּמַחֲזִיר לוֹ אֶת חֲלוּקוֹ וְנוֹתֵן לוֹ דְּמֵי קִרְעוֹ. וְאִם לֹא הוֹדִיעוֹ שֶׁהוּא מְבַקֵּר לוֹ חוֹלֶה הֲרֵי זֶה לֹא יִגַּע בּוֹ:","מִי שֶׁהָיָה לוֹ חוֹלֶה בְּתוֹךְ בֵּיתוֹ וְנִתְעַלֵּף וְסָבוּר שֶׁמֵּת וְקָרַע וְאַחַר כָּךְ מֵת. אִם בְּתוֹךְ כְּדֵי דִּבּוּר אֵינוֹ חוֹזֵר וְקוֹרֵעַ. וְאִם לְאַחַר כְּדֵי דִּבּוּר מֵת חוֹזֵר וְקוֹרֵעַ קֶרַע אַחֵר. וְכֵן מִי שֶׁאָמְרוּ לוֹ מֵת אָבִיו וְקָרַע וְאַחַר כָּךְ נִמְצָא שֶׁמֵּת בְּנוֹ. אָמְרוּ לוֹ מֵת לוֹ מֵת וְכַסָּבוּר שֶׁאָבִיו וְקָרַע וְאַחַר כָּךְ נִמְצָא בְּנוֹ. אִם תּוֹךְ כְּדֵי דִּבּוּר נוֹדַע לוֹ אֲמִתַּת הַדָּבָר יָצָא יְדֵי קְרִיעָה וְאִם לְאַחַר כְּדֵי דִּבּוּר לֹא יָצָא וְחַיָּב לִקְרוֹעַ קֶרַע אַחֵר:","מִי שֶׁמֵּתוּ לוֹ מֵתִים הַרְבֵּה כְּאֶחָד קוֹרֵעַ קֶרַע אֶחָד לְכֻלָּם. הָיָה בִּכְלָלָן אָבִיו אוֹ אִמּוֹ קוֹרֵעַ עַל כֻּלָּן קֶרַע אֶחָד וְעַל אָבִיו וְעַל אִמּוֹ קֶרַע אַחֵר:","מִי שֶׁמֵּת לוֹ מֵת וְקָרַע עָלָיו וְאַחַר כָּךְ מֵת לוֹ מֵת אַחֵר. אִם בְּתוֹךְ שִׁבְעָה קוֹרֵעַ קֶרַע אַחֵר וְאִם לְאַחַר שִׁבְעָה מוֹסִיף עַל הַקֶּרַע הָרִאשׁוֹן כָּל שֶׁהוּא. מֵת לוֹ מֵת שְׁלִישִׁי אַחַר שִׁבְעָה שֶׁל שֵׁנִי מוֹסִיף כָּל שֶׁהוּא וְכֵן מוֹסִיף וְהוֹלֵךְ עַד טַבּוּרוֹ. הִגִּיעַ לְטַבּוּרוֹ מַרְחִיק שָׁלֹשׁ אֶצְבָּעוֹת וְקוֹרֵעַ. נִתְמַלֵּא מִלְּפָנָיו מַחְזִירוֹ לַאֲחוֹרָיו. נִתְמַלֵּא מִלְּמַעְלָה הוֹפְכוֹ לְמַטָּה. אָמְרוּ לוֹ מֵת אָבִיו וְקָרַע וְאַחַר שִׁבְעָה מֵת בְּנוֹ וְהוֹסִיף. מִתְאַחֶה הַתַּחְתּוֹן וְלֹא הָעֶלְיוֹן כְּמוֹ שֶׁיִּתְבָּאֵר. אָמְרוּ לוֹ מֵת בְּנוֹ וְקָרַע וְאַחַר שִׁבְעָה מֵת אָבִיו אֵינוֹ מוֹסִיף אֶלָּא קוֹרֵעַ קֶרַע אַחֵר. שֶׁאֵין אָבִיו וְאִמּוֹ בְּתוֹסֶפֶת:"],"Mishneh Torah, Murderer and the Preservation of Life 7":["תַּלְמִיד שֶׁגָּלָה לְעָרֵי מִקְלָט מַגְלִין רַבּוֹ עִמּוֹ שֶׁנֶּאֱמַר וָחָי עֲשֵׂה לוֹ כְּדֵי שֶׁיִּחְיֶה וְחַיֵּי בַּעֲלֵי חָכְמָה וּמְבַקְּשֶׁיהָ בְּלֹא תַּלְמוּד תּוֹרָה כְּמִיתָה חֲשׁוּבִין. וְכֵן הָרַב שֶׁגָּלָה מַגְלִין יְשִׁיבָתוֹ עִמּוֹ:","עֶבֶד שֶׁגָּלָה לְעִיר מִקְלָט אֵין רַבּוֹ חַיָּב לְזוּנוֹ וּמַעֲשֵׂה יָדָיו לְרַבּוֹ. אֲבָל אִשָּׁה שֶׁגָּלְתָה לְעִיר מִקְלָט בַּעְלָהּ חַיָּב לְזוּנָהּ. וְאֵינוֹ יָכוֹל לוֹמַר לָהּ צְאִי מַעֲשֵׂה יָדַיִךְ לִמְזוֹנוֹתַיִךְ אֶלָּא אִם כֵּן הָיוּ מַסְפִּיקִין לָהּ:","רוֹצֵחַ שֶׁנִּגְמַר דִּינוֹ לְהַגְלוֹתוֹ וּמֵת קֹדֶם שֶׁיִּגְלֶה מוֹלִיכִין עַצְמוֹתָיו לְשָׁם. וְרוֹצֵחַ שֶׁמֵּת בְּעִיר מִקְלָטוֹ קוֹבְרִין אוֹתוֹ שָׁם. וּבְעֵת שֶׁיָּמוּת הַכֹּהֵן הַגָּדוֹל מוֹלִיכִין עַצְמוֹת הָרוֹצֵחַ מִשָּׁם לְקִבְרֵי אֲבוֹתָיו:","שְׁאָר הַלְוִיִּם הַשּׁוֹכְנִים בְּעָרֵי מִקְלָט כְּשֶׁיָּמוּת אֶחָד מֵהֶן אֵינוֹ נִקְבָּר בְּעִיר וְלֹא בְּתוֹךְ הַתְּחוּם. שֶׁנֶּאֱמַר (במדבר לה ג) \"וּמִגְרְשֵׁיהֶם יִהְיוּ לִבְהֶמְתָּם וְלִרְכֻשָׁם וּלְכל חַיָּתָם\". לְחַיִּים נִתָּנוּ וְלֹא לִקְבוּרָה:","רוֹצֵחַ שֶׁהָרַג בִּשְׁגָגָה בְּעִיר מִקְלָטוֹ. גּוֹלֶה בָּהּ מִשְּׁכוּנָה לִשְׁכוּנָה וְאֵינוֹ יוֹצֵא מִן הָעִיר. וְכֵן לֵוִי שֶׁהָרַג בִּמְדִינָתוֹ גּוֹלֶה לִמְדִינָה אַחֶרֶת מֵעָרֵי הַלְוִיִּם. לְפִי שֶׁכֻּלָּן קוֹלְטוֹת כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם הָרַג חוּץ מֵעָרֵי הַלְוִיִּם וּבָרַח לְעִירוֹ הֲרֵי זֶה קוֹלְטוֹ:","עִיר מִקְלָט שֶׁרֻבָּהּ רַצְחָנִים אֵינָהּ קוֹלֶטֶת. שֶׁנֶּאֱמַר (יהושע כ ד) \"וְדִבֶּר בְּאָזְנֵי זִקְנֵי הָעִיר הַהִיא אֶת דְּבָרָיו\" וְלֹא שֶׁשָּׁוִין דִּבְרֵיהֶם לִדְבָרָיו. וְכֵן עִיר שֶׁאֵין בָּהּ זְקֵנִים אֵינָהּ קוֹלֶטֶת שֶׁנֶּאֱמַר זִקְנֵי הָעִיר הַהִיא:","רוֹצֵחַ שֶׁגָּלָה לְעִיר מִקְלָט וְרָצוּ אַנְשֵׁי הָעִיר לְכַבְּדוֹ. יֹאמַר לָהֶם רוֹצֵחַ אֲנִי. אָמְרוּ לוֹ אַף עַל פִּי כֵן יְקַבֵּל מֵהֶן:","הַגּוֹלֶה אֵינוֹ יוֹצֵא מֵעִיר מִקְלָטוֹ לְעוֹלָם. וַאֲפִלּוּ לִדְבַר מִצְוָה אוֹ לְעֵדוּת בֵּין עֵדוּת מָמוֹן בֵּין עֵדוּת נְפָשׁוֹת. וַאֲפִלּוּ לְהַצִּיל נֶפֶשׁ בְּעֵדוּתוֹ אוֹ לְהַצִּיל מִיַּד הָעוֹבֵד כּוֹכָבִים אוֹ מִיַּד הַנָּהָר אוֹ מִיַּד הַדְּלֵקָה וּמִן הַמַּפּלֶת. וַאֲפִלּוּ כָּל יִשְׂרָאֵל צְרִיכִין לִתְשׁוּעָתוֹ כְּיוֹאָב בֶּן צְרוּיָה אֵינוֹ יוֹצֵא מִשָּׁם לְעוֹלָם עַד מוֹת הַכֹּהֵן הַגָּדוֹל. וְאִם יָצָא הִתִּיר עַצְמוֹ לְמִיתָה כְּמוֹ שֶׁבֵּאַרְנוּ:","אֶחָד כֹּהֵן גָּדוֹל הַמָּשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה. וְאֶחָד הַמְרֻבֶּה בִּבְגָדִים. וְאֶחָד הַכֹּהֵן הַגָּדוֹל הָעוֹבֵד. וְאֶחָד הַכֹּהֵן שֶׁעָבַר. כָּל אֶחָד מֵאַרְבַּעְתָּן שֶׁמֵּת מַחְזִיר אֶת הָרוֹצֵחַ. אֲבָל מְשׁוּחַ מִלְחָמָה אֵינוֹ מַחְזִיר מִפְּנֵי שֶׁהוּא כְּכֹהֵן הֶדְיוֹט:","רוֹצֵחַ שֶׁנִּגְמַר דִּינוֹ לִגְלוֹת וְלֹא הָיָה שָׁם כֹּהֵן גָּדוֹל. וְהַהוֹרֵג כֹּהֵן גָּדוֹל וְלֹא הָיָה שָׁם כֹּהֵן גָּדוֹל אַחֵר. וְכֹהֵן גָּדוֹל שֶׁהָרַג וְלֹא הָיָה שָׁם כֹּהֵן גָּדוֹל אַחֵר. הֲרֵי אֵלּוּ גּוֹלִין וְאֵינָן יוֹצְאִין מֵעִיר מִקְלָט לְעוֹלָם:","נִגְמַר דִּינוֹ לְגָלוּת וְאַחַר כָּךְ מֵת הַכֹּהֵן הַגָּדוֹל קֹדֶם שֶׁיִּגְלֶה הָרוֹצֵחַ. הֲרֵי זֶה פָּטוּר מִן הַגָּלוּת. וְאִם עַד שֶׁלֹּא נִגְמַר דִּינוֹ מֵת הַכֹּהֵן הַגָּדוֹל וּמִנּוּ כֹּהֵן אַחֵר תַּחְתָּיו וְאַחַר כָּךְ נִגְמַר דִּינוֹ הֲרֵי זֶה חוֹזֵר בְּמִיתָתוֹ שֶׁל שֵׁנִי שֶׁנִּגְמַר דִּינוֹ בְּפָנָיו:","נִגְמַר דִּינוֹ וְנִמְצָא הַכֹּהֵן הַגָּדוֹל בֶּן גְּרוּשָׁה אוֹ בֶּן חֲלוּצָה. בָּטְלָה כְּהֻנָּה וּכְאִלּוּ נִגְמַר דִּינוֹ בְּלֹא כֹּהֵן גָּדוֹל וְאֵינוֹ יוֹצֵא מִשָּׁם לְעוֹלָם:","רוֹצֵחַ שֶׁשָּׁב לְעִירוֹ אַחַר מוֹת הַכֹּהֵן הַגָּדוֹל. הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. וְאִם הֲרָגוֹ גּוֹאֵל הַדָּם נֶהֱרָג עָלָיו שֶׁכְּבָר נִתְכַּפֵּר לוֹ בְּגָלוּתוֹ:","אַף עַל פִּי שֶׁנִּתְכַּפֵּר לוֹ אֵינוֹ חוֹזֵר לַשְּׂרָרָה שֶׁהָיָה בָּהּ לְעוֹלָם. אֶלָּא הֲרֵי הוּא מוּרָד מִגְּדֻלָּתוֹ כָּל יָמָיו הוֹאִיל וּבָאָה תַּקָּלָה זוֹ הַגְּדוֹלָה עַל יָדוֹ:","אַף עַל פִּי שֶׁהַחוֹבֵל בְּאָבִיו בְּזָדוֹן חַיָּב מִיתַת בֵּית דִּין כְּמוֹ הַהוֹרֵג שְׁאָר אָדָם. אִם חָבַל בְּאָבִיו אוֹ בְּאִמּוֹ בִּשְׁגָגָה אֵינוֹ חַיָּב גָּלוּת. שֶׁלֹּא חִיְּבָה תּוֹרָה גָּלוּת אֶלָּא [לְהוֹרֵג] נֶפֶשׁ אָדָם בִּשְׁגָגָה בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Nazariteship 9":["הַמַּפְרִישׁ מָעוֹת שֶׁיַּקְרִיב מֵהֶן קָרְבְּנוֹת נְזִירִים וְהִקְרִיב מֵהֶן וְהוֹתִירוּ יָבִיאוּ בְּמוֹתָרָן קָרְבְּנוֹת נְזִירִים אֲחֵרִים. שֶׁמּוֹתַר נְזִירִים לִנְזִירִים. הִפְרִישׁ מָעוֹת סְתוּמִין לִנְזִירוּתוֹ וְהוֹתִירוּ יִפְּלוּ הַמּוֹתָרוֹת לִנְדָבָה:","הַמַּפְרִישׁ מָעוֹת מְפֹרָשִׁין לִנְזִירוּתוֹ וְהוֹתִירוּ. מוֹתַר מְעוֹת הָעוֹלָה יָבוֹאוּ עוֹלָה. וּמוֹתַר הַחַטָּאת יוֹלִיכֵם לְיָם הַמֶּלַח. וּמוֹתַר דְּמֵי הַשְּׁלָמִים יָבוֹאוּ שְׁלָמִים. וְאֵין טְעוּנִין לֶחֶם וְנֶאֱכָלִין לְיוֹם אֶחָד:","הַמַּפְרִישׁ מָעוֹת לִנְזִירוּתוֹ וּמֵת אִם הָיוּ סְתוּמִין יִפְּלוּ לִנְדָבָה. הָיוּ מְפֹרָשִׁין. דְּמֵי עוֹלָה [יָבוֹאוּ עוֹלָה]. דְּמֵי חַטָּאת יֵלְכוּ לְיָם הַמֶּלַח. דְּמֵי שְׁלָמִים יָבוֹאוּ שְׁלָמִים וְנֶאֱכָלִין לְיוֹם אֶחָד וְאֵין טְעוּנִין לֶחֶם:","כֵּיצַד הֵם הַמָּעוֹת הַסְּתוּמִין. כְּגוֹן שֶׁהִפְרִישׁ מָעוֹת לְהָבִיא מֵהֶן קָרְבְּנוֹתָיו וְלֹא אָמַר כְּלוּם. אֲבָל אִם אָמַר אֵלּוּ לְחוֹבָתִי הֲרֵי אֵלּוּ כִּמְפֹרָשִׁין. וְאֵין צָרִיךְ לוֹמַר אִם אָמַר אֵלּוּ לְעוֹלָתִי וּלְחַטָּאתִי וְלִשְׁלָמַי שֶׁהֵן כִּמְפֹרָשִׁין:","הַמַּפְרִישׁ בְּהֵמָה בַּעֲלַת מוּם הֲרֵי הִיא כְּמָעוֹת סְתוּמִין. וְכֵן הַמַּפְרִישׁ לָשׁוֹן שֶׁל כֶּסֶף וְשֶׁל זָהָב אוֹ כְּלִי אַף עַל פִּי שֶׁאָמַר זֶה לְחַטָּאתִי וּלְעוֹלָתִי וְלִשְׁלָמַי הֲרֵי הוּא כְּמָעוֹת סְתוּמִין:","הָאוֹמֵר אֵלּוּ לְחַטָּאתִי וְהַשְּׁאָר לִנְזִירוּתִי וּמֵת. אוֹ שֶׁהָיְתָה אִשָּׁה וְהֵפֵר לָהּ בַּעְלָהּ. דְּמֵי חַטָּאת יֵלְכוּ לְיָם הַמֶּלַח וְהַשְּׁאָר יָבוֹאוּ בְּחֶצְיָן עוֹלָה וּבְחֶצְיָן שְׁלָמִים:","אָמַר אֵלּוּ לְעוֹלָתִי וְהַשְּׁאָר לִנְזִירוּתִי דְּמֵי עוֹלָה יָבוֹאוּ עוֹלָה וְהַשְּׁאָר יִפְּלוּ לִנְדָבָה:","מִי שֶׁדִּמָּה שֶׁהוּא חַיָּב בִּנְזִירוּת וְהִפְרִישׁ קָרְבְּנוֹתָיו וְאַחַר כָּךְ שָׁאַל לְחָכָם וְהוֹרָהוּ שֶׁאֵין זֶה נֵדֶר וְאֵינוֹ חַיָּב בִּנְזִירוּת מַה יַּעֲשֶׂה בַּקָּרְבָּנוֹת שֶׁהִפְרִישׁ. יֵצְאוּ וְיִרְעוּ בָּעֵדֶר. שֶׁזֶּה הֶקְדֵּשׁ טָעוּת שֶׁאֵינוֹ הֶקְדֵּשׁ כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הָאִשָּׁה שֶׁנָּדְרָה בְּנָזִיר וְהִפְרִישָׁה קָרְבְּנוֹתֶיהָ וְאַחַר כָּךְ הֵפֵר לָהּ בַּעְלָהּ אִם שֶׁלּוֹ הָיְתָה הַבְּהֵמָה תֵּצֵא וְתִרְעֶה בָּעֵדֶר שֶׁאֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. וְאִם הָיוּ הַקָּרְבָּנוֹת מִשֶּׁלָּהּ וְאֵין לְבַעְלָהּ בָּהֶן כְּלוּם. כְּגוֹן שֶׁנָּתְנוּ לָהּ בְּמַתָּנָה עַל מְנָת שֶׁלֹּא יִהְיֶה לַבַּעַל בָּהֶן רְשׁוּת אֶלָּא מַה שֶּׁתִּרְצֶה תַּעֲשֶׂה בָּהֶן. הַחַטָּאת תָּמוּת. וְהָעוֹלָה תִּקָּרֵב עוֹלָה. וְהַשְּׁלָמִים יִקָּרְבוּ שְׁלָמִים. וְנֶאֱכָלִין לְיוֹם אֶחָד וְאֵינָן טְעוּנִין לֶחֶם:","הִפְרִישָׁה מָעוֹת סְתוּמִין לְקָרְבְּנוֹתֶיהָ יִפְּלוּ לִנְדָבָה. הָיוּ מְפֹרָשִׁין דְּמֵי חַטָּאת יֵלְכוּ לְיָם הַמֶּלַח. וּדְמֵי עוֹלָה יָבוֹאוּ עוֹלָה. וּדְמֵי שְׁלָמִים יָבוֹאוּ שְׁלָמִים וְנֶאֱכָלִין לְיוֹם אֶחָד וְאֵינָן טְעוּנִין לֶחֶם:","הָאִשָּׁה שֶׁנָּדְרָה בְּנָזִיר וְנִטְמֵאת בְּתוֹךְ יְמֵי נְזִירוּת וְאַחַר כָּךְ שָׁמַע בַּעְלָהּ וְהֵפֵר לָהּ הֲרֵי זוֹ מְבִיאָה קָרְבַּן טֻמְאָה:","הָאִישׁ שֶׁהִדִּיר אֶת בְּנוֹ בְּנָזִיר וְהִפְרִישׁ עָלָיו קָרְבְּנוֹתָיו וְלֹא רָצָה הַבֵּן בִּנְזִירוּת זוֹ. וּמָחָה הוּא אוֹ קְרוֹבָיו אוֹ שֶׁגִּלֵּחַ הוּא אוֹ שֶׁגִּלְּחוּהוּ קְרוֹבָיו. הַחַטָּאת תָּמוּת. וְהָעוֹלָה תִּקָּרֵב עוֹלָה וְהַשְּׁלָמִים יִקָּרְבוּ שְׁלָמִים וְנֶאֱכָלִין לְיוֹם אֶחָד וְאֵינָן טְעוּנִין לֶחֶם. הִפְרִישׁ לוֹ מָעוֹת סְתוּמִים הֲרֵי אֵלּוּ יִפְּלוּ לִנְדָבָה. הָיוּ מָעוֹת מְפֹרָשִׁין. דְּמֵי חַטָּאת יֵלְכוּ לְיָם הַמֶּלַח. דְּמֵי עוֹלָה יָבוֹאוּ עוֹלָה. דְּמֵי שְׁלָמִים יָבוֹאוּ שְׁלָמִים וְאֵינָן טְעוּנִין לֶחֶם וְנֶאֱכָלִין לְיוֹם אֶחָד:","הָאוֹמֵר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן וְהִפְרִישׁ קָרְבָּן וְהִפִּילָה אִשְׁתּוֹ וְחָזְרָה וְיָלְדָה. הֲרֵי הַקָּרְבָּנוֹת סָפֵק וַאֲסוּרִין בְּגִזָּה וּבַעֲבוֹדָה:","שְׁנֵי נְזִירִים שֶׁנִּטְמָא אֶחָד מֵהֶם וְאֵין יָדוּעַ מִי הוּא כֵּיצַד מְבִיאִין קָרְבְּנוֹתֵיהֶן. מְבִיאִין קָרְבַּן טֻמְאָה וְקָרְבַּן טָהֳרָה בִּמְלֹאת יְמֵי נְזִירוּתָם. וְאוֹמֵר אֶחָד מֵהֶם אִם אֲנִי הוּא הַטָּמֵא קָרְבַּן טֻמְאָה שֶׁלִּי וְקָרְבַּן טָהֳרָה שֶׁלְּךָ. וְאִם אֲנִי הוּא הַטָּהוֹר קָרְבַּן טָהֳרָה שֶׁלִּי וְקָרְבַּן טֻמְאָה שֶׁלְּךָ. וְסוֹפְרִים יְמֵי נְזִירוּת אַחֶרֶת גְּמוּרָה מֵאַחַר קָרְבָּנוֹת אֵלּוּ. וְחוֹזְרִין וּמְבִיאִין קָרְבַּן טָהֳרָה. וְאוֹמֵר אֶחָד מֵהֶן אִם אֲנִי הוּא שֶׁהָיִיתִי טָמֵא קָרְבַּן טֻמְאָה שֶׁלִּי וְקָרְבַּן טָהֳרָה שֶׁלְּךָ וְזֶה קָרְבַּן טָהֳרָתִי. אִם אֲנִי הוּא הַטָּהוֹר קָרְבַּן טָהֳרָה שֶׁלִּי וְקָרְבַּן טֻמְאָה שֶׁלְּךָ וְזֶה קָרְבַּן טָהֳרָתְךָ. נִמְצְאוּ שֶׁלֹּא הִפְסִידוּ בְּקָרְבְּנוֹתֵיהֶן כְּלוּם:","מֵת אֶחָד מֵהֶן הֲרֵי זֶה מֵבִיא חַטַּאת הָעוֹף וְעוֹלַת בְּהֵמָה. וְיֹאמַר אִם טָמֵא הָיִיתִי הַחַטָּאת מֵחוֹבָתִי וְהָעוֹלָה נְדָבָה. וְאִם טָהוֹר הָיִיתִי הָעוֹלָה מֵחוֹבָתִי וְחַטַּאת הָעוֹף סָפֵק. וְסוֹפֵר יְמֵי נְזִירוּת אַחֶרֶת וּמֵבִיא קָרְבַּן טָהֳרָה. וְאוֹמֵר אִם טָמֵא הָיִיתִי הָעוֹלָה הָרִאשׁוֹנָה נְדָבָה וְזוֹ חוֹבָה וְאִם טָהוֹר הָיִיתִי הָעוֹלָה הָרִאשׁוֹנָה חוֹבָה וְזוֹ נְדָבָה וְזֶה שְׁאָר קָרְבָּנִי. וְאֵין אֶחָד מִשְּׁנֵיהֶם מְגַלֵּחַ תִּגְלַחַת טֻמְאָה אֶלָּא אִם כֵּן הָיוּ קְטַנִּים אוֹ נָשִׁים שֶׁאֵין אֵלּוּ מַקִּיפִין פְּאַת רֹאשָׁם מִסָּפֵק:","וְכֵיצַד יִוָּלֵד לָהֶם סָפֵק זֶה בְּטֻמְאָה. כְּגוֹן שֶׁהָיוּ שְׁנֵי הַנְּזִירִין עוֹמְדִין בִּרְשׁוּת הַיָּחִיד שֶׁסְּפֵק טֻמְאָה שָׁם טָמֵא וְהָיָה אֶחָד מִבַּחוּץ רוֹאֶה אוֹתָן וְאָמַר רָאִיתִי אֶחָד מִכֶּם שֶׁנִּטְמָא וְאֵינִי יוֹדֵעַ מִי הוּא. אֲבָל אִם הָיָה עֵד זֶה עִמָּהֶן בֶּחָצֵר הֲרֵי שְׁנֵיהֶן טְהוֹרִין. כֵּיוָן שֶׁהֵם שְׁלֹשָׁה הֲרֵי הֵן רַבִּים וְרַבִּים בִּרְשׁוּת הַיָּחִיד סְפֵקָן טָהוֹר כִּסְפֵק טֻמְאָה בִּרְשׁוּת הָרַבִּים שֶׁהוּא טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁשָּׁתְקוּ הַנְּזִירִים שְׁנֵיהֶם אוֹ נִסְתַּפֵּק לָהֶן הַדָּבָר. אֲבָל אִם אָמַר אֶחָד מֵהֶן אֲנִי לֹא נִטְמֵאתִי אֲפִלּוּ שְׁנֵי עֵדִים מְעִידִים עָלָיו שֶׁנִּטְמָא אֵינוֹ מֵבִיא קָרְבָּן עַל פִּיהֶם. שֶׁזֶּה שֶׁאָמַר לֹא נִטְמֵאתִי כְּאוֹמֵר אֵינִי מֵבִיא בְּטֻמְאָה שֶׁכְּבָר נִשְׁאַלְתִּי עַל נְזִירוּתִי וְנִמְצָא שֶׁאֵינוֹ מַכְחִישׁ אֶת הָעֵדִים וְאָדָם נֶאֱמָן עַל יְדֵי עַצְמוֹ. אֲבָל אִם שָׁתַק אוֹ נִסְתַּפֵּק לוֹ הֲרֵי זֶה מֵבִיא קָרְבָּן אֲפִלּוּ עַל פִּי עֵד אֶחָד כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן עֵד שֶׁאָמַר לְאֶחָד בְּפָנַי נָדַרְתָּ בִּנְזִירוּת אִם הִכְחִישׁוֹ אֵינוֹ חַיָּב כְּלוּם. וְאִם לֹא הִכְחִישׁוֹ נוֹהֵג נְזִירוּת עַל פִּיו. אֲפִלּוּ אָמַר לִשְׁנַיִם רָאִיתִי אֶחָד מִכֶּם שֶׁנָּזַר וְאֵינִי יוֹדֵעַ מִי הוּא הוֹאִיל וְאֵין מַכְחִישִׁין אוֹתוֹ נוֹהֲגִין נְזִירוּת עַל פִּיו. נָהַג נְזִירוּת עַל פִּי עֵד אֶחָד וְשָׁתָה יַיִן אוֹ נִטְמָא וְהִתְרוּ בּוֹ [שְׁנַיִם] לוֹקֶה אַף עַל פִּי שֶׁעִקַּר הַנְּזִירוּת בְּעֵד אֶחָד:","מֵת שֶׁהָיָה מֻשְׁכָּב לְרֹחַב הַדֶּרֶךְ אַף עַל פִּי שֶׁאֵין שָׁם מָקוֹם לַעֲבֹר אֶלָּא עָלָיו אוֹ נוֹגֵעַ בְּצִדּוֹ וְאַף עַל פִּי שֶׁהִיא טֻמְאָה יְדוּעָה וְעָבַר שָׁם נָזִיר הֲרֵי זֶה טָהוֹר הוֹאִיל וְסָפֵק בִּרְשׁוּת הָרַבִּים טָהוֹר:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְהַלֵּךְ בְּרַגְלָיו. אֲבָל אִם הָיָה רוֹכֵב אוֹ טָעוּן מַשָּׂא הֲרֵי זֶה טָמֵא. שֶׁהַמְּהַלֵּךְ בְּרַגְלָיו אֶפְשָׁר שֶׁלֹּא יִגַּע אוֹ שֶׁלֹּא יַאֲהִיל אוֹ שֶׁלֹּא יָסִיט אֲבָל טָעוּן אוֹ רוֹכֵב אִי אֶפְשָׁר שֶׁלֹּא יִגַּע וְשֶׁלֹּא יַאֲהִיל אוֹ שֶׁלֹּא יָסִיט שֶׁהֲרֵי הַמֵּת לְרֹחַב הַדֶּרֶךְ:"],"Mishneh Torah, Negative Mitzvot 109":["שלא למכור מעשר בהמה, שנאמר \"לא ייגאל\" (ויקרא כז,לג)."],"Mishneh Torah, Negative Mitzvot 12":["שלא ליתן אבן משכית, שנאמר \"ואבן משכית לא תיתנו בארצכם\" (ויקרא כו,א)."],"Mishneh Torah, Negative Mitzvot 130":["שלא לאכול מן הקודשים שנטמאו, שנאמר \"והבשר אשר ייגע בכל טמא, לא ייאכל\" (ויקרא ז,יט)."],"Mishneh Torah, Negative Mitzvot 141":["שלא לאכול מעשר שני של דגן חוץ לירושלים, שנאמר \"לא תוכל לאכול בשעריך, מעשר דגנך\" (דברים יב,יז)."],"Mishneh Torah, Negative Mitzvot 152":["שלא להוציא דמי מעשר שני בשאר דברים שאין בהם אכילה ושתייה, שנאמר \"ולא נתתי ממנו, למת\" (דברים כו,יד); וכל שהוא חוץ לצורכי הגוף החי, \"נתתי ממנו, למת\" אקרא בו."],"Mishneh Torah, Negative Mitzvot 163":["שלא ייכנס כוהן למקדש פרוע ראש, שנאמר \"ראשיכם אל תפרעו\" (ויקרא י,ו)."],"Mishneh Torah, Negative Mitzvot 174":["שלא לאכול עוף טמא, שנאמר \"ואת אלה תשקצו מן העוף, לא ייאכלו\" (ויקרא יא,יג)."],"Mishneh Torah, Negative Mitzvot 185":["שלא לאכול חלב, שנאמר \"כל חלב שור וכשב, ועז--לא תאכלו\" (ויקרא ז,כג)."],"Mishneh Torah, Negative Mitzvot 196":["שלא לאכול ביום הצום, שנאמר \"כי כל הנפש אשר לא תעונה\" (ויקרא כג,כט)."],"Mishneh Torah, Negative Mitzvot 206":["שלא יאכל זוגין, שנאמר \"ועד זג--לא יאכל\" (במדבר ו,ד)."],"Mishneh Torah, Negative Mitzvot 217":["שלא להרביע בהמה מין בשאינו מינו, שנאמר \"בהמתך לא תרביע כלאיים\" (ויקרא יט,יט)."],"Mishneh Torah, Negative Mitzvot 228":["שלא לשנות מגרשי הלויים ושדותיהם, שנאמר \"ושדה מגרש עריהם, לא יימכר\" (ויקרא כה,לד); מפי השמועה למדו שזו אזהרה שלא ישתנה."],"Mishneh Torah, Negative Mitzvot 239":["שלא ימשכן בעל חוב בזרוע, שנאמר \"לא תבוא אל ביתו, לעבוט עבוטו\" (דברים כד,י)."],"Mishneh Torah, Negative Mitzvot 25":["שלא ליהנות בעבודה זרה, ובכל משמשיה ובתקרובת שלה וביין שנתנסך לה, שנאמר \"ולא תביא תועבה אל ביתך\" (דברים ז,כו)."],"Mishneh Torah, Negative Mitzvot 260":["שלא להניח הגוי לעבד בעבד עברי הנמכר לו בפרך, שנאמר \"לֹא יִרְדֶּנּוּ בְּפָרֶךְ לְעֵינֶךָ\" (ויקרא כה, נג)."],"Mishneh Torah, Negative Mitzvot 271":["שלא לעשות עול במדה, שנאמר \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בְּמִדָּה\" (ויקרא יט, לה); מפי השמועה למדו שהכתוב מזהיר לא תעשו עול במשפט המדה."],"Mishneh Torah, Negative Mitzvot 282":["שלא לנטות אחרי רבים בדיני נפשות, אם היו המחייבין יתר על המזכין אחד, שנאמר \"לֹא תִהְיֶה אַחֲרֵי רַבִּים לְרָעוֹת\" (שמות כג, ב)."],"Mishneh Torah, Negative Mitzvot 293":["שלא לחוס על הרודף, אלא הורגין אותו קודם שיגיע לנרדף ויהרגנו או יגלה ערוותו, שנאמר \"וְקַצּוֹתָה אֶת כַּפָּהּ לֹא תָחוֹס עֵינְךָ\" (דברים כה, יב)."],"Mishneh Torah, Negative Mitzvot 303":["שלא להלבין פני אדם מישראל, שנאמר \"הוכח תוכיח את עמיתך, ולא תישא עליו חטא\" (ויקרא יט,יז)."],"Mishneh Torah, Negative Mitzvot 314":["שלא לגרוע מכל מצוות התורה, שנאמר \"ולא תגרע ממנו\" (דברים יג,א)."],"Mishneh Torah, Negative Mitzvot 325":["שלא לעשות מלאכה בחג השבועות, שנאמר בו \"כל מלאכת עבודה, לא תעשו\" (ויקרא כג,כא; במדבר כח,כו)."],"Mishneh Torah, Negative Mitzvot 336":["שלא לגלות ערוות הבת; ולמה לא נתפרשה בתורה, מפני שאסר בת הבת שתק מן הבת, ומפי השמועה למדו שאיסור הבת מגופי תורה, כשאר עריות."],"Mishneh Torah, Negative Mitzvot 347":["שלא לגלות ערוות אשת איש, שנאמר \"ואל אשת, עמיתך--לא תיתן שכובתך\" (ויקרא יח,כ)."],"Mishneh Torah, Negative Mitzvot 358":["שלא יגרש האונס אנוסתו, שנאמר \"לא יוכל שלחה, כל ימיו\" (דברים כב,כט)."],"Mishneh Torah, Negative Mitzvot 4":["שלא לעשות צורות לנואי, ואף על פי שאין עובדין אותן, שנאמר \"לא תעשון, איתי\" (שמות כ,יט)."],"Mishneh Torah, Negative Mitzvot 50":["שלא לחון על עובדי עבודה זרה, שנאמר \"ולא תחונם\" (דברים ז,ב)."],"Mishneh Torah, Negative Mitzvot 61":["שלא לעבור על שבועת ביטוי, שנאמר \"וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר\" (ויקרא יט, יב)"],"Mishneh Torah, Negative Mitzvot 72":["שלא יתעסקו הלויים בעבודת הכהנים ולא הכהנים בעבודת הלויים, שנאמר \"אֶל כְּלֵי הַקֹּדֶשׁ וְאֶל הַמִּזְבֵּחַ לֹא יִקְרְבוּ גַם הֵם גַּם אַתֶּם\" (במדבר יח, ג)."],"Mishneh Torah, Negative Mitzvot 83":["שלא לעשות במתכונת שמן המשחה, שנאמר \"ובמתכונתו, לא תעשו\" (שמות ל,לב)."],"Mishneh Torah, Negative Mitzvot 94":["שלא להקטיר אימורי בעלי מומין, שנאמר \"ואישה, לא תיתנו מהם\" (ויקרא כב,כב)."],"Mishneh Torah, Neighbors 2":["חַצְרוֹת הַכְּפָרִים שֶׁכָּל אֶחָד וְאֶחָד בּוֹנֶה לוֹ בַּיִת וְנִמְצֵאת הֶחָצֵר שֶׁבֵּין שְׁנֵי הַבָּתִּים מְשֻׁתֶּפֶת לְכָל בְּנֵי הַבָּתִּים. הֲרֵי יֵשׁ לְכָל פֶּתַח וּפֶתַח אַרְבַּע אַמּוֹת לְפָנָיו בְּרֹחַב כָּל הַפֶּתַח. וְהַנִּשְׁאָר מִן הֶחָצֵר אִם יֵשׁ בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת לְכָל שֻׁתָּף וְשֻׁתָּף חוֹלְקִין אוֹתָהּ וְאִם לָאו אֵין חוֹלְקִין אוֹתָהּ שֶׁכָּל חָצֵר שֶׁאֵין לָהּ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵינָהּ קְרוּיָה חָצֵר כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד. הָיוּ שְׁנֵי שֻׁתָּפִין לָזֶה שְׁנֵי בָּתִּים וְלָזֶה בַּיִת אֶחָד. זֶה שֶׁיֵּשׁ לוֹ שְׁנֵי בָּתִּים מוֹדְדִין לוֹ מִן הֶחָצֵר אַרְבַּע אַמּוֹת לְכָל בַּיִת וּבַיִת עַל כָּל רֹחַב הַפֶּתַח אֲפִלּוּ הָיָה עֶשֶׂר אַמּוֹת. וְזֶה שֶׁיֵּשׁ לוֹ בַּיִת אֶחָד נוֹתְנִין לוֹ אַרְבַּע אַמּוֹת בְּרֹחַב פִּתְחוֹ לִפְנֵי פִּתְחוֹ. וְהַנִּשְׁאָר מִן הֶחָצֵר אִם יֵשׁ בָּהּ שְׁמוֹנֶה אַמּוֹת כְּדֵי שֶׁיְּהֵא לָזֶה אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת וְלָזֶה אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת חוּץ מִן הַפְּתָחִים יֵשׁ בָּהּ דִּין חֲלוּקָה וְחוֹלְקִין. פָּחוֹת מִזֶּה אֵין בָּהּ דִּין חֲלוּקָה:","בַּיִת שֶׁיֵּשׁ לוֹ פְּתָחִים רַבִּים מִכָּל רוּחוֹתָיו יֵשׁ לוֹ אַרְבַּע אַמּוֹת לְכָל רוּחַ. וְאִם יִחֵד לוֹ פֶּתַח אֵין לוֹ אֶלָּא אַרְבַּע אַמּוֹת כְּנֶגֶד פִּתְחוֹ:","אַכְסַדְרָה אִם אֶפְשָׁר לוֹ לְהִכָּנֵס לְתוֹכָהּ בְּמַשָּׂאוֹ אֵין לָהּ אַרְבַּע אַמּוֹת וְאִם לָאו יֵשׁ לָהּ אַרְבַּע אַמּוֹת. שֶׁלֹּא אָמְרוּ שֶׁיֵּשׁ לְכָל פֶּתַח וּפֶתַח אַרְבַּע אַמּוֹת אֶלָּא לִפְרֹק שָׁם מַשָּׂאוֹ:","בֵּית שַׁעַר אוֹ מִרְפֶּסֶת יֵשׁ לָהֶם אַרְבַּע אַמּוֹת. הָיוּ חֲמִשָּׁה בָּתִּים פְּתוּחִים לְמִרְפֶּסֶת וְהַמִּרְפֶּסֶת פְּתוּחָה לֶחָצֵר אֵין לָהּ אֶלָּא אַרְבַּע אַמּוֹת:","לוּל שֶׁל תַּרְנְגוֹלִים אֵין לוֹ אַרְבַּע אַמּוֹת:","בַּיִת חֶצְיוֹ מְקֹרֶה וְחֶצְיוֹ שֶׁאֵינוֹ מְקֹרֶה בֵּין שֶׁקֵּרוּיוֹ כְּלַפֵּי פְּנִים בֵּין שֶׁקֵּרוּיוֹ כְּלַפֵּי חוּץ אֵין לוֹ אַרְבַּע אַמּוֹת:","בַּיִת סָתוּם יֵשׁ לוֹ אַרְבַּע אַמּוֹת. פָּרַץ אֶת פְּצִימָיו אֵין לוֹ אַרְבַּע אַמּוֹת:","בַּיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵין לוֹ אַרְבַּע אַמּוֹת בֶּחָצֵר אֶלָּא אִם יֵשׁ בֶּחָצֵר אַרְבַּע אַמּוֹת לָזֶה וְאַרְבַּע אַמּוֹת לָזֶה עַד פֶּתַח הַבַּיִת הַזֶּה חוֹלְקִין. וְהַזֶּבֶל שֶׁל חָצֵר מִתְחַלֵּק לְפִי הַפְּתָחִים. אֲבָל אַכְסַנְיָא שֶׁל מֶלֶךְ לְפִי בְּנֵי אָדָם:","הַשֻּׁתָּפִין שֶׁרָצוּ לַחֲלֹק דָּבָר שֶׁאֵין בּוֹ דִּין חֲלוּקָה אַף עַל פִּי שֶׁהֵן מַפְסִידִין אֶת שְׁמוֹ חוֹלְקִין. וּבְכִתְבֵי הַקֹּדֶשׁ אַף עַל פִּי שֶׁרָצוּ לֹא יַחֲלֹקוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֶרֶךְ אֶחָד. אֲבָל בִּשְׁתֵּי כְּרִיכוֹת חוֹלְקִין:","מָקוֹם שֶׁאֵין בּוֹ דִּין חֲלוּקָה שֶׁרָצוּ שֻׁתָּפִין לְחַלְּקוֹ אַף עַל פִּי שֶׁקָּנוּ מִיָּדָם כָּל אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. שֶׁזֶּה קִנְיַן דְּבָרִים הוּא כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם קָנוּ מִיָּדָם שֶׁזֶּה רָצָה בְּרוּחַ פְּלוֹנִי וְזֶה רָצָה בְּרוּחַ פְּלוֹנִי אֵינָן יְכוֹלִים לַחְזֹר בָּהֶם. וְכֵן אִם הָלַךְ זֶה בְּעַצְמוֹ וְהֶחֱזִיק בְּחֶלְקוֹ וְזֶה בְּעַצְמוֹ וְהֶחֱזִיק בְּחֶלְקוֹ אַף עַל פִּי שֶׁלֹּא קָנוּ מִיָּדָם אֵין אֶחָד מֵהֶם יָכוֹל לַחְזֹר בַּחֲבֵרוֹ:","הָאַחִין שֶׁחָלְקוּ וְעָשׂוּ בֵּינֵיהֶם גּוֹרָל כֵּיוָן שֶׁעָלָה גּוֹרָל לְאֶחָד מֵהֶן קָנוּ כֻּלָּן. בַּהֲנָיָה שֶׁנַּעֲשֵׂית לָהֶם שֶׁשָּׁמְעוּ זֶה מִזֶּה לְדָבָר שֶׁהִסְכִּימוּ עָלָיו גָּמַר כָּל אֶחָד מֵהֶן וּמַקְנֶה לַחֲבֵרוֹ:","הָאַחִין שֶׁחָלְקוּ הֲרֵי הֵן כְּלָקוֹחוֹת זֶה מִזֶּה. וְאֵין לָהֶם דֶּרֶךְ זֶה עַל זֶה. וְלֹא סֻלָּמוֹת זֶה עַל זֶה. וְלֹא חַלּוֹנוֹת זֶה עַל זֶה. וְלֹא אַמַּת הַמַּיִם זֶה עַל זֶה. שֶׁכֵּיוָן שֶׁחָלְקוּ לֹא נִשְׁאַר לְאֶחָד מֵהֶן זְכוּת בְּחֵלֶק חֲבֵרוֹ. לְפִיכָךְ יֵשׁ לוֹמַר לָאַחִין כְּשֶׁהָיְתָה הַשָּׂדֶה כֻּלָּהּ לְאֶחָד הָיָה מַעֲבִיר בָּהּ אַמַּת הַמַּיִם הַזֹּאת מִמָּקוֹם לְמָקוֹם אֲבָל עַתָּה שֶׁנַּעֲשֵׂית זֶה חֶלְקִי יֵשׁ לִי לְהָסִיר אַמַּת הַמַּיִם מֵעָלַי. וְכֵן סוֹתֵם הַחַלּוֹן הַמַּשְׁקִיף עַל חֶלְקוֹ וּבוֹנֶה בְּצַד הַסֻּלָּם אַף עַל פִּי שֶׁהוּא מְבַטֵּל תַּשְׁמִישׁוֹ. וְהוּא הַדִּין בִּשְׁנַיִם שֶׁקָּנוּ שָׂדֶה מֵאֶחָד וְחָלְקוּ לֹא נִשְׁאַר לְאֶחָד מֵהֶם זְכוּת בְּחֵלֶק חֲבֵרוֹ. וּמַפְסִיק אַמַּת הַמַּיִם מֵחֶלְקוֹ וְסוֹתֵם הַחַלּוֹנוֹת:","אֲבָל שְׁנַיִם שֶׁקָּנוּ שָׂדֶה מִשְּׁנֵי אֲנָשִׁים אוֹ מִשְּׁנֵי אַחִין. אֵין לְאֶחָד מֵהֶן לְהַפְסִיק אַמַּת הַמַּיִם וְלֹא לְשַׁנּוֹת דָּבָר מִן הַנְּזָקִים שֶׁהֶחְזִיקוּ בָּהֶן הַמּוֹכְרִין:","חֲצַר הַשֻּׁתָּפִין שֶׁיֵּשׁ בָּהּ דִּין חֲלוּקָה. אוֹ שֶׁחִלְּקוּהָ בִּרְצוֹנָם אַף עַל פִּי שֶׁאֵין בָּהּ דִּין חֲלוּקָה. יֵשׁ לְכָל אֶחָד מֵהֶן לָכֹף אֶת חֲבֵרוֹ לִבְנוֹת הַכֹּתֶל בָּאֶמְצַע כְּדֵי שֶׁלֹּא יִרְאֵהוּ חֲבֵרוֹ בְּשָׁעָה שֶׁמִּשְׁתַּמֵּשׁ בְּחֶלְקוֹ. שֶׁהֶזֵּק רְאִיָּה הֶזֵּק הוּא וְאֵין לוֹ חֲזָקָה בֶּחָצֵר. אֶלָּא אַף עַל פִּי שֶׁעָמְדוּ כָּךְ שָׁנִים רַבּוֹת בְּלֹא מְחִצָּה כּוֹפֵהוּ לַעֲשׂוֹת מְחִצָּה בְּכָל עֵת שֶׁיִּרְצֶה:","רֹחַב מְקוֹם הַכֹּתֶל מִשֶּׁל שְׁנֵיהֶם. וְכַמָּה יִהְיֶה רָחְבּוֹ. הַכּל כְּמִנְהַג הַמְּדִינָה. וַאֲפִלּוּ נָהֲגוּ לַעֲשׂוֹת מְחִצָּה בֵּינֵיהֶם בְּקָנִים וּבְהוּצִין. וּבִלְבַד שֶׁלֹּא יִהְיֶה אֲוִיר שֶׁיִּסְתַּכֵּל בּוֹ וְיִרְאֶה אֶת חֲבֵרוֹ:","כַּמָּה גֹּבַהּ הַכֹּתֶל אֵין פָּחוֹת מֵאַרְבַּע אַמּוֹת. וְכֵן בְּגִנָּה כּוֹפֵהוּ לְהַבְדִּיל גִּנָּתוֹ מִגִּנַּת חֲבֵרוֹ בִּמְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים. אֲבָל בְּבִקְעָה אֵין צָרִיךְ לְהַבְדִּיל בִּקְעָתוֹ מִבִּקְעַת חֲבֵרוֹ אֶלָּא בְּמָקוֹם שֶׁנָּהֲגוּ. רָצָה לְהַבְדִּיל בִּקְעָתוֹ מִבִּקְעַת חֲבֵרוֹ כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּבוֹנֶה וְעוֹשֶׂה חָזִית כְּמוֹ אַמָּה בְּסִיד מִבַּחוּץ כְּדֵי לְהוֹדִיעַ שֶׁהַכֹּתֶל שֶׁלּוֹ. לְפִיכָךְ אִם נָפַל הַכֹּתֶל הַמָּקוֹם וְהָאֲבָנִים שֶׁלּוֹ. וְאִם עָשׂוּ מִדַּעַת שְׁנֵיהֶם בּוֹנִים הַכֹּתֶל בָּאֶמְצַע וְעוֹשִׂין חֲזִית מִכָּאן וּמִכָּאן. לְפִיכָךְ אִם נָפַל הַכֹּתֶל הַמָּקוֹם וְהָאֲבָנִים שֶׁל שְׁנֵיהֶן:","הַמּוֹכֵר גִּנָּה לַחֲבֵרוֹ סְתָם וְהָיְתָה מְעֹרֶבֶת עִם גִּנּוֹת אֲחֵרוֹת. כּוֹפִין אֶת הַלּוֹקֵחַ לִבְנוֹת אֶת הַכֹּתֶל בֵּינֵיהֶם. וַאֲפִלּוּ בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִגְדֹּר בַּגִּנּוֹת. אֲבָל אִם מָכַר בִּקְעָה סְתָם אֵין מְחַיְּבִים אוֹתוֹ לִגְדֹּר אֶלָּא בְּמָקוֹם שֶׁנָּהֲגוּ:","מָקוֹם שֶׁנָּהֲגוּ לִבְנוֹת כְּתָלִים הַמַּבְדִּילִין בַּחֲצֵרוֹת אוֹ בַּגִּנּוֹת בַּאֲבָנִים שֶׁאֵינָן גָּזִית זֶה נוֹתֵן שְׁלֹשָׁה טְפָחִים וְזֶה נוֹתֵן שְׁלֹשָׁה טְפָחִים. בְּגָזִית זֶה נוֹתֵן טְפָחַיִם וּמֶחֱצָה וְזֶה נוֹתֵן טְפָחַיִם וּמֶחֱצָה. בִּכְפִיסִין זֶה נוֹתֵן טְפָחַיִם וְזֶה נוֹתֵן טְפָחַיִם. בִּלְבֵנִים זֶה נוֹתֵן טֶפַח וּמֶחֱצָה וְזֶה נוֹתֵן טֶפַח וּמֶחֱצָה. וְכָל הַשִּׁעוּרִין הָאֵלּוּ עֳבִי הַכֹּתֶל עִם הַסִּיד. וְהוֹאִיל וּמְקוֹם הַכֹּתֶל מִשֶּׁל שְׁנֵיהֶם אִם נָפַל הַכֹּתֶל הֲרֵי הַמָּקוֹם וְהָאֲבָנִים שֶׁל שְׁנֵיהֶם. וַאֲפִלּוּ נָפַל לִרְשׁוּת אֶחָד מֵהֶן אוֹ שֶׁפִּנָּה אֶחָד מֵהֶן אֶת כָּל הָאֲבָנִים לִרְשׁוּתוֹ וְטָעַן שֶׁמָּכַר לוֹ חֲבֵרוֹ חֶלְקוֹ אוֹ נְתָנוֹ לוֹ בְּמַתָּנָה אֵינוֹ נֶאֱמָן. אֶלָּא הֲרֵי הֵן בִּרְשׁוּת שֶׁל שְׁנֵיהֶם עַד שֶׁיָּבִיא רְאָיָה:"],"Mishneh Torah, Oaths 2":["אֶחָד הַנִּשְׁבָּע אֶחָד מֵאַרְבָּעָה מִינֵי שְׁבוּעוֹת אֵלּוּ מִפִּי עַצְמוֹ. וְאֶחָד הַמֻּשְׁבָּע מִפִּי אֲחֵרִים וְעָנָה אָמֵן. אֲפִלּוּ הִשְׁבִּיעוֹ עַכּוּ\"ם אוֹ קָטָן וְעָנָה אָמֵן חַיָּב. שֶׁכָּל הָעוֹנֶה אָמֵן אַחַר שְׁבוּעָה כְּמוֹצִיא שְׁבוּעָה מִפִּיו. וְאֶחָד הָעוֹנֶה אָמֵן אוֹ הָאוֹמֵר דָּבָר שֶׁעִנְיָנוֹ כְּעִנְיַן אָמֵן. כְּגוֹן שֶׁאָמַר הֵן אוֹ מְחֻיָּב אֲנִי בִּשְׁבוּעָה זוֹ. קִבַּלְתִּי עָלַי שְׁבוּעָה זוֹ. וְכָל כַּיּוֹצֵא בָּזֶה בְּכָל לָשׁוֹן הֲרֵי זֶה כְּנִשְׁבָּע לְכָל דָּבָר בֵּין לְחַיְּבוֹ מַלְקוֹת בֵּין לְחַיְּבוֹ קָרְבָּן:","אֶחָד הַנִּשְׁבָּע. אוֹ שֶׁהִשְׁבִּיעוֹ אַחֵר בַּשֵּׁם הַמְיֻחָד. אוֹ בְּאֶחָד מִן הַכִּנּוּיִין כְּגוֹן שֶׁנִּשְׁבַּע בְּמִי שֶׁשְּׁמוֹ חַנּוּן וּבְמִי שֶׁשְּׁמוֹ רַחוּם וּבְמִי שֶׁשְּׁמוֹ אֶרֶךְ אַפַּיִם. וְכַיּוֹצֵא בָּהֶן בְּכָל לָשׁוֹן הֲרֵי זוֹ שְׁבוּעָה גְּמוּרָה. וְכֵן אָלָה וְאָרוּר הֲרֵי הֵן שְׁבוּעָה. וְהוּא שֶׁיַּזְכִּיר שֵׁם מִן הַשֵּׁמוֹת אוֹ כִּנּוּי מִן הַכִּנּוּיִין. כֵּיצַד. כְּגוֹן שֶׁאָמַר בְּאָלָה אוֹ אָרוּר לַה'. אוֹ לְמִי שֶׁשְּׁמוֹ חַנּוּן. אוֹ לְמִי שֶׁשְּׁמוֹ רַחוּם. מִי שֶׁיֹּאכַל דָּבָר פְּלוֹנִי וַאֲכָלוֹ הֲרֵי זֶה נִשְׁבַּע לַשֶּׁקֶר. וְכֵן בִּשְׁאָר מִינֵי שְׁבוּעוֹת:","וְכֵן הָאוֹמֵר שְׁבוּעָה בַּה' אוֹ בְּמִי שֶׁשְּׁמוֹ חַנּוּן שֶׁלֹּא אֹכַל וְאָכַל. שֶׁזּוֹ אִשָּׁה וְהוּא אִישׁ. שֶׁאֵין לְךָ בְּיָדִי כְּלוּם וְיֵשׁ לוֹ. שֶׁאֵינִי יוֹדֵעַ לְךָ עֵדוּת וְהוּא יוֹדֵעַ. הֲרֵי זֶה חַיָּב:","אָמַר אָלָה אוֹ אָרוּר אוֹ שְׁבוּעָה וְלֹא הִזְכִּיר שֵׁם וְלֹא כִּנּוּי הֲרֵי זֶה אָסוּר בַּדָּבָר שֶׁנִּשְׁבַּע עָלָיו. אֲבָל אֵינוֹ לוֹקֶה וְלֹא מֵבִיא קָרְבָּן אִם עָבַר עַל שְׁבוּעָתוֹ עַד שֶׁיִּהְיֶה בָּהּ שֵׁם מִן הַשֵּׁמוֹת הַמְּיֻחָדִים אוֹ כִּנּוּי מִן הַכִּנּוּיִין כְּמוֹ שֶׁבֵּאַרְנוּ:","וְלֹא הַשְּׁבוּעָה בִּלְבַד אֶלָּא כָּל כִּנּוּיֵי שְׁבוּעָה כִּשְׁבוּעָה. כְּגוֹן שֶׁהָיוּ אַנְשֵׁי אוֹתוֹ מָקוֹם עִלְּגִים וְהָיוּ קוֹרְאִים לִשְׁבוּעָה שְׁבוּתָהּ אוֹ שְׁקוּקָה. אוֹ שֶׁהָיוּ אֲרַמִּיִּים שֶׁלְּשׁוֹן שְׁבוּעָה בִּלְשׁוֹנָם מוֹמְתָא. וְהָעִלְּגִים מְכַנִּין אוֹתָהּ וְאוֹמְרִים מוֹהָא. כֵּיוָן שֶׁאָמַר לָשׁוֹן שֶׁמַּשְׁמָעוֹ וְעִנְיָנוֹ שְׁבוּעָה הֲרֵי זֶה חַיָּב כְּמִי שֶׁהוֹצִיא לְשׁוֹן שְׁבוּעָה:","וְכֵן הָאוֹמֵר לָאו לָאו שְׁתֵּי פְּעָמִים דֶּרֶךְ שְׁבוּעָה אוֹ הֵן הֵן וְהִזְכִּיר שֵׁם אוֹ כִּנּוּי הֲרֵי זֶה כְּנִשְׁבָּע. וְכֵן יָמִין שְׁבוּעָה. וּשְׂמֹאל שְׁבוּעָה. שֶׁנֶּאֱמַר (ישעיה סב ח) \"נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ\". וְכֵן הָאוֹמֵר מִבְטָא שֶׁלֹּא אֶעֱשֶׂה כָּךְ וְכָךְ וְהִזְכִּיר שֵׁם אוֹ כִּנּוּי הֲרֵי זוֹ שְׁבוּעָה:","אָמַר אִסָּר לַה' אוֹ לְמִי שֶׁשְּׁמוֹ חַנּוּן שֶׁאֶעֱשֶׂה אוֹ שֶׁלֹּא אֶעֱשֶׂה הוֹאִיל וְהוֹצִיאוֹ בִּלְשׁוֹן שְׁבוּעָה הֲרֵי הִיא כִּשְׁבוּעָה:","שָׁמַע חֲבֵרוֹ נִשְׁבָּע וְאָמַר וַאֲנִי כְּמוֹתְךָ הוֹאִיל וְלֹא הוֹצִיא שְׁבוּעָה מִפִּיו וְלֹא הִשְׁבִּיעוֹ חֲבֵרוֹ הֲרֵי זֶה פָּטוּר. וְזֶהוּ מַתְפִּיס בִּשְׁבוּעָה שֶׁהוּא פָּטוּר:","וְכֵן אִם נִשְׁבַּע שֶׁלֹּא אֹכַל בָּשָׂר זֶה. וְחָזַר וְאָמַר וַהֲרֵי הַפַּת זוֹ כַּבָּשָׂר הַזֶּה הֲרֵי הוּא פָּטוּר עַל הַפַּת. שֶׁהֲרֵי לֹא הוֹצִיא שְׁבוּעָה מִפִּיו עָלֶיהָ אֶלָּא הִתְפִּיסָהּ. וְאַף עַל פִּי שֶׁהוּא פָּטוּר מִן הַמַּלְקוֹת אוֹ מִן הַקָּרְבָּן אָסוּר לוֹ לֶאֱכל אוֹתָהּ הַפַּת שֶׁהִתְפִּיס בִּשְׁבוּעָה:","מִי שֶׁנִּתְכַּוֵּן לִשְׁבוּעָה וְגָמַר בְּלִבּוֹ שֶׁלֹּא יֹאכַל הַיּוֹם אוֹ שֶׁלֹּא יִשְׁתֶּה וְשֶׁדָּבָר זֶה אָסוּר עָלָיו בִּשְׁבוּעָה וְלֹא הוֹצִיא בִשְׂפָתָיו הֲרֵי זֶה מֻתָּר שֶׁנֶּאֱמַר (ויקרא ה ד) \"לְבַטֵּא בִּשְׂפָתַיִם\". אֵין הַנִּשְׁבָּע חַיָּב עַד שֶׁיּוֹצִיא עִנְיַן שְׁבוּעָה בִּשְׂפָתָיו:","וְכֵן אִם גָּמַר בְּלִבּוֹ לְהִשָּׁבַע וְטָעָה וְהוֹצִיא בִּשְׂפָתָיו דָּבָר שֶׁלֹּא הָיָה בְּלִבּוֹ הֲרֵי זֶה מֻתָּר. כֵּיצַד. הַמִּתְכַּוִּן לְהִשָּׁבַע שֶׁלֹּא יֹאכַל אֵצֶל רְאוּבֵן וּכְשֶׁבָּא לְהוֹצִיא שְׁבוּעָה נִשְׁבַּע שֶׁלֹּא יֹאכַל אֵצֶל שִׁמְעוֹן. הֲרֵי זֶה מֻתָּר לֶאֱכל עִם רְאוּבֵן שֶׁהֲרֵי לֹא הוֹצִיאוֹ בִּשְׂפָתָיו. וְעִם שִׁמְעוֹן שֶׁהֲרֵי לֹא הָיָה שִׁמְעוֹן בְּלִבּוֹ:","וְכֵן שְׁאָר מִינֵי שְׁבוּעוֹת אֵינוֹ חַיָּב עַד שֶׁיִּהְיֶה פִּיו וְלִבּוֹ שָׁוִין. לְפִיכָךְ אִם נִשְׁבַּע אֶחָד בְּפָנֵינוּ שֶׁלֹּא יֹאכַל הַיּוֹם וְאָכַל. וְהִתְרוּ בּוֹ וְאָמַר אֲנִי לֹא הָיָה בְּלִבִּי אֶלָּא שֶׁלֹּא אֵצֵא הַיּוֹם וְטָעָה לְשׁוֹנִי וְהוֹצִיא אֲכִילָה שֶׁלֹּא הָיְתָה בְּלִבִּי הֲרֵי זֶה אֵינוֹ לוֹקֶה. עַד שֶׁיּוֹדֶה בִּפְנֵי עֵדִים קֹדֶם שֶׁיֹּאכַל שֶׁעַל אֲכִילָה נִשְׁבַּע. אוֹ שֶׁקִּבֵּל עָלָיו הַתְרָאָה וְלֹא טָעַן שֶׁטָּעָה בְּעֵת הַתְרָאָה אַף עַל פִּי שֶׁטָּעַן אַחַר כָּךְ אֵין שׁוֹמְעִין לוֹ. וְכֵן אִם הִתְרוּ בּוֹ וְאָמַר מֵעוֹלָם לֹא נִשְׁבַּעְתִּי אוֹ לֹא נָדַרְתִּי אֶלָּא עַל דָּבָר זֶה וְאַחַר שֶׁהֵעִידוּ עָלָיו שֶׁנִּשְׁבַּע אוֹ נָדַר אָמַר כֵּן הָיָה אֲבָל לֹא הָיָה פִּי וְלִבִּי שָׁוִין אוֹ תְּנַאי הָיָה בְּלִבִּי עַל הַנֵּדֶר אֵין שׁוֹמְעִין לוֹ וְלוֹקֶה:","כַּיּוֹצֵא בּוֹ אָמְרוּ לוֹ אִשְׁתְּךָ נָדְרָה. וְאָמַר בְּלִבִּי הָיָה לְהָפֵר לָהּ וְהֵפַרְתִּי שׁוֹמְעִין לוֹ. אָמְרוּ לוֹ נָדְרָה וְהוּא אוֹמֵר לֹא נָדְרָה וְכֵיוָן שֶׁרָאָה אוֹתָם הֵעִידוּ עָלָיו אָמַר בְּלִבִּי הָיָה לְהָפֵר אֵין שׁוֹמְעִין לוֹ:","גָּמַר בְּלִבּוֹ שֶׁלֹּא לֶאֱכל פַּת חִטִּין וְנִשְׁבַּע שֶׁלֹּא יֹאכַל פַּת סְתָם אָסוּר בְּפַת חִטִּים שֶׁפַּת חִטִּים פַּת שְׁמָהּ:","מִי שֶׁנִּשְׁבַּע וְאָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם וְעַל דַּעְתְּכֶם אֲנִי נִשְׁבָּע. אֵין זֶה יָכוֹל לוֹמַר כָּךְ וְכָךְ הָיָה בְּלִבִּי. שֶׁלֹּא נִשְׁבַּע זֶה עַל דַּעְתּוֹ אֶלָּא עַל דַּעַת אֲחֵרִים וְכֵיוָן שֶׁהָיָה פִּיו וְלִבָּם שֶׁל אֲחֵרִים שֶׁנִּשְׁבַּע עַל דַּעְתָּם שָׁוִים חַיָּב מִפְּנֵי שֶׁלִּבָּם שֶׁל אֵלּוּ בִּמְקוֹם לִבּוֹ קָם. וְכֵן בִּשְׁאָר מִינֵי שְׁבוּעוֹת:","לְפִיכָךְ כְּשֶׁמַּשְׁבִּיעִין הַדַּיָּנִין אֶת הַנִּשְׁבָּע אוֹמְרִים לוֹ לֹא עַל דַּעְתְּךָ אָנוּ מַשְׁבִּיעִים אוֹתְךָ אֶלָּא עַל דַּעְתֵּנוּ:","מִי שֶׁנִּשְׁבַּע וְהָיָה פִּיו וְלִבּוֹ שָׁוִין בִּשְׁבוּעָה. וְאַחַר שֶׁנֶּאֱסַר חָזַר בּוֹ מִיָּד בְּתוֹךְ כְּדֵי דִּבּוּר וְהוּא כְּדֵי שֶּׁיֹּאמַר תַּלְמִיד לְרַב שָׁלוֹם עָלֶיךָ רַבִּי. וְאָמַר אֵין זוֹ שְׁבוּעָה אוֹ נִחַמְתִּי אוֹ חָזַרְתִּי בִּי וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁעִנְיָנָם שֶׁהִתִּיר מַה שֶּׁאָסַר הֲרֵי זֶה מֻתָּר וְנֶעֶקְרָה הַשְּׁבוּעָה שֶׁזֶּה דּוֹמֶה לְטוֹעֶה:","וְכֵן אִם אָמְרוּ לוֹ אֲחֵרִים חֲזֹר בְּךָ אוֹ מֻתָּר לְךָ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ וְקִבֵּל מֵהֶן בְּתוֹךְ כְּדֵי דִּבּוּר וְאָמַר הֵן אוֹ חָזַרְתִּי בִּי וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה מֻתָּר. וְאִם אַחַר כְּדֵי דִּבּוּר אֵינוֹ יָכוֹל לַחְזֹר בּוֹ:","נִשְׁבַּע וְחָזַר בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר בְּלִבּוֹ אֵין זֶה כְּלוּם. וְכֵן אִם אָמְרוּ לוֹ אֲחֵרִים חֲזֹר בְּךָ אוֹ מֻתָּר לְךָ אוֹ מָחוּל לְךָ וְקִבֵּל דִּבְרֵיהֶם בְּלִבּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר אֵין זֶה כְּלוּם עַד שֶׁיּוֹצִיא הַחֲזָרָה בְּפִיו כְּמוֹ הַשְּׁבוּעָה:"],"Mishneh Torah, Offerings for Those with Incomplete Atonement 5":["אֵי זֶהוּ תְּנוּךְ אֹזֶן זֶה גָּדֵר הָאֶמְצָעִי. נָתַן עַל צִדֵּי הַבְּהוֹנוֹת כָּשֵׁר. נָתַן עַל צִדֵּי צִדֵּיהֶן פָּסוּל. בֵּין שֶׁנָּתַן הַשֶּׁמֶן עַל דַּם הָאָשָׁם עַצְמוֹ מִלְמַעְלָה בֵּין שֶׁנָּתַן בְּצַד הַדָּם אֲפִלּוּ נִתְקַנֵּחַ הַדָּם קֹדֶם שֶׁיִּתֵּן הַשֶּׁמֶן עַל בְּהוֹנוֹת יָצָא שֶׁנֶּאֱמַר (ויקרא יד כח) \"עַל מְקוֹם דַּם הָאָשָׁם\". אֵין לוֹ בֹּהֶן יַד יְמָנִית אוֹ בֹּהֶן רֶגֶל יְמָנִית אוֹ שֶׁאֵין לוֹ אֹזֶן יְמָנִית אֵין לוֹ טָהֳרָה עוֹלָמִית:","אֲשַׁם מְצֹרָע שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ אוֹ שֶׁלֹּא נָתַן מִדָּמוֹ עַל גַּבֵּי בְּהוֹנוֹת הֲרֵי זֶה עוֹלֶה לַמִּזְבֵּחַ וְטָעוּן נְסָכִים כְּנִסְכֵּי אֲשַׁם מְצֹרָע וְצָרִיךְ הַמְצֹרָע אָשָׁם אַחֵר לְהַכְשִׁירוֹ:","הִקְדִּים חַטָּאתוֹ לַאֲשָׁמוֹ לֹא יִהְיֶה אַחֵר מְמָרֵס בְּדָמָהּ אֶלָּא תְּעֵבַּר צוּרָתָהּ וְתֵצֵא לְבֵית הַשְּׂרֵפָה:","יֵשׁ לְאָדָם לְהָבִיא אֲשָׁמוֹ הַיּוֹם וְלוֹגוֹ אַחַר עֲשָׂרָה יָמִים. וְאִם רָצָה לְשַׁנּוֹת הַלּוֹג לַאֲשַׁם מְצֹרָע אַחֵר מְשַׁנֶּה אַף עַל פִּי שֶׁקָּדַשׁ בִּכְלִי. חָסַר הַלּוֹג עַד שֶׁלֹּא יָצַק יְמַלְּאֶנּוּ. חָסַר מֵאַחַר שֶׁיָּצַק יָבִיא אַחֵר בַּתְּחִלָּה:","יָצַק מִן הַשֶּׁמֶן לְכַפּוֹ וְהִתְחִיל לְהַזּוֹת וְנִשְׁפַּךְ הַלּוֹג אִם עַד שֶׁלֹּא גָּמַר מַתַּן שֶׁבַע נִשְׁפַּךְ הַלּוֹג יָבִיא אַחֵר וְיַתְחִיל בְּמַתַּן שֶׁבַע. גָּמַר מַתַּן שֶׁבַע וְנִשְׁפַּךְ הַלּוֹג יָבִיא אַחֵר וְיַתְחִיל לְכַתְּחִלָּה בַּבְּהוֹנוֹת. הִתְחִיל בַּבְּהוֹנוֹת וְנִשְׁפַּךְ הַלּוֹג קֹדֶם שֶׁיִּגְמֹר יָבִיא אַחֵר וְיַתְחִיל לְכַתְּחִלָּה בַּבְּהוֹנוֹת. גָּמַר הַבְּהוֹנוֹת וְאַחַר כָּךְ נִשְׁפַּךְ הַלּוֹג קֹדֶם שֶׁיִּתֵּן שְׁאָר הַשֶּׁמֶן שֶׁבְּכַפּוֹ עַל רֹאשׁ הַמִּטַּהֵר אֵינוֹ צָרִיךְ לְהָבִיא לוֹג אַחֵר שֶׁמַּתְּנַת הָרֹאשׁ אֵינָהּ מְעַכֶּבֶת שֶׁנֶּאֱמַר (ויקרא יד יח) \"וְהַנּוֹתָר בַּשֶּׁמֶן\" (ויקרא יד יז) \"וּמִיֶּתֶר הַשֶּׁמֶן\":","הִקְדִּים מַתַּן שֶׁמֶן לְמַתַּן דָּם יְמַלֵּא הַלּוֹג שֶׁמֶן וְיַחְזֹר וְיִתֵּן הַשֶּׁמֶן אַחַר הַדָּם. הִקְדִּים מַתַּן שֶׁמֶן עַל הַבְּהוֹנוֹת לְמַתַּן שֶׁבַע יְמַלֵּא הַלּוֹג וְיַחְזֹר וְיִתֵּן עַל הַבְּהוֹנוֹת אַחַר מַתַּן שֶׁבַע שֶׁנֶּאֱמַר (ויקרא יד ב) \"זֹאת תִּהְיֶה תּוֹרַת הַמְצֹרָע\" שֶׁתִּהְיֶה כָּל תּוֹרָתוֹ עַל הַסֵּדֶר:","נָתַן שֶׁבַע הַמַּתָּנוֹת שֶׁלֹּא לִשְׁמָן לֹא הֻרְצָה וְהֻכְשַׁר הַמְצֹרָע:","מְצֹרָע שֶׁנִּתְנַגֵּעַ אַחַר שֶׁהֵבִיא אֲשָׁמוֹ צָרִיךְ קָרְבָּן אַחֵר לְצָרַעַת שְׁנִיָּה. וְכֵן אִם הֵבִיא אֲשָׁמוֹ וְנִתְנַגֵּעַ צָרִיךְ קָרְבָּן עַל כָּל אַחַת וְאַחַת. אֲבָל אִם נִתְנַגֵּעַ וְנִרְפָּא וְהֵבִיא צִפֳּרָיו וְחָזַר וְנִתְנַגֵּעַ וְנִתְרַפֵּא וְהֵבִיא צִפֳּרָיו קָרְבָּן אֶחָד לְכֻלָּן:","מְצֹרָע שֶׁהֵבִיא קָרְבַּן עָנִי וְהֶעֱשִׁיר אוֹ עָשִׁיר וְהֶעֱנִי קֹדֶם שֶׁיַּקְרִיב קָרְבְּנוֹתָיו הַכּל הוֹלֵךְ אַחַר הָאָשָׁם. אִם הָיָה בִּשְׁעַת שְׁחִיטַת הָאָשָׁם עָשִׁיר יְשַׁלֵּם קָרְבַּן עָשִׁיר וְאִם הָיָה עָנִי יְשַׁלֵּם קָרְבַּן עָנִי:","שְׁנֵי מְצֹרָעִים שֶׁנִּתְעָרְבוּ קָרְבְּנוֹתֵיהֶן וְנִזְרַק דַּם אַחַת מִשְּׁתֵי הַחַטָּאוֹת שֶׁלָּהֶן וְאַחַר כָּךְ מֵת אֶחָד מִן הַמְצֹרָעִים כֵּיצַד עוֹשֶׂה זֶה הַמְצֹרָע הַחַי. לְהָבִיא חַטַּאת בְּהֵמָה אֵינוֹ יָכוֹל שֶׁמָּא זוֹ שֶׁנִּזְרַק דָּמָהּ חַטָּאתוֹ הִיא וְאֵין מְבִיאִין חַטַּאת בְּהֵמָה עַל הַסָּפֵק. וּלְהָבִיא חַטַּאת הָעוֹף אֵינוֹ יָכוֹל שֶׁעָשִׁיר שֶׁהֵבִיא קָרְבַּן עָנִי לֹא יָצָא. וְכֵיצַד יַעֲשֶׂה. יִכְתֹּב כָּל נְכָסָיו לְאַחֵר וְנִמְצָא עָנִי וְיָבִיא חַטַּאת הָעוֹף מִסָּפֵק וְלֹא תֵּאָכֵל כְּמוֹ שֶׁבֵּאַרְנוּ וְנִמְצָא אוֹכֵל בְּקָדָשִׁים:","עָשִׁיר שֶׁאָמַר קָרְבָּנוֹ שֶׁל מְצֹרָע זֶה עָלָיו וְהַמְצֹרָע הָיָה עָנִי הֲרֵי זֶה מֵבִיא עַל יָדוֹ קָרְבְּנוֹת עָשִׁיר שֶׁהֲרֵי יַד הַנּוֹדֵר מַשֶּׂגֶת. וְעָנִי שֶׁאָמַר קָרְבָּנוֹ שֶׁל מְצֹרָע זֶה עָלַי וְהָיָה הַמְצֹרָע עָשִׁיר הֲרֵי זֶה מֵבִיא עַל יָדוֹ קָרְבְּנוֹת עָשִׁיר שֶׁהֲרֵי זֶה הַנּוֹדֵר חַיָּב בְּקָרְבְּנוֹת עָשִׁיר:"],"Mishneh Torah, Offerings for Unintentional Transgressions 6":["דִין שִׁגְגַת הַמַּאֲכָלוֹת כְּדִין שִׁגְגַת הַבְּעִילוֹת. לְפִיכָךְ אִם אָכַל אֲכִילוֹת הַרְבֵּה מִשֵּׁם אֶחָד בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶן יָמִים רַבִּים אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. כֵּיצַד. אָכַל חֵלֶב הַיּוֹם וְאָכַל חֵלֶב לְמָחָר וְחֵלֶב לְמָחָר בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁהֵן בִּשְׁלֹשָׁה תַּמְחוּיִין אֵינוֹ חַיָּב אֶלָּא אַחַת. אֲבָל אִם אָכַל כְּזַיִת חֵלֶב וְנוֹדַע לוֹ וְחָזַר וְאָכַל כְּזַיִת חֵלֶב וְנוֹדַע לוֹ. חַיָּב עַל כָּל אֲכִילָה וַאֲכִילָה שֶׁהַיְדִיעוֹת מְחַלְּקוֹת הַשְּׁגָגוֹת. אָכַל כַּחֲצִי זַיִת חֵלֶב וְחָזַר וְאָכַל כַּחֲצִי זַיִת חֵלֶב בְּהֶעְלֵם אַחַת אַף עַל פִּי שֶׁהֵן שֵׁנִי תַּמְחוּיִין וְאַף עַל פִּי שֶׁהִפְסִיק בֵּינֵיהֶן הֲרֵי אֵלּוּ מִצְטָרְפִין וּמֵבִיא חַטָּאת. שֶׁאֵין הַתַּמְחוּיִין מְחַלְּקִין. וְהוּא שֶׁלֹּא יִשְׁהֶה בֵּינֵיהֶן יוֹתֵר מִכְּדֵי אֲכִילַת שָׁלֹשׁ בֵּיצִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת. שֶׁכְּשֵׁם שֶׁמִּצְטָרֵף הַשִּׁעוּר לְמֵזִיד לְמַלְקוֹת כָּךְ מִצְטָרֵף הַשִּׁעוּר לְשׁוֹגֵג לְקָרְבָּן:","אָכַל נוֹתָר מֵחֲמִשָּׁה זְבָחִים כְּזַיִת מִכָּל זֶבַח בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁאֲכָלָן בַּחֲמִשָּׁה תַּמְחוּיִין אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת שֶׁכֻּלָּן שֵׁם אֶחָד הֵן וְהַתַּמְחוּיִין אֵינָן מְחַלְּקִין. וְגוּפֵי הַזְּבָחִים אֵינָן מְחַלְּקִין. שֶׁאֶחָד הָאוֹכֵל בָּשָׂר מִזְּבָחִים רַבִּים אוֹ מִזֶּבַח אֶחָד. וְכֵן הַשּׁוֹחֵט חֲמִשָּׁה זְבָחִים בַּחוּץ בְּהֶעְלֵם אַחַת. אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. הָא לְמָה זֶה דּוֹמֶה לְמִשְׁתַּחֲוֶה לְחָמֵשׁ צוּרוֹת בְּהֶעְלֵם אַחַת:","הִקִּיז דָּם לִבְהֶמְתּוֹ וְקִבְּלוֹ בִּשְׁנֵי כּוֹסוֹת וּשְׁתָאָן בְּהֶעְלֵם אַחַת אֵינוֹ מֵבִיא אֶלָּא חַטָּאת אַחַת:","הָאוֹכֵל מַאֲכָלוֹת הַרְבֵּה מִשֵּׁמוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת חַיָּב עַל כָּל שֵׁם וְשֵׁם. כֵּיצַד. כְּגוֹן שֶׁאָכַל חֵלֶב וְדָם וְנוֹתָר וּפִגּוּל כְּזַיִת מִכָּל אֶחָד וְאֶחָד בְּהֶעְלֵם אַחַת מֵבִיא אַרְבַּע חַטָּאוֹת. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. וְכֵן הָאוֹכֵל כְּזַיִת אֶחָד שֶׁנִּתְקַבְּצוּ בּוֹ שֵׁמוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת. אִם נִתְקַבְּצוּ בְּאִסּוּר מוֹסִיף אוֹ בְּאִסּוּר כּוֹלֵל אוֹ בְּאִסּוּר בַּת אַחַת חַיָּב עַל כָּל שֵׁם וְשֵׁם. לְפִיכָךְ הַטָּמֵא שֶׁאָכַל כְּזַיִת חֵלֶב וְנוֹתָר בְּיוֹם הַכִּפּוּרִים. מֵבִיא אַרְבַּע חַטָּאוֹת וְאָשָׁם. חַטָּאת אַחַת מִשּׁוּם טָמֵא שֶׁאָכַל קוֹדֶשׁ. וְאַחַת מִשּׁוּם אוֹכֵל חֵלֶב. וְאַחַת מִשּׁוּם אוֹכֵל נוֹתָר. וְאַחַת מִשּׁוּם יוֹם הַכִּפּוּרִים. וְהוּא שֶׁיִּצְטָרֵף אֹכֶל אַחֵר עִם כְּזַיִת זֶה עַד שֶׁיַּשְׁלִימוֹ לִכְכוֹתֶבֶת. וּמֵבִיא אָשָׁם וַדַּאי לִמְעִילָה שֶׁהֲרֵי נֶהֱנָה מִן הַהֶקְדֵּשׁ בִּשְׁגָגָה:","הָאוֹכֵל וְשׁוֹתֶה בְּיוֹם הַכִּפּוּרִים בְּהֶעְלֵם אַחַת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. אֲכִילָה וּשְׁתִיָּה אַחַת הִיא:","הָעוֹשֶׂה מְלָאכָה בְּיוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת בְּשַׁבָּת חַיָּב שְׁתֵּי חַטָּאוֹת מִפְּנֵי שֶׁהֵן שְׁנֵי אִסּוּרִין הַבָּאִין כְּאֶחָד:","אָכַל כַּחֲצִי זַיִת חֵלֶב וְכַחֲצִי זַיִת דָּם בְּהֶעְלֵם אַחַת אֵינוֹ חַיָּב קָרְבָּן. כְּשֵׁם שֶׁאֵין הָאִסּוּרִין מִצְטָרְפִין לַמַּלְקוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת כָּךְ אֵין מִצְטָרְפִין לְקָרְבָּן:","אָכַל כַּחֲצִי זַיִת וְנוֹדַע לוֹ וְחָזַר וְשָׁכַח וְאָכַל כַּחֲצִי זַיִת אַחֵר בְּהֶעְלֵם שֵׁנִי פָּטוּר. שֶׁהֲרֵי נוֹדַע לוֹ בֵּינְתַיִם וְיֵשׁ יְדִיעָה לַחֲצִי שִׁעוּר. וְכֵן אִם כָּתַב אוֹת אַחַת [בְּשַׁבָּת] בִּשְׁגָגָה וְנוֹדַע לוֹ וְחָזַר וְשָׁכַח וְכָתַב אוֹת שְׁנִיָּה סְמוּכָה לָהּ בְּהֶעְלֵם שֵׁנִי פָּטוּר מִקָּרְבַּן חַטָּאת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן אִם הוֹצִיא שְׁתֵּי אַמּוֹת בְּשׁוֹגֵג וּשְׁתֵּי אַמּוֹת בְּמֵזִיד וּשְׁתֵּי אַמּוֹת בְּשׁוֹגֵג. אִם בִּזְרִיקָה חַיָּב. לֹא מִפְּנֵי שֶׁאֵין יְדִיעָה לַחֲצִי שִׁעוּר אֶלָּא מִפְּנֵי שֶׁאֵין בְּיָדוֹ לְהַחְזִירָהּ. לְפִיכָךְ לֹא הוֹעִילָה לוֹ הַיְדִיעָה שֶׁבֵּינְתַיִם. וְאִם בְּהַעֲבָרָה פָּטוּר שֶׁיֵּשׁ יְדִיעָה לַחֲצִי שִׁעוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹכֵל כְּזַיִת חֵלֶב וּכְזַיִת חֵלֶב בְּהֶעְלֵם אַחַת וְנוֹדַע לוֹ עַל הָרִאשׁוֹן וְחָזַר וְנוֹדַע לוֹ עַל הַשֵּׁנִי מֵבִיא שְׁתֵּי חַטָּאוֹת שֶׁהַיְדִיעוֹת מְחַלְּקוֹת וְאַף עַל פִּי שֶׁעֲדַיִן לֹא הִפְרִישׁ הַקָּרְבָּן. אֲבָל אִם נוֹדַע לוֹ עַל שְׁנֵיהֶן כְּאַחַת מֵבִיא חַטָּאת אַחַת. וְכֵן יֵרָאֶה לִי שֶׁהוּא הַדִּין בִּבְעִילוֹת:","אָכַל כְּזַיִת וּמֶחֱצָה בְּהֶעְלֵם אַחַת וְנוֹדַע לוֹ עַל כְּזַיִת וְחָזַר וְאָכַל חֲצִי זַיִת בְּהֵעָלְמוֹ שֶׁל שֵׁנִי. אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. שֶׁאֵין חֲצִי זַיִת הָאַחֲרוֹן מִצְטָרֵף לָרִאשׁוֹן אַף עַל פִּי שֶׁהוּא בְּהֵעָלְמוֹ שֶׁהֲרֵי נוֹדַע לוֹ עַל מִקְצָת הַעֲלָמָה רִאשׁוֹנָה:","אָכַל שְׁנֵי זֵיתֵי חֵלֶב בְּהֶעְלֵם אַחַת וְנוֹדַע לוֹ עַל אַחַת מֵהֶן וְחָזַר וְאָכַל כְּזַיִת אַחֵר בְּהֵעָלְמוֹ שֶׁל שֵׁנִי וְהֵבִיא חַטָּאת עַל הָרִאשׁוֹן. רִאשׁוֹן וְשֵׁנִי מִתְכַּפְּרִין אֲבָל שְׁלִישִׁי לֹא נִתְכַּפֵּר. אֶלָּא כְּשֶׁיִּוָּדַע לוֹ עָלָיו יָבִיא חַטָּאת אַחֶרֶת. הֵבִיא חַטָּאת עַל הַשְּׁלִישִׁי. שְׁלִישִׁי וְשֵׁנִי מִתְכַּפְּרִין שֶׁשְּׁנֵיהֶם בְּהֶעְלֵם אַחַת. וְרִאשׁוֹן לֹא נִתְכַּפֵּר בְּחַטָּאת זוֹ. הֵבִיא חַטָּאת עַל הָאֶמְצָעִי. שְׁלָשְׁתָּן מִתְכַּפְּרִין. מִפְּנֵי שֶׁהָרִאשׁוֹן וְהַשְּׁלִישִׁי בְּהֵעָלְמוֹ שֶׁל אֶמְצָעִי. וּכְשֶׁיִּוָּדַע לּוֹ עַל הָרִאשׁוֹן וְעַל הַשְּׁלִישִׁי אֵין צָרִיךְ לְהָבִיא חַטָּאת אַחֶרֶת:","מִי שֶׁאָכַל חֲתִיכָה מִשְּׁתֵי חֲתִיכוֹת וְנִסְתַּפֵּק לוֹ אִם אָכַל חֵלֶב אוֹ שֻׁמָּן וְאָכַל חֲתִיכָה אַחֶרֶת מִשְּׁתֵי חֲתִיכוֹת וְנִסְתַּפֵּק לוֹ אִם אָכַל חֵלֶב אוֹ שֻׁמָּן וְאַחַר כָּךְ נוֹדַע לוֹ בְּוַדַּאי שֶׁחֵלֶב אָכַל בָּרִאשׁוֹנָה וּבַשְּׁנִיָּה. אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. שֶׁיְּדִיעַת סָפֵק שֶׁהָיְתָה לוֹ בֵּינְתַיִם אַף עַל פִּי שֶׁמְּחַלֶּקֶת לַאֲשָׁמוֹת אֵינָהּ מְחַלֶּקֶת לְחַטָּאוֹת:"],"Mishneh Torah, Other Sources of Defilement 1":["הַנְּבֵלָה אָב מֵאֲבוֹת הַטֻּמְאוֹת. כְּזַיִת מִבְּשָׂרָהּ מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בַּאֲוִיר. וּמְטַמֵּא אֶת הָאָדָם בְּמַשָּׂא לְטַמֵּא בְּגָדִים כְּמֶרְכַּב הַזָּב. כֵּיצַד. אָדָם שֶׁנָּגַע בִּנְבֵלָה נִטְמָא וַהֲרֵי הוּא רִאשׁוֹן לְטֻמְאָה. וְאִם נָגַע בְּכֵלִים אֲפִלּוּ בִּשְׁעַת מַגָּעוֹ בִּנְבֵלָה הֲרֵי הֵן טְהוֹרִין. וְכֵן כֵּלִים שֶׁעָלָיו טְהוֹרִין לְפִי [שֶׁהוּא] וָלָד וְאֵין וָלָד מְטַמֵּא כֵּלִים. אֲבָל הַנּוֹשֵׂא אֶת הַנְּבֵלָה מְטַמֵּא כֵּלִים בִּשְׁעַת נְשִׂיאָתוֹ שֶׁנֶּאֱמַר (ויקרא יא כח) \"וְהַנּשֵֹׁא אֶת נִבְלָתָם יְכַבֵּס בְּגָדָיו\". וְאוֹתָן הַבְּגָדִים רִאשׁוֹן לְטֻמְאָה. וְאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כְּלֵי חֶרֶס וַאֲפִלּוּ בִּשְׁעַת נְשִׂיאָתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְטַמְּאֵי מִשְׁכָּב וּמוֹשָׁב:","אֶחָד בְּהֵמָה וְחַיָּה בֵּין הַמֻּתָּרִין בַּאֲכִילָה בֵּין הָאֲסוּרִין אִם מֵתוּ כֻּלָּן בְּשָׂרָן מְטַמֵּא בִּכְזַיִת. וּשְׁחִיטַת בְּהֵמָה טְהוֹרָה וְחַיָּה טְהוֹרָה מְטַהַרְתּוֹ בְּכָל מָקוֹם. וַאֲפִלּוּ שָׁחַט חֻלִּין בַּעֲזָרָה וְקָדָשִׁים בַּחוּץ הֲרֵי אֵלּוּ טְהוֹרִין. וְאִם אֵרַע פִּסּוּל בַּשְּׁחִיטָה הֲרֵי זוֹ נְבֵלָה וּמְטַמְּאָה בְּמַשָּׂא כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שְׁחִיטָה:","בְּהֵמָה טְמֵאָה וְחַיָּה טְמֵאָה אֵין הַשְּׁחִיטָה מוֹעֶלֶת בָּהּ וְאֶחָד הַשּׁוֹחֲטָהּ אוֹ הַנּוֹחֲרָהּ אוֹ הַחוֹנְקָהּ אוֹ שֶׁמֵּתָה כְּדַרְכָּהּ הֲרֵי זוֹ נְבֵלָה. וְכָל הַנְּבֵלוֹת מִצְטָרְפוֹת לְעִנְיַן טֻמְאָה לִכְזַיִת אֶחָד טְמֵאוֹת וְאֶחָד טְהוֹרוֹת:","מֹחַ הֲרֵי הוּא כְּבָשָׂר. וְדַם הַנְּבֵלָה אֵינוֹ מְטַמֵּא כִּנְבֵלָה אֶלָּא הֲרֵי הוּא כְּמַשְׁקִין טְמֵאִים שֶׁאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כֵּלִים מִן הַתּוֹרָה:","חֵלֶב בְּהֵמָה טְהוֹרָה שֶׁמֵּתָה טָהוֹר. שֶׁנֶּאֱמַר (ויקרא ז כד) \"וְחֵלֶב נְבֵלָה וְחֵלֶב טְרֵפָה יֵעָשֶׂה לְכָל מְלָאכָה וְאָכל לֹא תֹאכְלֻהוּ\" מִי שֶׁאִסּוּרוֹ מִשּׁוּם נְבֵלָה וּטְרֵפָה. וְאִם הֻכְשַׁר בְּמַשְׁקִין הַמַּכְשִׁירִין הֲרֵי הוּא כָּאֳכָלִין טְמֵאִין וְאֵינוֹ כִּבְשַׂר נְבֵלָה. וְהַנּוֹגֵעַ בַּחֵלֶב הַחוֹפֶה אֶת הַכֻּלְיָא קֹדֶם הַפְרָשָׁה הֲרֵי זֶה טָמֵא כְּנוֹגֵעַ בַּכֻּלְיָא עַצְמָהּ שֶׁהֲרֵי כַּמָּה חוּטִין נִמְשָׁכִין מִמֶּנָּה בַּחֵלֶב. אֲבָל בְּהֵמָה טְמֵאָה וְהַחַיָּה בֵּין טְהוֹרָה בֵּין טְמֵאָה אֶחָד בְּשָׂרָהּ וְאֶחָד חֶלְבָּהּ לְטֻמְאָה. וּמְטַמֵּא אָדָם וְכֵלִים בִּכְזַיִת כִּבְשַׂר הַנְּבֵלָה:","הַכְּוִי חֶלְבּוֹ מְטַמֵּא כִּבְשָׂרוֹ וְטֻמְאָתוֹ בְּסָפֵק. לְפִיכָךְ אֵין שׂוֹרְפִין עָלָיו תְּרוּמָה וְקָדָשִׁים וְאֵין חַיָּבִין כָּרֵת עַל טֻמְאָתוֹ וְעַל בִּיאַת הַמִּקְדָּשׁ אוֹ עַל אֲכִילַת קָדָשָׁיו:","וְאֵלּוּ דְּבָרִים שֶׁאֵין מְטַמְּאִין מִן הַנְּבֵלוֹת. הָעֲצָמוֹת וְהַקַּרְנַיִם וְהַטְּלָפַיִם אֲפִלּוּ עִקָּרָן הָרַךְ שֶׁאִם יַחְתֹּךְ מִן הַחַי יוֹצֵא דָּם. וְהָעוֹר אַף עַל פִּי שֶׁאֵינוֹ מְעֻבָּד. וְהָאָלָל וְהַגִּידִים וְהַמָּרָק וְהַתַּבְלִין שֶׁמִּתְבַּשְּׁלִין עִמָּהּ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁפֵּרְשׁוּ מִן הַנְּבֵלָה. אֲבָל הַנּוֹגֵעַ בְּאֶחָד מִכָּל אֵלּוּ כְּשֶׁהֵן מְחֻבָּרִין בַּבָּשָׂר הֲרֵי זֶה טָמֵא. וְהוּא שֶׁיִּהְיֶה בַּבָּשָׂר כְּזַיִת. שֶׁאֵין אֶחָד מִכָּל אֵלּוּ מִצְטָרֵף לִכְזַיִת:","הָאָלָל בֵּין שֶׁפְּלָטַתּוּ חַיָּה בֵּין שֶׁפְּלָטַתּוּ סַכִּין אֵינוֹ מִצְטָרֵף לִכְזַיִת. וְאִם כְּנָסוֹ וְהָיָה בּוֹ כְּזַיִת מְטַמֵּא:","וְאֵלּוּ בְּהֵמוֹת שֶׁעוֹרוֹתֵיהֶם כִּבְשָׂרָם. עוֹר חֲזִיר שֶׁל יִשּׁוּב וְעוֹר חֲטוֹטֶרֶת הַגָּמָל הָרַכָּה וְעוֹר בֵּית הַבֹּשֶׁת וְעוֹר הַשְּׁלִיל וְעוֹר שֶׁתַּחַת הָאַלְיָה. הֲרֵי אֵלּוּ מְטַמְּאִין מִן הַנְּבֵלָה. וְאִם עִבְּדָן אוֹ הָלַךְ בָּהֶן כְּדֵי עֲבוֹדָה הֲרֵי אֵלּוּ טְהוֹרִים. וְאִם עָשָׂה בָּהֶן מַעֲשֶׂה שֶׁבִּטְּלָן טְהוֹרִין אַף עַל פִּי שֶׁלֹּא הָלַךְ בָּהֶן כְּדֵי עֲבוֹדָה. כֵּיצַד. אֹזֶן חֲמוֹר שֶׁטְּלָאָהּ לִכְפִיפָתוֹ טְהוֹרָה. כַּמָּה הוּא כְּדֵי עֲבוֹדָה אַרְבָּעָה מִילִין. וְאֵי זוֹ הִיא חֲטוֹטֶרֶת רַכָּה כָּל זְמַן שֶׁלֹּא טָעֲנָה. הִגִּיעַ זְמַנָּהּ לִטְעֹן וְלֹא טָעֲנָה אוֹ שֶׁטָּעֲנָה קדֶם שֶׁיַּגִּיעַ זְמַנָּהּ הֲרֵי זֶה סָפֵק:","הַמַּפְשִׁיט נִבְלַת בְּהֵמָה אוֹ חַיָּה בֵּין טְמֵאָה בֵּין טְהוֹרָה בֵּין דַּקָּה בֵּין גַּסָּה. אִם לִשְׁטִיחָה הִפְשִׁיט כֵּיוָן שֶׁהִפְשִׁיט מִן הָעוֹר כְּדֵי אֲחִיזָה וְהוּא שְׁנֵי טְפָחִים הַנּוֹגֵעַ בְּעוֹר זֶה שֶׁהֻפְשַׁט טָהוֹר. וְעַד שֶׁלֹּא הִפְשִׁיט שְׁנֵי טְפָחִים הַנּוֹגֵעַ בָּעוֹר כְּנוֹגֵעַ בַּבָּשָׂר. הִפְשִׁיטָהּ כְּדֵי לַעֲשׂוֹת מִן הָעוֹר חֵמֶת הֲרֵי הָעוֹר חִבּוּר עַד שֶׁיַּפְשִׁיט אֶת כָּל הֶחָזֶה. וְאִם הִפְשִׁיטָהּ מֵרַגְלֶיהָ בִּלְבַד הֲרֵי הָעוֹר כֻּלּוֹ חִבּוּר וְהַנּוֹגֵעַ בָּעוֹר כְּנוֹגֵעַ בַּבָּשָׂר עַד שֶׁיַּפְרִישׁ הָעוֹר כֻּלּוֹ מֵעַל הַבָּשָׂר. וְכֵן הַמַּפְשִׁיט בִּשְׁרָצִים חִבּוּר עַד שֶׁיַּפְשִׁיט כֻּלּוֹ. עוֹר שֶׁעַל הַצַּוָּאר חִבּוּר עַד שֶׁיַּפְשִׁיט כֻּלּוֹ. וְכָל עוֹר שֶׁהוּא חִבּוּר לְטַמֵּא כָּךְ הוּא חִבּוּר לְהִתְטַמֵּא. שֶׁאִם הָיְתָה שְׁחוּטָה וְנָגְעָה טֻמְאָה בְּעוֹר זֶה שֶׁהוּא חִבּוּר נִטְמָא הַבָּשָׂר:","עוֹר שֶׁיֵּשׁ עָלָיו כְּזַיִת נְבֵלָה הַנּוֹגֵעַ בַּצִּיב הַיּוֹצֵא מִמֶּנּוּ וּבִשְׂעָרוֹ שֶׁכְּנֶגְדוֹ מֵאֲחוֹרֵי הָעוֹר נִטְמָא מִפְּנֵי שֶׁהָעוֹר בִּשְׂעָרוֹ שׁוֹמֵר לַבָּשָׂר. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁפְּלָטַתּוּ חַיָּה. אֲבָל פְּלָטַתּוּ סַכִּין אִם הָיָה מְרֻדָּד בָּטֵל אַגַּב הָעוֹר:","עוֹר שֶׁיֵּשׁ עָלָיו כִּשְׁנֵי חֲצָאֵי זֵיתִים בְּשַׂר נְבֵלָה הָעוֹר מְבַטְּלָן וְאֵינָן מְטַמְּאִין לֹא בְּמַגָּע וְלֹא בְּמַשָּׂא. שֶׁכָּל שֶׁאֵינוֹ מְטַמֵּא מִן הַנְּבֵלָה בְּמַגָּע אֵינוֹ מְטַמֵּא בְּמַשָּׂא. אֲבָל שְׁנֵי חֲצָאֵי זֵיתִים שֶׁתְּחָבָן בְּקֵיסָם הַנּוֹשְׂאָן טָמֵא שֶׁהֲרֵי נָשָׂא כְּזַיִת וְהַנּוֹגֵעַ טָהוֹר שֶׁאֵין חִבּוּרֵי אָדָם חִבּוּר וְהוּא שֶׁיִּהְיוּ שְׁנֵיהֶן מְרֻדָּדִין וּדְבוּקִין זֶה בָּזֶה עַד שֶׁיִּנָּטְלוּ כְּאֶחָד. אֲבָל אִם הָיָה חֲצִי זַיִת זֶה בִּפְנֵי עַצְמוֹ וְזֶה בִּפְנֵי עַצְמוֹ בְּקֵיסָם אֶחָד אֲפִלּוּ הוֹלִיךְ וְהֵבִיא כָּל הַיּוֹם כֻּלּוֹ טָהוֹר:","בְּשַׂר נְבֵלָה שֶׁנִּפְסַד וְהִבְאִישׁ וְנִפְסַל מִלֶּאֱכל הַכֶּלֶב טָהוֹר. לְפִיכָךְ נֶצֶל הַנְּבֵלָה סָפֵק אִם מְטַמֵּא בִּכְזַיִת אִם לֹא. בְּשַׂר נְבֵלָה שֶׁיָּבַשׁ אִם יָכוֹל לִשְׁרוֹת בְּפוֹשְׁרִין מֵעֵת לְעֵת וְלַחֲזֹר לַח וְרָאוּי לַכֶּלֶב מְטַמֵּא וְאִם לָאו טָהוֹר וַאֲפִלּוּ כָּאֳכָלִין טְמֵאִין אֵינוֹ מִטַּמֵא:","בְּשַׂר נְבֵלָה שֶׁהָיָה סָרוּחַ מֵעִקָּרוֹ וְאֵינוֹ רָאוּי לְמַאֲכַל אָדָם הֲרֵי זֶה טָהוֹר שֶׁנֶּאֱמַר (דברים יד כא) \"לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנֶנָּה וַאֲכָלָהּ\" עַד שֶׁתִּהְיֶה תְּחִלָּתָהּ רְאוּיָה לְגֵר:","שִׁלְיָא שֶׁל נְבֵלָה הֲרֵי הִיא כְּפֶרֶשׁ וּכְרֶעִי וְאֵינָהּ מְטַמְּאָה כִּנְבֵלָה. וְאִם חָשַׁב עָלֶיהָ לַאֲכִילָה מִתְטַמֵּא טֻמְאַת אֳכָלִין. הַקֵּבָה וְהֶחָלָב שֶׁל נְבֵלָה טְהוֹרִין מִכְּלוּם:","בְּהֵמָה שֶׁשָּׁפְעָה חֲרָרַת דָּם אַף עַל פִּי שֶׁנִּפְטְרָה מִן הַבְּכוֹרָה אֵינָהּ מְטַמְּאָה לֹא בְּמַגָּע וְלֹא בְּמַשָּׂא עַד שֶׁיִּהְיֶה בָּהּ צוּרַת נֵפֶל לְפִי שֶׁהִיא בְּטֵלָה בָּרֹב הַיּוֹצֵא עִמָּהּ. לְפִיכָךְ הִיא טְהוֹרָה אַף עַל פִּי שֶׁהָיְתָה רְאוּיָה לַגֵּר אַגַּב אִמָּהּ:","נְבֵלָה שֶׁנִּתְעָרְבָה בִּשְׁחוּטָה אִם רֹב מִן הַשְּׁחוּטָה בְּטֵלָה הַנְּבֵלָה בַּשְּׁחוּטָה וְאֵין הַכּל מְטַמֵּא בְּמַגָּע. אֲבָל אִם נָשָׂא הַכּל נִטְמָא שֶׁאִי אֶפְשָׁר לִשְׁחוּטָה שֶׁתַּחְזֹר נְבֵלָה אֲבָל הַנְּבֵלָה אֶפְשָׁר שֶׁתִּטְהַר כְּשֶׁתִּסְרַח לְפִיכָךְ תִּבָּטֵל:"],"Mishneh Torah, Other Sources of Defilement 20":["כָּל מָקוֹם שֶׁהוּא רְשׁוּת הָרַבִּים לְעִנְיַן שַׁבָּת כָּךְ הוּא רְשׁוּת הָרַבִּים לְעִנְיַן טֻמְאָה:","אַרְבַּע אַמּוֹת הַסְּמוּכוֹת לִרְשׁוּת הָרַבִּים הֲרֵי הֵן כִּרְשׁוּת הָרַבִּים לְטֻמְאָה. וְכֵן הַכַּרְמְלִית כְּגוֹן הַיָּם וְהַאִצְטְוַונִית הֲרֵי הֵן כִּרְשׁוּת הָרַבִּים לְטֻמְאָה:","יֵשׁ שָׁם מְקוֹמוֹת שֶׁאַף עַל פִּי שֶׁהֵן רְשׁוּת הַיָּחִיד לְשַׁבָּת הֲרֵי הֵן כִּרְשׁוּת הָרַבִּים לְעִנְיַן טֻמְאָה וְאֵלּוּ הֵן. הַשְּׁבִילִין הַמְפֻלָּשִׁין לְשִׁיחִין וּלְבוֹרוֹת וּלְגִתּוֹת וְהַבִּקְעָה הַמֻּקֶּפֶת גָּדֵר בִּימוֹת הַחַמָּה וּבַסִילְקִי מְלָכִים שֶׁהוּא בִּנְיָן רָחָב הַרְבֵּה לַעֲמֹד בּוֹ אַנְשֵׁי הַמֶּרְכָּבָה וְיֵשׁ לוֹ פְּתָחִים הַרְבֵּה פְּתוּחִים לִרְשׁוּת הָרַבִּים וְהַפּוֹרָן וְהוּא הַבִּנְיָן הַגָּדוֹל שֶׁיֵּשׁ לוֹ שְׁנֵי פְּתָחִים זֶה כְּנֶגֶד זֶה וְחָצֵר שֶׁהָרַבִּים נִכְנָסִין בְּפֶתַח זֶה וְיוֹצְאִין בְּפֶתַח אַחֵר. וְכֵן מְבוֹאוֹת הַיּוֹרְדִים לַיָּם אוֹ לַנָּהָר אַף עַל פִּי שֶׁהֵן גְּדוּרִין מִכָּאן וּמִכָּאן וְרַבִּים מְטַפְּסִין וְעוֹלִין בָּהֶן וְהַבִּימוֹסוֹת וְהַמֶּרְחֲצָאוֹת הֲרֵי הֵן כִּרְשׁוּת הָרַבִּים לְטֻמְאָה. וְכֵן כָּל הָעֲזָרָה כִּרְשׁוּת הָרַבִּים לְטֻמְאָה:","גִּנּוֹת הָעִיר שֶׁדֶּרֶךְ הָעִיר עוֹבֶרֶת עֲלֵיהֶן רְשׁוּת הָרַבִּים לְטֻמְאָה:","הַגִּנָּה בִּזְמַן שֶׁהִיא מִשְׁתַּמֶּרֶת רְשׁוּת הַיָּחִיד וּבִזְמַן שֶׁאֵינָהּ מִשְׁתַּמֶּרֶת רְשׁוּת הָרַבִּים לְטֻמְאָה. וְכֵן בַּסִילְקִי גְּדוֹלָה בִּזְמַן שֶׁפּוֹתְחִין אוֹתָהּ רְשׁוּת הָרַבִּים לְטֻמְאָה וּבִזְמַן שֶׁנּוֹעֲלִין אוֹתָהּ רְשׁוּת הַיָּחִיד לַכּל:","הַבִּקְעָה הַמֻּקֶּפֶת גָּדֵר בִּימוֹת הַגְּשָׁמִים רְשׁוּת הַיָּחִיד לְשַׁבָּת וּלְטֻמְאָה וְאִם לֹא הָיְתָה מֻקֶּפֶת הֲרֵי הִיא רְשׁוּת הַיָּחִיד לְטֻמְאָה בִּלְבַד. וּבִקְעָה שֶׁעָבְרוּ עָלֶיהָ בִּימוֹת הַגְּשָׁמִים הֲרֵי הִיא רְשׁוּת הַיָּחִיד לְטֻמְאָה אֲפִלּוּ בִּימוֹת הַחַמָּה. וְאֵלּוּ הֵן יְמוֹת הַחַמָּה מִשֶּׁתֵּעָקֵר הַתְּבוּאָה מִתּוֹכָהּ. וְאֵלּוּ הֵן יְמוֹת הַגְּשָׁמִים מִשֶּׁתֵּרֵד רְבִיעָה שְׁנִיָּה. בֵּין הָעִגּוּלִים שֶׁל עֲנָבִים לַזּוֹגִין רְשׁוּת הָרַבִּים לְטֻמְאָה:","כֶּרֶם שֶׁלִּפְנֵי הַבּוֹצְרִים רְשׁוּת הַיָּחִיד וּלְאַחַר הַבּוֹצְרִים רְשׁוּת הָרַבִּים לְטֻמְאָה. אֵימָתַי בִּזְמַן שֶׁהָרַבִּים נִכְנָסִים בְּרוּחַ זוֹ וְיוֹצְאִים בָּרוּחַ שֶׁכְּנֶגְדָהּ. שְׁאָר כָּל הַמְּקוֹמוֹת חוּץ מֵאֵלּוּ שֶׁבֵּאַרְנוּ דִּינָם כְּשֵׁם שֶׁהֵן רְשׁוּת הַיָּחִיד לְשַׁבָּת כָּךְ הֵם רְשׁוּת הַיָּחִיד לְטֻמְאָה:","וְיֵשׁ מְקוֹמוֹת שֶׁאֵינָן רְשׁוּת הַיָּחִיד לְשַׁבָּת וְאַף עַל פִּי כֵן הֵן רְשׁוּת הַיָּחִיד לְטֻמְאָה מִפְּנֵי שֶׁאֵין הָעָם מִשְׁתַּמְּשִׁין בָּהֶן וְאֵלּוּ הֵן. הָאִילָנוֹת וְחוֹרֵי רְשׁוּת הָרַבִּים אַף עַל פִּי שֶׁאֵין בָּהֶן אַרְבָּעָה עַל אַרְבָּעָה. כֵּיצַד. אִילָן שֶׁהוּא עוֹמֵד בִּרְשׁוּת הָרַבִּים וְטֻמְאָה בְּתוֹכוֹ עָלָה לְרֹאשׁוֹ סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא. הִכְנִיס יָדוֹ לְחוֹר שֶׁיֵּשׁ בּוֹ טֻמְאָה סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא:","חֲנוּת שֶׁהִיא טְמֵאָה וּפְתוּחָה לִרְשׁוּת הָרַבִּים סָפֵק נִכְנַס סָפֵק לֹא נִכְנַס סְפֵקוֹ טָהוֹר שֶׁכָּל הַחֲנוּת כְּמוֹ שֶׁרֶץ הַמֻּנָּח בִּרְשׁוּת הָרַבִּים שֶׁסְּפֵק מַגָּעוֹ טָהוֹר. הָיוּ שְׁתֵּי חֲנֻיּוֹת אַחַת טְהוֹרָה וְאַחַת טְמֵאָה וְנִכְנַס לְאַחַת מֵהֶן סָפֵק לְטָמֵא נִכְנַס סָפֵק לְטָהוֹר סְפֵקוֹ טָמֵא שֶׁזֶּה סָפֵק רְשׁוּת הַיָּחִיד שֶׁהַחֲנוּת רְשׁוּת הַיָּחִיד. וְכֵן בִּקְעָה בִּימוֹת הַגְּשָׁמִים שֶׁיֵּשׁ בָּהּ שָׂדוֹת הַרְבֵּה וּבָהּ שָׂדֶה אַחַת טְמֵאָה וְאַחַת טְהוֹרָה וְאָמַר נִכְנַסְתִּי לְבִקְעָה זוֹ וְאֵינִי יוֹדֵעַ אִם נִכְנַסְתִּי לְאוֹתָהּ שָׂדֶה אוֹ לֹא נִכְנַסְתִּי סְפֵקוֹ טָמֵא שֶׁסְּפֵק טֻמְאָה בִּרְשׁוּת הַיָּחִיד אֲפִלּוּ סְפֵק בִּיאָה טָמֵא:","מָקוֹם שֶׁהָיָה רְשׁוּת הַיָּחִיד וְנַעֲשָׂה רְשׁוּת הָרַבִּים וְחָזַר וְנַעֲשָׂה רְשׁוּת הַיָּחִיד כְּשֶׁהוּא רְשׁוּת הַיָּחִיד סְפֵקוֹ טָמֵא וּכְשֶׁהוּא רְשׁוּת הָרַבִּים סְפֵקוֹ טָהוֹר:","דְּבָרִים שֶׁהֵן בִּרְשׁוּת הָרַבִּים הֲרֵי הֵן כִּרְשׁוּת הָרַבִּים. כֵּיצַד. קֻפָּה בִּרְשׁוּת הָרַבִּים גָּבוֹהַּ עֲשָׂרָה טְפָחִים וְהַטֻּמְאָה בְּתוֹכָהּ סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָהוֹר. הִכְנִיס יָדוֹ לְתוֹכָהּ סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא. הָיְתָה כְּפִישָׁה נְתוּנָה עַל כְּתֵפוֹ וְכִכַּר תְּרוּמָה כָּרוּךְ בְּסִיב אוֹ בִּנְיָר וְנָתוּן לְתוֹכָהּ סָפֵק נָגַע בָּהּ אַחֵר סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא:","חֲמוֹר בִּרְשׁוּת הָרַבִּים גָּבוֹהַּ עֲשָׂרָה טְפָחִים וְטֻמְאָה נְתוּנָה עָלָיו סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָהוֹר. פָּשַׁט יָדוֹ עַל גַּבָּיו סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא. וְכֵן סֶלַע הַמֻּנָּח בִּרְשׁוּת הָרַבִּים גָּבוֹהַּ עֲשָׂרָה טְפָחִים וְטֻמְאָה נְתוּנָה עָלָיו סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָהוֹר. עָלָה בְּרֹאשׁ הַסֶּלַע סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא:","הָיָה זָב רוֹכֵב עַל חֲמוֹרוֹ וְזֶה רוֹכֵב עַל חֲמוֹרוֹ וּמְהַלְּכִין בַּדֶּרֶךְ סָפֵק נָגַע בַּזָּב סָפֵק לֹא נָגַע. תִּינוֹק טָמֵא מֻרְכָּב עַל כְּתֵפוֹ שֶׁל אָבִיו וְתִינוֹק טָהוֹר מֻרְכָּב עַל כְּתֵפוֹ שֶׁל אָבִיו וְהָלְכוּ זֶה בְּצַד זֶה סָפֵק נָגַע סָפֵק לֹא נָגַע. חֲבִילָה עַל כְּתֵפוֹ וְהָרֹק מֻדְבָּק בַּכֹּתֶל סָפֵק נָגַע סָפֵק לֹא נָגַע. כֵּלִים שְׁטוּחִין בִּרְשׁוּת הָרַבִּים לְמַעְלָה מֵעֲשָׂרָה וְהַטָּמֵא עוֹבֵר סָפֵק הֵסִיט סָפֵק לֹא הֵסִיט הַכּל טָהוֹר: בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Overview of Mishneh Torah Contents 13":["ספר משפטים","הלכותיו חמש, וזה הוא סידורן: הלכות שכירות, הלכות שאלה ופיקדון, הלכות מלווה ולווה, הלכות טוען ונטען, הלכות נחלות.","הלכות שכירות. יש בכללן שבע מצוות – שלוש מצוות עשה, וארבע מצוות לא תעשה; וזה הוא פרטן: (א) דין שכיר ושומר שכר; (ב) ליתן שכר שכיר ביומו; (ג) שלא יאחר שכר שכיר אחר זמנו; (ד) שיאכל השכיר מן המחובר שיעשה בו; (ה) שלא יאכל השכיר מן המחובר שלא בשעת גמר מלאכה; (ו) שלא יוליך השכיר בידו יתר על מה שאכל; (ז) שלא יחסום שור בדישו, וכן שאר הבהמה.","הלכות שאלה ופיקדון. יש בכללן שתי מצוות עשה: (א) דין השואל; (ב) דין שומר חינם.","הלכות מלווה ולווה. יש בכללן שתים עשרה מצוות – ארבע מצוות עשה, ושמונה מצוות לא תעשה; וזה הוא פרטן: (א) להלוות לעני ומך; (ב) שלא ייגוש אותו; (ג) לנגוש את הנוכרי; (ד) שלא ימשכן בעל חוב בזרוע; (ה) להחזיר המשכון לבעליו, בזמן שהוא צריך לו; (ו) שלא יאחר המשכון מבעליו העני, בעת שהוא צריך לו; (ז) שלא יחבול אלמנה; (ח) שלא יחבול כלים שעושים בהן אוכל נפש; (ט) שלא ייתן המלווה בריבית; (י) שלא ילווה הלווה בריבית; (יא) שלא יתעסק אדם בין מלווה ולווה בריבית, ולא יעיד ביניהן ולא יכתוב שטר ולא יערוב; (יב) ללוות מן הנוכרי ולהלוותו בריבית.","הלכות טוען ונטען. מצות עשה אחת, והיא דין טוען ומודה או כופר.","הלכות נחלות. מצות עשה אחת, והוא דין סדר נחלות.","נמצאו כל המצוות הנכללות בספר זה, שלוש ועשרים – מהן אחת עשרה מצוות עשה, ושתים עשרה מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 11":["שְׁכִיב מֵרַע שֶׁאָמַר נְכָסים אֵלּוּ לְבָנַי. אֵין הַבָּנוֹת בִּכְלָלָם. הָיָה לוֹ בֵּן אֶחָד וּבַת. אוֹ בֵּן וּבֶן הַבֵּן. אַף עַל פִּי שֶׁהוּא אָמַר לְבָנַי שֶׁהוּא לְשׁוֹן רַבִּים אֵין נוֹתְנִין אֶלָּא לִבְנוֹ. שֶׁהַבֵּן הָאֶחָד נִקְרָא בָּנִים:","שְׁכִיב מֵרַע שֶׁאָמַר נְכָסַי לְטוֹבִיָּה וּמֵת. וּבָא אֶחָד שֶׁשְּׁמוֹ טוֹבִיָּה וְאָמַר אֲנִי הוּא. נוֹטְלָן. וְאִם הֻחְזַק שְׁמוֹ רַב טוֹבִיָּה אֵינוֹ נוֹטְלָן. וְאִם הָיָה שְׁכִיב מֵרַע גַּס בּוֹ וְקוֹרֵא אוֹתוֹ בִּשְׁמוֹ נוֹטְלָן:","בָּאוּ שְׁנַיִם לִתְבֹּעַ וְכָל אֶחָד מֵהֶן מֻחְזָק שְׁמוֹ טוֹבִיָּה. אִם הָיָה אֶחָד מֵהֶם תַּלְמִיד חָכָם. תַּלְמִיד חָכָם קוֹדֵם. אֵין בָּהֶן תַּלְמִיד חָכָם וְהָיָה אֶחָד מֵהֶן שָׁכֵן אוֹ קָרוֹב הוּא קוֹדֵם. הָיָה אֶחָד שָׁכֵן וְאֶחָד קָרוֹב שָׁכֵן קוֹדֵם. שְׁנֵיהֶם קְרוֹבִים אוֹ שְׁנֵיהֶם שְׁכֵנִים אוֹ שְׁנֵיהֶם תַּלְמִידֵי חֲכָמִים. יַעֲשׂוּ הַדַּיָּנִין כְּמוֹ שֶׁיֵּרָאֶה לָהֶם. כָּל מִי שֶׁדַּעְתָּן נוֹטָה שֶׁעַל זֶה אָמַר נוֹתְנִין לוֹ. וְכֵן אִם הָיוּ רַבִּים:","שְׁכִיב מֵרַע שֶׁאָמַר נְכָסַי לִפְלוֹנִי וּפְלוֹנִי וּפְלוֹנִי. חוֹלְקִין בְּשָׁוֶה אֲפִלּוּ הֵן מֵאָה:","אָמַר נְכָסַי לִפְלוֹנִי וּלְבָנַי חוֹלְקִין. פְּלוֹנִי נוֹטֵל מֶחֱצָה וְכָל בָּנָיו מֶחֱצָה. וּמַעֲשֶׂה בְּאֶחָד שֶׁאָמַר לְאִשְׁתּוֹ נְכָסַי לִיךְ וּלְבָנַיִךְ. וְאָמְרוּ חֲכָמִים תִּטּל הִיא מֶחֱצָה וְכָל הַבָּנִים מֶחֱצָה:","אָמַר לִפְלוֹנִי וּפְלוֹנִי וְלִבְנֵי פְּלוֹנִי. נוֹטְלִין בְּנֵי פְּלוֹנִי מֶחֱצָה וְהַשְּׁנַיִם הָרִאשׁוֹנִים מֶחֱצָה:","שְׁכִיב מֵרַע שֶׁאָמַר יַחֲלֹק פְּלוֹנִי בִּנְכָסַי. יִטּל מֶחֱצָה. תְּנוּ חֵלֶק לִפְלוֹנִי בִּנְכָסַי. יִטּל אֶחָד מִשִּׁשָּׁה עָשָׂר. וְיֵשׁ מִי שֶׁהוֹרָה יִטּל רְבִיעַ הַנְּכָסִים:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ חֵלֶק לִפְלוֹנִי בְּבוֹר הַיַּיִן שֶׁיֵּשׁ לִי. יִטּל רְבִיעַ הַיַּיִן. אָמַר תְּנוּ לוֹ בּוֹ חֵלֶק לֶחָבִית. הֲרֵי מִעוּט וְיִטּל שְׁמִינִית הַיַּיִן. אָמַר תְּנוּ לוֹ בּוֹ חֵלֶק לִקְדֵרָה נוֹטֵל חֵלֶק מִשְּׁנֵים עָשָׂר מִן הַיַּיִן. אָמַר תְּנוּ לוֹ בּוֹ חֵלֶק לְטָפִיחַ נוֹטֵל חֵלֶק מִשִּׁשָּׁה עָשָׂר מִן הַיַּיִן שֶׁבַּבּוֹר. שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁלְּחֵלֶק מוּעָט נִתְכַּוֵּן:","וְאֵין גּוֹמְרִין מִן הַשִּׁעוּרִין הָאֵלּוּ לְדִין אַחֵר:","שְׁכִיב מֵרַע שֶׁאָמַר תִּטּל אִשְׁתִּי כְּאֶחָד מִן הַבָּנִים. נוֹטֶלֶת כְּאֶחָד מִבָּנָיו. וְאִם נוֹלְדוּ לוֹ בָּנִים אַחַר הַצַּוָּאָה מִצְטָרְפִין עִם אֵלּוּ שֶׁהָיוּ בִּשְׁעַת הַצַּוָּאָה וְנוֹטֶלֶת חֵלֶק עִם כֻּלָּן. כֵּיצַד. הָיוּ שְׁלֹשָׁה בָּנִים בִּשְׁעַת הַצַּוָּאָה וּלְאַחַר זְמַן נוֹלְדוּ לוֹ שְׁנַיִם. נוֹטֶלֶת כְּאֶחָד מִן הַחֲמִשָּׁה שֶׁהוּא שְׁתוּת כָּל הַמָּמוֹן:","וְאֵינָהּ נוֹטֶלֶת עִמָּהֶם אֶלָּא בִּנְכָסִים שֶׁהָיוּ לוֹ בִּשְׁעַת הַצַּוָּאָה. אֲבָל נְכָסִים שֶׁבָּאוּ לוֹ אַחַר זְמַן הַצַּוָּאָה אֵין לָהּ בָּהֶן חֵלֶק שֶׁאֵין אָדָם מַקְנֶה דָּבָר שֶׁלֹּא בָּא בִּרְשׁוּתוֹ:","שְׁכִיב מֵרַע שֶׁאָמַר מִטַּלְטְלִין שֶׁיֵּשׁ לִי לִפְלוֹנִי. נוֹטֵל כְּלֵי תַּשְׁמִישׁוֹ. אֲבָל לֹא חִטִּים וּשְׂעוֹרִים וְכַיּוֹצֵא בָּהֶן. אָמַר כָּל מִטַּלְטְלִין שֶׁלִּי. נוֹטֵל הַכּל:","וְהָעֲבָדִים בִּכְלַל הַמִּטַּלְטְלִין. אֲבָל לֹא רֵחַיִם הַתַּחְתּוֹנָה וְכַיּוֹצֵא בָּהּ. שֶׁהֲרֵי הִיא מְחֻבֶּרֶת לָאָרֶץ:","אָמַר כָּל הַמִּטַּלְטֵל. נוֹטֵל אַף רֵחַיִם הַתַּחְתּוֹנָה וְכַיּוֹצֵא בָּהֶן:","שְׁכִיב מֵרַע שֶׁאָמַר נְכָסַי לִפְלוֹנִי. נוֹטֵל כָּל הַמִּטַּלְטְלִין וְכָל הַקַּרְקָעוֹת וְהַבְּגָדִים וְהָעֲבָדִים וְהַבְּהֵמָה וְהָעוֹפוֹת. וְהַתְּפִלִּין עִם שְׁאָר סְפָרִים הַכּל בִּכְלַל הַנְּכָסִים. אֲבָל סֵפֶר תּוֹרָה יֵשׁ בּוֹ סָפֵק אִם הוּא בִּכְלַל נְכָסִים אוֹ אֵינוֹ לְפִיכָךְ אִם תְּפָסוֹ אֵין מוֹצִיאִין מִיָּדוֹ:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ מָאתַיִם זוּז לִפְלוֹנִי בְּכוֹרִי כָּרָאוּי לוֹ. נוֹטְלָן וְנוֹטֵל בְּכוֹרָתוֹ:","אָמַר בִּבְכוֹרָתוֹ יָדוֹ עַל הָעֶלְיוֹנָה. רָצָה חֵלֶק בְּכוֹרָה נוֹטֵל רָצָה מָאתַיִם זוּז נוֹטֵל:","וְכֵן אִם אָמַר תְּנוּ מָאתַיִם זוּז לִפְלוֹנִית אִשְׁתִּי כָּרָאוּי לָהּ. נוֹטַלְתָּן וְנוֹטֶלֶת כְּתֻבָּתָהּ. וְאִם אָמַר בִּכְתֻבָּתָהּ יָדָהּ עַל הָעֶלְיוֹנָה:","אָמַר תְּנוּ מָאתַיִם זוּז לִפְלוֹנִי בַּעַל חוֹבִי כָּרָאוּי לוֹ נוֹטְלָן וְנוֹטֵל אֶת חוֹבוֹ. אָמַר בְּחוֹבוֹ אֵין לוֹ אֶלָּא חוֹבוֹ:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ אַרְבַּע מֵאוֹת זוּז לִפְלוֹנִי וְיִשָּׂא בִּתִּי. הֲרֵי זֶה כְּמִי שֶׁנָּתַן לוֹ שְׁתֵּי מַתָּנוֹת כָּל אֵיזֶה מֵהֶן שֶׁיִּרְצֶה יִקַּח. לְפִיכָךְ אִם רָצָה לִקַּח הַמָּעוֹת וְלֹא יִשָּׂא הַבַּת יִקַּח. אֲבָל אִם אָמַר יִקַּח בִּתִּי וּתְנוּ לוֹ אַרְבַּע מֵאוֹת זוּז. הֲרֵי זֶה תְּנַאי וְלֹא יִזְכֶּה בַּמָּעוֹת עַד שֶׁיִּקַּח הַבַּת:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ אַרְבַּע מֵאוֹת זוּז לְבִתִּי בִּכְתֻבָּתָהּ אוֹ לִכְתֻבָּתָהּ. אִם דֶּרֶךְ אַנְשֵׁי הָעִיר לְהוֹסִיף בְּשׁוּמַת הַנְּדוּנְיָא וְלִכְתֹּב שְׁוֵה מָנֶה בְּמָאתַיִם אֵינָהּ נוֹטֶלֶת אֶלָּא מָאתַיִם זוּז. שֶׁהֲרֵי לֹא אָמַר אַרְבַּע מֵאוֹת זוּז סְתָם אֶלָּא בִּכְתֻבָּתָהּ. כְּלוֹמַר תְּנוּ לָהּ מַה שֶּׁתִּהְיֶה שׁוּמָתוֹ בִּכְתֻבָּתָהּ אַרְבַּע מֵאוֹת זוּז:","אָמַר תְּנוּ נְדוּנְיָא לְבִתִּי כָּךְ וְכָךְ בְּגָדִים כָּךְ וְכָךְ כֵּלִים. הוּזְלוּ הַבְּגָדִים וְהַכֵּלִים אַחַר כֵּן. הָרֶוַח לַיתוֹמִים וְנוֹתְנִין לָהּ כַּשַּׁעַר הַזּוֹל. וְכֵן אִם אָמַר תְּנוּ אַרְבַּע מֵאוֹת זוּז דְּמֵי הַיַּיִן לְבִתִּי וְהוּקַר הַיַּיִן הָרֶוַח לַיתוֹמִים וְנוֹתְנִין לָהּ אַרְבַּע מֵאוֹת זוּז. מַעֲשֶׂה בְּאֶחָד שֶׁהָיָה יוֹצֵא בְּקוֹלָר וְאָמַר תְּנוּ לִפְלוֹנִי אַרְבַּע מֵאוֹת זוּז מֵהַיַּיִן שֶׁל מָקוֹם פְּלוֹנִי. וְאָמְרוּ חֲכָמִים יִטּל אַרְבַּע מֵאוֹת זוּז מִדְּמֵי אוֹתוֹ הַיַּיִן שֶׁלֹּא נִתְכַּוֵּן זֶה לִתֵּן לוֹ מִן הַיַּיִן מִשְׁקַל אַרְבַּע מֵאוֹת זוּז וְלֹא נִתְכַּוֵּן אֶלָּא לְדָמִים וְזֶה שֶׁיִּחֲדָן כְּדֵי לְיַפּוֹת אֶת כֹּחוֹ. וְשׁוּב מַעֲשֶׂה בְּאֶחָד שֶׁאָמַר הַדֶּקֶל לְבִתִּי וְהִנִּיחַ שְׁנֵי חֲצָאֵי דֶּקֶל אָמְרוּ חֲכָמִים תִּטּל הַשְּׁנֵי חֲצָאִים שֶׁלָּזֶה נִתְכַּוֵּן וְהֵם שֶׁקָּרָא דֶּקֶל. וְשׁוּב מַעֲשֶׂה בְּאֶחָד שֶׁאָמַר תְּנוּ לִפְלוֹנִי בַּיִת הַמַּחֲזִיק מֵאָה כּוֹרִין וְנִמְצָא הַבַּיִת שֶׁיֵּשׁ לְזֶה הַמְצַוֶּה מַחֲזִיק מֵאָה וְעֶשְׂרִים. וְאָמְרוּ חֲכָמִים זָכָה בְּבַיִת זֶה שֶׁהַדְּבָרִים מַרְאִין שֶׁכַּוָּנָתוֹ לָזֶה הָיְתָה שֶׁכָּל הַנּוֹתֵן בְּעַיִן יָפָה נוֹתֵן. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ לִבְנִי שֶׁקֶל בְּכָל שַׁבָּת. אוֹ שֶׁאָמַר אַל תִּתְּנוּ לָהֶם אֶלָּא שֶׁקֶל. וְנִמְצָא שֶׁאֵינוֹ מַסְפִּיק לָהֶם אֶלָּא סֶלַע בְּכָל שַׁבָּת. נוֹתְנִים לָהֶם כָּל צָרְכָּן שֶׁלֹּא נִתְכַּוֵּן זֶה לְהַרְעִיב אֶת בָּנָיו אֶלָּא לְזָרֵז אוֹתָם. שֶׁמָּא יַרְוִיחוּ בָּהוֹצָאָה יוֹתֵר מִדַּאי:","שְׁכִיב מֵרַע שֶׁצִּוָּה וְאָמַר אַל תִּסְפְּדוּהוּ. אֵין סוֹפְדִין אוֹתוֹ. אַל תִּקְבְּרוּהוּ מִנְּכָסָיו. אֵין שׁוֹמְעִין לוֹ שֶׁיָּחוּס עַל מָמוֹן בָּנָיו וְיַפִּיל עַצְמוֹ עַל הַצִּבּוּר. שֶׁאָסוּר לְהַנִּיחוֹ בְּלֹא קְבוּרָה. אֶלָּא כּוֹפִין אֶת הַיּוֹרְשִׁין לְקָבְרוֹ מִנְּכָסָיו:"],"Mishneh Torah, Paschal Offering 2":["אֵין שׁוֹחֲטִין אֶת הַפֶּסַח אֶלָּא לִמְנוּיָיו שֶׁנֶּאֱמַר (שמות יב ד) \"תָּכֹסּוּ עַל הַשֶּׂה\" מְלַמֵּד שֶׁמִּתְמַנִּים עָלָיו כְּשֶׁהוּא חַי. וְאֵלּוּ הַמִּתְמַנִּים עַל הַפֶּסַח הֵם הַנִּקְרָאִים בְּנֵי חֲבוּרָה:","יָחִיד שֶׁשָּׁחַט אֶת הַפֶּסַח לְעַצְמוֹ כָּשֵׁר. וְהוּא שֶׁיִּהְיֶה רָאוּי לֶאֱכוֹל אֶת כֻּלּוֹ. וּמִשְׁתַּדְּלִין שֶׁלֹּא יִשְׁחַט לְכַתְּחִלָּה עַל יָחִיד שֶׁנֶּאֱמַר (שמות יב מז) (במדבר ט יא יב) \"יַעֲשׂוּ אֹתוֹ\":","אֵין שׁוֹחֲטִין אֶת הַפֶּסַח אֶלָּא עַל מִי שֶׁרָאוּי לֶאֱכל. הָיָה אֶחָד מִבְּנֵי חֲבוּרָה קָטָן אוֹ זָקֵן אוֹ חוֹלֶה אִם יָכוֹל לֶאֱכל כְּזַיִת שׁוֹחֲטִין עָלָיו וְאִם לָאו אֵין שׁוֹחֲטִין עָלָיו שֶׁנֶּאֱמַר (שמות יב ד) \"אִישׁ לְפִי אָכְלוֹ\" עַד שֶׁיִּהְיֶה רָאוּי לֶאֱכל. אֲפִלּוּ חֲבוּרָה שֶׁל מֵאָה וְאֵין כָּל אֶחָד מֵהֶן יָכוֹל לֶאֱכל כְּזַיִת אֵין שׁוֹחֲטִין עֲלֵיהֶן:","אֵין עוֹשִׂין חֲבוּרָה נָשִׁים וַעֲבָדִים אוֹ קְטַנִּים וַעֲבָדִים מִפְּנֵי שֶׁלֹּא תִּהְיֶה קַלּוּת רֹאשׁ בֵּינֵיהֶן. אֲבָל עוֹשִׂים חֲבוּרָה כֻּלָּם נָשִׁים אֲפִלּוּ בְּפֶסַח שֵׁנִי. אוֹ כֻּלָּהּ עֲבָדִים. וְשׁוֹחֲטִין עַל הַקְּטַנִּים שֶׁיִּהְיוּ מִכְּלַל בְּנֵי הַחֲבוּרָה. לֹא שֶׁתִּהְיֶה חֲבוּרָה כֻּלָּהּ קְטַנִּים שֶׁאֵינָן בְּנֵי דַּעַת. וְכֵן אֵין עוֹשִׂין חֲבוּרָה כֻּלָּהּ חוֹלִים אוֹ זְקֵנִים אוֹ אוֹנְנִים אַף עַל פִּי שֶׁהֵן יְכוֹלִין לֶאֱכל הוֹאִיל וַאֲכִילָתָם מְעוּטָה. שֶׁמָּא יַשְׁאִירוּ הַפֶּסַח וִיבִיאוּהוּ לִידֵי פְּסוּל. וְאִם עָבְרוּ וְשָׁחֲטוּ עַל חֲבוּרָה זוֹ כָּשֵׁר. וְכֵן אֵין עוֹשִׂין חֲבוּרָה כֻּלָּהּ גֵּרִים שֶׁמָּא יְדַקְדְּקוּ בּוֹ וִיבִיאוּהוּ לִידֵי פִּסּוּל. וְאִם שָׁחֲטוּ עֲלֵיהֶן כָּשֵׁר:","שְׁחָטוֹ שֶׁלֹּא לִמְנוּיָיו אוֹ לְמִי שֶׁאֵין כָּל אֶחָד מֵהֶן יָכוֹל לֶאֱכל כְּזַיִת אוֹ שֶׁשְּׁחָטוֹ לַעֲרֵלִים אוֹ לִטְמֵאִים פָּסוּל. שְׁחָטוֹ לְמִי שֶׁיָּכוֹל לֶאֱכל וּלְמִי שֶׁאֵינוֹ יָכוֹל לֶאֱכל כְּזַיִת. לִמְנוּיָיו וְשֶׁלֹּא לִמְנוּיָיו. לְמוּלִים וְלַעֲרֵלִים. לִטְהוֹרִים וְלִטְמֵאִין. כָּשֵׁר. שֶׁאֵלּוּ הָרְאוּיִין לוֹ אוֹכְלִין כַּהֲלָכָה וְהָאֲחֵרִים כְּאִלּוּ לֹא חָשַׁב עֲלֵיהֶם:","שְׁחָטוֹ לְמוּלִים וְזָרַק הַדָּם לְשֵׁם מוּלִים וַעֲרֵלִים פָּסוּל. שֶׁהַזְּרִיקָה חֲמוּרָה שֶׁהִיא עִקַּר הַקָּרְבָּן. שְׁחָטוֹ לְמוּלִים שֶׁיִּתְכַּפְּרוּ בּוֹ עֲרֵלִים פָּסוּל שֶׁהֲרֵי יֵשׁ מַחֲשֶׁבֶת עֲרֵלִים בִּזְרִיקָה. שְׁחָטוֹ לְאוֹכְלָיו לִזְרֹק דָּמוֹ שֶׁלֹּא לְאוֹכְלָיו הַפֶּסַח כָּשֵׁר וְאֵין אָדָם יוֹצֵא בּוֹ יְדֵי חוֹבָתוֹ לְפִי שֶׁאֵין מַחֲשֶׁבֶת אוֹכְלִים בַּזְּרִיקָה:","מִי שֶׁהוּא בָּרִיא בִּשְׁעַת שְׁחִיטָה וְחוֹלֶה בִּשְׁעַת זְרִיקָה. אוֹ חוֹלֶה בִּשְׁעַת שְׁחִיטָה וּבָרִיא בִּשְׁעַת זְרִיקָה. אֵין שׁוֹחֲטִין וְזוֹרְקִין עָלָיו עַד שֶׁיִּהְיֶה בָּרִיא מִשְּׁעַת שְׁחִיטָה עַד שְׁעַת זְרִיקָה:","שׁוֹחֵט אָדָם עַל יְדֵי בְּנוֹ וּבִתּוֹ הַקְּטַנִּים וְעַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים בֵּין מִדַּעְתָּן בֵּין שֶׁלֹּא מִדַּעְתָּן. אֲבָל אֵינוֹ שׁוֹחֵט עַל יְדֵי בְּנוֹ וּבִתּוֹ הַגְּדוֹלִים וְלֹא עַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הָעִבְרִים וְלֹא עַל יְדֵי אִשְׁתּוֹ אֶלָּא מִדַּעְתָּן. וְאִם שָׁתְקוּ וְלֹא מִחוּ הֲרֵי זֶה מִדַּעְתָּן:","שָׁחַט עַל יְדֵי בְּנוֹ וּבִתּוֹ הַקְּטַנִּים וְעַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים וְהָלְכוּ וְשָׁחֲטוּ הֵן לְעַצְמָן יוֹצְאִין בְּשֶׁל רַבָּן:","שָׁחַט עַל יְדֵי אִשְׁתּוֹ וּבְנוֹ וּבִתּוֹ הַגְּדוֹלִים וְעַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הָעִבְרִים וְשָׁחֲטוּ הֵן לְעַצְמָן. אֵין לְךָ מִחוּי גָּדוֹל מִזֶּה וְאֵינָן יוֹצְאִין אֶלָּא בְּשֶׁל עַצְמָן:","הָאִשָּׁה שֶׁהִיא בְּבֵית בַּעְלָהּ שָׁחַט עָלֶיהָ אָבִיהָ וְשָׁחַט עָלֶיהָ בַּעְלָהּ תֹּאכַל מִשֶּׁל בַּעְלָהּ. הָיְתָה נֶחְפֶּזֶת לָלֶכֶת לְבֵית אָבִיהָ בָּרֶגֶל הָרִאשׁוֹן הַסָּמוּךְ לְנִשּׂוּאֶיהָ כְּדֶרֶךְ כָּל הַבָּנוֹת וְשָׁחַט עָלֶיהָ אָבִיהָ וְשָׁחַט עָלֶיהָ בַּעְלָהּ תֹּאכַל מִשֶּׁל אָבִיהָ. מִכָּאן וְאֵילָךְ תֹּאכַל מִמָּקוֹם שֶׁהִיא רוֹצָה. וְהוּא שֶׁתִּבְרֹר לָהּ מָקוֹם שֶׁתִּרְצֶה בִּשְׁעַת שְׁחִיטָה. וְכֵן יָתוֹם שֶׁשָּׁחֲטוּ עָלָיו אַפּוֹטְרוֹפְּסִין יֹאכַל מִמָּקוֹם שֶׁהוּא רוֹצֶה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּיָתוֹם קָטָן. אֲבָל גָּדוֹל נַעֲשֶׂה כִּמְמַנֶּה עַצְמוֹ עַל שְׁנֵי פְּסָחִים וְהַמְמַנֶּה עַצְמוֹ עַל שְׁנֵי פְּסָחִים אֵינוֹ אוֹכֵל אֶלָּא מִן הַנִּשְׁחָט רִאשׁוֹן:","עֶבֶד שֶׁל שְׁנֵי שֻׁתָּפִין בִּזְמַן שֶׁמַּקְפִּידִין זֶה עַל זֶה שֶׁלֹּא יִגְנְבֶנּוּ לֹא יֹאכַל מִשֶּׁל שְׁנֵיהֶן. וְאִם אֵינָן מַקְפִּידִין מִמָּקוֹם שֶׁיִּרְצֶה יֹאכַל:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין. לֹא יֹאכַל לֹא מִשֶּׁל רַבּוֹ וְלֹא מִשֶּׁל עַצְמוֹ עַד שֶׁיֵּעָשֶׂה כֻּלּוֹ בֶּן חוֹרִין:","עַד כַּמָּה נִמְנִים עַל הַפֶּסַח. עַד שֶׁיִּהְיֶה בּוֹ כְּזַיִת לְכָל אֶחָד וְאֶחָד. וְנִמְנִין עָלָיו וּמוֹשְׁכִין אֶת יְדֵיהֶן מִמֶּנּוּ עַד שֶׁיִּשָּׁחֵט. כֵּיוָן שֶׁנִּשְׁחַט אֵינוֹ יָכוֹל לִמְשֹׁךְ אֶת יָדוֹ שֶׁהֲרֵי נִשְׁחַט עָלָיו. נִמְנוּ עָלָיו וְחָזְרוּ אֲחֵרִים וְנִמְנוּ עָלָיו. רִאשׁוֹנִים שֶׁיֵּשׁ לָהֶם כְּזַיִת אוֹכְלִים וּפְטוּרִים מֵעֲשׂוֹת פֶּסַח שֵׁנִי וְאַחֲרוֹנִים שֶׁרָבוּ עַד שֶׁלֹּא נִמְצָא בּוֹ כְּזַיִת לְכָל אֶחָד אֵינָן אוֹכְלִין וְחַיָּבִים לַעֲשׂוֹת פֶּסַח שֵׁנִי:","הַמְמַנֶּה אֲחֵרִים עִמּוֹ עַל חֶלְקוֹ וְלֹא יָדְעוּ בָּהֶן בְּנֵי הַחֲבוּרָה הֲרֵי בְּנֵי הַחֲבוּרָה רַשָּׁאִין לִתֵּן לוֹ חֶלְקוֹ אַחַר שֶׁיִּצָּלֶה בְּעֵת הָאֲכִילָה וּבְנֵי הַחֲבוּרָה אוֹכְלִין מִשֶּׁלָּהֶן וְהוּא אוֹכֵל חֶלְקוֹ עִם הָאֲחֵרִים שֶׁמָּנָה עָלָיו בַּחֲבוּרָה שְׁנִיָּה. וְכֵן בְּנֵי הַחֲבוּרָה שֶׁהָיָה אֶחָד מֵהֶם גַּרְגְּרָן רַשָּׁאִים לְהוֹצִיאוֹ מֵהֶן וְנוֹתְנִין לוֹ חֶלְקוֹ וְיֹאכְלֵהוּ בַּחֲבוּרָתוֹ. וְאִם אֵינוֹ זוֹלֵל אֵינָן רַשָּׁאִין לְחַלֵּק:"],"Mishneh Torah, Plaintiff and Defendant 13":["וְאֵלּוּ שֶׁאֵין מַעֲמִידִין הַקַּרְקַע בְּיָדָן אַף עַל פִּי שֶׁאֲכָלוּם שָׁלֹשׁ שָׁנִים. הָאֻמָּנִין וְהָאֲרִיסִין וְהָאַפּוֹטְרוֹפִּין וְהַשֻּׁתָּפִין וְהָאִישׁ בְּנִכְסֵי אִשְׁתּוֹ וְהָאִשָּׁה בְּנִכְסֵי בַּעְלָהּ וּבֵן בְּנִכְסֵי אָבִיו וְהָאָב בְּנִכְסֵי הַבֵּן. שֶׁכָּל אֶחָד מֵאֵלּוּ אֵין מַקְפִּידִין זֶה עַל זֶה. לְפִיכָךְ אֵין אֲכִילָתָן רְאָיָה אַף עַל פִּי שֶׁלֹּא מִחוּ בָּהֶן הַבְּעָלִים אֶלָּא תַּחְזֹר הַקַּרְקַע לַבְּעָלִים שֶׁהֵבִיאוּ רְאָיָה שֶׁזֹּאת הַקַּרְקַע יְדוּעָה לָהֶן וְיִשָּׁבַע הֶסֵּת שֶׁלֹּא מְכָרוֹ וְשֶׁלֹּא נְתָנוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן רָאשֵׁי גָּלֻיּוֹת שֶׁל אוֹתוֹ זְמַן וְהַגַּזְלָן וְהָעַכּוּ\"ם אֵין אֲכִילָתָן רְאָיָה מִפְּנֵי שֶׁהֵן בַּעֲלֵי זְרוֹעַ. וְכֵן חֵרֵשׁ שׁוֹטֶה וְקָטָן אֵין אֲכִילָתָן רְאָיָה מִפְּנֵי שֶׁאֵין לָהֶם טַעֲנָה כְּדֵי שֶׁתַּעֲמֹד הַקַּרְקַע בְּיָדָן אֶלָּא תַּחְזֹר לַבְּעָלִים. וְכֵן הַמַּחֲזִיק בְּנִכְסֵיהֶן אֵין אֲכִילָתָן רְאָיָה:","כֵּיצַד אֵין מַעֲמִידִין אֶת הַקַּרְקַע בְּיָדָן. רְאוּבֵן שֶׁאָכַל שְׂדֵה שִׁמְעוֹן שְׁנֵי חֲזָקָה וְהוּא טָעַן שֶׁהִיא לְקוּחָה בְּיָדוֹ וְהֵבִיא שִׁמְעוֹן עֵדִים שֶׁהִיא יְדוּעָה לוֹ וְכֵן הֵבִיא עֵדִים שֶׁרְאוּבֵן יָדוּעַ שֶׁהוּא שֻׁתָּפוֹ אוֹ אֲרִיסוֹ אוֹ אַפּוֹטְרוֹפּוֹסוֹ וּמִפְּנֵי זֶה לֹא מִחָה תַּחְזֹר הַשָּׂדֶה לְשִׁמְעוֹן וְיִשָּׁבַע הֶסֵּת שֶׁלֹּא מָכַר וְלֹא נָתַן. וְהוּא הַדִּין לִשְׁאָרָן. אֲבָל אִם לֹא הֵבִיא שִׁמְעוֹן רְאָיָה שֶׁרְאוּבֵן הָיָה שֻׁתָּף אוֹ אָרִיס אֶלָּא רְאוּבֵן הוֹדָה מֵעַצְמוֹ וְאָמַר הֵן הוּא שֻׁתָּפִי וּמָכַר לִי. הוֹאִיל וְאָכַל שְׁנֵי חֲזָקָה וְיָכוֹל לוֹמַר לֹא הָיָה שֻׁתָּפִי מֵעוֹלָם הֲרֵי זֶה נֶאֱמָן כִּשְׁאָר כָּל אָדָם:","הָאֻמָּנִין כֵּיצַד. כְּגוֹן שֶׁהָיוּ בּוֹנִין בָּהּ אוֹ מְתַקְּנִין אוֹתָהּ שָׁנִים רַבּוֹת. יָרְדוּ מֵאֻמָּנוּתָן אִם אָכְלוּ אוֹתָן שָׁלֹשׁ שָׁנִים מֵאַחַר שֶׁיָּרְדוּ מֵאֻמָּנוּתָן יֵשׁ לָהֶן חֲזָקָה:","הָאֲרִיסִין כֵּיצַד. כְּגוֹן שֶׁהָיָה אָרִיס לְאָבִיו שֶׁל בַּעַל הַשָּׂדֶה אוֹ לְאַנְשֵׁי מִשְׁפַּחְתּוֹ שֶׁכֵּיוָן שֶׁהוּא אָרִיס שֶׁל בָּתֵּי אָבוֹת אֵין מְמַחִין הַבְּעָלִים בְּיָדוֹ. אֲבָל אִם זֶה הוּא שֶׁנַּעֲשָׂה אָרִיס תְּחִלָּה הוֹאִיל וַאֲכָלָהּ כֻּלָּהּ שְׁנֵי חֲזָקָה מַעֲמִידִין אוֹתָהּ בְּיָדוֹ. וְאוֹמְרִין לַבְּעָלִים הֵיאַךְ אָכַל שָׁנָה אַחַר שָׁנָה וְלֹא מָחִיתָ בּוֹ:","אָרִיס שֶׁל בָּתֵּי אָבוֹת שֶׁהוֹרִיד אֲרִיסִין תַּחַת יָדוֹ יֵשׁ לוֹ חֲזָקָה שֶׁאֵין מוֹרִידִין אֲרִיסִים אֲחֵרִים לְנִכְסֵי אָדָם וְהוּא שׁוֹתֵק. אֲבָל אִם חָלַק לַאֲרִיסִין אֲחֵרִים שֶׁהָיוּ בָּהּ אֵין לוֹ חֲזָקָה שֶׁמָּא מְמֻנֶּה עַל הָאֲרִיסִין עָשׂוּ אוֹתוֹ. וְאָרִיס שֶׁיָּרַד מֵאֲרִיסוּתוֹ וַאֲכָלָהּ שָׁלֹשׁ שָׁנִים מֵאַחַר שֶׁיָּרַד הֶחֱזִיק:","הָאַפּוֹטְרוֹפּוֹסִין כֵּיצַד. בֵּין שֶׁהָיָה אַפּוֹטְרוֹפּוֹס עַל שָׂדֶה זוֹ בֵּין עַל שְׁאָר נְכָסִים בֵּין שֶׁמִּנּוּ אוֹתָם בֵּית דִּין בֵּין שֶׁמִּנָּה אוֹתָם אֲבִי יְתוֹמִים וְגָדְלוּ הַיְתוֹמִים וְהִנִּיחוּ אוֹתָן. בֵּין שֶׁמִּנָּה אָדָם אַפּוֹטְרוֹפּוֹס עַל הוֹצָאָתוֹ וְהַכְנָסָתוֹ. הוֹאִיל וְהֵן מִשְׁתַּמְּשִׁין בִּרְשׁוּת אֵין לָהֶן חֲזָקָה. עָבְרוּ הָאַפּוֹטְרוֹפִּין מִמִּנּוּיָן וְאָכְלוּ שָׁלֹשׁ שָׁנִים אַחַר שֶׁעָבְרוּ הֲרֵי זוֹ חֲזָקָה:","הַשֻּׁתָּפִין כֵּיצַד. אִם הָיָה שֻׁתָּף בְּשָׂדֶה זוֹ וְאֵין בָּהּ דִּין חֲלוּקָה אַף עַל פִּי שֶׁאָכַל אֶת כֻּלָּהּ הָאֶחָד מֵהֶן כַּמָּה שָׁנִים הֲרֵי הִיא בְּחֶזְקַת שְׁנֵיהֶם. וְאִם יֵשׁ בָּהּ דִּין חֲלוּקָה וַאֲכָלָהּ הָאֶחָד כֻּלָּהּ שְׁנֵי חֲזָקָה יֵשׁ לוֹ חֲזָקָה שֶׁהֲרֵי אוֹמֵר לְשֻׁתָּפוֹ אִם בֶּאֱמֶת שֶׁלֹּא מָכַרְתָּ וְלֹא נָתַתָּ הֵיאַךְ אָכַלְתִּי אֶת כֻּלָּהּ וְאַתָּה שׁוֹתֵק וְלֹא מָחִיתָ כָּל שָׁלֹשׁ שָׁנִים. וְכֵן הָאִישׁ שֶׁאָכַל בְּנִכְסֵי אִשְׁתּוֹ שְׁנֵי חֲזָקָה אַף עַל פִּי שֶׁהִתְנָה עִמָּהּ שֶׁאֵין לוֹ פֵּרוֹת בִּנְכָסֶיהָ. וַאֲפִלּוּ הִתְנָה עִמָּהּ כְּשֶׁהִיא אֲרוּסָה שֶׁלֹּא יִירָשֶׁנָּה וְאַחַר כָּךְ אָכַל וּבָנָה וְהָרַס וְעָשָׂה כָּל מַה שֶּׁעָשָׂה. וְכֵן הָאִשָּׁה שֶׁאָכְלָה פֵּרוֹת בְּנִכְסֵי בַּעְלָהּ וְנִשְׁתַּמְּשָׁה בָּהֶן כְּחֶפְצָהּ כַּמָּה שָׁנִים. אַף עַל פִּי שֶׁיִּחֵד לָהּ שָׂדֶה בִּמְזוֹנוֹתֶיהָ וְאָכְלָה שָׂדוֹת אֲחֵרוֹת אֵין אֲכִילָתָן רְאָיָה. וְכֵן הַבֵּן שֶׁהוּא סוֹמֵךְ עַל שֻׁלְחָנוֹ שֶׁל אָבִיו וְנֶחְשָׁב בִּכְלַל בְּנֵי בֵּיתוֹ אִם אָכַל נִכְסֵי אָבִיו שְׁנֵי חֲזָקָה. וְכֵן הָאָב שֶׁאָכַל נִכְסֵי בֵּן זֶה שֶׁהוּא סוֹמֵךְ עָלָיו שְׁנֵי חֲזָקָה. אֵין אֲכִילָתָן רְאָיָה:","וּבֵן שֶׁפֵּרַשׁ מֵאָבִיו וְאִשָּׁה שֶׁנִּתְגָּרְשָׁה אֲפִלּוּ סְפֵק גֵּרוּשִׁין הֲרֵי הֵן כִּשְׁאָר כָּל אָדָם:","רָאשֵׁי גָּלֻיּוֹת שֶׁהָיוּ בִּימֵי חֲכָמִים לְפִי שֶׁהָיָה בָּהֶן כֹּחַ לִרְדּוֹת אֶת הָעָם אֵין אֲכִילָתָן רְאָיָה. וְכֵן אַחֵר שֶׁהֶחְזִיק בְּנִכְסֵיהֶן אֲפִלּוּ אָכַל כַּמָּה שָׁנִים אֵין אֲכִילָתָן רְאָיָה לְפִי שֶׁאֵינָן מְמַחִין מִפְּנֵי שֶׁיָּדָן תְּקֵפָה כָּל זְמַן שֶׁיִּרְצוּ מְסַלְּקִין זֶה מִמֶּנָּה. אֲבָל נִשְׁבָּעִין הֶסֵּת שֶׁלֹּא מָכְרוּ וְשֶׁלֹּא נָתְנוּ. וְאִם הֵן הֶחֱזִיקוּ בְּנִכְסֵי אַחֵר וְאָמַר שֶׁלֹּא מָכַר נִשְׁבָּע הֶסֵּת שֶׁלֹּא מָכַר לָהֶן וְלֹא נָתַן לָהֶם:","הַגַּזְלָן כֵּיצַד. מִי שֶׁהֻחְזַק גַּזְלָן עַל שָׂדֶה זוֹ אוֹ מִי שֶׁהֻחְזְקוּ אֲבוֹתָיו שֶׁהֵן הוֹרְגִין נְפָשׁוֹת עַל עִסְקֵי מָמוֹן אַף עַל פִּי שֶׁאָכַל שָׂדֶה זוֹ כַּמָּה שָׁנִים לֹא הֶחֱזִיק וְתַחְזֹר שָׂדֶה לַבְּעָלִים:"],"Mishneh Torah, Positive Mitzvot 1":["מִצְוָה רִאשׁוֹנָה מִמִּצְווֹת עֲשֵׂה, לֵידַע שֶׁיֵּשׁ שָׁם אֱלוֹהַּ, שֶׁנֶּאֱמָר: \"אָנֹכִי ה' אֱלֹהֶיךָ\" (שמות כ ב, דברים ה ו)."],"Mishneh Torah, Positive Mitzvot 11":["לִלְמֹד תּוֹרָה וּלְלַמְּדָהּ, שֶׁנֶּאֱמָר: \"וְשִׁנַּנְתָּם לְבָנֶיךָ\" (דברים ו, ז)."],"Mishneh Torah, Positive Mitzvot 120":["להניח פיאה."],"Mishneh Torah, Positive Mitzvot 131":["להתוודות וידוי מעשר, שנאמר: \"ואמרת לפני ה' אלוהיך ביערתי הקודש\" (דברים כו,יג)."],"Mishneh Torah, Positive Mitzvot 142":["לנגוש לנוכרי, שנאמר: \"את הנוכרי, תיגוש; ואשר יהיה לך\" (דברים טו,ג)."],"Mishneh Torah, Positive Mitzvot 153":["לקדש חודשים ולחשב שנים וחודשים בבית דין בלבד, שנאמר: \"החודש הזה לכם, ראש חודשים\" (שמות יב,ב)."],"Mishneh Torah, Positive Mitzvot 164":["להתענות בעשירי בו, שנאמר: \"ובעשור לחודש תענו את נפשותיכם\" (ראה ויקרא טז,כט; במדבר כט,ז)."],"Mishneh Torah, Positive Mitzvot 175":["לנטות אחרי רבים אם תהיה מחלוקת בין הסנהדרין בדינין, שנאמר: \"אחרי רבים--להטות\" (שמות כג,ב)."],"Mishneh Torah, Positive Mitzvot 186":["להרוג אנשי עיר הנידחת ולשרוף את העיר, שנאמר: \"ושרפת באש את . . . כל שללה\" (דברים יג,יז)."],"Mishneh Torah, Positive Mitzvot 197":["להלוות לעני, שנאמר: \"אם כסף תלווה את עמי\" (שמות כב,כד); \"אם\" זה אינו רשות אלא מצוה, שנאמר: \"והעבט, תעביטנו\" (דברים טו,ח)."],"Mishneh Torah, Positive Mitzvot 207":["לאהוב את הגר, שנאמר: \"ואהבתם את הגר\" (דברים י, יט)."],"Mishneh Torah, Positive Mitzvot 218":["לישא אונס שנאמר: \"ולו תהיה לאישה\" (דברים כב,כט)."],"Mishneh Torah, Positive Mitzvot 229":["להיות בית דין סוקלין באבנים, שנאמר: \"וסקלתם אותם\" (דברים כב,כד)."],"Mishneh Torah, Positive Mitzvot 24":["לְקַדֵּשׁ הַכּוֹהֵן יָדָיו וְרַגְלָיו בִּשְׁעַת הָעֲבוֹדָה, שֶׁנֶּאֱמָר: \"וְרָחֲצוּ אַהֲרֹן וּבָנָיו...\" (שמות ל, יט)."],"Mishneh Torah, Positive Mitzvot 27":["לְהַסְדִּיר לֶחֶם וּלְבוֹנָה לִפְנֵי ה' בְּכָל שַׁבָּת, שֶׁנֶּאֱמָר: \"וְנָתַתָּ עַל הַשֻׁלְחָן לֶחֶם פָּנִים\" (שמות כה, ל)."],"Mishneh Torah, Positive Mitzvot 38":["להיות כהן גדול נושא בתולה, שנאמר: \"וְהוּא אִשָּׁה בִּבְתוּלֶיהָ יִקָּח\" (ויקרא כא, יג)."],"Mishneh Torah, Positive Mitzvot 49":["לעשות עבודת היום ביום הצום, שנאמר: \"בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ בְּפַר בֶּן בָּקָר\" (ויקרא טז, ג), וכל העבודה הכתובה בפרשת \"אחרי מות\"."],"Mishneh Torah, Positive Mitzvot 6":["לְדָבְקָה בּוֹ, שֶׁנֶּאֱמָר: \"וּבוֹ תִדְבָּק\" (דברים י כ)."],"Mishneh Torah, Positive Mitzvot 70":["להקריב היחיד קרבן אם נסתפק לו אם חטא חטא שחייבים עליו חטאת או לא חטא, שנאמר: \"וְלֹא יָדַע וְאָשֵׁם וְהֵבִיא אֶת אֲשָׁמוֹ\" (ויקרא ה, יז) וזה הוא נקרא אשם תלוי."],"Mishneh Torah, Positive Mitzvot 81":["לפדות פטר חמור, שנאמר: \"ופטר חמור תפדה בשה\" (שמות לד,כ)."],"Mishneh Torah, Positive Mitzvot 92":["לגדל הנזיר שיערו, שנאמר: \"גדל פרע, שיער ראשו\" (במדבר ו,ה)."],"Mishneh Torah, Prayer and the Priestly Blessing 13":["הַמִּנְהָג הַפָּשׁוּט בְּכָל יִשְׂרָאל שֶׁמַּשְׁלִימִין אֶת הַתּוֹרָה בְּשָׁנָה אַחַת. מַתְחִילִין בְּשַׁבָּת שֶׁאַחַר חַג הַסֻּכּוֹת וְקוֹרִין בְּסֵדֶר (בראשית א א) ״בְּרֵאשִׁית״. בַּשְּׁנִיָּה (בראשית ו ט) ״אֵלֶּה תּוֹלְדֹת״. בַּשְּׁלִישִׁית (בראשית יב א) ״וַיֹּאמֶר יְיָ׳‎ אֶל אַבְרָם״. וְקוֹרְאִין וְהוֹלְכִין עַל הַסֵּדֶר הַזֶּה עַד שֶׁגּוֹמְרִין אֶת הַתּוֹרָה בְּחַג הַסֻּכּוֹת. וְיֵשׁ מִי שֶׁמַּשְׁלִים אֶת הַתּוֹרָה בְּשָׁלֹשׁ שָׁנִים וְאֵינוֹ מִנְהָג פָּשׁוּט:","עֶזְרָא תִּקֵּן לָהֶם לְיִשְׂרָאֵל שֶׁיְּהוּ קוֹרִין קְלָלוֹת שֶׁבְּסֵפֶר וַיִּקְרָא קֹדֶם עֲצֶרֶת וְשֶׁבְּמִשְׁנֵה תּוֹרָה קֹדֶם רֹאשׁ הַשָּׁנָה. וְהַמִּנְהָג הַפָּשׁוּט שֶׁיְּהוּ קוֹרְאִין (במדבר א א) ״בְּמִדְבַּר סִינַי״ קֹדֶם עֲצֶרֶת. (דברים ג כג) ״וָאֶתְחַנַּן״ אַחַר תִּשְׁעָה בְּאָב. (דברים כט ט) ״אַתֶּם נִצָּבִים״ קֹדֶם רֹאשׁ הַשָּׁנָה. (ויקרא ו ב) ״צַו אֶת אַהֲרֹן״ קֹדֶם הַפֶּסַח בְּשָׁנָה פְּשׁוּטָה. לְפִיכָךְ יֵשׁ שַׁבָּתוֹת שֶׁקּוֹרִין שַׁחֲרִית שְׁנֵי סְדָרִין כְּגוֹן (ויקרא יב ב) ״אִשָּׁה כִּי תַזְרִיעַ״ וְ(ויקרא יד ב) ״זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע״. (ויקרא כו ג) ״אִם בְּחֻקֹּתַי״ עִם (ויקרא כה א) ״בְּהַר סִינַי״ וְכַיּוֹצֵא בָּהֶן כְּדֵי שֶׁיַּשְׁלִימוּ בְּשָׁנָה וְיִקְרְאוּ אוֹתָן הַסְּדָרִים בְּעוֹנָתָן:","מָקוֹם שֶׁמַּפְסִיקִין בְּשַׁבָּת בְּשַׁחֲרִית שָׁם קוֹרְאִין בְּמִנְחָה וּבְשֵׁנִי וּבַחֲמִישִׁי וּלְשַׁבָּת הַבָּאָה. כֵּיצַד. שַׁבָּת רִאשׁוֹנָה קוֹרִין בְּשַׁחֲרִית בְּסֵדֶר (בראשית א א) ״בְּרֵאשִׁית״. בְּמִנְחָה קוֹרִין (בראשית ו ט) ״אֵלֶּה תּוֹלְדֹת נֹחַ״ עֲשָׂרָה פְּסוּקִים אוֹ יוֹתֵר. וְכֵן בְּשֵׁנִי וּבַחֲמִישִׁי. וְכֵן לְשַׁבָּת הַבָּאָה בְּשַׁחֲרִית מַתְחִילִין מֵאֵלֶּה תּוֹלְדֹת נֹחַ וְקוֹרֵא עַד סוֹף הַסֵּדֶר. וְעַל דֶּרֶךְ זוֹ קוֹרִין כָּל הַשָּׁנָה. וּמַפְטִירִין בְּכָל שַׁבָּת וְשַׁבָּת בַּנָּבִיא מֵעֵין שֶׁקָּרָא בַּתּוֹרָה:","וּבְרָאשֵׁי חֳדָשִׁים. הָרִאשׁוֹן קוֹרֵא שְׁלֹשָׁה פְּסוּקִים מִפָּרָשַׁת (במדבר כח ב) ״צַו״. וְהַשֵּׁנִי חוֹזֵר וְקוֹרֵא פָּסוּק ג׳‎ שֶׁקָּרָא הָרִאשׁוֹן וּשְׁנֵי פְּסוּקִים שֶׁאַחֲרָיו כְּדֵי שֶׁיְּשַׁיֵּר בַּפָּרָשָׁה שְׁלֹשָׁה פְּסוּקִים. וְהַשְּׁלִישִׁי קוֹרֵא שְׁלֹשָׁה פְּסוּקִים שֶׁשִּׁיֵּר הַשֵּׁנִי עִם (במדבר כח ט) ״וּבְיוֹם הַשַּׁבָּת״. וְהָרְבִיעִי קוֹרֵא (במדבר כח יא) ״וּבְרָאשֵׁי חָדְשֵׁיכֶם״. וְאִם חָל רֹאשׁ חֹדֶשׁ לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁנֵי סְפָרִים בְּשַׁחֲרִית. בְּאֶחָד קוֹרִין בּוֹ סֵדֶר אוֹתָהּ שַׁבָּת וּבַשֵּׁנִי קוֹרֵא בּוֹ הַמַּשְׁלִים וּבְרָאשֵׁי חָדְשֵׁיכֶם. וְהַמַּפְטִיר קוֹרֵא עִנְיַן רֹאשׁ חֹדֶשׁ. וּמַפְטִירִין (ישעיה סו כג) ״וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ״. וְרֹאשׁ חֹדֶשׁ אָב שֶׁחָל לִהְיוֹת בְּשַׁבָּת מַפְטִירִין (ישעיה א יד) ״חָדְשֵׁיכֶם וּמוֹעֲדֵיכֶם שָׂנְאָה נַפְשִׁי״. וְרֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּאֶחָד בְּשַׁבָּת מַפְטִירִין בַּשַּׁבָּת שֶׁלְּפָנָיו (שמואל א כ יח) ״וַיֹּאמֶר לוֹ יְהוֹנָתָן מָחָר חֹדֶשׁ״:","כָּל הָעוֹלֶה לִקְרוֹת בַּתּוֹרָה פּוֹתֵחַ בְּדָבָר טוֹב וּמְסַיֵּם בְּדָבָר טוֹב. אֲבָל פָּרָשַׁת (דברים לב א) ״הַאֲזִינוּ״ קוֹרֵא הָרִאשׁוֹן עַד (דברים לב ז) ״זְכֹר יְמוֹת עוֹלָם״. וְהַשֵּׁנִי מַתְחִיל מִזְּכֹר יְמוֹת עוֹלָם עַד (דברים לב יג) ״יַרְכִּבֵהוּ״. וְהַשְּׁלִישִׁי מִיַּרְכִּבֵהוּ עַד וַיַּרְא ה׳‎ וַיִּנְאָץ. וְהָרְבִיעִי מִן וַיַּרְא ה׳‎ וַיִּנְאָץ עַד (דברים לב כט) ״לוּ חָכְמוּ״. וְהַחֲמִישִׁי מִן לוּ חָכְמוּ עַד (דברים לב מ) ״כִּי אֶשָּׂא אֶל שָׁמַיִם יָדִי״. וְהַשִּׁשִּׁי מִכִּי אֶשָּׂא אֶל שָׁמַיִם יָדִי עַד סוֹף הַשִּׁירָה. וְלָמָּה פּוֹסְקִין בָּהּ בְּעִנְיָנוֹת אֵלּוּ מִפְּנֵי שֶׁהֵן תּוֹכָחָה כְּדֵי שֶׁיַּחְזְרוּ הָעָם בִּתְשׁוּבָה:","שְׁמוֹנָה פְּסוּקִים שֶׁבְּסוֹף הַתּוֹרָה מֻתָּר לִקְרוֹת אוֹתָם בְּבֵית הַכְּנֶסֶת בְּפָחוֹת מֵעֲשָׂרָה. אַף עַל פִּי שֶׁהַכּל תּוֹרָה הִיא וּמשֶׁה מִפִּי הַגְּבוּרָה אֲמָרָם הוֹאִיל וּמַשְׁמָעָן שֶׁהֵם אַחַר מִיתַת משֶׁה הֲרֵי נִשְׁתַּנּוּ וּלְפִיכָךְ מֻתָּר לְיָחִיד לִקְרוֹת אוֹתָן:","קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים אֵין מַפְסִיקִין בָּהֶן אֶלָּא אֶחָד קוֹרֵא אוֹתָן מַתְחִיל בַּפָּסוּק שֶׁלִּפְנֵיהֶם וּמְסַיֵּם בַּפָּסוּק שֶׁל אַחֲרֵיהֶם. וּקְלָלוֹת שֶׁבְּמִשְׁנֵה תּוֹרָה אִם רָצָה לִפְסֹק בָּהֶן פּוֹסֵק וּכְבָר נָהֲגוּ הָעָם שֶׁלֹּא לִפְסֹק בָּהֶן אֶלָּא אֶחָד קוֹרֵא אוֹתָן:","מַפְסִיקִין לְמוֹעֲדוֹת וּלְיוֹם הַכִּפּוּרִים וְקוֹרְאִין בְּעִנְיַן הַמּוֹעֵד, לֹא בְּסֵדֶר שַׁבָּת. וּמשֶׁה תִּקֵּן לָהֶם לְיִשְׂרָאֵל שֶׁיְּהוּ קוֹרְאִין בְּכָל מוֹעֵד עִנְיָנוֹ. וְשׁוֹאֲלִין וְדוֹרְשִׁין בְּעִנְיָנוֹ שֶׁל יוֹם בְּכָל מוֹעֵד וּמוֹעֵד. וּמַה הֵן קוֹרִין. בְּפֶסַח בְּפָרָשַׁת מוֹעֲדוֹת שֶׁבְּתוֹרַת כֹּהֲנִים. וּכְבָר נָהֲגוּ הָעָם לִקְרוֹת בְּיוֹם רִאשׁוֹן (שמות יב כא) ״מִשְׁכוּ וּקְחוּ לָכֶם״ וּמַפְטִירִין בְּ(גמרא מגילה לא א) ״פֶסַח גִּלְגָּל״. וּבְיוֹם טוֹב שֵׁנִי (ויקרא כב כז) ״שׁוֹר אוֹ כֶשֶׂב״ וּמַפְטִירִין בְּפֶסַח יֹאשִׁיָּהוּ. בַּשְּׁלִישִׁי (שמות יג ב) ״קַדֶּשׁ לִי כָל בְּכוֹר״. בָּרְבִיעִי (שמות כב כד) ״אִם כֶּסֶף תַּלְוֶה״. בַּחֲמִישִׁי (שמות לד א) ״פְּסָל לְךָ״. בְּשִׁשִּׁי (במדבר ט ב) ״וְיַעֲשׂוּ בְנֵי יִשְׂרָאֵל אֶת הַפָּסַח בְּמוֹעֲדוֹ״. בְּיוֹם טוֹב אַחֲרוֹן (שמות יג יז) ״וַיְהִי בְּשַׁלַּח״ עַד סוֹף הַשִּׁירָה עַד (שמות טו כו) ״כִּי אֲנִי ה׳‎ רֹפְאֶךָ״ וּמַפְטִירִין (שמואל ב כב א) ״וַיְדַבֵּר דָּוִד״. וּבַשְּׁמִינִי (דברים טו יט) ״כָּל הַבְּכוֹר״ וּמַפְטִירִין (ישעיה י לב) ״עוֹד הַיּוֹם״:","בַּעֲצֶרֶת קוֹרִין בְּ(דברים טז ט) ״שִׁבְעָה שָׁבוּעוֹת״. וּמִנְהָג פָּשׁוּט שֶׁקּוֹרִים בְּיוֹם טוֹב הָרִאשׁוֹן (שמות יט א) ״בַּחֹדֶשׁ הַשְּׁלִישִׁי״ וּמַפְטִירִין בְּמֶרְכָּבָה. וּבְשֵׁנִי קוֹרִין בְּפָרָשַׁת מוֹעֲדוֹת (דברים טו יט) ״כָּל הַבְּכוֹר״ וּמַפְטִירִין בַּחֲבַקּוּק:","בְּרֹאשׁ הַשָּׁנָה קוֹרִין (במדבר כט א) ״בַּחֹדֶשׁ הַשְּׁבִיעִי בְּאֶחָד לַחֹדֶשׁ״. וּמִנְהָג פָּשׁוּט שֶׁקּוֹרִין בְּיוֹם רִאשׁוֹן (בראשית כא א) ״וַיְיָ׳‎ פָּקַד אֶת שָׂרָה״ וּמַפְטִירִין (שמואל א א א) ״וַיְהִי אִישׁ אֶחָד מִן הָרָמָתַיִם״. וּבְשֵׁנִי קוֹרִין (בראשית כב א) ״וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם״ וּמַפְטִירִין (ירמיה לא יט) ״הֲבֵן יַקִּיר לִי אֶפְרַיִם״:","בְּיוֹם הַכִּפּוּרִים בְּשַׁחֲרִית קוֹרִין (ויקרא טז א) ״אַחֲרֵי מוֹת״ וּמַפְטִירִין (ישעיה נז טו) ״כֹּה אָמַר רָם וְנִשָּׂא״. בְּמִנְחָה קוֹרִין בַּעֲרָיוֹת שֶׁבְּאַחֲרֵי מוֹת כְּדֵי שֶׁיִּזְכֹּר וְיִכָּלֵם כָּל מִי שֶׁנִּכְשַׁל בְּאַחַת מֵהֶן וְיַחֲזֹר בִּתְשׁוּבָה. וְהַשְּׁלִישִׁי קוֹרֵא בַּתּוֹרָה וּמַפְטִיר בְּיוֹנָה:","בְּסֻכּוֹת בִּשְׁנֵי יָמִים טוֹבִים הָרִאשׁוֹנִים קוֹרִין בְּפָרָשַׁת הַמּוֹעֲדוֹת שֶׁהִיא (ויקרא כב כז) ״שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז״ וְגוֹ׳‎ וּמַפְטִירִין בְּיוֹם רִאשׁוֹן (זכריה יד א) ״הִנֵּה יוֹם בָּא לַיְיָ׳‎״. וּבְיוֹם שֵׁנִי (מלכים א ח ב) ״וַיִּקָּהֲלוּ אֶל הַמֶּלֶךְ שְׁלֹמֹה״. וּבְיוֹם טוֹב אַחֲרוֹן קוֹרִין (דברים טו יט) ״כָּל הַבְּכוֹר״ וּמַפְטִירִין (מלכים א ח נד) ״וַיְהִי כְּכַלּוֹת שְׁלֹמֹה״. וּלְמָחָר קוֹרִין (דברים לג א) ״וְזֹאת הַבְּרָכָה״ וּמַפְטִירִין (מלכים א ח כב) ״וַיַּעֲמֹד שְׁלֹמֹה״. וְיֵשׁ מִי שֶׁמַּפְטִירִין (יהושע א א) ״וַיְהִי אַחֲרֵי מוֹת משֶׁה״. וּבִשְׁאָר יְמוֹת הֶחָג קוֹרִין בְּקָרְבְּנוֹת הֶחָג:","כֵּיצַד. בְּכָל יוֹם וָיוֹם מֵחֻלּוֹ שֶׁל מוֹעֵד קוֹרֵא שְׁתֵּי פָּרָשִׁיּוֹת. (במדבר כט כ) ״בַּיּוֹם הַשְּׁלִישִׁי״ שֶׁהוּא חֻלּוֹ שֶׁל מוֹעֵד קוֹרֵא הַכֹּהֵן (במדבר כט יז) ״וּבַיּוֹם הַשֵּׁנִי״. וְלֵוִי קוֹרֵא וּבַיּוֹם הַשְּׁלִישִׁי. וְיִשְׂרָאֵל קוֹרֵא בַּיּוֹם הַשְּׁלִישִׁי. וְהָרְבִיעִי חוֹזֵר וְקוֹרֵא בַּיּוֹם הַשֵּׁנִי וּבַיּוֹם הַשְּׁלִישִׁי. וְכֵן בַּיּוֹם הָרְבִיעִי שֶׁהוּא שֵׁנִי שֶׁל חֻלּוֹ שֶׁל מוֹעֵד קוֹרִין וּבַיּוֹם הַשְּׁלִישִׁי (במדבר כט כג) ״וּבַיּוֹם הָרְבִיעִי״. וְעַל דֶּרֶךְ זוֹ בְּכָל יוֹם וָיוֹם:","בְּכָל יוֹם וְיוֹם מִיָּמִים טוֹבִים וְכֵן בְּיוֹם הַכִּפּוּרִים וּבְשִׁבְעַת יְמֵי הַפֶּסַח מוֹצִיאִין שְׁנֵי סְפָרִים בְּשַׁחֲרִית. הָרִאשׁוֹן קוֹרֵא בּוֹ אֵלּוּ הָעִנְיָנוֹת שֶׁאָמַרְנוּ. וְהַשֵּׁנִי קוֹרֵא בּוֹ קָרְבַּן אוֹתוֹ הַיּוֹם הָאָמוּר בְּחֻמַּשׁ הַפְּקֻדִּים בַּתּוֹרָה. וְהַקּוֹרֵא עִנְיַן הַקָּרְבָּן הוּא מַפְטִיר בַּנָּבִיא:","וּבְכָל יוֹם שֶׁמּוֹצִיאִין שְׁנֵי סְפָרִים אוֹ שְׁלֹשָׁה אִם הוֹצִיאוּ זֶה אַחַר זֶה כְּשֶׁמַּחֲזִיר אֶת הָרִאשׁוֹן אוֹמֵר קַדִּישׁ וּמוֹצִיא הַשֵּׁנִי. וּכְשֶׁמַּחֲזִיר אֶת הָאַחֲרוֹן אוֹמֵר קַדִּישׁ. וּכְבָר אָמַרְנוּ שֶׁהַמִּנְהָג הַפָּשׁוּט לוֹמַר קַדִּישׁ אַחַר שֶׁקּוֹרֵא הַמַּשְׁלִים לְעוֹלָם וְאַחַר כָּךְ מַפְטִירִין בַּנָּבִיא:","שַׁבָּת שֶׁחָלָה לִהְיוֹת בְּחֻלּוֹ שֶׁל מוֹעֵד בֵּין בְּפֶסַח בֵּין בְּסֻכּוֹת קוֹרִין בְּאוֹתָהּ שַׁבָּת (שמות לג יב) ״רְאֵה אַתָּה אֹמֵר אֵלַי״ וּמַפְטִירִין בְּפֶסַח (יחזקאל לז ד) ״הָעֲצָמוֹת הַיְבֵשׁוֹת״. וְאִם חָלָה בְּתוֹךְ הֶחָג (יחזקאל לח יח) ״בְּיוֹם בּוֹא גוֹג״:","בַּחֲנֻכָּה בְּיוֹם רִאשׁוֹן קוֹרִין מִ(במדבר ו כב) ״בִּרְכַּת כֹּהֲנִים״ עַד סוֹף קָרְבַּן (במדבר ז יב) ״הַמַּקְרִיב בַּיּוֹם הָרִאשׁוֹן״. וּבְיוֹם שֵׁנִי קוֹרִין קָרְבַּן נָשִׂיא שֶׁהִקְרִיב בְּשֵׁנִי. וְכֵן עַד יוֹם הַשְּׁמִינִי. בְּיוֹם שְׁמִינִי קוֹרִין עַד סוֹף הַקָּרְבָּנוֹת עַד סוֹף הַסֵּדֶר. וּמַפְטִירִין בְּשַׁבָּת שֶׁל חֲנֻכָּה בְּנֵרוֹת זְכַרְיָה. וְאִם הָיוּ שְׁתֵּי שַׁבָּתוֹת בַּחֲנֻכָּה מַפְטִירִין בְּשַׁבָּת רִאשׁוֹנָה בְּנֵרוֹת זְכַרְיָה. וּבַשְּׁנִיָּה בְּנֵרוֹת שְׁלֹמֹה. וְהַקּוֹרֵא בְּעִנְיַן חֲנֻכָּה הוּא שֶׁמַּפְטִיר בַּנָּבִיא. בְּפוּרִים קוֹרִין בְּשַׁחֲרִית (שמות יז ח) ״וַיָּבֹא עֲמָלֵק״:","בְּתִשְׁעָה בְּאָב קוֹרִין בְּשַׁחֲרִית (דברים ד כה) ״כִּי תוֹלִיד בָּנִים״ וּמַפְטִירִין (ירמיה ח יג) ״אָסֹף אֲסִיפֵם נְאֻם יְיָ׳‎״. וּבְמִנְחָה קוֹרִין (שמות לב יא) ״וַיְחַל משֶׁה״ כִּשְׁאָר יְמֵי הַתַּעֲנִיּוֹת. וּבִשְׁאָר הַתַּעֲנִיּוֹת שֶׁאָנוּ מִתְעֲנִין עַל מַה שֶּׁאֵרַע לַאֲבוֹתֵינוּ קוֹרִין בְּשַׁחֲרִית וּמִנְחָה. הָרִאשׁוֹן קוֹרֵא וַיְחַל משֶׁה אַרְבַּע פְּסוּקִים. וְקוֹרֵא הַשֵּׁנִי וְהַשְּׁלִישִׁי מִ(שמות לד א) ״פְּסָל לְךָ״ עַד (שמות לד י) ״אֲשֶׁר אֲנִי עשֶֹׁה עִמָּךְ״. וּבְתַעֲנִיּוֹת שֶׁגּוֹזְרִין אוֹתָן הַצִּבּוּר מִפְּנֵי הַצָּרוֹת כְּגוֹן בַּצֹּרֶת וְדֶבֶר וְכַיּוֹצֵא בָּהֶן קוֹרִין בְּרָכוֹת וּקְלָלוֹת כְּדֵי שֶׁיָּשׁוּבוּ הָעָם וְיִכָּנַע לְבָבָם כְּשֶׁיִּשְׁמְעוּ אוֹתָם:","נָהֲגוּ הָעָם לִהְיוֹת מַפְטִירִין קֹדֶם תִּשְׁעָה בְּאָב בְּשָׁלֹשׁ שַׁבָּתוֹת בְּדִבְרֵי תּוֹכָחוֹת. שַׁבָּת רִאשׁוֹנָה מַפְטִירִין בְּ(ירמיה א א) ״דִבְרֵי יִרְמְיָהוּ״. שְׁנִיָּה (ישעיה א א) ״חֲזוֹן יְשַׁעְיָהוּ״. שְׁלִישִׁית (ישעיה א כא) ״אֵיכָה הָיְתָה לְזוֹנָה״. וְכֵן שַׁבָּת שֶׁאַחַר תִּשְׁעָה בְּאָב מַפְטִירִין (ישעיה מ א) ״נַחֲמוּ נַחֲמוּ עַמִּי״. וּמִנְהָג פָּשׁוּט בְּעִירֵנוּ לִהְיוֹת מַפְטִירִין בְּנֶחָמוֹת יְשַׁעְיָהוּ מֵאַחַר תִּשְׁעָה בְּאָב עַד רֹאשׁ הַשָּׁנָה. וְשַׁבָּת שֶׁבֵּין רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מַפְטִירִין (הושע יד ב) ״שׁוּבָה יִשְׂרָאֵל״:","רֹאשׁ חֹדֶשׁ אֲדָר שֶׁחָל לִהְיוֹת בְּשַׁבָּת קוֹרִין בְּפָרָשַׁת (שמות ל יא טז) ״שְׁקָלִים״ וּמַפְטִירִין בִּ(מלכים ב יב ג) ״יהוֹיָדָע הַכֹּהֵן״. וְכֵן אִם חָל רֹאשׁ חֹדֶשׁ אֲדָר לִהְיוֹת בְּתוֹךְ הַשַּׁבָּת וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת מַקְדִּימִין וְקוֹרִין בַּשַּׁבָּת שֶׁלְּפָנָיו בְּפָרָשַׁת שְׁקָלִים. בַּשְּׁנִיָּה קוֹרִין (דברים כה יז) ״זָכוֹר״ וּמַפְטִירִין (שמואל א טו ב) ״פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק״. אֵי זוֹ הִיא שַׁבָּת שְׁנִיָּה כָּל שֶׁחָל פּוּרִים לִהְיוֹת בְּתוֹכָהּ וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת. בַּשְּׁלִישִׁית קוֹרִין (במדבר יט א) ״פָּרָה אֲדֻמָּה״ וּמַפְטִירִין (יחזקאל לו כה) ״וְזָרַקְתִּי עֲלֵיכֶם״. וְאֵי זוֹ הִיא שַׁבָּת שְׁלִישִׁית הַסְּמוּכָה לָרְבִיעִית. בָּרְבִיעִית קוֹרִין (שמות יב ב) ״הַחֹדֶשׁ הַזֶּה״ וּמַפְטִירִין (יחזקאל מה יח) ״בְּרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ״. וְאֵי זוֹ הִיא רְבִיעִית כָּל שֶׁחָל רֹאשׁ חֹדֶשׁ נִיסָן לִהְיוֹת בְּתוֹכָהּ וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת:","נִמְצֵאתָ אוֹמֵר שֶׁפְּעָמִים תִּהְיֶה הַפְסָקָה בֵּין שַׁבָּת רִאשׁוֹנָה וּשְׁנִיָּה אוֹ בֵּין שְׁנִיָּה וּשְׁלִישִׁית. וּפְעָמִים יִהְיוּ שְׁתֵּי הַפְסָקוֹת בֵּין רִאשׁוֹנָה לִשְׁנִיָּה וּבֵין שְׁנִיָּה וּשְׁלִישִׁית. אֲבָל בֵּין שְׁלִישִׁית לִרְבִיעִית אֵין מַפְסִיקִין:","כָּל פָּרָשָׁה מֵאַרְבַּע פָּרָשִׁיּוֹת הָאֵלּוּ אֶחָד קוֹרֵא אוֹתָהּ בְּסֵפֶר שֵׁנִי אַחַר שֶׁקּוֹרִין סֵדֶר אוֹתָהּ שַׁבָּת בַּסֵּפֶר שֶׁהוֹצִיאוּ רִאשׁוֹן. חָל רֹאשׁ חֹדֶשׁ אֲדָר לִהְיוֹת בְּשַׁבָּת וְהָיָה סֵדֶר אוֹתָהּ שַׁבָּת בִּ (שמות כז כ) ״וְאַתָּה תְּצַוֶּה״ קוֹרִין שִׁשָּׁה מִוְּאַתָּה תְּצַוֶּה עַד (שמות ל יח) ״וְעָשִׂיתָ כִּיּוֹר נְחשֶׁת״ וְהַשְּׁבִיעִי חוֹזֵר וְקוֹרֵא מִכִּי תִשָּׂא עַד וְעָשִׂיתָ כִּיּוֹר. וְאִם הָיָה סֵדֶר אוֹתָהּ שַׁבָּת כִּי תִשָּׂא עַצְמוֹ קוֹרִין שִׁשָּׁה מִכִּי תִשָּׂא עַד (שמות לה א) ״וַיַּקְהֵל״ וְהַשְּׁבִיעִי חוֹזֵר וְקוֹרֵא בְּסֵפֶר שֵׁנִי מִכִּי תִשָּׂא עַד וְעָשִׂיתָ כִּיּוֹר נְחשֶׁת:","רֹאשׁ חֹדֶשׁ אֲדָר שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. הָרִאשׁוֹן קוֹרֵא בּוֹ סֵדֶר הַיּוֹם. וְהַשֵּׁנִי קוֹרֵא בּוֹ עִנְיַן רֹאשׁ חֹדֶשׁ. וְהַשְּׁלִישִׁי קוֹרִין בּוֹ (שמות ל יב) ״כִּי תִשָּׂא״. וְכֵן רֹאשׁ חֹדֶשׁ נִיסָן שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. קוֹרִין סֵדֶר הַיּוֹם בָּרִאשׁוֹן. וְעִנְיַן רֹאשׁ חֹדֶשׁ בַּשֵּׁנִי. וְ(שמות יב ב) ״הַחֹדֶשׁ הַזֶּה״ בַּשְּׁלִישִׁי:","רֹאשׁ חֹדֶשׁ טֵבֵת שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. הָרִאשׁוֹן קוֹרֵא בּוֹ סֵדֶר הַיּוֹם. וְהַשֵּׁנִי קוֹרֵא בּוֹ עִנְיַן רֹאשׁ חֹדֶשׁ. וְהַשְּׁלִישִׁי קוֹרֵא בּוֹ עִנְיַן חֲנֻכָּה. חָל לִהְיוֹת בְּאֶמְצַע הַשַּׁבָּת שְׁלֹשָׁה קוֹרִין בְּעִנְיַן רֹאשׁ חֹדֶשׁ וְהָרְבִיעִי קוֹרֵא בְּעִנְיַן חֲנֻכָּה:","אַף עַל פִּי שֶׁאָדָם שׁוֹמֵעַ כָּל הַתּוֹרָה כֻּלָּהּ בְּכָל שַׁבָּת בַּצִּבּוּר חַיָּב לִקְרוֹת לְעַצְמוֹ בְּכָל שָׁבוּעַ וְשָׁבוּעַ סֵדֶר שֶׁל אוֹתָהּ שַׁבָּת שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם. וּפָסוּק שֶׁאֵין בּוֹ תַּרְגּוּם קוֹרְאֵהוּ שָׁלֹשׁ פְּעָמִים עַד שֶׁיַּשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר:"],"Mishneh Torah, Reading the Shema 2":["הַקּוֹרֵא אֶת שְׁמַע וְלֹא כִּוֵּן לִבּוֹ בְּפָסוּק רִאשׁוֹן שֶׁהוּא (דברים ו ד) ״שְׁמַע יִשְׂרָאֵל״ לֹא יָצָא יְדֵי חוֹבָתוֹ וְהַשְּׁאָר אִם לֹא כִּוֵּן לִבּוֹ יָצָא. אֲפִלּוּ הָיָה קוֹרֵא בַּתּוֹרָה כְּדַרְכּוֹ אוֹ מַגִּיהַּ אֶת הַפָּרָשִׁיּוֹת הָאֵלּוּ בְּעוֹנַת קְרִיאָה יָצָא וְהוּא שֶׁכִּוֵּן לִבּוֹ בְּפָסוּק רִאשׁוֹן:","כָּל אָדָם קוֹרִין כְּדַרְכָּן בֵּין עוֹמְדִין בֵּין מְהַלְּכִין בֵּין שׁוֹכְבִין בֵּין רוֹכְבִין עַל גַּבֵּי בְּהֵמָה. וְאָסוּר לִקְרוֹת קְרִיאַת שְׁמַע וְהוּא מֻטָּל וּפָנָיו טוּחוֹת בַּקַּרְקַע אוֹ מֻשְׁלָךְ עַל גַּבּוֹ וּפָנָיו לְמַעְלָה. אֲבָל קוֹרֵא הוּא וְהוּא שׁוֹכֵב עַל צִדּוֹ. וְאִם הָיָה בַּעַל בָּשָׂר הַרְבֵּה וְאֵינוֹ יָכוֹל לְהִתְהַפֵּךְ עַל צִדּוֹ אוֹ שֶׁהָיָה חוֹלֶה נוֹטֶה מְעַט לְצִדּוֹ וְקוֹרֵא:","מִי שֶׁהָיָה מְהַלֵּךְ עַל רַגְלָיו עוֹמֵד בְּפָסוּק רִאשׁוֹן וְהַשְּׁאָר קוֹרֵא וְהוּא מְהַלֵּךְ. הָיָה יָשֵׁן מְצַעֲרִין אוֹתוֹ וּמְעִירִין אוֹתוֹ עַד שֶׁיִּקְרָא פָּסוּק רִאשׁוֹן וּמִכָּאן וְאֵילָךְ אִם אֲנָסַתּוּ שֵׁנָה אֵין מְצַעֲרִין אוֹתוֹ:","מִי שֶׁהָיָה עוֹסֵק בִּמְלָאכָה מַפְסִיק עַד שֶׁיִּקְרָא פָּרָשָׁה רִאשׁוֹנָה כֻּלָּהּ. וְכֵן הָאֻמָּנִין בְּטֵלִין מִמְּלַאכְתָּן בְּפָרָשָׁה רִאשׁוֹנָה כְּדֵי שֶׁלֹּא תְּהֵא קְרִיאָתָן עַרְאַי, וְהַשְּׁאָר קוֹרֵא הוּא כְּדַרְכּוֹ וְעוֹסֵק בִּמְלַאכְתּוֹ. אֲפִלּוּ הָיָה עוֹמֵד בְּרֹאשׁ הָאִילָן אוֹ בְּרֹאשׁ הַכֹּתֶל קוֹרֵא בִּמְקוֹמוֹ וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ:","הָיָה עוֹסֵק בְּתַלְמוּד תּוֹרָה וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע פּוֹסֵק וְקוֹרֵא וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ. הָיָה עוֹסֵק בְּצָרְכֵי רַבִּים לֹא יִפְסֹק אֶלָּא יִגְמֹר עִסְקֵיהֶן וְיִקְרָא אִם נִשְׁאָר עֵת לִקְרוֹת:","הָיָה עוֹסֵק בַּאֲכִילָה אוֹ שֶׁהָיָה בַּמֶּרְחָץ אוֹ שֶׁהָיָה עוֹסֵק בְּתִסְפֹּרֶת אוֹ שֶׁהָיָה מְהַפֵּךְ בְּעוֹרוֹת אוֹ שֶׁהָיוּ עוֹסְקִין בַּדִּין גּוֹמֵר וְאַחַר כָּךְ קוֹרֵא קְרִיאַת שְׁמַע. וְאִם הָיָה מִתְיָרֵא שֶׁמָּא יַעֲבֹר זְמַן קְרִיאָה וּפָסַק וְקָרָא הֲרֵי זֶה מְשֻׁבָּח:","מִי שֶׁיָּרַד לִטְבּל אִם יָכוֹל לַעֲלוֹת וּלְהִתְכַּסּוֹת קֹדֶם שֶׁתָּנֵץ הַחַמָּה יַעֲלֶה וְיִתְכַּסֶּה וְיִקְרָא. וְאִם הָיָה מִתְיָרֵא שֶׁמָּא תָּנֵץ הַחַמָּה קֹדֶם שֶׁיִּקְרָא יִתְכַּסֶּה בַּמַּיִם שֶׁהוּא עוֹמֵד בָּהֶן וְיִקְרָא. וְלֹא יִתְכַּסֶּה לֹא בַּמַּיִם הָרָעִים שֶׁרֵיחָן רַע וְלֹא בְּמֵי הַמִּשְׁרֶה וְלֹא בְּמַיִם צְלוּלִין מִפְּנֵי שֶׁעֶרְוָתוֹ נִרְאֵית בָּהֶן. אֲבָל מִתְכַּסֶּה הוּא בְּמַיִם עֲכוּרִין שֶׁאֵין רֵיחָן רַע וְקוֹרֵא בִּמְקוֹמוֹ:","הַקּוֹרֵא קְרִיאַת שְׁמַע לֹא יִרְמֹז בְּעֵינָיו וְלֹא יִקְרֹץ בִּשְׂפָתָיו וְלֹא יַרְאֶה בְּאֶצְבְּעוֹתָיו כְּדֵי שֶׁלֹּא תִּהְיֶה קְרִיאָתוֹ עַרְאַי. וְאִם עָשָׂה כֵּן אַף עַל פִּי שֶׁיָּצָא יְדֵי חוֹבָתוֹ הֲרֵי זֶה מְגֻנֶּה. וְצָרִיךְ לְהַשְׁמִיעַ לְאָזְנוֹ כְּשֶׁהוּא קוֹרֵא וְאִם לֹא הִשְׁמִיעַ לְאָזְנוֹ יָצָא. וְצָרִיךְ לְדַקְדֵּק בְּאוֹתִיּוֹתָיו וְאִם לֹא דִּקְדֵּק יָצָא:","כֵּיצַד יְדַקְדֵּק. יִשְׁמֹר שֶׁלֹּא יַרְפֶּה הֶחָזָק וְלֹא יַחֲזִיק הֲרָפֶה וְלֹא יָנִיחַ הַנָּד וְלֹא יָנִיד הַנָּח. לְפִיכָךְ צָרִיךְ לִתֵּן רֶוַח בֵּין הַדְּבָקִים בֵּין כָּל שְׁתֵּי אוֹתִיּוֹת הַדּוֹמוֹת שֶׁאַחַת מֵהֶן סוֹף תֵּבָה וְהָאַחֶרֶת תְּחִלַּת תֵּבָה הַסְּמוּכָה לָהּ. כְּגוֹן בְּכָל לְבָבְךָ קוֹרֵא בְּכָל וְשׁוֹהֶה וְחוֹזֵר וְקוֹרֵא לְבָבְךָ. וְכֵן וַאֲבַדְתֶּם מְהֵרָה. הַכָּנָף פְּתִיל. וְצָרִיךְ לְבָאֵר זַיִ״ן שֶׁל תִּזְכְּרוּ. וְצָרִיךְ לְהַאֲרִיךְ בְּדָלֶ״ת שֶׁל אֶחָד כְּדֵי שֶׁיַּמְלִיכֵהוּ בַּשָּׁמַיִם וּבָאָרֶץ וּבְאַרְבַּע רוּחוֹת. וְצָרִיךְ שֶׁלֹּא יַחְטֹף בַּחֵי״ת כְּדֵי שֶׁלֹּא יְהֵא כְּאוֹמֵר אֵי חָד:","קוֹרֵא אָדָם אֶת שְׁמַע בְּכָל לָשׁוֹן שֶׁיִּהְיֶה מְבִינָהּ. וְהַקּוֹרֵא בְּכָל לָשׁוֹן צָרִיךְ לְהִזָּהֵר מִדִּבְרֵי שִׁבּוּשׁ שֶׁבְּאוֹתוֹ הַלָּשׁוֹן וּמְדַקְדֵּק בְּאוֹתוֹ הַלָּשׁוֹן כְּמוֹ שֶׁמְּדַקְדֵּק בִּלְשׁוֹן הַקֹּדֶשׁ:","הַקּוֹרֵא לְמַפְרֵעַ לֹא יָצָא. בַּמֶּה דְּבָרִים אֲמוּרִים בְּסֵדֶר הַפְּסוּקִים אֲבָל אִם הִקְדִּים פָּרָשָׁה לְפָרָשָׁה אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי אֲנִי אוֹמֵר שֶׁיָּצָא לְפִי שֶׁאֵינָהּ סְמוּכָה לָהּ בַּתּוֹרָה. קָרָא פָּסוּק וְחָזַר וּקְרָאוֹ פַּעַם שְׁנִיָּה הֲרֵי זֶה מְגֻנֶּה. קָרָא מִלָּה אַחַת וּכְפָלָהּ כְּגוֹן שֶׁקָּרָא שְׁמַע שְׁמַע מְשַׁתְּקִין אוֹתוֹ:","קְרָאָהּ סֵרוּגִין יָצָא. אֲפִלּוּ שָׁהָה בֵּין סֵרוּג לְסֵרוּג כְּדֵי לִגְמֹר אֶת כֻּלָּהּ יָצָא. וְהוּא שֶׁיִּקְרָא עַל הַסֵּדֶר. קְרָאָהּ מִתְנַמְנֵם וְהוּא מִי שֶׁאֵינוֹ עֵר וְלֹא נִרְדָּם בְּשֵׁנָה יָצָא. וּבִלְבַד שֶׁיִּהְיֶה עֵר בְּפָסוּק רִאשׁוֹן:","סָפֵק קָרָא קְרִיאַת שְׁמַע סָפֵק לֹא קָרָא חוֹזֵר וְקוֹרֵא וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ. אֲבָל אִם יָדַע שֶׁקָּרָא וְנִסְתַּפֵּק לוֹ אִם בֵּרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ אוֹ לֹא בֵּרֵךְ אֵינוֹ חוֹזֵר וּמְבָרֵךְ. קָרָא וְטָעָה יַחֲזֹר לַמָּקוֹם שֶׁטָּעָה. נֶעֱלַם מִמֶּנּוּ בֵּין פָּרָשָׁה לְפָרָשָׁה וְאֵינוֹ יוֹדֵעַ אֵי זוֹ פָּרָשָׁה הִשְׁלִים וְאֵי זוֹ צָרִיךְ לְהַתְחִיל חוֹזֵר לְפָרָשָׁה רִאשׁוֹנָה שֶׁהוּא (דברים ו ה) ״וְאָהַבְתָּ אֵת יְיָ׳‎ אֱלֹהֶיךָ״ וְגוֹ׳‎:","טָעָה בְּאֶמְצַע הַפֶּרֶק וְאֵינוֹ יוֹדֵעַ לְהֵיכָן פָּסַק חוֹזֵר לְרֹאשׁ הַפֶּרֶק. הָיָה קוֹרֵא וּכְתַבְתָּם וְאֵינוֹ יוֹדֵעַ אִם הוּא בְּוּכְתַבְתָּם שֶׁל שְׁמַע אוֹ בְּוּכְתַבְתָּם שֶׁבִּוְהָיָה אִם שָׁמוֹעַ חוֹזֵר לְוּכְתַבְתָּם שֶׁל שְׁמַע. וְאִם נִסְתַּפֵּק לוֹ אַחַר שֶׁקָּרָא לְמַעַן יִרְבּוּ יְמֵיכֶם אֵינוֹ חוֹזֵר שֶׁעַל הֶרְגֵּל לְשׁוֹנוֹ הוּא הוֹלֵךְ:","הָיָה קוֹרֵא וּפָגַע בַּאֲחֵרִים אוֹ פָּגְעוּ בּוֹ אֲחֵרִים. אִם הָיָה בֵּין פֶּרֶק לְפֶרֶק פּוֹסֵק וּמַתְחִיל וְשׁוֹאֵל שְׁלוֹם מִי שֶׁהוּא חַיָּב בִּכְבוֹדוֹ כְּגוֹן שֶׁפָּגַע בְּאָבִיו אוֹ רַבּוֹ אוֹ מִי שֶׁהוּא גָּדוֹל מִמֶּנּוּ בְּחָכְמָה. וּמֵשִׁיב שָׁלוֹם לְכָל אָדָם שֶׁנָּתַן לוֹ שָׁלוֹם:","הָיָה קוֹרֵא בְּאֶמְצַע הַפָּרָשָׁה אֵינוֹ פּוֹסֵק וּמַתְחִיל לִשְׁאל אֶלָּא בִּשְׁלוֹם מִי שֶׁהוּא מִתְיָרֵא מִמֶּנּוּ כְּגוֹן מֶלֶךְ אוֹ אַנָּס וְכַיּוֹצֵא בָּהֶן. אֲבָל מִי שֶׁהוּא חַיָּב בִּכְבוֹדוֹ כְּגוֹן אָבִיו אוֹ רַבּוֹ אִם נָתַן לוֹ שָׁלוֹם תְּחִלָּה פּוֹסֵק וּמֵשִׁיב לוֹ שָׁלוֹם:","וְאֵלּוּ הֵן בֵּין הַפְּרָקִים. בֵּין בְּרָכָה רִאשׁוֹנָה לַשְּׁנִיָּה. בֵּין שְׁנִיָּה לִשְׁמַע. בֵּין שְׁמַע לִוְהָיָה אִם שָׁמֹעַ. בֵּין וְהָיָה אִם שָׁמֹעַ לְוַיֹּאמֶר. בֵּין הַפְּרָקִים הָאֵלּוּ שׁוֹאֵל מִפְּנֵי הַכָּבוֹד וּמֵשִׁיב שָׁלוֹם לְכָל אָדָם. אֲבָל בֵּין וַיֹּאמֶר לֶאֱמֶת וְיַצִּיב הֲרֵי זֶה כְּאֶמְצַע הַפֶּרֶק וְלֹא יַפְסִיק אֶלָּא לִשְׁאל מִפְּנֵי הַיִּרְאָה וּלְהָשִׁיב מִפְּנֵי הַכָּבוֹד:"],"Mishneh Torah, Red Heifer 11":["כֵּיצַד מְטַהֲרִים טְמֵא מֵת בְּמֵי נִדָּה. לוֹקֵחַ אָדָם טָהוֹר שְׁלֹשָׁה קְלָחִין שֶׁל אֵזוֹב וְאוֹגְדָן אֲגוּדָה אַחַת וּבְכָל בַּד וּבַד גִּבְעוֹל אֶחָד וְטוֹבֵל רָאשֵׁי גִּבְעוֹלִין בְּמֵי נִדָּה שֶׁבַּכְּלִי וּמִתְכַּוֵּן וּמַזֶּה עַל הָאָדָם אוֹ עַל הַכֵּלִים בַּיּוֹם הַשְּׁלִישִׁי וּבַיּוֹם הַשְּׁבִיעִי אַחַר שֶׁתָּנֵץ הַחַמָּה. וְאִם הִזָּה מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר כָּשֵׁר. וְאַחַר שֶׁיַּזֶּה עָלָיו בַּיּוֹם הַשְּׁבִיעִי טוֹבֵל בַּיּוֹם וּמַעֲרִיב שִׁמְשׁוֹ וַהֲרֵי הוּא טָהוֹר לָעֶרֶב. טָבַל אֶת הָאֵזוֹב בַּלַּיְלָה וְהִזָּה בַּיּוֹם אוֹ שֶׁטָּבַל אֶת הָאֵזוֹב בַּיּוֹם וְהִזָּה בַּלַּיְלָה הַזָּאָתוֹ פְּסוּלָה וְהַמַּיִם מְטַמְּאִין מִשּׁוּם מֵי חַטָּאת כְּמוֹ שֶׁיִּתְבָּאֵר. עַד שֶׁתִּהְיֶה טְבִילַת הָאֵזוֹב בַּמַּיִם וְהַזָּאָתוֹ מִמֶּנּוּ בַּיּוֹם הַשְּׁלִישִׁי וּבַיּוֹם הַשְּׁבִיעִי אַחַר שֶׁתָּנֵץ הַחַמָּה וְאִם עָבַר וְעָשָׂה מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר כָּשֵׁר כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁנִּטְמָא בְּמֵת וְשָׁהָה כַּמָּה יָמִים בְּלֹא הַזָּאָה כְּשֶׁיָּבוֹא לְהַזּוֹת מוֹנֶה בְּפָנֵינוּ שְׁלֹשָׁה יָמִים וּמַזִּין עָלָיו בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי וְטוֹבֵל בַּשְּׁבִיעִי וּמַעֲרִיב שִׁמְשׁוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעַם הָאָרֶץ שֶׁבָּא לְהַזּוֹת שֶׁאֲפִלּוּ אָמַר הַיּוֹם שְׁלִישִׁי שֶׁלִּי אֵינוֹ נֶאֱמָן שֶׁמָּא הַיּוֹם נִטְמָא לְפִיכָךְ צָרִיךְ לִמְנוֹת בְּפָנֵינוּ. אֲבָל חָבֵר שֶׁבָּא לְהַזּוֹת מַזִּין עָלָיו אוֹ עַל כֵּלָיו מִיָּד. מִי שֶׁהֻזָּה עָלָיו בַּשְּׁלִישִׁי וְלֹא הֻזָּה עָלָיו בַּשְּׁבִיעִי וְשָׁהָה כַּמָּה יָמִים טוֹבֵל בְּכָל עֵת שֶׁיִּרְצֶה אַחַר הַשְּׁבִיעִי בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה וּמַזִּין עָלָיו בַּיּוֹם בֵּין קֹדֶם טְבִילָה בֵּין אַחַר טְבִילָה אֲפִלּוּ טָבַל בְּלֵיל תְּשִׁיעִי אוֹ בְּלֵיל עֲשִׂירִי מַזִּין עָלָיו לְמָחָר אַחַר הָנֵץ הַחַמָּה:","כָּל הַמְטַמְּאִין מְקַבְּלִין הַזָּאָה. כֵּיצַד. זָבִים וְזָבוֹת נִדּוֹת וְיוֹלְדוֹת שֶׁנִּטְמְאוּ בְּמֵת מַזִּין עֲלֵיהֶן בַּשְּׁלִישִׁי וּשְׁבִיעִי וַהֲרֵי הֵם טְהוֹרִין מִטֻּמְאַת מֵת אַף עַל פִּי שֶׁהֵן טְמֵאִין טֻמְאָה אַחֶרֶת. שֶׁנֶּאֱמַר (במדבר יט יט) \"וְהִזָּה הַטָּהֹר עַל הַטָּמֵא בַּיּוֹם הַשְּׁלִישִׁי\" הָא לָמַדְתָּ שֶׁהַזָּיָה מוֹעֶלֶת לוֹ אַף עַל פִּי שֶׁהוּא טָמֵא. וְכֵן הֶעָרֵל מְקַבֵּל הַזָּאָה. כֵּיצַד. עָרֵל שֶׁנִּטְמָא בְּמֵת וְהִזָּה עָלָיו שְׁלִישִׁי וּשְׁבִיעִי הֲרֵי זֶה טָהוֹר מִטֻּמְאַת מֵת. וּכְשֶׁיָּמוּל טוֹבֵל וְאוֹכֵל בְּקָדָשִׁים לָעֶרֶב:","מִצְוַת אֵזוֹב שְׁלֹשָׁה קְלָחִין וְכָל קֶלַח וְקֶלַח גִּבְעוֹל אֶחָד. נִמְצְאוּ שְׁלֹשָׁה גִּבְעוֹלִין. וּשְׁיָרָיו שְׁנַיִם. אוֹ אִם לָקַח שְׁנַיִם בַּתְּחִלָּה וַאֲגָדָן כָּשֵׁר. נִתְפָּרְדוּ הַגִּבְעוֹלִין וְנָשְׁרוּ הֶעָלִין אֲפִלּוּ לֹא נִשְׁאַר מִכָּל גִּבְעוֹל מֵהֶם אֶלָּא כָּל שֶׁהוּא כָּשֵׁר שֶׁשְּׁיָרֵי הָאֵזוֹב בְּכָל שֶׁהוּא. קֶלַח שֶׁיֵּשׁ בּוֹ שְׁלֹשָׁה בַּדִּין מְפַסְּקוֹ וְאַחַר כָּךְ אוֹגֵד שְׁלָשְׁתָּן שֶׁמִּצְוָתוֹ לִהְיוֹת אֲגֻדָּה אַף עַל פִּי שֶׁלֹּא נִתְפָּרֵשׁ בַּתּוֹרָה שֶׁיִּהְיֶה אֲגֻדָּה. פְּסָקוֹ וְלֹא אֲגָדוֹ אוֹ שֶׁאֲגָדוֹ וְלֹא פְּסָקוֹ אוֹ שֶׁלֹּא פְּסָקוֹ וְלֹא אֲגָדוֹ וְהִזָּה בּוֹ כָּשֵׁר. הָאֵזוֹב הַקָּצָר אוֹגְדוֹ בְּחוּט עַל הַכּוּשׁ וְכַיּוֹצֵא בּוֹ וְטוֹבֵל בְּמַיִם וּמַעֲלֶה וְאוֹחֵז בָּאֵזוֹב וּמַזֶּה. נִסְתַּפֵּק לוֹ אִם מִן הַחוּט הִזָּה אוֹ מִן הַכּוּשׁ אוֹ מִן הַגִּבְעוֹל הַזָּאָתוֹ פְּסוּלָה:","אֵין מַזִּין לֹא בְּיוֹנְקוֹת הָאֵזוֹב וְלֹא בַּתְּמָרוֹת אֶלָּא בַּגִּבְעוֹלִין. אֵלּוּ הֵן הַיּוֹנְקוֹת גִּבְעוֹלִין שֶׁלֹּא גָּמְלוּ. וּמִי שֶׁהֻזָּה עָלָיו בְּיוֹנְקוֹת וְנִכְנַס לַמִּקְדָּשׁ פָּטוּר. וּמֵאֵימָתַי מַזִּין בָּאֵזוֹב מִשֶּׁיָּנֵץ. וְאֵזוֹב שֶׁהֻזָּה בּוֹ מֵי נִדָּה כָּשֵׁר לְטַהֵר בּוֹ אֶת הַמְצֹרָע. כָּל אֵזוֹב שֶׁיֵּשׁ לוֹ שֵׁם לְוַוי פָּסוּל. וְהָאֵזוֹב שֶׁקּוֹרִין אוֹתוֹ אֵזוֹב בְּיִחוּד הוּא הַכָּשֵׁר וְהוּא הָאֵזוֹב שֶׁאוֹכְלִין אוֹתוֹ בַּעֲלֵי בָּתִּים. אֲבָל זֶה שֶׁקּוֹרִין אוֹתוֹ אֵזוֹב יוֹן וְאֵזוֹב כַּחְלִית וְאֵזוֹב מִדְבָּרִי פָּסוּל:","אֵזוֹב שֶׁל אֲשֵׁרָה וְשֶׁל עִיר הַנִּדַּחַת וְשֶׁל עֲבוֹדָה זָרָה וְשֶׁל תְּרוּמָה טְמֵאָה פְּסוּלָה. שֶׁל תְּרוּמָה טְהוֹרָה לֹא יַזֶּה וְאִם הִזָּה כָּשֵׁר:","אֵזוֹב שֶׁלִּקְּטוֹ לְעֵצִים וְנָפְלוּ עָלָיו מַשְׁקִין מְנַגְּבוֹ וְהוּא כָּשֵׁר לְהַזָּיָה. לִקְּטוֹ לָאֳכָלִין וְנָפְלוּ עָלָיו מַשְׁקִין אַף עַל פִּי שֶׁנִּגְּבוֹ פָּסוּל שֶׁהֲרֵי נִטְמָא לְהַזָּיָה שֶׁכָּל הַמַּשְׁקִין וְכָל הָאֳכָלִין וְכָל הַכֵּלִים הֲרֵי הֵן כִּטְמֵאִים לְעִנְיַן חַטָּאת כְּמוֹ שֶׁבֵּאַרְנוּ. לִקְּטוֹ לְחַטָּאת הֲרֵי זֶה כְּנִלְקָט לְעֵצִים וְאִם נָפְלוּ עָלָיו מַשְׁקִין מְנַגְּבוֹ וּמַזֶּה בּוֹ:"],"Mishneh Torah, Red Heifer 9":["כֵּיצַד מְקַדְּשִׁין אֶת הַמַּיִם בְּאֵפֶר הַפָּרָה. נוֹתֵן אֶת הַמַּיִם שֶׁנִּתְמַלְּאוּ לְשֵׁם מֵי חַטָּאת בַּכְּלִי וְנוֹתֵן אֵפֶר עַל פְּנֵי הַמַּיִם כְּדֵי שֶׁיֵּרָאֶה עַל פְּנֵי הַמַּיִם. אַף עַל פִּי שֶׁהִיא חָבִית גְּדוֹלָה מְלֵאָה מַיִם. וּמְעָרֵב הַכּל. וְאִם נָתַן הָאֵפֶר תְּחִלָּה וְאַחַר כָּךְ נָתַן עָלָיו הַמַּיִם פָּסַל. וּמַהוּ זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (במדבר יט יז) \"וְנָתַן עָלָיו מַיִם חַיִּים\". כְּדֵי לְעָרֵב אֶת הָאֵפֶר בַּמַּיִם:","הַמְקַדֵּשׁ צָרִיךְ שֶׁיִּתְכַּוֵּן וְיִתֶּן הָאֵפֶר בְּיָדוֹ עַל הַמַּיִם שֶׁנֶּאֱמַר (במדבר יט יז) \"וְלָקְחוּ לַטָּמֵא\" עַד שֶׁיִּהְיֶה מִתְכַּוֵּן לְקִדּוּשׁ וּלְמִלּוּי וּלְהַזָּיָה. אֲבָל אִם נָפַל הָאֵפֶר מִן הַכְּלִי שֶׁיֵּשׁ בּוֹ הָאֵפֶר לְתוֹךְ הַמַּיִם. אוֹ שֶׁנָּטַל הָאֵפֶר בְּיָדוֹ וּדְחָפוֹ חֲבֵרוֹ אוֹ הָרוּחַ וְנָפַל הָאֵפֶר מִיָּדוֹ עַל הַמַּיִם. אוֹ שֶׁנָּפַל הָאֵפֶר מִיָּדוֹ עַל צַד הַכְּלִי אוֹ עַל יָדוֹ וְאַחַר כָּךְ נָפַל לַמַּיִם הֲרֵי זֶה פָּסוּל:","קִדֵּשׁ פָּחוֹת מִכְּדֵי הַזָּאָה בִּכְלִי זֶה וּפָחוֹת מִכְּדֵי הַזָּאָה בִּכְלִי אַחֵר לֹא נִתְקַדְּשׁוּ. הָיָה הָאֵפֶר צָף עַל פְּנֵי הַמַּיִם וְכָנַס מִמֶּנּוּ מִלְּמַעְלָה וְקִדֵּשׁ בּוֹ מַיִם אֲחֵרִים הֲרֵי אֵלּוּ מְקֻדָּשִׁין. וְכָל שֶׁנָּגַע בַּמַּיִם אֵין מְקַדְּשִׁין בּוֹ פַּעַם שְׁנִיָּה וְאַף עַל פִּי שֶׁנִּגְּבוֹ. וַאֲפִלּוּ נָשְׁבָה הָרוּחַ וְנָתְנָה אֶת הָאֵפֶר עַל גַּבֵּי הַמַּיִם אֵינוֹ מְנַגְּבוֹ וּמְקַדֵּשׁ בּוֹ:","כְּלִי קָטָן שֶׁהָיָה בְּתוֹךְ כְּלִי גָּדוֹל וְהֵן מְלֵאִין מַיִם וְהַמַּיִם מְעֹרָבִין כֵּיוָן שֶׁנָּתַן הָאֵפֶר בַּמַּיִם שֶׁבַּכְּלִי הַגָּדוֹל נִתְקַדְּשׁוּ כָּל הַמַּיִם שֶׁבְּתוֹךְ הַכְּלִי הַקָּטָן. וְאַף עַל פִּי שֶׁהָיָה פִּיו צַר בְּיוֹתֵר וְלֹא נִכְנַס לוֹ אֵפֶר שֶׁהֲרֵי הַמַּיִם כֻּלָּן מְעֹרָבִין:","הָיָה סְפוֹג בְּתוֹךְ הַמַּיִם בְּעֵת שֶׁנָּתַן הָאֵפֶר הֲרֵי הַמַּיִם שֶׁבַּסְּפוֹג פְּסוּלִין מִפְּנֵי שֶׁאֵינָן בַּכְּלִי. כֵּיצַד יַעֲשֶׂה. זוֹלֵף אֶת כָּל הַמַּיִם עַד שֶׁמַּגִּיעַ לַסְּפוֹג וְלֹא יִגַּע בַּסְּפוֹג. וְאִם נָגַע בַּסְּפוֹג אַף עַל פִּי שֶׁהַמַּיִם צָפִין עַל גַּבָּיו כָּל שֶׁהֵן פְּסוּלִין. מִפְּנֵי שֶׁהַמַּיִם שֶׁבַּסְּפוֹג יוֹצְאִין וּמִתְעָרְבִין בַּמַּיִם הַכְּשֵׁרִין. נָפַל סְפוֹג לְתוֹךְ הַמַּיִם הַמְקֻדָּשִׁין נוֹטְלוֹ וְסוֹחֲטוֹ חוּץ לַכְּלִי וְהַמַּיִם שֶׁבַּכְּלִי כְּשֵׁרִין:","שְׁתֵּי שְׁקָתוֹת שֶׁבְּאֶבֶן אַחַת שֶׁנָּתַן אֶת הָאֵפֶר לְתוֹךְ אַחַת מֵהֵן אֵין הַמַּיִם שֶׁבַּשְּׁנִיָּה מְקֻדָּשִׁין. וְאִם הָיוּ נְקוּבוֹת זוֹ לְזוֹ כִּשְׁפוֹפֶרֶת הַנּוֹד אוֹ שֶׁהָיוּ הַמַּיִם צָפִין עַל גַּבֵּיהֶן אֲפִלּוּ כִּקְלִפַּת הַשּׁוּם וְנָתַן אֵפֶר לְאַחַת מֵהֵן הֲרֵי הַמַּיִם שֶׁבַּשְּׁנִיָּה מְקֻדָּשִׁין:","שְׁתֵּי אֲבָנִים שֶׁהִקִּיפָן זוֹ לְזוֹ וַעֲשָׂאָן שֹׁקֶת וְכֵן שְׁתֵּי עֲרֵבוֹת. וְכֵן שֹׁקֶת שֶׁנֶּחְלְקָה וְנָתַן אֵפֶר בְּחֵלֶק אֶחָד מֵהֶן. הַמַּיִם שֶׁבֵּינֵיהֶן אֵינָן מְקֻדָּשִׁין. וְאִם חִבְּרָן בְּסִיד אוֹ בְּגַפְסִיס וְהֵם יְכוֹלוֹת לְהִנָּטֵל כְּאַחַת הַמַּיִם שֶׁבֵּינֵיהֶן מְקֻדָּשִׁין:","מַיִם מְקֻדָּשִׁין שֶׁנִּתְעָרְבוּ בָּהֶן מַיִם אֲחֵרִים כָּל שֶׁהוּא אֲפִלּוּ מַיִם שֶׁנִּתְמַלְּאוּ לְקִדּוּשׁ הֲרֵי אֵלּוּ פְּסוּלִין. וְכֵן אִם יָרַד לְתוֹכָן טַל הֲרֵי אֵלּוּ פְּסוּלִין. נָפַל לְתוֹכָן מַשְׁקִין וּמֵי פֵּרוֹת יְעָרֶה הַכּל וְצָרִיךְ לְנַגֵּב הַכְּלִי וְאַחַר כֵּן יִתֵּן לְתוֹכוֹ מַיִם מְקֻדָּשִׁין אֲחֵרִים. נָפַל לְתוֹכָן דְּיוֹ קוֹמוֹס וְקַנְקַנְתּוֹם וְכָל דָּבָר שֶׁהוּא רוֹשֵׁם יְעָרֶה וְאֵין צָרִיךְ לְנַגֵּב. שֶׁאִם יִשָּׁאֵר שָׁם דָּבָר הָרוֹשֵׁם הֲרֵי הוּא נִרְאֶה:","הַמַּטְבִּיל כְּלִי לְחַטָּאת בְּמַיִם שֶׁאֵינָן רְאוּיִין לְקַדֵּשׁ צָרִיךְ לְנַגֵּב וְאַחַר כָּךְ יְקַדֵּשׁ בּוֹ. הִטְבִּילוֹ בְּמַיִם הָרְאוּיִין לְקַדֵּשׁ אֵינוֹ צָרִיךְ לְנַגֵּב. וְאִם הִטְבִּילוֹ לֶאֱסֹף בּוֹ מַיִם מְקֻדָּשִׁין בֵּין כָּךְ וּבֵין כָּךְ צָרִיךְ לְנַגֵּב:","קֵרוּיָה שֶׁהִטְבִּילָהּ בְּמַיִם הָרְאוּיִין לְקַדֵּשׁ מְקַדְּשִׁין בָּהּ. אֲבָל אֵין אוֹסְפִין לְתוֹכָהּ מֵי חַטָּאת מִפְּנֵי שֶׁהַמַּיִם שֶׁהֻטְבְּלָה בָּהֶן נִבְלָעִים בְּתוֹכָהּ וְיוֹצְאִין וּמִתְעָרְבִין בְּמֵי חַטָּאת וּפוֹסְלִין אוֹתָן. נִטְמֵאת וְהִטְבִּילוּהָ אֵין מְקַדְּשִׁין בָּהּ שֶׁהַמַּשְׁקִין הַטְּמֵאִין הַנִּבְלָעִין בְּגוּפָהּ יֵצְאוּ וְיִתְעָרְבוּ בַּמַּיִם שֶׁמְּקַדְּשִׁין אוֹתָן בְּתוֹכָהּ:","מַיִם מְקֻדָּשִׁין שֶׁנָּפַל לְתוֹכָן שְׁקָצִים וּרְמָשִׂים וְנִתְבַּקְּעוּ אוֹ שֶׁנִּשְׁתַּנּוּ מַרְאֵיהֶן פְּסוּלִין. אֲפִילּוּ הָיוּ יְבֵשִׁים בְּיוֹתֵר כְּגוֹן הַנְּמָלָה וְהָרִירָה וְהַכִּנָּה שֶׁבַּתְּבוּאָה. נָתַן לְתוֹכָהּ חִפּוּשִׁין אַף עַל פִּי שֶׁלֹּא נִתְבַּקְּעוּ וְלֹא נִשְׁתַּנּוּ מַרְאֵיהֶן הֲרֵי הַמַּיִם פְּסוּלִין מִפְּנֵי שֶׁהִיא כִּשְׁפוֹפֶרֶת וְהַמַּיִם נִכְנָסִין בְּתוֹכָהּ וְיוֹצְאִין מִתּוֹכָהּ עִם הַלֵּחָה שֶׁבָּהּ:","מַיִם מְקֻדָּשִׁין שֶׁשָּׁתָה מֵהֶן בְּהֵמָה אוֹ חַיָּה פְּסוּלִין. וְכֵן כָּל הָעוֹפוֹת פְּסוּלִין חוּץ מִן הַיּוֹנָה מִפְּנֵי שֶׁהִיא מוֹצֶצֶת וְאֵין רִיר יוֹצֵא מִפִּיהָ וּמִתְעָרֵב בַּמַּיִם. וְכֵן כָּל הַשְּׁרָצִים שֶׁשָּׁתוּ אֵינָן פּוֹסְלִין חוּץ מִן הַחֻלְדָּה מִפְּנֵי שֶׁהִיא מְלַקֶּקֶת בִּלְשׁוֹנָהּ וְנִמְצֵאת הַלֵּחָה יוֹצְאָה מִפִּיהָ לַמַּיִם:","מֵי חַטָּאת שֶׁנִּשְׁתַּנּוּ מַרְאֵיהֶן מֵחֲמַת עַצְמָן כְּשֵׁרִים. נִשְׁתַּנּוּ מֵחֲמַת עָשָׁן פְּסוּלִין. הִגְלִידוּ וְחָזְרוּ וְנִמּוֹחוּ כְּשֵׁרִים אֲפִלּוּ נִמּוֹחוּ בַּחַמָּה אֲבָל אִם הִמְחָן בָּאוּר פְּסוּלִין:","אֵפֶר חַטָּאת שֶׁנִּשְׁתַּנּוּ מַרְאָיו מֵחֲמַת עַצְמוֹ אוֹ מֵחֲמַת עָשָׁן כָּשֵׁר. נִשְׁתַּנּוּ מֵחֲמַת אָבָק אוֹ שֶׁנָּפַל לְתוֹכוֹ סִיד אוֹ גַּפְסִיס אוֹ שֶׁנִּתְעָרֵב בּוֹ אֵפֶר מַקְלֶה כָּל שֶׁהוּא הֲרֵי זֶה פָּסוּל:","הַחוֹשֵׁב עַל מֵי חַטָּאת לִשְׁתּוֹתָן לֹא פְּסָלָן עַד שֶׁיִּשְׁתֶּה מֵהֶן. וְאִם שָׁפַךְ מִן הַכְּלִי לְתוֹךְ גְּרוֹנוֹ וְלֹא נָגְעָה שְׂפָתוֹ בַּמַּיִם שֶׁבַּכְּלִי לֹא פָּסַל:","כְּלִי שֶׁיֵּשׁ בּוֹ מַיִם מְקֻדָּשִׁין שֶׁהִנִּיחוֹ מְגֻלֶּה וּבָא וּמְצָאוֹ מְכֻסֶּה הֲרֵי אֵלּוּ פְּסוּלִין שֶׁמָּא אָדָם שֶׁאֵינוֹ טָהוֹר לְחַטָּאת נָגַע בָּהֶן שֶׁהֲרֵי אָדָם כִּסָּהוּ בְּוַדַּאי. הִנִּיחוֹ מְכֻסֶּה וּבָא וּמְצָאוֹ מְגֻלֶּה אִם יְכוֹלָה הַחֻלְדָּה לִשְׁתּוֹת מִמֶּנּוּ אוֹ שֶׁיָּרַד לוֹ טַל בַּלַּיְלָה פְּסוּלִין וְאִם לָאו כְּשֵׁרִין מִפְּנֵי שֶׁיֵּשׁ כָּאן שְׁתֵּי סְפֵקוֹת סָפֵק אָדָם גִּלָּה אוֹ בְּהֵמָה חַיָּה וָרֶמֶשׂ וְאִם תִּמְצֵי לוֹמַר אָדָם גִּלָּהוּ שֶׁמָּא הָיָה טָהוֹר לְחַטָּאת אוֹ לֹא:","הַמּוֹסֵר מַיִם מְקֻדָּשִׁין אוֹ מַיִם שֶׁנִּתְמַלְּאוּ לְקִדּוּשׁ לְטָמֵא לְשָׁמְרָן הֲרֵי אֵלּוּ פְּסוּלִין:","שְׁנַיִם שֶׁהָיוּ שׁוֹמְרִין אֶת הַמַּיִם וְנִטְמָא אֶחָד מֵהֶן כְּשֵׁרִים מִפְּנֵי שֶׁהֵן בִּרְשׁוּתוֹ שֶׁל שֵׁנִי. טָהַר וְחָזַר לִשְׁמֹר וְנִטְמָא הַשֵּׁנִי כְּשֵׁרִים מִפְּנֵי שֶׁהֵן בִּרְשׁוּתוֹ שֶׁל רִאשׁוֹן. נִטְמְאוּ שְׁנֵיהֶן כְּאַחַת הַמַּיִם פְּסוּלִין:"],"Mishneh Torah, Rest on a Holiday 2":["אֶפְרוֹחַ שֶׁנּוֹלַד בְּיוֹם טוֹב אָסוּר מִפְּנֵי שֶׁהוּא מֻקְצֶה. וְעֵגֶל שֶׁנּוֹלַד בְּיוֹם טוֹב אִם הָיְתָה אִמּוֹ עוֹמֶדֶת לַאֲכִילָה מֻתָּר מִפְּנֵי שֶׁהוּא מוּכָן עַל גַּבֵּי אִמּוֹ וְאִלּוּ שָׁחַט אִמּוֹ הָיָה זֶה שֶׁבְּמֵעֶיהָ מֻתָּר בְּיוֹם טוֹב אַף עַל פִּי שֶׁלֹּא נוֹלַד:","בְּהֵמוֹת שֶׁיּוֹצְאוֹת וְרוֹעוֹת חוּץ לַתְּחוּם וּבָאוֹת וְלָנוֹת בְּתוֹךְ הַתְּחוּם הֲרֵי אֵלּוּ מוּכָנִין וְלוֹקְחִין מֵהֶן וְשׁוֹחֲטִין אוֹתָן בְּיוֹם טוֹב. אֲבָל הָרוֹעוֹת וְלָנוֹת חוּץ לַתְּחוּם אִם בָּאוּ בְּיוֹם טוֹב אֵין שׁוֹחֲטִין אוֹתָן בְּיוֹם טוֹב מִפְּנֵי שֶׁהֵן מֻקְצִין וְאֵין דַּעַת אַנְשֵׁי הָעִיר עֲלֵיהֶם:","וְכֵן בֶּהֱמַת קָדָשִׁים שֶׁנּוֹלַד בָּהּ מוּם בְּיוֹם טוֹב הוֹאִיל וְלֹא הָיְתָה דַּעְתּוֹ עָלֶיהָ מֵעֶרֶב יוֹם טוֹב אָסוּר לְשָׁחֳטָהּ בְּיוֹם טוֹב. לְפִיכָךְ אָסוּר לִרְאוֹת מוּמֵי קָדָשִׁים בְּיוֹם טוֹב גְּזֵרָה שֶׁמָּא יַתִּירֵם הֶחָכָם בְּמוּמָן וְיָבֹא זֶה לִשְׁחוֹט בּוֹ בַּיּוֹם. אֲבָל רוֹאֶה הוּא הַמּוּם מֵעֶרֶב יוֹם טוֹב וּלְמָחָר מַתִּיר אוֹ אוֹסֵר:","בְּכוֹר שֶׁנּוֹלַד וּמוּמוֹ עִמּוֹ הֲרֵי זֶה מוּכָן וְאֵין מְבַקְּרִים אוֹתוֹ בְּיוֹם טוֹב. וְאִם עָבַר וְרָאָה מוּמוֹ וּבִקְּרוֹ וְהִתִּירוֹ הֲרֵי זֶה שׁוֹחֵט וְאוֹכֵל. בְּכוֹר שֶׁנָּפַל לַבּוֹר עוֹשֶׂה לוֹ פַּרְנָסָה בִּמְקוֹמוֹ שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהַעֲלוֹתוֹ מִפְּנֵי שֶׁאֵינוֹ רָאוּי לִשְׁחִיטָה בְּיוֹם טוֹב. (ויקרא כב כח) \"אוֹתוֹ וְאֶת בְּנוֹ\" שֶׁנָּפְלוּ לַבּוֹר מַעֲלֶה אֶת הָרִאשׁוֹן עַל מְנָת לְשָׁחֳטוֹ וְאֵינוֹ שׁוֹחֲטוֹ. וּמַעֲרִים וּמַעֲלֶה אֶת הַשֵּׁנִי עַל מְנָת לְשָׁחֳטוֹ וְשׁוֹחֵט אֶת אֵי זֶה מֵהֶן שֶׁיִּרְצֶה. מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים הִתִּירוּ לְהַעֲרִים. בֶּהֱמַת חֻלִּין שֶׁנָּפְלָה מִן הַגַּג וְעָמְדָה מֵעֵת לְעֵת וַהֲרֵי הִיא צְרִיכָה בְּדִיקָה שׁוֹחֲטִין אוֹתָהּ בְּיוֹם טוֹב וְתִבָּדֵק אֶפְשָׁר שֶׁתִּמָּצֵא כְּשֵׁרָה וְתֵאָכֵל:","אֲוָזִין וְתַרְנְגוֹלִין וְיוֹנִים שֶׁבַּבַּיִת הֲרֵי אֵלּוּ מוּכָנִין וְאֵין צְרִיכִין זִמּוּן. אֲבָל יוֹנֵי שׁוֹבָךְ וְיוֹנֵי עֲלִיָּה וְצִפֳּרִים שֶׁקִּנְּנוּ בִּטְפִיחִין אוֹ בְּכִירָה וּבַפַּרְדֵּס הֲרֵי אֵלּוּ מֻקְצֶה. וְצָרִיךְ לְזַמֵּן מִבָּעֶרֶב וְלוֹמַר אֵלּוּ וְאֵלּוּ אֲנִי נוֹטֵל וְאֵינוֹ צָרִיךְ לְנַעֲנֵעַ:","זִמֵּן שְׁחוֹרִים וּלְבָנִים וּמָצָא שְׁחוֹרִים בִּמְקוֹם לְבָנִים וּלְבָנִים בִּמְקוֹם שְׁחוֹרִים אֲסוּרִים שֶׁאֲנִי אוֹמֵר שֶׁמָּא אוֹתָן שֶׁזִּמֵּן פָּרְחוּ לָהֶן וְאֵלּוּ אֲחֵרִים הֵן וְכָל סָפֵק מוּכָן אָסוּר. זִמֵּן שְׁנַיִם וּמָצָא שְׁלֹשָׁה הַכּל אָסוּר. שְׁלֹשָׁה וּמָצָא שְׁנַיִם מֻתָּרִין. זִמֵּן בְּתוֹךְ הַקֵּן וּמָצָא לִפְנֵי הַקֵּן אִם אֵין שָׁם בַּקֵּן אֶלָּא הֵן וְאֵינָן יְכוֹלִין לִפְרֹחַ אַף עַל פִּי שֶׁיֵּשׁ שָׁם קֵן אַחֵר בְּקֶרֶן זָוִית בְּתוֹךְ חֲמִשִּׁים אַמָּה הֲרֵי אֵלּוּ מֻתָּרִין שֶׁאֵין הַמְדַדֶּה מְדַדֶּה אֶלָּא כְּנֶגֶד קִנּוֹ בְּשָׁוֶה:","דָּגִים שֶׁבְּבֵיבָרִין גְּדוֹלִים וְכֵן חַיָּה וָעוֹף שֶׁבְּבֵיבָרִין גְּדוֹלִים כָּל שֶׁהוּא מְחֻסַּר צִידָה עַד שֶׁאוֹמְרִים הָבֵא מְצוּדָה וּנְצוּדֶנּוּ הֲרֵי זֶה מֻקְצֶה וְאֵין צָדִין אוֹתָן בְּיוֹם טוֹב וְאִם צָד לֹא יֹאכְלוֹ. וְכָל שֶׁאֵינוֹ צָרִיךְ מְצוּדָה הֲרֵי זֶה מוּכָן וְצָדִין אוֹתוֹ בְּיוֹם טוֹב וְאוֹכְלִין אוֹתוֹ. וְכֵן חַיָּה שֶׁקִּנְּנָה בְּפַרְדֵּס הַסָּמוּךְ לָעִיר יְלָדֶיהָ כְּשֶׁהֵן קְטַנִּים שֶׁאֵינָן צְרִיכִין צִידָה אֵינָם צְרִיכִים זִמּוּן מִפְּנֵי שֶׁדַּעְתּוֹ עֲלֵיהֶן:","מְצוּדוֹת חַיָּה וְעוֹפוֹת וְדָגִים שֶׁפְּרָסָן מֵעֶרֶב יוֹם טוֹב לֹא יִטּל מֵהֶן בְּיוֹם טוֹב אֶלָּא אִם כֵּן יוֹדֵעַ שֶׁנִּצּוֹדוּ מֵעֶרֶב יוֹם טוֹב. הַסּוֹכֵר אַמַּת הַמַּיִם מֵעֶרֶב יוֹם טוֹב וּלְמָחָר הִשְׁכִּים וּמָצָא בָּהּ דָּגִים הֲרֵי אֵלּוּ מֻתָּרִין שֶׁכְּבָר נִצּוֹדוּ מֵעֶרֶב יוֹם טוֹב וַהֲרֵי הֵן מוּכָנִין:","בַּיִת שֶׁהִיא מָלֵא פֵּרוֹת מוּכָנִין וְנִפְחַת נוֹטֵל מִמְּקוֹם הַפְּחָת. הָעוֹמֵד עַל הַמֻּקְצֶה מֵעֶרֶב יוֹם טוֹב בַּשָּׁנָה הַשְּׁבִיעִית שֶׁכָּל הַפֵּרוֹת הֶפְקֵר צָרִיךְ שֶׁיִּרְשֹׁם וְיֹאמַר מִכָּאן וְעַד כָּאן אֲנִי נוֹטֵל וְאִם לֹא רָשַׁם לֹא יִטּל:","כּוּתִי שֶׁהֵבִיא תְּשׁוּרָה לְיִשְׂרָאֵל בְּיוֹם טוֹב אִם יֵשׁ מֵאוֹתוֹ הַמִּין בִּמְחֻבָּר לַקַּרְקַע אוֹ שֶׁהֵבִיא חַיָּה אוֹ עוֹפוֹת אוֹ דָּגִים שֶׁאֶפְשָׁר לְצוּדָן בּוֹ בַּיּוֹם הֲרֵי אֵלּוּ אֲסוּרִין עַד לָעֶרֶב וְיַמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ. וַאֲפִלּוּ הֲדַס וְכַיּוֹצֵא בּוֹ אֵינוֹ מֵרִיחַ בּוֹ לָעֶרֶב עַד שֶׁיַּמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ. וְאִם אֵין מֵאוֹתוֹ הַמִּין בִּמְחֻבָּר לַקַּרְקַע אוֹ שֶׁהָיְתָה צוּרָתוֹ מוּכַחַת עָלָיו שֶׁמֵּאֶתְמוֹל נֶעֱקַר אוֹ נִצּוֹד אִם הֱבִיאוֹ מִתּוֹךְ הַתְּחוּם מֻתָּר וְאִם הֱבִיאוֹ מִחוּץ לַתְּחוּם הֲרֵי זֶה אָסוּר. וְהַבָּא בִּשְׁבִיל יִשְׂרָאֵל זֶה מִחוּץ לַתְּחוּם מֻתָּר לְיִשְׂרָאֵל אַחֵר:","עֵצִים שֶׁנָּשְׁרוּ מִן הַדֶּקֶל בְּיוֹם טוֹב אָסוּר לְהַסִּיקָן מִפְּנֵי שֶׁהֵן נוֹלָד. וְאִם נָשְׁרוּ לְתוֹךְ הַתַּנּוּר מַרְבֶּה עֲלֵיהֶן עֵצִים מוּכָנִין וּמַסִּיקָן. עֲרֵמַת הַתֶּבֶן וְאוֹצָר שֶׁל עֵצִים אֵין מַתְחִילִין בָּהֶן בְּיוֹם טוֹב אֶלָּא אִם כֵּן הֵכִין מִבָּעֶרֶב מִפְּנֵי שֶׁהֵן מֻקְצֶה. וְאִם הָיָה הַתֶּבֶן מְעֹרָב בְּקוֹצִים שֶׁהֲרֵי אֵינוֹ רָאוּי אֶלָּא לְאֵשׁ הֲרֵי זֶה מוּכָן:","אֵין מְבַקְּעִין עֵצִים מִסַּוַואר שֶׁל קוֹרוֹת מִפְּנֵי שֶׁהֵן מֻקְצֶה. וְלֹא מִן הַקּוֹרָה שֶׁנִּשְׁבְּרָה בְּיוֹם טוֹב מִפְּנֵי שֶׁהִיא נוֹלָד. וְכֵן כֵּלִים שֶׁנִּשְׁבְּרוּ בְּיוֹם טוֹב אֵין מַסִּיקִין בָּהֶן מִפְּנֵי שֶׁהֵן נוֹלָד. אֲבָל מַסִּיקִין בְּכֵלִים שְׁלֵמִים אוֹ בְּכֵלִים שֶׁנִּשְׁבְּרוּ מֵעֶרֶב יוֹם טוֹב שֶׁהֲרֵי הוּכְנוּ לִמְלָאכָה אַחֶרֶת מִבָּעֶרֶב. כַּיּוֹצֵא בּוֹ אֱגוֹזִים וּשְׁקֵדִים שֶׁאֲכָלָן מֵעֶרֶב יוֹם טוֹב מַסִּיקִין בִּקְלִפֵּיהֶן בְּיוֹם טוֹב. וְאִם אֲכָלָן בְּיוֹם טוֹב אֵין מַסִּיקִין בִּקְלִפֵּיהֶן. וְיֵשׁ נֻסְחָאוֹת שֶׁיֵּשׁ בָּהֶן שֶׁאִם אֲכָלָן מִבָּעֶרֶב אֵין מַסִּיקִין בִּקְלִפֵּיהֶן שֶׁהֲרֵי הֻקְצוּ וְאִם אֲכָלָן בְּיוֹם טוֹב מַסִּיקִין מִפְּנֵי שֶׁהֵן מוּכָנִין עַל גַּב הָאֹכֶל:","קוֹץ רָטֹב הֲרֵי הוּא מֻקְצֶה מִפְּנֵי שֶׁאֵינוֹ רָאוּי לְהַסָּקָה. לְפִיכָךְ אָסוּר לוֹ לַעֲשׂוֹתוֹ כְּמוֹ שִׁפּוּד לִצְלוֹת בּוֹ בָּשָׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נוֹטְלִין עֵצִים הַסְּמוּכִים לְדָפְנֵי הַסֻּכָּה וּמַסִּיקִין בָּהֶן. אֲבָל אֵין מְבִיאִים מִן הַשָּׂדֶה אֲפִלּוּ הָיוּ מְכֻנָּסִין שָׁם מִבָּעֶרֶב. אֲבָל מְגַבֵּב הוּא בַּשָּׂדֶה מִלְּפָנָיו וּמַדְלִיק שָׁם. וּמְבִיאִין מִן הַמְכֻנָּסִין שֶׁבִּרְשׁוּת הַיָּחִיד וַאֲפִלּוּ הָיְתָה מֻקֶּפֶת שֶׁלֹּא לְשֵׁם דִּירָה וּבִלְבַד שֶׁיִּהְיֶה לָהּ פּוֹתַחַת וְתִהְיֶה בְּתוֹךְ תְּחוּם שַׁבָּת. וְאִם חָסֵר אֶחָד מִכָּל אֵלּוּ הֲרֵי הֵן מֻקְצֶה:","עֲלֵי קָנִים וַעֲלֵי גְּפָנִים אַף עַל פִּי שֶׁהֵן מְכֻנָּסִין בְּקַרְפָּף כֵּיוָן שֶׁהָרוּחַ מְפַזֶּרֶת אוֹתָן הֲרֵי הֵן כִּמְפֻזָּרִין וַאֲסוּרִין. וְאִם הִנִּיחַ עֲלֵיהֶן כְּלִי כָּבֵד מֵעֶרֶב יוֹם טוֹב הֲרֵי אֵלּוּ מוּכָנִין:","בְּהֵמָה שֶׁמֵּתָה בְּיוֹם טוֹב אִם הָיְתָה מְסֻכֶּנֶת מֵעֶרֶב יוֹם טוֹב הֲרֵי זֶה מְחַתְּכָהּ לַכְּלָבִים. וְאִם לָאו הוֹאִיל וְלֹא הָיְתָה דַּעְתּוֹ עָלֶיהָ הֲרֵי זֶה מֻקְצֶה וְלֹא יַזִּיזֶנָּהּ מִמְּקוֹמָהּ. בֶּהֱמַת קָדָשִׁים שֶׁמֵּתָה וּתְרוּמָה שֶׁנִּטְמֵאת לֹא יַזִּיזֶנָּהּ מִמְּקוֹמָהּ:","דָּגִים וְעוֹפוֹת וְחַיָּה שֶׁהֵן מֻקְצֶה אֵין מַשְׁקִין אוֹתָן בְּיוֹם טוֹב וְאֵין נוֹתְנִין לִפְנֵיהֶם מְזוֹנוֹת שֶׁמָּא יָבֹא לִקַּח מֵהֶן. וְכָל שֶׁאָסוּר לְאָכְלוֹ אוֹ לְהִשְׁתַּמֵּשׁ בּוֹ בְּיוֹם טוֹב מִפְּנֵי שֶׁהוּא מֻקְצֶה אָסוּר לְטַלְטְלוֹ:","הַמַּכְנִיס עָפָר מֵעֶרֶב יוֹם טוֹב אִם יִחֵד לוֹ בַּחֲצֵרוֹ קֶרֶן זָוִית הֲרֵי זֶה מוּכָן וּמֻתָּר לְטַלְטְלוֹ וְלַעֲשׂוֹת בּוֹ כָּל צְרָכָיו. וְכֵן אֵפֶר שֶׁהֻסַּק מֵעֶרֶב יוֹם טוֹב מוּכָן. וְשֶׁהֻסַּק בְּיוֹם טוֹב כָּל זְמַן שֶׁהוּא חַם כְּדֵי לִצְלוֹת בּוֹ בֵּיצָה מֻתָּר לְטַלְטְלוֹ שֶׁעֲדַיִן אֵשׁ הוּא. וְאִם לָאו אָסוּר לְטַלְטְלוֹ מִפְּנֵי שֶׁהוּא נוֹלָד. מִי שֶׁהָיָה לוֹ דֶּקֶר נָעוּץ מֵעֶרֶב יוֹם טוֹב וְנִתְּקוֹ בְּיוֹם טוֹב וְהֶעֱלָה עָפָר אִם הָיָה אוֹתוֹ עָפָר תִּיחוֹחַ הֲרֵי זֶה מְכַסֶּה בּוֹ וּמְטַלְטְלוֹ. אֲבָל אִם הֶעֱלָה גּוּשׁ עָפָר הֲרֵי זֶה לֹא יִכְתּשׁ אוֹתוֹ בְּיוֹם טוֹב:"],"Mishneh Torah, Ritual Slaughter 11":["כָּל בְּהֵמָה אוֹ עוֹף שֶׁנּוֹלד בָּהֶן סְפֵק טְרֵפוֹת מִטְּרֵפוֹת אֵלּוּ. כְּגוֹן בְּהֵמָה שֶׁנָּפְלָה וְלֹא הָלְכָה. אוֹ שֶׁנִּדְרְסָה בִּידֵי חַיָּה וְאֵין יָדוּעַ אִם הֶאֱדִים בָּשָׂר כְּנֶגֶד בְּנֵי מֵעַיִם אוֹ לֹא הֶאֱדִים. אוֹ שֶׁנֶּחְבְּסָה גֻּלְגָּלְתָּהּ וְאֵין יָדוּעַ אִם רֻבָּהּ אוֹ מִעוּטָהּ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אִם הָיָה זָכָר וְשָׁהָה שְׁנֵים עָשָׂר חֹדֶשׁ הֲרֵי זוֹ בְּחֶזְקַת שְׁלֵמָה כִּשְׁאָר כָּל הַבְּהֵמוֹת. וְאִם הָיְתָה נְקֵבָה עַד שֶׁתֵּלֵד. וּבְעוֹף בְּזָכָר שְׁנֵים עָשָׂר חֹדֶשׁ. וּבִנְקֵבָה עַד שֶׁתֵּלֵד כָּל הַבֵּיצִים שֶׁל טְעִינָה הָרִאשׁוֹנָה וְתִטְעֹן טְעִינָה שְׁנִיָּה וְתֵלֵד:","וְאָסוּר לִמְכֹּר סְפֵק טְרֵפָה זוֹ לְנָכְרִי בְּתוֹךְ זְמַן זֶה שֶׁמָּא יִמְכְּרֶנָּה לְיִשְׂרָאֵל:","כָּל בְּהֵמָה חַיָּה וְעוֹף בְּחֶזְקַת בְּרִיאִים הֵם וְאֵין חוֹשְׁשִׁין לָהֶם שֶׁמָּא יֵשׁ בָּהֶן טְרֵפָה. לְפִיכָךְ כְּשֶׁיִּשָׁחֲטוּ שְׁחִיטָה כְּשֵׁרָה אֵינָן צְרִיכִין בְּדִיקָה שֶׁמָּא יֵשׁ בָּהֶן אַחַת מִן הַטְּרֵפוֹת. אֶלָּא הֲרֵי הֵן בְּחֶזְקַת הֶתֵּר עַד שֶׁיִּוָּלֵד לָהֶן דָּבָר שֶׁחוֹשְׁשִׁין לוֹ וְאַחַר כָּךְ בּוֹדְקִין עַל אוֹתוֹ דָּבָר בִּלְבַד:","כֵּיצַד. כְּגוֹן שֶׁנִּשְׁמַט הַגַּף שֶׁל עוֹף בּוֹדְקִין אֶת הָרֵאָה שֶׁמָּא נִקְּבָה. נָפְלָה הַבְּהֵמָה בּוֹדְקִין אוֹתָהּ שֶׁמָּא נִתְרַסְּקוּ אֵיבָרֶיהָ. נִתְרַצֵּץ עֶצֶם הָרֹאשׁ בּוֹדְקִין קְרוּם שֶׁל מֹחַ שֶׁמָּא נִקַּב. הִכָּה אוֹתָהּ קוֹץ אוֹ נִזְרַק בָּהּ חֵץ אוֹ רֹמַח וְכַיּוֹצֵא בָּהֶן וְנִכְנַס לַחֲלָלָהּ חוֹשְׁשִׁין לָהּ וּצְרִיכָה בְּדִיקָה כְּנֶגֶד כָּל הֶחָלָל שֶׁמָּא נִקַּב אֶחָד מִן הָאֵיבָרִין שֶׁתִּטָּרֵף בִּנְקִיבָתָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","לְפִיכָךְ רֵאָה שֶׁהֶעֶלְתָה צְמָחִין אוֹ שֶׁנִּמְצְאוּ סִרְכוֹת כְּמוֹ חוּטִין תְּלוּיִין מִמֶּנָּה וְלַדֹּפֶן אוֹ לַלֵּב אוֹ לְטַרְפַּשׁ הַכָּבֵד חוֹשְׁשִׁין לָהּ שֶׁמָּא נִקְּבָה וּצְרִיכָה בְּדִיקָה. וְכֵן אִם נִמְצָא בָּהּ אֲבַעְבּוּעַ מָלֵא לֵחָה חוֹשְׁשִׁין שֶׁמָּא נִקַּב סִמְפּוֹן שֶׁתַּחְתָּיו וּצְרִיכָה בְּדִיקָה:","מִן הַדִּין הָיָה עַל דֶּרֶךְ זוֹ שֶׁאִם נִמְצֵאת הָרֵאָה תְּלוּיָה בְּסִרְכוֹת כְּמוֹ חוּטִין. אִם הָיוּ מִן הָאוֹם שֶׁל רֵאָה וְלַדֹּפֶן אוֹ שֶׁהָיוּ לַלֵּב אוֹ לְטַרְפַּשׁ הַכָּבֵד שֶׁחוֹתְכִים אֶת הַסִּרְכָא וּמוֹצִיאִין אֶת הָרֵאָה וְנוֹפְחִין אוֹתָהּ בְּפוֹשְׁרִין. אִם נִמְצֵאת נְקוּבָה טְרֵפָה. וְאִם לֹא נִתְבַּעְבֵּעַ הַמַּיִם הֲרֵי הִיא שְׁלֵמָה מִכָּל נֶקֶב וּמֻתֶּרֶת וְסִרְכָא זוֹ לֹא הָיְתָה בִּמְקוֹם נֶקֶב אוֹ שֶׁמָּא נִקַּב קְרוּם הָעֶלְיוֹן בִּלְבַד. וּמֵעוֹלָם לֹא רָאִינוּ מִי שֶׁהוֹרָה כָּךְ וְלֹא שָׁמַעְנוּ מָקוֹם שֶׁעוֹשִׂין בּוֹ כָּךְ:","וְאַף עַל פִּי שֶׁאֵלּוּ הֵן הַדְּבָרִים הַנִּרְאִין מִדִּבְרֵי חַכְמֵי הַגְּמָרָא. הַמִּנְהָג הַפָּשׁוּט בְּיִשְׂרָאֵל כָּךְ הוּא. כְּשֶׁשּׁוֹחֲטִין אֶת הַבְּהֵמָה אוֹ אֶת הַחַיָּה קוֹרְעִין אֶת הַטַּרְפַּשׁ שֶׁל כָּבֵד וּבוֹדְקִין אֶת הָרֵאָה בִּמְקוֹמָהּ. אִם לֹא נִמְצְאָה תְּלוּיָה בְּסִרְכָא. אוֹ שֶׁנִּמְצְאָה סִרְכָא בֵּין אֹזֶן מֵאָזְנֵי הָרֵאָה וְלַבָּשָׂר שֶׁבִּמְקוֹם רְבִיצָתָהּ בֵּין בָּשָׂר שֶׁבֵּין הַצְּלָעוֹת בֵּין בָּשָׂר שֶׁבֶּחָזֶה. אוֹ שֶׁנִּמְצְאָה סִרְכָא מֵאֹזֶן לְאֹזֶן עַל הַסֵּדֶר אוֹ מִן הָאוֹם לָאֹזֶן הַסְּמוּכָה לָהּ. הֲרֵי אֵלּוּ מַתִּירִין אוֹתָהּ:","וְאִם נִמְצָא חוּט יוֹצֵא מִן הָאוֹם שֶׁל רֵאָה לְאֵיזֶה מָקוֹם שֶׁיִּמָּשֵׁךְ וַאֲפִלּוּ הָיָה כְּחוּט הַשַּׂעֲרָה אוֹסְרִין אוֹתָהּ:","וְכֵן אִם הָיָה מִן הָרֵאָה חוּט מָשׁוּךְ לַלֵּב אוֹ לְטַרְפַּשׁ הַכָּבֵד אוֹ לְכִיס הַלֵּב אוֹ לַוַּרְדָּא. בֵּין שֶׁהָיָה הַחוּט מִן הָאוֹם שֶׁל רֵאָה בֵּין שֶׁהָיָה מִן הָאֹזֶן וַאֲפִלּוּ הָיָה כְּחוּט הַשַּׂעֲרָה אוֹסְרִין אוֹתָהּ. וְכֵן וַרְדָּא שֶׁנִּמְצֵאת דְּבוּקָה בְּכִיסָהּ אוֹ חוּט יוֹצֵא מִמֶּנָּה לְכִיסָהּ אוֹסְרִין אוֹתָהּ. וְחוּט הַיּוֹצֵא מֵאֹזֶן לְאֹזֶן שֶׁלֹּא עַל הַסֵּדֶר אוֹסְרִין אוֹתָהּ:","יֵשׁ מְקוֹמוֹת שֶׁמִּנְהָגָן אִם מָצְאוּ סִרְכָא מִן הָאֹזֶן לַבָּשָׂר וְלָעֶצֶם שֶׁבַּצְּלָעוֹת וְהַסִּרְכָא דְּבוּקָה בִּשְׁתֵּיהֶן אוֹסְרִין אוֹתָהּ. וְאַבָּא מָרִי מִן הָאוֹסְרִין וַאֲנִי מִן הַמַּתִּירִין. וּמִעוּט מְקוֹמוֹת מַתִּירִין אֲפִלּוּ נִדְבְּקָה בָּעֶצֶם לְבַדּוֹ וַאֲנִי אוֹסֵר:","וְיֵשׁ מְקוֹמוֹת שֶׁנּוֹפְחִין הָרֵאָה שֶׁמָּא יֵשׁ בָּהּ נֶקֶב. וְרֹב הַמְּקוֹמוֹת אֵין נוֹפְחִין שֶׁהֲרֵי לֹא נוֹלַד דָּבָר שֶׁגּוֹרֵם לַחֲשָׁשׁ. וּמֵעוֹלָם לֹא נָפַחְנוּ רֵאָה בִּסְפָרַד וּבַמַּעֲרָב אֶלָּא אִם נוֹלַד לָנוּ דָּבָר שֶׁחוֹשְׁשִׁים לוֹ:","וּדְבָרִים הָאֵלּוּ כֻּלָּן אֵינָן עַל פִּי הַדִּין אֶלָּא עַל פִּי הַמִּנְהָג כְּמוֹ שֶׁבֵּאַרְנוּ. וּמֵעוֹלָם לֹא שָׁמַעְנוּ בְּמִי שֶׁבָּדַק עוֹף אֶלָּא אִם נוֹלַד לוֹ חֲשָׁשׁ:","מִי שֶׁשָּׁחַט אֶת הַבְּהֵמָה וְקָרַע אֶת הַבֶּטֶן. וְקֹדֶם שֶׁיִּבְדֹּק אֶת הָרֵאָה בָּא כֶּלֶב אוֹ עַכּוּ\"ם וְנָטַל אֶת הָרֵאָה וְהָלַךְ לוֹ. הֲרֵי זוֹ מֻתֶּרֶת. וְאֵין אוֹמְרִים שֶׁמָּא נְקוּבָה הָיְתָה אוֹ שֶׁמָּא דְּבוּקָה הָיְתָה. שֶׁאֵין מַחֲזִיקִין אִסּוּר. אֶלָּא הֲרֵי זוֹ בְּחֶזְקַת הֶתֵּר עַד שֶׁיִּוָּדַע בַּמֶּה נִטְרְפָה. וּכְשֵׁם שֶׁאֵין חוֹשְׁשִׁין לִקְרוּם מֹחַ וְלַשִּׁדְרָה וְכַיּוֹצֵא בָּהֶן כָּךְ לֹא נָחוּשׁ לַרֵאָה שֶׁאָבְדָה. וְאֵין בָּזֶה מִנְהָג שֶׁדָּבָר שֶׁאֵינוֹ מָצוּי אֵין בּוֹ מִנְהָג:","בָּא הָעַכּוּ\"ם אוֹ הַיִּשְׂרָאֵל וְהוֹצִיא הָרֵאָה קֹדֶם שֶׁתִּבָּדֵק וַהֲרֵי הִיא קַיֶּמֶת נוֹפְחִין אוֹתָהּ וְאַף עַל פִּי שֶׁאֵין אָנוּ יוֹדְעִין אִם הָיוּ שָׁם צְמָחִין אוֹ לֹא הָיוּ. מִפְּנֵי פִּשּׁוּט הַמִּנְהָג:","יֵשׁ מְקוֹמוֹת שֶׁאִם נִמְצְאוּ סִרְכוֹת מְדֻלְדָּלוֹת מִן הָרֵאָה אַף עַל פִּי שֶׁאֵינָן דְּבוּקוֹת לֹא לַדֹּפֶן וְלֹא לְמָקוֹם אַחֵר אוֹסְרִין אוֹתָהּ. וְדָבָר זֶה הֶפְסֵד גָּדוֹל הוּא וְאִבּוּד מָמוֹן לְיִשְׂרָאֵל. וּמֵעוֹלָם לֹא נָהֲגוּ זֶה לֹא בְּצָרְפַת וְלֹא בִּסְפָרַד וְלֹא נִשְׁמַע זֶה בַּמַּעֲרָב. וְאֵין רָאוּי לִנְהֹג בְּמִנְהָג זֶה. אֶלָּא נוֹפְחִין אוֹתָהּ בִּלְבַד. אִם נִמְצֵאת שְׁלֵמָה מִן הַנֶּקֶב הֲרֵי זוֹ מֻתֶּרֶת:"],"Mishneh Torah, Robbery and Lost Property 1":["כָּל הַגּוֹזֵל אֶת חֲבֵרוֹ שְׁוֵה פְּרוּטָה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יג) \"לֹא תִגְזל\". אֵין לוֹקִין עַל לָאו זֶה שֶׁהֲרֵי הַכָּתוּב נִתְּקוֹ לַעֲשֵׂה שֶׁאִם גָּזַל חַיָּב לְהַחְזִיר שֶׁנֶּאֱמַר (ויקרא ה כג) \"וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל\" זוֹ מִצְוַת עֲשֵׂה. וַאֲפִלּוּ שָׂרַף הַגְּזֵלָה אֵינוֹ לוֹקֶה שֶׁהֲרֵי הוּא חַיָּב לְשַׁלֵּם דָּמֶיהָ וְכָל לָאו שֶׁנִּתָּן לְתַשְׁלוּמִין אֵין לוֹקִין עָלָיו:","וְאָסוּר לִגְזל כָּל שֶׁהוּא דִּין תּוֹרָה אֲפִלּוּ עַכּוּ\"ם אָסוּר לְגָזְלוֹ אוֹ לְעָשְׁקוֹ. וְאִם גְּזָלוֹ אוֹ עֲשָׁקוֹ יַחְזִיר:","אֵי זֶהוּ גּוֹזֵל זֶה הַלּוֹקֵחַ מָמוֹן הָאָדָם בְּחָזְקָה כְּגוֹן שֶׁחָטַף מִיָּדוֹ מִטַּלְטְלִין אוֹ שֶׁנִּכְנַס לִרְשׁוּתוֹ שֶׁלֹּא בִּרְצוֹן הַבְּעָלִים וְנָטַל מִשָּׁם כֵּלִים. אוֹ שֶׁתָּקַף בְּעַבְדּוֹ וּבִבְהֶמְתּוֹ וְנִשְׁתַּמֵּשׁ בָּהֶן. אוֹ שֶׁיָּרַד לְתוֹךְ שָׂדֵהוּ וְאָכַל פֵּרוֹתֶיהָ וְכָל כַּיּוֹצֵא בָּזֶה הוּא גּוֹזֵל. כָּעִנְיָן שֶׁנֶּאֱמַר (שמואל ב כג כא) \"וַיִּגְזל אֶת הַחֲנִית מִיַּד הַמִּצְרִי\":","אֵי זֶהוּ עוֹשֵׁק זֶה שֶׁבָּא מָמוֹן חֲבֵרוֹ לְתוֹךְ יָדוֹ בִּרְצוֹן הַבְּעָלִים וְכֵיוָן שֶׁתְּבָעוּהוּ כָּבַשׁ הַמָּמוֹן אֶצְלוֹ בְּחָזְקָה וְלֹא הֶחֱזִירוֹ. כְּגוֹן שֶׁהָיָה לוֹ בְּיַד חֲבֵרוֹ הַלְוָאָה אוֹ שְׂכִירוּת וְהוּא תּוֹבְעוֹ וְאֵינוֹ יָכוֹל לְהוֹצִיא מִמֶּנּוּ מִפְּנֵי שֶׁהוּא אַלָּם וְקָשֶׁה. וְעַל זֶה נֶאֱמַר (ויקרא יט יג) \"לֹא תַעֲשֹׁק אֶת רֵעֲךָ\":","כָּל הַגּוֹזֵל חַיָּב לְהַחְזִיר הַגְּזֵלָה עַצְמָהּ שֶׁנֶּאֱמַר (ויקרא ה כג) \"וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל\". וְאִם אָבְדָה אוֹ נִשְׁתַּנֵּית מְשַׁלֵּם דָּמֶיהָ. בֵּין שֶׁהוֹדָה מִפִּי עַצְמוֹ בֵּין שֶׁבָּאוּ עָלָיו עֵדִים שֶׁגָּזַל הֲרֵי זֶה חַיָּב לְשַׁלֵּם הַקֶּרֶן בִּלְבַד. אֲפִלּוּ גָּזַל קוֹרָה וּבְנָאָהּ בַּבִּירָה הוֹאִיל וְלֹא נִשְׁתַּנֵּית דִּין תּוֹרָה הוּא שֶׁיַּהֲרֹס אֶת כָּל הַבִּנְיָן וְיַחְזִיר קוֹרָה לִבְעָלֶיהָ. אֲבָל תִּקְּנוּ חֲכָמִים מִפְּנֵי תַּקָּנַת הַשָּׁבִים שֶׁיִּהְיֶה נוֹתֵן אֶת דָּמֶיהָ וְלֹא יַפְסִיד הַבִּנְיָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲפִלּוּ גָּזַל קוֹרָה וַעֲשָׂאָהּ בְּסֻכַּת הֶחָג וּבָא בַּעַל הַקּוֹרָה לְתָבְעָהּ בְּתוֹךְ הֶחָג נוֹתֵן לוֹ אֶת דָּמֶיהָ. אֲבָל אַחַר הֶחָג הוֹאִיל וְלֹא נִשְׁתַּנֵּית וְלֹא בְּנָאָהּ בְּטִיט מַחְזִיר אֶת הַקּוֹרָה עַצְמָהּ:","הַגּוֹזֵל פָּחוֹת מִשְּׁוֵה פְּרוּטָה אַף עַל פִּי שֶׁעָבַר אֵינוֹ בְּתוֹרַת הֲשָׁבַת גְּזֵלָה. גָּזַל שָׁלֹשׁ אֲגֻדּוֹת שָׁווֹת שָׁלֹשׁ פְּרוּטוֹת וְהֻזְּלוּ וַהֲרֵי שְׁלָשְׁתָּן שָׁווֹת שְׁתֵּי פְּרוּטוֹת וְהֶחְזִיר לוֹ שְׁתַּיִם חַיָּב לְהַחְזִיר הַשְּׁלִישִׁית הוֹאִיל וּבַתְּחִלָּה הָיְתָה שָׁוָה פְּרוּטָה. גָּזַל שְׁתַּיִם שְׁווֹת פְּרוּטָה וְהֶחְזִיר אַחַת גְּזֵלָה אֵין כָּאן מִצְוַת הֲשָׁבַת גְּזֵלָה אֵין כָּאן:","הַגּוֹזֵל אֶת חֲבֵרוֹ בַּיִּשּׁוּב וְהֶחְזִיר לוֹ גְּזֵלָתוֹ בַּמִּדְבָּר הָרְשׁוּת בְּיַד הַנִּגְזָל אִם רָצָה נוֹטֵל וְאִם לָאו אוֹמֵר לוֹ אֵינִי נוֹטֵל אֶלָּא בַּיִּשּׁוּב שֶׁמָּא תֵּאָנֵס מִמֶּנִּי כָּאן. וַהֲרֵי הִיא בִּרְשׁוּת הַגַּזְלָן וּבְאַחֲרָיוּתוֹ עַד שֶׁיַּחֲזִירֶנָּהּ לוֹ בַּיִּשּׁוּב. וְכֵן בִּדְמֵי הַגְּזֵלָה:","הַגּוֹזֵל אֶת חֲבֵרוֹ וְהִבְלִיעַ לוֹ בְּחֶשְׁבּוֹן יָצָא. וְאִם הֶחְזִיר לְכִיסוֹ שֶׁיֵּשׁ בּוֹ מָעוֹת יָצָא שֶׁאָדָם עָשׂוּי לְמַשְׁמֵשׁ בְּכִיסוֹ בְּכָל שָׁעָה וַהֲרֵי מָנָה הַמָּעוֹת שֶׁהֶחְזִיר לוֹ בִּכְלַל מְעוֹתָיו וּמִנְיַן שֶׁלֹּא מִדַּעַת פּוֹטֵר. וְאִם הֶחְזִיר לְכִיס שֶׁאֵין בּוֹ כְּלוּם לֹא יָצָא וְחַיָּב בְּאַחֲרָיוּת הַגְּזֵלָה עַד שֶׁיּוֹדִיעוֹ שֶׁהֶחְזִיר לְכִיס פְּלוֹנִי:","כָּל הַחוֹמֵד עַבְדּוֹ אוֹ אֲמָתוֹ אוֹ בֵּיתוֹ וְכֵלָיו שֶׁל חֲבֵרוֹ אוֹ דָּבָר שֶׁאֶפְשָׁר לוֹ שֶׁיִּקְנֵהוּ מִמֶּנּוּ וְהִכְבִּיר עָלָיו בְּרֵעִים וְהִפְצִיר בּוֹ עַד שֶׁלְּקָחוֹ מִמֶּנּוּ אַף עַל פִּי שֶׁנָּתַן לוֹ דָּמִים רַבִּים הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ יד) (דברים ה יח) \"לֹא תַחְמֹד\". וְאֵין לוֹקִין עַל לָאו זֶה מִפְּנֵי שֶׁאֵין בּוֹ מַעֲשֶׂה. וְאֵינוֹ עוֹבֵר בְּלָאו זֶה עַד שֶׁיִּקַּח הַחֵפֶץ שֶׁחָמַד. כָּעִנְיָן שֶׁנֶּאֱמַר (דברים ז כה) \"לֹא תַחְמֹד כֶּסֶף וְזָהָב עֲלֵיהֶם וְלָקַחְתָּ לָךְ\". חִמּוּד שֶׁיֵּשׁ בּוֹ מַעֲשֶׂה:","כָּל הַמִּתְאַוֶּה בֵּיתוֹ אוֹ אִשְׁתּוֹ וְכֵלָיו שֶׁל חֲבֵרוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן מִשְּׁאָר דְּבָרִים שֶׁאֶפְשָׁר לוֹ לִקְנוֹתָן מִמֶּנּוּ. כֵּיוָן שֶׁחָשַׁב בְּלִבּוֹ הֵיאַךְ יִקְנֶה דָּבָר זֶה וְנִפְתָּה בְּלִבּוֹ בַּדָּבָר עָבַר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים ה יח) \"לֹא תִתְאַוֶּה\" וְאֵין תַּאֲוָה אֶלָּא בַּלֵּב בִּלְבַד:","הַתַּאֲוָה מְבִיאָה לִידֵי חִמּוּד וְהַחִמּוּד מֵבִיא לִידֵי גֵּזֶל. שֶׁאִם לֹא רָצוּ הַבְּעָלִים לִמְכֹּר אַף עַל פִּי שֶׁהִרְבָּה לָהֶם בְּדָמִים וְהִפְצִיר בְּרֵעִים יָבוֹא לִידֵי גֵּזֶל שֶׁנֶּאֱמַר (מיכה ב ב) \"וְחָמְדוּ בָּתִּים וְגָזָלוּ\". וְאִם עָמְדוּ הַבְּעָלִים בְּפָנָיו לְהַצִּיל מָמוֹנָם אוֹ מְנָעוּהוּ מִלִּגְזל יָבוֹא לִידֵי שְׁפִיכוּת דָּמִים. צֵא וּלְמַד מִמַּעֲשֵׂה אַחְאָב וְנָבוֹת:","הָא לָמַדְתָּ שֶׁהַמִּתְאַוֶּה עוֹבֵר בְּלָאו אֶחָד וְהַקּוֹנֶה דָּבָר שֶׁהִתְאַוָּה בְּהֶפְצֵר שֶׁהִפְצִיר בַּבְּעָלִים אוֹ בְּבַקָּשָׁה מֵהֶן עוֹבֵר בִּשְׁנֵי לָאוִין. לְכָךְ נֶאֱמַר (שמות כ יד) (דברים ה יח) \"לֹא תַחְמֹד\" וְ(דברים ה יח) \"לֹא תִתְאַוֶּה\". וְאִם גָּזַל עָבַר בִּשְׁלֹשָׁה לָאוִין:","כָּל הַגּוֹזֵל אֶת חֲבֵרוֹ שְׁוֵה פְּרוּטָה כְּאִלּוּ נוֹטֵל נִשְׁמָתוֹ מִמֶּנּוּ שֶׁנֶּאֱמַר (משלי א יט) \"כֵּן אָרְחוֹת כָּל בֹּצֵעַ בָּצַע אֶת נֶפֶשׁ\" וְגוֹ'. וְאַף עַל פִּי כֵן אִם לֹא הָיְתָה הַגְּזֵלָה קַיֶּמֶת וְרָצָה הַגַּזְלָן לַעֲשׂוֹת תְּשׁוּבָה וּבָא מֵאֵלָיו וְהֶחְזִיר דְּמֵי הַגְּזֵלָה. תַּקָּנַת חֲכָמִים הִיא שֶׁאֵין מְקַבְּלִין מִמֶּנּוּ אֶלָּא עוֹזְרִין אוֹתוֹ וּמוֹחֲלִין לוֹ כְּדֵי לְקָרֵב הַדֶּרֶךְ הַיְשָׁרָה עַל הַשָּׁבִים. וְכָל הַמְקַבֵּל מִמֶּנּוּ דְּמֵי הַגְּזֵלָה אֵין רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ:"],"Mishneh Torah, Robbery and Lost Property 4":["קְנָּס קָנְסוּ חֲכָמִים לַגַּזְלָנִין שֶׁיִּהְיֶה הַנִּגְזָל נִשְׁבָּע עַל כָּל מַה שֶּׁיִּטְעֹן וְנוֹטֵל מִן הַגַּזְלָן. וְהוּא שֶׁיִּהְיֶה זֶה מֻחְזָק שֶׁגְּזָלוֹ בִּשְׁנֵי עֵדִים:","כֵּיצַד. הֲרֵי שֶׁנִּכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ לְמַשְׁכְּנוֹ בִּפְנֵי עֵדִים וְלֹא הָיָה כְּלוּם תַּחַת כְּנָפָיו וְיָצָא וְכֵלִים מֻטָּלִין לוֹ תַּחַת כְּנָפָיו וְלֹא יָדְעוּ הָעֵדִים מַה הֵן וּבַעַל הַבַּיִת אוֹמֵר כָּךְ וְכָךְ גְּזָלְתַּנִי. בֵּין שֶׁאָמַר הַגַּזְלָן מֵעוֹלָם לֹא נִכְנַסְתִּי וְלֹא נָטַלְתִּי כְּלוּם. בֵּין שֶׁאָמַר נִכְנַסְתִּי לְמַשְׁכֵּן כְּמוֹ שֶׁרָאוּ הָעֵדִים אֲבָל לֹא נָטַלְתִּי וְלֹא הָיָה תַּחַת כְּנָפַי אֶלָּא כֵּלִים שֶׁלִּי. בֵּין שֶׁאָמַר נָטַלְתִּי כְּלִי זֶה וּבַעַל הַבַּיִת טוֹעֵן שֶׁנָּטַל זֶה וּכְלִי אַחֵר. הֲרֵי בַּעַל הַבַּיִת נִשְׁבַּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כָּל מַה שֶּׁיִּטְעֹן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁטָּעַן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶן אוֹ שֶׁהוּא אָמוּד שֶׁמַּפְקִידִין אֶצְלוֹ אוֹתָן דְּבָרִים שֶׁטָּעַן וְטָעַן בִּדְבָרִים שֶׁאֶפְשָׁר שֶׁיִּנָּטְלוּ תַּחַת הַכְּנָפַיִם כְּמוֹ שֶׁהֵעִידוּ הָעֵדִים:","רָאוּהוּ עֵדִים שֶׁנִּכְנַס לְמַשְׁכֵּן אֶת חֲבֵרוֹ וְלֹא רָאוּהוּ בְּעֵת שֶׁיָּצָא אוֹ שֶׁיָּצָא וְאֵין נִרְאֶה תַּחַת כְּנָפָיו כְּלוּם וּבַעַל הַבַּיִת טוֹעֵן וְאוֹמֵר כָּךְ וְכָךְ נָטַל. אֲפִלּוּ אוֹמֵר מֵעוֹלָם לֹא נִכְנַסְתִּי שֶׁהֲרֵי מַכְחִישׁ אֶת הָעֵדִים הֲרֵי זֶה פָּטוּר. שֶׁאִם אָמַר נִכְנַסְתִּי וְלֹא נָטַלְתִּי נִשְׁבַּע שְׁבוּעַת הֶסֵּת שֶׁלֹּא נָטַל כְּלוּם וְהוֹלֵךְ. שֶׁאֶפְשָׁר שֶׁיִּכָּנֵס לִגְזל וְלֹא גָּזַל:","הָיָה עֵד אֶחָד מְעִידוֹ שֶׁנִּכְנַס וְנָטַל כֵּלִים תַּחַת כְּנָפָיו וְאֵינוֹ יוֹדֵעַ מַה הֵן. וְהוּא אוֹמֵר לֹא גָּזַלְתִּי כְּלוּם אוֹ שֶׁאָמַר בְּחוֹבִי נָטַלְתִּי. הוֹאִיל וְאֵין הָעֵד יוֹדֵעַ מֶה הָיָה תַּחַת כְּנָפָיו הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁלֹּא גָּזַל. שֶׁאֵינוֹ מֻחְזָק בְּגַזְלָנוּת אֶלָּא בִּשְׁנֵי עֵדִים:","כְּשֵׁם שֶׁבַּעַל הַבַּיִת נִשְׁבָּע וְנוֹטֵל מִן הַגַּזְלָן כָּךְ שׁוֹמֵר שֶׁל בַּעַל הַבַּיִת אֲפִלּוּ אִשְׁתּוֹ שֶׁל שׁוֹמֵר נִשְׁבַּעַת שֶׁזֶּה נָטַל כָּךְ וְכָךְ וּמְשַׁלֵּם הַגַּזְלָן:","הָיָה שָׁם לְקִיטוֹ אוֹ שְׂכִירוֹ שֶׁל בַּעַל הַבַּיִת אֵינָן נִשְׁבָּעִין וְנוֹטְלִין. וְאֵין הַנִּגְזָל יָכוֹל לִשָּׁבַע שֶׁהֲרֵי לֹא הָיָה בְּבֵיתוֹ בְּשָׁעָה שֶׁנִּגְזַל וְאֵין הָעֵדִים יוֹדְעִים מַה נָּטַל תַּחַת כְּנָפָיו כְּדֵי לְחַיֵּב הַגַּזְלָן לְהַחְזִיר. וְאֵין מַשְׁבִּיעִין אֶת הַגַּזְלָן מִפְּנֵי שֶׁהוּא חָשׁוּד עַל הַשְּׁבוּעָה:","וְכֵיצַד עוֹשִׂים בְּדִין זֶה. מַחֲרִים בַּעַל הַבַּיִת חֵרֶם סְתָם עַל מִי שֶׁנָּטַל מִבֵּיתוֹ כְּלוּם וְאֵינוֹ מוֹדֶה בְּבֵית דִּין. וַאֲפִלּוּ הוֹדָה הַגַּזְלָן שֶׁגָּזַל קְצָת מַחְזִיר הַמִּקְצָת שֶׁהוֹדָה בָּהּ בִּלְבַד שֶׁהֲרֵי אֵין בַּעַל הַבַּיִת טוֹעֲנוֹ טַעֲנַת וַדַּאי:","הַגּוֹזֵל אֶחָד מֵחֲמִשָּׁה וְאֵין יָדוּעַ מִי הוּא הַנִּגְזָל וְכָל אֶחָד וְאֶחָד מֵהֶן תּוֹבְעוֹ וְאוֹמֵר לִי גָּזַלְתָּ אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁגָּזַל הֲרֵי כָּל אֶחָד מֵהֶן נִשְׁבָּע שֶׁזֶּה גְּזָלוֹ וּמְשַׁלֵּם גְּזֵלָה לְכָל אֶחָד וְאֶחָד. אַף דָּבָר זֶה קְנָס הוּא שֶׁקְּנָסוּהוּ חֲכָמִים מִפְּנֵי שֶׁעָבַר עֲבֵרָה וְגָזַל. אֲבָל דִּין תּוֹרָה אֵינוֹ חַיָּב לְשַׁלֵּם מִסָּפֵק:","אָמַר לִשְׁנַיִם גָּזַלְתִּי אֶחָד מִכֶּם אוֹ אָבִיו שֶׁל אֶחָד מִכֶּם וְאֵינִי יוֹדֵעַ אֵיזֶהוּ. אִם בָּא לָצֵאת יְדֵי שָׁמַיִם חַיָּב לְשַׁלֵּם גְּזֵלָה לְכָל אֶחָד וְאֶחָד. אֲבָל בְּדִין אֵינוֹ נוֹתֵן אֶלָּא גְּזֵלָה אַחַת וְהֵן חוֹלְקִין אוֹתָהּ בֵּינֵיהֶן. שֶׁהֲרֵי אֵין אֶחָד מֵהֶן יוֹדֵעַ שֶׁנִּגְזַל אֶלָּא זֶה בָּא וְהוֹדִיעָם. וְלֹא קָנְסוּ חֲכָמִים בְּדָבָר זֶה מִפְּנֵי שֶׁאֵין לוֹ תּוֹבֵעַ:","הַטּוֹעֵן אֶת חֲבֵרוֹ וְאָמַר לוֹ גְּזָלְתַּנִי מֵאָה. אִם אָמַר לֹא גָּזַלְתִּי נִשְׁבַּע שְׁבוּעַת הֶסֵּת כְּדִין כָּל נִתְבָּע. וְאִם הוֹדָה שֶׁגְּזָלוֹ חֲמִשִּׁים מְשַׁלֵּם חֲמִשִּׁים וְנִשְׁבַּע שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר כְּדִין כָּל מוֹדֶה בְּמִקְצָת שֶׁהֲרֵי לֹא הֻחְזַק גַּזְלָן בְּעֵדִים. וְכֵן הַטּוֹעֵן אֶת חֲבֵרוֹ שֶׁנִּכְנַס לְבֵיתוֹ וּגְזָלוֹ כֵּלִים וְהוּא אוֹמֵר דֶּרֶךְ מַשְׁכּוֹן לָקַחְתִּי בְּחוֹב שֶׁיֵּשׁ לִי אֶצְלְךָ וּבַעַל הַבַּיִת אוֹמֵר אֵין לְךָ בְּיָדִי כְּלוּם אַף עַל פִּי שֶׁהוֹדָה שֶׁמִּשְׁכְּנוֹ שֶׁלֹּא בִּרְשׁוּת הוֹאִיל וְאֵין שָׁם עֵדִים שֶׁמְּעִידִים שֶׁגָּזַל הֲרֵי זֶה נִשְׁבָּע וְגוֹבֶה חוֹבוֹ מִן הַמַּשְׁכּוֹן שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר. וְהוֹאִיל וְהוּא נִשְׁבָּע וְנוֹטֵל הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת טוֹעֵן:","רָאוּהוּ עֵדִים שֶׁנִּכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ שֶׁלֹּא בִּפְנֵי בַּעַל הַבַּיִת וְנָטַל מִשָּׁם כֵּלִים. אַף עַל פִּי שֶׁהוֹצִיאָן מְגֻלִּין וְאַף עַל פִּי שֶׁבַּעַל הַבַּיִת הַזֶּה עָשׂוּי לִמְכֹּר אֶת כֵּלָיו. אִם טָעַן וְאָמַר דֶּרֶךְ גֵּזֶל לְקָחָן וְהַלָּה אוֹמֵר בִּרְשׁוּתְךָ בָּאתִי וְאַתָּה מְכַרְתָּם לִי אוֹ נְתָתַּם לִי אוֹ בְּחוֹב שֶׁיֵּשׁ לִי אֶצְלְךָ תְּפַשְׂתִּים אֵינוֹ נֶאֱמָן. שֶׁכָּל הַנִּכְנָס לְבֵית חֲבֵרוֹ שֶׁלֹּא בְּפָנָיו וְנָטַל כֵּלִים מִשָּׁם וְהוֹצִיאָן בִּפְנֵי עֵדִים הֲרֵי זֶה בְּחֶזְקַת גַּזְלָן. לְפִיכָךְ מַחְזִיר הַכֵּלִים לְבַעַל הַבַּיִת וְאֵין כָּאן שְׁבוּעָה שֶׁהֲרֵי הָעֵדִים רָאוּ מַה גָּזַל. וְאַחַר שֶׁיַּחְזִיר חוֹזֵר וְתוֹבֵעַ אֶת בַּעַל הַבַּיִת בְּכָל מַה שֶּׁיִּטְעֹן וְהַדִּין בֵּינֵיהֶן:","וְכֵן אִם הָיָה שָׁם עֵד אֶחָד בִּלְבַד וּבַעַל הַבַּיִת טוֹעֵן שֶׁגָּזוּל הוּא כְּלִי זֶה בְּיָדוֹ וְהַלָּה אוֹמֵר לָקוּחַ הוּא בְּיָדִי אוֹ בְּחוֹב גְּבִיתִיו אוֹ שֶׁלִּי הָיָה וּפִקָּדוֹן הוּא אֶצְלְךָ הֲרֵי זֶה חַיָּב לְהַחְזִיר הַכְּלִי לִבְעָלָיו בְּלֹא שְׁבוּעָה שֶׁאִלּוּ הָיוּ שָׁם שְׁנֵי עֵדִים הָיָה חַיָּב לְשַׁלֵּם וְעַכְשָׁו שֶׁאֵין שָׁם אֶלָּא עֵד אֶחָד חַיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע שֶׁהֲרֵי אֵינוֹ מַכְחִישׁ אֶת הָעֵד וְכָל הַמְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע מְשַׁלֵּם. לְפִיכָךְ אִם כָּפַר וְאָמַר לֹא נִכְנַסְתִּי לְבֵיתוֹ וְלֹא נָטַלְתִּי כְּלוּם הוֹאִיל וְאֵין שָׁם אֶלָּא עֵד אֶחָד וְהוּא מַכְחִישׁוֹ הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה שֶׁלֹּא לָקַח מִבֵּיתוֹ כְּלוּם וְנִפְטָר:","מַעֲשֶׂה בְּאֶחָד שֶׁחָטַף לָשׁוֹן שֶׁל כֶּסֶף מִיַּד חֲבֵרוֹ בִּפְנֵי עֵד אֶחָד. וּבָא הַחוֹטֵף וְאָמַר חָטַפְתִּי וְשֶׁלִּי חָטַפְתִּי. וְחִיְּבוּהוּ חֲכָמִים לְהַחְזִיר מִפְּנֵי שֶׁהוּא מְחֻיָּב שְׁבוּעָה בְּעֵד זֶה וְאֵינוֹ יָכוֹל לִשָּׁבַע שֶׁהֲרֵי הוֹדָה כְּמוֹ שֶׁאָמַר הָעֵד. וְאִלּוּ לֹא הָיָה שָׁם עֵד כְּלָל הָיָה נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁשֶּׁלּוֹ חָטַף. וְאִלּוּ הִכְחִישׁ הָעֵד וְאָמַר מֵעוֹלָם לֹא חָטַפְתִּי הָיָה נִשְׁבַּע שְׁבוּעַת הַתּוֹרָה שֶׁלֹּא חָטַף. וּכְדִין זֶה דָּנִין בְּכָל כַּיּוֹצֵא בָּזֶה בְּכָל מָקוֹם:","חָטַף מִמֶּנּוּ זְהוּבִים [בְּעֵד אֶחָד] וְהוּא אוֹמֵר שֶׁלִּי חָטַפְתִּי וְעֶשְׂרִים הָיוּ אַף עַל פִּי שֶׁאֵין הָעֵד יוֹדֵעַ כַּמָּה חָטַף הֲרֵי זֶה מְשַׁלֵּם הָעֶשְׂרִים שֶׁהֲרֵי יָדַע בְּוַדַּאי שֶׁזְּהוּבִים חָטַף וְאִלּוּ הָיוּ שְׁנַיִם הָיָה חַיָּב לְשַׁלֵּם וְנִמְצָא בְּעֵד אֶחָד מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע כְּמוֹ שֶׁבֵּאַרְנוּ:","אָמַר הַחוֹטֵף עֶשְׂרִים חָטַפְתִּי וְשֶׁלִּי הֵן וְהַנִּגְזָל אוֹמֵר מֵאָה חָטַף הוֹאִיל וְאֵין הָעֵד יוֹדֵעַ מִנְיָנָן הֲרֵי מְשַׁלֵּם הָעֶשְׂרִים שֶׁהוֹדָה בָּהֶן שֶׁחֲטָפָן וְנִשְׁבַּע שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר שֶׁהֲרֵי נִתְחַיֵּב בְּמִקְצָת. וְדַעְתִּי נוֹטָה בָּזֶה שֶׁיִּשָּׁבַע הֶסֵּת שֶׁהֲרֵי לֹא הוֹדָה כְּלוּם אֶלָּא אָמַר שֶׁלִּי חָטַפְתִּי:","נִכְנַס לְבֵיתוֹ שֶׁל חֲבֵרוֹ שֶׁלֹּא בְּפָנָיו וְנָטַל מִשָּׁם כֵּלִים בִּפְנֵי עֵד אֶחָד וְאֵין הָעֵד יוֹדֵעַ כַּמָּה נָטַל (הֲרֵי) בַּעַל הַבַּיִת אוֹמֵר עֶשְׂרִים כֵּלִים הָיוּ בְּבֵיתִי וְהַגּוֹזֵל אוֹמֵר לֹא נָטַלְתִּי אֶלָּא עֲשָׂרָה וְהֵם שֶׁלִּי חַיָּב לְהַחְזִיר הָעֲשָׂרָה מִפְּנֵי שֶׁהוּא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע. וְאֵינוֹ נִשְׁבָּע עַל הַשְּׁאָר אֲפִלּוּ שְׁבוּעַת הֶסֵּת מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לִטְעֹן עַל הַגַּזְלָן טַעֲנַת וַדַּאי:"],"Mishneh Torah, Sabbath 15":["עוֹמֵד אָדָם בִּרְשׁוּת הָרַבִּים וּמְטַלְטֵל בִּרְשׁוּת הַיָּחִיד כֻּלָּהּ. וְעוֹמֵד בִּרְשׁוּת הַיָּחִיד וּמִטַּלְטֵל בִּרְשׁוּת הָרַבִּים וּבִלְבַד שֶׁלֹּא יוֹצִיא חוּץ לְאַרְבָּעָה אַמּוֹת. וְאִם הוֹצִיא פָּטוּר מִפְּנֵי שֶׁהוּא בִּרְשׁוּת אַחֶרֶת. וְכֵן עוֹמֵד אָדָם בִּרְשׁוּת הַיָּחִיד וּפוֹתֵחַ בִּרְשׁוּת הָרַבִּים, בִּרְשׁוּת הָרַבִּים וּפוֹתֵחַ בִּרְשׁוּת הַיָּחִיד. בְּהֵמָה שֶׁהָיְתָה רֻבָּהּ בַּחוּץ וְרֹאשָׁהּ בִּפְנִים אוֹבְסִין אוֹתָהּ. וּבְגָמָל עַד שֶׁיְּהֵא רֹאשׁוֹ וְרֻבּוֹ בִּפְנִים הוֹאִיל וְצַוָּארוֹ אָרֹךְ:","לֹא יַעֲמֹד אָדָם בִּרְשׁוּת הַיָּחִיד וְיִשְׁתֶּה בִּרְשׁוּת הָרַבִּים. בִּרְשׁוּת הָרַבִּים וְיִשְׁתֶּה בִּרְשׁוּת הַיָּחִיד. אֶלָּא אִם כֵּן הִכְנִיס רֹאשׁוֹ וְרֻבּוֹ לְמָקוֹם שֶׁהוּא שׁוֹתֶה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה שׁוֹתֶה בְּכֵלִים נָאִים שֶׁהוּא צָרִיךְ לָהֶן. גְּזֵרָה שֶׁמָּא יוֹצִיאֵם. אֲבָל אִם הָיוּ כֵּלִים שֶׁאֵינָן נָאִים שֶׁאֵינוֹ צָרִיךְ לָהֶן. אוֹ שֶׁהָיָה הַבּוֹר בְּכַרְמְלִית אַף עַל פִּי שֶׁהַכֵּלִים נָאִים. מַכְנִיס רֹאשׁוֹ בִּלְבַד וְשׁוֹתֶה בִּמְקוֹמוֹ וְאַף עַל פִּי שֶׁלֹּא הִכְנִיס רֹאשׁוֹ וְרֻבּוֹ:","עוֹמֵד אָדָם בִּרְשׁוּת הָרַבִּים וְקוֹלֵט מִן הָאֲוִיר מִן הַמַּיִם הַמְקַלְּחִין מִן הַצִּנּוֹר אוֹ מִן הַכֹּתֶל וְשׁוֹתֶה. וּבִלְבַד שֶׁלֹּא יִגַּע בַּצִּנּוֹר אוֹ בַּכֹּתֶל וְיִקְלֹט מֵעַל גַּבָּן. וְאִם נָגַע אִם הָיָה מָקוֹם שֶׁנָּגַע בּוֹ לְמַעְלָה מֵעֲשָׂרָה בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לַגַּג הֲרֵי זֶה אָסוּר. שֶׁנִּמְצָא כְּעוֹקֵר מֵעַל הַגַּג שֶׁהוּא רְשׁוּת הַיָּחִיד. וְכֵן אִם הָיָה בַּצִּנּוֹר אַרְבָּעָה עַל אַרְבָּעָה בֵּין שֶׁהָיָה הַצִּנּוֹר בְּתוֹךְ עֲשָׂרָה בֵּין שֶׁהָיָה לְמַעְלָה מֵעֲשָׂרָה וְקָלַט מִמֶּנּוּ מַיִם הֲרֵי זֶה אָסוּר. וְלָמָּה אֵינוֹ חַיָּב מִפְּנֵי שֶׁלֹּא נָחוּ הַמַּיִם אֶלָּא הֲרֵי הֵן נִזְחָלִין וְהוֹלְכִין:","זִיז שֶׁלִּפְנֵי הַחַלּוֹן יוֹצֵא בָּאֲוִיר שֶׁעַל רְשׁוּת הָרַבִּים. אִם הָיָה לְמַעְלָה מֵעֲשָׂרָה טְפָחִים מֻתָּר לְהִשְׁתַּמֵּשׁ עָלָיו שֶׁאֵין רְשׁוּת הָרַבִּים תוֹפֶסֶת אֶלָּא עֲשָׂרָה טְפָחִים. לְפִיכָךְ מֻתָּר לְהִשְׁתַּמֵּשׁ בְּכָל הַכֹּתֶל עַד עֲשָׂרָה טְפָחִים הַתַּחְתּוֹנִים:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה זִיז אֶחָד יוֹצֵא בָּאֲוִיר. אֲבָל אִם הָיוּ יוֹצְאִים בַּכֹּתֶל שְׁנֵי זִיזִין זֶה לְמַטָּה מִזֶּה אַף עַל פִּי שֶׁשְּׁנֵיהֶם לְמַעְלָה מֵעֲשָׂרָה. אִם יֵשׁ בַּזִּיז הָעֶלְיוֹן שֶׁלִּפְנֵי הַחַלּוֹן רֹחַב אַרְבָּעָה עַל אַרְבָּעָה אָסוּר לְהִשְׁתַּמֵּשׁ עָלָיו. מִפְּנֵי שֶׁהוּא רְשׁוּת בִּפְנֵי עַצְמוֹ וְהַזִּיז שֶׁתַּחְתָּיו רְשׁוּת אַחֶרֶת. וְאָסְרוּ זֶה עַל זֶה. שֶׁאֵין שְׁתֵּי רְשׁוּיוֹת מִשְׁתַּמְּשׁוֹת בִּרְשׁוּת אַחַת:","אֵין בָּעֶלְיוֹן אַרְבָּעָה וְאֵין בַּתַּחְתּוֹן אַרְבָּעָה. מִשְׁתַּמֵּשׁ בִּשְׁנֵיהֶן וְכֵן בְּכָל הַכֹּתֶל עַד עֲשָׂרָה טְפָחִים הַתַּחְתּוֹנִים. הָיָה בַּתַּחְתּוֹן אַרְבָּעָה וְהָעֶלְיוֹן אֵין בּוֹ אַרְבָּעָה אֵינוֹ מִשְׁתַּמֵּשׁ בָּעֶלְיוֹן אֶלָּא כְּנֶגֶד חַלּוֹנוֹ בִּלְבַד. אֲבָל בִּשְׁאָר הַזִּיז שֶׁבִּשְׁנֵי צִדְדֵי הַחַלּוֹן אָסוּר לְהִשְׁתַּמֵּשׁ מִפְּנֵי זֶה שֶׁתַּחְתָּיו שֶׁחָלַק רְשׁוּת לְעַצְמוֹ:","כָּל זִיז הַיּוֹצֵא עַל אֲוִיר רְשׁוּת הָרַבִּים שֶׁמֻּתָּר לְהִשְׁתַּמֵּשׁ עָלָיו. כְּשֶׁהוּא מִשְׁתַּמֵּשׁ בּוֹ אֵין נוֹתְנִין עָלָיו וְאֵין נוֹטְלִין מִמֶּנּוּ אֶלָּא כְּלֵי חֶרֶס וּזְכוּכִית וְכַיּוֹצֵא בָּהֶן שֶׁאִם יִפְּלוּ לִרְשׁוּת הָרַבִּים יִשָּׁבְרוּ. אֲבָל שְׁאָר כֵּלִים וָאֳכָלִין אֲסוּרִים שֶׁמָּא יִפְּלוּ לִרְשׁוּת הָרַבִּים וִיבִיאֵם:","שְׁנֵי בָּתִּים בִּשְׁנֵי צִדֵּי רְשׁוּת הָרַבִּים זָרַק מִזּוֹ לָזוֹ לְמַעְלָה מֵעֲשָׂרָה פָּטוּר וְהוּא שֶׁיִּהְיוּ שְׁנֵיהֶם שֶׁלּוֹ אוֹ שֶׁיִּהְיֶה בֵּינֵיהֶם עֵרוּב. וַאֲפִלּוּ בְּגָדִים וּכְלֵי מַתָּכוֹת מֻתָּר לִזְרֹק. וְאִם הָיָה זֶה לְמַעְלָה מִזֶּה וְלֹא הָיָה בְּשָׁוֶה אָסוּר לִזְרֹק בֶּגֶד וְכַיּוֹצֵא בּוֹ שֶׁמָּא יִפּל וִיבִיאֶנּוּ. אֲבָל כְּלֵי חֶרֶס וְכַיּוֹצֵא בָּהֶן זוֹרֵק:","בּוֹר בִּרְשׁוּת הָרַבִּים וְחַלּוֹן עַל גַּבָּיו הַבּוֹר וְחֻלְיָתוֹ מִצְטָרְפִים לַעֲשָׂרָה וּמְמַלְּאִין מִמֶּנּוּ בְּשַׁבָּת. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה סָמוּךְ לַכֹּתֶל בְּתוֹךְ אַרְבָּעָה טְפָחִים שֶׁאֵין אָדָם יָכוֹל לַעֲבֹר שָׁם. אֲבָל אִם הָיָה מֻפְלָג אֵין מְמַלְּאִין מִמֶּנּוּ אֶלָּא אִם כֵּן הָיְתָה חֻלְיָתוֹ גְּבוֹהָה עֲשָׂרָה שֶׁנִּמְצָא הַדְּלִי כְּשֶׁיֵּצֵא מִן הַחֻלְיָא יֵצֵא לִמְקוֹם פְּטוֹר:","אַשְׁפָּה בִּרְשׁוּת הָרַבִּים גְּבוֹהָה עֲשָׂרָה טְפָחִים וְחַלּוֹן עַל גַּבָּהּ שׁוֹפְכִין לָהּ מַיִם בְּשַׁבָּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאַשְׁפָּה שֶׁל רַבִּים שֶׁאֵין דַּרְכָּהּ לְהִפָּנוֹת. אֲבָל שֶׁל יָחִיד אֵין שׁוֹפְכִין עָלֶיהָ שֶׁמָּא תִּתְפַּנֶּה וְנִמְצְאוּ שׁוֹפְכִין כְּדַרְכָּן בִּרְשׁוּת הָרַבִּים:","אַמַּת הַמַּיִם שֶׁהִיא עוֹבֶרֶת בֶּחָצֵר אִם יֵשׁ בְּגָבְהָהּ עֲשָׂרָה טְפָחִים וּבְרָחְבָּהּ אַרְבָּעָה אוֹ יוֹתֵר עַל כֵּן עַד עֶשֶׂר אַמּוֹת אֵין מְמַלְּאִין מִמֶּנָּה בְּשַׁבָּת אֶלָּא אִם כֵּן עָשׂוּ לָהּ מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים בַּכְּנִיסָה וּבַיְצִיאָה. וְאִם אֵין בְּגָבְהָהּ עֲשָׂרָה אוֹ שֶׁאֵין בְּרָחְבָּהּ אַרְבָּעָה מְמַלְּאִין מִמֶּנָּה בְּלֹא מְחִצָּה:","הָיָה בְּרָחְבָּהּ יֶתֶר מֵעֶשֶׂר אַמּוֹת אַף עַל פִּי שֶׁאֵין בְּגָבְהָהּ עֲשָׂרָה אֵין מְמַלְּאִין מִמֶּנָּה עַד שֶׁיַּעֲשֶׂה לָהּ מְחִצָּה. שֶׁכָּל יֶתֶר עַל עֶשֶׂר פִּרְצָה הִיא וּמַפְסֶדֶת הַמְּחִצּוֹת. וּמַהוּ לְטַלְטֵל בְּכָל הֶחָצֵר. אִם נִשְׁאַר מִצַּד הַפִּרְצָה פַּס מִכָּאן וּפַס מִכָּאן בְּכָל שֶׁהוּא אוֹ פַּס רֹחַב אַרְבָּעָה טְפָחִים מֵרוּחַ אַחַת מֻתָּר לְטַלְטֵל בְּכָל הֶחָצֵר וְאֵין אָסוּר אֶלָּא לְמַלְּאוֹת מִן הָאַמָּה בִּלְבַד. אֲבָל אִם לֹא נִשְׁאַר פַּס כְּלָל אָסוּר לְטַלְטֵל בְּכָל הֶחָצֵר שֶׁהֲרֵי נִפְרְצָה חָצֵר לַיָּם שֶׁהוּא כַּרְמְלִית:","וְהֵיאַךְ מַעֲמִידִין אֶת הַמְּחִצָּה בְּמַיִם. אִם הָיְתָה לְמַעְלָה מִן הַמַּיִם צָרִיךְ שֶׁיִּהְיֶה טֶפַח מִן הַמְּחִצָּה יוֹרֵד בְּתוֹךְ הַמַּיִם. וְאִם הָיְתָה הַמְּחִצָּה כֻּלָּהּ יוֹרֶדֶת בְּתוֹךְ הַמַּיִם צָרִיךְ שֶׁיִּהְיֶה טֶפַח מִמֶּנָּה יוֹצֵא לְמַעְלָה מִן הַמַּיִם. כְּדֵי שֶׁיִּהְיוּ הַמַּיִם שֶׁבֶּחָצֵר מֻבְדָּלִין אַף עַל פִּי שֶׁאֵין הַמְּחִצָּה מַגַּעַת עַד הַקַּרְקַע הוֹאִיל וְיֵשׁ בָּהּ עֲשָׂרָה טְפָחִים הֲרֵי זוֹ מֻתֶּרֶת. וְלֹא הִתִּירוּ מְחִצָּה תְּלוּיָה אֶלָּא בְּמַיִם בִּלְבַד. שֶׁאִסּוּר טִלְטוּל בְּמַיִם מִדִּבְרֵיהֶם וְהֵקֵלוּ בִּמְחִצָּה שֶׁאֵינָהּ אֶלָּא כְּדֵי לַעֲשׂוֹת הֶכֵּר:","אַמַּת הַמַּיִם הָעוֹבֶרֶת בֵּין הַחֲצֵרוֹת וְחַלּוֹנוֹת פְּתוּחוֹת אֵלֶיהָ. אִם אֵין בָּהּ כַּשִּׁעוּר מְשַׁלְשְׁלִין דְּלִי מִן הַחַלּוֹנוֹת וּמְמַלְּאִים מִמֶּנָּה בְּשַׁבָּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵינָהּ מֻפְלֶגֶת מִן הַכֹּתֶל שְׁלֹשָׁה טְפָחִים. אֲבָל אִם הָיְתָה מֻפְלֶגֶת מִן הַכֹּתֶל שְׁלֹשָׁה טְפָחִים אֵין מְמַלְּאִים מִמֶּנָּה אֶלָּא אִם כֵּן הָיוּ פַּסִּין יוֹצְאִין מִן הַכְּתָלִים מִכָּאן וּמִכָּאן שֶׁנִּמְצָא הָאַמָּה כְּאִלּוּ הִיא עוֹבֶרֶת בְּתוֹךְ הֶחָצֵר:","כְּצוֹצְרָה שֶׁהִיא לְמַעְלָה מִן הַיָּם וְחַלּוֹן בְּתוֹכָהּ עַל גַּבֵּי הַמַּיִם. אֵין מְמַלְּאִים מִמֶּנָּה בְּשַׁבָּת אֶלָּא אִם כֵּן עָשׂוּ מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים עַל גַּבֵּי הַמַּיִם כְּנֶגֶד הַחַלּוֹן שֶׁבַּכְּצוֹצְרָה. אוֹ תִּהְיֶה הַמְּחִצָּה יוֹרֶדֶת מִן הַכְּצוֹצְרָה כְּנֶגֶד הַמַּיִם וְרוֹאִין אוֹתָהּ כְּאִלּוּ יָרְדָה וְנָגְעָה עַד הַמַּיִם. וּכְשֵׁם שֶׁמְּמַלְּאִין מִזּוֹ שֶׁעָשׂוּ לָהּ מְחִצָּה כָּךְ שׁוֹפְכִין מִמֶּנָּה עַל הַיָּם. שֶׁהֲרֵי עַל הַכַּרְמְלִית הֵן שׁוֹפְכִין:","חָצֵר שֶׁהִיא פְּחוּתָה מֵאַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵין שׁוֹפְכִין בְּתוֹכָהּ מַיִם בְּשַׁבָּת מִפְּנֵי שֶׁהֵן יוֹצְאִין לִרְשׁוּת הָרַבִּים בִּמְהֵרָה. לְפִיכָךְ צָרִיךְ לַעֲשׂוֹת גּוּמָה מַחְזֶקֶת סָאתַיִם בְּתוֹךְ הֶחָצֵר אוֹ בִּרְשׁוּת הָרַבִּים בְּצַד הֶחָצֵר כְּדֵי שֶׁיִּהְיוּ הַמַּיִם נִקְבָּצִים בְּתוֹכָהּ. וְצָרִיךְ לִבְנוֹת עָלֶיהָ כִּפָּה מִבַּחוּץ כְּדֵי שֶׁלֹּא תֵּרָאֶה הָעוּקָה הַזֹּאת בִּרְשׁוּת הָרַבִּים. וְהֶחָצֵר וְהָאַכְסַדְרָה מִצְטָרְפִין לְאַרְבַּע אַמּוֹת. וְכַמָּה הוּא הַמָּקוֹם שֶׁמַּחֲזִיק סָאתַיִם חֲצִי אַמָּה עַל חֲצִי אַמָּה בְּרוּם שְׁלֹשָׁה חֻמְשֵׁי אַמָּה:","הָיְתָה הָעוּקָה פְּחוּתָה מִסָּאתַיִם שׁוֹפְכִין לָהּ בְּמִלּוּאָהּ. הָיְתָה מַחְזֶקֶת סָאתַיִם שׁוֹפְכִין לָהּ אֲפִלּוּ שִׁשִּׁים סְאָה שֶׁל מַיִם. וְאַף עַל פִּי שֶׁהַמַּיִם יִתְגַּבְּרוּ וְיָפוּצוּ מֵעַל הַגּוּמָה לַחוּץ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּימוֹת הַגְּשָׁמִים שֶׁהַחֲצֵרוֹת מִתְקַלְקְלוֹת וּסְתָם צִנּוֹרוֹת מְקַלְּחִין וְלֹא יָבוֹאוּ הָרוֹאִים לוֹמַר שֶׁזֶּה מִשְׁתַּמֵּשׁ בִּרְשׁוּת הָרַבִּים וְהַמַּיִם יוֹצְאִים מִכֹּחוֹ בִּרְשׁוּת הָרַבִּים. אֲבָל בִּימוֹת הַחַמָּה אִם הָיְתָה מַחְזֶקֶת סָאתַיִם אֵין שׁוֹפְכִין לָהּ אֶלָּא סָאתַיִם. הָיְתָה פְּחוּתָה מִסָּאתַיִם אֵין שׁוֹפְכִין לָהּ כָּל עִקָּר:","בִּיב שֶׁשּׁוֹפְכִין לוֹ מַיִם וְהֵן נִזְחָלִין וְהוֹלְכִין תַּחַת הַקַּרְקַע וְיוֹצְאִין לִרְשׁוּת הָרַבִּים. וְכֵן צִנּוֹר שֶׁשּׁוֹפְכִין עַל פִּיו מַיִם וְהֵן נִזְחָלִין עַל הַכֹּתֶל וְיוֹרְדִין לִרְשׁוּת הָרַבִּים. אֲפִלּוּ הָיָה אֹרֶךְ הַכֹּתֶל אוֹ אֹרֶךְ הַדֶּרֶךְ שֶׁתַּחַת הָאָרֶץ מֵאָה אַמָּה אָסוּר לִשְׁפֹּךְ עַל פִּי הַבִּיב אוֹ עַל פִּי הַצִּנּוֹר מִפְּנֵי שֶׁהַמַּיִם יוֹצְאִין מִכֹּחוֹ לִרְשׁוּת הָרַבִּים. אֶלָּא שׁוֹפֵךְ חוּץ לַבִּיב וְהֵן יוֹרְדִין לַבִּיב:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּימוֹת הַחַמָּה אֲבָל בִּימוֹת הַגְּשָׁמִים שׁוֹפֵךְ וְשׁוֹנֶה וְאֵינוֹ נִמְנָע. שֶׁסְּתָם צִנּוֹרוֹת מְקַלְּחִין הֵן וְאָדָם רוֹצֶה שֶׁיִּבָּלְעוּ הַמַּיִם בִּמְקוֹמָן. הָיָה שׁוֹפֵךְ עַל פִּי הַבִּיב וְהַמַּיִם יוֹצְאִין לְכַרְמְלִית הֲרֵי זֶה מֻתָּר וַאֲפִלּוּ בִּימוֹת הַחַמָּה שֶׁלֹּא גָּזְרוּ עַל כֹּחוֹ בְּכַרְמְלִית. לְפִיכָךְ מֻתָּר לִשְׁפֹּךְ עַל כָּתְלֵי הַסְּפִינָה וְהֵם יוֹרְדִין לַיָּם:","לֹא יְמַלֵּא אָדָם מַיִם מִן הַיָּם וְהוּא בְּתוֹךְ הַסְּפִינָה אֶלָּא אִם כֵּן עָשָׂה מְקוֹם אַרְבָּעָה עַל אַרְבָּעָה יוֹצֵא מִן הַסְּפִינָה עַל הַיָּם. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה תּוֹךְ עֲשָׂרָה אֲבָל אִם הָיָה לְמַעְלָה מֵעֲשָׂרָה מִן הַיָּם מוֹצִיא זִיז כָּל שֶׁהוּא וּמְמַלֵּא. שֶׁהֲרֵי דֶּרֶךְ מְקוֹם פְּטוֹר מְמַלֵּא וְאֵינוֹ צָרִיךְ לְזִיז זֶה אֶלָּא מִשּׁוּם הֶכֵּר:","הַקּוֹרֵא בְּסֵפֶר בְּכַרְמְלִית וְנִתְגַּלְגֵּל מִקְצָת הַסֵּפֶר לִרְשׁוּת הָרַבִּים וּמִקְצָתוֹ בְּיָדוֹ. אִם נִתְגַּלְגֵּל לְחוּץ לְאַרְבַּע אַמּוֹת הוֹפְכוֹ עַל הַכְּתָב וּמַנִּיחוֹ. גְּזֵרָה שֶׁמָּא יִשָּׁמֵט כֻּלּוֹ מִיָּדוֹ וְיַעֲבִירֶנּוּ אַרְבַּע אַמּוֹת. נִתְגַּלְגֵּל לְתוֹךְ אַרְבַּע אַמּוֹת גּוֹלְלוֹ אֶצְלוֹ. וְכֵן אִם נִתְגַּלְגֵּל לִרְשׁוּת הַיָּחִיד גּוֹלְלוֹ אֶצְלוֹ. הָיָה קוֹרֵא בִּרְשׁוּת הַיָּחִיד וְנִתְגַּלְגֵּל לִרְשׁוּת הָרַבִּים אִם נָח בָּהּ הוֹפְכוֹ עַל הַכְּתָב. וְאִם לֹא נָח אֶלָּא הָיָה תָּלוּי בַּאֲוִיר רְשׁוּת הָרַבִּים וְלֹא הִגִּיעַ לָאָרֶץ גּוֹלְלוֹ אֶצְלוֹ:","הַמַּעֲבִיר קוֹץ כְּדֵי שֶׁלֹּא יִזּוֹקוּ בּוֹ רַבִּים. אִם הָיָה בִּרְשׁוּת הָרַבִּים מוֹלִיכוֹ פָּחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת. וְאִם הָיָה בְּכַרְמְלִית מוֹלִיכוֹ כְּדַרְכּוֹ אֲפִלּוּ מֵאָה אַמָּה. וְכֵן מֵת שֶׁהִסְרִיחַ וְנִתְבַּזָּה יֶתֶר מִדַּאי וְלֹא יָכְלוּ שְׁכֵנִים לַעֲמֹד מוֹצִיאִין אוֹתוֹ מֵרְשׁוּת הַיָּחִיד לְכַרְמְלִית. הַיּוֹרֵד לִרְחֹץ בַּיָּם כְּשֶׁהוּא עוֹלֶה מְנַגֵּב עַצְמוֹ שֶׁמָּא יַעֲבִיר מַיִם שֶׁעָלָיו אַרְבַּע אַמּוֹת בְּכַרְמְלִית:"],"Mishneh Torah, Sabbath 26":["כָּל כְּלֵי הָאוֹרֵג וַחֲבָלָיו וְקָנִים שֶׁלּוֹ מֻתָּר לְטַלְטְלָן כִּכְלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר חוּץ מִכֹּבֶד הָעֶלְיוֹן וְכֹבֶד הַתַּחְתּוֹן לְפִי שֶׁאֵין נִטָּלִין מִפְּנֵי שֶׁהֵן תְּקוּעִין. וְכֵן הָעַמּוּדִים שֶׁל אוֹרֵג אָסוּר לְטַלְטְלָן שֶׁמָּא יְתַקֵּן הַגֻּמּוֹת שֶׁלָּהֶן. וּשְׁאָר כְּלֵי הָאוֹרֵג מֻתָּרִין:","מִכְבָּדוֹת שֶׁל תְּמָרָה וְכַיּוֹצֵא בָּהֶן שֶׁמְּכַבְּדִין בָּהֶן אֶת הַקַּרְקַע הֲרֵי הֵן כִּכְלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר שֶׁהֲרֵי מֻתָּר לְכַבֵּד בְּשַׁבָּת. לְבֵנִים שֶׁנִּשְׁאֲרוּ מִן הַבִּנְיָן הֲרֵי הֵן כִּכְלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר מִפְּנֵי שֶׁרְאוּיִין לְהָסֵב עֲלֵיהֶן שֶׁהֲרֵי שָׁפִין אוֹתָן וּמְתַקְּנִין אוֹתָן. וְאִם צָבַר אוֹתָן הֲרֵי הִקְצָם וְאָסוּר לְטַלְטְלָם:","חֶרֶס קְטַנָּה מֻתָּר לְטַלְטְלָהּ אֲפִלּוּ בִּרְשׁוּת הָרַבִּים הוֹאִיל וּרְאוּיָה הִיא בְּחָצֵר לְכַסּוֹת בָּהּ פִּי כְּלִי קָטָן. מְגוּפַת חָבִית שֶׁנִּתְכַּתְתָּה הִיא וּשְׁבָרֶיהָ מֻתָּר לְטַלְטְלָהּ וְאִם זְרָקָהּ לָאַשְׁפָּה מִבְּעוֹד יוֹם אָסוּר לְטַלְטְלָהּ. כְּלִי שֶׁנִּתְרוֹעֵעַ לֹא יִתְלֹשׁ מִמֶּנּוּ חֶרֶס לְכַסּוֹת בּוֹ אוֹ לִסְמֹךְ בּוֹ:","מֻתָּר לְהַכְנִיס לְבֵית הַכִּסֵּא שָׁלֹשׁ אֲבָנִים מְקֻרְזָלוֹת לְקַנֵּחַ בָּהֶן וְכַמָּה שִׁעוּרָן כִּמְלֹא הַיָּד. אֲבָל אֲדָמָה שֶׁהִיא קְרוֹבָה לְהִתְפָּרֵךְ אָסוּר לְטַלְטְלָהּ לְקַנֵּחַ בָּהּ. וּמֻתָּר לְהַעֲלוֹת אֲבָנִים לַגַּג לְקַנֵּחַ בָּהֶן. יָרְדוּ עֲלֵיהֶן גְּשָׁמִים וְנִשְׁתַּקְעוּ בְּטִיט אִם רִשּׁוּמָן נִכָּר מֻתָּר לְטַלְטֵל. אֶבֶן שֶׁיֵּשׁ עָלֶיהָ טִנּוּף שֶׁוַּדַּאי לְקַנֵּחַ הִיא מֻתָּר לְטַלְטְלָהּ וַאֲפִלּוּ הִיא גְּדוֹלָה:","הָיָה לְפָנָיו צְרוֹר וְחֶרֶשׂ מְקַנֵּחַ בַּצְּרוֹר וְאִם הָיָה הַחֶרֶשׂ מֵאוֹגְנֵי כֵּלִים מְקַנֵּחַ בַּחֶרֶשׂ. הָיוּ לְפָנָיו צְרוֹר וַעֲשָׂבִים אִם הָיוּ עֲשָׂבִים רַכִּים מְקַנֵּחַ בָּהֶן וְאִם לָאו מְקַנֵּחַ בַּצְּרוֹר:","שְׁיָרֵי מַחְצְלָאוֹת שֶׁבָּלוּ הֲרֵי הֵן כִּכְלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר מִפְּנֵי שֶׁרְאוּיִין לְכַסּוֹת בָּהֶן הַטִּנּוּף. אֲבָל שְׁיָרֵי בְּגָדִים שֶׁבָּלוּ שֶׁאֵין בָּהֶן שְׁלֹשָׁה עַל שְׁלֹשָׁה אָסוּר לְטַלְטְלָן שֶׁאֵינָן רְאוּיִין לֹא לַעֲנִיִּים וְלֹא לַעֲשִׁירִים. שִׁבְרֵי הַתַּנּוּר מֻתָּר לְטַלְטְלָן וַהֲרֵי הֵן כְּכָל הַכֵּלִים שֶׁמְּלַאכְתָּן לְהֶתֵּר. כִּירָה שֶׁנִּשְׁמְטָה אַחַת מִיַּרְכוֹתֶיהָ אָסוּר לְטַלְטְלָהּ שֶׁמָּא יִתְקַע:","סֻלָּם שֶׁל עֲלִיָּה אָסוּר לְטַלְטְלוֹ שֶׁאֵין עָלָיו תּוֹרַת כְּלִי. וְשֶׁל שׁוֹבָךְ מֻתָּר לְהַטּוֹתוֹ. אֲבָל לֹא יוֹלִיכוֹ מִשּׁוֹבָךְ לְשׁוֹבָךְ שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבוֹא לָצוּד. קָנֶה שֶׁמּוֹסְקִין בּוֹ הַזֵּיתִים אִם יֵשׁ עָלָיו תּוֹרַת כְּלִי הֲרֵי הוּא כִּכְלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר. קָנֶה שֶׁהִתְקִינוֹ בַּעַל הַבַּיִת לִהְיוֹת פּוֹתֵחַ וְנוֹעֵל בּוֹ אִם יֵשׁ תּוֹרַת כְּלִי עָלָיו הֲרֵי הוּא כִּכְלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר:","דֶּלֶת שֶׁהָיָה לָהּ צִיר אַף עַל פִּי שֶׁאֵין לָהּ עַתָּה צִיר שֶׁהֱכִינָהּ לִסְתֹּם בָּהּ מָקוֹם מֻקְצֶה וְהִיא נִגְרֶרֶת שֶׁנּוֹטְלִין אוֹתָהּ וְסוֹתְמִין בָּהּ. וְכֵן חֲדָקִים שֶׁסּוֹתְמִין בָּהֶן הַפִּרְצָה. וְכֵן מַחְצֶלֶת הַנִּגְרֶרֶת. בִּזְמַן שֶׁקְּשׁוּרִין וּתְלוּיִין בַּכֹּתֶל סוֹתְמִין בָּהֶן וְנוֹעֲלִים בָּהֶם וְאִם לָאו אֵין נוֹעֲלִין בָּהֶן. וְאִם הָיוּ גְּבוֹהִים מֵעַל הָאָרֶץ נוֹעֲלִין בָּהֶן:","דֶּלֶת שֶׁהָיָה לָהּ לוּחַ אֶחָד שֶׁשּׁוֹמְטִין אוֹתָהּ וְנוֹעֲלִין בָּהּ אִם לֹא הָיָה לָהּ לְמַטָּה כֵּן כְּמוֹ אַסְקֻפָּה שֶׁמּוֹכִיחַ עָלֶיהָ שֶׁהִיא כְּלִי מוּכָן לִנְעִילָה אֵין נוֹעֲלִין בָּהּ. וְאִם יֵשׁ לְמַטָּה אַסְקֻפָּה נוֹעֲלִים בָּהּ. וְכֵן נֶגֶר שֶׁיֵּשׁ בְּרֹאשׁוֹ קְלֻסְטְרָא שֶׁמּוֹכַחַת עָלָיו שֶׁהוּא כְּלִי מוּכָן לִנְעִילָה וְאֵינוֹ קוֹרָה כִּשְׁאָר כָּל הַקּוֹרוֹת נוֹעֲלִין בּוֹ בְּשַׁבָּת:","נֶגֶר שֶׁאֵין בְּרֹאשׁוֹ קְלֻסְטְרָא אִם הָיָה קָשׁוּר וְתָלוּי בַּדֶּלֶת נוֹעֲלִין בּוֹ. וְכֵן אִם הָיָה נִטָּל וְאֶגְדּוֹ עִמּוֹ. אֲבָל אִם הָיָה אֶגְדּוֹ קָבוּעַ בַּדֶּלֶת וְהָיָה הַנֶּגֶר נִשְׁמָט כְּמוֹ קוֹרָה וּמַנִּיחִין אוֹתוֹ בַּזָּוִית וְחוֹזְרִין וְנוֹעֲלִין בּוֹ בְּעֵת שֶׁרוֹצִין הֲרֵי זֶה אָסוּר לִנְעל בּוֹ שֶׁאֵין עָלָיו תּוֹרַת כְּלִי וְאֵינוֹ אָגוּד וְאֵין בּוֹ אֶגֶד לְהוֹכִיחַ עָלָיו:","מְנוֹרָה שֶׁל חֻלְיוֹת בֵּין גְּדוֹלָה בֵּין קְטַנָּה אֵין מְטַלְטְלִין אוֹתָהּ שֶׁמָּא יַחֲזִירֶנָהּ בְּשַׁבָּת. הָיוּ בָּהּ חֲדָקִים וְהִיא נִרְאֵית כְּבַעֲלַת חֻלְיוֹת. אִם הָיְתָה גְּדוֹלָה הַנִּטֶּלֶת בִּשְׁתֵּי יָדַיִם אָסוּר לְטַלְטְלָהּ מִפְּנֵי כָּבְדָהּ. הָיְתָה קְטַנָּה מִזּוֹ מֻתָּר לְטַלְטְלָהּ:","מִנְעָל שֶׁעַל גַּבֵּי הָאִמּוּם שׁוֹמְטִין אוֹתוֹ בְּשַׁבָּת. מַכְבֵּשׁ שֶׁל בַּעֲלֵי בָּתִּים מַתִּירִין אֲבָל לֹא כּוֹבְשִׁין. וְשֶׁל כּוֹבְסִין לֹא יִגַּע בּוֹ מִפְּנֵי שֶׁהוּא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס. וְכֵן גִּזֵּי צֶמֶר אֵין מְטַלְטְלִין אוֹתָן מִפְּנֵי שֶׁהוּא מַקְפִּיד עֲלֵיהֶן. לְפִיכָךְ אִם יִחֲדָן לְתַשְׁמִישׁ מֻתָּרִין. וְהַשְּׁלָחִין מֻתָּר לְטַלְטְלָן בֵּין שֶׁהָיוּ שֶׁל בַּעַל הַבַּיִת אוֹ שֶׁל אֻמָּן מִפְּנֵי שֶׁאֵינוֹ מַקְפִּיד עֲלֵיהֶם:","כָּל דָּבָר מְטֻנָּף כְּגוֹן רְעִי וְקִיא וְצוֹאָה וְכַיּוֹצֵא בָּהֶן אִם הָיוּ בְּחָצֵר שֶׁיּוֹשְׁבִין בָּהּ מֻתָּר לְהוֹצִיאָן לְאַשְׁפָּה אוֹ לְבֵית הַכִּסֵּא וְזֶה הוּא הַנִּקְרָא גְּרָף שֶׁל רְעִי. וְאִם הָיוּ בְּחָצֵר אַחֶרֶת כּוֹפִין עֲלֵיהֶן כְּלִי כְּדֵי שֶׁלֹּא יֵצֵא הַקָּטָן וְיִתְלַכְלֵךְ בָּהֶן. רֹק שֶׁעַל הַקַּרְקַע דּוֹרְסוֹ לְפִי תֻּמּוֹ וְהוֹלֵךְ. מְטַלְטְלִין כְּנוּנָא מִפְּנֵי אֶפְרוֹ אַף עַל פִּי שֶׁיֵּשׁ עָלָיו שִׁבְרֵי עֵצִים מִפְּנֵי שֶׁהוּא כִּגְרָף שֶׁל רְעִי. וְאֵין עוֹשִׂין גְּרָף שֶׁל רְעִי לְכַתְּחִלָּה בְּשַׁבָּת. אֲבָל אִם נַעֲשָׂה מֵאֵלָיו אוֹ שֶׁעָבַר וְעָשָׂהוּ מוֹצִיאִין אוֹתוֹ:","שֶׁמֶן שֶׁיּוֹצֵא מִתַּחַת הַקּוֹרָה שֶׁל בֵּית הַבַּד בְּשַׁבָּת וְכֵן תְּמָרִים וּשְׁקֵדִים הַמּוּכָנִים לִסְחוֹרָה מֻתָּר לְאָכְלָם בְּשַׁבָּת. וַאֲפִלּוּ אוֹצָר שֶׁל תְּבוּאָה אוֹ תְּבוּאָה צְבוּרָה מַתְחִיל לְהִסְתַּפֵּק מִמֶּנָּה בְּשַׁבָּת שֶׁאֵין שׁוּם אֹכֶל שֶׁהוּא מֻקְצֶה בְּשַׁבָּת כְּלָל אֶלָּא הַכּל מוּכָן הוּא. חוּץ מִגְּרוֹגָרוֹת וְצִמּוּקִין שֶׁבַּמֻּקְצֶה בִּזְמַן שֶׁמְּיַבְּשִׁים אוֹתָם הוֹאִיל וּמַסְרִיחוֹת בֵּינְתַיִם וְאֵינָם רְאוּיִין לַאֲכִילָה הֲרֵי הֵן אֲסוּרִין בְּשַׁבָּת מִשּׁוּם מֻקְצֶה. חָבִית שֶׁנִּתְגַּלְּתָה וַאֲבַטִּיחַ שֶׁנִּשְׁבְּרָה אַף עַל פִּי שֶׁאֵינָן רְאוּיִין לַאֲכִילָה נוֹטְלָן וּמַנִּיחָן בְּמָקוֹם הַמֻּצְנָע. כַּיּוֹצֵא בּוֹ קָמֵעַ שֶׁאֵינוֹ מֻמְחֶה אַף עַל פִּי שֶׁאֵין יוֹצְאִין בּוֹ מְטַלְטְלִין אוֹתוֹ. מוֹתַר הַשֶּׁמֶן שֶׁבַּנֵּר וְשֶׁבַּקְּעָרָה שֶׁהִדְלִיקוּ בָּהֶן בְּאוֹתָהּ שַׁבָּת אָסוּר לְהִסְתַּפֵּק מִמֶּנּוּ בְּאוֹתָהּ שַׁבָּת מִפְּנֵי שֶׁהוּא מֻקְצֶה מֵחֲמַת אִסּוּר:","אוֹצָר שֶׁל תְּבוּאָה אוֹ שֶׁל כַּדֵּי יַיִן אַף עַל פִּי שֶׁמֻּתָּר לְהִסְתַּפֵּק מִמֶּנּוּ אָסוּר לְהַתְחִיל בּוֹ לְפַנּוֹתוֹ אֶלָּא לִדְבַר מִצְוָה כְּגוֹן שֶׁפִּנָּהוּ לְהַכְנָסַת אוֹרְחִין אוֹ לִקְבֹּעַ בּוֹ בֵּית הַמִּדְרָשׁ וְכֵיצַד מְפַנִּין אוֹתוֹ. כָּל אֶחָד וְאֶחָד מְמַלֵּא אַרְבַּע אוֹ חָמֵשׁ קֻפּוֹת עַד שֶׁגּוֹמְרִין. וְלֹא יְכַבְּדוּ קַרְקָעִיתוֹ שֶׁל אוֹצָר כְּמוֹ שֶׁבֵּאַרְנוּ אֶלָּא נִכְנָס וְיוֹצֵא בּוֹ וְעוֹשֶׂה שְׁבִיל בְּרַגְלָיו בִּכְנִיסָתוֹ וּבִיצִיאָתוֹ:","כָּל שֶׁהוּא רָאוּי לְמַאֲכַל בְּהֵמָה וְחַיָּה וְעוֹף הַמְּצוּיִין מְטַלְטְלִין אוֹתוֹ בְּשַׁבָּת. כֵּיצַד. מְטַלְטְלִין אֶת הַתֻּרְמוֹס הַיָּבֵשׁ מִפְּנֵי שֶׁהוּא מַאֲכָל לְעִזִּים אֲבָל לֹא אֶת הַלַּח. אֶת הֶחָצָב מִפְּנֵי שֶׁהוּא מַאֲכָל לִצְבָאִים. אֶת הַחַרְדָּל מִפְּנֵי שֶׁהוּא מַאֲכָל לְיוֹנִים. אֶת הָעֲצָמוֹת מִפְּנֵי שֶׁהֵן מַאֲכָל לִכְלָבִים. וְכֵן כָּל הַקְּלִפִּין וְהַגַּרְעִינִין הָרְאוּיִין לְמַאֲכַל בְּהֵמָה מְטַלְטְלִין אוֹתָן. וְשֶׁאֵינָן רְאוּיִין אוֹכֵל אֶת הָאֹכֶל וְזוֹרְקָן לְאַחֲרָיו וְאָסוּר לְטַלְטְלָן. מְטַלְטְלִין בָּשָׂר תָּפוּחַ מִפְּנֵי שֶׁהוּא מַאֲכָל לְחַיָּה. וּמְטַלְטְלִין בָּשָׂר חַי בֵּין תָּפֵל בֵּין מָלִיחַ מִפְּנֵי שֶׁרָאוּי לְאָדָם. וְכֵן דָּג מָלִיחַ. אֲבָל הַתָּפֵל אָסוּר לְטַלְטְלוֹ:","אֵין מְטַלְטְלִין שִׁבְרֵי זְכוּכִית אַף עַל פִּי שֶׁהֵן מַאֲכָל לְנַעֲמִיּוֹת. וְלֹא חֲבִילֵי זְמוֹרוֹת אַף עַל פִּי שֶׁהֵן מַאֲכָל לְפִילִים. וְלֹא אֶת הַלּוּף אַף עַל פִּי שֶׁהֵן מַאֲכָל לְעוֹרְבִים. מִפְּנֵי שֶׁאֵין אֵלּוּ וְכַיּוֹצֵא בָּהֶן מְצוּיִין אֵצֶל רֹב בְּנֵי אָדָם:","חֲבִילֵי קַשׁ וַחֲבִילֵי זְרָדִין אִם הִתְקִינָן לְמַאֲכַל בְּהֵמָה מְטַלְטְלִין אוֹתָן וְאִם לָאו אֵין מְטַלְטְלִין אוֹתָן. חֲבִילֵי סֵיאָה פּוּאָה וְאֵזוֹב וְקוֹרָנִית. הִכְנִיסָן לְעֵצִים אֵין מִסְתַּפֵּק מֵהֶם בְּשַׁבָּת. לְמַאֲכַל בְּהֵמָה מִסְתַּפֵּק מֵהֶן. וְכֵן בַּאֲמִינְתָּא וְכֵן בְּפֵיגָם וְכֵן בִּשְׁאָר מִינֵי תַּבְלִין:","אֵין גּוֹרְפִין מַאֲכָל מִלִּפְנֵי הַפְּטָם בֵּין בְּאֵבוּס שֶׁל כְּלִי בֵּין בְּאֵבוּס שֶׁל קַרְקַע. וְאֵין מְסַלְּקִין לַצְּדָדִין מִפְּנֵי הָרְעִי גְּזֵרָה שֶׁמָּא יַשְׁוֶה גֻּמּוֹת. נוֹטְלִין מִלִּפְנֵי הַחֲמוֹר וְנוֹתְנִין לִפְנֵי הַשּׁוֹר. אֲבָל אֵין נוֹטְלִין מִלִּפְנֵי הַשּׁוֹר וְנוֹתְנִין לִפְנֵי הַחֲמוֹר מִפְּנֵי שֶׁהַמַּאֲכָל שֶׁלִּפְנֵי הַשּׁוֹר מְטֻנָּף בְּרִירוֹ וְאֵין רָאוּי לְמַאֲכַל בְּהֵמָה אַחֶרֶת. וְכֵן עָלִים שֶׁרֵיחָם רַע וּמְאוּסִין וְאֵין הַבְּהֵמָה אוֹכַלְתָּן אָסוּר לְטַלְטְלָן. לְפִיכָךְ תְּלַאי שֶׁל דָּגִים אָסוּר לְטַלְטְלוֹ וְשֶׁל בָּשָׂר מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אַף עַל פִּי שֶׁאָסוּר לְטַלְטֵל אֶת הַמֵּת בְּשַׁבָּת סָכִין אוֹתוֹ וּמְדִיחִין אוֹתוֹ וּבִלְבַד שֶׁלֹּא יָזִיזוּ בּוֹ אֵיבָר. וְשׁוֹמְטִין אֶת הַכַּר מִתַּחְתָּיו כְּדֵי שֶׁיִּהְיֶה מֻטָּל עַל הַחוֹל בִּשְׁבִיל שֶׁיַּמְתִּין וְלֹא יַסְרִיחַ. וּמְבִיאִין כְּלֵי מֵיקֵר וּכְלֵי מַתָּכוֹת וּמַנִּיחִין לוֹ עַל כְּרֵסוֹ כְּדֵי שֶׁלֹּא יִתְפַּח. וּפוֹקְקִין אֶת נְקָבָיו שֶׁלֹּא יִכָּנֵס בָּהֶן הָרוּחַ. וְקוֹשְׁרִין אֶת הַלֶּחִי לֹא שֶׁיַּעֲלֶה אֶלָּא שֶׁלֹּא יוֹסִיף. וְאֵין מְעַמְּצִין אֶת עֵינָיו בְּשַׁבָּת:","מֵת הַמֻּטָּל בַּחַמָּה מַנִּיחַ עָלָיו כִּכָּר אוֹ תִּינוֹק וּמְטַלְטְלוֹ. וְכֵן אִם נָפְלָה דְּלֵקָה בְּחָצֵר שֶׁיֵּשׁ בָּהּ מֵת מַנִּיחַ עָלָיו כִּכָּר אוֹ תִּינוֹק וּמְטַלְטְלוֹ. וְאִם אֵין שָׁם כִּכָּר וְלֹא תִּינוֹק מַצִּילִין אוֹתוֹ מִן הַדְּלֵקָה מִכָּל מָקוֹם שֶׁמָּא יָבֹא לְכַבּוֹת מִפְּנֵי שֶׁהוּא בָּהוּל עַל מֵתוֹ שֶׁלֹּא יִשָּׂרֵף. וְלֹא הִתִּירוּ לְטַלְטֵל בְּכִכָּר אוֹ תִּינוֹק אֶלָּא לְמֵת בִּלְבַד מִפְּנֵי שֶׁאָדָם בָּהוּל עַל מֵתוֹ:","הָיָה מֻטָּל בַּחַמָּה וְאֵין לָהֶם מָקוֹם לְטַלְטְלוֹ אוֹ שֶׁלֹּא רָצוּ לַהֲזִיזוֹ מִמְּקוֹמוֹ בָּאִין שְׁנֵי בְּנֵי אָדָם וְיוֹשְׁבִים מִשְּׁנֵי צְדָדָיו. חַם לָהֶם מִלְּמַטָּה זֶה מֵבִיא מִטָּתוֹ וְיוֹשֵׁב עָלֶיהָ וְזֶה מֵבִיא מִטָּתוֹ וְיוֹשֵׁב עָלֶיהָ. חַם לָהֶם מִלְּמַעְלָה זֶה מֵבִיא מַחְצֶלֶת וּפוֹרֵשׁ עַל גַּבָּיו. וְזֶה מֵבִיא מַחְצֶלֶת וּפוֹרֵשׁ עַל גַּבָּיו. זֶה זוֹקֵף מִטָּתוֹ וְנִשְׁמָט וְהוֹלֵךְ לוֹ וְזֶה זוֹקֵף מִטָּתוֹ וְנִשְׁמָט וְהוֹלֵךְ לוֹ וְנִמְצָא מְחִצָּה עֲשׂוּיָה מֵאֵלֶיהָ. שֶׁהֲרֵי מַחְצֶלֶת זֶה וּמַחְצֶלֶת זֶה גַּגֵּיהֶן סְמוּכוֹת זוֹ לָזוֹ וּשְׁנֵי קְצוֹתֵיהֶם עַל הַקַּרְקַע מִשְׁנִי צִדֵּי הַמֵּת:","מֵת שֶׁהִסְרִיחַ בְּבַיִת וְנִמְצָא מִתְבַּזֶּה בֵּין הַחַיִּים וְהֵם מִתְבַּזִּים מִמֶּנּוּ מֻתָּר לְהוֹצִיאוֹ לְכַרְמְלִית. גָּדוֹל כְּבוֹד הַבְּרִיּוֹת שֶׁדּוֹחֶה אֶת לֹא תַּעֲשֶׂה שֶׁבַּתּוֹרָה שֶׁהוּא (דברים יז יא) \"לֹא תָסוּר מִן הַדָּבָר אֲשֶׁר יַגִּידוּ לְךָ יָמִין וּשְׂמֹאל\". וְאִם הָיָה לָהֶן מָקוֹם אַחֵר לָצֵאת בּוֹ אֵין מוֹצִיאִין אוֹתוֹ אֶלָּא מְנִיחִין אוֹתוֹ בִּמְקוֹמוֹ וְיוֹצְאִין הֵם:"],"Mishneh Torah, Sabbatical Year and the Jubilee 1":["מִצְוַת עֲשֵׂה לִשְׁבֹּת מֵעֲבוֹדַת הָאָרֶץ וַעֲבוֹדַת הָאִילָן בְּשָׁנָה שְׁבִיעִית שֶׁנֶּאֱמַר (ויקרא כה ב) \"וְשָׁבְתָה הָאָרֶץ שַׁבָּת לַה'\" וְנֶאֱמַר (שמות לד כא) \"בֶּחָרִישׁ וּבַקָּצִיר תִּשְׁבֹּת\". וְכָל הָעוֹשֶׂה מְלָאכָה מֵעֲבוֹדַת הָאָרֶץ אוֹ הָאִילָנוֹת בְּשָׁנָה זוֹ בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא כה ד) \"שָׂדְךָ לֹא תִזְרָע וְכַרְמְךָ לֹא תִזְמֹר\":","אֵינוֹ לוֹקֶה מִן הַתּוֹרָה אֶלָּא עַל הַזְּרִיעָה אוֹ עַל הַזְּמִירָה וְעַל הַקְּצִירָה אוֹ עַל הַבְּצִירָה. וְאֶחָד הַכֶּרֶם וְאֶחָד שְׁאָר הָאִילָנוֹת:","וּזְמִירָה בִּכְלַל זְרִיעָה וּבְצִירָה בִּכְלַל קְצִירָה. וְלָמָּה פֵּרְטָן הַכָּתוּב לוֹמַר לְךָ עַל שְׁתֵּי תּוֹלָדוֹת אֵלּוּ בִּלְבַד הוּא חַיָּב וְעַל שְׁאָר הַתּוֹלָדוֹת שֶׁבַּעֲבוֹדַת הָאָרֶץ עִם שְׁאָר הָאָבוֹת שֶׁלֹּא נִתְפָּרְשׁוּ בְּעִנְיָן זֶה אֵינוֹ לוֹקֶה עֲלֵיהֶן. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","כֵּיצַד. הַחוֹפֵר אוֹ הַחוֹרֵשׁ לְצֹרֶךְ הַקַּרְקַע אוֹ הַמְסַקֵּל אוֹ הַמְזַבֵּל וְכַיּוֹצֵא בָּהֶן מִשְּׁאָר עֲבוֹדַת הָאָרֶץ. וְכֵן הַמַּבְרִיךְ אוֹ הַמַּרְכִּיב אוֹ הַנּוֹטֵעַ וְכַיּוֹצֵא בָּהֶן מֵעֲבוֹדַת הָאִילָנוֹת. מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶן:","אֵין נוֹטְעִין בַּשְּׁבִיעִית אֲפִלּוּ אִילַן סְרָק. וְלֹא יַחְתֹּךְ הַיִּבּוֹלֶת מִן הָאִילָנוֹת. וְלֹא יְפָרֵק הֶעָלִין וְהַבַּדִּים הַיְבֵשִׁים. וְלֹא יְאַבֵּק אֶת צַמַּרְתּוֹ בָּאָבָק. וְלֹא יְעַשֵּׁן תַּחְתָּיו כְּדֵי שֶׁיָּמוּת הַתּוֹלַעַת. וְלֹא יָסוּךְ אֶת הַנְּטִיעוֹת בְּדָבָר שֶׁיֵּשׁ לוֹ זוֹהֲמָא כְּדֵי שֶׁלֹּא יֹאכַל אוֹתוֹ הָעוֹף כְּשֶׁהוּא רַךְ. וְלֹא יָסוּךְ אֶת הַפַּגִּין. וְלֹא יִנְקֹב אוֹתָן. וְלֹא יִכְרֹךְ אֶת הַנְּטִיעוֹת. וְלֹא יִקְטֹם אוֹתָם. וְלֹא יְפַסֵּג אֶת הָאִילָנוֹת. וְכֵן שְׁאָר כָּל עֲבוֹדַת הָאִילָן. וְאִם עָשָׂה אַחַת מֵאֵלּוּ בַּשְּׁבִיעִית מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אֵין מְצִיתִין אֶת הָאוּר בְּאִישַׁת הַקָּנִים מִפְּנֵי שֶׁהִיא עֲבוֹדַת קַרְקַע. וְאֵין מְלַמְּדִין אֶת הַפָּרָה לַחְרשׁ אֶלָּא בְּחוֹל. וְאֵין בּוֹדְקִין אֶת הַזְּרָעִים בְּעָצִיץ מָלֵא עָפָר אֲבָל בּוֹדְקִין אוֹתָן בְּעָצִיץ מָלֵא גְּלָלִים. וְשׁוֹרִין אֶת הַזְּרָעִים בַּשְּׁבִיעִית כְּדֵי לְזָרְעָן בְּמוֹצָאֵי שְׁבִיעִית. וּמְקַיְּמִין הָאִלוּיֵי בְּרֹאשׁ הַגַּג אֲבָל אֵין מַשְׁקִין אוֹתוֹ:","סוֹקְרִין אֶת הָאִילָן בְּסִקְרָא. וְטוֹעֲנִין אוֹתוֹ בַּאֲבָנִים וְעוֹדְרִין תַּחַת הַגְּפָנִים. וְהַמְקַשְׁקֵשׁ בְּזֵיתִים אִם לְהַבְרוֹת אֶת הָאִילָן אָסוּר וְאִם לִסְתֹּם אֶת הַפְּצִימִים מֻתָּר:","מַשְׁקִין בֵּית הַשְּׁלָחִין בַּשְּׁבִיעִית וְהִיא שְׂדֵה הַזְּרִיעָה שֶׁצְּמֵאָה בְּיוֹתֵר. וְכֵן שְׂדֵה הָאִילָנוֹת אִם הָיוּ מְרֻחָקִין זֶה מִזֶּה יֶתֶר מֵעֶשֶׂר לְבֵית סְאָה מוֹשְׁכִין אֶת הַמַּיִם מֵאִילָן לְאִילָן. אֲבָל לֹא יַשְׁקוּ אֶת כָּל הַשָּׂדֶה. וְאִם הָיוּ מְקֹרָבִין זֶה לָזֶה עֶשֶׂר לְבֵית סְאָה מַשְׁקִין כָּל הַשָּׂדֶה בִּשְׁבִילָן. וְכֵן עֲפַר הַלָּבָן מַרְבִּיצִין אוֹתוֹ בְּמַיִם בַּשְּׁבִיעִית בִּשְׁבִיל הָאִילָנוֹת שֶׁלֹּא יִפָּסְדוּ:","וְעוֹשִׂין עוּגִיּוֹת לַגְּפָנִים. וְעוֹשִׂין אֶת אַמַּת הַמַּיִם כַּתְּחִלָּה וּמְמַלְּאִין אֶת הַנְּקָעִים מַיִם:","וּמִפְּנֵי מָה הִתִּירוּ כָּל אֵלֶּה. שֶׁאִם לֹא יַשְׁקֶה תֵּעָשֶׂה הָאָרֶץ מְלֵחָה וְיָמוּת כָּל עֵץ שֶׁבָּהּ. וְהוֹאִיל וְאִסּוּר הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶם מִדִּבְרֵיהֶם לֹא גָּזְרוּ עַל אֵלּוּ שֶׁאֵין אָסוּר מִן הַתּוֹרָה אֶלָּא אוֹתָן שְׁנֵי אָבוֹת וּשְׁתֵּי תּוֹלָדוֹת שֶׁלָּהֶם כְּמוֹ שֶׁבֵּאַרְנוּ:","מִשֶּׁרַבּוּ הָאַנָּסִין וְהִטִּילוּ מַלְכֵי עַכּוּ\"ם עַל יִשְׂרָאֵל לַעֲשׂוֹת מַחֲנוֹת לְחֵילוֹתֵיהֶן הִתִּירוּ לִזְרֹעַ בַּשְּׁבִיעִית דְּבָרִים שֶׁצְּרִיכִין לָהֶם עַבְדֵי הַמֶּלֶךְ בִּלְבַד. וְכֵן מִי שֶׁכְּפָאוֹ אַנָּס לַעֲשׂוֹת בַּשְּׁבִיעִית בְּחִנָּם כְּמוֹ עֲבוֹדַת הַמֶּלֶךְ וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה עוֹשֶׂה:","הַנּוֹטֵעַ בַּשְּׁבִיעִית בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד יַעֲקֹר. מִפְּנֵי שֶׁיִּשְׂרָאֵל חֲשׁוּדִין עַל הַשְּׁבִיעִית. אִם תֹּאמַר בְּשׁוֹגֵג יְקַיֵּם יֹאמַר הַמֵּזִיד שׁוֹגֵג הָיִיתִי:","הַחוֹרֵשׁ אֶת שָׂדֵהוּ אוֹ נָרָהּ אוֹ זִבְּלָהּ בַּשְּׁבִיעִית כְּדֵי שֶׁתִּהְיֶה יָפָה לִזְרִיעָה בְּמוֹצָאֵי שְׁבִיעִית קוֹנְסִין אוֹתוֹ וְלֹא יִזְרָעֶנָּה בְּמוֹצָאֵי שְׁבִיעִית. וְאֵין חוֹכְרִין אוֹתָהּ מִמֶּנּוּ כְּדֵי לְזָרְעָהּ אֶלָּא תְּהִי בּוּרָה לְפָנָיו. וְאִם מֵת יִזְרָעֶנָּה בְּנוֹ:","הַמַּעֲבִיר קוֹצִים מֵאַרְצוֹ בַּשְּׁבִיעִית כְּדֵי לְתַקְּנָהּ לְמוֹצָאֵי שְׁבִיעִית. אוֹ שֶׁסִּקֵּל מִמֶּנָּה אֲבָנִים אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי לֹא קָנְסוּ אוֹתוֹ וּמֻתָּר לוֹ לְזָרְעָהּ בְּמוֹצָאֵי שְׁבִיעִית:","הַטּוֹמֵן לֶפֶת וּצְנוֹנוֹת וְכַיּוֹצֵא בָּהֶן בַּשְּׁבִיעִית אִם הָיוּ מִקְצָת הֶעָלִין מְגֻלִּין אֵינוֹ חוֹשֵׁשׁ וְאִם לָאו אָסוּר. הַטּוֹמֵן אֶת הַלּוּף וְכַיּוֹצֵא בָּהֶן לֹא יִפְחֹת מֵאַרְבַּע קַבִּים עַל גֹּבַהּ טֶפַח וְטֶפַח עָפָר עַל גַּבָּיו. וְטוֹמְנוֹ בִּמְקוֹם דְּרִיסַת הָאָדָם כְּדֵי שֶׁלֹּא יִצְמַח. וּמֻתָּר לְמָרֵס בְּאֹרֶז בַּשְּׁבִיעִית אֲבָל לֹא יְכַסֵּחַ:","בָּרִאשׁוֹנָה הָיוּ אוֹמְרִים מְלַקֵּט אָדָם עֵצִים וַאֲבָנִים וַעֲשָׂבִים מִתּוֹךְ שָׂדֵהוּ. וְהוּא שֶׁיִּטּל הַגַּס הַגַּס כְּדֵי שֶׁלֹּא יִתְכַּוֵּן לְנַקּוֹת הָאָרֶץ. אֲבָל מִשְּׂדֵה חֲבֵרוֹ נוֹטֵל בֵּין דַּק בֵּין גַּס. מִשֶּׁרַבּוּ עוֹבְרֵי עֲבֵרָה שֶׁמִּתְכַּוְּנִין לְנַקּוֹת וְאוֹמְרִין הַגַּס הַגַּס אָנוּ נוֹטְלִין. אָסְרוּ לִטּל אָדָם מִשָּׂדֵהוּ אֶלָּא מִתּוֹךְ שְׂדֵה חֲבֵרוֹ וְהוּא שֶׁלֹּא יְלַקֵּט בְּטוֹבָה. שֶׁלֹּא יֹאמַר לוֹ רְאֵה כַּמָּה טוֹב עָשִׂיתִי לְךָ שֶׁהֲרֵי נִקֵּיתִי שָׂדְךָ:","הָיְתָה בְּהֶמְתּוֹ עוֹמֶדֶת בְּתוֹךְ שָׂדֵהוּ מְלַקֵּט וּמֵבִיא לְפָנֶיהָ. שֶׁבְּהֶמְתּוֹ מוֹכַחַת עָלָיו. וְכֵן אִם הָיְתָה שָׁם כִּירָתוֹ מְלַקֵּט הַכּל וּמַדְלִיק. שֶׁכִּירָתוֹ מוֹכַחַת עָלָיו:","הַקּוֹצֵץ אִילָן אוֹ שְׁנַיִם לְעֵצִים הֲרֵי זֶה מֻתָּר לְשַׁרְשָׁן. קָצַץ שְׁלֹשָׁה אוֹ יֶתֶר זֶה בְּצַד זֶה לֹא יְשָׁרֵשׁ. שֶׁהֲרֵי מְתַקֵּן אֶת הָאָרֶץ. אֶלָּא קוֹצֵץ מֵעַל הָאָרֶץ וּמַנִּיחַ שָׁרָשָׁיו בָּאָרֶץ. בַּמֶּה דְּבָרִים אֲמוּרִים מִתּוֹךְ שֶׁלּוֹ. אֲבָל מִשְּׂדֵה חֲבֵרוֹ מֻתָּר לְשָׁרֵשׁ:","הַמַּבְקִיעַ בְּזַיִת לִטּל עֵצִים לֹא יְחַפֶּה מְקוֹם הַבִּקּוּעַ בְּעָפָר מִפְּנֵי שֶׁהִיא עֲבוֹדָה אֲבָל מְכַסֶּה בַּאֲבָנִים אוֹ בְּקַשׁ:","הַמְזַנֵּב בַּגְּפָנִים וְהַקּוֹצֵץ קָנִים הֲרֵי זֶה קוֹצֵץ כְּדַרְכּוֹ בְּקַרְדֹּם וּבְמַגָּל וּבִמְגֵרָה וּבְכָל מַה שֶּׁיִּרְצֶה:","אֵין קוֹצְצִין בְּתוּלַת שִׁקְמָה בַּשְּׁבִיעִית כְּדֶרֶךְ שֶׁקּוֹצְצִין בִּשְׁאָר הַשָּׁנִים מִפְּנֵי שֶׁקְּצִיצָתָהּ עֲבוֹדַת אִילָן. שֶׁבִּקְצִיצָה זוֹ תִּגְדַּל וְתוֹסִיף. וְאִם צָרִיךְ לְעֵצֶיהָ קוֹצֵץ אוֹתָהּ שֶׁלֹּא כְּדֶרֶךְ עֲבוֹדָתָהּ:","כֵּיצַד קוֹצְצָהּ. מֵעִם הָאָרֶץ אוֹ לְמַעְלָה מֵעֲשָׂרָה טְפָחִים. אִילָן שֶׁנִּפְשַׁח קוֹשְׁרִין אוֹתוֹ בַּשְּׁבִיעִית. לֹא שֶׁיַּעֲלֶה אֶלָּא שֶׁלֹּא יוֹסִיף:"],"Mishneh Torah, Sabbatical Year and the Jubilee 9":["מִצְוַת עֲשֵׂה לְהַשְׁמִיט הַמַּלְוֶה בַּשְּׁבִיעִית שֶׁנֶּאֱמַר (דברים טו ב) \"שָׁמוֹט כָּל בַּעַל מַשֵּׁה יָדוֹ\". וְהַתּוֹבֵעַ חוֹב שֶׁעָבְרָה עָלָיו שְׁבִיעִית עָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים טו ב) \"לֹא יִגּשֹׁ אֶת רֵעֵהוּ וְאֶת אָחִיו\":","אֵין שְׁמִטַּת כְּסָפִים נוֹהֶגֶת מִן הַתּוֹרָה אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג שֶׁיֵּשׁ שָׁם שְׁמִטַּת קַרְקַע. שֶׁהֲרֵי יָשׁוּב הַקַּרְקַע לִבְעָלָיו בְּלֹא כֶּסֶף. וְדָבָר זֶה קַבָּלָה הוּא. אָמְרוּ חֲכָמִים בִּזְמַן שֶׁאַתָּה מְשַׁמֵּט קַרְקַע אַתָּה מְשַׁמֵּט כְּסָפִים בְּכָל מָקוֹם בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּבִזְמַן שֶׁאֵין שָׁם שְׁמִטַּת קַרְקַע אֵין אַתָּה מְשַׁמֵּט כְּסָפִים בִּשְׁבִיעִית אֲפִלּוּ בָּאָרֶץ:","וּמִדִּבְרֵי סוֹפְרִים שֶׁתְּהֵא שְׁמִטַּת כְּסָפִים נוֹהֶגֶת בַּזְּמַן הַזֶּה בְּכָל מָקוֹם וְאַף עַל פִּי שֶׁאֵין הַיּוֹבֵל נוֹהֵג כְּדֵי שֶׁלֹּא תִּשְׁתַּכֵּחַ תּוֹרַת שְׁמִטַּת הַכְּסָפִים מִיִּשְׂרָאֵל:","אֵין שְׁבִיעִית מְשַׁמֶּטֶת כְּסָפִים אֶלָּא בְּסוֹפָהּ שֶׁנֶּאֱמַר (דברים טו א) \"מִקֵּץ שֶׁבַע שָׁנִים תַּעֲשֶׂה\" שְׁמִטָּה וְזֶה דְּבַר הַשְּׁמִטָּה וְשָׁם הוּא אוֹמֵר (דברים לא י) \"מִקֵּץ שֶׁבַע שָׁנִים בְּמֹעֵד שְׁנַת הַשְּׁמִטָּה בְּחַג הַסֻּכּוֹת\". מָה שָׁם אַחַר שֶׁבַע אַף הַשְׁמָטַת כְּסָפִים אַחַר שֶׁבַע. לְפִיכָךְ הִלְוָה אֶת חֲבֵרוֹ בַּשְּׁבִיעִית עַצְמָהּ גּוֹבֶה חוֹבוֹ כָּל הַשָּׁנָה. וּכְשֶׁתִּשְׁקַע חַמָּה בְּלֵילֵי רֹאשׁ הַשָּׁנָה שֶׁל מוֹצָאֵי שְׁבִיעִית אָבַד הַחוֹב:","שָׁחַט אֶת הַפָּרָה וְחִלְּקָהּ עַל דַּעַת שֶׁהַיּוֹם רֹאשׁ הַשָּׁנָה שֶׁל מוֹצָאֵי שְׁבִיעִית וְנִתְעַבֵּר אֱלוּל וְנִמְצָא אוֹתוֹ הַיּוֹם סוֹף שְׁבִיעִית אָבְדוּ הַדָּמִים. שֶׁהֲרֵי עָבְרָה שְׁבִיעִית עַל הַחוֹב:","שְׁבִיעִית מְשַׁמֶּטֶת אֶת הַמִּלְוֶה וַאֲפִלּוּ מִלְוֶה שֶׁבִּשְׁטָר שֶׁיֵּשׁ בּוֹ אַחֲרָיוּת נְכָסִים הֲרֵי זֶה מְשַׁמֵּט. וְאִם סִיֵּם לוֹ שָׂדֶה בְּהַלְוָאָתוֹ אֵינוֹ מַשְׁמִיט. וְהַשְּׁבִיעִית מְשַׁמֶּטֶת אֶת הַשְּׁבוּעָה שֶׁנֶּאֱמַר (דברים טו ב) \"לֹא יִגּשֹׁ\" מִכָּל מָקוֹם לֹא לְשַׁלֵּם וְלֹא לְהִשָּׁבַע:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁבוּעַת הַדַּיָּנִין וְכָל כַּיּוֹצֵא בָּהּ מִדְּבָרִים שֶׁאִם יוֹדֶה בָּהֶן שְׁבִיעִית מְשַׁמַּטְתָן. אֲבָל שְׁבוּעַת הַשּׁוֹמְרִין וְהַשֻּׁתָּפִין וְכַיּוֹצֵא בָּהֶן מִשָּׁבוּעוֹת שֶׁאִם יוֹדֶה יְשַׁלֵּם הֲרֵי זֶה יִשָּׁבַע אַחַר הַשְּׁמִטָּה:","הִלְוָהוּ וּתְבָעוֹ וְכָפַר בּוֹ. וְהִגִּיעַ הַשְּׁמִטָּה וְהוּא בִּכְפִירָתוֹ. וְהוֹדָה אַחַר שֶׁעָבְרָה שְׁבִיעִית. אוֹ שֶׁבָּאוּ עָלָיו עֵדִים אַחַר הַשְּׁבִיעִית אֵין הַשְּׁבִיעִית מְשַׁמֶּטֶת:","הַמַּלְוֶה אֶת חֲבֵרוֹ וְקָבַע לוֹ זְמַן לְעֶשֶׂר שָׁנִים אֵינוֹ מְשַׁמֵּט. אַף עַל פִּי שֶׁהוּא בָּא לִידֵי (דברים טו ב) \"לֹא יִגּשֹׁ\" הֲרֵי הוּא עַתָּה אֵינוֹ יָכוֹל לִנְגּשֹׁ. הִתְנָה עִמּוֹ שֶׁלֹּא יִתְבָּעֶנּוּ שְׁבִיעִית מְשַׁמֶּטֶת:","הַמַּלְוֶה אֶת חֲבֵרוֹ וְהִתְנָה עִמּוֹ שֶׁלֹּא תְּשַׁמְּטֶנּוּ שְׁבִיעִית הֲרֵי זֶה נִשְׁמָט שֶׁאֵינוֹ יָכוֹל לְבַטֵּל דִּין הַשְּׁבִיעִית. הִתְנָה עִמּוֹ שֶׁלֹּא יְשַׁמֵּט הוּא חוֹב זֶה וַאֲפִלּוּ בַּשְּׁבִיעִית תְּנָאוֹ קַיָּם. שֶׁכָּל תְּנַאי שֶׁבְּמָמוֹן קַיָּם. וְנִמְצָא זֶה חִיֵּב עַצְמוֹ בְּמָמוֹן שֶׁלֹּא חִיְּבַתּוּ תּוֹרָה שֶׁהוּא חַיָּב:","הַקָּפַת הַחֲנוּת אֵינָהּ נִשְׁמֶטֶת. וְאִם עֲשָׂאָהּ מִלְוֶה נִשְׁמֶטֶת. שְׂכַר שָׂכִיר אֵינוֹ נִשְׁמָט. וְאִם זְקָפוֹ עָלָיו בְּמִלְוֶה נִשְׁמָט:","קְנָסוֹת שֶׁל אוֹנֵס וְשֶׁל מְפַתֶּה וְהַמּוֹצִיא שֵׁם רַע אֵינָם נִשְׁמָטִין. וְאִם זְקָפָן בְּמִלְוֶה נִשְׁמָטִים. וּמֵאֵימָתַי נִזְקָפִין בְּמִלְוֶה מִשְּׁעַת הַעֲמָדָה בַּדִּין:","הַמְגָרֵשׁ אֶת אִשְׁתּוֹ קֹדֶם הַשְּׁמִטָּה אֵין כְּתֻבָּתָהּ נִשְׁמֶטֶת. וְאִם פְּגַמְתָּהּ אוֹ זְקַפְתָּהּ עָלָיו בְּמִלְוֶה נִשְׁמֶטֶת:","הַמַּלְוֶה עַל הַמַּשְׁכּוֹן אֵינוֹ מַשְׁמִיט. וְהוּא שֶׁיִּהְיֶה הַחוֹב כְּנֶגֶד הַמַּשְׁכּוֹן. וְאִם הָיָה יֶתֶר מַשְׁמִיט הַיֶּתֶר:","הַמּוֹסֵר שִׁטְרוֹתָיו לְבֵית דִּין וְאָמַר לָהֶם אַתֶּם גְּבוּ לִי חוֹבִי זֶה אֵינוֹ נִשְׁמָט שֶׁנֶּאֱמַר (דברים טו ג) \"וַאֲשֶׁר יִהְיֶה לְךָ אֶת אָחִיךָ\" וְזֶה בֵּית דִּין תּוֹבְעִין אוֹתוֹ. וְכֵן בֵּית דִּין שֶׁחָתְכוּ אֶת הַדִּין וְכָתְבוּ אִישׁ פְּלוֹנִי אַתָּה חַיָּב לִתֵּן לָזֶה כָּךְ וְכָךְ אֵינוֹ נִשְׁמָט. שֶׁזֶּה כְּגָבוּי הוּא וּכְאִלּוּ בָּא לְיָדוֹ וְאֵינוֹ כְּמִלְוֶה:","כְּשֶׁרָאָה הִלֵּל הַזָּקֵן שֶׁנִּמְנְעוּ מִלְּהַלְווֹת זֶה אֶת זֶה וְעוֹבְרִין עַל הַכָּתוּב בַּתּוֹרָה (דברים טו ט) \"הִשָּׁמֶר לְךָ פֶּן יִהְיֶה דָבָר\" וְגוֹ' הִתְקִין פְּרוֹזְבּוּל כְּדֵי שֶׁלֹּא יִשָּׁמֵט הַחוֹב עַד שֶׁיַּלְווּ זֶה אֶת זֶה. וְאֵין הַפְּרוֹזְבּוּל מוֹעִיל אֶלָּא בִּשְׁמִטַּת כְּסָפִים בַּזְּמַן הַזֶּה שֶׁהִיא מִדִּבְרֵי סוֹפְרִים. אֲבָל שְׁמִטָּה שֶׁל תּוֹרָה אֵין הַפְּרוֹזְבּוֹל מוֹעִיל בָּהּ:","אֵין כּוֹתְבִין פְּרוֹזְבּוּל אֶלָּא חֲכָמִים גְּדוֹלִים בְּיוֹתֵר כְּבֵית דִּינוֹ שֶׁל רַבִּי אַמִּי וְרַבִּי אַסִּי שֶׁהֵן רְאוּיִין לְהַפְקִיעַ מָמוֹן בְּנֵי אָדָם. אֲבָל שְׁאָר בָּתֵּי דִּינִין אֵין כּוֹתְבִין:","זֶהוּ גּוּפוֹ שֶׁל פְּרוֹזְבּוּל. מוֹסְרַנִי לָכֶם פְּלוֹנִי וּפְלוֹנִי הַדַּיָּנִין שֶׁבְּמָקוֹם פְּלוֹנִי שֶׁכָּל חוֹב שֶׁיֵּשׁ לִי שֶׁאֶגְבֶּנּוּ כָּל זְמַן שֶׁאֶרְצֶה. וְהַדַּיָּנִין אוֹ הָעֵדִים חוֹתְמִין מִלְּמַטָּה:","אֵין כּוֹתְבִין פְּרוֹזְבּוּל אֶלָּא עַל הַקַּרְקַע. אִם אֵין קַרְקַע לַלּוֹוֶה מוֹכֵר לוֹ הַמַּלְוֶה כָּל שֶׁהוּא בְּתוֹךְ שָׂדֵהוּ אֲפִלּוּ קֶלַח שֶׁל כְּרוּב. הִשְׁאִילוֹ מָקוֹם לְתַנּוּר אוֹ לְכִירָה כּוֹתְבִין עָלָיו פְּרוֹזְבּוּל. הָיְתָה לוֹ שָׂדֶה מְמֻשְׁכֶּנֶת כּוֹתְבִין עָלֶיהָ פְּרוֹזְבּוּל:","כּוֹתְבִין לְאִישׁ עַל נִכְסֵי אִשְׁתּוֹ וְלִיתוֹמִים עַל נִכְסֵי אַפַּטְרוֹפּוּס. אֵין לוֹ קַרְקַע וְלָעָרֵב יֵשׁ לוֹ קַרְקַע כּוֹתְבִין עָלֶיהָ פְּרוֹזְבּוּל. הָיָה לוֹ חוֹב עַל חֲבֵרוֹ וְיֵשׁ לַחֲבֵרוֹ קַרְקַע הוֹאִיל וְהוּא תַּחַת שִׁעְבּוּדוֹ כּוֹתֵב עָלָיו פְּרוֹזְבּוּל:","אֶחָד שֶׁלָּוָה מֵחֲמִשָּׁה צְרִיכִים פְּרוֹזְבּוּל לְכָל אֶחָד וְאֶחָד. וַחֲמִשָּׁה שֶׁלָּווּ מֵאֶחָד דַּיּוֹ פְּרוֹזְבּוּל אֶחָד לְכֻלָּן:","כָּתַב הַפְּרוֹזְבּוּל תְּחִלָּה וְאַחַר כָּךְ הִלְוָה אֵינוֹ מוֹעִיל. אֶלָּא מַשְׁמִיט עַד שֶׁיִּכְתֹּב הַפְּרוֹזְבּוּל אַחַר שֶׁהִלְוָה. נִמְצֵאתָ אוֹמֵר שֶׁכָּל מִלְוֶה הַקּוֹדֶמֶת לִפְרוֹזְבּוּל אֵינָהּ נִשְׁמֶטֶת בִּפְרוֹזְבּוּל זֶה. וְאִם הַפְּרוֹזְבּוּל קוֹדֵם לַמִּלְוֶה נִשְׁמֶטֶת בִּפְרוֹזְבּוּל זֶה:","לְפִיכָךְ פְּרוֹזְבּוּל הַמֻּקְדָּם כָּשֵׁר. וְהַמְאֻחָר פָּסוּל. כֵּיצַד. כְּתָבוֹ בְּנִיסָן וְהִקְדִּים זְמַנּוֹ מֵאֲדָר כָּשֵׁר. שֶׁהֲרֵי הוּרַע כֹּחוֹ שֶׁאֵינוֹ מַשְׁמִיט אֶלָּא עַד אֲדָר. אֲבָל אִם אִחֵר זְמַנּוֹ וּכְתָבוֹ מֵאִיָּר פָּסוּל שֶׁהֲרֵי מְיַפֶּה כֹּחוֹ שֶׁאֵינוֹ מַשְׁמִיט עַד אִיָּר שֶׁלֹּא כַּדִּין. שֶׁאֵין דִּינוֹ שֶׁלֹּא יַשְׁמִיט אֶלָּא עַד נִיסָן בִּשְׁעַת מְסִירַת הַדְּבָרִים לְבֵית דִּין:","הַמּוֹצִיא שְׁטַר חוֹב אַחַר שְׁבִיעִית וְאֵין עִמּוֹ פְּרוֹזְבּוּל אָבַד חוֹבוֹ. וְאִם אָמַר הָיָה לִי וְאָבַד נֶאֱמָן. שֶׁמִּזְּמַן הַסַּכָּנָה וְאֵילָךְ בַּעַל חוֹב גּוֹבֶה שֶׁלֹּא בִּפְרוֹזְבּוּל. וְלֹא עוֹד אֶלָּא כְּשֶׁיָּבִיא בַּעַל חוֹב אֶת שְׁטָרוֹ אוֹ כְּשֶׁיָּבוֹא לִתְבֹּעַ בְּמִלְוֶה עַל פֶּה אוֹמְרִים לַנִּתְבָּע שַׁלֵּם לוֹ. וְאִם טָעַן הַנִּתְבָּע וְאָמַר אַיֵּה פְּרוֹזְבּוּל שֶׁלּוֹ. אוֹמְרִים לַתּוֹבֵעַ הָיָה לְךָ פְּרוֹזְבּוּל וְאָבַד אִם אָמַר הֵן נֶאֱמָן. וְאִם הוֹדָה שֶׁלֹּא כָּתַב פְּרוֹזְבּוּל אָבַד חוֹבוֹ. וְהַיְתוֹמִים אֵינָן צְרִיכִין פְּרוֹזְבּוּל:","הוֹצִיא פְּרוֹזְבּוּל וְטָעַן הַנִּתְבָּע וְאָמַר מִלְוֶה זוֹ שֶׁהוּא תּוֹבֵעַ אַחַר פְּרוֹזְבּוּל זֶה הָיְתָה וְהַתּוֹבֵעַ אוֹמֵר קֹדֶם פְּרוֹזְבּוּל הָיְתָה הַתּוֹבֵעַ נֶאֱמָן. שֶׁאִלּוּ אָמַר הָיָה לִי וְאָבַד נֶאֱמָן וְאַף עַל פִּי שֶׁאֵין אָנוּ יוֹדְעִין זְמַן הַפְּרוֹזְבּוּל שֶׁאָבַד:","טָעַן הַנִּתְבָּע וְאָמַר מִלְוֶה יֵשׁ לוֹ אֶצְלִי. וְהַתּוֹבֵעַ אוֹמֵר לֹא כִּי אֶלָּא הַקָּפַת חֲנוּת הִיא שֶׁאֵינָהּ נִשְׁמֶטֶת שֶׁהֲרֵי לֹא זָקַפְתִּי מִלְוֶה הֲרֵי זֶה נֶאֱמָן. שֶׁהֲרֵי אִם יִרְצֶה יֹאמַר מִלְוֶה הָיְתָה וּפְרוֹזְבּוּל הָיָה לִי וְאָבַד. שֶׁכֵּיוָן שֶׁתִּקְּנוּ חֲכָמִים פְּרוֹזְבּוּל חֲזָקָה הִיא שֶׁאֵין אָדָם מַנִּיחַ דָּבָר מֻתָּר וְאוֹכֵל דָּבָר אָסוּר:","תַּלְמִידֵי חֲכָמִים שֶׁהִלְווּ זֶה אֶת זֶה וּמָסַר דְּבָרָיו לְתַלְמִידִים וְאָמַר מוֹסְרַנִי לָכֶם שֶׁכָּל חוֹב שֶׁיֵּשׁ לִי שֶׁאֶגְבֶּנּוּ כָּל זְמַן שֶׁאֶרְצֶה אֵינוֹ צָרִיךְ לִכְתֹּב פְּרוֹזְבּוּל. מִפְּנֵי שֶׁהֵן יוֹדְעִים שֶׁהַשְׁמָטַת כְּסָפִים בַּזְּמַן הַזֶּה מִדִּבְרֵיהֶם וּבִדְבָרִים בִּלְבַד הִיא נִדְחֵית:","כָּל הַמַּחֲזִיר חוֹב שֶׁעָבְרָה עָלָיו שְׁבִיעִית רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. וְצָרִיךְ הַמַּלְוֶה לוֹמַר לַמַּחֲזִיר מַשְׁמִיט אֲנִי וּכְבָר נִפְטַרְתָּ מִמֶּנִּי. אָמַר לוֹ אַף עַל פִּי כֵן רְצוֹנִי שֶׁתְּקַבֵּל יְקַבֵּל מִמֶּנּוּ שֶׁנֶּאֱמַר (דברים טו ב) \"לֹא יִגּשֹׁ\" וַהֲרֵי לֹא נָגַשׂ. וְאַל יֹאמַר לוֹ בְּחוֹבִי אֲנִי נוֹתֵן לְךָ אֶלָּא יֹאמַר לוֹ שֶׁלִּי הֵם וּבְמַתָּנָה אֲנִי נוֹתֵן לְךָ:","הֶחֱזִיר לוֹ חוֹבוֹ וְלֹא אָמַר לוֹ כֵּן. מְסַבֵּב עִמּוֹ בִּדְבָרִים עַד שֶׁיֹּאמַר לוֹ שֶׁלִּי הֵם וּבְמַתָּנָה נְתַתִּים לְךָ. וְאִם לֹא אָמַר לֹא יְקַבֵּל מִמֶּנּוּ אֶלָּא יִטּל מְעוֹתָיו וְיֵלֵךְ לוֹ:","מִי שֶׁנִּמְנָע מִלְּהַלְווֹת אֶת חֲבֵרוֹ קֹדֶם הַשְּׁמִטָּה שֶׁמָּא יִתְאַחֵר הַחוֹב שֶׁלּוֹ וְיִשָּׁמֵט עָבַר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר הִשָּׁמֶר לְךָ וְגוֹ'. וְחֵטְא גָּדוֹל הוּא שֶׁהֲרֵי הִזְהִירָה עָלָיו תּוֹרָה בִּשְׁנֵי לָאוִין שֶׁנֶּאֱמַר (דברים טו ט) \"הִשָּׁמֶר לְךָ פֶּן\" וְגוֹ'. וְכָל מָקוֹם שֶׁנֶּאֱמַר הִשָּׁמֶר אוֹ פֶּן אוֹ אַל הֲרֵי זֶה מִצְוַת לֹא תַּעֲשֶׂה. וְהַתּוֹרָה הִקְפִּידָה עַל מַחֲשָׁבָה רָעָה זוֹ וּקְרָאַתּוּ (דברים טו ט) \"בְּלִיַּעַל\". וַהֲרֵי הוֹסִיף הַכָּתוּב לְהַזְהִיר וּלְצַוּוֹת שֶׁלֹּא יִמָּנַע אֶלָּא יִתֵּן שֶׁנֶּאֱמַר (דברים טו י) \"נָתוֹן תִּתֵּן לוֹ וְלֹא יֵרַע לְבָבְךָ בְּתִתְּךָ לוֹ\" וְגוֹ'. וְהִבְטִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׂכַר מִצְוָה זוֹ בָּעוֹלָם הַזֶּה שֶׁנֶּאֱמַר (דברים טו י) \"כִּי בִּגְלַל הַדָּבָר הַזֶּה יְבָרֶכְךָ\" וְגוֹ':"],"Mishneh Torah, Sacrifices Rendered Unfit 2":["כָּל הַדָּמִים הַנִּתָּנִין עַל מִזְבֵּחַ הַחִיצוֹן. אִם נָתַן מַתָּנָה אַחַת בִּלְבַד כִּפֵּר. וַאֲפִלּוּ בְּחַטָּאת מַתָּנָה אַחַת הִיא הָעִקָּר וּשְׁאָר הָאַרְבַּע מַתָּנוֹת לְמִצְוָה. שֶׁנֶּאֱמַר (דברים יב כז) \"וְדַם זְבָחֶיךָ יִשָּׁפֵךְ עַל מִזְבַּח ה' אֱלֹהֶיךָ\". שְׁפִיכַת הַדָּם עַל הַמִּזְבֵּחַ הִיא הָעִקָּר:","וְכָל הַנִּתָּנִין בִּזְרִיקָה שֶׁנְּתָנָן בִּשְׁפִיכָה יָצָא. שֶׁנֶּאֱמַר (דברים יב כז) \"וְדַם זְבָחֶיךָ יִשָּׁפֵךְ\":","כָּל הַדָּמִים הַנִּתָּנִין עַל מִזְבֵּחַ הַפְּנִימִי. אִם חִסֵּר אַחַת מֵהֶן לֹא כִּפֵּר. אֶלָּא כֻּלָּן הֵן עִקַּר הַכַּפָּרָה. שֶׁהֲרֵי הַכָּתוּב הִקְפִּיד עַל מִנְיָנָן שֶׁנֶּאֱמַר (ויקרא ד ו) (ויקרא ד יז) \"שֶׁבַע פְּעָמִים\":","חַטָּאת שֶׁנָּתַן מִמֶּנּוּ מַתָּנָה אַחַת וּמֵתוּ הַבְּעָלִים. יַשְׁלִים אַרְבַּע מַתָּנוֹת לְאַחַר הַמִּיתָה:","אֲבָל אִם נָתַן הָאַחַת בַּיּוֹם לֹא יִתֵּן הַשָּׁלֹשׁ בַּלַּיְלָה:","וְאִם נָתַן אַחַת בִּפְנִים וְהִשְׁלִימָן בַּחוּץ חַיָּב מִשּׁוּם מַעֲלֶה בַּחוּץ:","הָיָה מַזֶּה וְנִקְטְעָה יָדוֹ שֶׁל מַזֶּה קֹדֶם שֶׁיַּגִּיעַ דָּם לַאֲוִיר הַמִּזְבֵּחַ. לֹא עָלְתָה לוֹ הַזָּיָה:","שִׁנָּה מַתַּן קָרְבָּנוֹת בְּחַטָּאת. בֵּין בְּחַטָּאת הַנַּעֲשֵׂית בִּפְנִים בֵּין בְּחַטָּאת הַנַּעֲשֵׂית בַּחוּץ נִפְסַל. אֲבָל בִּשְׁאָר קָדָשִׁים כְּשֵׁרִין:","נָתַן הַדָּם מִן הַקֶּרֶן וְלִפְנִים. בֵּין בְּחַטָּאת בֵּין בִּשְׁאָר קָדָשִׁים. בֵּין בַּמִּזְבֵּחַ הַפְּנִימִי בֵּין בַּמִּזְבֵּחַ הַחִיצוֹן. פָּסוּל:","דָּם שֶׁמִּצְוָתוֹ לִתֵּן אוֹתוֹ לְמַעְלָה מֵחֲצִי הַמִּזְבֵּחַ שֶׁנְּתָנוֹ לְמַטָּה. אוֹ שֶׁמִּצְוָתוֹ לִתְּנוֹ לְמַטָּה וּנְתָנוֹ לְמַעְלָה. אוֹ שֶׁמִּצְוָתוֹ לִתְּנוֹ בִּפְנִים בַּהֵיכָל וּנְתָנוֹ עַל מִזְבֵּחַ הַחִיצוֹן. אוֹ הַנִּתָּנִין עַל מִזְבֵּחַ הַחִיצוֹן שֶׁנְּתָנָן לִפְנִים בַּהֵיכָל. אוֹ שֶׁנָּתַן דַּם הַנִּתָּנִין בַּחוּץ עַל הַכֶּבֶשׁ שֶׁלֹּא כְּנֶגֶד הַיְסוֹד. הֲרֵי בְּשַׂר הַזֶּבַח פָּסוּל. וְאַף עַל פִּי כֵן נִתְכַּפְּרוּ הַבְּעָלִים בּוֹ כֵּיוָן שֶׁהִגִּיעַ דָּם לַמִּזְבֵּחַ. אַף עַל פִּי שֶׁהִגִּיעַ שֶׁלֹּא לִמְקוֹמוֹ הֲרֵי הוּא כְּמוֹ שֶׁהִגִּיעַ לִמְקוֹמוֹ לְכַפֵּר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה זֶה הַזּוֹרֵק כָּשֵׁר לַעֲבוֹדָה. אֲבָל אִם קִבֵּל הַכָּשֵׁר וְנָתַן לַפָּסוּל וְנָתַן הַפָּסוּל אֶת הַנִּתָּנִין לְמַעְלָה לְמַטָּה. וְאֶת הַנִּתָּנִין בִּפְנִים בַּחוּץ. וְאֶת הַנִּתָּנִין בַּחוּץ בִּפְנִים. אוֹ שֶׁנָּתַן עַל הַכֶּבֶשׁ שֶׁלֹּא כְּנֶגֶד הַיְסוֹד. לֹא נִפְסַל בְּשַׂר הַזֶּבַח אִם נִשְׁאַר דַּם הַנֶּפֶשׁ. אֶלָּא יַחְזֹר הַכָּשֵׁר וִיקַבֵּל שְׁאָר דַּם הַנֶּפֶשׁ וְיִזְרֹק הַדָּם בִּמְקוֹמוֹ:","דְּמֵי קָדָשִׁים שֶׁנִּתְעָרְבוּ. בֵּין דָּם בְּדָם. בֵּין כּוֹסוֹת בְּכוֹסוֹת. אִם נִתְעָרְבוּ הַנִּתָּנִין מַתָּנָה אַחַת בַּנִּתָּנִין מַתָּנָה אַחַת. יִתֵּן הַכּל מַתָּנָה אַחַת. וְכֵן הַנִּתָּנִין מַתַּן אַרְבַּע בַּנִּתָּנִין מַתַּן אַרְבַּע. יִתֵּן הַכּל מַתַּן אַרְבַּע. נִתְעָרְבוּ הַנִּתָּנִין מַתָּנָה אַחַת בַּנִּתָּנִין מַתַּן שְׁתַּיִם שֶׁהֵן אַרְבַּע. יִתֵּן הַכּל מַתָּנָה אַחַת. נִתְעָרְבוּ הַנִּתָּנִין לְמַעְלָה בַּנִּתָּנִין לְמַטָּה. יִשָּׁפֵךְ הַכּל לָאַמָּה וְהַזְּבָחִים פְּסוּלִין. אֲפִלּוּ נִתְעָרְבוּ שְׁיָרֵי הַחַטָּאת עִם דַּם הָעוֹלָה שֶׁמְּקוֹם הַכּל לְמַטָּה יִשָּׁפֵךְ הַכּל לָאַמָּה:","וְאִם לֹא שָׁאַל אֶלָּא נָתַן מִן הַתַּעֲרוֹבוֹת לְמַעְלָה וּלְמַטָּה הֲרֵי זֶה כָּשֵׁר. נָתַן לְמַעְלָה וְשָׁאַל יִתֵּן לְמַטָּה וְאֵלּוּ וְאֵלּוּ עָלוּ לוֹ:","נִתְעָרְבוּ הַנִּתָּנִין בִּפְנִים בַּנִּתָּנִין בַּחוּץ. יִשְׁפֹּךְ הַכּל לָאַמָּה. וְאִם לֹא שָׁאַל וְלָקַח דַּם הַתַּעֲרֹבֶת וְנָתַן מִמֶּנּוּ בִּפְנִים וּבַחוּץ. בֵּין שֶׁנָּתַן בִּפְנִים וְחָזַר וְנָתַן בַּחוּץ אוֹ בַּחוּץ וְחָזַר וְנָתַן בִּפְנִים הַכּל כָּשֵׁר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר דָּמִים הַנִּתָּנִים בַּחוּץ חוּץ מִן הַחַטָּאת. אֲבָל דַּם חַטָּאת הַנַּעֲשֵׂית בַּחוּץ שֶׁנִּתְעָרֵב בְּדַם חַטָּאת הַנַּעֲשֵׂית בִּפְנִים. אִם נָתַן בַּחוּץ וְחָזַר וְנָתַן בִּפְנִים כָּשֵׁר. נָתַן בִּפְנִים וְחָזַר וְנָתַן בַּחוּץ פְּסוּלָה. שֶׁדַּם חַטָּאת שֶׁנִּכְנַס לַהֵיכָל אֲפִלּוּ חַטַּאת יָחִיד הַנֶּאֱכֶלֶת אֲסוּרָה. שֶׁנֶּאֱמַר (ויקרא ו כג) \"וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ\" וְגוֹ'. וְהוּא שֶׁיָּבוֹא דֶּרֶךְ שַׁעַר הַהֵיכָל. שֶׁנֶּאֱמַר יוּבָא דֶּרֶךְ בִּיאָה. אֲבָל אִם הִכְנִיסוֹ בְּפִשְׁפָּשׁ אוֹ דֶּרֶךְ חַלּוֹן אוֹ גַּג. אֵינוֹ נִפְסַל:","פַּר הֶעְלֵם וְשָׂעִיר עֲבוֹדָה זָרָה שֶׁדָּמָם נִכְנָס לַהֵיכָל. אִם הִכְנִיסוֹ לְקֹדֶשׁ הַקָּדָשִׁים נִפְסַל שֶׁבְּמָקוֹם זֶה פְּנִימָה שֶׁל מְקוֹמָן הוּא. וְכֵן פַּר וְשָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים שֶׁדָּמָם נִכְנָס לְקֹדֶשׁ הַקָּדָשִׁים אִם הִכְנִיס דָּמָם לְקֹדֶשׁ הַקָּדָשִׁים וְהִזָּה מִמֶּנּוּ וְהוֹצִיאוֹ לַהֵיכָל וְחָזַר וְהִכְנִיסוֹ לְקֹדֶשׁ הַקָּדָשִׁים נִפְסַל וְאֵינוֹ גּוֹמֵר מִמֶּנּוּ הַזָּיוֹת שֶׁבְּקֹדֶשׁ הַקָּדָשִׁים כֵּיוָן שֶׁיָּצָא יָצָא. וְכֵן אִם גָּמַר הַזָּיוֹת שֶׁבְּקֹדֶשׁ הַקָּדָשִׁים וְהוֹצִיאָן לַהֵיכָל. וְהִזָּה מִקְצָת הַזָּיוֹת וְהוֹצִיאָן חוּץ לַהֵיכָל וְחָזַר וְהִכְנִיסָן לַהֵיכָל. אֵינוֹ גּוֹמֵר הַזָּיוֹת שֶׁבַּהֵיכָל. שֶׁכֵּיוָן שֶׁיָּצָא הַדָּם חוּץ לִמְקוֹמוֹ נִפְסַל:","חַטָּאת שֶׁקִּבֵּל דָּמָהּ בִּשְׁנֵי כּוֹסוֹת וְיָצָא אֶחָד מֵהֶם לַחוּץ. הַפְּנִימִי כָּשֵׁר וְיַזֶּה מִמֶּנּוּ. נִכְנַס אֶחָד מֵהֶם לַהֵיכָל וְהִזָּה מִמֶּנּוּ שָׁם. אַף הַחִיצוֹן פָּסוּל. שֶׁנֶּאֱמַר (ויקרא ו כג) \"אֲשֶׁר יוּבָא מִדָּמָהּ\" אֲפִלּוּ מִקְצָת דָּמָהּ אִם נִכְנַס לְכַפֵּר בַּקֹּדֶשׁ נִפְסְלָה:","דַּם חַטָּאת שֶׁהִכְנִיסוֹ לְכַפֵּר בּוֹ בִּפְנִים. וְלֹא כִּפֵּר אֶלָּא הוֹצִיאוֹ וְלֹא הִזָּה מִמֶּנּוּ בִּפְנִים כְּלוּם. אִם הִכְנִיסוֹ בְּשׁוֹגֵג הֲרֵי זֶה כָּשֵׁר וּמַזֶּה מִמֶּנּוּ בַּחוּץ שֶׁהֲרֵי לֹא כִּפֵּר בַּקֹּדֶשׁ. וְאִם הִכְנִיסוֹ בְּמֵזִיד פָּסוּל:","הִכְנִיס הַחַטָּאת עַצְמָהּ לַהֵיכָל כְּשֵׁרָה שֶׁנֶּאֱמַר (ויקרא ו כג) \"אֲשֶׁר יוּבָא מִדָּמָהּ\" וְלֹא בְּשָׂרָהּ:","חַטַּאת הָעוֹף שֶׁפִּרְכְּסָה וְנִכְנְסָה לַהֵיכָל כְּשֵׁרָה:","הִכְנִיס דַּם חַטַּאת הָעוֹף לַהֵיכָל בְּצַוָּארָהּ הֲרֵי זֶה סָפֵק אִם הַצַּוָּאר חָשׁוּב כִּכְלִי:","נִשְׁפַּךְ דַּם חַטַּאת הָעוֹף וַאֲסָפוֹ. הֲרֵי זֶה סָפֵק אִם הַכְּלִי פּוֹסֵל בְּדָמָהּ אוֹ אֵינוֹ פּוֹסֵל. לְפִיכָךְ תִּשָּׂרֵף כְּכָל חַטַּאת הָעוֹף שֶׁהוּא סָפֵק:","חַטָּאת שֶׁקִּבֵּל דָּמָהּ בְּאַרְבָּעָה כּוֹסוֹת. וְנָתַן מַתָּנָה אַחַת מִכָּל כּוֹס וְכוֹס. שְׁיָרֵי אַרְבַּעְתָּן נִשְׁפָּךְ עַל הַיְסוֹד שֶׁנֶּאֱמַר (ויקרא ד ל) (ויקרא ד לד) \"וְאֶת כָּל דָּמָהּ יִשְׁפֹּך\"ְ. נָתַן אַרְבַּע הַמַּתָּנוֹת מִכּוֹס אֶחָד. שְׁיָרֵי אוֹתוֹ הַכּוֹס נִשְׁפָּךְ עַל הַיְסוֹד וּשְׁאָר הַכּוֹסוֹת נִשְׁפָּכִין לָאַמָּה:","דָּם שֶׁנָּפַל לְתוֹךְ הַמַּיִם אוֹ לְתוֹךְ דָּמֵי חֻלִּין לֹא יַזֶּה מִמֶּנּוּ וְאִם הִזָּה פָּסוּל. נָפַל מַיִם לְתוֹךְ הַדָּם שֶׁבַּמִּזְרָק. אִם יֵשׁ בּוֹ מַרְאֵה דָּם כָּשֵׁר. נָפַל לְתוֹכוֹ יַיִן אוֹ דַּם חֻלִּין. אוֹמְדִין אוֹתוֹ אִלּוּ הָיוּ מַיִם. אִם רְאוּיִין לְבַטֵּל דָּם שֶׁבַּמִּזְרָק עַד שֶׁלֹּא יִהְיוּ מַרְאָיו מַרְאֵה דָּם הֲרֵי זֶה לֹא יַזֶּה מִמֶּנּוּ. וְאִם אֵינָם רְאוּיִין לְבַטֵּל מַרְאָיו יַזֶּה מִמֶּנּוּ:","דַּם הַקָּדָשִׁים שֶׁנִּתְעָרֵב בְּדַם פְּסוּלֵי הַמִּזְבֵּחַ אוֹ בְּדַם הַקָּדָשִׁים שֶׁנִּפְסְלוּ בִּשְׁחִיטָה. יִשָּׁפֵךְ הַכּל לָאַמָּה. וַאֲפִלּוּ קָרְבוּ כָּל הַכּוֹסוֹת חוּץ מֵאֶחָד יִשָּׁפֵךְ לָאַמָּה וְכָל אוֹתָן הַזְּבָחִים פְּסוּלִים. נִתְעָרֵב בְּדַם הַתַּמְצִית יִשָּׁפֵךְ לָאַמָּה. וְאִם לֹא שָׁאַל וְנָתַן כָּשֵׁר:","הָאֵימוּרִין וְאֵיבְרֵי הָעוֹלוֹת וְהַקְּמָצִים וְהַלְּבוֹנָה וּמְנָחוֹת הַנִּשְׂרָפוֹת אַחַר שֶׁנִּתְקַדְּשׁוּ בִּכְלִי שָׁרֵת. אִם זָרַק אֶחָד מִכָּל אֵלּוּ עַל גַּבֵּי הָאִשִּׁים בֵּין בְּיָד בֵּין בִּכְלִי בֵּין בְּיָמִין בֵּין בִּשְׂמֹאל הֲרֵי אֵלּוּ כְּשֵׁרִים:","הַיַּיִן וְהַמַּיִם שֶׁנִּסְכָן בֵּין בִּקְעָרָה בֵּין בְּהִין בֵּין בִּשְׁאָר כְּלֵי הַשָּׁרֵת כְּשֵׁרִים. נִסְּכָן בִּכְלִי חֹל אוֹ בְּיָדוֹ פְּסוּלִין:","אֵיבָרִים שֶׁסִּדְּרָן וְכֵן קֹמֶץ שֶׁסִּדְּרוֹ וְסִדֵּר הָעֵצִים שֶׁל מַעֲרָכָה לְמַעְלָה מֵהֶם. אוֹ שֶׁסִּדְּרָן מִצִּדֵּי הָעֵצִים. הֲרֵי זֶה סָפֵק אִם דֶּרֶךְ הַקְטָרָה בְּכָךְ אוֹ אֵין דֶּרֶךְ הַקְטָרָה בְּכָךְ. לְפִיכָךְ לֹא יַעֲשֶׂה כֵן לְכַתְּחִלָּה וְאִם עָשָׂה הֻרְצָה:"],"Mishneh Torah, Sacrificial Procedure 13":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת כּל מִנְחָה כְּמִצְוָתָהּ הָאֲמוּרָה בַּתּוֹרָה:","וְכֵיצַד עֲשִׂיַּת חֲבִיתֵי כֹּהֵן גָּדוֹל. מֵבִיא עִשָּׂרוֹן שָׁלֵם וּמַקְדִּישׁוֹ וְחוֹצֵהוּ בַּחֲצִי עִשָּׂרוֹן שֶׁבַּמִּקְדָּשׁ שֶׁאַף עַל פִּי שֶׁהִיא קְרֵבָה חֶצְיָן אֵינָהּ מִתְקַדֶּשֶׁת לְחֶצְיָן. וּמֵבִיא עִמָּהּ שְׁלֹשֶׁת לוֹגִין שֶׁמֶן שֶׁנֶּאֱמַר (ויקרא ו יד) \"בַּשֶּׁמֶן תֵּעָשֶׂה\" לְהוֹסִיף לָהּ שֶׁמֶן כְּנִסְכֵּי הַכֶּבֶשׂ. וּבוֹלֵל הַסּלֶת בְּשֶׁמֶן וְחוֹלְטָהּ בְּרוֹתְחִין. וְלָשׁ מִכָּל חֲצִי עִשָּׂרוֹן שֵׁשׁ חַלּוֹת. נִמְצְאוּ שְׁתֵּים עֶשְׂרֵה חַלּוֹת:","וְאַחַת אַחַת הָיוּ נַעֲשׂוֹת. וְכֵיצַד עוֹשֶׂה. מְחַלֵּק הַשְּׁלֹשָׁה לוֹגִין בִּרְבִיעִית שֶׁבַּמִּקְדָּשׁ. רְבִיעִית לְכָל חַלָּה. וְאוֹפָהּ הַחַלָּה מְעַט וְאַחַר כָּךְ קוֹלֶה אוֹתָהּ עַל הַמַּחֲבַת בִּשְׁאָר רְבִיעִית הַשֶּׁמֶן שֶׁלָּהּ. וְאֵינוֹ מְבַשְּׁלָהּ הַרְבֵּה שֶׁנֶּאֱמַר (ויקרא ו יד) \"תֻּפִינֵי\" בֵּין בָּשֵׁל וְנָא:","וְאַחַר כָּךְ חוֹלֵק כָּל חַלָּה וְחַלָּה לִשְׁנַיִם בְּאֹמֶד. כְּדֵי שֶׁיַּקְרִיב הַחֵצִי בַּבֹּקֶר וְהַחֵצִי בָּעֶרֶב וְלוֹקֵחַ הַחֲצָיִים וְכוֹפֵל כָּל אֶחָד מֵהֶן לִשְׁנַיִם וּפוֹתֵת עַד שֶׁתִּמָּצֵא כָּל פְּתִיתָה כְּפוּלָה לִשְׁנַיִם. וּמַקְרִיב הַחֲצָיִין עִם חֲצִי קֹמֶץ לְבוֹנָה בַּבֹּקֶר וְהַחֵצִי הַנִּשְׁאָר עִם חֲצִי קֹמֶץ לְבוֹנָה בָּעֶרֶב. וְאִם הָיְתָה מִנְחַת חִנּוּךְ אֵינוֹ חוֹצֶה אֶלָּא מַקְרִיבָהּ כֻּלָּהּ כְּאַחַת עִם קֹמֶץ לְבוֹנָה וּשְׁתֵּיהֶן כָּלִיל לָאִשִּׁים:","מִנְחַת הַסּלֶת כֵּיצַד הָיְתָה נַעֲשֵׂית. מֵבִיא עִשָּׂרוֹן סלֶת אוֹ כַּמָּה עֶשְׂרוֹנוֹת אוֹ כְּפִי נִדְרוֹ וְשֶׁמֶן הָרָאוּי לָהּ וּמוֹדֵד בְּעִשָּׂרוֹן שֶׁל מִקְדָּשׁ. וְנוֹתֵן שֶׁמֶן בִּכְלִי. וְאַחַר כָּךְ נוֹתֵן עָלָיו אֶת הַסּלֶת. וְאַחַר כָּךְ נוֹתֵן שֶׁמֶן אַחֵר עַל הַסּלֶת וּבוֹלֵל הַסּלֶת בּוֹ. וְאַחַר כָּךְ נוֹתְנָהּ בִּכְלִי שָׁרֵת וְצָק לְתוֹכָהּ שֶׁמֶן. וְשֶׁמֶן שֶׁנָּתַן תְּחִלָּה עִם הַשֶּׁמֶן הַבָּלוּל עִם שֶׁמֶן שֶׁיָּצַק הַכּל לוֹג לְעִשָּׂרוֹן וְנוֹתֵן עָלֶיהָ לְבוֹנָתָהּ:","מִנְחַת הַמַּחֲבַת וְהַמַּרְחֶשֶׁת כֵּיצַד. נוֹתֵן הַשֶּׁמֶן בִּכְלִי וְנוֹתֵן עָלָיו הַסּלֶת. וְנוֹתֵן עַל הַסּלֶת שֶׁמֶן אַחֵר וּבוֹלֵל הַסּלֶת וְאַחַר כָּךְ לָשָׁהּ בְּפוֹשְׁרִין וְאוֹפֶה אוֹתָהּ בְּמַחֲבַת אוֹ בַּמַּרְחֶשֶׁת כְּמוֹ שֶׁנָּדַר. וּפוֹתֵת אוֹתָהּ פִּתִּים וְנוֹתְנָהּ בִּכְלִי שָׁרֵת וְיוֹצֵק עָלֶיהָ שְׁאָר הַשֶּׁמֶן וְנוֹתֵן לְבוֹנָתָהּ:","מַה בֵּין מַחֲבַת לְמַרְחֶשֶׁת. מַרְחֶשֶׁת יֵשׁ לָהּ שָׂפָה וְהַבָּצֵק שֶׁאוֹפִין אוֹתוֹ עָלֶיהָ רַךְ שֶׁהֲרֵי יֵשׁ לָהּ שָׂפָה וְאֵינוֹ יוֹצֵא. וּמַחֲבַת אֵין לָהּ שָׂפָה וְהַבָּצֵק שֶׁאוֹפִין אוֹתוֹ בָּהּ קָשֶׁה כְּדֵי שֶׁלֹּא יֵצֵא מִכָּאן וּמִכָּאן:","מִנְחַת מַאֲפֵה תַּנּוּר כֵּיצַד. אִם חַלּוֹת הִיא בּוֹלֵל הַסּלֶת בְּשֶׁמֶן וְלָשׁ בְּפוֹשְׁרִין וְאוֹפֶה וּפוֹתֵת וְנוֹתֵן בִּכְלִי שָׁרֵת וְנוֹתֵן עָלֶיהָ לְבוֹנָתָהּ וְאֵין בָּהּ יְצִיקַת שֶׁמֶן שֶׁנֶּאֱמַר (ויקרא ב ד) \"חַלּוֹת מַצֹּת בְּלוּלֹת בַּשֶּׁמֶן\". וְאִם רְקִיקִין הִיא לָשׁ אֶת הַסּלֶת בְּפוֹשְׁרִין וּמוֹשֵׁחַ אֶת הָרְקִיקִין בְּשֶׁמֶן שֶׁנֶּאֱמַר (ויקרא ב ד) \"וּרְקִיקֵי מַצּוֹת מְשֻׁחִים בַּשָּׁמֶן\". וְיֵרָאֶה לִי שֶׁאַחַר אֲפִיָּה מוֹשֵׁחַ אוֹתָם:","וְכֵיצַד מוֹשְׁחָן. מֵבִיא לוֹג שֶׁמֶן לְכָל עִשָּׂרוֹן וּמוֹשְׁחָן וְחוֹזֵר וּמוֹשְׁחָן עַד שֶׁיִּכְלֶה כָּל הַשֶּׁמֶן שָׁבַּלֹּג:","כָּל אַרְבַּע מְנָחוֹת אֵלּוּ הָאֲפוּיוֹת. כְּשֶׁאוֹפִין אוֹתָן אוֹפִין כָּל עִשָּׂרוֹן עֶשֶׂר חַלּוֹת. וְאִם רִבָּה בְּחַלּוֹת אוֹ חִסֵּר כְּשֵׁרָה. וְכֵיצַד פּוֹתְתִין אוֹתָן. כּוֹפֵל הַחַלָּה לִשְׁנַיִם וְהַשְּׁנַיִם לְאַרְבָּעָה וּמַבְדִּיל. וְאִם הָיְתָה הַמִּנְחָה שֶׁל זִכְרֵי כְּהֻנָּה אֵינוֹ מַבְדִּיל וּפוֹתֵת. וְכֻלָּן פְּתִיתִין כְּזֵיתִים. וְאִם הִגְדִּיל הַפְּתִיתִין אוֹ הִקְטִין אוֹתָן כְּשֵׁרִים:","לֹא בָּלַל לֹא פָּתַת לֹא הִגִּישׁ לֹא מָשַׁח אֶת הָרְקִיקִין כְּשֵׁרָה. לֹא נֶאֶמְרוּ כָּל הַדְּבָרִים הָאֵלּוּ אֶלָּא לְמִצְוָה שֶׁכָּךְ הִיא מִצְוָתָהּ:","סֵדֶר הֲבָאַת הַמִּנְחָה כֵּיצַד. מֵבִיא אָדָם סלֶת מִתּוֹךְ בֵּיתוֹ בִּקְלָתוֹת שֶׁל כֶּסֶף אוֹ שֶׁל זָהָב אוֹ שֶׁל שְׁאָר מִינֵי מַתָּכוֹת כְּלִי שֶׁהוּא רָאוּי לִכְלֵי שָׁרֵת. וְאִם הָיְתָה מִנְחַת הַסּלֶת נוֹתְנָהּ לִכְלִי שָׁרֵת וּמְקַדְּשָׁהּ בִּכְלִי שָׁרֵת. וְאִם הָיְתָה מִן הַמְּנָחוֹת הַנֶּאֱפוֹת אוֹפֶה אוֹתָהּ שָׁם בַּמִּקְדָּשׁ וּפוֹתֵת כְּמוֹ שֶׁבֵּאַרְנוּ וְנוֹתֵן הַפְּתִיתִין לִכְלִי שָׁרֵת וְנוֹתֵן עָלֶיהָ שַׁמְנָהּ וּלְבוֹנָתָהּ וּמוֹלִיכָהּ אֵצֶל כֹּהֵן. וְהַכֹּהֵן מוֹלִיכָהּ אֵצֶל הַמִּזְבֵּחַ וּמַגִּישָׁהּ בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית כְּנֶגֶד חֻדָּהּ שֶׁל קֶרֶן וְדַיּוֹ. וּמְסַלֵּק אֶת כָּל לְבוֹנָתָהּ לְצַד אֶחָד וְקוֹמֵץ מִמָּקוֹם שֶׁנִּתְרַבָּה שַׁמְנָהּ שֶׁנֶּאֱמַר (ויקרא ב ב) \"מִסָּלְתָּהּ וּמִשַּׁמְנָהּ\". וְנוֹתֵן הַקֹּמֶץ לִכְלִי שָׁרֵת וּמְקַדְּשׁוֹ בִּכְלִי שָׁרֵת. וְקֹמֶץ שֶׁחִלְּקוֹ בִּשְׁנֵי כֵּלִים אֵינוֹ קָדוֹשׁ. וְחוֹזֵר וּמְקַדֵּשׁ וּמְלַקֵּט אֶת כָּל לְבוֹנָתָהּ וְנוֹתְנָהּ עַל הַקֹּמֶץ שֶׁבַּכְּלִי וּמַעֲלֵהוּ עַל הַמִּזְבֵּחַ וּמוֹלְחוֹ. וְנוֹתְנוֹ עַל גַּבֵּי הָאִשִּׁים מִכְּלִי שָׁרֵת. וְאִם מִנְחַת כֹּהֲנִים הִיא אֵינוֹ קוֹמֵץ אֶלָּא נוֹתֵן מֶלַח עַל כֻּלָּהּ וּמַשְׁלִיךְ הַכּל עַל גַּבֵּי הָאִשִּׁים:","כֵּיצַד קוֹמְצִין מְנָחוֹת הַנִּקְמָצוֹת. כְּדֶרֶךְ שֶׁקּוֹמֵץ כָּל הָאָדָם פּוֹשֵׁט אֶצְבְּעוֹתָיו עַל פַּס יָדוֹ וְקוֹמֵץ. קָמַץ בְּרָאשֵׁי אֶצְבְּעוֹתָיו אוֹ מִן הַצְּדָדִין לֹא יַקְטִיר וְאִם הִקְטִיר הֻרְצָה. וְאִם הוֹסִיף בַּקֹּמֶץ כְּגוֹן שֶׁהִרְחִיק אֶצְבְּעוֹתָיו וְקָמַץ הֲרֵי זֶה פָּסוּל:","אֵין קֹמֶץ פָּחוֹת מִכִּשְׁנֵי זֵיתִים. וּמִקְצָת הַקֹּמֶץ מְעַכֵּב אֶת כֻּלּוֹ. וְהַקֹּמֶץ וְהַלְּבוֹנָה מְעַכְּבִין זֶה אֶת זֶה. הַסּלֶת וְהַשֶּׁמֶן מְעַכְּבִין זֶה אֶת זֶה וּמִקְצָת הַשֶּׁמֶן מְעַכֵּב אֶת כֻּלּוֹ. אֵין פָּחוֹת מִלּוֹג לְעִשָּׂרוֹן כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sacrificial Procedure 7":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת הַחַטָּאוֹת כְּמִצְוָתָן הָאֲמוּרָה בַּתּוֹרָה. וְכֵיצַד מַעֲשֵׂה חַטָּאת הַנֶּאֱכֶלֶת. שׁוֹחֵט וְנוֹתֵן הַדָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַפְשִׁיטָהּ וּמַפְרִישׁ הָאֵימוּרִים וּמוֹלְחָן וְזוֹרְקָן עַל גַּבֵּי הָאִשִּׁים. וְאִם רָצָה לִתֵּן אֶת הָאֵימוּרִין בִּכְלִי כְּשֶׁמּוֹלִיכָן לַמִּזְבֵּחַ נוֹתֵן וּשְׁאָר בְּשָׂרָהּ נֶאֱכָל לְזִכְרֵי כְּהֻנָּה בָּעֲזָרָה:","וְכֵיצַד מַעֲשֵׂה חַטָּאוֹת הַנִּשְׂרָפוֹת. שׁוֹחֵט וְזוֹרֵק דָּמָם כְּמוֹ שֶׁבֵּאַרְנוּ. וְאַחַר כָּךְ קוֹרְעָם וּמוֹצִיא הָאֵימוּרִים וְנוֹתְנָן בִּכְלִי וּמוֹלְחָן וְזוֹרְקָן עַל גַּבֵּי הָאִשִּׁים. וּמוֹצִיא שְׁאֵרִיתָן חוּץ לָעִיר. וּמְנַתְּחִין אוֹתָן שָׁם כְּנִתְחֵי הָעוֹלָה בְּעוֹרָן. וְשׂוֹרְפִין אוֹתָן שָׁם בְּבֵית הַדֶּשֶׁן:","שְׁלֹשָׁה מְקוֹמוֹת לִשְׂרֵפָה. אֶחָד בְּתוֹךְ הָעֲזָרָה וּבוֹ שׂוֹרְפִין פְּסוּלֵי הַמֻּקְדָּשִׁין וְאֵמוּרֵי קָדָשִׁים קַלִּים שֶׁנִּפְסְלוּ וּפָרִים וּשְׂעִירִים שֶׁל חַטָּאוֹת הַנִּשְׂרָפוֹת אִם אֵרַע בָּהֶם פָּסוּל בֵּין לִפְנֵי זְרִיקָה בֵּין לְאַחַר זְרִיקָה. כְּגוֹן שֶׁנִּטְמְאוּ אוֹ שֶׁיָּצְאוּ חוּץ לָעֲזָרָה עַד שֶׁלֹּא הִגִּיעַ זְמַנָּן לָצֵאת. אוֹ שֶׁלָּן הַבָּשָׂר אוֹ לָנוּ הָאֵימוּרִין שֶׁלָּהֶן:","וְהַמָּקוֹם הַשֵּׁנִי בְּהַר הַבַּיִת וּשְׁמוֹ בִּירָה. וּבוֹ שׂוֹרְפִין חַטָּאוֹת הַנִּשְׂרָפוֹת אִם אֵרַע בָּהֶן פְּסוּל אַחַר צֵאתָן מִן הָעֲזָרָה. וְהַמָּקוֹם הַשְּׁלִישִׁי חוּץ לִירוּשָׁלַיִם וְהוּא הַנִּקְרָא בֵּית הַדֶּשֶׁן. וְשָׁם שׂוֹרְפִין חַטָּאוֹת הַנִּשְׂרָפוֹת בִּזְמַן שֶׁהֵן נִשְׂרָפוֹת כְּמִצְוָתָן:","וּשְׂרֵפַת כָּל הַנִּשְׂרָפִין כְּשֵׁרָה בְּזָר וּבַלַּיְלָה. וְכָל הַנִּשְׂרָפִין חוּץ לָעֲזָרָה כָּל הָעֵצִים כְּשֵׁרִין לִשְׂרֵפָתָן אֲפִלּוּ בְּקַשׁ וּבִגְבָבָא שֶׁנֶּאֱמַר (ויקרא ד יב) \"עַל עֵצִים בָּאֵשׁ\", אֵשׁ מִכָּל מָקוֹם. וְלָמָּה נֶאֱמַר עֵצִים לְהוֹצִיא אֶת הַסִּיד וְאֶת הָרֶמֶץ:","חַטַּאת הָעוֹף כֵּיצַד הָיְתָה נַעֲשֵׂית. מוֹלֵק אוֹתָהּ בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית כְּמוֹ שֶׁבֵּאַרְנוּ וְיוֹרֵד בְּצִפָּרְנוֹ עַד שֶׁיַּחְתֹּךְ הַסִּימָנִין אוֹ רֹב אֶחָד מֵהֶן וְאֵינוֹ מַבְדִּיל הָרֹאשׁ מִן הַגּוּף. וְאִם הִבְדִּיל פָּסַל וְלוֹקֶה שֶׁנֶּאֱמַר (ויקרא ה ח) \"וּמָלַק אֶת רֹאשׁוֹ מִמּוּל עָרְפּוֹ וְלֹא יַבְדִּיל\". וּמַזֶּה מִדָּמָהּ עַל קִיר הַמִּזְבֵּחַ לְמַטָּה מֵאֶמְצָעוֹ. וּשְׁיָרֵי הַדָּם מִתְמַצִּים עַל הַיְסוֹד שֶׁנֶּאֱמַר (ויקרא ה ט) \"וְהַנִּשְׁאָר בַּדָּם יִמָּצֵה עַל יְסוֹד הַמִּזְבֵּחַ\" מִכְּלָל שֶׁהַנְּתִינָה עַל קִיר שֶׁהַשְּׁיָרִין שֶׁלּוֹ מִתְמַצִּין אֶל יְסוֹד וְזֶהוּ קִיר הַתַּחְתּוֹן:","וּמִצּוּי דַּם חַטַּאת הָעוֹף מְעַכֵּב. וְאֵין לַמִּזְבֵּחַ בָּהּ אֶלָּא דָּמָהּ וְהַשְּׁאָר נֶאֱכָל לְזִכְרֵי כְּהֻנָּה כִּבְשַׂר חַטַּאת הַבְּהֵמָה:","כֵּיצַד אוֹחֵז חַטַּאת הָעוֹף בִּשְׁעַת מְלִיקָה. אוֹחֵז שְׁתֵּי רַגְלֶיהָ בֵּין שְׁתֵּי אֶצְבְּעוֹתָיו וּשְׁתֵּי אֲגַפֶּיהָ בֵּין שְׁתֵּי אֶצְבְּעוֹתָיו. וּמוֹתֵחַ צַוָּארָהּ אֶל רֹחַב שְׁתֵּי אֶצְבְּעוֹתָיו וּמוֹלֵק. וְזוֹ מֵעֲבוֹדוֹת קָשׁוֹת שֶׁבַּמִּקְדָּשׁ. וְאִם שִׁנָּה וְאָחַז בְּכָל מָקוֹם כְּשֵׁרָה:","וְכָל מָקוֹם מִן הַמִּזְבֵּחַ כָּשֵׁר לִמְלִיקָתָהּ. וּבִלְבַד שֶׁיַּזֶּה דָּמָהּ לְמַטָּה מֵאֶמְצַע הַמִּזְבֵּחַ. וְאִם הִזָּה בְּכָל מָקוֹם כְּשֵׁרָה. וְהוּא שֶׁיִּתֵּן לְמַטָּה מְעַט מִדַּם הַנֶּפֶשׁ:","שְׁלֹשָׁה דְּבָרִים הָיְתָה קֶרֶן דְּרוֹמִית מַעֲרָבִית מְשַׁמֶּשֶׁת לְמַעְלָה וּשְׁלֹשָׁה לְמַטָּה. מִלְּמַטָּה חַטַּאת הָעוֹף וְהַגָּשַׁת הַמְּנָחוֹת וּשְׁיָרֵי הַדָּם שֶׁל עוֹלוֹת וְחַטָּאוֹת הַנֶּאֱכָלוֹת וַאֲשָׁמוֹת וּשְׁלָמִים שֶׁשּׁוֹפְכִין עָלֶיהָ. וְהַשְּׁלֹשָׁה שֶׁל מַעְלָה נִסּוּךְ הַמַּיִם שֶׁמְּנַסְּכִין בֶּחָג וְנִסּוּךְ הַיַּיִן שֶׁל נְסָכִים וְעוֹלַת הָעוֹף בִּזְמַן שֶׁהִיא רַבָּה. וְאִם אֵין קֶרֶן דְּרוֹמִית מִזְרָחִית מְכִילָה אוֹתָהּ נִפְנִין לְקֶרֶן דְּרוֹמִית מַעֲרָבִית וְעוֹשִׂין אוֹתָהּ שָׁם:","כָּל הָעוֹלִין לַמִּזְבֵּחַ עוֹלִין דֶּרֶךְ יָמִין וּמַקִּיפִין וְיוֹרְדִין דֶּרֶךְ שְׂמֹאל. חוּץ מִן הָעוֹלֶה לְאֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ שֶׁלְּמַעְלָה בְּקֶרֶן זוֹ שֶׁהֵן עוֹלִין וְנִפְנִין עַל הַשְּׂמֹאל לַקֶּרֶן וְעוֹשִׂין מְלַאכְתָּן וְחוֹזְרִין לָעָקֵב. וּמִפְּנֵי מָה נִפְנִין לִשְׂמֹאל כְּדֵי שֶׁיִּפְגְּעוּ בְּקֶרֶן מַעֲרָבִית דְּרוֹמִית תְּחִלָּה. שֶׁאִם נִפְנִין עַל יָמִין וּמַקִּיפִין אֶת כָּל הַמִּזְבֵּחַ עַד שֶׁיַּגִּיעוּ לְקֶרֶן דְּרוֹמִית מַעֲרָבִית שֶׁמָּא יִתְעַשֵּׁן הַמַּיִם וְהַיַּיִן אוֹ שֶׁמָּא יָמוּת הָעוֹף בְּעֶשֶׁן הַמִּזְבֵּחַ:","לְפִיכָךְ הַמְנַסֵּךְ מַיִם אוֹ יַיִן כְּשֶׁהוּא מַקִּיף אֶת הַמִּזְבֵּחַ לֹא יִהְיֶה בְּיָדוֹ כְּלוּם. וּמַתְחִיל וּמַקִּיף מִקֶּרֶן דְּרוֹמִית מִזְרָחִית לְמִזְרָחִית צְפוֹנִית לִצְפוֹנִית מַעֲרָבִית לְמַעֲרָבִית דְּרוֹמִית וְלֹא יִהְיֶה בְּיָדוֹ כְּלוּם. וּכְשֶׁמַּגִּיעַ לְמַעֲרָבִית דְּרוֹמִית נוֹתְנִין הַמַּיִם אוֹ הַיַּיִן בְּיָדוֹ וּמְנַסֵּךְ. וְאִם לֹא הִקִּיף עוֹלֶה וּפוֹנֶה עַל שְׂמֹאלוֹ וְעוֹשֶׂה מְלַאכְתּוֹ וְיוֹרֵד:"],"Mishneh Torah, Sales 18":["אָסוּר לְרַמּוֹת אֶת בְּנֵי אָדָם בְּמִקָּח וּמִמְכָּר אוֹ לִגְנֹב אֶת דַּעְתָּם. וְאֶחָד עוֹבֵד כּוֹכָבִים וְאֶחָד יִשְׂרָאֵל שָׁוִים בְּדָבָר זֶה. הָיָה יוֹדֵעַ שֶׁיֵּשׁ בְּמִמְכָּרוֹ מוּם יוֹדִיעוֹ לַלּוֹקֵחַ. וַאֲפִלּוּ לִגְנֹב דַּעַת הַבְּרִיּוֹת בִּדְבָרִים אָסוּר:","אֵין מְפַרְכְּסִין אֶת הָאָדָם וְלֹא אֶת הַבְּהֵמָה וְלֹא אֶת הַכֵּלִים הַיְּשָׁנִים כְּדֵי שֶׁיֵּרָאוּ כַּחֲדָשִׁים. אֲבָל מְפַרְכְּסִין הַחֲדָשִׁים כְּגוֹן שֶׁיָּשׁוּף וִיגַהֵץ וִייַפֶּה כָּל צְרָכָיו:","אֵין מְשַׁרְבְּטִין אֶת הָאָדָם בְּמַיִם שֶׁל חֲזָרִין וְכַיּוֹצֵא בָּהֶן כְּדֵי שֶׁיִּתְפַּח וְיֵרָאוּ פָּנָיו שְׁמֵנִים. וְלֹא צוֹבְעִין אֶת הַפָּנִים בְּשָׁרָק וְכַיּוֹצֵא בּוֹ. וְלֹא נוֹפְחִין אֶת הַקְּרָבַיִם וְלֹא שׁוֹרִין אֶת הַבָּשָׂר בְּמַיִם. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ אֲסוּרִין. וְאֵין מוֹכְרִין בְּשַׂר נְבֵלָה לְנָכְרִי בִּכְלַל שְׁחוּטָה אַף עַל פִּי שֶׁהַנְּבֵלָה אֶצְלוֹ כִּשְׁחוּטָה:","מֻתָּר לָבֹר אֶת הַגְּרִיסִין אֲבָל לֹא עַל פִּי הַמְּגוּרָה. שֶׁאֵינוֹ אֶלָּא כְּגוֹנֵב אֶת הָעַיִן וִידַמֶּה שֶׁהוּא הַכּל בָּרוּר. וּמֻתָּר לְחֶנְוָנִי לְחַלֵּק קְלָיוֹת וֶאֱגוֹזִים לְתִינוֹקוֹת וְלִשְׁפָחוֹת כְּדֵי לְהַרְגִּילָן לָבוֹא אֶצְלוֹ. וּפוֹחֵת מִשַּׁעַר שֶׁבַּשּׁוּק כְּדֵי לְהַרְבּוֹת בְּמַקִּיפִין מִמֶּנּוּ. וְאֵין בְּנֵי הַשּׁוּק יְכוֹלִין לְעַכֵּב עָלָיו וְאֵין בָּזֶה גְּנֵבַת הַדַּעַת:","אֵין מְעָרְבִין פֵּרוֹת בְּפֵרוֹת אֲפִלּוּ חֲדָשִׁים בַּחֲדָשִׁים. וְאֵין צָרִיךְ לוֹמַר יְשָׁנִים בַּחֲדָשִׁים. אֲפִלּוּ הַיְשָׁנִים בְּיֹקֶר וְהַחֲדָשִׁים בְּזוֹל. מִפְּנֵי שֶׁהַלּוֹקֵחַ רוֹצֶה לְיַשְּׁנָן. בְּיַיִן הוּא שֶׁהִתִּירוּ לְעָרֵב קָשֶׁה בְּרַךְ בֵּין הַגִּתּוֹת בִּלְבַד מִפְּנֵי שֶׁמַּשְׁבִּיחוֹ. וְאִם הָיָה טַעֲמוֹ נִכָּר מֻתָּר לְעָרֵב בְּכָל מָקוֹם. שֶׁכָּל דָּבָר הַנִּכָּר טַעְמוֹ מַרְגִּישׁ הַלּוֹקֵחַ וּלְפִיכָךְ מֻתָּר לְעָרֵב אוֹתוֹ:","אֵין מְעָרְבִין מַיִם בְּיַיִן. וּמִי שֶׁנִּתְעָרֵב לוֹ מַיִם בְּיֵינוֹ לֹא יִמְכְּרֶנּוּ בַּחֲנוּת אֶלָּא אִם כֵּן מוֹדִיעוֹ. וְלֹא לְתַגָּר אַף עַל פִּי שֶׁמּוֹדִיעוֹ, שֶׁמְּרַמֶּה בּוֹ אֲחֵרִים. וּמָקוֹם שֶׁנָּהֲגוּ לְהַטִּיל מַיִם בְּיַיִן יַטִּיל. וְהוּא שֶׁיִּהְיֶה בֵּין הַגִּתּוֹת:","הַתַּגָּר נוֹטֵל מֵחָמֵשׁ גִּתּוֹת וְנוֹתֵן לְתוֹךְ פִּיטָם אֶחָד. מֵחָמֵשׁ גֳּרָנוֹת וְנוֹתֵן לְתוֹךְ מְגוּרָה אַחַת. וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לְעָרֵב:","אָסוּר לְעָרֵב שְׁמָרִים בֵּין בְּיַיִן בֵּין בְּשֶׁמֶן וַאֲפִלּוּ כָּל שֶׁהוּא. וַאֲפִלּוּ שְׁמָרִים שֶׁל אֶמֶשׁ בִּשְׁמָרִים שֶׁל יוֹם אָסוּר. אֲבָל אִם עֵרָה הַיַּיִן מִכְּלִי אֶל כְּלִי נוֹתֵן שְׁמָרָיו לְתוֹכוֹ:","הַמּוֹכֵר לַחֲבֵרוֹ שֶׁמֶן מְזֻקָּק אֵינוֹ מְקַבֵּל שְׁמָרִים. מָכַר לוֹ שֶׁמֶן סְתָם מְקַבֵּל לוֹג וּמֶחֱצָה שְׁמָרִים לְכָל מֵאָה לוֹג. וּמְקַבֵּל בִּשְׁאָר שְׁמָרִים שֶׁמֶן עָכוּר הָעוֹלֶה לְמַעְלָה עַל פְּנֵי הַשֶּׁמֶן יֶתֶר עַל הַשְּׁמָרִים הַיְדוּעִים בְּאוֹתוֹ מָקוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנָּתַן לוֹ מָעוֹת בְּתִשְׁרֵי שֶׁהַשֶּׁמֶן עָכוּר. וְלָקַח הַשֶּׁמֶן בְּנִיסָן כְּמִדַּת תִּשְׁרֵי שֶׁהִיא גְּדוֹלָה מִפְּנֵי אוֹתוֹ הַשֶּׁמֶן הַקּוֹפֶה לְמַעְלָה. אֲבָל אִם לָקַח בְּמִדַּת נִיסָן שֶׁהִיא קְטַנָּה מִפְּנֵי שֶׁכְּבָר צָלַל הַשֶּׁמֶן אֵינוֹ מְקַבֵּל אֶלָּא הַשְּׁמָרִים בִּלְבַד:","הַמּוֹכֵר חִטִּים לַחֲבֵרוֹ מְקַבֵּל עָלָיו רֹבַע קִטְנִית לְכָל סְאָה. שְׂעוֹרִים מְקַבֵּל עָלָיו רֹבַע נִישׁוֹבוֹת לְכָל סְאָה. עֲדָשִׁים מְקַבֵּל עָלָיו רֹבַע עַפְרוּרִית לִסְאָה. תְּאֵנִים מְקַבֵּל עָלָיו עֶשֶׂר מַתְלִיעוֹת לְכָל מֵאָה. מָכַר לוֹ שְׁאָר פֵּרוֹת מְקַבֵּל עָלָיו רֹבַע טִנוֹפוֹת לְכָל סְאָה. נִמְצָא מֵהֶן יֶתֶר עַל הַשִּׁעוּרִים הָאֵלּוּ כָּל שֶׁהוּא יְנַפֶּה אֶת הַכּל וְיִתֵּן לוֹ פֵּרוֹת מְנֻפִּין וּבְרוּרִין שֶׁאֵין בָּהֶן כְּלוּם:","וְאֵין כָּל אֵלּוּ הַדְּבָרִים אֲמוּרִים אֶלָּא בְּמָקוֹם שֶׁאֵין לָהֶם מִנְהָג אֲבָל בְּמָקוֹם שֶׁיֵּשׁ לָהֶם מִנְהָג הַכּל כְּמִנְהַג הַמְּדִינָה:","יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁיִּהְיוּ כָּל פֵּרוֹת מְנֻקִּים וּבְרוּרִים מִכָּל דָּבָר. וְשֶׁיִּהְיוּ הַיֵּינוֹת וְהַשְּׁמָנִים צְלוּלִין. וְלֹא יִמְכְּרוּ הַשְּׁמָרִים כְּלָל. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ אֲפִלּוּ הָיוּ בָּהֶן מֶחֱצָה שְׁמָרִים. אוֹ שֶׁהָיוּ בְּפֵרוֹת מֶחֱצָה עָפָר אוֹ תֶּבֶן אוֹ מִין אַחֵר יִמָּכֵר כְּמוֹת שֶׁהוּא. לְפִיכָךְ הַבּוֹרֵר צְרוֹר מִתּוֹךְ גָּרְנוֹ שֶׁל חֲבֵרוֹ נוֹתֵן לוֹ דְּמֵי חִטִּים כְּשִׁעוּר צְרוֹר שֶׁבֵּרֵר. שֶׁאִלּוּ הִנִּיחוֹ הָיָה נִמְכָּר בְּמִדַּת חִטִּים. וְאִם תֹּאמַר יַחְזִירֶנּוּ הֲרֵי אָמְרוּ אָסוּר לְעָרֵב כָּל שֶׁהוּא:","הַמּוֹכֵר קַנְקַנִּים בַּשָּׁרוֹן בְּמָקוֹם שֶׁאֵין מִנְהָג מְקַבֵּל לְכָל מֵאָה עֲשָׂרָה פִּיטָסוֹת. וְהוּא שֶׁיִּהְיוּ נָאוֹת וַעֲשׂוּיוֹת בְּגָפְרִית:"],"Mishneh Torah, Sales 29":["שְׁלֹשָׁה אֵין מִקָּחָן מִקָּח וְאֵין מִמְכָּרָן מִמְכַּר דִּין תּוֹרָה. הַחֵרֵשׁ הַשּׁוֹטֶה וְהַקָּטָן. אֲבָל חֲכָמִים תִּקְּנוּ שֶׁיִּהְיֶה הַחֵרֵשׁ וְהַקָּטָן נוֹשֵׂא וְנוֹתֵן וּמַעֲשָׂיו קַיָּמִין מִשּׁוּם כְּדֵי חַיָּיו:","הַחֵרֵשׁ כֵּיצַד נוֹשֵׂא וְנוֹתֵן. חֵרֵשׁ שֶׁאֵינוֹ שׁוֹמֵעַ וְלֹא מְדַבֵּר אוֹ מְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ כְּלוּם. מוֹכֵר וְלוֹקֵחַ הַמִּטַּלְטְלִין בִּרְמִיזָה. אֲבָל לֹא בְּקַרְקַע. וְאַף בְּמִטַּלְטְלִין לֹא יִתְקַיְּמוּ מַעֲשָׂיו עַד שֶׁבּוֹדְקִין אוֹתוֹ בְּדִיקוֹת רַבּוֹת וּמִתְיַשְּׁבִין בַּדָּבָר:","אִלֵּם שֶׁשּׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר אוֹ מִי שֶׁנִּשְׁתַּתֵּק מִקָּחוֹ מִקָּח וּמִמְכָּרוֹ מִמְכָּר וּמַתְּנוֹתָיו קַיָּמוֹת בַּכּל. בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקַע. וְהוּא שֶׁיִּבְדֹּק כְּדֶרֶךְ שֶׁבּוֹדְקִין לְגִטִּין אוֹ יִכְתֹּב בִּכְתַב יָדוֹ:","הַשּׁוֹטֶה אֵין מִקָּחוֹ מִקָּח וְאֵין מִמְכָּרוֹ מִמְכָּר וְאֵין מַתְּנוֹתָיו קַיָּמוֹת. וּבֵית דִּין מַעֲמִידִים אַפּוֹטְרוֹפּוֹס לְשׁוֹטִים כְּדֶרֶךְ שֶׁמַּעֲמִידִין לִקְטַנִּים:","מִי שֶׁהוּא עֵת שׁוֹטֶה וְעֵת שָׁפוּי כְּגוֹן אֵלּוּ הַנִּכְפִּין. בְּעֵת שֶׁהוּא שָׁפוּי כָּל מַעֲשָׂיו קַיָּמִין וְזוֹכֶה לְעַצְמוֹ וְלַאֲחֵרִים כְּכָל בֶּן דַּעַת. וּצְרִיכִין הָעֵדִים לַחְקֹר הַדָּבָר הֵיטֵב שֶׁמָּא בְּסוֹף שְׁטוּתוֹ אוֹ בִּתְחִלַּת שְׁטוּתוֹ עָשָׂה מַה שֶּׁעָשָׂה:","קָטָן עַד שֵׁשׁ שָׁנִים אֵין הַקְנָיָתוֹ לַאֲחֵרִים כְּלוּם. וּמִשֵּׁשׁ שָׁנִים עַד שֶׁיַּגְדִּיל אִם יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן מִקָּחוֹ מִקָּח וּמִמְכָּרוֹ מִמְכָּר וּמַתְּנָתוֹ קַיֶּמֶת. בֵּין בְּדָבָר מְרֻבֶּה בֵּין בְּדָבָר מוּעָט בֵּין בְּמַתְּנַת בָּרִיא בֵּין בְּמַתְּנַת שְׁכִיב מֵרַע. וְדָבָר זֶה מִדִּבְרֵי חֲכָמִים כְּמוֹ שֶׁבֵּאַרְנוּ כְּדֵי שֶׁלֹּא יִבָּטֵל וְלֹא יִמָּצֵא מִי שֶׁיִּמְכֹּר לוֹ וְלֹא יִקַּח מִמֶּנּוּ. וְהַכּל בְּמִטַּלְטְלִין אֲבָל בַּקַּרְקַע אֵינוֹ מוֹכֵר וְלֹא נוֹתֵן עַד שֶׁיַּגְדִּיל:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָטָן שֶׁאֵין לוֹ אַפּוֹטְרוֹפּוֹס. אֲבָל אִם הָיָה לוֹ אַפּוֹטְרוֹפּוֹס אֵין מַעֲשָׂיו כְּלוּם אֲפִלּוּ בְּמִטַּלְטְלִין אֶלָּא מִדַּעַת הָאַפּוֹטְרוֹפּוֹס. שֶׁאִם רָצָה לְקַיֵּם מִקָּחוֹ וּמִמְכָּרוֹ וּמַתְּנָתוֹ בְּמִטַּלְטְלִין קַיָּם:","בּוֹדְקִין אֶת הַקָּטָן אִם יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן אוֹ אֵינוֹ יוֹדֵעַ. לְפִי שֶׁיֵּשׁ קָטָן חָכָם וְנָבוֹן שֶׁהוּא יוֹדֵעַ וְהוּא בֶּן שֶׁבַע. וְיֵשׁ אַחֵר שֶׁאֲפִילוּ בֶּן שְׁלֹשׁ עֶשְׂרֵה אֵינוֹ יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן. קָטָן הַיּוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן שֶׁאֵין לוֹ אַפּוֹטְרוֹפּוֹס שֶׁנָּשָׂא וְנָתַן בְּמִטַּלְטְלִין וְטָעָה דִּינוֹ כְּדִין הַגָּדוֹל. פָּחוֹת מִשְּׁתוּת מְחִילָה. שְׁתוּת מַחְזִיר הַהוֹנָיָה. יֶתֶר עַל שְׁתוּת בָּטֵל מִקָּח כְּמוֹ שֶׁבֵּאַרְנוּ. וַאֲנִי אוֹמֵר שֶׁאֵין מִקַּח הַקָּטָן וּמִמְכָּרָיו בְּמִטַּלְטְלִין קַיָּמִין אֶלָּא בְּשֶׁמָּשַׁךְ אוֹ הִמְשִׁיךְ. אֲבָל אִם נָתַן מָעוֹת עַל הַמִּקָּח וְחָזַר בּוֹ אֵינוֹ מְקַבֵּל מִי שֶׁפָּרַע וַאֲחֵרִים שֶׁחָזְרוּ בּוֹ מְקַבְּלִין מִי שֶׁפָּרַע:","וְכֵן אִם קָנוּ מִיַּד הַקָּטָן אוֹ הִשְׂכִּיר מְקוֹם הַמִּטַּלְטְלִין וְחָזַר בּוֹ לֹא קָנָה הַלּוֹקֵחַ שֶׁאֵין מוֹצִיאִין מִידֵי הַקָּטָן בְּדִין וְאֵין קִנְיָן מִיַּד הַקָּטָן כְּלוּם. שֶׁהַקִּנְיָן בִּשְׁטָר וְאֵין הָעֵדִים חוֹתְמִין אֶלָּא עַל שְׁטָר שֶׁל אָדָם גָּדוֹל:","וְכֵן קָטָן שֶׁקָּנָה מִטַּלְטְלִין וְקָנוּ מִיָּדוֹ וְשָׂכַר מֵהֶם הַמָּקוֹם לֹא קָנָה עַד שֶׁיִּמְשֹׁךְ. לְפִי שֶׁאֵינוֹ זוֹכֶה בִּדְרָכִים שֶׁזּוֹכִין בָּהֶן הַגְּדוֹלִים. רְאָיָה לַדָּבָר שֶׁאֵין חָצֵר שֶׁל קָטָן וְלֹא אַרְבַּע אַמּוֹת שֶׁלּוֹ קוֹנִין לוֹ מִפְּנֵי שֶׁנִּתְרַבּוּ מִדִּין שְׁלִיחוּת וְלֹא מִדִּין יָדוֹ כְּמוֹ שֶׁיִּתְבָּאֵר וְלֹא יִהְיֶה הַקִּנְיָן אוֹ שְׂכִירוּת הַמָּקוֹם גָּדוֹל מֵחֲצֵרוֹ. אֲבָל הַקְּטַנָּה שֶׁנִתְרַבְּתָה חֲצֵרָהּ מִיָּדָהּ תִּקְנֶה הַמִּטַּלְטְלִין מֵאֲחֵרִים אִם קָנוּ מִיָּדָהּ אוֹ בִּשְׂכִירוּת מָקוֹם:","יֵרָאֶה לִי שֶׁקָּטָן שֶׁקָּנָה קַרְקַע וְנָתַן דָּמִים וְהֶחֱזִיק בַּקַּרְקַע תַּעֲמֹד בְּיָדוֹ אַף עַל פִּי שֶׁאֵין מִמְכָּרוֹ בַּקַּרְקַע כְּלוּם שֶׁהַקָּטָן כְּמִי שֶׁאֵינוֹ בְּפָנֵינוּ הוּא וְזָכִין לְאָדָם שֶׁלֹּא בְּפָנָיו וְאֵין חָבִין לוֹ אֶלָּא בְּפָנָיו:","קָטָן שֶׁהִגְדִּיל וְהֵבִיא הַזָּכָר שְׁתֵּי שְׂעָרוֹת אַחַר שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְהַבַּת אַחַר שְׁתֵּים עֶשְׂרֵה אַף עַל פִּי שֶׁאֵינוֹ יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן מִקָּחוֹ מִקָּח וּמִמְכָּרוֹ מִמְכָּר וּמַתְּנָתוֹ מַתָּנָה בְּמִטַּלְטְלִין. אֲבָל בְּקַרְקַע אֵין מַעֲשָׂיו קַיָּמִין עַד שֶׁיִּהְיֶה יוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן אַחַר שֶׁהִגְדִּיל:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּקַרְקַע שֶׁלּוֹ. אֲבָל קַרְקַע שֶׁיָּרַשׁ מֵאֲבוֹתָיו אוֹ מִשְּׁאָר מוֹרִישָׁיו אֵין מִמְכָּרוֹ מִמְכָּר עַד שֶׁיִּהְיֶה בֶּן עֶשְׂרִים שָׁנָה אַף עַל פִּי שֶׁהֵבִיא שְׁתֵּי שְׂעָרוֹת וְיוֹדֵעַ בְּטִיב מַשָּׂא וּמַתָּן. שֶׁמָּא יִמְכֹּר בְּזוֹל מִפְּנֵי שֶׁדַּעְתּוֹ נוֹטָה אַחַר הַמָּעוֹת וַעֲדַיִן לֹא נִתְיַשְּׁבָה דַּעְתּוֹ בְּדַרְכֵי הָעוֹלָם:","מַתְּנָתוֹ כְּשֶׁהוּא פָּחוֹת מִבֶּן עֶשְׂרִים בֵּין מַתְּנַת בָּרִיא בֵּין מַתְּנַת שְׁכִיב מֵרַע הֲרֵי זוֹ קַיֶּמֶת. שֶׁאִלּוּ לֹא הִגִּיעַ לוֹ הֲנָיָה גְּדוֹלָה לֹא נָתַן. וְהוּא דָּבָר שֶׁאֵינוֹ מָצוּי תָּמִיד. וְאָמְרוּ חֲכָמִים תִּתְקַיֵּם מַתְּנָתוֹ כְּדֵי שֶׁיִּהְיוּ דְּבָרָיו נִשְׁמָעִין:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא מוֹכֵר קַרְקַע אָבִיו כְּשֶׁהוּא בֶּן עֶשְׂרִים כְּשֶׁהֵבִיא שְׁתֵּי שְׂעָרוֹת אוֹ כְּשֶׁנּוֹלְדוּ לוֹ סִימָנֵי סָרִיס. אֲבָל אִם לֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְלֹא נַעֲשָׂה סָרִיס. קָטָן הוּא וְאֵין מִמְכָּרוֹ בַּקַּרְקַע מִמְכָּר וַאֲפִלּוּ בִּנְכָסָיו עַד שֶׁיַּגְדִּיל לְרֹב שְׁנוֹתָיו:","מִי שֶׁמָּכַר בֵּין בִּנְכָסָיו בֵּין בְּנִכְסֵי אָבִיו וּמֵת וּבָאוּ קְרוֹבָיו וְעִרְעֲרוּ שֶׁהָיָה קָטָן בִּשְׁעַת הַמֶּכֶר וּבִקְּשׁוּ לְבָדְקוֹ אֵין שׁוֹמְעִין לָהֶם לְנַוְּלוֹ. וְעוֹד שֶׁהַסִּימָנִים מִשְׁתַּנִין בְּמִיתָה. וַחֲזָקָה הִיא שֶׁאֵין הָעֵדִים חוֹתְמִין עַל הַשְּׁטָר אֶלָּא אִם כֵּן יָדְעוּ בְּוַדַּאי שֶׁהַמּוֹכֵר גָּדוֹל:","פָּחוֹת מִבֶּן עֶשְׂרִים שֶׁמָּכַר קַרְקַע אָבִיו חוֹזֵר וּמוֹצִיא מִיַּד הַלּוֹקֵחַ בֵּין קֹדֶם עֶשְׂרִים בֵּין אַחַר עֶשְׂרִים. וּמוֹצִיא מִן הַלּוֹקֵחַ כָּל הַפֵּרוֹת שֶׁאָכַל. וְאִם הוֹצִיא הוֹצָאוֹת אוֹ שֶׁנָּטַע וְזָרַע שָׁמִין לוֹ וּמַחֲזִיר אֶת הַשְּׁאָר. כַּדִּין הַזֶּה הוֹרוּ רַבּוֹתַי. וַאֲנִי אוֹמֵר שֶׁאֲפִלּוּ קָטָן שֶׁמָּכַר קַרְקַע מִנִּכְסֵי אָבִיו וּכְשֶׁנַּעֲשָׂה בֶּן עֶשְׂרִים לֹא מִחָה אֵינוֹ יָכוֹל לַחְזֹר. שֶׁכֵּיוָן שֶׁלָּקַח הַמָּעוֹת וְנִשְׁתַּמֵּשׁ הַלּוֹקֵחַ בְּקַרְקַע זוֹ לְפָנָיו כְּשֶׁהוּא בֶּן עֶשְׂרִים וְלֹא מִחָה נִתְקַיְּמָה בִּידֵי הַלּוֹקֵחַ שֶׁהֲרֵי רָצָה בְּמִמְכָּרוֹ:","הַשִּׁכּוֹר מִקָּחוֹ מִקָּח וּמִמְכָּרוֹ מִמְכָּר וּמַתְּנוֹתָיו קַיָּמִין. וְאִם הִגִּיעַ לְשִׁכְרוּתוֹ שֶׁל לוֹט וְהוּא הַשִּׁכּוֹר שֶׁעוֹשֶׂה וְאֵינוֹ יוֹדֵעַ מָה עוֹשֶׂה אֵין מַעֲשָׂיו כְּלוּם וַהֲרֵי הוּא כְּשׁוֹטֶה אוֹ כְּקָטָן פָּחוֹת מִבֶּן שֵׁשׁ:"],"Mishneh Torah, Sanctification of the New Month 12":["מַהֲלַךְ הַשֶּׁמֶשׁ הָאֶמְצָעִי בְּיוֹם אֶחָד שֶׁהוּא כ\"ד שָׁעוֹת נ\"ט חֲלָקִים וּשְׁמוֹנֶה שְׁנִיּוֹת. סִימָנָם כ\"ד נט\"ח. נִמְצָא מַהֲלָכָהּ בַּעֲשָׂרָה יָמִים תֵּשַׁע מַעֲלוֹת וְנ\"א חֲלָקִים וְכ\"ג שְׁנִיּוֹת. סִימָנָם טנ\"א כ\"ג. וְנִמְצָא מַהֲלָכָהּ בְּמֵאָה יוֹם צ\"ח מַעֲלוֹת וּשְׁלֹשָׁה וּשְׁלֹשִׁים חֲלָקִים וְנ\"ג שְׁנִיּוֹת. סִימָנָם צ\"ח ל\"ג נ\"ג. וְנִמְצָא שְׁאֵרִית מַהֲלָכָהּ בְּאֶלֶף יוֹם אַחַר שֶׁתַּשְׁלִיךְ כָּל ש\"ס מַעֲלוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. רס\"ה מַעֲלוֹת וְל\"ח חֲלָקִים וְנ' שְׁנִיּוֹת. סִימָנָם רס\"ה לח\"ן. וְנִמְצָא שְׁאֵרִית מַהֲלָכָהּ בַּעֲשֶׂרֶת אֲלָפִים יוֹם. קל\"ו מַעֲלוֹת וְכ\"ח חֲלָקִים וְכ' שְׁנִיּוֹת. סִימָנָם קל\"ו כ\"ח כ'. וְעַל הַדֶּרֶךְ הַזֶּה תִּכְפּל וְתוֹצִיא מַהֲלָכָהּ לְכָל מִנְיָן שֶׁתִּרְצֶה. וְכֵן אִם תִּרְצֶה לַעֲשׂוֹת סִימָנִין יְדוּעִים אֶצְלְךָ לְמַהֲלָכָהּ לִשְׁנֵי יָמִים וְלִשְׁלֹשָׁה וּלְאַרְבָּעָה עַד עֲשָׂרָה תַּעֲשֶׂה. וְכֵן אִם תִּרְצֶה לִהְיוֹת לְךָ סִימָנִין יְדוּעִים מוּכָנִין לְמַהֲלָכָהּ לְכ' יוֹם וּלְל' וּלְמ' עַד מֵאָה תַּעֲשֶׂה. וְדָבָר גָּלוּי הוּא וְיָדוּעַ מֵאַחַר שֶׁיָּדַעְתָּ מַהֲלַךְ יוֹם אֶחָד. וְרָאוּי הוּא לִהְיוֹת מוּכָן וְיָדוּעַ אֶצְלְךָ מַהֲלַךְ אֶמְצַע הַשֶּׁמֶשׁ לְכ\"ט יוֹם וּלְשנ\"ד יוֹם שֶׁהֵן יְמֵי שְׁנַת הַלְּבָנָה בִּזְמַן שֶׁחֳדָשֶׁיהָ כְּסִדְרָן. וְהִיא הַנִּקְרֵאת שָׁנָה סְדוּרָה. שֶׁבִּזְמַן שֶׁיִּהְיוּ לְךָ אֶמְצָעִיּוֹת אֵלּוּ מוּכָנִין יִהְיֶה הַחֶשְׁבּוֹן הַזֶּה קַל עָלֶיךָ לִרְאִיַּת הַחֹדֶשׁ. לְפִי שֶׁכ\"ט יוֹם גְּמוּרִים מִלֵּיל הָרְאִיָּה עַד לֵיל הָרְאִיָּה שֶׁל חֹדֶשׁ הַבָּא וְכֵן בְּכָל חֹדֶשׁ וְחֹדֶשׁ אֵין פָּחוֹת מִכ\"ט יוֹם וְלֹא יוֹתֵר. שֶׁאֵין חֶפְצֵנוּ בְּכָל אֵלּוּ הַחֶשְׁבּוֹנוֹת אֶלָּא לָדַעַת הָרְאִיָּה בִּלְבַד. וְכֵן מִלֵּיל הָרְאִיָּה שֶׁל חֹדֶשׁ זֶה עַד לֵיל הָרְאִיָּה לְאוֹתוֹ הַחֹדֶשׁ לַשָּׁנָה הַבָּאָה שָׁנָה סְדוּרָה אוֹ שָׁנָה וְיוֹם אֶחָד. וְכֵן בְּכָל שָׁנָה וְשָׁנָה. וּמַהֲלַךְ הַשֶּׁמֶשׁ הָאֶמְצָעִי לְכ\"ט יוֹם כ\"ח מַעֲלוֹת וְל\"ה חֲלָקִים וּשְׁנִיָּה אַחַת. סִימָנָן כ\"ח ל\"ה א'. וּמַהֲלָכָהּ לְשָׁנָה סְדוּרָה שמ\"ח מַעֲלוֹת וְנ\"ה חֲלָקִים וְט\"ו שְׁנִיּוֹת סִימָנָן שמ\"ח נ\"ה ט\"ו:","נְקֻדָּה אַחַת יֵשׁ בְּגַלְגַּל הַשֶּׁמֶשׁ וְכֵן בִּשְׁאָר גַּלְגַּלֵּי הַשִּׁבְעָה כּוֹכָבִים. בְּעֵת שֶׁיִּהְיֶה הַכּוֹכָב בָּהּ יִהְיֶה גָּבוֹהַּ מֵעַל הָאָרֶץ כָּל מְאוֹרוֹ. וְאוֹתָהּ הַנְּקֻדָּה שֶׁל גַּלְגַּל הַשֶּׁמֶשׁ וּשְׁאָר הַכּוֹכָבִים חוּץ מִן הַיָּרֵחַ סוֹבֶבֶת בְּשָׁוֶה. וּמַהֲלָכָהּ בְּכָל שִׁבְעִים שָׁנָה בְּקֵרוּב מַעֲלָה אַחַת. וּנְקֻדָּה זוֹ הִיא הַנִּקְרֵאת גֹּבַהּ הַשֶּׁמֶשׁ. מַהֲלָכוֹ בְּכָל עֲשָׂרָה יָמִים שְׁנִיָּה אַחַת וַחֲצִי שְׁנִיָּה שֶׁהִיא ל' שְׁלִישִׁיּוֹת. נִמְצָא מַהֲלָכוֹ בְּק' יוֹם ט\"ו שְׁנִיּוֹת. וּמַהֲלָכוֹ בְּאֶלֶף יוֹם שְׁנֵי חֲלָקִים וּשְׁלֹשִׁים שְׁנִיּוֹת. וּמַהֲלָכוֹ בַּעֲשֶׂרֶת אֲלָפִים יוֹם כ\"ה חֲלָקִים. וְנִמְצָא מַהֲלָכוֹ לְתִשְׁעָה וְעֶשְׂרִים יוֹם אַרְבַּע שְׁנִיּוֹת וְעוֹד. וּמַהֲלָכוֹ בְּשָׁנָה סְדוּרָה נ\"ג שְׁנִיּוֹת. כְּבָר אָמַרְנוּ שֶׁהָעִקָּר שֶׁמִּמֶּנּוּ הַתְחָלַת חֶשְׁבּוֹן זֶה הוּא מִתְּחִלַּת לֵיל חֲמִישִׁי שֶׁיּוֹמוֹ שְׁלִישִׁי לְחֹדֶשׁ נִיסָן מִשְּׁנַת תתקל\"ח וְאַרְבַּעַת אֲלָפִים לַיְצִירָה. וּמְקוֹם הַשֶּׁמֶשׁ בְּמַהֲלָכָהּ הָאֶמְצָעִי הָיָה בָּעִקָּר הַזֶּה בְּשֶׁבַע מַעֲלוֹת וּשְׁלֹשָׁה חֲלָקִים וְל\"ב שְׁנִיּוֹת מִמַּזַּל טָלֶה. סִימָנָן ז\"ג ל\"ב. וּמְקוֹם גֹּבַהּ הַשֶּׁמֶשׁ הָיָה בְּעִקָּר זֶה בְּכ\"ו מַעֲלוֹת מ\"ה חֲלָקִים וּשְׁמוֹנֶה שְׁנִיּוֹת מִמַּזַּל תְּאוֹמִים. סִימָנָם כ\"ו מ\"ה ח'. כְּשֶׁתִּרְצֶה לֵידַע מְקוֹם הַשֶּׁמֶשׁ בְּמַהֲלָכָהּ הָאֶמְצָעִי בְּכָל זְמַן שֶׁתִּרְצֶה. תִּקַּח מִנְיַן הַיָּמִים שֶׁמִּתְּחִלַּת יוֹם הָעִקָּר עַד הַיּוֹם שֶׁתִּרְצֶה. וְתוֹצִיא מַהֲלָכָהּ הָאֶמְצָעִי בְּאוֹתָן הַיָּמִים מִן הַסִּימָנִין שֶׁהוֹדַעְנוּ. וְהוֹסֵיף הַכּל עַל הָעִקָּר וּתְקַבֵּץ כָּל מִין עִם מִינוֹ. וְהַיּוֹצֵא הוּא מְקוֹם הַשֶּׁמֶשׁ בְּמַהֲלָכָהּ הָאֶמְצָעִי לְאוֹתוֹ הַיּוֹם. כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע מְקוֹם הַשֶּׁמֶשׁ הָאֶמְצָעִי בִּתְחִלַּת לֵיל הַשַּׁבָּת שֶׁיּוֹמוֹ אַרְבָּעָה עָשָׂר לְחֹדֶשׁ תַּמּוּז מִשָּׁנָה זוֹ שֶׁהִיא שְׁנַת הָעִקָּר. מָצָאנוּ מִנְיַן הַיָּמִים מִיּוֹם הָעִקָּר עַד תְּחִלַּת הַיּוֹם זֶה שֶׁאָנוּ רוֹצִים לֵידַע מְקוֹם הַשֶּׁמֶשׁ בּוֹ מֵאָה יוֹם. לָקַחְנוּ אֶמְצַע מַהֲלָכָהּ לְק' יוֹם שֶׁהוּא צ\"ח ל\"ג נ\"ג וְהוֹסַפְנוּ עַל הָעִקָּר שֶׁהוּא ז\"ג ל\"ב. יָצָא מִן הַחֶשְׁבּוֹן מֵאָה וְחָמֵשׁ מַעֲלוֹת וְל\"ז חֲלָקִים וְכ\"ה שְׁנִיּוֹת. סִימָנָן ק\"ה ל\"ז כ\"ה. וְנִמְצָא מְקוֹמָהּ בְּמַהֲלַךְ אֶמְצָעִי בִּתְחִלַּת לַיִל זֶה בְּמַזַּל סַרְטָן בְּט\"ו מַעֲלוֹת בּוֹ וְל\"ז חֲלָקִים מִמַּעֲלַת ט\"ז. וְהָאֶמְצָעִי שֶׁיָּצָא בְּחֶשְׁבּוֹן זֶה פְּעָמִים יִהְיֶה בִּתְחִלַּת הַלַּיְלָה בְּשָׁוֶה. אוֹ קֹדֶם שְׁקִיעַת הַחַמָּה בְּשָׁעָה. אוֹ אַחַר שְׁקִיעַת הַחַמָּה בְּשָׁעָה. וְדָבָר זֶה לֹא תָּחוּשׁ לוֹ בַּשֶּׁמֶשׁ בְּחֶשְׁבּוֹן הָרְאִיָּה. שֶׁהֲרֵי אָנוּ מַשְׁלִימִים קֵרוּב זֶה כְּשֶׁנַּחֲשֹׁב לְאֶמְצַע הַיָּרֵחַ. וְעַל הַדֶּרֶךְ הַזֹּאת תַּעֲשֶׂה תָּמִיד לְכָל עֵת שֶׁתִּרְצֶה וַאֲפִלּוּ אַחַר אֶלֶף שָׁנִים. שֶׁתְּקַבֵּץ כָּל הַשְּׁאֵרִית וְתוֹסִיף עַל הָעִקָּר יֵצֵא לְךָ הַמָּקוֹם הָאֶמְצָעִי. וְכֵן תַּעֲשֶׂה בְּאֶמְצַע הַיָּרֵחַ וּבְאֶמְצַע כָּל כּוֹכָב וְכוֹכָב. מֵאַחַר שֶׁתֵּדַע מַהֲלָכוֹ בְּיוֹם אֶחָד כַּמָּה הוּא וְתֵדַע הָעִקָּר שֶׁמִּמֶּנּוּ תַּתְחִיל. וּתְקַבֵּץ מַהֲלָכוֹ לְכָל הַשָּׁנִים וְהַיָּמִים שֶׁתִּרְצֶה וְתוֹסִיף עַל הָעִקָּר וְיֵצֵא לְךָ מְקוֹמוֹ בְּמַהֲלָךְ אֶמְצָעִי. וְכֵן תַּעֲשֶׂה בְּגֹבַהּ הַשֶּׁמֶשׁ תּוֹסִיף מַהֲלָכוֹ בְּאוֹתָם הַיָּמִים אוֹ הַשָּׁנִים עַל הָעִקָּר יֵצֵא לְךָ מְקוֹם גֹּבַהּ הַשֶּׁמֶשׁ לְאוֹתוֹ הַיּוֹם שֶׁתִּרְצֶה. וְכֵן אִם תִּרְצֶה לַעֲשׂוֹת עִקָּר אַחֵר שֶׁתַּתְחִיל מִמֶּנּוּ חוּץ מֵעִקָּר זֶה שֶׁהִתְחַלְנוּ מִמֶּנּוּ בְּשָׁנָה זוֹ. כְּדֵי שֶׁיִּהְיֶה אוֹתוֹ עִקָּר בִּתְחִלַּת שְׁנַת מַחֲזוֹר יָדוּעַ. אוֹ בִּתְחִלַּת מֵאָה מִן הַמֵּאוֹת. הָרְשׁוּת בְּיָדְךָ. וְאִם תִּרְצֶה לִהְיוֹת הָעִקָּר שֶׁתַּתְחִיל מִמֶּנּוּ מִשָּׁנִים שֶׁעָבְרוּ קֹדֶם עִקָּר זֶה אוֹ לְאַחַר כַּמָּה שָׁנִים מֵעִקָּר זֶה הַדֶּרֶךְ יְדוּעָה. כֵּיצַד הִיא הַדֶּרֶךְ. כְּבָר יָדַעְתָּ מַהֲלַךְ הַשֶּׁמֶשׁ לְשָׁנָה סְדוּרָה וּמַהֲלָכָהּ לְכ\"ט יוֹם וּמַהֲלָכָהּ לְיוֹם אֶחָד. וְדָבָר יָדוּעַ שֶׁהַשָּׁנָה שֶׁחֳדָשֶׁיהָ שְׁלֵמִים הִיא יְתֵרָה עַל הַסְּדוּרָה יוֹם אֶחָד. וְהַשָּׁנָה שֶׁחֳדָשֶׁיהָ חֲסֵרִין הִיא חֲסֵרָה מִן הַסְּדוּרָה יוֹם אֶחָד. וְהַשָּׁנָה הַמְעֻבֶּרֶת אִם יִהְיוּ חֳדָשֶׁיהָ כְּסִדְרָן תִּהְיֶה יְתֵרָה עַל הַשָּׁנָה הַסְּדוּרָה שְׁלֹשִׁים יוֹם. וְאִם יִהְיוּ חֳדָשֶׁיהָ שְׁלֵמִים הִיא יְתֵרָה עַל הַסְּדוּרָה ל\"א יוֹם. וְאִם יִהְיוּ חֳדָשֶׁיהָ חֲסֵרִין הִיא יְתֵרָה עַל הַסְּדוּרָה כ\"ט יוֹם. וּמֵאַחַר שֶׁכָּל הַדְּבָרִים הָאֵלּוּ יְדוּעִים תּוֹצִיא מַהֲלַךְ אֶמְצַע הַשֶּׁמֶשׁ לְכָל הַשָּׁנִים וְהַיָּמִים שֶׁתִּרְצֶה וְתוֹסִיף עַל הָעִקָּר שֶׁעָשִׂינוּ. יֵצֵא לְךָ אֶמְצָעָהּ לַיּוֹם שֶׁתִּרְצֶה מִשָּׁנִים הַבָּאוֹת. וְתַעֲשֶׂה אוֹתוֹ הַיּוֹם עִקָּר. אוֹ תִּגְרַע הָאֶמְצַע שֶׁהוֹצֵאתָ מִן הָעִקָּר שֶׁעָשִׂינוּ וְיֵצֵא לְךָ הָעִקָּר לַיּוֹם שֶׁתִּרְצֶה מִשָּׁנִים שֶׁעָבְרוּ. וְתַעֲשֶׂה אוֹתוֹ אֶמְצַע הָעִקָּר. וְכָזֶה תַּעֲשֶׂה בְּאֶמְצַע הַיָּרֵחַ וּשְׁאָר הַכּוֹכָבִים אִם יִהְיוּ יְדוּעִים לְךָ. וּכְבָר נִתְבָּאֵר לְךָ מִכְּלַל דְּבָרֵינוּ שֶׁכְּשֵׁם שֶׁתֵּדַע אֶמְצַע הַשֶּׁמֶשׁ לְכָל יוֹם שֶׁתִּרְצֶה מִיָּמִים הַבָּאִים כָּךְ תֵּדַע אֶמְצָעָהּ לְכָל יוֹם שֶׁתִּרְצֶה מִיָּמִים שֶׁעָבְרוּ:"],"Mishneh Torah, Sanctification of the New Month 6":["בִזְמַן שֶׁעוֹשִׂין עַל הָרְאִיָּה הָיוּ מְחַשְּׁבִין וְיוֹדְעִין שָׁעָה שֶׁיִּתְקַבֵּץ בּוֹ הַיָּרֵחַ עִם הַחַמָּה בְּדִקְדּוּק הַרְבֵּה כְּדֶרֶךְ שֶׁהָאִיצְטַגְנִינִין עוֹשִׂין. כְּדֵי לֵידַע אִם יֵרָאֶה הַיָּרֵחַ אוֹ לֹא יֵרָאֶה. וּתְחִלַּת אוֹתוֹ הַחֶשְׁבּוֹן הוּא הַחֶשְׁבּוֹן שֶׁמְּחַשְּׁבִין אוֹתוֹ בְּקֵרוּב וְיוֹדְעִין שְׁעַת קִבּוּצָם בְּלֹא דִּקְדּוּק אֶלָּא בְּמַהֲלָכָם הָאֶמְצָעִי הוּא הַנִּקְרָא מוֹלָד. וְעִקְּרֵי הַחֶשְׁבּוֹן שֶׁמְּחַשְּׁבִין בִּזְמַן שֶׁאֵין שָׁם בֵּית דִּין שֶׁיִּקְבְּעוּ בּוֹ עַל הָרְאִיָּה וְהוּא חֶשְׁבּוֹן שֶׁאָנוּ מְחַשְּׁבִין הַיּוֹם הוּא הַנִּקְרָא עִבּוּר:","הַיּוֹם וְהַלַּיְלָה אַרְבַּע וְעֶשְׂרִים שָׁעוֹת בְּכָל זְמַן. שְׁתֵּים עֶשְׂרֵה בַּיּוֹם וּשְׁתֵּים עֶשְׂרֵה בַּלַּיְלָה. וְהַשָּׁעָה מְחֻלֶּקֶת לְאֶלֶף וּשְׁמוֹנִים חֲלָקִים. וְלָמָּה חִלְּקוּ הַשָּׁעָה לְמִנְיָן זֶה. לְפִי שֶׁמִּנְיָן זֶה יֵשׁ בּוֹ חֲצִי וּרְבִיעַ וּשְׁמִינִית וּשְׁלִישׁ וּשְׁתוּת וְתֵשַׁע וְחֹמֶשׁ וְעִשּׂוּר. וְהַרְבֵּה חֲלָקִים יֵשׁ לְכָל אֵלּוּ הַשֵּׁמוֹת:","מִשֶּׁיִּתְקַבֵּץ הַיָּרֵחַ וְהַחַמָּה לְפִי חֶשְׁבּוֹן זֶה עַד שֶׁיִּתְקַבְּצוּ פַּעַם שְׁנִיָּה בְּמַהֲלָכָם הָאֶמְצָעִי. תִּשְׁעָה וְעֶשְׂרִים יוֹם וּשְׁתֵּים עֶשְׂרֵה שָׁעוֹת מִיּוֹם שְׁלֹשִׁים מִתְּחִלַּת לֵילוֹ. וּשְׁבַע מֵאוֹת וּשְׁלֹשָׁה וְתִשְׁעִים חֲלָקִים מִשְּׁעַת שְׁלֹשׁ עֶשְׂרֵה. וְזֶה הוּא הַזְּמַן שֶׁבֵּין כָּל מוֹלָד וּמוֹלָד וְזֶה הוּא חָדְשָׁהּ שֶׁל לְבָנָה:","שָׁנָה שֶׁל לְבָנָה אִם תִּהְיֶה שְׁנֵים עָשָׂר חֹדֶשׁ מֵחֳדָשִׁים אֵלּוּ יִהְיֶה כְּלָלָהּ שְׁלֹשׁ מֵאוֹת יוֹם וְאַרְבָּעָה וַחֲמִשִּׁים יוֹם וּשְׁמוֹנֶה שָׁעוֹת וּשְׁמוֹנֶה מֵאוֹת וְשִׁשָּׁה וְשִׁבְעִים חֲלָקִים. וְאִם תִּהְיֶה מְעֻבֶּרֶת וְתִהְיֶה הַשָּׁנָה שְׁלֹשָׁה עָשָׂר חֹדֶשׁ יִהְיֶה כְּלָלָהּ שְׁלֹשׁ מֵאוֹת וּשְׁמוֹנִים וּשְׁלֹשָׁה יוֹם וְאַחַת וְעֶשְׂרִים שָׁעוֹת וַחֲמֵשׁ מֵאוֹת וְתִשְׁעָה וּשְׁמוֹנִים חֲלָקִים. וּשְׁנַת הַחַמָּה הִיא שְׁלֹשׁ מֵאוֹת חֲמִשָּׁה וְשִׁשִּׁים יוֹם וְשֵׁשׁ שָׁעוֹת. נִמְצָא תּוֹסֶפֶת שְׁנַת הַחַמָּה עַל שְׁנַת הַלְּבָנָה עֲשָׂרָה יָמִים וְאַחַת וְעֶשְׂרִים שָׁעוֹת וּמָאתַיִם וְאַרְבָּעָה חֲלָקִים:","כְּשֶׁתַּשְׁלִיךְ יְמֵי חֹדֶשׁ הַלְּבָנָה שִׁבְעָה שִׁבְעָה שֶׁהֵן יְמֵי הַשָּׁבוּעַ. יִשָּׁאֵר יוֹם אֶחָד וּשְׁתֵּים עֶשְׂרֵה שָׁעוֹת וּשְׁבַע מֵאוֹת וּשְׁלֹשָׁה וְתִשְׁעִים חֲלָקִים. סִימָן לָהֶם אי\"ב תשצ\"ג. וְזוֹ הִיא שְׁאֵרִית חֹדֶשׁ הַלְּבָנָה. וְכֵן כְּשֶׁתַּשְׁלִיךְ יְמֵי שְׁנַת הַלְּבָנָה שִׁבְעָה שִׁבְעָה. אִם שָׁנָה פְּשׁוּטָה הִיא יִשָּׁאֵר מִמֶּנָּה אַרְבָּעָה יָמִים וּשְׁמוֹנֶה שָׁעוֹת וּשְׁמוֹנֶה מֵאוֹת וְשִׁשָּׁה וְשִׁבְעִים חֲלָקִים. סִימָן לָהֶם ד\"ח תתע\"ו. וְזוֹ הִיא שְׁאֵרִית שָׁנָה פְּשׁוּטָה. וְאִם שָׁנָה מְעֵבֶּרֶת הִיא תִּהְיֶה שְׁאֵרִיתָהּ חֲמִשָּׁה יָמִים וְאַחַת וְעֶשְׂרִים שָׁעוֹת וַחֲמֵשׁ מֵאוֹת וְתִשְׁעָה וּשְׁמוֹנִים חֲלָקִים. סִימָן לָהֶם הכ\"א תקפ\"ט:","כְּשֶׁיִּהְיֶה עִמְּךָ יָדוּעַ מוֹלַד חֹדֶשׁ מִן הֶחֳדָשִׁים וְתוֹסִיף עָלָיו אי\"ב תשצ\"ג יֵצֵא מוֹלָד שֶׁאַחֲרָיו. וְתֵדַע בְּאֵי זֶה יוֹם מִימֵי הַשָּׁבוּעַ וּבְאֵי זוֹ שָׁעָה וּבְכַמָּה חֲלָקִים יִהְיֶה:","כֵּיצַד. הֲרֵי שֶׁהָיָה מוֹלַד נִיסָן בְּאֶחָד בְּשַׁבָּת בְּחָמֵשׁ שָׁעוֹת בַּיּוֹם וּמֵאָה וְשִׁבְעָה חֲלָקִים סִימָן לָהֶם אהק\"ז. כְּשֶׁתּוֹסִיף עָלָיו שְׁאֵרִית חֹדֶשׁ הַלְּבָנָה וְהוּא אי\"ב תשצ\"ג. יֵצֵא מוֹלַד אִיָּר בְּלֵיל שְׁלִישִׁי חָמֵשׁ שָׁעוֹת בַּלַּיְלָה וּתְשַׁע מֵאוֹת חֲלָקִים. סִימָן לָהֶם ג\"ה תת\"ק. וְעַל דֶּרֶךְ זוֹ עַד סוֹף הָעוֹלָם חֹדֶשׁ אַחַר חֹדֶשׁ:","וְכֵן כְּשֶׁיִּהְיֶה עִמְּךָ יָדוּעַ מוֹלַד שָׁנָה זוֹ וְתוֹסִיף שְׁאֵרִיתָהּ עַל יְמֵי הַמּוֹלָד. אִם פְּשׁוּטָה הִיא שְׁאֵרִית הַפְּשׁוּטָה וְאִם מְעֻבֶּרֶת הִיא שְׁאֵרִית הַמְעֻבֶּרֶת. יֵצֵא לְךָ מוֹלַד שָׁנָה שֶׁלְּאַחֲרֶיהָ. וְכֵן שָׁנָה אַחַר שָׁנָה עַד סוֹף הָעוֹלָם. וְהַמּוֹלָד הָרִאשׁוֹן שֶׁמִּמֶּנּוּ תַּתְחִיל הוּא מוֹלַד שֶׁהָיָה בַּשָּׁנָה הָרִאשׁוֹנָה שֶׁל יְצִירָה. וְהוּא הָיָה בְּלֵיל שֵׁנִי חָמֵשׁ שָׁעוֹת בַּלַּיְלָה וּמָאתַיִם וְאַרְבָּעָה חֲלָקִים. סִימָן לָהֶם בהר\"ד וּמִמֶּנּוּ הוּא תְּחִלַּת הַחֶשְׁבּוֹן:","בְּכָל הַחֶשְׁבּוֹנוֹת הָאֵלּוּ שֶׁתֵּדַע מֵהֶן הַמּוֹלָד. כְּשֶׁתּוֹסִיף שְׁאֵרִית עִם שְׁאֵרִית. כְּשֶׁיִּתְקַבֵּץ מִן הַחֲלָקִים אֶלֶף וּשְׁמוֹנִים תַּשְׁלִים שָׁעָה אַחַת וְתוֹסִיף אוֹתָהּ לְמִנְיַן הַשָּׁעוֹת. וּכְשֶׁיִּתְקַבֵּץ מִן הַשָּׁעוֹת אַרְבַּע וְעֶשְׂרִים תַּשְׁלִים יוֹם וְתוֹסִיף מִמֶּנּוּ לְמִנְיַן הַיָּמִים. וּכְשֶׁיִּתְקַבֵּץ מִן הַיָּמִים יוֹתֵר עַל שִׁבְעָה תַּשְׁלִיךְ שִׁבְעָה מִן הַמִּנְיָן וְתַנִּיחַ הַשְּׁאָר. שֶׁאֵין אָנוּ מְחַשְּׁבִין לֵידַע מִנְיַן הַיָּמִים אֶלָּא לֵידַע בְּאֵי זֶה יוֹם מִימֵי הַשָּׁבוּעַ וּבְאֵי זֶה שָׁעָה וְאֵי זֶה חֵלֶק יִהְיֶה הַמּוֹלָד:","כָּל תְּשַׁע עֶשְׂרֵה שָׁנָה שֶׁיִּהְיוּ מֵהֶן שֶׁבַע שָׁנִים מְעֵבָּרוֹת וּשְׁתֵּים עֶשְׂרֵה פְּשׁוּטוֹת נִקְרָא מַחֲזוֹר. וְלָמָּה סָמַכְנוּ עַל מִנְיָן זֶה. שֶׁבִּזְמַן שֶׁאַתָּה מְקַבֵּץ מִנְיַן יְמֵי שְׁתֵּים עֶשְׂרֵה שָׁנָה פְּשׁוּטוֹת וְשֶׁבַע מְעֵבָּרוֹת וּשְׁעוֹתֵיהֶן וְחֶלְקֵיהֶן וְתַשְׁלִים כָּל אֶלֶף וּשְׁמֹנִים חֲלָקִים שָׁעָה. וְכָל אַרְבַּע וְעֶשְׂרִים שָׁעוֹת יוֹם. וְתוֹסִיף לְמִנְיַן הַיָּמִים. תִּמְצָא הַכּל תְּשַׁע עֶשְׂרֵה שָׁנָה מִשְּׁנֵי הַחַמָּה שֶׁכָּל שָׁנָה מֵהֶן שְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִּׁים יוֹם וְשֵׁשׁ שָׁעוֹת בְּשָׁוֶה. וְלֹא יִשָּׁאֵר מִמִּנְיַן יְמֵי הַחַמָּה בְּכָל תְּשַׁע עֶשְׂרֵה שָׁנָה חוּץ מִשָּׁעָה אַחַת וְאַרְבַּע מֵאוֹת וּשְׁמוֹנִים וַחֲמִשָּׁה חֲלָקִים. סִימָן לָהֶם אתפ\"ה:","נִמְצָא בְּמַחֲזוֹר שֶׁהוּא כָּזֶה הֶחֳדָשִׁים כֻּלָּם חָדְשֵׁי הַלְּבָנָה וְהַשָּׁנִים שְׁנֵי הַחַמָּה. וְהַשֶּׁבַע שָׁנִים הַמְעֻבָּרוֹת שֶׁבְּכָל מַחֲזוֹר וּמַחֲזוֹר לְפִי חֶשְׁבּוֹן זֶה הֵם שָׁנָה שְׁלִישִׁית מִן הַמַּחֲזוֹר וְשִׁשִּׁית וּשְׁמִינִית וּשְׁנַת אַחַת עֶשְׂרֵה וּשְׁנַת אַרְבַּע עֶשְׂרֵה וּשְׁנַת שְׁבַע עֶשְׂרֵה וּשְׁנַת י\"ט. סִימָן לָהֶם גו\"ח י\"א י\"ד י\"ז י\"ט:","כְּשֶׁתְּקַבֵּץ שְׁאֵרִית כָּל שָׁנָה מִשְּׁתֵּים עֶשְׂרֵה שָׁנָה הַפְּשׁוּטוֹת שֶׁהִיא ד\"ח תתע\"ו. וּשְׁאֵרִית כָּל שָׁנָה מִשֶּׁבַע שָׁנִים הַמְעֻבָּרוֹת שֶׁהִיא הכ\"א תקפ\"ט. וְתַשְׁלִיךְ הַכּל שִׁבְעָה שִׁבְעָה יִשָּׁאֵר שְׁנֵי יָמִים וְשֵׁשׁ עֶשְׂרֵה שָׁעוֹת וַחֲמֵשׁ מֵאוֹת וַחֲמִשָּׁה וְתִשְׁעִים חֲלָקִים. סִימָן לָהֶם בי\"ו תקצ\"ה. וְזֶה הוּא שְׁאֵרִית הַמַּחֲזוֹר:","כְּשֶׁיִּהְיֶה לְךָ יָדוּעַ מוֹלַד תְּחִלַּת מַחֲזוֹר וְתוֹסִיף עָלָיו בי\"ו תקצ\"ה. יָצָא לְךָ תְּחִלַּת הַמַּחֲזוֹר שֶׁאַחֲרָיו וְכֵן מוֹלַד כָּל מַחֲזוֹר וּמַחֲזוֹר עַד סוֹף הָעוֹלָם. וּכְבָר אָמַרְנוּ שֶׁמּוֹלַד תְּחִלַּת הַמַּחֲזוֹר הָרִאשׁוֹן הָיָה לבהר\"ד. וּמוֹלַד הַשָּׁנָה הוּא מוֹלַד תִּשְׁרֵי שֶׁל אוֹתָהּ הַשָּׁנָה:","וּבַדֶּרֶךְ הַזֹּאת תֵּדַע מוֹלַד כָּל שָׁנָה וְשָׁנָה שֶׁתִּרְצֶה. וּמוֹלַד כָּל חֹדֶשׁ וְחֹדֶשׁ שֶׁתִּרְצֶה. מִשָּׁנִים שֶׁעָבְרוּ אוֹ מִשָּׁנִים שֶׁעֲתִידִים לָבֹא. כֵּיצַד. תִּקַּח שְׁנֵי יְצִירָה שֶׁעָבְרוּ וְגָמְרוּ וְתַעֲשֶׂה אוֹתָם מַחֲזוֹרִין שֶׁל תְּשַׁע עֶשְׂרֵה תְּשַׁע עֶשְׂרֵה שָׁנָה עַד תִּשְׁרֵי שֶׁל אוֹתָהּ הַשָּׁנָה. וְתֵדַע מִנְיַן הַמַּחֲזוֹרִין שֶׁעָבְרוּ וּמִנְיַן הַשָּׁנִים שֶׁעָבְרוּ מִמַּחֲזוֹר שֶׁעֲדַיִן לֹא נִשְׁלַם. וְתִקַּח לְכָל מַחֲזוֹר וּמַחֲזוֹר בי\"ו תקצ\"ה. וּלְכָל שָׁנָה וְשָׁנָה פְּשׁוּטָה מִשְּׁנֵי הַמַּחֲזוֹר שֶׁלֹּא נִשְׁלַם ד\"ח תתע\"ו. וּלְכָל שָׁנָה מְעֵבֶּרֶת הכ\"א תקפ\"ט. וּתְקַבֵּץ הַכּל וְתַשְׁלִים הַחֲלָקִים שָׁעוֹת. וְתַשְׁלִים הַשָּׁעוֹת יָמִים. וְהַיָּמִים תַּשְׁלִיכֵם שִׁבְעָה שִׁבְעָה. וְהַנִּשְׁאָר מִן הַיָּמִים וּמִן הַשָּׁעוֹת וְהַחֲלָקִים הוּא מוֹלַד שָׁנָה הַבָּאָה שֶׁתִּרְצֶה לֵידַע מוֹלָדָהּ:","מוֹלַד הַשָּׁנָה שֶׁיֵּצֵא בְּחֶשְׁבּוֹן זֶה הוּא מוֹלַד רֹאשׁ חֹדֶשׁ תִּשְׁרֵי. וּכְשֶׁתּוֹסִיף עָלָיו אי\"ב תשצ\"ג יֵצֵא מוֹלַד מַרְחֶשְׁוָן. וּכְשֶׁתּוֹסִיף עַל מַרְחֶשְׁוָן אי\"ב תשצ\"ג יֵצֵא מוֹלַד כִּסְלֵו. וְכֵן לְכָל חֹדֶשׁ וְחֹדֶשׁ זֶה אַחַר זֶה עַד סוֹף הָעוֹלָם:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 3":["הָאוֹכֵל מַעֲשֵׂר שֵׁנִי בְּטֻמְאָה לוֹקֶה שֶׁנֶּאֱמַר (דברים כו יד) \"וְלֹא בִעַרְתִּי מִמֶּנּוּ בְּטָמֵא\". בֵּין שֶׁהַמַּעֲשֵׂר טָמֵא וְהָאוֹכֵל טָהוֹר. בֵּין שֶׁהַמַּעֲשֵׂר טָהוֹר וְהָאוֹכֵל טָמֵא. וְהוּא שֶׁיֹּאכְלֶנּוּ בִּירוּשָׁלַיִם קֹדֶם שֶׁיִּפָּדֶה. שֶׁאֵינוֹ לוֹקֶה עַל אֲכִילָתוֹ בְּטֻמְאָה אֶלָּא בִּמְקוֹם אֲכִילָתוֹ. אֲבָל אִם אֲכָלוֹ בְּטֻמְאָה חוּץ לִירוּשָׁלַיִם מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וַאֲפִלּוּ לְהַדְלִיק [בּוֹ] אֶת הַנֵּר אַחַר שֶׁנִּטְמָא אָסוּר עַד שֶׁיִּפָּדֶה שֶׁנֶּאֱמַר (דברים כו יד) \"לֹא בִעַרְתִּי מִמֶּנּוּ בְּטָמֵא\":","כְּבָר בֵּאַרְנוּ שֶׁהַמַּעֲשֵׂר שֶׁנִּטְמָא אֲפִלּוּ בִּירוּשָׁלַיִם פּוֹדִין וְיֵאָכֵל. וְאוֹכְלִין אֶת דָּמָיו בְּטָהֳרָה בְּתוֹרַת פֵּרוֹת מַעֲשֵׂר כְּמוֹ שֶׁיִּתְבָּאֵר. אֲפִלּוּ נִטְמְאוּ הַפֵּרוֹת כֻּלָּן כְּשֶׁהֵן טֶבֶל מַפְרִישׁ מַעֲשֵׂר שֵׁנִי בְּטֻמְאָה וּפוֹדֵהוּ:","הֶעָרֵל כְּטָמֵא וְאִם אָכַל מַעֲשֵׂר שֵׁנִי לוֹקֶה מִן הַתּוֹרָה כְּדֶרֶךְ שֶׁלּוֹקֶה עַל אֲכִילַת תְּרוּמָה. שֶׁהַתְּרוּמָה קְרוּיָה קֹדֶשׁ וּמַעֲשֵׂר שֵׁנִי קָרוּי קֹדֶשׁ שֶׁהֲרֵי נֶאֱמַר בּוֹ (ויקרא כז ל) \"קֹדֶשׁ לַה'\". וְטָמֵא שֶׁטָּבַל אוֹכֵל מַעֲשֵׂר שֵׁנִי אַף עַל פִּי שֶׁלֹּא הֶעֱרִיב שִׁמְשׁוֹ:","הָאוֹכֵל מַעֲשֵׂר שֵׁנִי בַּאֲנִינוּת שֶׁל תּוֹרָה לוֹקֶה שֶׁנֶּאֱמַר (דברים כו יד) \"לֹא אָכַלְתִּי בְאֹנִי מִמֶּנּוּ\". וְהוּא שֶׁיֹּאכְלֶנּוּ בְּמָקוֹם אֲכִילָתוֹ בִּירוּשָׁלַיִם. אֲבָל אִם אֲכָלוֹ בַּחוּץ בַּאֲנִינוּת. אוֹ שֶׁאֲכָלוֹ בִּפְנִים בַּאֲנִינוּת שֶׁל דִּבְרֵיהֶם. מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אֵיזֶהוּ אוֹנֵן זֶה הַמִּתְאַבֵּל עַל אֶחָד מִן הַקְּרוֹבִים שֶׁהוּא חַיָּב לְהִתְאַבֵּל עֲלֵיהֶן. וּבְיוֹם הַמִּיתָה הוּא אוֹנֵן מִן הַתּוֹרָה וּבַלַּיְלָה אוֹנֵן מִדִּבְרֵיהֶן שֶׁנֶּאֱמַר (ויקרא י יט) \"וְאָכַלְתִּי חַטָּאת הַיּוֹם הַיִּיטַב בְּעֵינֵי ה'\". הַיּוֹם אָסוּר וְלַיְלָה מֻתָּר. נִשְׁתַּהָה הַמֵּת יָמִים רַבִּים וְאַחַר כָּךְ נִקְבַּר. כָּל אוֹתָן הַיָּמִים שֶׁאַחַר יוֹם הַמִּיתָה עַד יוֹם הַקְּבוּרָה הוּא אוֹנֵן מִדִּבְרֵיהֶן. וְאֵין יוֹם הַקְּבוּרָה תּוֹפֵשׂ לֵילוֹ:","וְלֹא מַעֲשֵׂר שֵׁנִי בִּלְבַד אֶלָּא כָּל הַקָּדָשִׁים כֻּלָּן אִם אֲכָלָן בַּאֲנִינוּת שֶׁל תּוֹרָה לוֹקֶה. וּבַאֲנִינוּת שֶׁל דִּבְרֵיהֶן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אֵין נוֹתְנִין פֵּרוֹת מַעֲשֵׂר שֵׁנִי לְעַם הָאָרֶץ וְלֹא פֵּרוֹת הַנִּלְקָחוֹת בִּמְעוֹת מַעֲשֵׂר וְלֹא מְעוֹת מַעֲשֵׂר מִפְּנֵי שֶׁהוּא בְּחֶזְקַת טֻמְאָה. וּמֻתָּר לֶאֱכל מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי בַּאֲנִינוּת וְלִתְּנוֹ לְעַם הָאָרֶץ וְהוּא שֶׁיֹּאכַל כְּנֶגְדּוֹ. אֵין מַפְקִידִין מַעֲשֵׂר שֵׁנִי אֲפִלּוּ אֵצֶל חָבֵר שֶׁמָּא יָמוּת וְנִמְצָא הַמַּעֲשֵׂר תַּחַת יַד בְּנוֹ עַם הָאָרֶץ. אֲבָל מַפְקִידִים מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי אֵצֶל עַם הָאָרֶץ:","מַעֲשֵׂר שֵׁנִי אָסוּר לְאַבֵּד אֲפִלּוּ מִעוּטוֹ בַּדְּרָכִים. אֶלָּא מוֹלִיכוֹ כָּל שֶׁהוּא אוֹ מוֹלִיךְ דָּמָיו לִירוּשָׁלַיִם. וּמֻתָּר לְאַבֵּד מִעוּט מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי בַּדְּרָכִים. וְכַמָּה הִיא מִעוּט פָּחוֹת מִכִּגְרוֹגֶרֶת בֵּין בְּאֹכֶל שָׁלֵם בֵּין בְּפָרוּס. אֲבָל כִּגְרוֹגֶרֶת אֵין מְאַבְּדִין אוֹתוֹ. וְהַמַּפְרִישׁ מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי פָּחוֹת מִכִּגְרוֹגֶרֶת הֲרֵי זֶה נוֹתְנוֹ לְעַם הָאָרֶץ וְאוֹכֵל כְּנֶגְדּוֹ אֲבָל לֹא יַפְרִישֶׁנּוּ לְכַתְּחִלָּה לְאַבְּדוֹ שֶׁאֵין מַפְרִישִׁין לְאַבֵּד:","מַעֲשֵׂר שֵׁנִי נִתָּן לַאֲכִילָה וּשְׁתִיָּה שֶׁנֶּאֱמַר (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\". וְסִיכָה כִּשְׁתִיָּה. וְאָסוּר לְהוֹצִיאוֹ בִּשְׁאָר צְרָכָיו כְּגוֹן לִקַּח בּוֹ כֵּלִים וּבְגָדִים וַעֲבָדִים שֶׁנֶּאֱמַר (דברים כו יד) \"לֹא נָתַתִּי מִמֶּנּוּ לְמֵת\" כְּלוֹמַר לֹא הוֹצֵאתִי אוֹתוֹ בְּדָבָר שֶׁאֵינוֹ מְקַיֵּם אֶת הַגּוּף. וְאִם הוֹצִיא מִמֶּנּוּ בִּשְׁאָר דְּבָרִים אֲפִלּוּ בִּדְבַר מִצְוָה כְּגוֹן שֶׁלָּקַח מִמֶּנּוּ אָרוֹן וְתַכְרִיכִין לְמֵת מִצְוָה הֲרֵי זֶה אוֹכֵל כְּנֶגְדּוֹ בְּתוֹרַת מַעֲשֵׂר:","מַעֲשֵׂר אוֹכֵל דָּבָר שֶׁדַּרְכּוֹ לְהֵאָכֵל וְשׁוֹתֶה דָּבָר שֶׁדַּרְכּוֹ לִשְׁתּוֹת וְסָךְ דָּבָר שֶׁדַּרְכּוֹ לָסוּךְ. וְלֹא יָסוּךְ יַיִן וְחֹמֶץ אֲבָל סָךְ הוּא אֶת הַשֶּׁמֶן. וְלֹא יִסְחֹט אֶת הַפֵּרוֹת לְהוֹצִיא מֵהֶן מַשְׁקִין חוּץ מִזֵּיתִים וַעֲנָבִים בִּלְבַד. [וְאֵין מְפַטְּמִין אֶת הַשֶּׁמֶן אֲבָל מְפַטְּמִין אֶת הַיַּיִן]. וְאֵין מְחַיְּבִין אוֹתוֹ לֶאֱכל פַּת שֶׁעִפְּשָׁה וְשֶׁמֶן שֶׁנִּסְרַח. אֶלָּא כֵּיוָן שֶׁנִּפְסַל מֵאֹכֶל אָדָם פָּקְעָה קְדֻשָּׁה מִמֶּנּוּ:","כָּל שֶׁמֻּתָּר לְזָרִים לְאָכְלוֹ בִּתְרוּמָה כָּךְ מֻתָּר בְּמַעֲשֵׂר שֵׁנִי לְאָכְלוֹ בְּתוֹרַת חֻלִּין. שְׁמָרִים שֶׁל מַעֲשֵׂר שֵׁנִי שֶׁנָּתַן עֲלֵיהֶם מַיִם. רִאשׁוֹן אָסוּר כְּמַעֲשֵׂר וְשֵׁנִי מֻתָּר כְּחֻלִּין. וְשֶׁל דְּמַאי אֲפִלּוּ רִאשׁוֹן מֻתָּר:","יַיִן שֶׁל מַעֲשֵׂר שֶׁנָּפַל לְתוֹכוֹ דְּבַשׁ וְהַתַּבְלִין וְהִשְׁבִּיחוּ הַשֶּׁבַח לְפִי חֶשְׁבּוֹן. וְכֵן דָּגִים שֶׁנִּתְבַּשְּׁלוּ עִם קַפְלוֹטוֹת שֶׁל מַעֲשֵׂר שֵׁנִי וְהִשְׁבִּיחוּ הַשֶּׁבַח לְפִי חֶשְׁבּוֹן:","עִסָּה שֶׁל מַעֲשֵׂר שֵׁנִי שֶׁאֲפָאָהּ וְהִשְׁבִּיחָה הַשֶּׁבַח לַשֵּׁנִי. זֶה הַכְּלָל כָּל שֶׁשִּׁבְחוֹ נִכָּר אִם הוֹתִיר בְּמִדָּה הַשֶּׁבַח לְפִי חֶשְׁבּוֹן. וְאִם לֹא הוֹתִיר הַמִּדָּה הַשֶּׁבַח לַשֵּׁנִי בִּלְבַד. וְכָל שֶׁאֵין שִׁבְחוֹ נִכָּר אֲפִלּוּ הוֹתִיר הַמִּדָּה הַשֶּׁבַח לַשֵּׁנִי בִּלְבַד:","כֵּיצַד הַשֶּׁבַח. לְפִי חֶשְׁבּוֹן. יַיִן שֶׁל מַעֲשֵׂר שֶׁשָּׁוֶה שְׁלֹשָׁה שֶׁנָּפַל לְתוֹכוֹ דְּבַשׁ וְתַבְלִין שָׁוֶה זוּז אֶחָד וְהוֹסִיפָה בְּמִדָּתוֹ וְהִשְׁבִּיחוּהוּ וַהֲרֵי הַכּל שָׁוֶה חֲמִשָּׁה חוֹשְבִין הַכּל בְּאַרְבָּעָה וּרְבִיעַ. וְכֵן עַל דֶּרֶךְ זֶה בִּשְׁאָר הַדְּבָרִים:","מַעֲשֵׂר שֵׁנִי אַף עַל פִּי שֶׁנִּתָּן לְסִיכָה אֵין נוֹתְנִין אוֹתוֹ לֹא עַל גַּבֵּי צִינִית וְלֹא עַל גַּבֵּי חֲזָזִית. וְאֵין עוֹשִׂין מִמֶּנּוּ קָמֵעַ וְכַיּוֹצֵא בּוֹ שֶׁהֲרֵי לֹא נִתַּן לִרְפוּאָה:","מַעֲשֵׂר שֵׁנִי מָמוֹן גָּבוֹהַּ הוּא שֶׁנֶּאֱמַר (ויקרא כז ל) \"לַה' הוּא\". לְפִיכָךְ אֵינוֹ נִקְנֶה בְּמַתָּנָה אֶלָּא אִם כֵּן נָתַן לוֹ הַטֶּבֶל וְהַמְקַבֵּל מַפְרִישׁ הַמַּעֲשֵׂר. וְאֵין מְקַדְּשִׁין בּוֹ אֶת הָאִשָּׁה וְאֵין מוֹכְרִין אוֹתוֹ וְאֵין מְמַשְׁכְּנִין אוֹתוֹ וְאֵין מַחְלִיפִין אוֹתוֹ וְאֵין מַרְהִינִין אוֹתוֹ:","כֵּיצַד אֵין מְמַשְׁכְּנִין אוֹתוֹ. לֹא יִכָּנֵס לְבֵיתוֹ וִימַשְׁכְּנֶנּוּ מַעֲשֵׂר שֵׁנִי שֶׁלּוֹ. עָבַר וּמִשְׁכְּנוֹ מוֹצִיאִין אוֹתוֹ מִיָּדוֹ. כֵּיצַד אֵין מַרְהִינִין אוֹתוֹ. לֹא יֹאמַר לוֹ הֵא לְךָ מַעֲשֵׂר זֶה וְיִהְיֶה בְּיָדְךָ וְתֵן לִי עָלָיו מָעוֹת. כֵּיצַד אֵין מַחְלִיפִין אוֹתוֹ. לֹא יֹאמַר לוֹ הֵא לְךָ יֵין מַעֲשֵׂר וְתֵן לִי שֶׁמֶן מַעֲשֵׂר. אֲבָל אוֹמֵר לוֹ הֵא לְךָ יַיִן שֶׁאֵין לִי שֶׁמֶן וְאִם רָצָה חֲבֵרוֹ לִתֵּן לוֹ שֶׁמֶן מֻתָּר שֶׁהֲרֵי לֹא הֶחֱלִיף עִמּוֹ אֶלָּא הוֹדִיעוֹ שֶׁאֵין לוֹ וְאִם רָצָה הַלָּה לִתֵּן יִתֵּן:","מַעֲשֵׂר שֵׁנִי אֵין שׁוֹקְלִין כְּנֶגְדּוֹ אֲפִלּוּ דִּינְרֵי זָהָב. וַאֲפִלּוּ לְחַלֵּל עֲלֵיהֶם מַעֲשֵׂר שֵׁנִי אַחֵר גְּזֵרָה שֶׁמָּא לֹא יְכַוֵּן מִמֶּנּוּ מִשְׁקָלוֹ וְנִמְצְאוּ הַפֵּרוֹת חֲסֵרִים וְהוּא שׁוֹקֵל בָּהֶן מָעוֹת לְחַלֵּל עֲלֵיהֶם מַעֲשֵׂר אַחֵר נִמְצָא מוֹצִיא מַעֲשֵׂר לְחֻלִּין בְּפָחוֹת בְּדָמָיו:","הָאַחִים שֶׁחָלְקוּ מַעֲשֵׂר שֵׁנִי אֵין שׁוֹקְלִין זֶה כְּנֶגֶד זֶה וְכֵן מְעוֹת מַעֲשֵׂר שֵׁנִי אֵין שׁוֹקְלִים כְּנֶגְדָּן וְאֵין מוֹכְרִין אוֹתָם וְאֵין מַחְלִיפִין וְלֹא מַרְהִינִין. וְלֹא יִתְּנֵם לְשֻׁלְחָנִי לְהִתְנָאוֹת בָּהֶן וְלֹא יַלְוֶה אוֹתָן לְהִתְגַּדֵּל בָּהֶן. וְאִם הִלְוָן שֶׁלֹּא יַעֲלֶה חֲלֻדָּה מֻתָּר:","וְאֵין פּוֹרְעִין מֵהֶם אֶת הַמִּלְוֶה. אֵין עוֹשִׂין מֵהֶן שׁוֹשְׁבִינוּת וְאֵין מְשַׁלְּמִין מֵהֶן הַגְּמוּלִין. וְאֵין פּוֹסְקִין מֵהֶם צְדָקָה בְּבֵית הַכְּנֶסֶת. אֲבָל מְשַׁלְּמִין מֵהֶן דְּבָרִים שֶׁהֵן גְּמִילוּת חֲסָדִים. וְצָרִיךְ לְהוֹדִיעַ:","לֹא יֹאמַר אָדָם לַחֲבֵרוֹ הַעַל אֶת הַפֵּרוֹת הָאֵלּוּ לִירוּשָׁלַיִם וְטל מֵהֶן חֶלְקְךָ שֶׁנִּמְצָא זֶה כְּנוֹטֵל שָׂכָר מִמַּעֲשֵׂר שֵׁנִי עַל הֲבָאָתוֹ לִירוּשָׁלַיִם. אֲבָל אוֹמֵר לוֹ הַעְלֵם שֶׁנֹּאכְלֵם וְשֶׁנִּשְׁתֵּם בִּירוּשָׁלַיִם:","אוֹמֵר אָדָם לַחֲבֵרוֹ בִּירוּשָׁלַיִם לָסוּךְ אוֹתוֹ בְּשֶׁמֶן מַעֲשֵׂר שֵׁנִי אַף עַל פִּי שֶׁנִּסּוֹכָה יָדוֹ וְאֵין זֶה בִּשְׂכַר סִיכָתוֹ:","כְּבָר בֵּאַרְנוּ שֶׁהַמַּעֲשֵׂר מָמוֹן גָּבוֹהַּ הוּא. לְפִיכָךְ אָנוּ אוֹמְרִים שֶׁהַגּוֹנֵב מַעֲשֵׂר שֵׁנִי אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְהַגּוֹזְלוֹ אֵינוֹ מְשַׁלֵּם חֹמֶשׁ:","הַמַּקְדִּישׁ מַעֲשֵׂר שֵׁנִי שֶׁלּוֹ לְבֶדֶק הַבַּיִת הֲרֵי זֶה פּוֹדֶה אוֹתוֹ מִי שֶׁפּוֹדֵהוּ עַל מְנָת לִתֵּן לַהֶקְדֵּשׁ אֶת שֶׁלּוֹ וּלְמַעֲשֵׂר שֵׁנִי אֶת שֶׁלּוֹ:"],"Mishneh Torah, Sheqel Dues 1":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לִתֵּן כָּל אִישׁ מִיִּשְׂרָאֵל מַחֲצִית הַשֶּׁקֶל בְּכָל שָׁנָה וְשָׁנָה. אֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב. וְשׁוֹאֵל מֵאֲחֵרִים אוֹ מוֹכֵר כְּסוּת שֶׁעַל כְּתֵפוֹ וְנוֹתֵן מַחֲצִית הַשֶּׁקֶל כֶּסֶף שֶׁנֶּאֱמַר (שמות ל טו) \"הֶעָשִׁיר לֹא יַרְבֶּה וְהַדַּל לֹא יַמְעִיט\" וְגוֹ'. וְאֵינוֹ נוֹתְנוֹ בִּפְעָמִים רַבּוֹת הַיּוֹם מְעַט וּלְמָחָר מְעַט אֶלָּא נוֹתְנוֹ כֻּלּוֹ כְּאַחַת בְּפַעַם אַחַת:","מִנְיַן כֶּסֶף הָאָמוּר בַּתּוֹרָה בְּאוֹנֵס וּבִמְפַתֶּה וּבְמוֹצִיא שֵׁם רַע וְהוֹרֵג עֶבֶד הוּא כֶּסֶף הוּא שֶׁקֶל הַנֶּאֱמָר בְּכָל מָקוֹם בַּתּוֹרָה. וּמִשְׁקָלוֹ שְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים שְׂעוֹרָה. וּכְבָר הוֹסִיפוּ חֲכָמִים עָלָיו וְעָשׂוּ מִשְׁקָלוֹ כְּמִשְׁקַל הַמַּטְבֵּעַ הַנִּקְרָא סֶלַע בִּזְמַן בַּיִת שֵׁנִי. וְכַמָּה הוּא מִשְׁקַל הַסֶּלַע שְׁלֹשׁ מֵאוֹת וְאַרְבַּע וּשְׁמוֹנִים שְׂעוֹרָה בֵּינוֹנִית:","הַסֶּלַע אַרְבָּעָה דִּינָרִין וְהַדִּינָר שֵׁשׁ מָעִין. וּמָעָה הִיא הַנִּקְרֵאת בִּימֵי משֶׁה רַבֵּנוּ גֵּרָה. וּמָעָה הִיא שְׁנֵי פּוּנְדְיוֹנִין וּפוּנְדְיוֹן שְׁנֵי אִיסָרִין. וּפְרוּטָה אַחַת מִשְּׁמוֹנָה בְּאִיסָר. נִמְצָא מִשְׁקַל הַמָּעָה וְהִיא הַגֵּרָה שֵׁשׁ עֶשְׂרֵה שְׂעוֹרוֹת. וּמִשְׁקַל הָאִיסָר אַרְבַּע שְׂעוֹרוֹת. וּמִשְׁקַל הַפְּרוּטָה חֲצִי שְׂעוֹרָה:","וְעוֹד מַטְבֵּעַ אַחֵר הָיָה שָׁם שֶׁהָיָה מִשְׁקָלוֹ שְׁתֵּי סְלָעִים וְהוּא הָיָה נִקְרָא דַּרְכּוֹן. וְאֵלּוּ הַמַּטְבְּעוֹת כֻּלָּן שֶׁאָמַרְנוּ וּבֵאַרְנוּ מִשְׁקַל כָּל אֶחָד מֵהֶן הֵן שֶׁמְּשַׁעֲרִין בָּהֶן בְּכָל מָקוֹם. וּכְבָר בֵּאַרְנוּם כְּדֵי שֶׁלֹּא אֶהְיֶה צָרִיךְ לְפָרֵשׁ מִשְׁקָלָם בְּכָל מָקוֹם:","מַחֲצִית הַשֶּׁקֶל זוֹ מִצְוָתָהּ שֶׁיִּתֵּן מַחֲצִית מַטְבֵּעַ שֶׁל אוֹתוֹ הַזְּמַן אֲפִלּוּ הָיָה אוֹתוֹ מַטְבֵּעַ גָּדוֹל מִשֶּׁקֶל הַקֹּדֶשׁ. וּלְעוֹלָם אֵינוֹ שׁוֹקֵל פָּחוֹת מֵחֲצִי הַשֶּׁקֶל שֶׁהָיָה בִּימֵי משֶׁה רַבֵּנוּ שֶׁהוּא מִשְׁקָלוֹ מֵאָה וְשִׁשִּׁים שְׂעוֹרָה:","בִּזְמַן שֶׁהָיָה מַטְבֵּעַ שֶׁל אוֹתוֹ זְמַן דַּרְכּוֹנוֹת הָיָה כָּל אֶחָד וְאֶחָד נוֹתֵן בְּמַחֲצִית הַשֶּׁקֶל שֶׁלּוֹ סֶלַע. וּבִזְמַן שֶׁהָיָה הַמַּטְבֵּעַ סְלָעִים הָיָה נוֹתֵן כָּל אֶחָד בְּמַחֲצִית הַשֶּׁקֶל שֶׁלּוֹ חֲצִי סֶלַע שֶׁהוּא שְׁנֵי דִּינָרִין. וּבִזְמַן שֶׁהָיָה הַמַּטְבֵּעַ חֲצִי סֶלַע הָיָה כָּל אֶחָד וְאֶחָד נוֹתֵן בְּמַחֲצִית הַשֶּׁקֶל אוֹתוֹ חֲצִי הַסֶּלַע. וּמֵעוֹלָם לֹא שָׁקְלוּ יִשְׂרָאֵל בְּמַחֲצִית הַשֶּׁקֶל פָּחוֹת מֵחֲצִי שֶׁקֶל שֶׁל תּוֹרָה:","הַכּל חַיָּבִין לִתֵּן מַחֲצִית הַשֶּׁקֶל כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים וְגֵרִים וַעֲבָדִים מְשֻׁחְרָרִים. אֲבָל לֹא נָשִׁים וְלֹא עֲבָדִים וְלֹא קְטַנִּים. וְאִם נָתְנוּ מְקַבְּלִין מֵהֶם. אֲבָל הַכּוּתִים שֶׁנָּתְנוּ מַחֲצִית הַשֶּׁקֶל אֵין מְקַבְּלִין מֵהֶם. קָטָן שֶׁהִתְחִיל אָבִיו לִתֵּן עָלָיו מַחֲצִית הַשֶּׁקֶל שׁוּב אֵינוֹ פּוֹסֵק אֶלָּא נוֹתֵן עָלָיו בְּכָל שָׁנָה וְשָׁנָה עַד שֶׁיַּגְדִּיל וְיִתֵּן עַל עַצְמוֹ:","הַשְּׁקָלִים אֵינָן נוֹהֲגִין אֶלָּא בִּפְנֵי הַבַּיִת. וּבִזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם נוֹתְנִין אֶת הַשְּׁקָלִים בֵּין בְּאֶרֶץ יִשְׂרָאֵל בֵּין בְּחוּצָה לָאָרֶץ. וּבִזְמַן שֶׁהוּא חָרֵב אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אֵין נוֹהֲגִין:","בְּאֶחָד בַּאֲדָר מַשְׁמִיעִין עַל הַשְּׁקָלִים כְּדֵי שֶׁיָּכִין כָּל אֶחָד וְאֶחָד מַחֲצִית הַשֶּׁקֶל שֶׁלּוֹ. וְיִהְיֶה עָתִיד לִתֵּן. בַּחֲמִשָּׁה עָשָׂר בּוֹ יָשְׁבוּ הַשֻּׁלְחָנִים בְּכָל מְדִינָה וּמְדִינָה וְתוֹבְעִין בְּנַחַת כָּל מִי שֶׁיִּתֵּן לָהֶם יְקַבְּלוּ מִמֶּנּוּ וּמִי שֶׁלֹּא נָתַן אֵין כּוֹפִין אוֹתוֹ לִתֵּן. בַּחֲמִשָּׁה וְעֶשְׂרִים בּוֹ יָשְׁבוּ בַּמִּקְדָּשׁ לִגְבּוֹת. וּמִכָּאן וְאֵילָךְ כּוֹפִין אֶת מִי שֶׁלֹּא נָתַן עַד שֶׁיִּתֵּן. וְכָל מִי שֶׁלֹּא יִתֵּן מְמַשְׁכְּנִין אוֹתוֹ וְלוֹקְחִין עֲבוֹטוֹ בַּעַל כָּרְחוֹ וַאֲפִלּוּ כְּסוּתוֹ:","כָּל מִי שֶׁאֵינוֹ חַיָּב בִּשְׁקָלִים אַף עַל פִּי שֶׁדַּרְכּוֹ לִתֵּן אוֹ הוּא עָתִיד לִתֵּן אֵין מְמַשְׁכְּנִין אוֹתוֹ. וְאֵין מְמַשְׁכְּנִין אֶת הַכֹּהֲנִים לְעוֹלָם מִפְּנֵי דַּרְכֵי שָׁלוֹם אֶלָּא כְּשֶׁיִּתְּנוּ מְקַבְּלִין מֵהֶן וְתוֹבְעִין אוֹתָן עַד שֶׁיִּתְּנוּ:"],"Mishneh Torah, Slaves 1":["(שמות כא ב) \"עֶבֶד עִבְרִי\" הָאָמוּר בַּתּוֹרָה זֶה יִשְׂרְאֵלִי שֶׁמָּכְרוּ אוֹתוֹ בֵּית דִּין עַל כָּרְחוֹ אוֹ הַמּוֹכֵר עַצְמוֹ לִרְצוֹנוֹ. כֵּיצַד. גָּנַב וְאֵין לוֹ לְשַׁלֵּם אֶת הַקֶּרֶן בֵּית דִּין מוֹכְרִין אוֹתוֹ כְּמוֹ שֶׁאָמַרְנוּ בְּהִלְכוֹת גְּנֵבָה. וְאֵין לְךָ אִישׁ בְּיִשְׂרָאֵל שֶׁמּוֹכְרִין אוֹתוֹ בֵּית דִּין אֶלָּא הַגַּנָּב בִּלְבַד. וְעַל זֶה שֶׁמְּכָרוּהוּ בֵּית דִּין הוּא אוֹמֵר (שמות כא ב) \"כִּי תִקְנֶה עֶבֶד עִבְרִי\". וְעָלָיו הוּא אוֹמֵר בְּמִשְׁנֵה תּוֹרָה (דברים טו יב) \"כִּי יִמָּכֵר לְךָ אָחִיךָ הָעִבְרִי\". מוֹכֵר עַצְמוֹ כֵּיצַד. זֶה יִשְׂרָאֵל שֶׁהֶעֱנִי בְּיוֹתֵר נָתְנָה לוֹ תּוֹרָה רְשׁוּת לִמְכֹּר אֶת עַצְמוֹ שֶׁנֶּאֱמַר (ויקרא כה לט) \"כִּי יָמוּךְ אָחִיךָ עִמָּךְ וְנִמְכַּר לְךָ\". וְאֵינוֹ רַשַּׁאי לִמְכֹּר אֶת עַצְמוֹ וּלְהַצְנִיעַ אֶת דָּמָיו אוֹ לִקְנוֹת בָּהֶם סְחוֹרָה אוֹ כֵּלִים אוֹ לִתְּנֵם לְבַעַל חוֹב אֶלָּא אִם כֵּן צָרִיךְ לְאָכְלָן בִּלְבַד. וְאֵין אָדָם רַשַּׁאי לִמְכֹּר אֶת עַצְמוֹ עַד שֶׁלֹּא יִשָּׁאֵר לוֹ כְּלוּם וַאֲפִלּוּ כְּסוּת לֹא תִּשָּׁאֵר לוֹ וְאַחַר כָּךְ יִמְכֹּר אֶת עַצְמוֹ:","כְּבָר בֵּאַרְנוּ שֶׁאֵין הָאִשָּׁה נִמְכֶּרֶת בִּגְנֵבָתָהּ וְכֵן אֵינָהּ מוֹכֶרֶת אֶת עַצְמָהּ וְאֵינָהּ קוֹנָה לֹא עֶבֶד עִבְרִי וְלֹא עֶבֶד כְּנַעֲנִי מִפְּנֵי הַחֲשָׁד. וְאֵין הַגֵּר נִקְנֶה בְּעֶבֶד עִבְרִי שֶׁנֶּאֱמַר (ויקרא כה מא) \"וְשָׁב אֶל מִשְׁפַּחְתּוֹ\" מִי שֶׁיֵּשׁ לוֹ מִשְׁפָּחָה:","עֶבֶד עִבְרִי שֶׁמְּכָרוּהוּ בֵּית דִּין אֵין מוֹכְרִין אוֹתוֹ אֶלָּא לְיִשְׂרָאֵל אוֹ לְגֵר צֶדֶק. וְכֵן הַמּוֹכֵר עַצְמוֹ אֵינוֹ רַשַּׁאי לִמְכֹּר עַצְמוֹ לְעַכּוּ\"ם וַאֲפִלּוּ לְגֵר תּוֹשָׁב. וְאִם עָבַר וּמָכַר עַצְמוֹ אֲפִלּוּ לְעַכּוּ\"ם וַאֲפִלּוּ לַעֲבוֹדַת כּוֹכָבִים עַצְמָהּ הֲרֵי זֶה מָכוּר שֶׁנֶּאֱמַר (ויקרא כה מז) \"אוֹ לְעֵקֶר מִשְׁפַּחַת גֵּר\". לְעֵקֶר זֶה הַנִּמְכָּר לַעֲבוֹדַת כּוֹכָבִים עַצְמָהּ:","בָּא וְאָמַר לְךָ הֲרֵינִי מוֹכֵר עַצְמִי לְעַכּוּ\"ם אֵין אַתָּה זָקוּק לוֹ עַד שֶׁיִּמָּכֵר אֲבָל לְאַחַר שֶׁנִּמְכַּר לְעַכּוּ\"ם אַף עַל פִּי שֶׁעָבַר וְעָשָׂה שֶׁלֹּא כַּהֹגֶן מִצְוָה לִפְדּוֹתוֹ וְלֹא יִטָּמַע בָּהֶם שֶׁנֶּאֱמַר (ויקרא כה מח) \"אַחֲרֵי נִמְכַּר גְּאֻלָּה תִּהְיֶה לּוֹ\":","אֶחָד הַמּוֹכֵר אֶת עַצְמוֹ אוֹ שֶׁמְּכָרוּהוּ בֵּית דִּין אֵינוֹ נִמְכָּר בְּפַרְהֶסְיָא עַל אֶבֶן הַמִּקָּח וְלֹא בְּסִמְטָא כְּדֶרֶךְ שֶׁהָעֲבָדִים נִמְכָּרִין שֶׁנֶּאֱמַר (ויקרא כה מב) \"לֹא יִמָּכְרוּ מִמְכֶּרֶת עָבֶד\" אֵינוֹ נִמְכָּר אֶלָּא בְּצִנְעָה וְדֶרֶךְ כָּבוֹד:","כָּל עֶבֶד עִבְרִי אָסוּר לַעֲבֹד בּוֹ בְּפָרֶךְ. וְאֵיזוֹ הִיא עֲבוֹדַת פָּרֶךְ זוֹ עֲבוֹדָה שֶׁאֵין לָהּ קִצְבָה וַעֲבוֹדָה שֶׁאֵינוֹ צָרִיךְ לָהּ אֶלָּא תִּהְיֶה מַחְשַׁבְתּוֹ לְהַעֲבִידוֹ בִּלְבַד שֶׁלֹּא יִבָּטֵל. מִכָּאן אָמְרוּ חֲכָמִים שֶׁלֹּא יֹאמַר לוֹ עֲדֹר תַּחַת הַגְּפָנִים עַד שֶׁאָבוֹא שֶׁהֲרֵי לֹא נָתַן לוֹ קִצְבָה. אֶלָּא יֹאמַר לוֹ עֲדֹר עַד שָׁעָה פְּלוֹנִית אוֹ עַד מָקוֹם פְּלוֹנִי. וְכֵן לֹא יֹאמַר לוֹ חֲפֹר מָקוֹם זֶה וְהוּא אֵינוֹ צָרִיךְ לוֹ. וַאֲפִלּוּ לְהָחֵם לוֹ כּוֹס שֶׁל חַמִּין אוֹ לְהָצֵן וְאֵינוֹ צָרִיךְ לוֹ אָסוּר וְעוֹבֵר עָלָיו בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא כה מג) \"לֹא תִרְדֶּה בוֹ בְּפָרֶךְ\". הָא אֵינוֹ עוֹשֶׂה לוֹ אֶלָּא דָּבָר קָצוּב שֶׁהוּא צָרִיךְ לוֹ. וְכֵן הָעַכּוּ\"ם שֶׁנִּמְכַּר לוֹ אִם רָדָה בּוֹ בְּפָרֶךְ הֲרֵי יִשְׂרָאֵל מְצֻוִּין לְמָנְעוֹ. וְאִם הִנִּיחוּהוּ עוֹבְרִים בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא כה נג) \"לֹא יִרְדֶּנּוּ בְּפֶרֶךְ לְעֵינֶיךָ\". וְאֵין אָנוּ נִזְקָקִין לִכְנֹס לִרְשׁוּתוֹ שֶׁל עַכּוּ\"ם וְלִבְדֹּק אַחֲרָיו שֶׁלֹּא יַעֲבִידֶנּוּ בְּפָרֶךְ שֶׁנֶּאֱמַר לְעֵינֶיךָ בִּזְמַן שֶׁאַתָּה רוֹאֶה:","כָּל עֶבֶד עִבְרִי אָסוּר לְיִשְׂרָאֵל שֶׁקָּנָהוּ לְהַעֲבִידוֹ בִּדְבָרִים בּוֹזִים שֶׁהֵם מְיֻחָדִים לַעֲשׂוֹת הָעֲבָדִים כְּגוֹן שֶׁיּוֹלִיךְ אַחֲרָיו כֵּלָיו לְבֵית הַמֶּרְחָץ אוֹ יַחְלֹץ לוֹ מִנְעָלָיו שֶׁנֶּאֱמַר (ויקרא כה לט) \"לֹא תַעֲבֹד בּוֹ עֲבֹדַת עָבֶד\". אֵינוֹ נוֹהֵג בּוֹ אֶלָּא כְּשָׂכִיר שֶׁנֶּאֱמַר (ויקרא כה מ) \"כְּשָׂכִיר כְּתוֹשָׁב יִהְיֶה עִמָּךְ\". וּמֻתָּר לְסַפֵּר לוֹ שְׂעָרוֹ וּלְכַבֵּס לוֹ כְּסוּתוֹ וְלֶאֱפוֹת לוֹ עִסָּתוֹ. אֲבָל לֹא יַעֲשֶׂה אוֹתוֹ בַּלָּן לָרַבִּים אוֹ סַפָּר לָרַבִּים אוֹ נַחְתּוֹם לָרַבִּים. וְאִם הָיְתָה אֻמָּנוּתוֹ זֹאת קֹדֶם שֶׁיִּמָּכֵר הֲרֵי זֶה יַעֲשֶׂה. אֲבָל לֹא יְלַמְּדֵנוּ בַּתְּחִלָּה מְלָאכָה כְּלָל אֶלָּא אֻמָּנוּת שֶׁהָיָה בָּהּ הוּא שֶׁעוֹשֶׂה כְּשֶׁהָיָה עוֹשֶׂה מִקֹּדֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעֶבֶד עִבְרִי מִפְּנֵי שֶׁנַּפְשׁוֹ שְׁפָלָה בִּמְכִירָה. אֲבָל יִשְׂרָאֵל שֶׁלֹּא נִמְכַּר מֻתָּר לְהִשְׁתַּמֵּשׁ בּוֹ כְּעֶבֶד שֶׁהֲרֵי אֵינוֹ עוֹשֶׂה מְלָאכָה זוֹ אֶלָּא בִּרְצוֹנוֹ וּמִדַּעַת עַצְמוֹ:","אֲנָשִׁים שֶׁאֵינָן נוֹהֲגִין כַּשּׁוּרָה מֻתָּר לִרְדּוֹתָן בְּחָזְקָה וּלְהִשְׁתַּעְבֵּד בָּהֶן. מֶלֶךְ שֶׁגָּזַר שֶׁכָּל מִי שֶׁלֹּא יִתֵּן הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ יִשְׁתַּעְבֵּד לְזֶה שֶׁנָּתַן הַמַּס עַל יָדוֹ הֲרֵי זֶה מֻתָּר לְהִשְׁתַּמֵּשׁ בּוֹ יוֹתֵר מִדַּאי אֲבָל לֹא כְּעֶבֶד. וְאִם אֵינוֹ נוֹהֵג כַּשּׁוּרָה מֻתָּר לְהִשְׁתַּמֵּשׁ בּוֹ כְּעֶבֶד:","כָּל עֶבֶד עִבְרִי אוֹ אָמָה הָעִבְרִיָּה חַיָּב הָאָדוֹן לְהַשְׁווֹתָן לוֹ בְּמַאֲכָל וּבְמַשְׁקֶה בִּכְסוּת וּבְמָדוֹר שֶׁנֶּאֱמַר (דברים טו טז) \"כִּי טוֹב לוֹ עִמָּךְ\" שֶׁלֹּא תְּהֵא אַתָּה אוֹכֵל פַּת נָקִי וְהוּא אוֹכֵל פַּת קִבָּר אַתָּה שׁוֹתֶה יַיִן יָשָׁן וְהוּא שׁוֹתֶה יַיִן חָדָשׁ אַתָּה יָשֵׁן עַל גַּבֵּי מוֹכִין וְהוּא יָשֵׁן עַל גַּבֵּי הַתֶּבֶן אַתָּה דָּר בִּכְרַךְ וְהוּא דָּר בִּכְפָר אוֹ אַתָּה דָּר בִּכְפָר וְהוּא יוֹשֵׁב בִּכְרַךְ. שֶׁנֶּאֱמַר (ויקרא כה מא) \"וְיָצָא מֵעִמָּךְ\". מִכָּאן אָמְרוּ כָּל הַקּוֹנֶה עֶבֶד עִבְרִי כְּקוֹנֶה אָדוֹן לְעַצְמוֹ. וְחַיָּב לִנְהֹג בּוֹ מִנְהַג אַחְוָה שֶׁנֶּאֱמַר (ויקרא כה מו) \"וּבְאַחֵיכֶם בְּנֵי יִשְׂרָאֵל\". וְאַף עַל פִּי כֵן צָרִיךְ הָעֶבֶד לִנְהֹג בְּעַצְמוֹ מִנְהַג עַבְדוּת בְּאוֹתָן הָעֲבוֹדוֹת שֶׁהוּא עוֹשֶׂה לוֹ:","אֵין אָמָה הָעִבְרִיָּה נוֹהֶגֶת וְלֹא עֶבֶד עִבְרִי נוֹהֵג אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג. בֵּין עֶבֶד עִבְרִי שֶׁמּוֹכֵר עַצְמוֹ בֵּין זֶה שֶׁמְּכָרוּהוּ בֵּית דִּין. וּכְבָר בֵּאַרְנוּ מָתַי בָּטְלוּ הַיּוֹבְלוֹת:"],"Mishneh Torah, Substitution 4":["כֵּיצַד דִּין וַלְדוֹת הַקָּדָשִׁים. וְלַד שְׁלָמִים וּוְלַד תְּמוּרַת שְׁלָמִים הֲרֵי אֵלּוּ כִּשְׁלָמִים וְהֵן עַצְמָן כִּשְׁלָמִים לְכָל דָּבָר. וְכֵן וְלַד הַתּוֹדָה וּוְלַד תְּמוּרָתָהּ הֲרֵי אֵלּוּ יִקָּרְבוּ כְּתוֹדָה אֶלָּא שֶׁאֵינָן טְעוּנִין לֶחֶם שֶׁאֵין מְבִיאִין לֶחֶם אֶלָּא עִם הַתּוֹדָה עַצְמָהּ. שֶׁנֶּאֱמַר (ויקרא ז יב) \"עַל זֶבַח הַתּוֹדָה\" עָלָיו וְלֹא עַל וְלָדָהּ וְלֹא עַל תְּמוּרָתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בַּוְּלָדוֹת עַצְמָן אֲבָל וַלְדֵי וְלָדוֹת אֵינָן קְרֵבִין. שֶׁמִּתּוֹךְ מַעֲשָׂיו נִכָּר שֶׁהוּא מַשְׁהֶה אוֹתָן לְגַדֵּל מֵהֶן עֲדָרִים עֲדָרִים וּלְפִיכָךְ קוֹנְסִין אוֹתוֹ וְלֹא יַקְרִיבֵם:","וְלַד הַחַטָּאת יָמוּת וְאֵין צָרִיךְ לוֹמַר וְלַד תְּמוּרָתָהּ:","הַשּׁוֹחֵט אֶת הַחַטָּאת וּמָצָא בָּהּ בֶּן אַרְבָּעָה חַי הֲרֵי זוֹ נֶאֱכֶלֶת כִּבְשַׂר הַחַטָּאת. שֶׁוַּלְדֵי הַקָּדָשִׁים בִּמְעֵי אִמָּן הֵם קְדוֹשִׁים:","וְלַד תְּמוּרַת הָאָשָׁם וּוְלַד וְלָדָהּ עַד סוֹף הָעוֹלָם יִרְעוּ עַד שֶׁיִּפּל בָּהֶם מוּם וְיִמָּכְרוּ וְיִפְּלוּ דְּמֵיהֶן לִנְדָבָה. וְאִם יָלְדָה זָכָר אַחַר שֶׁהִקְרִיב אֲשָׁמוֹ הַוָּלָד עַצְמוֹ יִקָּרֵב עוֹלָה. הִפְרִישׁ נְקֵבָה לַאֲשָׁמוֹ וְיָלְדָה תִּרְעֶה הִיא וּבְנָהּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיִמָּכְרוּ וְיָבִיא בִּדְמֵי שְׁנֵיהֶם אֲשָׁמוֹ. וְאִם כְּבָר הִקְרִיב אֲשָׁמוֹ יִפְּלוּ דְּמֵיהֶן לִנְדָבָה:","וְלַד תְּמוּרַת הָעוֹלָה וּוְלַד וְלָדָהּ עַד סוֹף הָעוֹלָם הֲרֵי אֵלּוּ כְּעוֹלָה וְהֵן עַצְמָן יִקָּרְבוּ עוֹלָה. הִפְרִישׁ נְקֵבָה לְעוֹלָתוֹ וְיָלְדָה אַף עַל פִּי שֶׁיָּלְדָה זָכָר יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיָבִיא בְּדָמָיו עוֹלָה. כְּבָר בֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת שֶׁכָּל מָקוֹם שֶׁאָנוּ אוֹמְרִין יִפְּלוּ לִנְדָבָה הוּא שֶׁיִּתֵּן הַמָּעוֹת בַּשּׁוֹפָרוֹת שֶׁהָיוּ בַּמִּקְדָּשׁ שֶׁבֵּאַרְנוּ בִּשְׁקָלִים כַּמָּה הֵם. וּבֵית דִּין מַקְרִיבִין בְּאוֹתָן הַמָּעוֹת עוֹלוֹת נְדָבָה וְנִסְכֵּיהֶם מִשֶּׁל צִבּוּר וְאֵינָן טְעוּנוֹת סְמִיכָה. אֲבָל מָקוֹם שֶׁנֶּאֱמַר הוּא עַצְמוֹ יִקְרַב עוֹלָה אוֹ יָבִיא בְּדָמָיו עוֹלָה. הֲרֵי זוֹ טְעוּנָה סְמִיכָה וּנְסָכֶיהָ מִשֶּׁלּוֹ:","וְלַד הַמַּעֲשֵׂר. [וּוְלַד] תְּמוּרַת הַמַּעֲשֵׂר. וְלַד תְּמוּרַת הַבְּכוֹר וּוַלְדֵי וַלְדוֹתֵיהֶן עַד סוֹף הָעוֹלָם. הֲרֵי אֵלּוּ לֹא יִקָּרְבוּ אֶלָּא יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיֵאָכְלוּ כִּבְכוֹר וּכְמַעֲשֵׂר שֶׁנָּפַל בָּהֶן מוּם. וַלְדוֹת תְּמוּרַת הַבְּכוֹר לְכֹהֵן. וַלְדוֹת מַעֲשֵׂר וּתְמוּרָתוֹ לִבְעָלָיו:","וְלַד תְּמוּרַת הַפֶּסַח כִּתְמוּרַת הַפֶּסַח. אִם הָיְתָה אִמּוֹ קְרֵבָה שְׁלָמִים וְלָדָהּ יִקָּרֵב שְׁלָמִים וְאִם הָיָה דִּינָהּ שֶׁתִּמָּכֵר וְיָבִיא בְּדָמֶיהָ שְׁלָמִים אַף וְלָדָהּ נִמְכָּר וְיָבִיא בְּדָמָיו שְׁלָמִים. הִפְרִישׁ נְקֵבָה לְפִסְחוֹ וְיָלְדָה. אוֹ שֶׁהִפְרִישָׁהּ מְעֻבֶּרֶת. הִיא וּוְלָדָהּ יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵיהֶן פֶּסַח. וְאִם נִשְׁאֲרָה נְקֵבָה זוֹ עַד אַחַר הַפֶּסַח אוֹ שֶׁיָּלְדָה אַחַר הַפֶּסַח. תִּרְעֶה הִיא וּוְלָדָהּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵיהֶן שְׁלָמִים:","וַלְדוֹת הַקָּדָשִׁים שֶׁיָּצְאוּ דֶּרֶךְ דֹּפֶן. אוֹ שֶׁיָּלְדוּ טֻמְטוּם וְאַנְדְּרוֹגִינוּס וְכִלְאַיִם וּטְרֵפָה. הֲרֵי אֵלּוּ יִפָּדוּ וְיָבִיא בִּדְמֵיהֶן קָרְבָּן הָרָאוּי לְהָבִיא בִּדְמֵי וָלָד שֶׁל זוֹ:","וְלַד בַּעֲלַת מוּם הֲרֵי הוּא כִּוְלַד הַתְּמִימָה לְכָל דָּבָר וְיִקָּרֵב כָּרָאוּי לוֹ:","קָדָשִׁים שֶׁהִפִּילוּ נֵפֶל אוֹ שִׁלְיָא יִקָּבְרוּ וַהֲרֵי הֵם אֲסוּרִים בַּהֲנָאָה:","הַמְשַׁנֶּה אֶת הַקָּדָשִׁים מִקְּדֻשָּׁה לִקְדֻשָּׁה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר בִּבְכוֹר (ויקרא כז כו) \"לֹא יַקְדִּישׁ אִישׁ אֹתוֹ\" שֶׁלֹּא יַעֲשֶׂנּוּ עוֹלָה אוֹ שְׁלָמִים. וְהוּא הַדִּין לִשְׁאָר הַקָּדָשִׁים שֶׁאֵין מְשַׁנִּין אוֹתָן מִקְּדֻשָּׁה לִקְדֻשָּׁה אֶחָד קָדְשֵׁי מִזְבֵּחַ וְאֶחָד קָדְשֵׁי בֶּדֶק הַבַּיִת. כֵּיצַד. אִם הִקְדִּישׁ לְבֶדֶק הַהֵיכָל לֹא יְשַׁנֶּה לְבֶדֶק הַמִּזְבֵּחַ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאֵין לוֹקִין עַל לָאו זֶה:","כֵּיצַד מַעֲרִימִין עַל הַבְּכוֹר לְהַקְדִּישׁוֹ לַמִּזְבֵּחַ הֶקְדֵּשׁ אַחֵר. מַקְדִּישׁוֹ בַּבֶּטֶן קֹדֶם שֶׁיִּוָּלֵד שֶׁנֶּאֱמַר (ויקרא כז כו) \"אֲשֶׁר יְבֻכַּר לַה'\" (ויקרא כז כו) \"לֹא יַקְדִּישׁ אִישׁ אוֹתוֹ\". מִשֶּׁיְּבֻכַּר אִי אַתָּה מַקְדִּישׁוֹ אֲבָל אַתָּה מַקְדִּישׁוֹ בַּבֶּטֶן. לְפִיכָךְ יֵשׁ לוֹ לוֹמַר מַה שֶּׁבְּמֵעֶיהָ שֶׁל מַבְכֶּרֶת זוֹ אִם הוּא זָכָר הֲרֵי זוֹ עוֹלָה. אֲבָל אֵינוֹ יָכוֹל לוֹמַר זִבְחֵי שְׁלָמִים שֶׁאֵינוֹ יָכוֹל לְהַפְקִיעַ אוֹתוֹ מִקְּדֻשָּׁתוֹ כְּדֵי לֵהָנוֹת בּוֹ. וְאִם אָמַר עִם יְצִיאַת רֹב רֹאשׁוֹ יִהְיֶה עוֹלָה הֲרֵי זֶה בְּכוֹר וְאֵינוֹ עוֹלָה:","וְאֵין מַעֲרִימִין עַל בֶּהֱמַת הֶקְדֵּשׁ לְהַקְדִּישׁ עֻבָּרָהּ קְדֻשָּׁה אַחֶרֶת אֶלָּא הֲרֵי הוּא כִּקְדֻשַּׁת אִמּוֹ. שֶׁוַּלְדוֹת הַקָּדָשִׁים מִמְּעֵי אִמָּם הֵם קְדוֹשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ. וַהֲרֵי כָּל עֻבָּר מֵהֶן כִּקְדֻשַּׁת אִמּוֹ וְאֵינוֹ יָכוֹל לְשַׁנּוֹתוֹ בַּבֶּטֶן כְּדֶרֶךְ שֶׁעָשָׂה בִּבְכוֹר שֶׁהַבְּכוֹר בִּיצִיאָתוֹ הוּא שֶׁמִּתְקַדֵּשׁ. אַף עַל פִּי שֶׁכָּל חֻקֵּי הַתּוֹרָה גְּזֵרוֹת הֵם כְּמוֹ שֶׁבֵּאַרְנוּ בְּסוֹף מְעִילָה. רָאוּי לְהִתְבּוֹנֵן בָּהֶן וְכָל מַה שֶּׁאַתָּה יָכוֹל לִתֵּן לוֹ טַעַם תֵּן לוֹ טַעַם. הֲרֵי אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים שֶׁהַמֶּלֶךְ שְׁלֹמֹה הֵבִין רֹב הַטְּעָמִים שֶׁל כָּל חֻקֵּי הַתּוֹרָה. יֵרָאֶה לִי שֶׁזֶּה שֶׁאָמַר הַכָּתוּב (ויקרא כז י) (ויקרא כז ל) \"וְהָיָה הוּא וּתְמוּרָתוֹ יִהְיֶה קֹדֶשׁ\". כָּעִנְיָן שֶׁאָמַר (ויקרא כז טו) \"וְאִם הַמַּקְדִּישׁ יִגְאַל אֶת בֵּיתוֹ וְיָסַף חֲמִישִׁית כֶּסֶף עֶרְכְּךָ עָלָיו\". יָרְדָה תּוֹרָה לְסוֹף מַחֲשֶׁבֶת הָאָדָם וּקְצָת יִצְרוֹ הָרַע. שֶׁטֶּבַע שֶׁל אָדָם נוֹטֶה לְהַרְבּוֹת קִנְיָנוֹ וְלָחוּס עַל מָמוֹנוֹ וְאַף עַל פִּי שֶׁנָּדַר וְהִקְדִּישׁ אֶפְשָׁר שֶׁחָזַר בּוֹ וְנִחַם וְיִפְדֶּה בְּפָחוֹת מִשָּׁוְיוֹ אָמְרָה תּוֹרָה אִם פָּדָה לְעַצְמוֹ יוֹסִיף חֹמֶשׁ. וְכֵן אִם הִקְדִּישׁ בְּהֵמָה קְדֻשַּׁת הַגּוּף שֶׁמָּא יַחְזֹר בּוֹ וְכֵיוָן שֶׁאֵינוֹ יָכוֹל לִפְדּוֹתָהּ יַחְלִיפֶנָּה בִּפְחוּתָה מִמֶּנָּה. וְאִם תִּתֵּן לוֹ רְשׁוּת לְהַחְלִיף הָרַע בְּיָפֶה יַחְלִיף הַיָּפֶה בְּרַע וְיֹאמַר טוֹב הוּא. לְפִיכָךְ סָתַם הַכָּתוּב בְּפָנָיו שֶׁלֹּא יַחְלִיף. וּקְנָסוֹ אִם הֶחְלִיף וְאָמַר וְהָיָה הוּא וּתְמוּרָתוֹ יִהְיֶה קֹדֶשׁ. וְכָל אֵלּוּ הַדְּבָרִים כְּדֵי לָכֹף אֶת יִצְרוֹ וּלְתַקֵּן דֵּעוֹתָיו. וְרֹב דִּינֵי הַתּוֹרָה אֵינָן אֶלָּא עֵצוֹת מֵרָחוֹק מִגְּדוֹל הָעֵצָה לְתַקֵּן הַדֵּעוֹת וּלְיַשֵּׁר כָּל הַמַּעֲשִׂים. וְכֵן הוּא אוֹמֵר (משלי כב כ) \"הֲלֹא כָתַבְתִּי לְךָ שָׁלִישִׁים בְּמֹעֵצוֹת וָדָעַת\". לְהוֹדִיעֲךָ קֹשְׁטְ אִמְרֵי אֱמֶת לְהָשִׁיב אֲמָרִים אֱמֶת לְשלְחֶיךָ:","ספר תשיעי והוא ספר הקרבנות הלכותיו ששה ופרקיו חמשה וארבעים:ואלו הן:הלכות קרבן פסח עשרה פרקים הלכות חגיגה שלשה פרקים הלכות בכורות שמונה פרקים הלכות שגגות חמשה עשר פרקים הלכות מחוסרי כפרה חמשה פרקים הלכות תמורה ארבעה פרקים:"],"Mishneh Torah, Testimony 10":["הָרְשָׁעִים פְּסוּלִין לְעֵדוּת מִן הַתּוֹרָה שֶׁנֶּאֱמַר (שמות כג א) \"אַל תָּשֶׁת יָדְךָ עִם רָשָׁע לִהְיֹת עֵד חָמָס\" מִפִּי הַשְּׁמוּעָה לָמְדוּ אַל תָּשֶׁת רָשָׁע עֵד. וַאֲפִלּוּ עֵד כָּשֵׁר שֶׁיּוֹדֵעַ בַּחֲבֵרוֹ שֶׁהוּא רָשָׁע וְאֵין הַדַּיָּנִים מַכִּירִין רִשְׁעוֹ אָסוּר לוֹ לְהָעִיד עִמּוֹ אַף עַל פִּי שֶׁהוּא עֵדוּת אֱמֶת. מִפְּנֵי שֶׁמִּצְטָרֵף עִמּוֹ וְנִמְצָא זֶה הַכָּשֵׁר הֵשִׁית יָדוֹ עִם הָרָשָׁע עַד שֶׁנִּתְקַבְּלָה עֵדוּתוֹ. וְאֵין צָרִיךְ לוֹמַר עֵד כָּשֵׁר שֶׁהוּא יוֹדֵעַ בְּעֵדוּת לַחֲבֵרוֹ וְיָדַע שֶׁהָעֵד הַשֵּׁנִי עִמּוֹ עֵד שֶׁקֶר שֶׁאָסוּר לוֹ לְהָעִיד שֶׁנֶּאֱמַר אַל תָּשֶׁת יָדְךָ עִם רָשָׁע:","אֵי זֶהוּ רָשָׁע כָּל שֶׁעָבַר עֲבֵרָה שֶׁחַיָּבִין עָלֶיהָ מַלְקוֹת זֶהוּ רָשָׁע וּפָסוּל. שֶׁהֲרֵי הַתּוֹרָה קָרְאָה לַמְחֻיָּב מַלְקוֹת רָשָׁע שֶׁנֶּאֱמַר (דברים כה ב) \"וְהָיָה אִם בִּן הַכּוֹת הָרָשָׁע\". וְאֵין צָרִיךְ לוֹמַר מְחֻיָּב מִיתַת בֵּית דִּין שֶׁהוּא פָּסוּל שֶׁנֶּאֱמַר (במדבר לה לא) \"אֲשֶׁר הוּא רָשָׁע לָמוּת\":","עָבַר עֲבֵרָה שֶׁחַיָּבִין עָלֶיהָ מַלְקוֹת מִן הַתּוֹרָה הֲרֵי זֶה פָּסוּל מִן הַתּוֹרָה. וְאִם הָיָה הַחִיּוּב שֶׁבָּהּ מִדִּבְרֵיהֶם הֲרֵי זֶה פָּסוּל מִדִּבְרֵיהֶם. כֵּיצַד. אָכַל בְּשַׂר בְּהֵמָה בְּחָלָב אוֹ שֶׁאָכַל נְבֵלוֹת וּשְׁקָצִים וְכַיּוֹצֵא בָּהֶן בֵּין לְתֵאָבוֹן בֵּין לְהַכְעִיס. אוֹ שֶׁחִלֵּל אֶת יוֹם טוֹב הָרִאשׁוֹן. אוֹ שֶׁלָּבַשׁ שַׁעַטְנֵז שֶׁהוּא שׁוּעַ אוֹ טָווּי אוֹ נוּז. הֲרֵי זֶה פָּסוּל לְעֵדוּת מִן הַתּוֹרָה. אֲבָל אִם אָכַל בְּשַׂר עוֹף בְּחָלָב. אוֹ שֶׁחִלֵּל יוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת. אוֹ שֶׁלָּבַשׁ בֶּגֶד צֶמֶר שֶׁאָבַד בּוֹ חוּט שֶׁל פִּשְׁתָּן וְכַיּוֹצֵא בּוֹ. הֲרֵי הוּא פָּסוּל מִדִּבְרֵיהֶם. וּכְבָר מָנִינוּ כָּל עֲבֵרָה שֶׁחַיָּבִין עָלֶיהָ מַלְקוֹת. וּכְבָר נִתְבָּאֵר בְּכָל מִצְוָה וּמִצְוָה דְּבָרִים שֶׁאֲסוּרִים מִן הַתּוֹרָה וּדְבָרִים שֶׁאֲסוּרִין מִדִּבְרֵיהֶם:","וְעוֹד יֵשׁ שָׁם רְשָׁעִים שֶׁהֵן פְּסוּלִין לְעֵדוּת אַף עַל פִּי שֶׁהֵן בְּנֵי תַּשְׁלוּמִין וְאֵינָן בְּנֵי מַלְקוֹת. הוֹאִיל וְלוֹקְחִים מָמוֹן שֶׁאֵינוֹ שֶׁלָּהֶם בְּחָמָס פְּסוּלִין שֶׁנֶּאֱמַר (דברים יט טז) \"כִּי יָקוּם עֵד חָמָס בְּאִישׁ\". כְּגוֹן הַגַּנָּבִים וְהַחַמְסָנִים אַף עַל פִּי שֶׁהֶחְזִיר פָּסוּל לְעֵדוּת מֵעֵת שֶׁגָּנַב אוֹ גָּזַל. וְכֵן עֵד זוֹמֵם אַף עַל פִּי שֶׁהוּזַם בְּעֵדוּת מָמוֹן וְשִׁלֵּם הֲרֵי זֶה פָּסוּל מִן הַתּוֹרָה לְכָל עֵדוּת. וּמֵאֵימָתַי הוּא נִפְסָל מֵעֵת שֶׁהֵעִיד בְּבֵית דִּין. אַף עַל פִּי שֶׁלֹּא הוּזַם עַל אוֹתָהּ עֵדוּת אֶלָּא אַחַר כַּמָּה יָמִים. וְכֵן הַמַּלְוֶה בְּרִבִּית אֶחָד הַמַּלְוֶה וְאֶחָד הַלּוֶֹה שְׁנֵיהֶם פְּסוּלִין לְעֵדוּת. אִם רִבִּית קְצוּצָה עָשׂוּ הֲרֵי הֵן פְּסוּלִין מִן הַתּוֹרָה וְאִם אֲבַק רִבִּית עָשׂוּ הֲרֵי הֵן פְּסוּלִין מִדִּבְרֵיהֶם. וְכֵן כָּל הָעוֹבֵר עַל גֵּזֶל שֶׁל דִּבְרֵיהֶם הֲרֵי הוּא פָּסוּל מִדִּבְרֵיהֶם. כֵּיצַד. הַחַמְסָנִים וְהֵם הַלּוֹקְחִים קַרְקַע אוֹ מִטַּלְטְלִין שֶׁלֹּא בִּרְצוֹן הַבְּעָלִים אַף עַל פִּי שֶּׁנּוֹתְנִין הַדָּמִים הֲרֵי אֵלּוּ פְּסוּלִין מִדִּבְרֵיהֶם. וְכֵן הָרוֹעִים אֶחָד רוֹעֵי בְּהֵמָה דַּקָּה וְאֶחָד רוֹעֵי בְּהֵמָה גַּסָּה שֶׁל עַצְמָן הֲרֵי הֵן פְּסוּלִין שֶׁחֶזְקָתָן פּוֹשְׁטִין יְדֵיהֶן בְּגֵזֶל וּמְנִיחִים בְּהֶמְתָּן לִרְעוֹת בְּשָׂדוֹת וּפַרְדֵּסִים שֶׁל אֲחֵרִים וּלְפִיכָךְ סְתָם רוֹעֶה פָּסוּל. וּמְגַדְּלֵי בְּהֵמָה דַּקָּה בְּאֶרֶץ יִשְׂרָאֵל פְּסוּלִין אֲבָל בְּחוּצָה לָאָרֶץ כְּשֵׁרִין. וּמֻתָּר לְגַדֵּל בְּהֵמָה גַּסָּה בְּכָל מָקוֹם. וְכֵן הַמּוֹכְסִין סְתָמָן פְּסוּלִין מִפְּנֵי שֶׁחֶזְקָתָן לִקַּח יוֹתֵר מִדָּבָר הַקָּצוּב לָהֶם בְּדִין הַמַּלְכוּת וְלוֹקְחִין הֶתֵּר לְעַצְמָן. אֲבָל גַּבָּאֵי מְנַת הַמֶּלֶךְ סְתָמָן כְּשֵׁרִין וְאִם נוֹדַע שֶׁלָּקְחוּ אֲפִלּוּ פַּעַם אַחַת יֶתֶר מִן הָרָאוּי לָהֶם לִגְבּוֹת הֲרֵי אֵלּוּ פְּסוּלִין. וְכֵן מַפְרִיחֵי יוֹנִים בַּיִּשּׁוּב פְּסוּלִין מִפְּנֵי שֶׁחֶזְקָתָן שֶׁגּוֹזְלִים יוֹנִים שֶׁל אֲחֵרִים בְּחִנָּם. וְכֵן סוֹחֲרֵי שְׁבִיעִית וְהֵם בְּנֵי אָדָם שֶׁיּוֹשְׁבִין בְּטֵלִים וְכֵיוָן שֶׁבָּאָה שְׁבִיעִית פּוֹשְׁטִים יְדֵיהֶן וּמַתְחִילִין לִשָּׂא וְלִתֵּן בְּפֵרוֹת שֶׁחֶזְקַת אֵלּוּ שֶׁהֵן אוֹסְפִין פֵּרוֹת שְׁבִיעִית וְעוֹשִׂין בָּהֶן סְחוֹרָה. וְכֵן מְשַׂחֵק בְּקֻבִּיָּא וְהוּא שֶׁלֹּא תִּהְיֶה לוֹ אֻמָּנוּת אֶלָּא הוּא. הוֹאִיל וְאֵינוֹ עוֹסֵק בְּיִשּׁוּבוֹ שֶׁל עוֹלָם הֲרֵי זֶה בְּחֶזְקַת שֶׁאוֹכֵל מִן הַקֻּבִּיָּא שֶׁהוּא אֲבַק גֵּזֶל. וְלֹא בְּקֻבִּיָּא בִּלְבַד אֶלָּא אֲפִלּוּ מְשַׂחֲקִים בִּקְלִפֵּי אֱגוֹזִים וּקְלִפֵּי רִמּוֹנִים. וְכֵן לֹא יוֹנִים בִּלְבַד אָמְרוּ אֶלָּא אֲפִלּוּ הַמְשַׂחֲקִים בִּבְהֵמָה חַיָּה וְעוֹף וְאוֹמֵר כָּל הַקּוֹדֵם אֶת חֲבֵרוֹ אוֹ כָּל הַנּוֹצֵחַ אֶת חֲבֵרוֹ יִטּל בְּעָלָיו אֶת שְׁנֵיהֶן. וְכֵן כָּל כַּיּוֹצֵא בִּשְׂחוֹק זֶה. וְהוּא שֶׁלֹּא תִּהְיֶה לוֹ אֻמָּנוּת אֶלָּא שְׂחוֹק זֶה הֲרֵי הוּא פָּסוּל. וְכָל אֵלּוּ פְּסוּלִין מִדִּבְרֵיהֶם:","אָרִיס שֶׁלָּקַח דָּבָר מוּעָט מִן הַפֵּרוֹת שֶׁבִּכְּרוּ בִּימֵי נִיסָן וִימֵי תִּשְׁרֵי קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן. אַף עַל פִּי שֶׁלָּקַח שֶׁלֹּא מִדַּעַת בַּעַל הַשָּׂדֶה אֵינוֹ גַּנָּב וְכָשֵׁר לְעֵדוּת. שֶׁאֵין בַּעַל הַשָּׂדֶה מַקְפִּיד עָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Testimony 21":["עֵדִים שֶׁהֵעִידוּ שֶׁפְּלוֹנִי גֵּרֵשׁ אִשְׁתּוֹ וְלֹא נָתַן לָהּ כְּתֻבָּה וְהוּזַמּוּ. וַהֲלֹא בֵּין הַיּוֹם בֵּין לְמָחָר אִם גֵּרֵשׁ סוֹפוֹ לִתֵּן כְּתֻבָּה. אוֹמְדִין כַּמָּה רוֹצֶה אָדָם לִתֵּן בִּכְתֻבָּתָהּ שֶׁל זוֹ שֶׁתִּמְכֹּר אוֹתָהּ בְּטוֹבַת הֲנָאָה וּמְשַׁלְּמִין דְּמֵי טוֹבַת הֲנָאָה זוֹ. וּמְשַׁעֲרִין בְּאִשָּׁה וּבִכְתֻבָּתָהּ. שֶׁאִם הָאִשָּׁה הָיְתָה חוֹלָה אוֹ זְקֵנָה אוֹ שֶׁהָיָה שָׁלוֹם בֵּינָהּ לְבֵין בַּעְלָהּ אֵין דְּמֵי הַכְּתֻבָּה כְּשֶׁתִּמָּכֵר כְּמוֹ דָּמֶיהָ אִם הָיְתָה הָאִשָּׁה בְּרִיאָה וּקְטַנָּה אִם יֵשׁ בֵּינֵיהֶן קְטָטָה שֶׁזּוֹ קְרוֹבָה מִן הַגֵּרוּשִׁין וּרְחוֹקָה מִן הַמִּיתָה. וְכֵן אֵין טוֹבַת הֲנָאָה שֶׁל כְּתֻבָּה הַמְרֻבָּה לְפִי טוֹבַת הֲנָאָה שֶׁל כְּתֻבָּה הַמּוּעֶטֶת. שֶׁאִם הָיְתָה כְּתֻבָּתָהּ אֶלֶף זוּז הֲרֵי הִיא נִמְכֶּרֶת בְּטוֹבַת הֲנָאָה בְּמֵאָה. וְאִם הָיְתָה מֵאָה אֵינָהּ נִמְכֶּרֶת בַּעֲשָׂרָה אֶלָּא בְּפָחוֹת. דְּבָרִים אֵלּוּ כְּפִי מַה שֶּׁיְּשַׁעֲרוּ הַדַּיָּנִים:","הֵעִידוּ עַל זֶה שֶׁחַיָּב לִפְלוֹנִי אֶלֶף זוּז עַל מְנָת לִתֵּן מִכָּאן וְעַד שְׁלֹשִׁים יוֹם. וְהַלּוֶֹה אוֹמֵר עַד חָמֵשׁ שָׁנִים אַחַר הַשְּׁלֹשִׁים יוֹם. וְנִמְצְאוּ זוֹמְמִין. אוֹמְדִין כַּמָּה רוֹצֶה אָדָם לִתֵּן וְיִהְיוּ בְּיָדוֹ אֶלֶף זוּז חָמֵשׁ שָׁנִים וּמְשַׁלְּמִין כֵּן לַלּוֶֹה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֵעִידוּ עַל שׁוֹרוֹ שֶׁל זֶה שֶׁנָּגַח וְנִמְצְאוּ זוֹמְמִין מְשַׁלְּמִין חֲצִי נֵזֶק. וְאִם אֵין הַשּׁוֹר שָׁוֶה חֲצִי נֵזֶק מְשַׁלְּמִין דְּמֵי הַשּׁוֹר בִּלְבַד שֶׁאֵין מְשַׁלֵּם חֲצִי נֵזֶק אֶלָּא מִגּוּפוֹ. לְפִיכָךְ אִם הֵעִידוּ עָלָיו שֶׁאָכַל פֵּרוֹת אוֹ שָׁבַר כֵּלִים בְּדֶרֶךְ הִלּוּכוֹ מְשַׁלְּמִין נֵזֶק שָׁלֵם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֵעִידוּ עַל פְּלוֹנִי שֶׁהִפִּיל שֵׁן עַבְדּוֹ וְאַחַר כָּךְ סִמֵּא אֶת עֵינוֹ וְהוּזַמּוּ. מְשַׁלְּמִין לָאָדוֹן דְּמֵי הָעֶבֶד וּדְמֵי עֵינוֹ. הֵעִידוּ שֶׁסִּמֵּא אֶת עֵינוֹ וְאַחַר כָּךְ הִפִּיל אֶת שִׁנּוֹ וְהוּזַמּוּ (וְאַחַר כָּךְ) וְנִמְצָא הַדָּבָר הֵפֶךְ שֶׁהָאָדוֹן הִפִּיל אֶת שִׁנּוֹ וְאַחַר כָּךְ סִמֵּא אֶת עֵינוֹ מְשַׁלְּמִין דְּמֵי עַיִן לָעֶבֶד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","עֵדֵי קִנּוּי וּסְתִירָה שֶׁהוּזַמּוּ לוֹקִין. בָּא עֵד אֶחָד וְהֵעִיד שֶׁזִּנְּתָה אַחַר קִנּוּי וּסְתִירָה [וְנִמְצָא אוֹתוֹ הָעֵד זוֹמֵם מְשַׁלֵּם כְּתֻבָּתָהּ. הָיוּ שְׁנַיִם וְהֵן עֵדֵי הַקִּנּוּי וְהַסְּתִירָה וְהַטֻּמְאָה] וְנִמְצְאוּ זוֹמְמִין מְשַׁלְּמִין כְּנֶגֶד הַכְּתֻבָּה וְאֵין לוֹקִין. וְלָמָּה לֹא יֵהָרְגוּ וַהֲרֵי הֵעִידוּ בַּטֻּמְאָה. לְפִי שֶׁלֹּא הִתְרוּ בָּהּ:","שְׁנַיִם שֶׁהֵעִידוּ עַל זֶה שֶׁגָּנַב וְטָבַח אוֹ מָכַר וְהוּזַמּוּ מְשַׁלְּמִין אֶת הַכּל. הֵעִידוּ שְׁנַיִם שֶׁגָּנַב וְהֵעִידוּ שְׁנַיִם אֲחֵרִים שֶׁטָּבַח אוֹ מָכַר וְהוּזַמּוּ אֵלּוּ וְאֵלּוּ. הֲרֵי הָרִאשׁוֹנִים מְשַׁלְּמִין תַּשְׁלוּמֵי כֶּפֶל וְאַחֲרוֹנִים מְשַׁלְּמִין שְׁנַיִם וּשְׁלֹשָׁה. הוּזַמּוּ הָאַחֲרוֹנִים בִּלְבַד הֲרֵי הַגַּנָּב מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְהָעֵדִים הָאַחֲרוֹנִים מְשַׁלְּמִין לַגַּנָּב תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. נִמְצָא אֶחָד מִן הָאַחֲרוֹנִים זוֹמֵם בָּטְלָה עֵדוּת שְׁנִיָּה. נִמְצָא אֶחָד מִן הָרִאשׁוֹנִים זוֹמֵם בָּטְלָה כָּל הָעֵדוּת שֶׁאִם אֵין גְּנֵבָה אֵין הַטְּבִיחָה אוֹ הַמְּכִירָה מְחַיַּבְתּוֹ לְשַׁלֵּם כְּלוּם:","שְׁנַיִם שֶׁהֵעִידוּ שֶׁאָכַל שָׂדֶה זוֹ שָׁלֹשׁ שָׁנִים וְנִמְצְאוּ זוֹמְמִין מְשַׁלְּמִין לְבַעַל הַשָּׂדֶה דְּמֵי הַשָּׂדֶה. הֵעִידוּ שְׁנַיִם שֶׁאֲכָלָהּ שָׁנָה רִאשׁוֹנָה וּשְׁנַיִם שֶׁאֲכָלָהּ שָׁנָה שְׁנִיָּה וּשְׁנַיִם שֶׁאֲכָלָהּ שָׁנָה שְׁלִישִׁית וְהוּזַמּוּ כֻּלָּן מְשַׁלְּשִׁין בֵּינֵיהֶן. שֶׁאַף עַל פִּי שֶׁעֵדוּת הַחֲזָקָה שָׁלֹשׁ עֵדֻיּוֹת הֵן הֲרֵי הֵן כְּעֵדוּת אַחַת לַהֲזָמָה. לְפִיכָךְ שְׁלֹשָׁה אַחִים וְאֶחָד מִצְטָרֵף עִם כָּל אֶחָד וְאֶחָד וְהֵעִידוּ בְּשָׁנָה שָׁנָה הֲרֵי אֵלּוּ שָׁלֹשׁ עֵדֻיּוֹת וְתִתְקַיֵּם בָּהֶן הַחֲזָקָה וְהֵן כְּעֵדוּת אַחַת לַהֲזָמָה. שֶׁאִם הוּזַמּוּ כֻּלָּן הֲרֵי שְׁלֹשָׁה הָאַחִין מְשַׁלְּמִין חֲצִי דְּמֵי הַשָּׂדֶה וְזֶה שֶׁנִּצְטָרֵף עִם כָּל אֶחָד מֵהֶן מְשַׁלֵּם חֲצִי דָּמֶיהָ:","שָׁלֹשׁ כִּתֵּי עֵדִים שֶׁנִּתְקַיֵּם בְּעֵדוּתָן שֶׁשּׁוֹר זֶה מוּעָד וְנִמְצֵאת כַּת רִאשׁוֹנָה וּשְׁנִיָּה זוֹמְמִין כֻּלָּן פְּטוּרִין. נִמְצְאוּ שְׁלָשְׁתָּן זוֹמְמִין כֻּלָּן חַיָּבִין לְשַׁלֵּם הַנֵּזֶק שֶׁאַף עַל פִּי שֶׁהוּא תָּם מְשַׁלֵּם חֲצִי נֵזֶק. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ כֻּלָּן רוֹמְזִין זֶה אֶת זֶה. אוֹ שֶׁבָּאוּ רְצוּפִין. אוֹ שֶׁהָיוּ מַכִּירִין בַּעַל הַשּׁוֹר וְלֹא הִכִּירוּ הַשּׁוֹר. אֲבָל אִם אֵין שָׁם אַחַת מֵאֵלּוּ הֲרֵי כַּת רִאשׁוֹנָה וּשְׁנִיָּה פְּטוּרִין שֶׁהֲרֵי הֵן אוֹמְרִין לֹא בָּאנוּ אֶלָּא לְחַיְּבוֹ חֲצִי נֵזֶק וְלֹא יָדַעְנוּ שֶׁתָּבוֹא כַּת אַחֶרֶת וְיֵעָשֶׂה מוּעָד:","וְכֵן שְׁנַיִם שֶׁהֵעִידוּ בְּבֵן סוֹרֵר וּמוֹרֶה עֵדוּת הָרִאשׁוֹנָה וּבָאוּ שְׁנַיִם אַחֲרֵיהֶם וְהֵעִידוּ עָלָיו עֵדוּת הָאַחֲרוֹנָה שֶׁבָּהּ יֵהָרֵג וְהוּזַמּוּ שְׁתֵּיהֶן. כַּת הָרִאשׁוֹנָה לוֹקָה וְאֵינָהּ נֶהֱרֶגֶת מִפְּנֵי שֶׁיְּכוֹלִים לוֹמַר לְהַלְקוֹתוֹ בָּאנוּ. אֲבָל כַּת הָאַחֲרוֹנָה נֶהֱרֶגֶת שֶׁעַל פִּיהֶן בִּלְבַד הוּא נֶהֱרָג. הָיְתָה הַכַּת הָאַחֲרוֹנָה אַרְבָּעָה שְׁנַיִם אוֹמְרִים בְּפָנֵינוּ גָּנַב וּשְׁנַיִם אוֹמְרִים בְּפָנֵינוּ אָכַל וְהוּזַמּוּ כֻּלָּן נֶהֱרָגִין. הֵעִידוּ שְׁנַיִם שֶׁזֶּה גָּנַב נֶפֶשׁ מִיִּשְׂרָאֵל וּמְכָרוֹ וְהוּזַמּוּ הֲרֵי אֵלּוּ נֶחְנָקִין. הֵעִידוּ שְׁנַיִם שֶׁגְּנָבוֹ וְהֵעִידוּ שְׁנַיִם אֲחֵרִים שֶׁמְּכָרוֹ. בֵּין שֶׁהוּזַמּוּ עֵדֵי גְּנֵבָה בֵּין שֶׁהוּזַמּוּ עֵדֵי מְכִירָה כָּל כַּת מֵהֶן שֶׁהוּזַמָּה נֶהֱרֶגֶת. שֶׁהַגְּנֵבָה הִיא תְּחִלַּת חִיּוּבוֹ שֶׁל זֶה לְמִיתָה. הֵעִידוּ שְׁנַיִם שֶׁמְּכָרוֹ לְזֶה הַיִּשְׂרָאֵל וְהוּזַמּוּ וְלֹא הָיוּ שָׁם עֵדִים שֶׁגְּנָבוֹ הֲרֵי אֵלּוּ פְּטוּרִין. שֶׁאֲפִלּוּ לֹא הוּזַמּוּ לֹא הָיָה זֶה נֶהֱרָג מִפְּנֵי שֶׁיָּכוֹל לוֹמַר עַבְדִּי מָכַרְתִּי. בָּאוּ עֵדֵי גְּנֵבָה אַחַר שֶׁהוּזַמּוּ עֵדֵי מְכִירָה אֲפִלּוּ רָאִינוּ אוֹתָן רוֹמְזִין זֶה אֶת זֶה אֵין נֶהֱרָגִין:","מוֹצִיא שֵׁם רַע עַל אִשְׁתּוֹ שֶׁהֵבִיא עֵדִים שֶׁזִּנְּתָה כְּשֶׁהִיא אֲרוּסָה וְהֵבִיא אָבִיהָ עֵדִים וֶהֱזִימוּם הֲרֵי עֵדֵי הַבַּעַל נֶהֱרָגִין. חָזַר הַבַּעַל וְהֵבִיא עֵדִים וְהֵזִימוּ עֵדֵי הָאָב. הֲרֵי עֵדֵי הָאָב נֶהֱרָגִין וּמְשַׁלְּמִין מָמוֹן לַבַּעַל. נֶהֱרָגִין מִפְּנֵי שֶׁעֵדֵי הַבַּעַל נִגְמַר דִּינָם לַהֲרִיגָה בְּעֵדוּתָן וּמְשַׁלְּמִין קְנָס מִפְּנֵי שֶׁנִּגְמַר דִּין הַבַּעַל לְשַׁלֵּם קְנָס בְּעֵדוּתָן וְנִמְצְאוּ חַיָּבִין נְפָשׁוֹת לָזֶה וּמָמוֹן לָזֶה. וְכֵן שְׁנַיִם שֶׁהֵעִידוּ עַל זֶה שֶׁבָּא עַל נַעֲרָה הַמְאֹרָסָה וְהוּזְמוּ נֶהֱרָגִין וְאֵין מְשַׁלְּמִין. בָּא עַל בִּתּוֹ שֶׁל פְּלוֹנִי וְהוּזַמּוּ נֶהֱרָגִין וּמְשַׁלְּמִין הַקְּנָס לְאָבִיהָ. פְּלוֹנִי רָבַע הַשּׁוֹר וְהוּזַמּוּ נִסְקָלִין וְאֵין מְשַׁלְּמִין. שׁוֹרוֹ שֶׁל פְּלוֹנִי נִסְקָלִין וּמְשַׁלְּמִין דְּמֵי הַשּׁוֹר לְבַעַל הַשּׁוֹר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, The Chosen Temple 4":["אֶבֶן הָיְתָה בְּקֹדֶשׁ הַקָּדָשִׁים בְּמַעֲרָבוֹ שֶׁעָלֶיהָ הָיָה הָאָרוֹן מֻנָּח. וּלְפָנָיו צִנְצֶנֶת הַמָּן וּמַטֵּה אַהֲרֹן. וּבְעֵת שֶׁבָּנָה שְׁלֹמֹה אֶת הַבַּיִת וְיָדַע שֶׁסּוֹפוֹ לֵחָרֵב בָּנָה בּוֹ מָקוֹם לִגְנֹז בּוֹ הָאָרוֹן לְמַטָּה בְּמַטְמוֹנִיּוֹת עֲמֻקוֹת וַעֲקַלְקַלּוֹת וְיֹאשִׁיָּהוּ הַמֶּלֶךְ צִוָּה וּגְנָזוֹ בַּמָּקוֹם שֶׁבָּנָה שְׁלֹמֹה שֶׁנֶּאֱמַר (דברי הימים ב לה ג) \"וַיֹּאמֶר לַלְוִיִּם הַמְּבִינִים לְכָל יִשְׂרָאֵל הַקְּדוֹשִׁים לַה' תְּנוּ אֶת אֲרוֹן הַקֹּדֶשׁ בַּבַּיִת אֲשֶׁר בָּנָה שְׁלֹמֹה בֶן דָּוִיד מֶלֶךְ יִשְׂרָאֵל אֵין לָכֶם מַשָּׂא בַּכָּתֵף עַתָּה עִבְדוּ אֶת ה' אֱלֹהֵיכֶם\" וְגוֹ'. וְנִגְנַז עִמּוֹ מַטֵּה אַהֲרֹן וְהַצִּנְצֶנֶת וְשֶׁמֶן הַמִּשְׁחָה וְכָל אֵלּוּ לֹא חָזְרוּ בְּבַיִת שֵׁנִי. וְאַף אוּרִים וְתֻמִּים שֶׁהָיוּ בְּבַיִת שֵׁנִי לֹא הָיוּ מְשִׁיבִין בְּרוּחַ הַקֹּדֶשׁ. וְלֹא הָיוּ נִשְׁאָלִין בָּהֶן שֶׁנֶּאֱמַר (עזרא ב סג) (נחמיה ז סה) \"עַד עֲמֹד כֹּהֵן לְאוּרִים וְתֻמִּים\". וְלֹא הָיוּ עוֹשִׂין אוֹתָן אֶלָּא לְהַשְׁלִים שְׁמוֹנָה בְּגָדִים לְכֹהֵן גָּדוֹל כְּדֵי שֶׁלֹּא יְהֵא מְחֻסַּר בְּגָדִים:","בְּבַיִת רִאשׁוֹן הָיָה כֹּתֶל מַבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקָּדָשִׁים עָבְיוֹ אַמָּה. וְכֵיוָן שֶׁבָּנוּ הַבַּיִת שֵׁנִי נִסְתַּפֵּק לָהֶם אִם עֳבִי הַכֹּתֶל הָיָה מִמִּדַּת הַקֹּדֶשׁ אוֹ מִמִּדַּת קֹדֶשׁ הַקָּדָשִׁים לְפִיכָךְ עָשׂוּ קֹדֶשׁ הַקָּדָשִׁים עָבְיוֹ עֶשְׂרִים אַמָּה תְּמִימוֹת וְעָשׂוּ הַקֹּדֶשׁ אַרְבָּעִים אַמָּה תְּמִימוֹת וְהִנִּיחוּ אַמָּה יְתֵרָה בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקָּדָשִׁים וְלֹא בָּנוּ כֹּתֶל בְּבַיִת שֵׁנִי אֶלָּא עָשׂוּ שְׁתֵּי פָּרוֹכוֹת אַחַת מִצַּד קֹדֶשׁ הַקָּדָשִׁים וְאַחַת מִצַּד הַקֹּדֶשׁ וּבֵינֵיהֶן אַמָּה כְּנֶגֶד עֳבִי הַכֹּתֶל שֶׁהָיָה בָּרִאשׁוֹן. אֲבָל בְּמִקְדָּשׁ רִאשׁוֹן לֹא הָיְתָה שָׁם אֶלָּא פָרֹכֶת אַחַת בִּלְבַד שֶׁנֶּאֱמַר (שמות כו לג) \"וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם\" וְגוֹ':","הַהֵיכָל שֶׁבָּנוּ בְּנֵי גּוֹלָה הָיָה מֵאָה אַמָּה עַל מֵאָה אַמָּה עַל רוּם מֵאָה. וְכֵן הָיְתָה מִדַּת רוּמוֹ. בָּנוּ גֹּבַהּ שֵׁשׁ אַמּוֹת אָטוּם סָתוּם כְּמוֹ יְסוֹד לוֹ. וְרוּם כָּתְלֵי הַבַּיִת אַרְבָּעִים אַמָּה וְרוּם הַכִּיּוּר שֶׁבַּתִּקְרָה אַמָּה וְעַל גַּבָּיו גֹּבַהּ שְׁתֵּי אַמּוֹת פָּנוּי שֶׁיִּכָּנֵס בּוֹ הַדֶּלֶף וְהוּא הַנִּקְרָא בֵּית דִּילְפָא. וָעֳבִי הַתִּקְרָה שֶׁעַל גַּבֵּי בֵּית דִּילְפָא אַמָּה. וּמַעֲזִיבָה גֹּבַהּ אַמָּה. וַעֲלִיָּה בְּנוּיָה עַל גַּבָּיו גֹּבַהּ כְּתָלֶיהָ אַרְבָּעִים אַמָּה. וּבְגַגָּהּ גֹּבַהּ אַמָּה כִּיּוּר וְאַמָּתַיִם גֹּבַהּ בֵּית דִּילְפָא וְאַמָּה תִּקְרָה וְאַמָּה מַעֲזִיבָה וְגֹבַהּ הַמַּעֲקֶה שָׁלֹשׁ אַמּוֹת וְטַס שֶׁל בַּרְזֶל כְּמוֹ סַיִף גָּבְהוֹ אַמָּה עַל גַּבֵּי הַמַּעֲקֶה סָבִיב כְּדֵי שֶׁלֹּא יָנוּחוּ עָלָיו הָעוֹפוֹת וְהוּא הַנִּקְרָא כָּלֶה עוֹרֵב. הֲרֵי הַכּל מֵאָה אַמָּה:","מִן הַמַּעֲרָב לַמִּזְרָח מֵאָה אַמָּה וְזֶהוּ חֶשְׁבּוֹנָן. אַרְבָּעָה כְּתָלִים זֶה לְפָנִים מִזֶּה וּבֵינֵיהֶן שְׁלֹשָׁה מְקוֹמוֹת פְּנוּיִין. בֵּין הַכֹּתֶל הַמַּעֲרָבִי וּבֵין הַכֹּתֶל שֶׁלְּפָנִים מִמֶּנּוּ חָמֵשׁ אַמּוֹת וּבֵין כֹּתֶל שֵׁנִי וּשְׁלִישִׁי שֵׁשׁ אַמּוֹת וּבֵין כֹּתֶל שְׁלִישִׁי וּרְבִיעִי שֵׁשׁ אַמּוֹת. וְאֵלּוּ הַמִּדּוֹת הֵן שֶׁל עֳבִי הַכֹּתֶל עִם הַמָּקוֹם הַפָּנוּי שֶׁבֵּין שְׁנֵי כְּתָלִים. וְאֹרֶךְ קֹדֶשׁ הַקָּדָשִׁים עֶשְׂרִים אַמָּה. וּבֵין שְׁתֵּי הַפָּרוֹכוֹת הַמַּבְדִּילוֹת בֵּינוֹ וּבֵין הַקֹּדֶשׁ אַמָּה. וְאֹרֶךְ הַקֹּדֶשׁ אַרְבָּעִים אַמָּה. וָעֳבִי הַכֹּתֶל הַמִּזְרָחִי שֶׁבּוֹ הַשַּׁעַר שֵׁשׁ אַמּוֹת וְהָאוּלָם אַחַת עֶשְׂרֵה אַמָּה. וָעֳבִי כֹּתֶל הָאוּלָם חָמֵשׁ אַמּוֹת. נִמְצָא הַכּל מֵאָה אַמָּה:","מִן הַצָּפוֹן לַדָּרוֹם מֵאָה אַמָּה. עֳבִי כֹּתֶל הָאוּלָם חָמֵשׁ אַמּוֹת. וּמִכֹּתֶל אוּלָם עַד כֹּתֶל הַקֹּדֶשׁ עֶשֶׂר אַמּוֹת. וְכָתְלֵי הַקֹּדֶשׁ שִׁשָּׁה כְּתָלִים זֶה לְפָנִים מִזֶּה וּבֵינֵיהֶן חֲמִשָּׁה מְקוֹמוֹת פְּנוּיִין. בֵּין כֹּתֶל חִיצוֹן וּבֵין הַשֵּׁנִי חָמֵשׁ אַמּוֹת. וּבֵין שֵׁנִי וּשְׁלִישִׁי שָׁלֹשׁ אַמּוֹת. וְחָמֵשׁ בֵּין שְׁלִישִׁי וּרְבִיעִי. וּבֵין רְבִיעִי וַחֲמִישִׁי שֵׁשׁ. וּבֵין חֲמִישִׁי וְכֹתֶל הַפְּנִימִי שֵׁשׁ. נִמְצָא הַכּל אַרְבָּעִים אַמָּה מִצַּד זֶה וְאַרְבָּעִים אַמָּה מִצַּד שֶׁכְּנֶגְדוֹ וְרֹחַב הַבַּיִת מִבִּפְנִים עֶשְׂרִים. הֲרֵי מֵאָה אַמָּה:","הַפִּשְׁפָּשׁ וְהוּא שַׁעַר הַקָּטָן. וּשְׁנֵי פִּשְׁפָּשִׁין הָיוּ לַהֵיכָל מִצִּדֵּי הַשַּׁעַר הַגָּדוֹל שֶׁבְּאֶמְצַע. אֶחָד בַּצָּפוֹן וְאֶחָד בַּדָּרוֹם. שֶׁבַּדָּרוֹם לֹא נִכְנַס בּוֹ אָדָם מֵעוֹלָם וְעָלָיו הוּא מְפֹרָשׁ עַל יְדֵי יְחֶזְקֵאל (יחזקאל מד ב) \"הַשַּׁעַר הַזֶּה סָגוּר יִהְיֶה לֹא יִפָּתֵחַ\". וְשֶׁבַּצָּפוֹן בּוֹ נִכְנָסִין. וּמְהַלֵּךְ בֵּין שֵׁנִי הַכְּתָלִים עַד שֶׁמַּגִּיעַ לְמָקוֹם פָּתוּחַ לַקֹּדֶשׁ מִשְּׂמֹאלוֹ וְנִכְנָס לְתוֹךְ הַהֵיכָל וּמְהַלֵּךְ עַד שַׁעַר הַגָּדוֹל וּפוֹתְחוֹ:","הַשַּׁעַר הַגָּדוֹל הָיָה רָחְבּוֹ עֶשֶׂר אַמּוֹת וְגָבְהוֹ עֶשְׂרִים אַמָּה. וְאַרְבַּע דַּלְתוֹת הָיוּ לוֹ שְׁתַּיִם בִּפְנִים וּשְׁתַּיִם בַּחוּץ. הַחִיצוֹנוֹת נִפְתָּחוֹת לְתוֹךְ הַפֶּתַח לְכַסּוֹת עָבְיוֹ שֶׁל כֹּתֶל וְהַפְּנִימִיּוֹת נִפְתָּחוֹת לְתוֹךְ הַבַּיִת לְכַסּוֹת אֲחוֹרֵי הַדְּלָתוֹת:","פִּתְחוֹ שֶׁל אוּלָם הָיָה גָּבוֹהַּ אַרְבָּעִים אַמָּה וְרֹחַב עֶשְׂרִים. וְלֹא הָיָה לוֹ שְׁעָרִים. וְחָמֵשׁ מַלְתְּרִיּוֹת שֶׁל מִילָא הָיוּ עַל גַּבֵּי פִּתְחוֹ מִלְּמַעְלָה. הַתַּחְתּוֹנָה עוֹדֶפֶת עַל הַפֶּתַח אַמָּה מִזֶּה וְאַמָּה מִזֶּה. וְכָל אַחַת מֵחֲמִשְׁתָּן עוֹדֶפֶת עַל שֶׁלְּמַטָּה מִמֶּנָּה אַמָּה מִזֶּה וְאַמָּה מִזֶּה. נִמְצֵאת הָעֶלְיוֹנָה שְׁלֹשִׁים אַמָּה. וְנִדְבָּךְ שֶׁל אֲבָנִים הָיָה בֵּין כָּל אַחַת וְאַחַת:","הַהֵיכָל הָיָה בִּנְיָנוֹ רָחָב מִלְּפָנָיו וְצַר מֵאֲחוֹרָיו כְּמוֹ אֲרִי. וִיצִיעִים הָיוּ מַקִּיפִין לַבַּיִת כֻּלּוֹ מִסָּבִיב חוּץ לְכֹתֶל הַמְּסִבָּה. וְיָצִיעַ הַתַּחְתּוֹנָה חָמֵשׁ וְרֹבֶד עַל גַּבָּהּ שֵׁשׁ וְיָצִיעַ אֶמְצָעִית שֵׁשׁ וְרֹבֶד עַל גַּבָּהּ שֶׁבַע וְהָעֶלְיוֹנָה שֶׁבַע שֶׁנֶּאֱמַר (מלכים א ו ו) \"הַיָּצִיעַ הַתַּחְתֹּנָה\" וְגוֹ'. וְכֵן הָיוּ הַשָּׁלֹשׁ יְצִיעִים מַקִּיפִים לַבַּיִת מִשְּׁלֹשָׁה רוּחוֹתָיו וְכֵן סָבִיב לְכָתְלֵי הָאוּלָם מִלְּמַטָּה עַד לְמַעְלָה כָּךְ הָיוּ אַמָּה אַחַת חָלָק וְרֹבֶד שָׁלֹשׁ אַמּוֹת. וְאַמָּה חָלָק וְרֹבֶד שָׁלֹשׁ אַמּוֹת עַד לְמַעְלָה. וְנִמְצְאוּ הָרְבָדִין מֻקָּפִין לַכְּתָלִים. רֹחַב כָּל רֹבֶד שָׁלֹשׁ אַמּוֹת עַד לְמַעְלָה. וּבֵין כָּל רֹבֶד וְרֹבֶד אַמָּה. וְרֹבֶד הָעֶלְיוֹן הָיָה רָחְבּוֹ אַרְבַּע אַמּוֹת:","כָּל אֵלּוּ הַמְּקוֹמוֹת הַפְּנוּיִים שֶׁבֵּין הַכְּתָלִים הֵם הַנִּקְרָאִים תָּאִים. נִמְצְאוּ הַתָּאִים הַמֻּקָּפִין לַמִּקְדָּשׁ חֲמִשָּׁה מִן הַצָּפוֹן וַחֲמִשָּׁה מִן הַדָּרוֹם וּשְׁלֹשָׁה מִן הַמַּעֲרָב. וְשָׁלֹשׁ דְּיוֹטוֹת הָיוּ דְּיוֹטָא עַל גַּבֵּי דְּיוֹטָא. נִמְצְאוּ ט\"ו תָּאִים בַּדָּרוֹם חֲמִשָּׁה עַל גַּבֵּי חֲמִשָּׁה וַחֲמִשָּׁה עַל גַּבֵּיהֶן וְכֵן בַּצָּפוֹן חֲמִשָּׁה עָשָׂר. וּשְׁמוֹנָה תָּאִים הָיוּ בַּמַּעֲרָב שְׁלֹשָׁה עַל גַּבֵּי שְׁלֹשָׁה וּשְׁנַיִם עַל גַּבֵּיהֶן בִּדְיוֹטָא אַחַת הַכּל ל\"ח תָּאִים:","שְׁלֹשָׁה פְּתָחִים הָיוּ לְכָל אֶחָד וְאֶחָד מִן הַתָּאִים. אֶחָד לַתָּא מִן הַיָּמִין. וְאֶחָד לַתָּא מִן הַשְּׂמֹאל. וְאֶחָד לַתָּא שֶׁעַל גַּבָּיו. וּבְקֶרֶן מִזְרָחִית צְפוֹנִית בַּתָּא שֶׁבַּדְּיוֹטָא הָאֶמְצָעִית הָיוּ חֲמִשָּׁה פְּתָחִים. אֶחָד לַתָּא מִיָּמִין. וְאֶחָד לַתָּא שֶׁעַל גַּבָּיו. וְאֶחָד לַמְּסִבָּה. וְאֶחָד לַתָּא שֶׁיֵּשׁ בּוֹ הַפִּשְׁפָּשׁ. וְאֶחָד לַהֵיכָל:","וּמְסִבָּה הָיְתָה עוֹלָה מִקֶּרֶן מִזְרָחִית צְפוֹנִית לְקֶרֶן צְפוֹנִית מַעֲרָבִית שֶׁבָּהּ הָיוּ עוֹלִין לְגַגּוֹת הַתָּאִים. הָיָה עוֹלֶה בַּמְּסִבָּה וּפָנָיו לַמַּעֲרָב הָלַךְ אֶת כָּל פְּנֵי הַצָּפוֹן עַד שֶׁהוּא מַגִּיעַ לַמַּעֲרָב. הִגִּיעַ לַמַּעֲרָב הָפַךְ פָּנָיו לַדָּרוֹם הָלַךְ אֶת כָּל פְּנֵי הַמַּעֲרָב עַד שֶׁהוּא מַגִּיעַ לַדָּרוֹם. הִגִּיעַ לַדָּרוֹם הָפַךְ פָּנָיו לַמִּזְרָח וְהָיָה מְהַלֵּךְ לַדָּרוֹם עַד שֶׁהוּא מַגִּיעַ לְפִתְחָהּ שֶׁל עֲלִיָּה שֶׁפִּתְחָהּ שֶׁל עֲלִיָּה הָיָה פָּתוּחַ לַדָּרוֹם:","וּבְפִתְחָהּ שֶׁל עֲלִיָּה הָיוּ שְׁתֵּי כְּלוּנְסוֹת שֶׁל אֶרֶז שֶׁבָּהֶן עוֹלִין לְגַגָּהּ שֶׁל עֲלִיָּה. וְרָאשֵׁי פִּסְפְּסִין הָיוּ מַבְדִּילִין בַּעֲלִיָּה בֵּין גַּג הַקֹּדֶשׁ לְגַג קֹדֶשׁ הַקָּדָשִׁים. וְלוּלִין הָיוּ פְּתוּחִין בָּעֲלִיָּה לְבֵית קֹדֶשׁ הַקָּדָשִׁים שֶׁבָּהֶן מְשַׁלְשְׁלִין אֶת הָאֻמָּנִין בְּתֵבוֹת כְּדֵי שֶׁלֹּא יָזוּנוּ עֵינֵיהֶם מִבֵּית קֹדֶשׁ הַקָּדָשִׁים. וּפַעַם אַחַת בְּשָׁנָה מִפֶּסַח לְפֶסַח מְלַבְּנִין אֶת הַהֵיכָל:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 11":["מַה בֵּין דִּינֵי מָמוֹנוֹת לְדִינֵי נפָשׁוֹת. דִּינֵי מָמוֹנוֹת בִּשְׁלֹשָׁה דִּינֵי נְפָשׁוֹת בְּעֶשְׂרִים וּשְׁלֹשָׁה. דִּינֵי מָמוֹנוֹת פּוֹתְחִין בֵּין לִזְכוּת בֵּין לְחוֹבָה דִּינֵי נְפָשׁוֹת פּוֹתְחִין לִזְכוּת כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵין פּוֹתְחִין לְחוֹבָה. דִּינֵי מָמוֹנוֹת מַטִּין עַל פִּי אֶחָד בֵּין לִזְכוּת בֵּין לְחוֹבָה דִּינֵי נְפָשׁוֹת מַטִּין עַל פִּי אֶחָד לִזְכוּת וְעַל פִּי שְׁנַיִם לְחוֹבָה. דִּינֵי מָמוֹנוֹת מַחֲזִירִין בֵּין לִזְכוּת בֵּין לְחוֹבָה וְדִינֵי נְפָשׁוֹת מַחֲזִירִין לִזְכוּת וְאֵין מַחֲזִירִין לְחוֹבָה כְּמוֹ שֶׁבֵּאַרְנוּ. דִּינֵי מָמוֹנוֹת הַכּל רְאוּיִין לְלַמֵּד זְכוּת אוֹ חוֹבָה בֵּין הַדַּיָּנִים בֵּין הַתַּלְמִידִים וְדִינֵי נְפָשׁוֹת הַכּל מְלַמְּדִין זְכוּת וַאֲפִלּוּ הַתַּלְמִידִים וְאֵין מְלַמֵּד חוֹבָה אֶלָּא הַדַּיָּנִים. דִּינֵי מָמוֹנוֹת הַדַּיָּן הַמְלַמֵּד חוֹבָה חוֹזֵר וּמְלַמֵּד זְכוּת וְהַמְלַמֵּד זְכוּת חוֹזֵר וּמְלַמֵּד חוֹבָה דִּינֵי נְפָשׁוֹת הַמְלַמֵּד חוֹבָה חוֹזֵר וּמְלַמֵּד זְכוּת אֲבָל הַמְלַמֵּד זְכוּת אֵינוֹ יָכוֹל לַחְזֹר וּלְלַמֵּד חוֹבָה אֶלָּא בִּשְׁעַת גְּמַר דִּין יֵשׁ לוֹ לַחְזֹר וּלְהִמָּנוֹת עִם הַמְחַיְּבִין כְּמוֹ שֶׁבֵּאַרְנוּ. דִּינֵי מָמוֹנוֹת דָּנִין בַּיּוֹם וְגוֹמְרִין בַּלַּיְלָה דִּינֵי נְפָשׁוֹת דָּנִין בַּיּוֹם וְגוֹמְרִין בַּיּוֹם. דִּינֵי מָמוֹנוֹת גּוֹמְרִין בּוֹ בַּיּוֹם בֵּין לִזְכוּת בֵּין לְחוֹבָה דִּינֵי נְפָשׁוֹת גּוֹמְרִין בּוֹ בַּיּוֹם לִזְכוּת וּבַיּוֹם שֶׁלְּאַחֲרָיו לְחוֹבָה:","לְפִיכָךְ אֵין דָּנִין דִּינֵי נְפָשׁוֹת לֹא עֶרֶב שַׁבָּת וְלֹא עֶרֶב יוֹם טוֹב שֶׁמָּא יִתְחַיֵּב וְאִי אֶפְשָׁר לְהָרְגוֹֹ לְמָחָר וְאָסוּר לְעַנּוֹת אֶת דִּינוֹ וּלְהַנִּיחוֹ אַחַר הַשַּׁבָּת אֶלָּא אוֹסְרִין אוֹתוֹ עַד אֶחָד בְּשַׁבָּת וּמַתְחִילִין בְּדִינוֹ:","דִּינֵי מָמוֹנוֹת אַף עַל פִּי שֶׁדָּנִין אוֹתָן בְּכָל יוֹם מִן הַתּוֹרָה שֶׁנֶּאֱמַר (שמות יח כב) \"וְשָׁפְטוּ אֶת הָעָם בְּכָל עֵת\" מִדִּבְרֵיהֶם לָמְדוּ שֶׁאֵין דָּנִין בְּעֶרֶב שַׁבָּת:","אֶחָד דִּינֵי נְפָשׁוֹת וְאֶחָד דִּינֵי מַלְקִיּוֹת וְאֶחָד דִּינֵי גָּלוּת הַדִּינִים הָאֵלּוּ שָׁוִים בָּהֶן אֶלָּא שֶׁהַמַּלְקוֹת בִּשְׁלֹשָׁה וְאֵין אֶחָד מֵהֶן בְּשׁוֹר הַנִּסְקָל חוּץ מִדָּבָר אֶחָד שֶׁדִּינוֹ בְּעֶשְׂרִים וּשְׁלֹשָׁה:","הַמַּסִּית אֵין דִּינָיו כִּשְׁאָר דִּינֵי נְפָשׁוֹת. מְכַמְנִין לוֹ אֶת הָעֵדִים. וְאֵינוֹ צָרִיךְ הַתְרָאָה כִּשְׁאָר הַנֶּהֱרָגִין. וְאִם יָצָא מִבֵּית דִּין זַכַּאי וְאָמַר אֶחָד יֵשׁ לִי לְלַמֵּד עָלָיו חוֹבָה מַחֲזִירִין אוֹתוֹ. יָצָא חַיָּב וְאָמַר אֶחָד יֵשׁ לִי לְלַמֵּד עָלָיו זְכוּת אֵין מַחֲזִירִין אוֹתוֹ. וְאֵין טוֹעֲנִין לְמַסִּית. וּמוֹשִׁיבִין בְּדִינוֹ זָקֵן וְסָרִיס וּמִי שֶׁאֵין לוֹ בָּנִים כְּדֵי שֶׁלֹּא יְרַחֲמוּ עָלָיו. שֶׁהָאַכְזָרִיּוּת עַל אֵלּוּ שֶׁמַּטְעִין אֶת הָעָם אַחֲרֵי הַהֶבֶל רַחֲמִים הוּא בָּעוֹלָם שֶׁנֶּאֱמַר (דברים יג יח) \"לְמַעַן יָשׁוּב ה' מֵחֲרוֹן אַפּוֹ וְנָתַן לְךָ רַחֲמִים\":","דִּינֵי מָמוֹנוֹת וְכֵן הַטֻּמְאוֹת וְהַטָּהֳרוֹת מַתְחִילִין מִן הַגָּדוֹל שֶׁבַּדַּיָּנִים וְשׁוֹמְעִין אֶת דְּבָרָיו. וְדִינֵי נְפָשׁוֹת מַתְחִילִין מִן הַצַּד וְאֵין שׁוֹמְעִין דִּבְרֵי הַגָּדוֹל אֶלָּא בָּאַחֲרוֹנָה:","דִּינֵי מָמוֹנוֹת וְכֵן הַטֻּמְאוֹת וְכֵן הַטָּהֳרוֹת הָאָב וּבְנוֹ הָרַב וְתַלְמִידוֹ מוֹנִין אוֹתָן בִּשְׁנַיִם. וְדִינֵי נְפָשׁוֹת וּמַכּוֹת וְקִדּוּשׁ הַחֹדֶשׁ וְעִבּוּר הַשָּׁנָה אָב וּבְנוֹ אוֹ הָרַב וְתַלְמִידוֹ מוֹנִין אוֹתָן בְּאֶחָד:","זֶה שֶׁאָנוּ מוֹנִין הָאָב עִם הַבֵּן בֵּין בְּאֶחָד בֵּין בִּשְׁנַיִם כְּגוֹן שֶׁהָיָה הָאֶחָד מֵהֶן בַּסַּנְהֶדְרִין וְהַשֵּׁנִי הָיָה מִן הַתַּלְמִידִים שֶׁאָמַר יֵשׁ לִי לְלַמֵּד זְכוּת אוֹ חוֹבָה שׁוֹמְעִין דְּבָרָיו וְנוֹשְׂאִין וְנוֹתְנִין עִמּוֹ וְנִמְנִין עִמּוֹ:","וּבִשְׁעַת גְּמַר דִּין אֵין גּוֹמְרִין אֶת הַדִּין בִּקְרוֹבִים שֶׁהַדַּיָּנִין הַקְּרוֹבִים פְּסוּלִין לְדִין כְּמוֹ שֶׁיִּתְבָּאֵר:","תַּלְמִיד שֶׁהָיָה חָכָם וּמֵבִין וְהָיָה מְחֻסָּר קַבָּלָה הֲרֵי רַבּוֹ מוֹסֵר לוֹ הַקַּבָּלָה שֶׁהוּא צָרִיךְ לָהּ בְּדִין זֶה וְהוּא דָּן עִמּוֹ בְּדִינֵי נְפָשׁוֹת:","הַכּל כְּשֵׁרִים לָדוּן דִּינֵי מָמוֹנוֹת אֲפִלּוּ גֵּר וְהוּא שֶׁתִּהְיֶה אִמּוֹ מִיִּשְׂרָאֵל. וְגֵר דָּן אֶת חֲבֵרוֹ הַגֵּר אַף עַל פִּי שֶׁאֵין אִמּוֹ מִיִּשְׂרָאֵל וְכֵן הַמַּמְזֵר וְהַסּוּמָא בְּאַחַת מֵעֵינָיו כָּשֵׁר לָדוּן דִּינֵי מָמוֹנוֹת. אֲבָל בְּדִינֵי נְפָשׁוֹת אֵין דָּנִין אוֹתָן אֶלָּא כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים הַמַּשִּׂיאִין לִכְהֻנָּה וְלֹא יִהְיֶה אֶחָד מֵהֶן סוּמָא אֲפִלּוּ בְּאַחַת מֵעֵינָיו כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 22":["שְׁנַּיִם שֶׁבָּאוּ לְפָנֶיךָ לְדִין אֶחָד רַךְ וְאֶחָד קָשֶׁה. עַד שֶׁלֹּא תִּשְׁמַע אֶת דִּבְרֵיהֶם אוֹ מִשֶּׁתִּשְׁמַע אֶת דִּבְרֵיהֶם וְאִי אַתָּה יוֹדֵעַ לְהֵיכָן הַדִּין נוֹטֶה אַתָּה רַשַּׁאי לוֹמַר לָהֶם אֵינִי נִזְקָק לָכֶם שֶׁמָּא יִתְחַיֵּב הַקָּשֶׁה וְנִמְצָא רוֹדֵף אַחַר הַדַּיָּן. אֲבָל מִשֶּׁתִּשְׁמַע אֶת דִּבְרֵיהֶם וְתֵדַע לְהֵיכָן הַדִּין נוֹטֶה אִי אַתָּה רַשַּׁאי לוֹמַר אֵינִי נִזְקָק לָכֶם. שֶׁנֶּאֱמַר (דברים א יז) \"לֹא תָגוּרוּ מִפְּנֵי אִישׁ\" שֶׁלֹּא תֹּאמַר אִישׁ פְּלוֹנִי רָשָׁע הוּא שֶׁמָּא יַהֲרֹג אֶת בְּנִי שֶׁמָּא יַדְלִיק אֶת גְּדִישִׁי שֶׁמָּא יְקַצֵּץ נְטִיעוֹתַי. וְאִם הָיָה מְמֻנֶּה לָרַבִּים חַיָּב לְהִזָּקֵק לָהֶם:","וְכֵן תַּלְמִיד שֶׁהָיָה יוֹשֵׁב לִפְנֵי רַבּוֹ וְרָאָה זְכוּת לֶעָנִי וְחוֹבָה לֶעָשִׁיר אִם שָׁתַק הֲרֵי זֶה עוֹבֵר מִשּׁוּם (דברים א יז) \"לֹא תָגוּרוּ מִפְּנֵי אִישׁ\" וְעַל זֶה נֶאֱמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\". וּמִנַּיִן לַדַּיָּן שֶׁלֹּא יוֹשִׁיב תַּלְמִיד בּוּר לְפָנָיו תַּלְמוּד לוֹמַר מִדְּבַר שֶׁקֶר תִּרְחָק:","וּמִנַּיִן לְתַלְמִיד שֶׁרָאָה רַבּוֹ שֶׁטּוֹעֶה בַּדִּין שֶׁלֹּא יֹאמַר אַמְתִּין לוֹ עַד שֶׁיִּגָּמֵר הַדִּין וְאֶסְתְּרֵנוּ וַאֲבִינֶנּוּ כְּדֵי שֶׁיִּקָּרֵא הַדִּין עַל שְׁמִי תַּלְמוּד לוֹמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\":","מִצְוָה לוֹמַר לְבַעֲלֵי דִּינִים בַּתְּחִלָּה בְּדִין אַתֶּם רוֹצִים אוֹ בִּפְשָׁרָה. אִם רָצוּ בִּפְשָׁרָה עוֹשִׂין בֵּינֵיהֶן פְּשָׁרָה. וְכָל בֵּית דִּין שֶׁעוֹשִׂין פְּשָׁרָה תָּמִיד הֲרֵי זֶה מְשֻׁבָּח וְעָלָיו נֶאֱמַר (זכריה ח טז) \"מִשְׁפַּט שָׁלוֹם שִׁפְטוּ בְּשַׁעֲרֵיכֶם\" אֵי זֶהוּ מִשְׁפָּט שֶׁיֵּשׁ עִמּוֹ שָׁלוֹם הֱוֵי אוֹמֵר זֶה בִּצּוּעַ. וְכֵן בְּדָוִד הוּא אוֹמֵר (שמואל ב ח טו) \"וַיְהִי דָוִד עשֶֹׁה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ\" אֵיזֶהוּ מִשְׁפָּט שֶׁיֵּשׁ עִמּוֹ צְדָקָה הֱוֵי אוֹמֵר זֶהוּ בִּצּוּעַ וְהִיא הַפְּשָׁרָה. בַּמֶּה דְּבָרִים אֲמוּרִים קֹדֶם גְּמַר דִּין אַף עַל פִּי שֶׁשָּׁמַע דִּבְרֵיהֶם וְיָדַע לְהֵיכָן הַדִּין נוֹטֶה מִצְוָה לִבְצֹעַ אֲבָל אַחֲרֵי שֶׁגָּמַר הַדִּין וְאָמַר אִישׁ פְּלוֹנִי אַתָּה זַכַּאי אִישׁ פְּלוֹנִי אַתָּה חַיָּב אֵינוֹ רַשַּׁאי לַעֲשׂוֹת פְּשָׁרָה בֵּינֵיהֶן אֶלָּא יִקֹּב הַדִּין אֶת הָהָר:","אַף עַל פִּי שֶׁרָצוּ בַּעֲלֵי הַדִּין בִּפְשָׁרָה בְּבֵית דִּין יֵשׁ לָהֶם לַחְזֹר וְלִתְבֹּעַ אֶת הַדִּין עַד שֶׁיִּקְנוּ מִיַּד שְׁנֵיהֶם:","יָפֶה כֹּחַ פְּשָׁרָה מִכֹּחַ הַדִּין שֶׁשְּׁנֵי הֶדְיוֹטוֹת שֶׁדָּנוּ אֵין דִּינֵיהֶן דִּין וְיֵשׁ לְבַעֲלֵי דִּינִין לַחְזֹר בָּהֶן וְאִם עָשׂוּ פְּשָׁרָה וְקָנוּ מִיָּדָן אֵין יְכוֹלִין לַחְזֹר בָּהֶן:","אָסוּר לְאֶחָד מִן הַדַּיָּנִים כְּשֶׁיֵּצֵא מִבֵּית דִּין לוֹמַר אֲנִי הוּא הַמְזַכֶּה אוֹ הַמְחַיֵּב וַחֲבֵרַי חוֹלְקִין עָלַי אֲבָל מָה אֶעֱשֶׂה שֶׁהֵם רַבּוּ עָלַי וְאִם אָמַר כֵּן הֲרֵי הוּא בִּכְלַל הוֹלֵךְ רָכִיל מְגַלֶּה סוֹד. וּמַעֲשֶׂה בְּתַלְמִיד אֶחָד שֶׁהוֹצִיא דְּבָרִים שֶׁנֶּאֶמְרוּ בְּבֵית הַמִּדְרָשׁ לְאַחַר שְׁתַּיִם וְעֶשְׂרִים שָׁנָה וְהוֹצִיאוּהוּ בֵּית דִּין מִבֵּית הַמִּדְרָשׁ וְהִכְרִיזוּ עָלָיו זֶה מְגַלֶּה סוֹד הוּא:","שָׁאַל אֶחָד מִבַּעֲלֵי דִּינִים לִכְתֹּב לוֹ פְּסַק דִּין כּוֹתְבִין לוֹ כָּךְ בָּא פְּלוֹנִי לְבֵית דִּין שֶׁל פְּלוֹנִי עִם פְּלוֹנִי בַּעַל דִּינוֹ שֶׁטְּעָנוֹ בְּכָךְ וְיָצָא זַכַּאי אוֹ חַיָּב וְנוֹתְנִין לוֹ וְאֵין מַזְכִּירִין שֵׁם הַמְזַכִּין וְלֹא שֵׁם הַמְחַיְּבִין אֶלָּא בֵּית דִּין שֶׁל פְּלוֹנִי מִדִּבְרֵיהֶם נִזְדַּכָּה פְּלוֹנִי:","כָּךְ הָיָה מִנְהָגָם שֶׁל אַנְשֵׁי יְרוּשָׁלַיִם. מַכְנִיסִין בַּעֲלֵי דִּינִין וְשׁוֹמְעִים דִּבְרֵיהֶם וְטַעֲנוֹתֵיהֶם וּמַכְנִיסִים הָעֵדִים וְשׁוֹמְעִים דִּבְרֵיהֶם. וּמוֹצִיאִין כָּל אָדָם לַחוּץ. וְהַדַּיָּנִים נוֹשְׂאִים וְנוֹתְנִים בֵּינֵיהֶם בַּדָּבָר וְגוֹמְרִין אֶת הַדָּבָר וְאַחַר כָּךְ מַכְנִיסִין בַּעֲלֵי דִּינִים וְגָדוֹל שֶׁבַּדַּיָּנִים אוֹמֵר אִישׁ פְּלוֹנִי אַתָּה זַכַּאי אִישׁ פְּלוֹנִי אַתָּה חַיָּב כְּדֵי שֶׁלֹּא יֵדַע אֶחָד מִבַּעֲלֵי דִּינִים אֵי זֶה דַּיָּן הוּא מִי שֶׁזִּכָּה אוֹתוֹ וְלֹא אֵי זֶה דַּיָּן הוּא שֶׁחִיְּבוֹ:","דַּיָּן שֶׁהוּא יוֹדֵעַ בַּחֲבֵרוֹ שֶׁהוּא גַּזְלָן אוֹ רָשָׁע אָסוּר לְהִצְטָרֵף עִמּוֹ שֶׁנֶּאֱמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\". וְכָךְ הָיוּ נְקִיֵּי הַדַּעַת שֶׁבִּירוּשָׁלַיִם עוֹשִׂין אֵין יוֹשְׁבִין בַּדִּין עַד שֶׁיֵּדְעוּ עִם מִי הֵם יוֹשְׁבִים וְלֹא חוֹתְמִים אֶת הַשְּׁטָר עַד שֶׁיֵּדְעוּ מִי חוֹתֵם עִמָּהֶם וְלֹא נִכְנָסִים לִסְעוּדָה עַד שֶׁיֵּדְעוּ מִי מֵסֵב עִמָּהֶן:"],"Mishneh Torah, Theft 1":["כָּל הַגּוֹנֵב מָמוֹן מִשְּׁוֵה פְּרוּטָה וּלְמַעְלָה עוֹבֵר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יא) \"לֹא תִגְנֹב\". וְאֵין לוֹקִין עַל לָאו זֶה שֶׁהֲרֵי נִתָּן לְתַשְׁלוּמִין שֶׁהַגַּנָּב חִיְּבַתּוּ תּוֹרָה לְשַׁלֵּם. וְאֶחָד הַגּוֹנֵב מָמוֹן יִשְׂרָאֵל אוֹ הַגּוֹנֵב מָמוֹן עַכּוּ\"ם וְאֶחָד הַגּוֹנֵב אֶת הַגָּדוֹל אוֹ אֶת הַקָּטָן:","אָסוּר לִגְנֹב כָּל שֶׁהוּא דִּין תּוֹרָה. וְאָסוּר לִגְנֹב דֶּרֶךְ שְׂחוֹק אוֹ לִגְנֹב עַל מְנָת לְהַחְזִיר אוֹ עַל מְנָת לְשַׁלֵּם הַכּל אָסוּר שֶׁלֹּא יַרְגִּיל עַצְמוֹ בְּכָךְ:","אֵיזֶה הוּא גַּנָּב זֶה הַלּוֹקֵחַ מָמוֹן אָדָם בַּסֵּתֶר וְאֵין הַבְּעָלִים יוֹדְעִים. כְּגוֹן הַפּוֹשֵׁט יָדוֹ לְתוֹךְ כִּיס חֲבֵרוֹ וְלָקַח מְעוֹתָיו וְאֵין הַבְּעָלִים רוֹאִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם לָקַח בְּגָלוּי וּבְפַרְהֶסְיָא בְּחֹזֶק יָד אֵין זֶה גַּנָּב אֶלָּא גַּזְלָן. לְפִיכָךְ לִסְטִים מְזֻיָּן שֶׁגָּנַב אֵינוֹ גַּזְלָן אֶלָּא גַּנָּב אַף עַל פִּי שֶׁהַבְּעָלִים יוֹדְעִים בְּשָׁעָה שֶׁגָּנַב:","גַּנָּב שֶׁהֵעִידוּ עָלָיו עֵדִים כְּשֵׁרִים שֶׁגָּנַב חַיָּב לְשַׁלֵּם שְׁנַיִם לְבַעַל הַגְּנֵבָה. אִם גָּנַב דִּינָר מְשַׁלֵּם שְׁנַיִם. גָּנַב חֲמוֹר אוֹ כְּסוּת אוֹ גָּמָל מְשַׁלֵּם שְׁנַיִם בְּדָמֶיהָ. נִמְצָא מַפְסִיד כַּשִּׁעוּר שֶׁבִּקֵּשׁ לְחַסֵּר אֶת חֲבֵרוֹ:","גַּנָּב שֶׁהוֹדָה מֵעַצְמוֹ שֶׁגָּנַב מְשַׁלֵּם אֶת הַקֶּרֶן וּפָטוּר מִן הַכֶּפֶל שֶׁנֶּאֱמַר (שמות כב ח) \"אֲשֶׁר יַרְשִׁיעֻן אֱלֹהִים יְשַׁלֵּם שְׁנַיִם\" וְלֹא הַמַּרְשִׁיעַ אֶת עַצְמוֹ מְשַׁלֵּם שְׁנַיִם. וְהוּא הַדִּין לְכָל הַקְּנָסוֹת שֶׁהַמּוֹדֶה בָּהֶן פָּטוּר:","תַּשְׁלוּמֵי כֶּפֶל נוֹהֲגִין בַּכּל חוּץ מִשֶּׂה וְשׁוֹר שֶׁהַגּוֹנֵב אֶת הַשּׁוֹר אוֹ אֶת הַשֶּׂה וְטָבַח אוֹ מָכַר מְשַׁלֵּם עַל הַשֶּׂה תַּשְׁלוּמֵי אַרְבָּעָה וְעַל הַשּׁוֹר תַּשְׁלוּמֵי חֲמִשָּׁה:","אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שֶׁגָּנְבוּ חַיָּבִין לְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. הָיְתָה אֵשֶׁת אִישׁ שֶׁאֵין לָהּ לְשַׁלֵּם הֲרֵי הַכֶּפֶל עָלֶיהָ חוֹב עַד שֶׁתִּתְגָּרֵשׁ אוֹ יָמוּת בַּעְלָהּ וּבֵית דִּין נִפְרָעִים מִמֶּנָּה:","קָטָן שֶׁגָּנַב פָּטוּר מִן הַכֶּפֶל וּמַחְזִירִין לוֹ דָּבָר הַגָּנוּב מִמֶּנּוּ. וְאִם אָבְדוּ אֵינוֹ חַיָּב לְשַׁלֵּם אַף הַקֶּרֶן וַאֲפִלּוּ לְאַחַר שֶׁהִגְדִּיל:","הָעֶבֶד שֶׁגָּנַב פָּטוּר מִן הַכֶּפֶל וּבְעָלָיו פְּטוּרִין שֶׁאֵין אָדָם חַיָּב עַל נִזְקֵי עֲבָדָיו אַף עַל פִּי שֶׁהֵן מָמוֹנוֹ מִפְּנֵי שֶׁיֵּשׁ בָּהֶן דַּעַת וְאֵינוֹ יָכוֹל לְשָׁמְרָן שֶׁאִם יַכְעִיסֶנּוּ רַבּוֹ יֵלֵךְ וְיַדְלִיק גָּדִישׁ בְּאֶלֶף דִּינָר וְכַיּוֹצֵא בָּזֶה מִשְּׁאָר נְזָקִין. נִשְׁתַּחְרֵר הָעֶבֶד חַיָּב לְשַׁלֵּם אֶת הַכֶּפֶל:","רָאוּי לְבֵית דִּין לְהַכּוֹת אֶת הַקְּטַנִּים כְּפִי כֹּחַ הַקָּטָן עַל הַגְּנֵבָה כְּדֵי שֶׁלֹּא יִהְיוּ רְגִילִין בָּהּ. וְכֵן אִם הִזִּיקוּ שְׁאָר נְזָקִין. וְכֵן מַכִּין אֶת הָעֲבָדִים שֶׁגָּנְבוּ אוֹ שֶׁהִזִּיקוּ מַכָּה רַבָּה כְּדֵי שֶׁלֹּא יִהְיוּ רְגִילִין לְהַזִּיק:","הָיְתָה הַגְּנֵבָה בְּיַד הַגַּנָּב וְהִשְׁבִּיחָה מֵאֵלֶיהָ כְּגוֹן כִּבְשָׂה שֶׁיָּלְדָה וּגְזָזָהּ מְשַׁלֵּם אוֹתָהּ וְאֶת גִּזּוֹתֶיהָ וְאֶת וַלְדוֹתֶיהָ. וְאִם אַחַר יֵאוּשׁ יָלְדָה וּגְזָזָהּ מְשַׁלֵּם כִּשְׁעַת הַגְּנֵבָה. הוֹצִיא עָלֶיהָ הוֹצָאָה וְהִשְׁבִּיחָהּ כְּגוֹן שֶׁפִּטְּמָהּ הֲרֵי הַשֶּׁבַח שֶׁל גַּנָּב אֲפִלּוּ לִפְנֵי יֵאוּשׁ. וּכְשֶׁמַּחְזִיר הַגְּנֵבָה עִם הַכֶּפֶל נוֹטֵל הַשֶּׁבַח מִן הַבְּעָלִים אוֹ מְחַשְּׁבִין לוֹ מִן הַכֶּפֶל:","הַגְּנֵבָה עַצְמָהּ שֶׁהִיא בְּיַד הַגַּנָּב וְלֹא נִשְׁתַּנֵּית חוֹזֶרֶת לִבְעָלֶיהָ בֵּין לִפְנֵי יֵאוּשׁ בֵּין לְאַחַר יֵאוּשׁ אֶלָּא שֶׁאַחַר יֵאוּשׁ הַשֶּׁבַח לַגַּנָּב כְּמוֹ שֶׁבֵּאַרְנוּ. נִשְׁתַּנֵּית הַגְּנֵבָה בְּיַד הַגַּנָּב קְנָאָהּ וְקָנָה שִׁבְחָהּ אֲפִלּוּ לִפְנֵי יֵאוּשׁ וְאֵינוֹ מְשַׁלֵּם אֶלָּא דָּמִים:","גָּנַב כְּחוּשָׁה וְהִשְׁמִינָה אוֹ שְׁמֵנָה וְהִכְחִישָׁה מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל אוֹ תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה כִּשְׁעַת הַגְּנֵבָה. גָּנַב טָלֶה וְנַעֲשָׂה אַיִל עֵגֶל וְנַעֲשָׂה שׁוֹר מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל כִּשְׁעַת הַגְּנֵבָה. טְבָחוֹ אוֹ מְכָרוֹ אַחַר שֶׁהִגְדִּיל נַעֲשָׂה שִׁנּוּי בְּיָדוֹ וְקָנָהוּ וְשֶׁלּוֹ הוּא טוֹבֵחַ וְשֶׁלּוֹ הוּא מוֹכֵר וְאֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","גָּנַב בְּהֵמָה אוֹ כְּלִי וְכַיּוֹצֵא בָּהֶן וּבִשְׁעַת הַגְּנֵבָה הָיָה שָׁוֶה אַרְבָּעָה וְעַכְשָׁו בִּשְׁעַת הַעֲמָדָה בַּדִּין שָׁוֶה שְׁנַיִם מְשַׁלֵּם קֶרֶן כִּשְׁעַת הַגְּנֵבָה וְתַשְׁלוּמֵי כֶּפֶל אוֹ אַרְבָּעָה וַחֲמִשָּׁה כִּשְׁעַת הַעֲמָדָה בַּדִּין. הָיָה שָׁוֶה בִּשְׁעַת הַגְּנֵבָה שְׁנַיִם וּבִשְׁעַת הַעֲמָדָה בַּדִּין אַרְבָּעָה אִם שָׁחַט אוֹ מָכַר אוֹ שָׁבַר הַכְּלִי אוֹ אִבְּדוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל אוֹ אַרְבָּעָה וַחֲמִשָּׁה כִּשְׁעַת הַעֲמָדָה בַּדִּין. וְאִם מֵתָה הַבְּהֵמָה אוֹ אָבַד הַכְּלִי מֵאֵלָיו מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל כִּשְׁעַת הַגְּנֵבָה:","מִי שֶׁגָּנַב כְּלִי וּשְׁבָרוֹ אוֹ פִּחֲתוֹ אוֹ נִשְׁבַּר אוֹ נִפְחַת מֵאֵלָיו אֵין שָׁמִין לוֹ הַפְּחָת אֶלָּא רוֹאִין כַּמָּה הָיָה שָׁוֶה אוֹתוֹ הַכְּלִי וּמְשַׁלֵּם לַבְּעָלִים שְׁנַיִם בְּדָמָיו וְהַכְּלִי הַשָּׁבוּר יִהְיֶה לַגַּנָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם רָצוּ הַבְּעָלִים לִטּל הַכְּלִי הַשָּׁבוּר וִישַׁלֵּם לָהֶם הַפְּחָת וְהַכֶּפֶל שׁוֹמְעִין לָהֶן:","הַגַּנָּב שֶׁגָּנַב וְטָבַח אוֹ מָכַר לִפְנֵי יֵאוּשׁ בְּעָלִים אַף עַל פִּי שֶׁלֹּא קָנָה לוֹקֵחַ וַהֲרֵי הַגְּנֵבָה חוֹזֶרֶת בְּעַצְמָהּ מִיַּד הַלּוֹקֵחַ הֲרֵי זֶה מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאֵין צָרִיךְ לוֹמַר אִם טָבַח אוֹ מָכַר לְאַחַר יֵאוּשׁ שֶׁהוּא מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה שֶׁהֲרֵי הוֹעִיל בְּמַעֲשָׂיו וְקָנָה הַלּוֹקֵחַ:","הַגּוֹנֵב מִגַּנָּב אַחֵר אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְאִם טָבַח וּמָכַר אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה לַגַּנָּב הָרִאשׁוֹן שֶׁהֲרֵי דִּין הַבְּהֵמָה הַזֹּאת לַחֲזֹר בְּעֵינֶיהָ לַבְּעָלִים וְלֹא קְנָאָהּ הַגַּנָּב וְלַבְּעָלִים אֵינוֹ מְשַׁלֵּם הַכֶּפֶל אוֹ אַרְבָּעָה וַחֲמִשָּׁה מִפְּנֵי שֶׁלֹּא גְּנָבָהּ מֵרְשׁוּתָן:","גָּנַב וְטָבַח וּבָא גַּנָּב אַחֵר וְגָנַב. הַגַּנָּב הָאַחֲרוֹן מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל לַגַּנָּב הָרִאשׁוֹן שֶׁהֲרֵי קָנָה בְּשִׁנּוּי מַעֲשֶׂה וְגַנָּב הָרִאשׁוֹן מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. גָּנַב וּמָכַר וּבָא אַחֵר וְגָנַב מִן הַלּוֹקֵחַ. אִם נִתְיָאֲשׁוּ הַבְּעָלִים הֲרֵי הָרִאשׁוֹן מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה וְהַגַּנָּב הַשֵּׁנִי מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְאִם לֹא נִתְיָאֲשׁוּ הַבְּעָלִים אֵין הָאַחֲרוֹן מְשַׁלֵּם אֶלָּא קֶרֶן בִּלְבַד:"],"Mishneh Torah, Things Forbidden on the Altar 4":["אֶחָד הַבְּהֵמָה וְאֶחָד הָעוֹף שֶׁנִּרְבְּעָה אוֹ שֶׁהֵמִית אֶת הָאָדָם אוֹ הֻקְצָה אוֹ נֶעֱבַד הַכּל פָּסוּל לְגַבֵּי הַמִּזְבֵּחַ:","הָרוֹבֵעַ וְהַנִּרְבָּע וְשֶׁהֵמִית אֶת הָאָדָם אִם הָיוּ שָׁם שְׁנֵי עֵדִים הֲרֵי הַבְּהֵמָה אוֹ הָעוֹף נִסְקָלִין וּבְשָׂרָן אָסוּר בַּהֲנָאָה. וְאֵין צָרִיךְ לוֹמַר בְּאֵלּוּ שֶׁהֵן אֲסוּרִין לְגָבוֹהַּ. וּבַמֶּה אָמְרוּ שֶׁהֵן אֲסוּרִין לַמִּזְבֵּחַ כְּשֶׁהָיוּ מֻתָּרִין לְהֶדְיוֹט. כְּגוֹן שֶׁהָיָה שָׁם עֵד אֶחָד בִּלְבַד וְהַבְּעָלִים שׁוֹתְקִין אוֹ עַל פִּי הַבְּעָלִים אַף עַל פִּי שֶׁאֵין עֵד כְּלָל. הָיָה שָׁם עֵד אֶחָד וְהַבְּעָלִים מַכְחִישִׁין אוֹתוֹ הֲרֵי אֵלּוּ מֻתָּרִין אַף לַמִּזְבֵּחַ:","בְּהֵמָה שֶׁשָּׂחֲקוּ בָּהּ וְהִגִּיחוּהָ עַד שֶׁהֵמִיתָה אֶת הָאָדָם הֲרֵי זוֹ כְּשֵׁרָה לַמִּזְבֵּחַ מִפְּנֵי שֶׁהִיא כַּאֲנוּסָה. אֵין הַבְּהֵמָה נִפְסֶלֶת מִשּׁוּם רוֹבֵעַ אוֹ נִרְבָּע עַד שֶׁיִּהְיֶה הָאָדָם שֶׁרְבָעָהּ בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד. בֵּין יִשְׂרָאֵל בֵּין עַכּוּ\"ם [בֵּין] עֶבֶד הוֹאִיל וּרְבָעָהּ אָדָם נִפְסְלָה. וְאִם הָאָדָם הוּא שֶׁנִּרְבַּע מִן הַבְּהֵמָה אֵינָהּ נִפְסֶלֶת עַד שֶׁתִּהְיֶה הָאִשָּׁה הַנִּרְבַּעַת בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד אוֹ יְהֵא הָאִישׁ הַנִּרְבָּע בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד:","מֵאֵימָתַי תִּפָּסֵל הַבְּהֵמָה אוֹ הָעוֹף מִשּׁוּם מֻקְצֶה מִשֶּׁיַּעֲשׂוּ בָּהֶן הַכְּמָרִים מַעֲשֶׂה. כְּגוֹן שֶׁיִּגְזְזוּ אוֹתָהּ אוֹ יַעַבְדוּ בָּהּ לְשֵׁם עֲבוֹדָה זָרָה. אֲבָל בִּדְבָרִים אֵינוֹ נַעֲשֶׂה מֻקְצֶה שֶׁאֵין הֶקְדֵּשׁ לַעֲבוֹדָה זָרָה:","הָרוֹבֵעַ וְהַנִּרְבָּע בֵּין שֶׁהָיְתָה הַבְּהֵמָה שֶׁלּוֹ בֵּין שֶׁהָיְתָה שֶׁל חֲבֵרוֹ בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה בֵּין לִפְנֵי הֶקְדֵּשָׁהּ בֵּין לְאַחַר הֶקְדֵּשָׁהּ הֲרֵי זוֹ אֲסוּרָה לַמִּזְבֵּחַ. אֲבָל הַמֻּקְצֶה אִם הִיא שֶׁלּוֹ וְהֻקְצָה קֹדֶם שֶׁיַּקְדִּישׁ נִפְסַל. הִקְצָה שֶׁל חֲבֵרוֹ אוֹ שֶׁהִקְצָה שֶׁלּוֹ אַחַר שֶׁהִקְדִּישׁוֹ הֲרֵי זֶה מֻתָּר. שֶׁאֵין אָדָם מַקְצֶה דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ:","הַנֶּעֱבָד בֵּין שֶׁעָבַד שֶׁלּוֹ בֵּין שֶׁל חֲבֵרוֹ בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה בֵּין לִפְנֵי הֶקְדֵּשׁ בֵּין לְאַחַר הֶקְדֵּשׁ הֲרֵי זֶה אָסוּר. וְיִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם קָבוּעַ וְיִפָּדֶה בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַנֶּעֱבָד הוּא וְכָל מַה שֶּׁעָלָיו אֲסוּרִין לַמִּזְבֵּחַ. שֶׁכָּל צִפּוּי נֶעֱבָד אֲסוּרִין בַּהֲנָאָה. אֲבָל הַמֻּקְצֶה הוּא אָסוּר וּמַה שֶּׁעָלָיו מֻתָּר לַמִּזְבֵּחַ:","הַמִּשְׁתַּחֲוֶה לְהָר אַף עַל פִּי שֶׁהוּא מֻתָּר בַּהֲנָאָה הֲרֵי אֲבָנָיו אֲסוּרִין לַמִּזְבֵּחַ. וְכֵן הַמִּשְׁתַּחֲוֶה לְמַעְיָן הַנּוֹבֵעַ בְּאַרְצוֹ הֲרֵי מֵימָיו פְּסוּלִין לְנַסֵּךְ. אֲשֵׁרָה שֶׁבָּטְלָה אֵין מְבִיאִין מִמֶּנָּה גְּזָרִים לַמַּעֲרָכָה. וְכֵן הַמִּשְׁתַּחֲוֶה לִבְהֵמָה כְּשֵׁם שֶׁנִּפְסְלָה לַמִּזְבֵּחַ כָּךְ צֶמֶר שֶׁלָּהּ פָּסוּל לְבִגְדֵי כְּהֻנָּה. וְקַרְנֶיהָ פְּסוּלִין לַחֲצוֹצְרוֹת וְשׁוֹקֶיהָ לַחֲלִילִין וּבְנֵי מֵעֶיהָ לְנִימִין הַכּל פָּסוּל:","כָּל שֶׁיֵּשׁ בּוֹ שֵׁם לַעֲבוֹדָה זָרָה לֹא יֵעָשֶׂה לִמְלֶאכֶת הַקֹּדֶשׁ אַף עַל פִּי שֶׁהוּא מֻתָּר בַּהֲנָאָה. אֵי זֶהוּ (דברים כג-יט) \"אֶתְנָן\" הָאוֹמֵר לְזוֹנָה הֵא לִיךְ דָּבָר זֶה בִּשְׂכָרֵךְ. אֶחָד זוֹנָה כּוּתִית אוֹ שִׁפְחָה אוֹ יִשְׂרְאֵלִית שֶׁהִיא עֶרְוָה עָלָיו אוֹ מֵחַיָּבֵי לָאוִין. אֲבָל הַפְּנוּיָה אֲפִלּוּ הָיָה כֹּהֵן אֶתְנָנָהּ מֻתָּר. וְכֵן אִשְׁתּוֹ נִדָּה אֶתְנָנָהּ מֻתָּר אַף עַל פִּי שֶׁהִיא עֶרְוָה:","נָשָׂא אַחַת מֵחַיָּבֵי לָאוִין כָּל שֶׁיִּתֵּן לָהּ מֵחֲמַת בְּעִילָה הֲרֵי זֶה אֶתְנָן וְאָסוּר. וְהַזָּכוּר אֶתְנָנוֹ אָסוּר. נָתְנָה הָאִשָּׁה אֶתְנָן לַבּוֹעֵל הֲרֵי זֶה מֻתָּר מִשּׁוּם אֶתְנָן:","הָאוֹמֵר לַחֲבֵרוֹ הֵא לְךָ דָּבָר זֶה וְתָלִין שִׁפְחָתְךָ אֵצֶל עַבְדִּי הָעִבְרִי הֲרֵי זֶה אֶתְנָן. וְהוּא שֶׁאֵין לוֹ אִשָּׁה וּבָנִים. אֲבָל אִם יֵשׁ לוֹ אִשָּׁה וּבָנִים הֲרֵי זֶה מֻתָּר בְּשִׁפְחָה כְּנַעֲנִית כְּמוֹ שֶׁיִּתְבָּאֵר. וְהוּא הַדִּין בְּאוֹמֵר לְזוֹנָה הֵא לִיךְ דָּבָר זֶה וְהִבָּעֲלִי לִפְלוֹנִי הַיִּשְׂרְאֵלִי הֲרֵי זֶה אֶתְנָן:","פָּסַק עִם הַזּוֹנָה לִתֵּן לָהּ טָלֶה אֶחָד וְנָתַן לָהּ הַרְבֵּה אֲפִלּוּ נָתַן אֶלֶף כֻּלָּן אֶתְנָן וַאֲסוּרִין לַמִּזְבֵּחַ. נָתַן לָהּ אֶתְנָנָהּ וְלֹא בָּא עָלֶיהָ אֶלָּא אָמַר לָהּ יְהִי אֶצְלֵךְ עַד שֶׁאָבוֹא עָלַיִךְ כְּשֶׁיָּבוֹא עָלֶיהָ יֵאָסֵר. קָדְמָה וְהִקְרִיבַתּוּ קֹדֶם שֶׁיָּבוֹא עָלֶיהָ כָּשֵׁר [וְאִם הָיְתָה חַיֶּבֶת קָרְבָּן יָצְאָה יְדֵי חוֹבָתָהּ]. וְהוּא שֶׁיֹּאמַר לָהּ בְּעֵת שֶׁנָּתַן אֵימָתַי שֶׁתֵּרָצִי לִי קְנִי אוֹתוֹ מֵעַכְשָׁו. אֲבָל אִם לֹא אָמַר לָהּ כֵּן אֵינָהּ יְכוֹלָה לְהַקְרִיב דָּבָר שֶׁאֵינָהּ שֶׁלָּהּ:","קָדְמָה וְהִקְדִּישַׁתּוּ קֹדֶם שֶׁיָּבוֹא עָלֶיהָ וְאַחַר כָּךְ בָּא עָלֶיהָ הֲרֵי זֶה סָפֵק אִם הוּא אֶתְנָן הוֹאִיל וּבָא עָלֶיהָ קֹדֶם שֶׁתַּקְרִיבֶנּוּ. אוֹ אֵינוֹ אֶתְנָן שֶׁהֲרֵי הִקְדִּישַׁתּוּ קֹדֶם בִּיאָה. לְפִיכָךְ לֹא יִקָּרֵב וְאִם קָרַב נִרְצָה:","בָּא עָלֶיהָ וְלֹא נָתַן לָהּ וּלְאַחַר זְמַן נָתַן לָהּ אֲפִלּוּ אַחַר כַּמָּה שָׁנִים הֲרֵי זֶה אֶתְנָן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכוּתִית שֶׁאָמַר לָהּ הִבָּעֲלִי לִי בְּטָלֶה זֶה שֶׁאֵינָהּ צְרִיכָה מְשִׁיכָה. אוֹ בְּיִשְׂרְאֵלִית שֶׁהָיָה הַטָּלֶה בַּחֲצֵרָהּ וְאָמַר לָהּ אִם לֹא אֶתֵּן לָךְ מָעוֹת בְּיוֹם פְּלוֹנִי הֲרֵי הוּא שֶׁלָּךְ. אֲבָל אִם אָמַר לָהּ הִבָּעֲלִי לִי בְּטָלֶה סְתָם וּבָא עָלֶיהָ וּלְאַחַר זְמַן שָׁלַח לָהּ טָלֶה הֲרֵי זֶה מֻתָּר מִשּׁוּם אֶתְנָן:","אֵין אָסוּר מִשּׁוּם אֶתְנָן וּמְחִיר אֶלָּא גּוּפָן. לְפִיכָךְ אֵינוֹ חָל אֶלָּא עַל דָּבָר הָרָאוּי לִקָּרֵב עַל גַּבֵּי הַמִּזְבֵּחַ. כְּגוֹן בְּהֵמָה טְהוֹרָה וְתוֹרִין וּבְנֵי יוֹנָה וְיַיִן וְשֶׁמֶן וְסלֶת. נָתַן לָהּ מָעוֹת וְלָקְחָה בָּהֶן קָרְבָּן הֲרֵי זֶה כָּשֵׁר:","נָתַן לָהּ חִטִּים וַעֲשָׂאָתָן סלֶת. זֵיתִים וַעֲשָׂאָתָן שֶׁמֶן. עֲנָבִים וַעֲשָׂאָתָן יַיִן. הֲרֵי אֵלּוּ כְּשֵׁרִים שֶׁכְּבָר נִשְׁתַּנּוּ. נָתַן לָהּ בֶּהֱמַת קָדָשִׁים בְּאֶתְנָנָהּ לֹא נֶאֶסְרָה לַמִּזְבֵּחַ. וַאֲפִלּוּ מָנָה אוֹתָהּ עַל פִּסְחוֹ וְעַל חֲגִיגָתוֹ בְּאֶתְנָנָהּ לֹא נִפְסְלוּ הַמֻּקְדָּשִׁין שֶׁכְּבָר זָכָה בָּהֶן גָּבוֹהַּ מִשָּׁעָה שֶׁהִקְדִּישָׁן. וְכֵן אִם נָתַן לָהּ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ לֹא פְּסָלוֹ שֶׁאֵין אָדָם אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ אֶלָּא אִם כֵּן נִתְיָאֲשׁוּ הַבְּעָלִים. אֲבָל אִם נָתַן לָהּ עוֹפוֹת אַף עַל פִּי שֶׁהֵן מֻקְדָּשִׁין אֶתְנָן חָל עֲלֵיהֶם וַאֲסוּרִים וּמִדִּבְרֵי קַבָּלָה הוּא דָּבָר זֶה:","אֵי זֶה הוּא (דברים כג-יט) \"מְחִיר כֶּלֶב\". זֶה הָאוֹמֵר לַחֲבֵרוֹ הֵא לְךָ טָלֶה זֶה תַּחַת כֶּלֶב זֶה. וְכֵן אִם הֶחְלִיף כֶּלֶב בְּכַמָּה בְּהֵמוֹת אוֹ עוֹפוֹת וְכַיּוֹצֵא בָּהֶן כֻּלָּן אֲסוּרוֹת לַמִּזְבֵּחַ:","שְׁנֵי שֻׁתָּפִין שֶׁחָלְקוּ. זֶה לָקַח עֲשָׂרָה טְלָאִים וְזֶה לָקַח תִּשְׁעָה וְכֶלֶב אֶחָד. שֶׁעִם הַכֶּלֶב מֻתָּרִין. אֲבָל הָעֲשָׂרָה שֶׁכְּנֶגְדוֹ אִם יֵשׁ אֶחָד מֵהֶם דָּמָיו כִּדְמֵי הַכֶּלֶב אוֹ יָתֵר עַל דְּמֵי הַכֶּלֶב מוֹצִיאוֹ מִן הָעֲשָׂרָה כְּנֶגֶד הַכֶּלֶב וְיִהְיֶה מְחִירוֹ וּשְׁאֵרָן מֻתָּרִים. וְאִם כָּל אֶחָד וְאֶחָד מֵהֶן דָּמָיו פְּחוּתִין מִדְּמֵי הַכֶּלֶב הֲרֵי הָעֲשָׂרָה כֻּלָּן אֲסוּרִים:","נִשְׁתַּנָּה הַמְּחִיר כְּגוֹן שֶׁהֶחְלִיף כֶּלֶב בְּחִטִּים וְנַעֲשׂוּ סלֶת הֲרֵי זֶה מֻתָּר. אֶתְנַן כֶּלֶב וּמְחִיר זוֹנָה מֻתָּרִין. (דברים כג-יט) \"אֶתְנַן זוֹנָה וּמְחִיר כֶּלֶב\" מֻתָּרִין לְבֶדֶק הַבַּיִת שֶׁהֲרֵי הֵן מִשְׁתַּנִּין. אֲבָל גּוּפָן שֶׁל אֶתְנָן לֹא יֵעָשֶׂה רִקּוּעִין לַבַּיִת שֶׁנֶּאֱמַר (דברים כג-יט) \"לְכָל נֶדֶר\" לְהָבִיא אֶת הָרִקּוּעִים:"],"Mishneh Torah, Those Who Defile Bed or Seat 5":["הַזָּב וְהַזָּבָה וְהַנִּדָּה וְהַיּוֹלֶדֶת לְעוֹלָם הֵם בְּטֻמְאָתָן וּמְטַמְּאִין אָדָם וְכֵלִים וּמִשְׁכָּב וּמֶרְכָּב עַד שֶׁיִּטְבּוֹלוּ. אֲפִלּוּ נִתְאַחֲרוּ כַּמָּה שָׁנִים בְּלֹא רְאִיַּת טֻמְאָה וְלֹא טָבְלוּ הֲרֵי הֵן בְּטֻמְאָתָן:","יוֹלֶדֶת שֶׁלֹּא טָבְלָה אַחַר שִׁבְעָה לְזָכָר וְאַרְבָּעָה עָשָׂר לִנְקֵבָה כָּל דָּם שֶׁתִּרְאֶה אַף עַל פִּי שֶׁהוּא בְּתוֹךְ יְמֵי טֹהַר הֲרֵי הוּא כְּדַם הַנִּדּוֹת וּמְטַמֵּא לַח וְיָבֵשׁ. לֹא תָּלָה הַכָּתוּב בְּיָמִים בִּלְבַד אֶלָּא בְּיָמִים וּטְבִילָה:","יוֹלֶדֶת שֶׁיָּרְדָה לִטְבּל מִטֻּמְאָה לְטָהֳרָה וְנֶעֱקַר מִמֶּנָּה דָּם בִּירִידָתָהּ וְיָצָא חוּץ לְבֵין הַשִּׁנַּיִם הֲרֵי זוֹ טְמֵאָה וְאֵין הַטְּבִילָה מוֹעֶלֶת לְדָם זֶה וְאַף עַל פִּי שֶׁעֲדַיִן הִיא בִּבְשָׂרָהּ. וְאִם נֶעֱקַר מִמֶּנָּה בַּעֲלִיָּתָהּ מִן הַמִּקְוֶה הֲרֵי זוֹ טְהוֹרָה מִפְּנֵי שֶׁהוּא דַּם טֹהַר. וְהַטְּבִילָה מוֹעֶלֶת לְכָל הַדָּם הַמֻּבְלָע בָּאֵיבָרִים וּמְשִׂימָה אוֹתוֹ דַּם טֹהַר:","יוֹלֶדֶת שֶׁטָּבְלָה אַחַר שִׁבְעָה שֶׁל זָכָר וְאַרְבָּעָה עָשָׂר שֶׁל נְקֵבָה אוֹ אַחַר סְפִירַת שִׁבְעָה יָמִים נְקִיִּים אִם הָיְתָה יוֹלֶדֶת בְּזוֹב הֲרֵי הִיא בְּכָל יְמֵי טֹהַר שֶׁלָּהּ כְּטָמֵא שֶׁטָּבַל וַעֲדַיִן לֹא הֶעֱרִיב שִׁמְשׁוֹ וַהֲרֵי הִיא טְבוּלַת יוֹם בְּכָל אוֹתָן הַיָּמִים. וְאֵינָהּ צְרִיכָה טְבִילָה אַחֶרֶת בְּסוֹף יְמֵי טֹהַר אֶלָּא בְּמִשְׁלָם הַיָּמִים הֲרֵי הִיא כִּטְבוּל יוֹם שֶׁהֶעֱרִיב שִׁמְשׁוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהִיא כִּטְבוּל יוֹם לְעִנְיַן תְּרוּמָה וּמַעֲשֵׂר. אֲבָל לְקָדָשִׁים הֲרֵי הִיא כְּרִאשׁוֹן לְטֻמְאָה שֶׁעֲדַיִן לֹא טָבַל אֶלָּא כְּמִי שֶׁנָּגַע בְּנִדָּה אוֹ בִּטְמֵא מֵת שֶׁעֲדַיִן לֹא טָבַל וְכַיּוֹצֵא בָּהֶן. נִמְצֵאתָ אַתָּה לָמֵד שֶׁהַיּוֹלֶדֶת בְּתוֹךְ יְמֵי טֹהַר אוֹכֶלֶת בְּמַעֲשֵׂר וּפוֹסֶלֶת אֶת הַתְּרוּמָה כִּטְבוּל יוֹם כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם נָפַל מֵרֻקָּהּ וּמִדַּם טָהֳרָתָהּ עַל כִּכָּר שֶׁל תְּרוּמָה הֲרֵי הוּא בְּטָהֳרָתוֹ שֶׁמַּשְׁקֵה טְבוּל יוֹם טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר. וּמְטַמְּאָה אֶת הַקָּדָשִׁים כִּוְלַד הַטֻּמְאוֹת עַד שֶׁתַּשְׁלִים יְמֵי טֹהַר וְתִהְיֶה טְהוֹרָה לַכּל. וְיֵרָאֶה לִי שֶׁמֵּאַחַר שֶׁהִיא מְטַמְּאָה אֶת הַקֹּדֶשׁ שֶׁהִיא צְרִיכָה טְבִילָה אַחֶרֶת בַּסּוֹף וְאַחַר כָּךְ תִגַּע בַּקֹּדֶשׁ אַף עַל פִּי שֶׁאֵינָהּ צְרִיכָה טְבִילָה אַחֶרֶת לַאֲכִילַת הַתְּרוּמָה:","יוֹלֶדֶת שֶׁהִיא מְצֹרַעַת וְטָבְלָה אַחַר שִׁבְעָה שֶׁל זָכָר אוֹ אַרְבָּעָה עָשָׂר שֶׁל נְקֵבָה הֲרֵי דַּם טֹהַר שֶׁלָּהּ טָמֵא כְּרֻקָּהּ וּכְמֵימֵי רַגְלֶיהָ. וְכֻלָּן כְּמַשְׁקִין טְמֵאִין שֶׁכָּל הַמַּשְׁקִין הַטְּמֵאִין הַיּוֹצְאִין מֵהֶן כְּמַשְׁקִין שֶׁהֵן נוֹגְעִין בָּהֶן. חוּץ מִזָּב וְכַיּוֹצֵא בּוֹ. שֶׁהֲרֵי שְׁלֹשָׁה מַשְׁקִין הַיּוֹצְאִין מִמֶּנּוּ אֲבוֹת טֻמְאוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","זָבָה קְטַנָּה שֶׁטָּבְלָה בַּיּוֹם הַשִּׁמּוּר שֶׁלָּהּ אַחַר הָנֵץ כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן אִסּוּר נִדָּה הֲרֵי מַגָּעָהּ וּבְעִילָתָהּ תְּלוּיִים. אִם נִגְמַר הַיּוֹם וְלֹא רָאֲתָה כָּל שֶׁנָּגְעָה בּוֹ טָהוֹר וּבוֹעֲלָהּ טָהוֹר וּפָטוּר. וְאִם רָאֲתָה דָּם אַחַר שֶׁטָּבְלָה כָּל טָהֳרוֹת שֶׁעָשְׂתָה טְמֵאוֹת וְעוֹשָׂת מִשְׁכָּב וּמֶרְכָּב וּבוֹעֲלָהּ חַיָּב חַטָּאת. טָבְלָה בְּלֵיל הַשִּׁמּוּר קֹדֶם שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר הֲרֵי זוֹ כְּמִי שֶׁלֹּא טָבְלָה וַעֲדַיִן עוֹשָׂת מֶרְכָּב וּמוֹשָׁב:","הָרוֹאָה דָּם בְּיוֹם אַחַד עָשָׂר וְטָבְלָה לְעֶרֶב לֵיל שְׁנֵים עָשָׂר הֲרֵי זוֹ מְטַמְּאָה מִשְׁכָּב וּמוֹשָׁב. אַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לִהְיוֹת זָבָה גְּדוֹלָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן אִסּוּר נִדָּה:","טָבְלָה בְּיוֹם שְׁנֵים עָשָׂר אַחַר הָנֵץ הַחַמָּה אַף עַל פִּי שֶׁאֲסוּרָה לְשַׁמֵּשׁ [עַד] לָעֶרֶב אִם שִׁמְּשָׁה בּוֹעֲלָהּ טָהוֹר וּמִשְׁכָּבָהּ וּמֶרְכָּבָהּ טְהוֹרִין אַף עַל פִּי שֶׁרָאֲתָה דָּם בְּיוֹם שְׁנֵים עָשָׂר אַחַר הַטְּבִילָה. מִפְּנֵי שֶׁהוּא תְּחִלַּת נִדָּה כְּמוֹ שֶׁבֵּאַרְנוּ שָׁם בְּאִסּוּר נִדָּה וְאֵינוֹ מִצְטָרֵף לְיוֹם אַחַד עָשָׂר לְפִיכָךְ אֵינָהּ צְרִיכָה לִשְׁמֹר יוֹם שְׁנֵים עָשָׂר אֶלָּא טוֹבֶלֶת וְעוֹסֶקֶת בְּטָהֳרוֹת. אֲבָל הָרוֹאָה דָּם בַּעֲשִׂירִי טוֹבֶלֶת בְּיוֹם אַחַד עָשָׂר וּמְשַׁמֶּרֶת אוֹתוֹ שֶׁאִם תִּרְאֶה בּוֹ דָּם אַחַר טְבִילָה נִטְמְאוּ כָּל טָהֳרוֹת שֶׁעָשְׂתָה וְנִטְמָא בּוֹעֲלָהּ אַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לִהְיוֹת זָבָה גְּדוֹלָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן נִדָּה:","זָב וְזָבָה גְּדוֹלָה שֶׁטָּבְלוּ בְּיוֹם שְׁבִיעִי שֶׁלָּהֶן כְּמוֹ שֶׁבֵּאַרְנוּ לֹא יִתְעַסְּקוּ בְּטָהֳרוֹת עַד לָעֶרֶב שֶׁמָּא יִרְאוּ טֻמְאָה וְיִסְּתְּרוּ שִׁבְעַת יְמֵי הַסְּפִירָה וְנִמְצָא אוֹתָן הַטָּהֳרוֹת טְמֵאוֹת לְמַפְרֵעַ. אַף עַל פִּי שֶׁהֵן עוֹשִׂין מִשְׁכָּב וּמוֹשָׁב לְמַפְרֵעַ אֵין מְטַמְּאִין כְּלֵי חֶרֶס בְּהֶסֵּט מֵאַחַר שֶׁטָּבְלוּ אַף עַל פִּי שֶׁחָזְרוּ וְרָאוּ טֻמְאָה וְסָתְרוּ הַכּל. וְכָל כְּלִי חֶרֶס שֶׁהֱסִיטוּ עַד שֶׁלֹּא רָאוּ טָהוֹר:"],"Mishneh Torah, Tithes 3":["פֵּרוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת וְנִתְלְשׁוּ וַעֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן כְּגוֹן תְּבוּאָה שֶׁקְּצָרָהּ וְדָשָׁהּ וַעֲדַיִן לֹא זָרָה אוֹתָהּ וְלֹא מֵרְחָהּ מֻתָּר לֶאֱכל מֵהֶן אֲכִילַת עַרְאַי עַד שֶׁתִּגָּמֵר מְלַאכְתָּן. וּמִשֶּׁתִּגָּמֵר מְלַאכְתָּן אָסוּר לֶאֱכל מֵהֶן עַרְאַי:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּגוֹמֵר פֵּרוֹתָיו לְמָכְרָן בַּשּׁוּק. אֲבָל אִם הָיְתָה כַּוָּנָתוֹ לְהוֹלִיכָן בַּבַּיִת הֲרֵי זֶה מֻתָּר לֶאֱכל מֵהֶן עַרְאַי אַחַר שֶׁנִּגְמְרָה מְלַאכְתָּן עַד שֶׁיִּקָּבְעוּ לְמַעֲשֵׂר:","אֶחָד מִשִּׁשָּׁה דְּבָרִים קוֹבֵעַ הַפֵּרוֹת לְמַעַשְׂרוֹת. הֶחָצֵר. וְהַמִּקָּח. וְהָאֵשׁ. וְהַמֶּלַח. וְהַתְּרוּמָה. וְהַשַּׁבָּת. וְכֻלָּן אֵין קוֹבְעִין אֶלָּא בְּדָבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ:","כֵּיצַד. פֵּרוֹת שֶׁדַּעְתּוֹ לְהוֹלִיכָן לַבַּיִת אַף עַל פִּי שֶׁנִּגְמְרָה מְלַאכְתָּן אוֹכֵל מֵהֶן אֲכִילַת עַרְאַי עַד שֶׁנִּכְנְסוּ לַבַּיִת. נִכְנְסוּ לַבַּיִת נִקְבְּעוּ לְמַעַשְׂרוֹת וְאָסוּר לֶאֱכל מֵהֶן עַד שֶׁיְּעַשֵּׂר. וְכֵן אִם מְכָרָן אוֹ בִּשְּׁלָן בְּאוּר אוֹ כְּבָשָׁן בְּמֶלַח אוֹ הִפְרִישׁ מֵהֶן תְּרוּמָה אוֹ נִכְנְסָה שַׁבָּת עֲלֵיהֶם לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר אַף עַל פִּי שֶׁלֹּא הִגִּיעוּ לַבַּיִת. הִכְנִיסָן לַבַּיִת קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן הֲרֵי זֶה אוֹכֵל מֵהֶן עַרְאַי. הִתְחִיל לִגְמֹר מְלַאכְתָּן מֵאַחַר שֶׁנִּכְנְסוּ לַבַּיִת חַיָּב לְעַשֵּׂר הַכּל. כֵּיצַד. הִכְנִיס קִשּׁוּאִין וְדִילוּעִין לַבַּיִת קֹדֶם שֶׁיְּשַׁפְשֵׁף מִשֶּׁיַּתְחִיל לְשַׁפְשֵׁף אַחַת נִקְבְּעוּ הַכּל לְמַעֲשֵׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הַתּוֹרֵם פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן מֻתָּר לֶאֱכל מֵהֶן עַרְאַי. חוּץ מִכַּלְכָּלַת תְּאֵנִים שֶׁאִם תְּרָמָהּ קֹדֶם שֶׁתִּגְמֹר מְלַאכְתָּן נִקְבְּעָה לְמַעֲשֵׂר:","הַמֵּבִיא לְבַיִת סֻכֵּי תְּאֵנָה וּבָהֶם תְּאֵנִים. מִכְבְּדֵי תְּמָרָה וּבָהֶם תְּמָרִים. אִם הִכְנִיסוּם תִּינוֹקוֹת אוֹ פּוֹעֲלִים לֹא נִקְבְּעוּ לְמַעֲשֵׂר. וְאִם הִכְנִיסָן בַּעַל הַבַּיִת חַיָּב בְּמַעֲשֵׂר. הִכְנִיס שִׁבֳּלִים לַעֲשׂוֹת מֵהֶן עִסָּה לֹא נִקְבְּעוּ. לְאָכְלָן מְלִילוֹת נִקְבְּעוּ לְמַעֲשֵׂר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְבוּאָה. אֲבָל בְּקִטְנִיּוֹת לֹא נִקְבְּעוּ לְמַעֲשֵׂר:","מֻתָּר לְהַעֲרִים עַל הַתְּבוּאָה לְהַכְנִיסָהּ בְּמוֹץ כְּדֵי שֶׁתִּהְיֶה בְּהֶמְתּוֹ אוֹכֶלֶת וּפְטוּרָה מִן הַמַּעֲשֵׂר. וְזוֹרֶה מְעַט מְעַט אַחַר שֶׁהִכְנִיס לְבֵיתוֹ וּפָטוּר לְעוֹלָם מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת שֶׁהֲרֵי אֵינוֹ מַתְחִיל לִגְמֹר הַכּל:","הַגּוֹמֵר פֵּרוֹתָיו שֶׁל חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ וְכֵן הַקּוֹבֵעַ פֵּרוֹתָיו בְּאֶחָד מִן הַשִּׁשָּׁה דְּבָרִים שֶׁקּוֹבְעִים לְמַעֲשֵׂר שֶׁלֹּא מִדַּעְתּוֹ הֲרֵי אֵלּוּ טָבְלוּ לְמַעֲשֵׂר:","אֵי זֶהוּ גְּמַר מְלַאכְתָּן שֶׁל פֵּרוֹת. הַקִּשּׁוּאִין וְהַדִּילוּעִין וְהָאֲבַטִּיחִין מִשֶּׁיְּשַׁפְשֵׁף בְּיָדוֹ וְיָסִיר הַצִּהוּב שֶׁעֲלֵיהֶן כְּמוֹ שֵׂעָר דַּק. וְאִם אֵינוֹ מְשַׁפְשֵׁף מִשֶּׁיַּעֲמִיד עֲרֵמָה. וּבַאֲבַטִּיחַ מִשֶּׁיַּסְדִּיר אוֹתוֹ בְּמֻקְצֶה אֲבַטִּיחַ בְּצַד אֲבַטִּיחַ. הָיָה מְשַׁפְשֵׁף אַחַת אַחַת כֵּיוָן שֶׁגָּמַר כָּל צָרְכּוֹ נִגְמְרָה מְלַאכְתָּן. וְתוֹרְמִין קִשּׁוּאִין וְדִילוּעִין אַף עַל פִּי שֶׁלֹּא הֵסִיר הַצִּהוּב מֵעֲלֵיהֶן:","הַיָּרָק הַנֶּאֱגָד מִשֶּׁיֶּאֱגֹד. אִם אֵינוֹ אוֹגֵד מִשֶּׁיְּמַלֵּא אֶת הַכְּלִי. [אִם] אֵינוֹ מְמַלֵּא הֲרֵי זֶה אוֹכֵל עַרְאַי עַד שֶׁיְּלַקֵּט כָּל צָרְכּוֹ:","כַּלְכָּלָה מִשֶּׁיְּחַפֶּה הַפֵּרוֹת שֶׁבָּהּ בְּעָלִים וּבְהוּצִין וְכַיּוֹצֵא בָּהֶן. אִם אֵינוֹ מְחַפֶּה מִשֶּׁיְּמַלֵּא אֶת הַכְּלִי. אִם אֵינוֹ מְמַלֵּא עַד שֶׁיְּלַקֵּט כָּל צָרְכּוֹ:","כְּלִי גָּדוֹל שֶׁדַּעְתּוֹ לְמַלְּאוֹת אֶת חֶצְיוֹ כֵּיוָן שֶׁמִּלֵּא חֶצְיוֹ נִטְבַּל. הָיָה בְּדַעְתּוֹ לְמַלְּאוֹת אֶת כֻּלּוֹ אֵינוֹ נִטְבָּל עַד שֶׁיְּמַלֵּא אֶת כֻּלּוֹ. הָיוּ שְׁנַיִם וּבְדַעְתּוֹ לְמַלְּאוֹת אֶת שְׁנֵיהֶם לֹא נִטְבְּלוּ עַד שֶׁיְּמַלֵּא שְׁנֵיהֶם:","אָגַד הַיָּרָק אֶגֶד גָּדוֹל בַּשָּׂדֶה אַף עַל פִּי שֶּׁבְּדַעְתּוֹ לְאָגְדוֹ אֲגֻדּוֹת קְטַנּוֹת לַשּׁוּק הֲרֵי זֶה נִטְבָּל. הַפֶּרֶד וְהַצִּמּוּקִין וְהֶחָרוּבִין מִשֶּׁיַּעֲמִיד עֲרֵמָה בְּרֹאשׁ גַּגּוֹ. וְהַבְּצָלִים מִשֶּׁיָּסִיר הֶעָלִים וְהַקְּלִפּוֹת שֶׁדַּרְכּוֹ לְהַשְׁלִיכָם מֵעֲלֵיהֶן. וְאִם אֵינוֹ מֵסִיר עַד שֶׁיַּעֲמִיד עֲרֵמָה:","הַתְּבוּאָה מִשֶּׁיְּמַרֵחַ. וְאֵי זֶהוּ מְמָרֵחַ זֶה הַמְיַפֶּה פְּנֵי הַכְּרִי שֶׁל תְּבוּאָה בְּרַחַת בְּסוֹף כָּל דָּבָר כְּדֶרֶךְ שֶׁעוֹשִׂין כְּשֶׁגּוֹמְרִין כָּל מַעֲשֶׂיהָ. אִם אֵינוֹ מְמָרֵחַ עַד שֶׁיַּעֲמִיד עֲרֵמָה. הַקִּטְנִיּוֹת מִשֶּׁיִּכְבֹּר וְנוֹטֵל מִתַּחַת הַכְּבָרָה וְאוֹכֵל. [אִם] אֵינוֹ כּוֹבֵר עַד שֶׁיְּמַרֵחַ. וְאַף עַל פִּי שֶׁמֵּרֵחַ מֻתָּר לִטּל מִן הַקּוּטְעִים וּמִן הַצְּדָדִין וּמִמַּה שֶּׁבְּתוֹךְ הַתֶּבֶן וְאוֹכֵל:","הַיַּיִן מִשֶּׁיַּנִּיחֶנּוּ בֶּחָבִיּוֹת וְיִשְׁלֶה הַזַּגִּין וְהַחֲרְצָנִין מֵעַל פִּי הֶחָבִית. אֲבָל כְּשֶׁהוּא בְּתוֹךְ הַבּוֹר כְּשֶׁיַּגְבִּיהֶנּוּ לְהַעֲמִידוֹ בֶּחָבִית שׁוֹתֶה עַרְאַי וְקוֹלֵט מִן הַגַּת הָעֶלְיוֹנָה וּמִן הַצִּנּוֹר וּמִכָּל מָקוֹם וְשׁוֹתֶה:","הַשֶּׁמֶן מִשֶּׁיֵּרֵד לַעוּקָה אַף עַל פִּי שֶׁיָּרַד נוֹטֵל מִן הָעֵקֶל וּמִן הַמֶּמֶל וּמִבֵּין הַפַּסִּין וְנוֹתֵן לִקְעָרָה קְטַנָּה וּלְתַמְחוּי לְתוֹךְ הַתַּבְשִׁיל אַף עַל פִּי שֶׁהוּא חַם מִפְּנֵי שֶׁאֵינוֹ מִתְבַּשֵּׁל בִּכְלִי שֵׁנִי. וְאִם הָיָה חַם בְּיוֹתֵר כְּדֵי שֶׁיִּכְוֶה אֶת הַיָּד לֹא יִתֵּן לְתוֹכוֹ מִפְּנֵי שֶׁהוּא מִתְבַּשֵּׁל:","הָעִגּוּל שֶׁל דְּבֵלָה מִשֶּׁיַחְלִקֶּנּוּ. הַגְּרוֹגָרוֹת מִשֶּׁיָּדוּשׁ. וְאִם הִכְנִיסָם לִמְגוּרָה מִשֶּׁיַּעֲגִיל בְּיָדוֹ עַל פִּי הַמְּגוּרָה. הָיָה דָּשׁ הַגְּרוֹגָרוֹת בְּחָבִית אוֹ הָעִגּוּל עַל פִּי הַמְּגוּרָה [נִשְׁבְּרָה הֶחָבִית אוֹ שֶׁנִּפְתְּחָה הַמְּגוּרָה] הֲרֵי זֶה לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר:","תְּאֵנִים וַעֲנָבִים שֶׁבַּמֻּקְצֶה מֻתָּר לֶאֱכל מֵהֶן עַרְאַי בִּמְקוֹמָן. אֲבָל אִם נָטַל מִן הַמֻּקְצֶה וְהוֹלִיךְ לְמָקוֹם אַחֵר לֹא יֹאכַל מֵהֶן עַרְאַי שֶׁהֲרֵי נִגְמְרָה מְלַאכְתָּן אַף עַל פִּי שֶׁלֹּא יָבְשׁוּ כָּל צָרְכָּן:","הֶחָרוּבִין עַד שֶׁלֹּא כִּנְּסָן לְרֹאשׁ הַגַּג מוֹרִיד מֵהֶן לִבְהֵמָה וּפָטוּר. מִפְּנֵי שֶׁהוּא מַחֲזִיר אֶת הַמּוֹתָר לְיַבְּשׁוֹ וְנִמְצָא מַאֲכִיל עַרְאַי:","מַעֲשֵׂר רִאשׁוֹן שֶׁהִקְדִּימוּ בְּשִׁבֳּלִים אָסוּר לֶאֱכל מִמֶּנּוּ עַרְאַי קֹדֶם שֶׁיַּפְרִישׁ תְּרוּמָתוֹ וְאִם אָכַל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. כֵּיצַד הִיא אֲכִילַת עַרְאַי. כְּגוֹן שֶׁהָיָה מְקַלֵּף שְׂעוֹרִים וְאוֹכֵל מְקַלֵּף אַחַת אַחַת. וְאִם קִלֵּף וְכָנַס לְתוֹךְ יָדוֹ חַיָּב לְעַשֵּׂר. הָיָה מוֹלֵל מְלִילוֹת שֶׁל חִטִּים מְנַפֶּה מִיָּד לְיָד וְאוֹכֵל. וְאִם נִפָּה לְתוֹךְ חֵיקוֹ חַיָּב לְעַשֵּׂר וְאֵין צָרִיךְ לוֹמַר אִם נִפָּה בִּכְלִי שֶׁאֵין זֶה עַרְאַי. וְכֵן נוֹטֵל מִן הַיַּיִן וְנוֹתֵן לִקְעָרָה לְתוֹךְ תַּבְשִׁיל צוֹנֵן וְאוֹכֵל. אֲבָל לֹא לְתוֹךְ הַקְּדֵרָה אַף עַל פִּי שֶׁהִיא צוֹנֶנֶת מִפְּנֵי שֶׁהִיא כְּבוֹר קָטָן. וְכֵן סוֹחֵט זֵיתִים עַל בְּשָׂרוֹ אֲבָל לֹא לְתוֹךְ יָדוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּכְשֵׁם שֶׁמֻּתָּר לֶאֱכל עַרְאַי מִפֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן כָּךְ מֻתָּר לְהַאֲכִיל מֵהֶן לְחַיָּה וְלִבְהֵמָה וְלָעוֹפוֹת כָּל מַה שֶּׁיִּרְצֶה וּמַפְקִיר מֵהֶן כָּל מַה שֶּׁיִּרְצֶה קֹדֶם שֶׁיְּעַשֵּׂר. וְאִם גָּמְרוּ אַף עַל פִּי שֶׁלֹּא נִקְבְּעוּ לְמַעֲשֵׂר לֹא יַפְקִיר. וְלֹא יַאֲכִיל לִבְהֵמָה וּלְחַיָּה וּלְעוֹפוֹת אֲכִילַת קֶבַע עַד שֶׁיְּעַשֵּׂר. וּמֻתָּר לְהַאֲכִיל לִבְהֵמָה עַרְאַי מִן הַטֶּבֶל וַאֲפִלּוּ בְּתוֹךְ הַבַּיִת. וּמַאֲכִיל פְּקִיעֵי עָמִיר עַד שֶׁיַּעֲשֵׂם חֲבִילוֹת:","הַמּוֹצֵא קְצִיצוֹת בַּדֶּרֶךְ אֲפִלּוּ בְּצַד שְׂדֵה קְצִיצוֹת הֲרֵי אֵלּוּ פְּטוּרִין מִן הַמַּעֲשֵׂר. מָצָא גְּרוֹגָרוֹת אִם דָּרְסוּ רֹב הַגְּרוֹגָרוֹת רֹב הָאָדָם חַיָּב לְעַשֵּׂר. שֶׁחֶזְקָתָן מִדָּבָר שֶׁנִּגְמְרָה מְלַאכְתָּן. וְכֵן אִם מָצָא פִּלְחֵי דְּבֵלָה שֶׁיָּדוּעַ שֶׁהֵם מִדָּבָר הַגָּמוּר:","מָצָא כְּרִיכוֹת בִּרְשׁוּת הַיָּחִיד חַיָּב לְעַשֵּׂר. בִּרְשׁוּת הָרַבִּים פְּטוּרוֹת. וְהָאֲלֻמּוֹת בְּכָל מָקוֹם חַיָּבוֹת בְּמַעֲשֵׂר. מָצָא תְּבוּאָה מְרוּחָה עוֹשֶׂה תְּרוּמוֹת וּמַעַשְׂרוֹת עַל פֵּרוֹת אֲחֵרוֹת וְאֵינוֹ חוֹשֵׁשׁ. מָצָא כַּלְכָּלָה מְחֻפָּה חַיֶּבֶת בְּמַעַשְׂרוֹת. מָצָא כַּלְכָּלָה בְּמָקוֹם שֶׁהָרֹב מַכְנִיסִין לַשּׁוּק אָסוּר לֶאֱכל מִמֶּנָּה עַרְאַי וּמְתַקְּנָהּ דְּמַאי. וּבְמָקוֹם שֶׁהָרֹב מַכְנִיסִין לַבָּתִּים אוֹכֵל מִמֶּנָּה עַרְאַי וּמְתַקְּנָהּ וַדַּאי. מֶחֱצָה לְמֶחֱצָה דְּמַאי. וְאִם הִכְנִיסָהּ לַבַּיִת מְתַקְּנָהּ וַדַּאי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵין לוֹ גְּמַר מְלָאכָה. אֲבָל בְּדָבָר שֶׁיֵּשׁ לוֹ גְּמַר מְלָאכָה אַף עַל פִּי שֶׁהוּא מַעֲשֵׂר וַדַּאי אֵינוֹ צָרִיךְ לְהַפְרִישׁ תְּרוּמָה. שֶׁחֶזְקָתָן שֶׁהִפְרִישׁ מֵהֶן תְּרוּמָה בְּשָׁעָה שֶׁנִּגְמְרָה מְלַאכְתָּן:","חַדְרֵי הַנְּמָלִים שֶׁלָּנוּ בְּצַד הָעֲרֵמָה הַחַיֶּבֶת הֲרֵי הַנִּמְצָא בָּהֶן חַיָּב לְמַעַשְׂרוֹת שֶׁיָּדוּעַ שֶׁמִּדָּבָר גָּמוּר הָיוּ גּוֹרְרִין כָּל הַלַּיְלָה:","הַמּוֹצֵא זֵיתִים תַּחַת הַזַּיִת וְחָרוּבִין תַּחַת הֶחָרוּב חַיָּבִין בְּמַעֲשֵׂר שֶׁחֶזְקָתָן שֶׁמֵּאִילָן זֶה נָפְלוּ. מָצָא תְּאֵנִים תַּחַת הַתְּאֵנָה הֲרֵי הֵם סָפֵק שֶׁהֲרֵי מִשְׁתַּנּוֹת וּמִתְלַכְלְכוֹת בֶּעָפָר שֶׁמָּא מִתְּאֵנָה זוֹ נָפְלוּ אוֹ מִתְּאֵנִים שֶׁנִּתְעַשְּׂרוּ:","הַמַּקְדִּישׁ פֵּרוֹת תְּלוּשִׁין וּפְדָאָן קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן חַיָּב לְעַשֵּׂר. וְאִם נִגְמְרָה מְלַאכְתָּן בְּיַד הַהֶקְדֵּשׁ וְאַחַר כָּךְ פְּדָאָן פְּטוּרִין מִן הַמַּעַשְׂרוֹת שֶׁבִּשְׁעַת חוֹבָתָן הָיוּ פְּטוּרִין מִן הַמַּעַשְׂרוֹת. הַמַּקְדִּישׁ קָמָה לִמְנָחוֹת פְּטוּרָה מִן הַמַּעַשְׂרוֹת:"],"Mishneh Torah, Torah Study 6":["כָּל תַּלְמִיד חָכָם מִצְוָה לְהַדְּרוֹ וְאַף עַל פִּי שֶׁאֵינוֹ רַבּוֹ שֶׁנֶּאֱמַר (ויקרא יט לב) \"מִפְּנֵי שֵׂיבָה תָּקוּם וְהָדַרְתָּ פְּנֵי זָקֵן\". זָקֵן זֶה שֶׁקָּנָה חָכְמָה. וּמֵאֵימָתַי חַיָּבִין לַעֲמֹד מִפָּנָיו. מִשֶּׁיִּקְרַב מִמֶּנּוּ בְּאַרְבַּע אַמּוֹת עַד שֶׁיַּעֲבֹר מִכְּנֶגֶד פָּנָיו:","אֵין עוֹמְדִין מִפָּנָיו לֹא בְּבֵית הַמֶּרְחָץ וְלֹא בְּבֵית הַכִּסֵּא שֶׁנֶּאֱמַר (ויקרא יט לב) \"תָּקוּם וְהָדַרְתָּ\" קִימָה שֶׁיֵּשׁ בָּהּ הִדּוּר. וְאֵין בַּעֲלֵי אֻמָּנֻיּוֹת חַיָּבִין לַעֲמֹד מִפְּנֵי תַּלְמִידֵי חֲכָמִים בְּשָׁעָה שֶׁעוֹסְקִין בִּמְלַאכְתָּן שֶׁנֶּאֱמַר תָּקוּם וְהָדַרְתָּ מַה הִדּוּר שֶׁאֵין בָּהּ חֶסְרוֹן כִּיס אַף קִימָה שֶׁאֵין בָּהּ חֶסְרוֹן כִּיס. וּמִנַּיִן שֶׁלֹּא יַעֲצִים עֵינָיו מִן הֶחָכָם כְּדֵי שֶׁלֹּא יִרְאֵהוּ עַד שֶׁלֹּא יַעֲמֹד מִפָּנָיו. שֶׁנֶּאֱמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ. הָא כָּל דָּבָר שֶׁהוּא מָסוּר לַלֵּב נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ:","אֵין רָאוּי לֶחָכָם שֶׁיַּטְרִיחַ אֶת הָעָם וִיכַוֵּן עַצְמוֹ לָהֶן כְּדֵי שֶׁיַּעַמְדוּ מִפָּנָיו אֶלָּא יֵלֵךְ בְּדֶרֶךְ קְצָרָה וּמִתְכַּוֵּן שֶׁלֹּא יִרְאוּ אוֹתוֹ כְּדֵי שֶׁלֹּא יַטְרִיחֵן לַעֲמֹד. וְהַחֲכָמִים הָיוּ מַקִּיפִין וְהוֹלְכִין בְּדֶרֶךְ הַחִיצוֹנָה שֶׁאֵין מַכִּירֵיהֶן מְצוּיִין שָׁם כְּדֵי שֶׁלֹּא יַטְרִיחוּם:","רוֹכֵב הֲרֵי הוּא כִּמְהַלֵּךְ וּכְשֵׁם שֶׁעוֹמְדִים מִפְּנֵי הַמְהַלֵּךְ כָּךְ עוֹמְדִין מִפְּנֵי הָרוֹכֵב:","שְׁלֹשָׁה שֶׁהָיוּ הוֹלְכִין בַּדֶּרֶךְ. הָרַב בָּאֶמְצַע גָּדוֹל מִימִינוֹ וְקָטָן מִשְּׂמֹאלוֹ:","הָרוֹאֶה חָכָם אֵינוֹ עוֹמֵד מִפָּנָיו עַד שֶׁיַּגִּיעַ לוֹ לְאַרְבַּע אַמּוֹת. וְכֵיוָן שֶׁעָבַר יוֹשֵׁב. רָאָה אַב בֵּית דִּין עוֹמֵד מִלְּפָנָיו מִשֶּׁיִּרְאֶנּוּ מֵרָחוֹק מְלֹא עֵינָיו וְאֵינוֹ יוֹשֵׁב עַד שֶׁיַּעֲבֹר מֵאַחֲרָיו אַרְבַּע אַמּוֹת. רָאָה אֶת הַנָּשִׂיא עוֹמֵד מִלְּפָנָיו מְלֹא עֵינָיו וְאֵינוֹ יוֹשֵׁב עַד שֶׁיֵּשֵׁב בִּמְקוֹמוֹ אוֹ עַד שֶׁיִּתְכַּסֶּה מֵעֵינָיו. וְהַנָּשִׂיא שֶׁמָּחַל עַל כְּבוֹדוֹ כְּבוֹדוֹ מָחוּל. כְּשֶׁהַנָּשִׂיא נִכְנָס כָּל הָעָם עוֹמְדִים וְאֵינָן יוֹשְׁבִין עַד שֶׁיֹּאמַר לָהֶם שְׁבוּ. כְּשֶׁאָב בֵּית דִּין נִכְנָס עוֹשִׂין לוֹ שְׁתֵּי שׁוּרוֹת וְעוֹמְדִין מִכָּאן וּמִכָּאן עַד שֶׁנִּכְנָס וְיוֹשֵׁב בִּמְקוֹמוֹ וּשְׁאָר הָעָם יוֹשְׁבִין בִּמְקוֹמָן:","חָכָם שֶׁנִּכְנָס כָּל שֶׁיַּגִּיעַ לוֹ בְּאַרְבַּע אַמּוֹת עוֹמֵד מִלְּפָנָיו אֶחָד עוֹמֵד וְאֶחָד יוֹשֵׁב עַד שֶׁנִּכְנָס וְיוֹשֵׁב בִּמְקוֹמוֹ. בְּנֵי חֲכָמִים וְתַלְמִידֵי חֲכָמִים בִּזְמַן שֶׁהָרַבִּים צְרִיכִין לָהֶם מְקַפְּצִין עַל רָאשֵׁי הָעָם וְנִכְנָסִים לִמְקוֹמָם. וְאֵין שֶׁבַח לְתַלְמִידֵי חֲכָמִים שֶׁיִּכָּנְסוּ לָאַחֲרוֹנָה. יָצָא לְצֹרֶךְ חוֹזֵר לִמְקוֹמוֹ. בְּנֵי חֲכָמִים בִּזְמַן שֶׁיֵּשׁ בָּהֶן דַּעַת לִשְׁמֹעַ הוֹפְכִין פְּנֵיהֶן כְּלַפֵּי אֲבִיהֶן. אֵין בָּהֶן דַּעַת לִשְׁמֹעַ הוֹפְכִין פְּנֵיהֶן כְּלַפֵּי הָעָם:","תַּלְמִיד שֶׁהוּא יוֹשֵׁב לִפְנֵי רַבּוֹ תָּמִיד אֵינוֹ רַשַּׁאי לַעֲמֹד מִפָּנָיו אֶלָּא שַׁחֲרִית וְעַרְבִית בִּלְבַד שֶׁלֹּא יְהֵא כְּבוֹדוֹ מְרֻבֶּה מִכְּבוֹד שָׁמַיִם:","מִי שֶׁהוּא זָקֵן מֻפְלָג בְּזִקְנָה אַף עַל פִּי שֶׁאֵינוֹ חָכָם עוֹמְדִין לְפָנָיו. וַאֲפִלּוּ הֶחָכָם שֶׁהוּא יֶלֶד עוֹמֵד בִּפְנֵי הַזָּקֵן הַמֻּפְלָג בְּזִקְנָה. וְאֵינוֹ חַיָּב לַעֲמֹד מְלֹא קוֹמָתוֹ אֶלָּא כְּדֵי לְהַדְּרוֹ. וַאֲפִלּוּ זָקֵן כּוּתִי מְהַדְּרִין אוֹתוֹ בִּדְבָרִים וְנוֹתְנִין לוֹ יָד לְסָמְכוֹ שֶׁנֶּאֱמַר (ויקרא יט לב) \"מִפְּנֵי שֵׂיבָה תָּקוּם\" כָּל שֵׂיבָה בְּמַשְׁמָע:","תַּלְמִידֵי חֲכָמִים אֵינָם יוֹצְאִין בְּעַצְמָן לַעֲשׂוֹת עִם כָּל הַקָּהָל בְּבִנְיָן וַחֲפִירָה שֶׁל מְדִינָה וְכַיּוֹצֵא בָּהֶן כְּדֵי שֶׁלֹּא יִתְבַּזּוּ בִּפְנֵי עַמֵּי הָאָרֶץ. וְאֵין גּוֹבִין מֵהֶן לְבִנְיַן הַחוֹמָה וְתִקּוּן הַשְּׁעָרִים וּשְׂכַר הַשּׁוֹמְרִים וְכַיּוֹצֵא בָּהֶן וְלֹא לִתְשׁוּרַת הַמֶּלֶךְ. וְאֵין מְחַיְּבִים אוֹתָן לִתֵּן הַמַּס בֵּין מַס שֶׁהוּא קָצוּב עַל בְּנֵי הָעִיר בֵּין מַס שֶׁהוּא קָצוּב עַל כָּל אִישׁ וָאִישׁ שֶׁנֶּאֱמַר (הושע ח י) \"גַּם כִּי יִתְנוּ בַגּוֹיִם עַתָּה אֲקַבְּצֵם וַיָּחֵלּוּ מְּעָט מִמַּשָּׂא מֶלֶךְ וְשָׂרִים\". וְכֵן אִם הָיְתָה סְחוֹרָה לְתַלְמִיד חָכָם מְנִיחִים אוֹתוֹ לִמְכֹּר תְּחִלָּה וְאֵין מְנִיחִים אֶחָד מִבְּנֵי הַשּׁוּק לִמְכֹּר עַד שֶׁיִּמְכֹּר הוּא. וְכֵן אִם הָיָה לוֹ דִּין וְהָיָה עוֹמֵד בִּכְלַל בַּעֲלֵי דִּינִים הַרְבֵּה מַקְדִּימִין אוֹתוֹ וּמוֹשִׁיבִין אוֹתוֹ:","עָוֹן גָּדוֹל הוּא לְבַזּוֹת אֶת הַחֲכָמִים אוֹ לִשְׂנוֹאתָן. לֹא חָרְבָה יְרוּשָׁלַיִם עַד שֶׁבִּזּוּ בָּהּ תַּלְמִידֵי חֲכָמִים שֶׁנֶּאֱמַר (דברי הימים ב לו טז) \"וַיִּהְיוּ מַלְעִבִים בְּמַלְאֲכֵי הָאֱלֹהִים וּבוֹזִים דְּבָרָיו וּמִתַּעְתְּעִים בִּנְבִאָיו\". כְּלוֹמַר בּוֹזִים מְלַמְּדֵי דְּבָרָיו. וְכֵן זֶה שֶׁאָמְרָה תּוֹרָה (ויקרא כו טו) \"אִם בְּחֻקֹּתַי תִּמְאָסוּ\", מְלַמְּדֵי חֻקּוֹתַי תִּמְאֲסוּ. וְכָל הַמְבַזֶּה אֶת הַחֲכָמִים אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא וַהֲרֵי הוּא בִּכְלַל (במדבר טו לא) \"כִּי דְבַר ה' בָּזָה\":","אַף עַל פִּי שֶׁהַמְבַזֶּה אֶת הַחֲכָמִים אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא, אִם בָּאוּ עֵדִים שֶׁבִּזָּהוּ אֲפִלּוּ בִּדְבָרִים חַיָּב נִדּוּי, וּמְנַדִּין אוֹתוֹ בֵּית דִּין בָּרַבִּים וְקוֹנְסִין אוֹתוֹ לִיטְרָא זָהָב בְּכָל מָקוֹם וְנוֹתְנִין אוֹתָהּ לֶחָכָם. וְהַמְבַזֶּה אֶת הֶחָכָם בִּדְבָרִים אֲפִלּוּ לְאַחַר מִיתָה מְנַדִּין אוֹתוֹ בֵּית דִּין וְהֵם מַתִּירִים אוֹתוֹ כְּשֶׁיַּחֲזֹר בִּתְשׁוּבָה. אֲבָל אִם הָיָה הֶחָכָם חַי אֵין מַתִּירִין אוֹתוֹ עַד שֶׁיְּרַצֶּה זֶה שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ. וְכֵן הֶחָכָם עַצְמוֹ מְנַדֶּה לִכְבוֹדוֹ לְעַם הָאָרֶץ שֶׁהִפְקִיר בּוֹ וְאֵין צָרִיךְ לֹא עֵדִים וְלֹא הַתְרָאָה. וְאֵין מַתִּירִין לוֹ עַד שֶׁיְּרַצֶּה אֶת הֶחָכָם. וְאִם מֵת הֶחָכָם בָּאִין שְׁלֹשָׁה וּמַתִּירִין לוֹ. וְאִם רָצָה הֶחָכָם לִמְחל לוֹ וְלֹא נִדָּהוּ הָרְשׁוּת בְּיָדוֹ:","הָרַב שֶׁנִּדָּה לִכְבוֹדוֹ כָּל תַּלְמִידָיו חַיָּבִין לִנְהֹג נִדּוּי בַּמְנֻדֶּה. אֲבָל תַּלְמִיד שֶׁנִּדָּה לִכְבוֹד עַצְמוֹ אֵין הָרַב חַיָּב לִנְהֹג בּוֹ נִדּוּי. אֲבָל כָּל הָעָם חַיָּבִין לִנְהֹג בּוֹ נִדּוּי. וְכֵן מְנֻדֶּה לְנָשִׂיא מְנֻדֶּה לְכָל יִשְׂרָאֵל. מְנֻדֶּה לְכָל יִשְׂרָאֵל אֵינוֹ מְנֻדֶּה לַנָּשִׂיא. מְנֻדֶּה לְעִירוֹ מְנֻדֶּה לְעִיר אַחֶרֶת. מְנֻדֶּה לְעִיר אַחֶרֶת אֵינוֹ מְנֻדֶּה לְעִירוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִי שֶׁנִּדּוּהוּ עַל שֶׁבִּזָּה תַּלְמִידֵי חֲכָמִים. אֲבָל מִי שֶׁנִּדּוּהוּ עַל שְׁאָר דְּבָרִים שֶׁחַיָּבִים עֲלֵיהֶם נִדּוּי אֲפִלּוּ נִדָּהוּ קָטָן שֶׁבְּיִשְׂרָאֵל חַיָּב הַנָּשִׂיא וְכָל יִשְׂרָאֵל לִנְהֹג בּוֹ נִדּוּי עַד שֶׁיַּחֲזֹר בִּתְשׁוּבָה מִדָּבָר שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ וְיַתִּירוּ לוֹ. עַל עֶשְׂרִים וְאַרְבָּעָה דְּבָרִים מְנַדִּין אֶת הָאָדָם בֵּין אִישׁ בֵּין אִשָּׁה. וְאֵלּוּ הֵן: א) הַמְבַזֶּה אֶת הֶחָכָם וַאֲפִלּוּ לְאַחַר מוֹתוֹ. ב) הַמְבַזֶּה שְׁלִיחַ בֵּית דִּין. ג) הַקּוֹרֵא לַחֲבֵרוֹ עֶבֶד. ד) מִי שֶׁשָּׁלְחוּ לוֹ בֵּית דִּין וְקָבְעוּ לוֹ זְמַן וְלֹא בָּא. ה) הַמְזַלְזֵל בְּדָבָר אֶחָד מִדִּבְרֵי סוֹפְרִים וְאֵין צָרִיךְ לוֹמַר בְּדִבְרֵי תּוֹרָה. ו) מִי שֶׁלֹּא קִבֵּל עָלָיו אֶת הַדִּין מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. ז) מִי שֶׁיֵּשׁ בִּרְשׁוּתוֹ דָּבָר הַמַּזִּיק כְּגוֹן כֶּלֶב רַע אוֹ סֻלָּם רָעוּעַ מְנַדִּין אוֹתוֹ עַד שֶׁיָּסִיר הֶזֵּקוֹ. ח) הַמּוֹכֵר קַרְקַע שֶׁלּוֹ לְעוֹבֵד כּוֹכָבִים מְנַדִּין אוֹתוֹ עַד שֶׁיְּקַבֵּל עָלָיו כָּל אֹנֶס שֶׁיָּבוֹא מִן הָעוֹבֵד כּוֹכָבִים לְיִשְׂרָאֵל חֲבֵרוֹ בַּעַל הַמֵּצָר. ט) הַמֵּעִיד עַל יִשְׂרָאֵל בְּעַרְכָּאוֹת שֶׁל עוֹבְדֵי כּוֹכָבִים וְהוֹצִיא מִמֶּנּוּ בְּעֵדוּתוֹ מָמוֹן שֶׁלֹּא כְּדִין יִשְׂרָאֵל, מְנַדִּין אוֹתוֹ עַד שֶׁיְּשַׁלֵּם. י) טַבָּח כֹּהֵן שֶׁאֵינוֹ מַפְרִישׁ הַמַּתָּנוֹת וְנוֹתְנָן לְכֹהֵן אַחֵר מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. יא) הַמְחַלֵּל יוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת אַף עַל פִּי שֶׁהוּא מִנְהָג. יב) הָעוֹשֶׂה מְלָאכָה בְּעֶרֶב הַפֶּסַח אַחַר חֲצוֹת. יג) הַמַּזְכִּיר שֵׁם שָׁמַיִם לְבַטָּלָה אוֹ לִשְׁבוּעָה בְּדִבְרֵי הֲבַאי. יד) הַמֵּבִיא אֶת הָרַבִּים לִידֵי חִלּוּל הַשֵּׁם. טו) הַמֵּבִיא אֶת הָרַבִּים לִידֵי אֲכִילַת קָדָשִׁים בַּחוּץ. טז) הַמְחַשֵּׁב שָׁנִים וְקוֹבֵעַ חֳדָשִׁים בְּחוּצָה לָאָרֶץ. יז) הַמַּכִשִׁיל אֵת הָעִוֵּר. יח) הַמְעַכֵּב הָרַבִּים מִלַּעֲשׂוֹת מִצְוָה. יט) טַבָּח שֶׁיָּצְאָה טְרֵפָה מִתַּחַת יָדוֹ. כ) טַבָּח שֶׁלֹּא בָּדַק סַכִּינוֹ לִפְנֵי חָכָם. כא) הַמַּקְשֶׁה עַצְמוֹ לְדַעַת. כב) מִי שֶׁגֵּרֵשׁ אֶת אִשְׁתּוֹ וְעָשָׂה בֵּינוֹ וּבֵינָהּ שֻׁתָּפוּת אוֹ מַשָּׂא וּמַתָּן הַמְּבִיאִין לָהֶן לְהִזָּקֵק זֶה לָזֶה כְּשֶׁיָּבוֹאוּ לְבֵית דִּין מְנַדִּין אוֹתָם. כג) חָכָם שֶׁשְּׁמוּעָתוֹ רָעָה. כד) הַמְנַדֶּה מִי שֶׁאֵינוֹ חַיָּב נִדּוּי:"],"Mishneh Torah, Transmission of the Oral Law 19":["וּמִגְּדוֹלֵי הַחֲכָמִים שֶׁקִּבְּלוּ מֵרָב וּשְׁמוּאֵל – רָב הוּנָא, וְרָב יְהוּדָה, וְרָב נַחְמָן, וְרָב כַּהֲנָא; וּמִגְּדוֹלֵי הַחֲכָמִים שֶׁקִּבְּלוּ מֵרִבִּי יוֹחָנָן – רַבָּה בַּר בַּר חָנָה, וְרִבִּי אַמֵי, וְרִבִּי אַסֵי, וְרָב דִּימֵי, וְרַאבּוּן."],"Mishneh Torah, Transmission of the Oral Law 3":["וְהַמִּצְוָה, שְׁהִיא פֵּרוּשׁ הַתּוֹרָה – לֹא כְתָבָהּ; אֵלָא צִוָּה בָּהּ לַזְּקֵנִים וְלִיהוֹשׁוּעַ וְלִשְׁאָר כָּל יִשְׂרָאֵל, שֶׁנֶּאֱמָר \"אֵת כָּל־הַדָּבָר, אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם – אֹתוֹ תִשְׁמְרוּ, לַעֲשׂוֹת . . .\" (דברים יג, א). וּמִפְּנֵי זֶה נִקְרֵאת תּוֹרָה שֶׁבְּעַל פֶּה."],"Mishneh Torah, Transmission of the Oral Law 40":["וּבַזְּמָן הַזֶּה תָּכְפוּ צָרוֹת יְתֵרוֹת, וְדָחֲקָה שָׁעָה אֶת הַכֹּל, וְאָבְדָה חָכְמַת חֲכָמֵינוּ, וּבִינַת נְבוֹנֵינוּ נִסְתַּתְּרָה; לְפִיכָּךְ אוֹתָן הַפֵּרוּשִׁין וְהַתְּשׁוּבוֹת וְהַהֲלָכוֹת שֶׁחִבְּרוּ הַגְּאוֹנִים, וְרָאוּ שְׁהֶם דְּבָרִים מְבֹאָרִים, נִתְקַשּׁוּ בְּיָמֵינוּ, וְאֵין מֵבִין עִנְיְנֵיהֶם כָּרָאוּי אֵלָא מְעַט בְּמִסְפָּר. וְאֵין צָרִיךְ לוֹמַר, הַתַּלְמוּד עַצְמוֹ: הַבַּבְלִי, וְהַיְּרוּשְׁלְמִי, וְסִפְרָא, וְסִפְרֵי, וְהַתּוֹסֶפְתּוֹת – שְׁהֶן צְרִיכִין דַּעַת רְחָבָה וְנֶפֶשׁ חֲכָמָה וּזְמָן אָרוּךְ, וְאַחַר כָּךְ יִוָּדַע מֵהֶן הַדֶּרֶךְ הַנְּכוֹחָה בַּדְּבָרִים הָאֲסוּרִין וְהַמֻּתָּרִין וּשְׁאָר דִּינֵי תּוֹרָה הֵיאַךְ הִיא."],"Mishneh Torah, Trespass 2":["קָדָשִׁים קַלִּים אֵין מוֹעֲלִין בָּהֶן עַד שֶׁיִּזָּרֵק הַדָּם. נִזְרַק הַדָּם מוֹעֲלִין בְּאֵימוּרֵיהֶן עַד שֶׁיֵּצְאוּ לְבֵית הַדֶּשֶׁן שֶׁהֲרֵי הֵן לָאִשִּׁים וְאֵין מוֹעֲלִין בְּדָבָר הַנֶּאֱכָל כְּמוֹ שֶׁבֵּאַרְנוּ. אֲפִלּוּ הֶעֱלָה הָאֵימוּרִין שֶׁלָּהֶן לַמִּזְבֵּחַ קֹדֶם זְרִיקָה אֵין מוֹעֲלִין בָּהֶן עַד שֶׁיִּזָּרֵק הַדָּם. הוֹצִיא אֵימוּרֵיהֶן לַחוּץ קֹדֶם זְרִיקָה אֵין מוֹעֲלִין בָּהֶן עַד שֶׁיִּזָּרֵק הַדָּם. נִזְרַק הַדָּם אַף עַל פִּי שֶׁעֲדַיִן הֵן בַּחוּץ וְלֹא הֶחְזִירָן מוֹעֲלִין בָּהֶן. שֶׁהַזְּרִיקָה מוֹעֶלֶת לַיּוֹצֵא בֵּין לְהָקֵל בֵּין לְהַחְמִיר:","כָּל קָדְשֵׁי קָדָשִׁים מוֹעֲלִין בָּהֶן מִשֶּׁהֻקְדְּשׁוּ עַד שֶׁיִּזָּרֵק הַדָּם. נִזְרַק הַדָּם מוֹעֲלִין בָּהֶן בְּדָבָר שֶׁכֻּלּוֹ לָאִשִּׁים עַד שֶׁיִּשָּׂרֵף וְיֵצֵא לְבֵית הַדֶּשֶׁן וְאֵין מוֹעֲלִין בְּדָבָר הַנֶּאֱכָל כְּמוֹ שֶׁבֵּאַרְנוּ:","כֵּיצַד הָעוֹלָה. אֶחָד עוֹלַת הָעוֹף וְאֶחָד עוֹלַת בְּהֵמָה וְהַקֹּמֶץ וְהַלְּבוֹנָה וּמִנְחַת כֹּהֲנִים וְהַחֲבִיתִין וּמִנְחַת נְסָכִים מוֹעֲלִין בָּהֶן מִשְּׁעַת הֶקְדֵּשָׁן עַד שֶׁיֵּצְאוּ אַחַר שְׂרֵפָתָן עַל הַמִּזְבֵּחַ לְבֵית הַדֶּשֶׁן:","וְכֵן פָּרִים הַנִּשְׂרָפִין וּשְׂעִירִים הַנִּשְׂרָפִין מוֹעֲלִין בָּהֶן מִשְּׁעַת הֶקְדֵּשָׁן עַד שֶׁיִּשָּׂרְפוּ וְתִגָּמֵר שְׂרֵפָתָן בְּבֵית הַדֶּשֶׁן וְיִתֹךְ הַבָּשָׂר. אֲבָל קֹדֶם שֶׁיִּתֹךְ מוֹעֲלִין בּוֹ וְהוּא בְּבֵית הַדֶּשֶׁן:","וְכֵן פָּרָה אֲדֻמָּה מוֹעֲלִין בָּהּ מִשֶּׁהֻקְדְּשָׁה עַד שֶׁתֵּעָשֶׂה אֵפֶר. אַף עַל פִּי שֶׁהִיא כְּקָדְשֵׁי בֶּדֶק הַבַּיִת הֲרֵי נֶאֱמַר בָּהּ (במדבר יט ט) \"חַטָּאת הִיא\". וּתְנַאי בֵּית דִּין הוּא שֶׁלֹּא יִמְעל אָדָם בְּאֵפֶר הַפָּרָה:","חַטַּאת בְּהֵמָה וְאָשָׁם וְזִבְחֵי שַׁלְמֵי צִבּוּר מוֹעֲלִים בְּכֻלָּן מִשֶּׁהֻקְדְּשׁוּ עַד שֶׁיִּזָּרֵק הַדָּם. נִזְרַק הַדָּם מוֹעֲלִין בְּאֵימוּרֵיהֶן עַד שֶׁיֵּצְאוּ לְבֵית הַדֶּשֶׁן. וְאֵין מוֹעֲלִין בַּבָּשָׂר. וְכֵן חַטַּאת הָעוֹף מוֹעֲלִין בָּהּ מִשֶּׁהֻקְדְּשׁוּ עַד שֶׁיַּזֶּה דָּמָהּ. הֻזָּה דָּמָהּ אֵין בָּהּ מְעִילָה. אֲבָל אָסוּר לֵהָנוֹת בְּמֻרְאָתָהּ וְנוֹצָתָהּ. וְהַנֶּהֱנֶה בָּהֶן אַחַר הַזָּיָה לֹא מָעַל:","הַמְּנָחוֹת מוֹעֲלִין בָּהֶן מִשֶּׁהֻקְדְּשׁוּ אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְקַדְּשׁוּ בִּכְלִי שָׁרֵת עַד שֶׁיַּקְטִיר הַקֹּמֶץ. קָרַב הַקֹּמֶץ הֻתְּרוּ הַשְּׁיָרִים בַּאֲכִילָה. וְאִם נִפְסְלוּ הַשְּׁיָרִים אוֹ חָסְרוּ וְאַחַר כָּךְ הִקְטִיר הַקֹּמֶץ הוֹאִיל וְהַקְטָרָה זוֹ אֵינָהּ מַתֶּרֶת הַשְּׁיָרִים בַּאֲכִילָה הֲרֵי הַדָּבָר סָפֵק אִם יָצְאוּ יְדֵי מְעִילָה אוֹ לֹא יָצְאוּ:","לֶחֶם הַפָּנִים מוֹעֲלִין בּוֹ מִשֶּׁהֻקְדַּשׁ אַף עַל פִּי שֶׁעֲדַיִן לֹא נֶאֱפָה עַד שֶׁיַּקְטִיר הַבְּזִיכִין. הִקְטִיר הַבְּזִיכִין הֻתַּר בַּאֲכִילָה. וְכֵן שְׁתֵּי הַלֶּחֶם מוֹעֲלִין בָּהֶן מִשֶּׁהֻקְדְּשׁוּ קֹדֶם שֶׁיֵּאָפוּ עַד שֶׁיִּזָּרֵק דַּם הַכְּבָשִׂים. נִזְרַק דַּם הַכְּבָשִׂים הֻתַּר בַּאֲכִילָה:","הַנְּסָכִים מוֹעֲלִין בָּהֶן מִשֶּׁהֻקְדְּשׁוּ. יָרְדוּ לַשִּׁיתִין אֵין מוֹעֲלִין בָּהֶן. מַיִם שֶׁמְּנַסְּכִים בְּחַג הַסֻּכּוֹת כָּל זְמַן שֶׁהֵן בְּכַד שֶׁל זָהָב אֵין נֶהֱנִין בָּהֶן וְהַנֶּהֱנֶה לֹא מָעַל. נָתְנוּ אוֹתָן בִּצְלוֹחִית מוֹעֲלִין בְּכֻלָּן. שֶׁהֲרֵי הֵן מִכְּלַל הַנְּסָכִים:","לוֹג שֶׁמֶן שֶׁל מְצֹרָע מוֹעֲלִין בּוֹ מִשֶּׁהֻקְדַּשׁ בִּכְלִי עַד שֶׁיִּזָּרֵק דַּם הָאָשָׁם. נִזְרַק דַּם הָאָשָׁם לֹא נֶהֱנִין וְלֹא מוֹעֲלִין עַד שֶׁיִּתְּנוּ מִמֶּנּוּ מַתְּנוֹתָיו. נָתְנוּ מִמֶּנּוּ הַמַּתָּנוֹת הֻתְּרוּ הַשְּׁיָרִים בַּאֲכִילָה כִּבְשַׂר חַטָּאת וְאָשָׁם:","כָּל דָּמֵי שְׁחִיטַת הַקָּדָשִׁים אֵין מוֹעֲלִין בּוֹ בֵּין לִפְנֵי כַּפָּרָה בֵּין לְאַחַר כַּפָּרָה עַד שֶׁיֵּצֵא לְנַחַל קִדְרוֹן. יָצָא לְנַחַל קִדְרוֹן מוֹעֲלִין בּוֹ מִפְּנֵי שֶׁהָיָה נִמְכַּר לְגַנּוֹת וְדָמָיו הֶקְדֵּשׁ. אֲבָל הַמַּקִּיז דָּם לְבֶהֱמַת קָדָשִׁים הֲרֵי הוּא אָסוּר בַּהֲנָיָה וּמוֹעֲלִין בּוֹ. הוֹאִיל וְאֵינָהּ יְכוֹלָה לִחְיוֹת בְּלֹא דָּם הֲרֵי הוּא כְּגוּפָהּ:","הָעֲצָמוֹת וְהַגִּידִים וְהַקַּרְנַיִם וְהַטְּלָפַיִם שֶׁפֵּרְשׁוּ מִקָּדְשֵׁי קָדָשִׁים לִפְנֵי זְרִיקַת דָּמִים מוֹעֲלִין בָּהֶן. פֵּרְשׁוּ לְאַחַר זְרִיקַת דָּמִים אֵין מוֹעֲלִין בָּהֶן. עַצְמוֹת הָעוֹלָה שֶׁפֵּרְשׁוּ לִפְנֵי זְרִיקָה אֵין מוֹעֲלִין בָּהֶן לְאַחַר זְרִיקָה שֶׁהַזְּרִיקָה מַתֶּרֶת אוֹתָם. וְאִם פֵּרְשׁוּ אַחַר זְרִיקָה מוֹעֲלִין בָּהֶן לְעוֹלָם. עַצְמוֹת הָעוֹלָה שֶׁפָּקְעוּ מֵעַל הַמִּזְבֵּחַ קֹדֶם חֲצוֹת הַלַּיְלָה מוֹעֲלִין בָּהֶן. לְאַחַר חֲצוֹת אֵין מוֹעֲלִין בָּהֶן. אַף עַל פִּי שֶׁפָּקְעוּ קֹדֶם חֲצוֹת כֵּיוָן שֶׁהִגִּיעַ חֲצוֹת הַלַּיְלָה נַעֲשׂוּ כָּל הָאֵיבָרִים כְּמִי שֶׁנִּתְאַכְּלוּ וְנַעֲשׂוּ אֵפֶר:","גַּחֶלֶת שֶׁפָּקְעָה מֵעַל הַמִּזְבֵּחַ בֵּין לִפְנֵי חֲצוֹת בֵּין לְאַחַר חֲצוֹת לֹא נֶהֱנִין וְלֹא מוֹעֲלִין. אֲבָל גַּחֶלֶת שֶׁל קָדְשֵׁי בֶּדֶק הַבַּיִת מוֹעֲלִין בָּהּ. וְהַשַּׁלְהֶבֶת לֹא נֶהֱנִין וְלֹא מוֹעֲלִין:","דֶּשֶׁן הַמִּזְבֵּחַ הַחִיצוֹן בֵּין קֹדֶם הֲרָמַת הַדֶּשֶׁן בֵּין אַחַר הֲרָמָה מוֹעֲלִין בּוֹ:","דִּשׁוּן הַמִּזְבֵּחַ הַפְּנִימִי וְדִשׁוּן הַמְּנוֹרָה לֹא נֶהֱנִין וְלֹא מוֹעֲלִין:","כָּל בֶּהֱמַת קָדְשֵׁי קָדָשִׁים שֶׁהִיא בַּעֲלַת מוּם בֵּין שֶׁקָּדַם מוּם קָבוּעַ לְהֶקְדֵּשָׁהּ בֵּין שֶׁקָּדַם הֶקְדֵּשָׁהּ לְמוּם קָבוּעַ וַאֲפִלּוּ הָיְתָה מְחֻסַּר זְמַן מוֹעֲלִין בָּהֶם מִשֶּׁהֻקְדְּשׁוּ עַד שֶׁיִּפָּדוּ. אֲבָל תּוֹרִין שֶׁלֹּא הִגִּיעַ זְמַנָּן וּבְנֵי יוֹנָה שֶׁעָבַר זְמַנָּן וְהֵן קָדְשֵׁי מִזְבֵּחַ אַף עַל פִּי שֶׁאָסוּר לֵהָנוֹת בָּהֶן הַנֶּהֱנֶה לֹא מָעַל. הוֹאִיל וְאֵינָן רְאוּיִין לְפִדְיוֹן הֲרֵי הֵם כַּחַטָּאוֹת הַמֵּתוֹת לְפִיכָךְ אֵין מוֹעֲלִין בָּהֶן:"],"Mishneh Torah, Vessels 14":["כָּל הַמַּצִּיל בְּצָמִיד פָּתִיל בְּאֹהֶל הַמֵּת מַצִּיל בְּצָמִיד פּתִיל בּאֲוִיר כְּלִי חֶרֶס. אִם הִצִּיל בְּמֵת הֶחָמוּר דִּין הוּא שֶׁיַּצִּיל בִּכְלִי חֶרֶס הַקַּל. וְכָל שֶׁאֵינוֹ מַצִּיל בְּאֹהֶל הַמֵּת אֵינוֹ מַצִּיל בַּאֲוִיר כְּלִי חֶרֶס:","וּכְשֵׁם שֶׁאֵין צָמִיד פָּתִיל לְטֻמְאָה בְּאֹהֶל הַמֵּת כָּךְ אֵין צָמִיד פָּתִיל לְטֻמְאָה בַּאֲוִיר כְּלִי חֶרֶס. כֵּיצַד. קְדֵרָה שֶׁהִיא מְלֵאָה אֳכָלִין וּמַשְׁקִין וּמֻקֶּפֶת צָמִיד פָּתִיל וּנְתוּנָה בְּתוֹךְ הַתַּנּוּר הַטָּמֵא הֲרֵי הַקְּדֵרָה וְכָל מַה שֶּׁבְּתוֹכָהּ טְהוֹרִין. הָיָה הַשֶּׁרֶץ אוֹ מַשְׁקִין טְמֵאִין בְּתוֹכָהּ וּמֻקֶּפֶת צָמִיד פָּתִיל וּנְתוּנָה בַּאֲוִיר הַתַּנּוּר נִטְמָא הַתַּנּוּר [וְכֵן כָּל כַּיּוֹצֵא בָּזֶה]:","טַבַּעַת טְמֵאָה שֶׁמֻּבְלַעַת בְּתוֹךְ הַלְּבֵנָה אוֹ מַחַט טְמֵאָה שֶׁמֻּבְלַעַת בְּתוֹךְ הָעֵץ וְנָפְלוּ לַאֲוִיר כְּלִי חֶרֶס נִטְמָא. אַף עַל פִּי שֶׁאִם נָגַע כִּכַּר תְּרוּמָה בְּעֵץ זֶה אוֹ בִּלְבֵנָה זוֹ טָהוֹר הֲרֵי הֵן מְטַמְּאִין כְּלִי חֶרֶס מֵאֲוִירוֹ:","תַּרְנְגוֹל שֶׁבָּלַע שֶׁרֶץ אוֹ בְּשַׂר מֵת וְנָפַל לַאֲוִיר הַתַּנּוּר הֲרֵי זֶה טָהוֹר. וְאִם מֵת שָׁם הַתַּרְנְגוֹל נִטְמָא הַתַּנּוּר. שֶׁהַבְּלוּעִין בְּחַי מַצִּילִין מִיַּד כְּלִי חֶרֶס כְּדֶרֶךְ שֶׁמַּצִּילִין בְּאֹהֶל הַמֵּת:","דְּבָרִים שֶׁבְּתוֹךְ הַפֶּה אוֹ בְּתוֹךְ הַקְּמָטִין אֵינָן כִּבְלוּעִין. כֵּיצַד. אָדָם שֶׁהָיוּ מַשְׁקִין טְמֵאִין בְּתוֹךְ פִּיו וְקָפַץ פִּיו וְהִכְנִיס רֹאשׁוֹ לַאֲוִיר כְּלִי חֶרֶס טִמְּאָהוּ. וְכֵן טָהוֹר שֶׁהָיוּ אֳכָלִין וּמַשְׁקִין לְתוֹךְ פִּיו וְהִכְנִיס רֹאשׁוֹ לַאֲוִיר תַּנּוּר טָמֵא נִטְמְאוּ אֳכָלִים שֶׁבְּפִיו. הָיָה לוֹ בְּתוֹךְ קֻמְטוֹ כַּעֲדָשָׁה מִן הַשֶּׁרֶץ וְהִכְנִיסוֹ לַאֲוִיר הַתַּנּוּר נִטְמָא הַתַּנּוּר אַף עַל פִּי שֶׁהַטֻּמְאָה בְּתוֹךְ הַקֶּמֶט:","סְפוֹג שֶׁבָּלַע מַשְׁקִין טְמֵאִין אַף עַל פִּי שֶׁהוּא נָגוּב מִבַּחוּץ אִם נָפַל לַאֲוִיר כְּלִי חֶרֶס טִמְּאָהוּ שֶׁסּוֹף מַשְׁקֶה לָצֵאת. וְכֵן חֲתִיכָה שֶׁל לֶפֶת וְשֶׁל גֶּמִי. חֲרָסִים שֶׁנִּשְׁתַּמְּשׁוּ בָּהֶן מַשְׁקִין טְמֵאִין וְנִגְּבוּ וְנָפְלוּ לַאֲוִיר כְּלִי חֶרֶס לֹא טִמְּאוּהוּ. נָפְלוּ לְתַנּוּר וְהֻסַּק נִטְמָא שֶׁסּוֹף מַשְׁקֶה לָצֵאת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמַשְׁקִין קַלִּין. אֲבָל בַּחֲמוּרִין כְּגוֹן דַּם הַנִּדָּה וּמֵימֵי רַגְלֶיהָ אִם הָיוּ יְכוֹלִין לָצֵאת וְהִקְפִּיד עָלָיו שֶׁיֵּצֵא הֲרֵי זֶה מְטַמֵּא הַתַּנּוּר אַף עַל פִּי שֶׁלֹּא הֻסַּק וְאִם אֵינוֹ מַקְפִּיד עָלָיו אֵינוֹ מְטַמֵּא עַד שֶׁיֻּסַּק וְיֵצֵא הַמַּשְׁקֶה. וְכֵן בְּגֶפֶת חֲדָשָׁה הַבָּאָה מִמַּשְׁקִין טְמֵאִין שֶׁהֻסַּק בָּהּ הַתַּנּוּר נִטְמָא שֶׁסּוֹף מַשְׁקֶה לָצֵאת אֲבָל בִּישָׁנָה טָהוֹר. אֵיזוֹ הִיא יְשָׁנָה לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ. וְאִם יָדוּעַ שֶׁיָּצָא מִמֶּנָּה מַשְׁקֶה בִּשְׁעַת הֶסֵּק אֲפִלּוּ לְאַחַר שָׁלֹשׁ שָׁנִים נִטְמָא הַתַּנּוּר כְּשֶׁיֻּסַּק:","כְּלִי חֶרֶס שֶׁחִלְּקוֹ בִּמְחִצָּה מִשְּׂפָתוֹ עַד קַרְקָעִיתוֹ וְנִכְנְסָה טֻמְאָה בַּאֲוִיר אֶחָד מִשְּׁנֵי הַחֲלָקִים נִטְמָא הַכְּלִי כֻּלּוֹ לְפִי שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְחַלֵּק כְּלֵי חֶרֶס כְּדֶרֶךְ שֶׁחוֹלְקִין הָאֹהָלִים. לְפִיכָךְ תַּנּוּר שֶׁחֲצָצוֹ בִּנְסָרִים אוֹ בִּירִיעוֹת וְנִמְצָא הַשֶּׁרֶץ בְּמָקוֹם אֶחָד הַכּל טָמֵא:","כְּלִי שֶׁהָיְתָה הַטֻּמְאָה בְּתוֹכוֹ וְהִכְנִיס הַכְּלִי לַאֲוִיר כְּלִי חֶרֶס וּשְׂפַת הַכְּלִי הַטָּמֵא חוּץ לִכְלִי חֶרֶס אַף עַל פִּי שֶׁהַטֻּמְאָה מְכֻוֶּנֶת בְּתוֹךְ כְּלִי חֶרֶס הֲרֵי זֶה טָהוֹר שֶׁנֶּאֱמַר (ויקרא יא לג) \"אֶל תּוֹכוֹ\" לֹא אֶל תּוֹךְ תּוֹכוֹ:","וְכֵן אִם הָיָה כְּלִי חֶרֶס טָמֵא וְהִכְנִיס לַאֲוִירוֹ כְּלִי אַחֵר שֶׁיֵּשׁ בּוֹ אֳכָלִים וּמַשְׁקִין וּשְׂפַת הַכְּלִי הָאַחֵר חוּץ לִכְלִי חֶרֶס אַף עַל פִּי שֶׁהָאֳכָלִין וְהַמַּשְׁקִין מְכֻוָּנִין בְּתוֹךְ כְּלִי חֶרֶס הַטָּמֵא הֲרֵי אֵלּוּ טְהוֹרִין שֶׁנֶּאֱמַר (ויקרא יא לג) \"כּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא\" וְלֹא שֶׁבְּתוֹךְ תּוֹכוֹ. כֵּיצַד. כַּוֶּרֶת אוֹ קֻפָּה אוֹ קְדֵרָה אוֹ חֵמֶת וְכַיּוֹצֵא בָּהֶן שֶׁהָיָה הַשֶּׁרֶץ בְּתוֹכָהּ וְשִׁלְשֵׁל הַקֻּפָּה לַאֲוִיר הֶחָבִית אוֹ לַאֲוִיר הַתַּנּוּר אַף עַל פִּי שֶׁהַשֶּׁרֶץ מְכֻוָּן בְּתוֹךְ אֲוִיר הֶחָבִית הוֹאִיל וּשְׂפַת הַקֻּפָּה אוֹ הַחֵמֶת לְמַעְלָה מִשְּׂפַת הֶחָבִית אוֹ מִשְּׂפַת הַתַּנּוּר הֲרֵי אֵלּוּ טְהוֹרִין. וְאִם הָיָה בְּתוֹךְ הַחֵמֶת אוֹ בְּתוֹךְ הַקְּדֵרָה וְכַיּוֹצֵא בָּהֶן אֳכָלִין אוֹ מַשְׁקִין וְשִׁלְשְׁלָן לַאֲוִיר הַתַּנּוּר אוֹ לַאֲוִיר הֶחָבִית הַטְּמֵאִין הֲרֵי הֵן טְהוֹרִין. הָיְתָה הַכַּוֶּרֶת אוֹ הַקֻּפָּה אוֹ הַחֵמֶת וְכַיּוֹצֵא בָּהֶן נְקוּבִין אֵינָן מַצִּילִין אֶלָּא אִם הָיָה הַשֶּׁרֶץ לְתוֹכָן וְשִׁלְשְׁלָן לַאֲוִיר כְּלִי חֶרֶס הַטָּהוֹר נִטְמָא. וְאִם הָיוּ אֳכָלִין אוֹ מַשְׁקִין לְתוֹכָן וְשִׁלְשְׁלָן לַאֲוִיר כְּלִי חֶרֶס הַטָּמֵא נִטְמְאוּ. וְכַמָּה יִהְיֶה בַּנֶּקֶב אִם הָיָה בִּכְלִי שֶׁטֶף בְּמוֹצִיא זֵיתִים וְאִם הָיָה בִּכְלִי חֶרֶס הֶעָשׂוּי לָאֳכָלִין שִׁעוּרוֹ כְּזֵיתִים וְהֶעָשׂוּי לְמַשְׁקִין שִׁעוּרוֹ בְּכוֹנֵס מַשְׁקֶה. וְהֶעָשׂוּי לְכָךְ וְכָךְ מְטִילִין אוֹתוֹ לְחֻמְרוֹ וּכְשֶׁיִּנָּקֵב כְּלִי חֶרֶס זֶה בְּכוֹנֵס מַשְׁקֶה אֵינוֹ מַצִּיל מִיַּד כְּלִי חֶרֶס:","סָתַם נֶקֶב כְּלִי חֶרֶס בְּזֶפֶת אִם הָיָה הַשֶּׁרֶץ בִּכְלִי זֶה וְשִׁלְשְׁלוֹ לַאֲוִיר הַתַּנּוּר הַטָּהוֹר נִטְמָא שֶׁאֵין הַצָּמִיד מַצִּיל עַל הַטֻּמְאָה מִלְּטַמֵּא כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם הָיָה בִּכְלִי זֶה אֳכָלִין אוֹ מַשְׁקִין וְשִׁלְשְׁלוֹ לַאֲוִיר הַתַּנּוּר הַטָּמֵא הֲרֵי הֵן טְהוֹרִין שֶׁהֲרֵי הַנֶּקֶב סָתוּם. וּשְׁאָר כָּל הַכֵּלִים שֶׁסְּתָמָן בְּזֶפֶת וְכַיּוֹצֵא בּוֹ אֵינוֹ מַצִּיל מִיַּד כְּלִי חֶרֶס:","כַּוֶּרֶת פְּחוּתָה אַף עַל פִּי שֶׁסָּתַם הַפְּחָת בְּקַשׁ אֵינָהּ מַצֶּלֶת מִיַּד כְּלִי חֶרֶס שֶׁהֲרֵי אֵינָהּ כְּלִי:","הַחֵמֶת וְהַכְּפִישָׁה שֶׁנִּפְחֲתוּ בְּמוֹצִיא רִמּוֹן אַף עַל פִּי שֶׁבִּטְּלוֹ מִתּוֹרַת כְּלִי הֲרֵי אֵלּוּ מַצִּילִין מִיַּד כְּלִי חֶרֶס. וְהוּא שֶׁיִּהְיֶה הַפְּחָת לְמַעְלָה מִשְּׂפַת כְּלִי חֶרֶס מִבַּחוּץ וְיִהְיֶה בֵּית קִבּוּל שֶׁלָּהֶן מְשֻׁלְשָׁל לְתוֹךְ כְּלִי חֶרֶס:","עוֹר פָּשׁוּט וְכַיּוֹצֵא בּוֹ שֶׁהָיָה שָׁקוּעַ לַאֲוִיר כְּלִי חֶרֶס אוֹ לַאֲוִיר הַתַּנּוּר וְהַשֶּׁרֶץ בְּתוֹךְ הָעוֹר הֲרֵי הַתַּנּוּר טָמֵא. וְאִם הָיָה הַשֶּׁרֶץ בַּתַּנּוּר אֳכָלִין וּמַשְׁקִין שֶׁבְּתוֹךְ הָעוֹר טְמֵאִין שֶׁאֵין מַצִּיל מִיַּד כְּלִי חֶרֶס אֶלָּא כֵּלִים שֶׁיֵּשׁ לָהֶן תּוֹךְ כְּגוֹן הַסַּל וְהַקֻּפָּה וְהַחֵמֶת:","כְּלִי חֶרֶס שֶׁהָיְתָה טֻמְאָה בְּתוֹכוֹ וְהָיָה כְּלִי חֶרֶס טָהוֹר כָּפוּי עַל פִּי הַכְּלִי הַטָּמֵא אוֹ שֶׁהָיָה הַכְּלִי שֶׁהַטֻּמְאָה דְּבוּקָה בְּתוֹכוֹ כָּפוּי עַל פִּי הַכְּלִי הַטָּהוֹר אַף עַל פִּי שֶׁאֲוִיר שְׁנֵיהֶן מְעֹרָב הַטָּמֵא בְּטֻמְאָתוֹ וְהַטָּהוֹר בְּטָהֳרָתוֹ שֶׁהֲרֵי לֹא נִכְנְסָה הַטֻּמְאָה עַצְמָהּ לַאֲוִיר כְּלִי חֶרֶס הַטָּהוֹר. לְפִיכָךְ חָבִית שֶׁהָיְתָה מְלֵאָה מַשְׁקִין טְהוֹרִין וּנְתוּנָה לְמַטָּה מִנְּחֻשְׁתּוֹ שֶׁל תַּנּוּר וְנָפַל שֶׁרֶץ לְתוֹךְ הַתַּנּוּר הֲרֵי הֶחָבִית וְהַמַּשְׁקִין טְהוֹרִין אַף עַל פִּי שֶׁאֲוִיר הַתַּנּוּר מְעֹרָב עִם אֲוִיר הֶחָבִית. וְכֵן אִם הָיְתָה הֶחָבִית כְּפוּיָה עַל פִּי הַתַּנּוּר וּפִיהָ לַאֲוִיר הַתַּנּוּר אֲפִלּוּ הַמַּשְׁקֶה שֶׁבְּשׁוּלֵי הֶחָבִית טָהוֹר:"],"Mishneh Torah, Vessels 25":["כָּל פְּשׁוּטֵי כְּלֵי עֵץ הָעֲשׂוּיִין לִישִׁיבָה אוֹ לִשְׁכִיבָה אוֹ לִרְכִיבָה מִתְטַמְּאִין בְּמִדְרָס כְּגוֹן הַמִּטָּה וְהַכִּסֵּא וְכַיּוֹצֵא בָּהֶן:","הַמִּטָּה וְהַכַּר וְהַכֶּסֶת שֶׁל מֵת וְכִסֵּא שֶׁל כַּלָּה וּמַשְׁבֵּר שֶׁל חַיָּה וְכִסֵּא שֶׁל כּוֹבֵס שֶׁכּוֹבֵס עָלָיו אֶת הַכֵּלִים וְכִסֵּא שֶׁל קָטָן שֶׁיֵּשׁ לוֹ רַגְלַיִם אַף עַל פִּי שֶׁאֵין בּוֹ גֹּבַהּ טֶפַח כָּל אֵלּוּ מִתְטַמְּאִין בְּמִדְרָס:","כִּסֵּא שֶׁל בַּרְזֶל שֶׁעוֹשִׂין בְּבֵית הַכִּסֵּא וְהָעוֹר נָתוּן עָלָיו הֲרֵי הוּא מִתְטַמֵּא בְּמִדְרָס וּבִשְׁאָר טֻמְאוֹת. הִפְרִישׁ עוֹר הַמְחֻפֶּה עַל הַבַּרְזֶל הָעוֹר מִתְטַמֵּא בְּמִדְרָס וְהַבַּרְזֶל מִתְטַמֵּא בִּשְׁאָר טֻמְאוֹת אֲבָל לֹא בְּמִדְרָס:","טְרַסְקָל שֶׁל גֶּמִי וְכַיּוֹצֵא בּוֹ הַמְחֻפֶּה בְּעוֹר מִתְטַמֵּא בְּמִדְרָס וּבִשְׁאָר טֻמְאוֹת. הִפְרִישׁ הָעוֹר מֵעָלָיו הָעוֹר מִתְטַמֵּא בְּמִדְרָס אֲבָל הַטְּרַסְקָל טָהוֹר מִכְּלוּם שֶׁהֲרֵי נַעֲשָׂה כְּשִׁבְרֵי כֵּלִים:","סַפְסָלִין שֶׁבַּמֶּרְחָץ שֶׁשְּׁתֵּי רַגְלָיו שֶׁל עֵץ מִתְטַמֵּא בְּמִדְרָס. הָיְתָה אַחַת שֶׁל עֵץ וְאַחַת שֶׁל שַׁיִשׁ אֵינוֹ מְקַבֵּל טֻמְאָה:","נְסָרִים שֶׁבַּמֶּרְחָץ שֶׁשִּׁגְמָן אֵינָן מְקַבְּלִין טֻמְאָה שֶׁאֵינָן עֲשׂוּיִין לִישִׁיבָה אֶלָּא כְּדֵי שֶׁיְּהַלְּכוּ הַמַּיִם תַּחְתֵּיהֶן:","הַכַּלְכָּלָה וְהַסַּל שֶׁמִּלְּאָן תֶּבֶן אוֹ מוֹכִין אַף עַל פִּי שֶׁהִתְקִינָן לִישִׁיבָה אֵינָן מְקַבְּלִין טֻמְאַת מִדְרָס שֶׁאֵינָן רְאוּיִין לִישִׁיבָה. וְאִם סֵרְגָן בְּגֶמִי אוֹ בִּמְשִׁיחָה עַל פִּיהֶן מִתְטַמְּאִין בְּמִדְרָס:","קוֹרַת בֵּית הַבַּד שֶׁעָשָׂה רֹאשָׁהּ הָאֶחָד כִּסֵּא אֵינוֹ מִתְטַמֵּא בְּמִדְרָס מִפְּנֵי שֶׁאוֹמְרִין לוֹ עֲמֹד וְנַעֲשֶׂה מְלַאכְתֵּנוּ. אֲבָל אִם קָבַע אֶת הַכִּסֵּא בְּקוֹרַת בֵּית הַבַּד הַכִּסֵּא מִתְטַמֵּא בְּמִדְרָס וְאִם דָּרַס הַזָּב עַל הַקּוֹרָה לֹא נִטְמָא הַכִּסֵּא. וְכֵן אִם קָבַע הַכִּסֵּא בְּקוֹרָה גְּדוֹלָה אוֹ עָשָׂה רֹאשׁ הַקּוֹרָה הַגְּדוֹלָה כִּסֵּא אֵין טָמֵא אֶלָּא מְקוֹם הַכִּסֵּא בִּלְבַד וּשְׁאָר הַקּוֹרָה טָהוֹר. וְכֵן הַדִּין בְּכִסֵּא שֶׁקְּבָעוֹ בַּעֲרֵבָה שֶׁהוּא טָהוֹר:","קְצָת הַקּוֹרָה שֶׁמְּתַקֵּן הַמְסַתֵּת אֶת הָאֶבֶן לֵישֵׁב עָלָיו הֲרֵי מְקוֹם יְשִׁיבָתוֹ מִתְטַמֵּא בְּמִדְרָס. וּמְקוֹם יְשִׁיבָה שֶׁאֲחוֹרֵי הַקָּרוֹן טָהוֹר שֶׁאֵינָהּ אֶלָּא יְשִׁיבַת צַעַר:","רָאשֵׁי כְּלוּנְסוֹת שֶׁיּוֹשְׁבִין עֲלֵיהֶן הָאֻמָּנִין וְשָׁפִין אֶת הָאֲבָנִים וְכַיּוֹצֵא בָּהֶן טְהוֹרִין. וְכֵן כֹּפֶת שֶׁל תְּמָרָה שֶׁהוּא יוֹשֵׁב עָלָיו אֲפִלּוּ גָּבוֹהַּ טֶפַח טָהוֹר שֶׁאֵין זֶה כְּלִי. וְכֵן בּוּל שֶׁל עֵץ אַף עַל פִּי שֶׁסֵּרְקוֹ וְכִרְכְּמוֹ וַעֲשָׂאָהוּ פָּנִים לְשָׁעַר וְכַיּוֹצֵא בּוֹ אֵינוֹ כְּלִי וְלֹא מְקַבֵּל טֻמְאָה עַד שֶׁיָּחֹק בּוֹ:","רָאשֵׁי כְּלוּנְסוֹת הַחֲקוּקִין אִם חֲקָקָן לְדַעַת מְקַבְּלִין טֻמְאָה. מְצָאָן חֲקוּקִין אִם חִשֵּׁב עֲלֵיהֶן מְקַבְּלִין טֻמְאָה מִכָּאן וּלְהַבָּא וְאִם חִשֵּׁב עֲלֵיהֶן חֵרֵשׁ שׁוֹטֶה וְקָטָן אוֹ אָדָם שֶׁאֵינָן שֶׁלּוֹ טְהוֹרִין. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁאֵינָן מְקַבְּלִין טֻמְאָה אֶלָּא בְּמַחְשָׁבָה שֶׁאֵין לְךָ מַחֲשָׁבָה מוֹעֶלֶת אֶלָּא מַחֲשֶׁבֶת בְּעָלִים שֶׁהֵן בְּנֵי דֵּעָה:","הָעוֹשֶׂה כִּפָּה מִן הַשְּׂאוֹר וְיִבְּשָׁהּ וְיִחֲדָהּ לִישִׁיבָה הֲרֵי בְּטֵלָה מִתּוֹרַת אֹכֶל וּמִתְטַמְּאָה בְּמִדְרָס שֶׁהֲרֵי מְשַׁמֶּשֶׁת תַּשְׁמִישֵׁי הָעֵץ:","מַחְצֶלֶת הַקַּשׁ מִתְטַמְּאָה בְּמִדְרָס וְשֶׁל קָנִים וְשֶׁל חֵלֶף טְהוֹרָה מִפְּנֵי שֶׁאֵינָהּ רְאוּיָה לְמִדְרָס. וּשְׁאָר הַמַּחְצְלָאוֹת אִם עֲשָׁאָהּ לִשְׁכִיבָה מְקַבֶּלֶת טֻמְאָה עֲשָׂאָהּ לְסִכּוּךְ טְהוֹרָה. עֲשָׂאָהּ סְתָם גְּדוֹלָה סְתָמָהּ לְסִכּוּךְ קְטַנָּה סְתָמָהּ לִשְׁכִיבָה:","מַחְצֶלֶת שֶׁעָשָׂה לָהּ קָנִים לְאָרְכָּהּ טְמֵאָה מִדְרָס שֶׁעֲדַיִן רְאוּיָה לִשְׁכִיבָה. עֲשָׂאָהּ כְּמִין כִּי טְהוֹרָה. עָשָׂה לָהּ קָנִים לְרָחְבָּהּ אִם אֵין בֵּין קָנֶה לַחֲבֵרוֹ אַרְבָּעָה טְפָחִים טְהוֹרָה. נֶחְלְקָה לְרָחְבָּהּ עֲדַיִן מְקַבֶּלֶת טֻמְאָה. לְאָרְכָּהּ נִשְׁתַּיְּרוּ בָּהּ שְׁלֹשָׁה מַעֲדַנִּים שֶׁל שִׁשָּׁה טְפָחִים עֲדַיִן הִיא רְאוּיָה לְמִדְרָס וּמִתְטַמְּאָה. פָּחוֹת מִכָּאן טְהוֹרָה. וְכֵן אִם הִתִּיר רָאשֵׁי מַעֲדַנִּים טְהוֹרָה. וְאַף טֻמְאַת מִדְרָס לֹא תְּקַבֵּל הַמַּחְצֶלֶת עַד שֶׁתִּגָּמֵר מְלַאכְתָּהּ וְתִתְנַקֵּב כְּמוֹ שֶׁבֵּאַרְנוּ:","תֵּבָה שֶׁפִּתְחָהּ מִלְּמַעְלָה טְהוֹרָה מִן הַמִּדְרָס שֶׁאֵינָהּ רְאוּיָה לֵישֵׁב עָלֶיהָ. וּמְקַבֶּלֶת שְׁאָר טֻמְאוֹת. פִּתְחָהּ מִצִּדָּהּ טְמֵאָה בְּמִדְרָס וּבִשְׁאָר טֻמְאוֹת:","עֲגָלָה שֶׁל קָטָן מִתְטַמְּאָה בְּמִדְרָס שֶׁהֲרֵי נִשְׁעָן עָלֶיהָ:","מַקֵּל שֶׁל זְקֵנִים טָהוֹר מִכְּלוּם שֶׁאֵינוֹ אֶלָּא לְסַיֵּעַ:","סַנְדָּל שֶׁל סַיָּדִין וְהוּא סַנְדָּל שֶׁל עֵץ מִתְטַמֵּא בְּמִדְרָס מִפְּנֵי שֶׁהַסַּיָּד פְּעָמִים מְטַיֵּל בּוֹ עַד שֶׁמַּגִּיעַ לְבֵיתוֹ:","קַב שֶׁל קִטֵּעַ שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל כְּתִיתִין מִתְטַמֵּא בִּשְׁאָר טֻמְאוֹת מִפְּנֵי בֵּית קִבּוּלוֹ. וּמִתְטַמֵּא בְּמִדְרָס שֶׁהֲרֵי נִשְׁעָן עָלָיו:","וְאֵלּוּ טְמֵאִין מִשּׁוּם מֶרְכָּב. מִרְדַּעַת שֶׁל חֲמוֹר. וְטַפִּיטָן שֶׁל סוּס. וְכַר הַגָּמָל. וְאֻכָּף שֶׁל נָאקָה וְכָל כַּיּוֹצֵא בָּהֶן. הַלּוּחוֹת שֶׁמַּנִּיחִין עַל גַּבֵּי הַחֲמוֹר וְאַחַר כָּךְ נוֹתְנִין עָלָיו הַמַּשּׂאוֹי טְהוֹרוֹת וְאִם הָיְתָה רְאוּיָה לְמֶרְכָּב טְמֵאָה:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 10":["כֵּיצַד סֵדֶר לְבִישַׁת הַבְּגָדִים. לוֹבֵשׁ הַמִּכְנָסַיִם תְּחִלָּה וְחוֹגֵר אֶת הַמִּכְנָסַיִם לְמַעְלָה מִטִּבּוּרוֹ מֵעַל מָתְנָיו. וְאַחַר כָּךְ לוֹבֵשׁ הַכֻּתֹּנֶת. וְאַחַר כָּךְ חוֹגֵר אֶת הָאַבְנֵט כְּנֶגֶד אַצִּילֵי יָדָיו וּמַקִּיפוֹ כֶּרֶךְ עַל כֶּרֶךְ עַד שֶׁגּוֹמֵר וְקוֹשֵׁר:","וְעַל הָאַבְנֵט מְפֹרָשׁ בַּקַּבָּלָה (יחזקאל מד יח) \"וְלֹא יַחְגְּרוּ בַּיָּזַע\" בְּמָקוֹם שֶׁמְּזִיעִין. וְכָךְ קִבֵּל יוֹנָתָן בֶּן עוּזִיאֵל מִפִּי הַנְּבִיאִים וְתִרְגֵּם עַל לְבָבֵיהוֹן יֵסְרוּן. וְאַחַר כָּךְ צוֹנֵף בַּמִּצְנֶפֶת כְּמִין כּוֹבַע:","כֹּהֵן גָּדוֹל אַחַר שֶׁחוֹגֵר בְּאַבְנֵט לוֹבֵשׁ הַמְּעִיל. וְעַל הַמְּעִיל הָאֵפוֹד וְהַחֹשֶׁן וְחוֹגֵר בְּחֵשֶׁב הָאֵפוֹד עַל הַמְּעִיל מִתַּחַת הַחֹשֶׁן וּלְפִיכָךְ נִקְרָא (שמות כח לא) (שמות כט ה) (שמות לט כב) \"מְעִיל הָאֵפוֹד\" שֶׁחוֹגְרוֹ בָּאֵפוֹד. וְאַחַר כָּךְ צוֹנֵף בַּמִּצְנֶפֶת וְקוֹשֵׁר הַצִּיץ לְמַעְלָה מִן הַמִּצְנֶפֶת וּשְׂעָרוֹ הָיָה נִרְאָה בֵּין צִיץ לַמִּצְנֶפֶת וְשָׁם הָיָה מֵנִיחַ תְּפִלִּין בֵּין צִיץ לַמִּצְנֶפֶת:","מִצְוַת עֲשֵׂה לַעֲשׂוֹת בְּגָדִים אֵלּוּ וְלִהְיוֹת הַכֹּהֵן עוֹבֵד בָּהֶן שֶׁנֶּאֱמַר (שמות כח ב) \"וְעָשִׂיתָ בִגְדֵי קֹדֶשׁ\". (שמות כט ח) \"וְאֶת בָּנָיו תַּקְרִיב וְהִלְבַּשְׁתָּם כֻּתֳּנֹת\". וְכֹהֵן גָּדוֹל שֶׁשִּׁמֵּשׁ בְּפָחוֹת מִשְּׁמוֹנָה בְּגָדִים אֵלּוּ אוֹ כֹּהֵן הֶדְיוֹט שֶׁשִּׁמֵּשׁ בְּפָחוֹת מֵאַרְבָּעָה בְּגָדִים אֵלּוּ הוּא הַנִּקְרָא מְחֻסַּר בְּגָדִים וַעֲבוֹדָתוֹ פְּסוּלָה וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם כְּזָר שֶׁשִּׁמֵּשׁ שֶׁנֶּאֱמַר (שמות כט ט) \"וְחָגַרְתָּ אֹתָם אַבְנֵט\" (שמות כט ט) \"וְהָיְתָה לָהֶם כְּהֻנָּה\". בִּזְמַן שֶׁבִּגְדֵיהֶם עֲלֵיהֶן כְּהֻנָּתָן עֲלֵיהֶן. אֵין בִּגְדֵיהֶן עֲלֵיהֶן אֵין כְּהֻנָּתָם עֲלֵיהֶן אֶלָּא הֲרֵי הֵם כְּזָרִים וְנֶאֱמַר (במדבר א נא) (במדבר ג י) (במדבר ג לח) (במדבר יח ז) \"וְהַזָּר הַקָּרֵב יוּמָת\":","כְּשֵׁם שֶׁהַמְּחֻסַּר בְּגָדִים חַיָּב מִיתָה וּפוֹסֵל הָעֲבוֹדָה. כָּךְ הַיָּתֵר בְּגָדִים כְּגוֹן שֶׁלָּבַשׁ שְׁתֵּי כֻּתֳּנוֹת אוֹ שְׁנֵי אַבְנֵטִים אוֹ כֹּהֵן הֶדְיוֹט שֶׁלָּבַשׁ בִּגְדֵי כֹּהֵן גָּדוֹל וְעָבַד הֲרֵי זֶה מְחַלֵּל הָעֲבוֹדָה וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם:","נֶאֱמַר בְּבִגְדֵי כְּהֻנָּה (ויקרא טז ד) \"עַל בְּשָׂרוֹ\" (ויקרא טז ד) \"וּלְבֵשָׁם\". מְלַמֵּד שֶׁלֹּא יִהְיֶה דָּבָר חוֹצֵץ בֵּין בְּשָׂרוֹ לַבְּגָדִים. אֲפִלּוּ נִימָא אַחַת אוֹ עָפָר אוֹ כִּנָּה מֵתָה אִם הָיְתָה בֵּין בָּשָׂר לַבֶּגֶד הֲרֵי זוֹ חֲצִיצָה וַעֲבוֹדָתוֹ פְּסוּלָה. לְפִיכָךְ אֵין הַכֹּהֵן יָכוֹל לַעֲבֹד בִּתְפִלִּין שֶׁל יָד שֶׁהֲרֵי חוֹצֶצֶת. אֲבָל שֶׁל רֹאשׁ אֵינָהּ חוֹצֶצֶת. וְאִם רָצָה לַהֲנִיחָם בִּשְׁעַת הָעֲבוֹדָה מֵנִיחַ:","וְצָרִיךְ לְהִזָּהֵר בְּשָׁעָה שֶׁלּוֹבֵשׁ שֶׁלֹּא יִהְיֶה אָבָק בֵּין בִּגְדוֹ לִבְשָׂרוֹ וְלֹא כִּנָּה אַף עַל פִּי שֶׁהִיא בַּחַיִּים. וְשֶׁלֹּא תִּכָּנֵס הָרוּחַ בִּשְׁעַת הָעֲבוֹדָה בֵּין בְּשָׂרוֹ לְבִגְדוֹ עַד שֶׁיִּתְרַחֵק הַבֶּגֶד מֵעָלָיו. וְלֹא יַכְנִיס יָדוֹ תַּחַת חֲלוּקוֹ לַחֵיק. וְלֹא יֵצֵא שְׂעָרוֹ מִן הַבֶּגֶד. וְלֹא יִהְיֶה בַּבֶּגֶד נִימָא מְדֻלְדֶּלֶת. וְאִם הָיָה שָׁם אֶחָד מִכָּל אֵלּוּ עֲבוֹדָתוֹ כְּשֵׁרָה:","כָּרַךְ עַל בְּשָׂרוֹ בֶּגֶד שֶׁלֹּא בִּמְקוֹם בְּגָדִים כְּגוֹן שֶׁכְּרָכוֹ עַל אֶצְבָּעוֹ אוֹ עַל עֲקֵבוֹ אִם הָיָה בּוֹ שָׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת הֲרֵי זֶה חוֹצֵץ וּפוֹסֵל. פָּחוֹת מִכָּאן אֵינוֹ חוֹצֵץ. וְאִם הָיָה צִלְצוּל קָטָן הוֹאִיל וְהוּא חָשׁוּב בֶּגֶד בִּפְנֵי עַצְמוֹ הֲרֵי זֶה פּוֹסֵל וְאַף עַל פִּי שֶׁאֵין בּוֹ שָׁלֹשׁ עַל שָׁלֹשׁ:","כֹּהֵן שֶׁלָּקָה בְּאֶצְבָּעוֹ מֻתָּר לִכְרֹךְ עָלֶיהָ גֶּמִי בְּשַׁבָּת אוֹ בֶּגֶד שֶׁאֵין בּוֹ שָׁלֹשׁ עַל שָׁלֹשׁ וְעוֹבֵד. וְאִם נִתְכַּוֵּן לְהוֹצִיא דָּם אָסוּר. וְהוּא שֶׁלֹּא יָחֹץ הַגֶּמִי אוֹ הַבֶּגֶד בֵּין בְּשָׂרוֹ לַכְּלִי בִּשְׁעַת עֲבוֹדָה:","עָשׂוּ בְּבַיִת שֵׁנִי אוּרִים וְתֻמִּים כְּדֵי לְהַשְׁלִים שְׁמוֹנָה בְּגָדִים וְאַף עַל פִּי שֶׁלֹּא הָיוּ נִשְׁאָלִין בָּהֶן. וּמִפְּנֵי מָה לֹא הָיוּ שׁוֹאֲלִין בָּהֶן מִפְּנֵי שֶׁלֹּא הָיְתָה שָׁם רוּחַ הַקֹּדֶשׁ וְכָל כֹּהֵן שֶׁאֵינוֹ מְדַבֵּר בְּרוּחַ הַקֹּדֶשׁ וְאֵין שְׁכִינָה שׁוֹרָה עָלָיו אֵין נִשְׁאָלִין בּוֹ:","וְכֵיצַד שׁוֹאֲלִין. עוֹמֵד הַכֹּהֵן וּפָנָיו לִפְנֵי הָאָרוֹן וְהַשּׁוֹאֵל מֵאַחֲרָיו. פָּנָיו לְאַחֲרֵי הַכֹּהֵן. וְאוֹמֵר הַשּׁוֹאֵל אֶעֱלֶה אוֹ לֹא אֶעֱלֶה. וְאֵינוֹ שׁוֹאֵל בְּקוֹל רָם וְלֹא מְהַרְהֵר בְּלִבּוֹ אֶלָּא בְּקוֹל נָמוּךְ כְּמִי שֶׁמִּתְפַּלֵּל בֵּינוֹ לְבֵין עַצְמוֹ. וּמִיָּד רוּחַ הַקֹּדֶשׁ לוֹבֵשׁ אֶת הַכֹּהֵן וּמַבִּיט בַּחֹשֶׁן וְרוֹאֶה בּוֹ בְּמַרְאֵה הַנְּבוּאָה עֲלֵה אוֹ לֹא תַּעֲלֶה בָּאוֹתִיּוֹת שֶׁבּוֹלְטוֹת מִן הַחֹשֶׁן כְּנֶגֶד פָּנָיו. וְהַכֹּהֵן מְשִׁיבוֹ וְאוֹמֵר לוֹ עֲלֵה אוֹ לֹא תַּעֲלֶה:","וְאֵין שׁוֹאֲלִין עַל שְׁנֵי דְּבָרִים כְּאֶחָד. וְאִם שָׁאַל מְשִׁיבִין עַל הָרִאשׁוֹן בִּלְבַד. וְאֵין נִשְׁאָלִין בָּהֶן לְהֶדְיוֹט אֶלָּא אוֹ לְמֶלֶךְ אוֹ לְבֵית דִּין אוֹ לְמִי שֶׁצֹּרֶךְ הַצִּבּוּר בּוֹ שֶׁנֶּאֱמַר (במדבר כז כא) \"וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן יַעֲמֹד וְגוֹ'. \"הוּא\" זֶה הַמֶּלֶךְ. \"וְכָל בְּנֵי יִשְׂרָאֵל\" זֶה הוּא מְשׁוּחַ מִלְחָמָה אוֹ מִי שֶׁצֹּרֶךְ הַצִּבּוּר בִּשְׁאֵלָתוֹ. \"וְכָל הָעֵדָה\" אֵלּוּ בֵּית דִּין הַגָּדוֹל:","זֶה שֶׁאַתָּה מוֹצֵא בְּדִבְרֵי נְבִיאִים שֶׁהַכֹּהֲנִים הָיוּ חוֹגְרִין אֵפוֹד בַּד לֹא הָיוּ כֹּהֲנִים גְּדוֹלִים. שֶׁאֵין הָאֵפוֹד שֶׁל כֹּהֵן גָּדוֹל אֵפוֹד בַּד. וְאַף הַלְוִיִּם הָיוּ חוֹגְרִין אוֹתוֹ שֶׁהֲרֵי שְׁמוּאֵל הַנָּבִיא לֵוִי הָיָה וְנֶאֱמַר בּוֹ (שמואל א ב יח) \"נַעַר חָגוּר אֵפוֹד בָּד\". אֶלָּא אֵפוֹד זֶה הָיוּ חוֹגְרִים אוֹתוֹ בְּנֵי הַנְּבִיאִים וּמִי שֶׁהוּא רָאוּי שֶׁתִּשְׁרֶה עָלָיו רוּחַ הַקֹּדֶשׁ לְהוֹדִיעַ כִּי הִגִּיעַ זֶה לְמַעֲלַת כֹּהֵן גָּדוֹל שֶׁמְּדַבֵּר עַל פִּי הָאֵפוֹד וְהַחֹשֶׁן בְּרוּחַ הַקֹּדֶשׁ:"],"Mishneh Torah, Vows 1":["הַנֵּדֶר נֶחְלָק לִשְׁתֵּי מַחֲלוֹקוֹת. הַחֵלֶק הָרִאשׁוֹן הוּא שֶׁיֶּאֱסֹר עַל עַצְמוֹ דְּבָרִים הַמֻּתָּרִים לוֹ כְּגוֹן שֶׁיֹּאמַר פֵּרוֹת מְדִינָה פְּלוֹנִית אֲסוּרִין עָלַי כָּל שְׁלֹשִׁים יוֹם אוֹ לְעוֹלָם. אוֹ מִין פְּלוֹנִי מִפֵּרוֹת הָעוֹלָם אוֹ פֵּרוֹת אֵלּוּ אֲסוּרִין עָלַי. בְּכָל לָשׁוֹן שֶׁיֶּאֱסֹר הֲרֵי זֶה נֶאֱסָר בָּהֶן. וְאַף עַל פִּי שֶׁאֵין שָׁם שְׁבוּעָה כְּלָל וְלֹא הַזְכָּרַת שֵׁם וְלֹא כִּנּוּי. וְעַל זֶה נֶאֱמַר בַּתּוֹרָה (במדבר ל ג) \"לֶאְסֹר אִסָּר עַל נַפְשׁוֹ\". שֶׁיֶּאֱסֹר עַל עַצְמוֹ דְּבָרִים הַמֻּתָּרִים. וְכֵן אִם אָמַר הֲרֵי הֵן עָלַי אִסָּר הֲרֵי אֵלּוּ אֲסוּרִין וְחֵלֶק זֶה הוּא שֶׁאֲנִי קוֹרֵא אוֹתוֹ נִדְרֵי אִסָּר:","וְהַחֵלֶק הַשֵּׁנִי הוּא שֶׁיְּחַיֵּב עַצְמוֹ בְּקָרְבָּן שֶׁאֵינוֹ חַיָּב בּוֹ. כְּגוֹן שֶׁיֹּאמַר הֲרֵי עָלַי לְהָבִיא עוֹלָה. אוֹ הֲרֵי עָלַי לְהָבִיא שְׁלָמִים אוֹ מִנְחָה. הֲרֵי בְּהֵמָה זוֹ עוֹלָה אוֹ שְׁלָמִים. וְהָאוֹמֵר [הֲרֵי] עָלַי הוּא הַנִּקְרָא נֵדֶר. וְהָאוֹמֵר הֲרֵי זוֹ הוּא הַנִּקְרָא נְדָבָה. וְהַנְּדָבָה וְהַנֵּדֶר מִמִּין אֶחָד הוּא אֶלָּא שֶׁהַנְּדָרִים חַיָּבִין בְּאַחֲרָיוּתָן וּנְדָבוֹת אֵין חַיָּבִין בְּאַחֲרָיוּתָן. וְעַל זֶה נֶאֱמַר בַּתּוֹרָה (דברים יב יז) \"וּנְדָרֶיךָ אֲשֶׁר תִּדֹּר וְנִדְבֹתֶיךָ\" וְגוֹ'. וְחֵלֶק זֶה הוּא שֶׁאֲנִי קוֹרֵא אוֹתוֹ נִדְרֵי הֶקְדֵּשׁ:","וְדִינֵי הַחֵלֶק הָרִאשׁוֹן וְעִנְיָנוֹ הֵם שֶׁאָנוּ מְבָאֲרִים בַּהֲלָכוֹת אֵלּוּ. אֲבָל דִּינֵי נִדְרֵי הֶקְדֵּשׁ וּמִשְׁפְּטֵיהֶם כֻּלָּם יִתְבָּאֲרוּ בִּמְקוֹמָם בְּהִלְכוֹת מַעֲשֵׂה הַקָּרְבָּנוֹת:","מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה שֶׁיְּקַיֵּם אָדָם שְׁבוּעָתוֹ אוֹ נִדְרוֹ בֵּין שֶׁהָיָה מִנִּדְרֵי אִסָּר בֵּין שֶׁהָיָה מִנִּדְרֵי הֶקְדֵּשׁ. שֶׁנֶּאֱמַר (דברים כג כד) \"מוֹצָא שְׂפָתֶיךָ תִּשְׁמֹר וְעָשִׂיתָ כַּאֲשֶׁר נָדַרְתָּ\" וְנֶאֱמַר (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\":","הָאוֹסֵר עַל עַצְמוֹ מִין מִמִּינֵי מַאֲכָל כְּגוֹן שֶׁאָמַר תְּאֵנִים אֲסוּרִין עָלַי אוֹ תְּאֵנִים שֶׁל מְדִינָה פְּלוֹנִית אֲסוּרִים עָלַי אוֹ תְּאֵנִים אֵלּוּ אֲסוּרִין עָלַי וְכַיּוֹצֵא בְּאֵלּוּ וְאָכַל מֵהֶן כָּל שֶׁהוּא לוֹקֶה מִן הַתּוֹרָה שֶׁנֶּאֱמַר (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\". שֶׁאֵין לִנְדָרִים שִׁעוּר. שֶׁכָּל הַנּוֹדֵר מִדָּבָר הֲרֵי זֶה כִּמְפָרֵשׁ כָּל שֶׁהוּא. אָמַר אֲכִילָה מִפֵּרוֹת מְדִינָה פְּלוֹנִית אֲסוּרִין עָלַי אוֹ אֲכִילָה מִפֵּרוֹת אֵלּוּ אֵינוֹ לוֹקֶה עַד שֶׁיֹּאכַל כְּזַיִת:","אָסַר עַל עַצְמוֹ אֲכִילָה מִן הַתְּאֵנִים וַאֲכִילָה מִן הָעֲנָבִים בֵּין בְּנֵדֶר אֶחָד בֵּין בִּשְׁנֵי נְדָרִים הֲרֵי אֵלּוּ מִצְטָרְפִין לִכְזַיִת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר פֵּרוֹת אֵלּוּ עָלַי קָרְבָּן אוֹ שֶׁאָמַר הֲרֵי הֵם כְּקָרְבָּן אוֹ שֶׁאָמַר לַחֲבֵרוֹ כָּל מַה שֶּׁאֹכַל עִמְּךָ עָלַי קָרְבָּן אוֹ כְּקָרְבָּן אוֹ הֲרֵי הֵן עָלַי קָרְבָּן. הֲרֵי אֵלּוּ אֲסוּרִין עָלָיו מִפְּנֵי שֶׁאֶפְשָׁר שֶׁיִּדֹּר אָדָם קָרְבָּן וְיַעֲשֶׂה בְּהֵמָה שֶׁהָיְתָה חֹל קָרְבָּן וְתֵאָסֵר:","אֲבָל הָאוֹמֵר פֵּרוֹת אֵלּוּ עָלַי אוֹ מִין פְּלוֹנִי עָלַי אוֹ מַה שֶּׁאֹכַל עִם פְּלוֹנִי עָלַי כִּבְשַׂר חֲזִיר אוֹ כְּעַכּוּ\"ם אוֹ כִּנְבֵלוֹת וּטְרֵפוֹת וְכַיּוֹצֵא בְּאֵלּוּ הֲרֵי אֵלּוּ מֻתָּרִין וְאֵין כָּאן נֵדֶר. שֶׁאִי אֶפְשָׁר שֶׁיַּעֲשֶׂה דָּבָר שֶׁאֵינוֹ בְּשַׂר חֲזִיר כִּבְשַׂר חֲזִיר:","זֶה הַכְּלָל כָּל הַמֵּשִׂים דְּבָרִים הַמֻּתָּרִים כַּדְּבָרִים הָאֲסוּרִים אִם אוֹתוֹ דָּבָר הָאָסוּר יָכוֹל לַעֲשׂוֹתוֹ בְּנֵדֶר הֲרֵי אֵלּוּ אֲסוּרִים. וְאִם אֵינוֹ יָכוֹל לַעֲשׂוֹתוֹ בְּנֵדֶר הֲרֵי אֵלּוּ מֻתָּרִין:","הַחַטָּאת וְהָאָשָׁם אַף עַל פִּי שֶׁאֵינָן בָּאִין בְּנֵדֶר וּנְדָבָה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ אֶפְשָׁר לַנּוֹדֵר לְהָבִיא אוֹתָם מֵחֲמַת נִדְרוֹ. שֶׁהַנּוֹדֵר בְּנָזִיר מֵבִיא חַטָּאת וְאִם נִטְמָא מֵבִיא אָשָׁם כְּמוֹ שֶׁיִּתְבָּאֵר. לְפִיכָךְ הָאוֹמֵר פֵּרוֹת אֵלּוּ עָלַי כְּחַטָּאת אוֹ כְּאָשָׁם אוֹ שֶׁאָמַר הֲרֵי הֵן חַטָּאת אוֹ הֲרֵי הֵן אָשָׁם הֲרֵי אֵלּוּ אֲסוּרִין. וְאֵין צָרִיךְ לוֹמַר בְּאוֹמֵר הֲרֵי הֵן עוֹלָה אוֹ שְׁלָמִים אוֹ מִנְחָה אוֹ תּוֹדָה שֶׁהֵן אֲסוּרִין שֶׁכָּל אֵלּוּ בָּאִין בְּנֵדֶר וּנְדָבָה:","אֲבָל הָאוֹמֵר פֵּרוֹת אֵלּוּ עָלַי כְּחַלַּת אַהֲרֹן אוֹ כִּתְרוּמָתוֹ הֲרֵי אֵלּוּ מֻתָּרִין שֶׁאֵין שָׁם דֶּרֶךְ לְהָבִיא אֵלּוּ בְּנֵדֶר וּנְדָבָה:","הָאוֹמֵר הֲרֵי הַפֵּרוֹת הָאֵלּוּ עָלַי כְּנוֹתָר כְּפִגּוּל כְּבָשָׂר טָמֵא שֶׁל קָדָשִׁים הֲרֵי אֵלּוּ אֲסוּרִין שֶׁהֲרֵי עֲשָׂאָן כִּבְשַׂר קָרְבָּן מִכָּל מָקוֹם:","הָאוֹמֵר הֲרֵי הֵן עָלַי כְּמַעֲשַׂר בְּהֵמָה הֲרֵי אֵלּוּ אֲסוּרִין הוֹאִיל וּקְדֻשָּׁתוֹ בִּידֵי אָדָם. הֲרֵי הֵן עָלַי כִּבְכוֹר הֲרֵי אֵלּוּ מֻתָּרִין שֶׁאֵין קְדֻשָּׁתוֹ בִּידֵי אָדָם וְאֵינוֹ יָכוֹל לְהַתְפִּיסוֹ בְּנֵדֶר שֶׁנֶּאֱמַר (ויקרא כז כו) \"לֹא יַקְדִּישׁ אִישׁ אֹתוֹ\":","אָמַר הֲרֵי הֵן עָלַי כְּחֶרְמֵי שָׁמַיִם הֲרֵי אֵלּוּ אֲסוּרִין. שֶׁחֶרְמֵי שָׁמַיִם לְבֶדֶק הַבַּיִת. הֲרֵי הֵן עָלַי כִּתְרוּמַת הַלִּשְׁכָּה כִּתְמִידִים כְּדִירִים כְּעֵצִים כְּאִשִּׁים כְּמִזְבֵּחַ אוֹ כְּאַחַד מִמְּשַׁמְּשֵׁי הַמִּזְבֵּחַ. כְּגוֹן שֶׁאָמַר הֲרֵי הֵן עָלַי כְּיָעִים כְּמִזְרָקוֹת כְּמִזְלָגוֹת וְכַיּוֹצֵא בָּהֶן. וְכֵן הָאוֹמֵר הֲרֵי הֵן עָלַי כְּהֵיכָל כִּירוּשָׁלַיִם הֲרֵי אֵלּוּ אֲסוּרִין. וְאַף עַל פִּי שֶׁלֹּא הַזְכִּיר שֵׁם קָרְבָּן. שֶׁכָּל דְּבָרִים אֵלּוּ עִנְיָנָם כְּאוֹמֵר הֲרֵי הֵן עָלַי קָרְבָּן:","הָיָה לְפָנָיו בְּשַׂר קֹדֶשׁ אֲפִלּוּ הָיָה בְּשַׂר שְׁלָמִים אַחַר זְרִיקַת דָּמִים שֶׁהוּא מֻתָּר לַזָּרִים וְאָמַר הֲרֵי הֵן עָלַי כְּבָשָׂר זֶה הֲרֵי אֵלּוּ אֲסוּרִין. שֶׁלֹּא הִתְפִּיס אֶלָּא בְּעִקָּרוֹ שֶׁהָיָה אָסוּר. אֲבָל אִם הָיָה בְּשַׂר בְּכוֹר אִם לִפְנֵי זְרִיקַת דָּמִים הֲרֵי זֶה אָסוּר וְאִם לְאַחר זְרִיקַת דָּמִים הֲרֵי זֶה מֻתָּר:","יֵשׁ מְקוֹמוֹת שֶׁאַנְשֵׁיהֶם עִלְּגִים וּמַפְסִידִין אֶת הַלָּשׁוֹן וּמְכַנִּין עַל דָּבָר בְּדָבָר אַחֵר הוֹלְכִין שָׁם אַחַר הַכִּנּוּי. כֵּיצַד כָּל כִּנּוּיֵי קָרְבָּן כְּקָרְבָּן. הָאוֹמֵר הֲרֵי הֵן עָלַי קוֹנַם קוֹנָח קוֹנָז הֲרֵי אֵלּוּ כִּנּוּיִין לְקָרְבָּן. חֵרֶק חֵרֶף חֵרֶךְ הֲרֵי אֵלּוּ כִּנּוּיִין לְחֵרֶם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה הוֹלְכִין אַחַר לְשׁוֹן כְּלַל הָעָם בְּאוֹתוֹ מָקוֹם וּבְאוֹתוֹ זְמַן:","וּכְשֵׁם שֶׁאוֹסֵר עַצְמוֹ בְּכִנּוּיִין כָּךְ אִם הִקְדִּישׁ בְּכִנּוּיִין הֲרֵי זֶה הֶקְדֵּשׁ. וְכִנּוּיֵי הַכִּנּוּיִין מֻתָּרִין בֵּין בְּנִדְרֵי אִסָּר בֵּין בְּנִדְרֵי הֶקְדֵּשׁ:","הָאוֹמֵר לַחֲבֵרוֹ מַה שֶּׁאֹכַל עִמְּךָ לֹא יְהֵא חֻלִּין אוֹ לֹא יְהֵא כָּשֵׁר אוֹ לֹא יְהֵא דְּכִי אוֹ לֹא יְהֵא טָהוֹר הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ כָּל מַה שֶּׁאֹכַל עִמְּךָ יְהֵא קָרְבָּן שֶׁהוּא אָסוּר. וְכֵן אִם אָמַר לוֹ כָּל מַה שֶּׁאֹכַל עִמְּךָ טָמֵא אוֹ נוֹתָר אוֹ פִּגּוּל הֲרֵי זֶה אָסוּר:","הָאוֹמֵר לַחֲבֵרוֹ לֹא חֻלִּין לֹא אֹכַל לְךָ הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ מַה שֶּׁאֹכַל לְךָ לֹא יְהֵא חֻלִּין אֶלָּא קָרְבָּן. וְכֵן אִם אָמַר הַקָרְבָּן שֶׁאֹכַל לְךָ קָרְבָּן שֶׁאֹכַל לְךָ כְּקָרְבָּן שֶׁאֹכַל לְךָ הֲרֵי זֶה אָסוּר. אֲבָל הָאוֹמֵר הַקָּרְבָּן לֹא אֹכַל לְךָ אוֹ כְּקָרְבָּן לֹא אֹכַל לְךָ אוֹ לְקָרְבָּן לֹא אֹכַל לְךָ אוֹ קָרְבָּן לֹא אֹכַל לְךָ אוֹ לֹא קָרְבָּן לֹא אֹכַל לְךָ כָּל אֵלּוּ מֻתָּרִים. שֶׁאֵין מַשְׁמַע דְּבָרִים אֵלּוּ אֶלָּא שֶׁנִּשְׁבַּע בְּקָרְבָּן שֶׁלֹּא יֹאכַל לָזֶה וְהַנִּשְׁבָּע בְּקָרְבָּן אֵינוֹ כְּלוּם אוֹ שֶׁנָּדַר שֶׁלֹּא יֹאכַל לוֹ קָרְבָּן:","חֻלִּין שֶׁאֹכַל לְךָ הַחֻלִּין שֶׁאֹכַל לְךָ כְּחֻלִּין שֶׁאֹכַל לְךָ חֻלִּין שֶׁלֹּא אֹכַל לְךָ הַחֻלִּין שֶׁלֹּא אֹכַל לְךָ כְּחֻלִּין שֶׁלֹּא אֹכַל לְךָ הֲרֵי זֶה מֻתָּר:","אֲבָל הָאוֹמֵר לֹא טָמֵא שֶׁאֹכַל לְךָ לֹא נוֹתָר שֶׁאֹכַל לְךָ לֹא פִּגּוּל שֶׁאֹכַל לְךָ אָסוּר. שֶׁמַּשְׁמָעוֹ שֶׁל דָּבָר דָּבָר שֶׁאֹכַל הוּא שֶׁיִּהְיֶה פִּגּוּל אוֹ טָמֵא לְפִיכָךְ לֹא אֹכַל לְךָ:","בַּהֵיכָל שֶׁאֹכַל לְךָ הֵיכָל שֶׁאֹכַל לְךָ לֹא הֵיכָל שֶׁאֹכַל לְךָ אָסוּר. הֵיכָל שֶׁלֹּא אֹכַל לְךָ כְּהֵיכָל שֶׁלֹּא אֹכַל לְךָ לֹא הֵיכָל שֶׁלֹּא אֹכַל לְךָ מֻתָּר. שֶׁזֶּה כְּמִי שֶׁנִּשְׁבַּע בַּהֵיכָל שֶׁלֹּא יֹאכַל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ מֻדָּר אֲנִי מִמְּךָ מַשְׁמַע דָּבָר זֶה שֶׁלֹּא יְדַבֵּר עִמּוֹ. מֻפְרָשׁ אֲנִי מִמְּךָ מַשְׁמָעוֹ שֶׁלֹּא יִשָּׂא וְיִתֵּן עִמּוֹ. מְרֻחָק אֲנִי מִמְּךָ מַשְׁמָעוֹ שֶׁלֹּא יֵשֵׁב בְּאַרְבַּע אַמּוֹתָיו. וְכֵן אִם אָמַר לוֹ מְנֻדֶּה אֲנִי לְךָ אוֹ מְשַׁמַּתְנָא מִמְּךָ. אֲבָל אִם אָמַר לוֹ מֻדָּר אֲנִי מִמְּךָ שֶׁלֹּא אֹכַל לְךָ. אוֹ מֻפְרָשׁ אֲנִי מִמְּךָ שֶׁלֹּא אֹכַל לְךָ אוֹ מְרֻחָק אֲנִי מִמְּךָ שֶׁלֹּא אֹכַל לְךָ הֲרֵי זֶה אָסוּר לֶאֱכל. וְאִם אָכַל כְּזַיִת מִכָּל נְכָסָיו לוֹקֶה מִשּׁוּם (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\":","אָמַר לוֹ מְנֻדֶּה אֲנִי לְךָ שֶׁלֹּא אֹכַל לְךָ אֵינוֹ אוֹכֵל לוֹ וְאִם אָכַל אֵינוֹ לוֹקֶה. אָמַר לוֹ נָדִינָא מִמְּךָ הֲרֵי זֶה אָסוּר לֵהָנוֹת:","הָאוֹמֵר לַחֲבֵרוֹ הֲרֵי עָלַי כְּנִדְרֵי רְשָׁעִים אִם אֹכַל לְךָ שֶׁמִּנִּדְרֵיהֶם נָזִיר וְקָרְבָּן וּשְׁבוּעָה וְאָכַל חַיָּב בְּכֻלָּן. וְכֵן הָאוֹמֵר הֲרֵי עָלַי כִּנְדָבוֹת כְּשֵׁרִים שֶׁמִּנִּדְבוֹתָם נָזִיר וְקָרְבָּן הֲרֵי זֶה חַיָּב:","אָמַר הֲרֵי עָלַי כְּנִדְרֵי רְשָׁעִים אוֹ כִּנְדָבוֹת כְּשֵׁרִים שֶׁאֹכַל לְךָ אוֹ אִם אֹכַל לְךָ הֲרֵי זֶה אָסוּר אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ. אָמַר כְּנִדְרֵי כְּשֵׁרִים לֹא נִתְחַיֵּב בִּכְלוּם שֶׁאֵין הַכְּשֵׁרִים נוֹדְרִים בְּדֶרֶךְ אִסּוּר וָכַעַס. אָמַר כְּנִדְרֵי רְשָׁעִים הֲרֵינִי וְהָיָה נָזִיר עוֹבֵר לְפָנָיו חַיָּב בִּנְזִירוּת. כְּנִדְרֵי רְשָׁעִים עָלַי חַיָּב קָרְבָּן. כְּנִדְרֵי רְשָׁעִים שֶׁלֹּא אֹכַל מִמֶּנּוּ חַיָּב בִּשְׁבוּעָה:","הַנּוֹדֵר בַּתּוֹרָה כְּגוֹן שֶׁאָמַר פֵּרוֹת אֵלּוּ עָלַי כָּזוֹ לֹא אָמַר כְּלוּם וְאֵינוֹ צָרִיךְ שְׁאֵלָה לְחָכָם. אֶלָּא אִם כֵּן הָיָה עַם הָאָרֶץ. כְּדֵי שֶׁלֹּא יִנְהֲגוּ קַלּוּת רֹאשׁ בִּנְדָרִים:","נָדַר בְּמַה שֶּׁכָּתוּב בָּהּ הֲרֵי זֶה אָסוּר שֶׁהֲרֵי כָּתוּב בָּהּ אִסָּר וְנֶדֶר. נְטָלָהּ בְּיָדוֹ וְנָדַר בָּהּ הֲרֵי זֶה כְּמִי שֶׁנָּדַר בְּמַה שֶּׁכָּתוּב בָּהּ:","הָאוֹמֵר לַחֲבֵרוֹ נַשְׁכִּים וְנִשְׁנֶה פֶּרֶק. עָלָיו לְהַשְׁכִּים וְלִקְרוֹת שֶׁזֶּה כְּמוֹ נֵדֶר הוּא וְאַף עַל פִּי שֶׁלֹּא הוֹצִיאוֹ בִּלְשׁוֹן נֵדֶר:","הָאוֹמֵר לְאִשְׁתּוֹ הֲרֵי אַתְּ עָלַי כְּאִמִּי אוֹ כַּאֲחוֹתִי אוֹ כְּעָרְלָה אוֹ כְּכִלְאֵי הַכֶּרֶם הֲרֵי זֶה כְּאוֹמֵר עַל הַפֵּרוֹת הֲרֵי אֵלּוּ כִּבְשַׂר חֲזִיר. כְּשֵׁם שֶׁהוּא מֻתָּר לְאָכְלָן כְּמוֹ שֶׁבֵּאַרְנוּ כָּךְ מֻתָּר בְּאִשְׁתּוֹ. אֲבָל אִם אָמַר לָהּ הֲרֵינִי מֻדָּר מִמֵךְ הֲנָיָה אוֹ הֲנָאַת תַּשְׁמִישֵׁךְ אֲסוּרָה עָלַי הֲרֵי זוֹ אֲסוּרָה עָלָיו כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Vows 9":["בִּנְּדָרִים הַלֵּךְ אַחַר לְשׁוֹן בְּנֵי אָדָם בְּאוֹתוֹ מָקוֹם וּבְאוֹתוֹ לָשׁוֹן וּבְאוֹתוֹ זְמַן שֶׁנָּדַר אוֹ נִשְׁבַּע בּוֹ. כֵּיצַד. נָדַר אוֹ נִשְׁבַּע מִן הַמְבֻשָּׁל. אִם דֶּרֶךְ אוֹתוֹ מָקוֹם בְּאוֹתוֹ לָשׁוֹן בְּאוֹתוֹ זְמַן שֶׁקּוֹרְאִין מְבֻשָּׁל אֲפִלּוּ לְצָלִי וּלְשָׁלוּק הֲרֵי זֶה אָסוּר בַּכּל. וְאִם אֵין דַּרְכָּם לִקְרוֹת מְבֻשָּׁל אֶלָּא לְבָשָׂר שֶׁנִּתְבַּשֵּׁל בְּמַיִם וּבְתַבְלִין הֲרֵי זֶה מֻתָּר בְּצָלִי וּבְשָׁלוּק. וְכֵן הַמְעֻשָּׁן וְהַמְבֻשָּׁל בְּחַמֵּי טְבֶרְיָא וְכַיּוֹצֵא בָּהֶן הוֹלְכִין בּוֹ אַחַר הַלָּשׁוֹן שֶׁל בְּנֵי הָעִיר:","נָדַר אוֹ נִשְׁבַּע מִן הַמָּלִיחַ. אִם דַּרְכָּם לִקְרוֹת מָלִיחַ לְכָל הַמְּלוּחִין הֲרֵי זֶה אָסוּר בְּכָל הַמְּלוּחִין. וְאִם אֵין דַּרְכָּם לִקְרוֹת מָלִיחַ אֶלָּא לְדָג מָלִיחַ בִּלְבַד אֵינוֹ אָסוּר אֶלָּא בְּדָג מָלִיחַ:","נָדַר אוֹ נִשְׁבַּע מִן הַכָּבוּשׁ אִם דַּרְכָּם לִקְרוֹת כָּבוּשׁ לְכָל הַכְּבוּשִׁים הֲרֵי זֶה אָסוּר בַּכּל. וְאִם אֵין דַּרְכָּם לִקְרוֹת כָּבוּשׁ אֶלָּא לְיָרָק כָּבוּשׁ בִּלְבַד אֵינוֹ אָסוּר אֶלָּא בְּכָבוּשׁ שֶׁל יָרָק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיוּ מִקְצָת בְּנֵי הַמָּקוֹם קוֹרִין לוֹ כָּךְ וּמִקְצָתָם אֵין קוֹרִין אֵין הוֹלְכִין אַחַר הָרֹב אֶלָּא הֲרֵי זֶה סְפֵק נְדָרִים וְכָל סְפֵק נְדָרִים לְהַחְמִיר וְאִם עָבַר אֵינוֹ לוֹקֶה:","כֵּיצַד. נָדַר מִן הַשֶּׁמֶן בְּמָקוֹם שֶׁמִּסְתַּפְּקִין בְּשֶׁמֶן זַיִת וּבְשֶׁמֶן שֻׁמְשְׁמִין וְרֹב אַנְשֵׁי הַמָּקוֹם אֵין קוֹרִין שֶׁמֶן סְתָם אֶלָּא לְשֶׁמֶן זַיִת וְקוֹרִין לְשֶׁמֶן שֻׁמְשְׁמִין שֶׁמֶן שֻׁמְשְׁמִין וּמִעוּטָם קוֹרִין אַף לְשֶׁמֶן שֻׁמְשְׁמִין שֶׁמֶן סְתָם. הֲרֵי זֶה אָסוּר בִּשְׁנֵיהֶם וְאֵינוֹ לוֹקֶה עַל שֶׁמֶן שֻׁמְשְׁמִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל דָּבָר שֶׁדֶּרֶךְ שָׁלִיחַ בְּאוֹתוֹ מָקוֹם לְהִמָּלֵךְ עָלָיו הֲרֵי הוּא בִּכְלַל הַמִּין שֶׁנֶּאֱמַר לְשָׁלִיחַ סְתָם. כֵּיצַד. מָקוֹם שֶׁדַּרְכָּן אִם יִשְׁלַח אָדָם שָׁלִיחַ לִקְנוֹת לוֹ בָּשָׂר סְתָם אָמַר לוֹ לֹא מָצָאתִי אֶלָּא דָּגִים אִם נִשְׁבַּע אוֹ נָדַר בְּמָקוֹם זֶה מִן הַבָּשָׂר נֶאֱסָר אַף בִּבְשַׂר דָּגִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וּבְכָל מָקוֹם הַנּוֹדֵר מִן הַבָּשָׂר אָסוּר בִּבְשַׂר עוֹפוֹת וּבִקְרָבַיִם וּמֻתָּר בַּחֲגָבִים. וְאִם מַרְאִין הַדְּבָרִים בְּעֵת שֶׁנָּדַר שֶׁלֹּא נִתְכַּוֵּן אֶלָּא בִּבְשַׂר בְּהֵמָה בִּלְבַד [אוֹ לִבְשַׂר עוֹף וּבְהֵמָה בִּלְבַד] הֲרֵי זֶה מֻתָּר בִּבְשַׂר דָּגִים וַאֲפִלּוּ בְּמָקוֹם שֶׁהַשָּׁלִיחַ נִמְלַךְ עֲלֵיהֶן:","הַנּוֹדֵר מִן הַמְבֻשָּׁל מֻתָּר בְּבֵיצָה שֶׁלֹּא נִתְבַּשְּׁלָה עַד שֶׁקָּפְתָּה אֶלָּא נִתְגַּלְגְּלָה בִּלְבַד. הַנּוֹדֵר מִמַּעֲשֵׂה קְדֵרָה אֵינוֹ אָסוּר אֶלָּא מִדְּבָרִים שֶׁמַּרְתִּיחִין אוֹתָן בִּקְדֵרָה. כְּגוֹן רִיפוֹת וּלְבִיבוֹת וְכַיּוֹצֵא בָּהֶן. אָסַר עַצְמוֹ מִכָּל הַיּוֹרֵד לִקְדֵרָה הֲרֵי זֶה אָסוּר בְּכָל הַמִּתְבַּשְּׁלִין בִּקְדֵרָה:","הַנּוֹדֵר מִן הַדָּגִים מֻתָּר בְּצִיר וּבְמֻרְיָס שֶׁל דָּגִים. הַנּוֹדֵר מִן הֶחָלָב מֻתָּר בַּקּוֹם וְהוּא הַמַּיִם הַמֻּבְדָּלִין מִן הֶחָלָב. נָדַר מִן הַקּוֹם מֻתָּר בְּחָלָב. נָדַר מִן הַגְּבִינָה אָסוּר בָּהּ בֵּין מְלוּחָה בֵּין תְּפֵלָה:","הַנּוֹדֵר מִן הַחִטִּים אָסוּר בָּהֶן בֵּין חַיִּין בֵּין מְבֻשָּׁלִין. חִטָּה חִטִּים שֶׁאֲנִי טוֹעֵם אָסוּר בָּהֶן בֵּין קֶמַח בֵּין פַּת. חִטָּה שֶׁאֲנִי טוֹעֵם אָסוּר בְּאָפוּי וּמֻתָּר לָכֹס. חִטִּים שֶׁאֲנִי טוֹעֵם מֻתָּר בְּאָפוּי וְאָסוּר לָכֹס. חִטָּה חִטִּים שֶׁאֲנִי טוֹעֵם אָסוּר בֵּין בְּאָפוּי בֵּין לָכֹס. וְהַנּוֹדֵר מִן הַדָּגָן אוֹ מִן הַתְּבוּאָה אֵינוֹ אָסוּר אֶלָּא בַּחֲמֵשֶׁת הַמִּינִין:","הַנּוֹדֵר מִן הַיָּרָק מֻתָּר בִּדְלוּעִין. הַנּוֹדֵר בִּכְרֵישִׁין מֻתָּר בְּקַפְלוֹטוֹת. הַנּוֹדֵר מִן הַכְּרוּב אָסוּר בְּמַיִם שֶׁנִּתְבַּשֵּׁל בּוֹ הַכְּרוּב שֶׁהֲרֵי מֵי שְׁלָקוֹת כִּשְׁלָקוֹת. נָדַר מִמֵּי הַשְּׁלָקוֹת מֻתָּר בַּשְּׁלָקוֹת עַצְמָן. הַנּוֹדֵר מִן הָרֹטֶב מֻתָּר בַּתַּבְלִין שֶׁבּוֹ. מִן הַתַּבְלִין מֻתָּר בָּרֹטֶב. הַנּוֹדֵר מִן הַגְּרִיסִין אָסוּר בַּמִּקְפָּה שֶׁל גְּרִיסִין:","הַנּוֹדֵר מִן פֵּרוֹת הָאָרֶץ אָסוּר בְּכָל פֵּרוֹת הָאָרֶץ וּמֻתָּר בִּכְמֵהִין וּפִטְרִיּוֹת. וְאִם אָמַר כָּל גִּדּוּלֵי קַרְקַע עָלַי אָסוּר אַף בִּכְמֵהִין וּפִטְרִיּוֹת אַף עַל פִּי שֶׁאֵינָן יוֹנְקִין מִן הַקַּרְקַע גְּדֵלִין הֵן בַּקַּרְקַע:","הַנּוֹדֵר מִפֵּרוֹת הַשָּׁנָה אָסוּר בְּכָל פֵּרוֹת הַשָּׁנָה וּמֻתָּר בִּגְדָיִים וּבִטְלָאִים וּבְחָלָב וּבְבֵיצִים וּבְגוֹזָלוֹת. וְאִם אָמַר כָּל גִּדּוּלֵי שָׁנָה עָלַי אָסוּר בְּכֻלָּם. הַנּוֹדֵר מִפֵּרוֹת הַקַּיִץ אֵין אָסוּר אֶלָּא בִּתְאֵנִים:","וּבְכָל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן הִזָּהֵר בְּעִקַּר הַגָּדוֹל שֶׁהוּא בִּנְדָרִים הַלֵּךְ אַחַר לְשׁוֹן בְּנֵי אָדָם שֶׁבְּאוֹתוֹ מָקוֹם בְּאוֹתוֹ לָשׁוֹן וּבְאוֹתוֹ זְמַן. וְעַל פִּי עִקָּר זֶה תּוֹרֶה וְתֹאמַר זֶה הַנּוֹדֵר אָסוּר בְּדָבָר פְּלוֹנִי וּמֻתָּר בְּדָבָר פְּלוֹנִי:","הַנּוֹדֵר מִן הָעֲנָבִים מֻתָּר בְּיַיִן וַאֲפִלּוּ הֶחָדָשׁ. מִן הַזֵּיתִים מֻתָּר בְּשֶׁמֶן. מִן הַתְּמָרִים מֻתָּר בִּדְבַשׁ תְּמָרִים. מִן הַסִּתְוָנִיּוֹת מֻתָּר בְּחֹמֶץ סִתְוָנִיּוֹת. מִן הַיַּיִן מֻתָּר בְּיֵין תַּפּוּחִים. מִן הַשֶּׁמֶן מֻתָּר בְּשֶׁמֶן שֻׁמְשְׁמִין. מִן הַדְּבַשׁ מֻתָּר בִּדְבַשׁ תְּמָרִים. מִן הַחֹמֶץ מֻתָּר בְּחֹמֶץ סִתְוָנִיּוֹת. מִן הַיָּרָק מֻתָּר בְּיַרְקוֹת שָׂדֶה. מִפְּנֵי שֶׁכָּל אֵלּוּ שֵׁם לְוַוי הֵם וְהוּא לֹא נָדַר אֶלָּא מִשֵּׁם שֶׁאֵינוֹ לְוַוי בְּאוֹתוֹ מָקוֹם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַנּוֹדֵר מִן הַכְּסוּת מֻתָּר בְּשַׂק וּבִירִיעָה וּבַחֲמִילָה. מִן הַבַּיִת אָסוּר בַּעֲלִיָּה שֶׁהָעֲלִיָּה בִּכְלַל הַבַּיִת. נָדַר מִן הָעֲלִיָּה מֻתָּר בַּבַּיִת. מִן הַדַּרְגָּשׁ מֻתָּר בַּמִּטָּה. מִן הַמִּטָּה אָסוּר בַּדַּרְגָּשׁ שֶׁהוּא כְּמוֹ מִטָּה קְטַנָּה:","הַנּוֹדֵר שֶׁלֹּא יִכָּנֵס לְבַיִת זֶה הֲרֵי זֶה אָסוּר מִן הָאֲגַף וְלִפְנִים. נָדַר שֶׁלֹּא יִכָּנֵס לְעִיר זוֹ מֻתָּר לְהִכָּנֵס לִתְחוּמָהּ וְאָסוּר לְהִכָּנֵס לְעִבּוּרָהּ:","הַנּוֹדֵר הֲנָיָה מִבְּנֵי הָעִיר וּבָא אָדָם וְנִשְׁתַּהָה שָׁם שְׁנֵים עָשָׂר חֹדֶשׁ הֲרֵי זֶה אָסוּר לֵהָנוֹת מִמֶּנּוּ. פָּחוֹת מִכָּאן מֻתָּר. נָדַר מִיּוֹשְׁבֵי הָעִיר כָּל שֶׁשָּׁהָה שָׁם שְׁלֹשִׁים יוֹם אָסוּר לֵהָנוֹת מִמֶּנּוּ. פָּחוֹת מִכֵּן מֻתָּר:","הַנּוֹדֵר מִן הַמַּיִם הַנִּמְשָׁכִין מִמַּעְיָן פְּלוֹנִי. אָסוּר בְּכָל הַנְּהָרוֹת הַיּוֹנְקוֹת מִמֶּנּוּ וְאֵין צָרִיךְ לוֹמַר הַנִּמְשָׁכוֹת. אַף עַל פִּי שֶׁנִּשְׁתַּנָּה שְׁמָם וְאֵין קוֹרִין אוֹתָן אֶלָּא נָהָר פְּלוֹנִי וּבְאֵר פְּלוֹנִי וְאֵין מְלַוִּין אוֹתָן לְשֵׁם הַמַּעְיָן הַנָּדוּר הוֹאִיל וְהוּא עִקָּרָן אָסוּר בַּכּל. אֲבָל אִם נָדַר מִנָּהָר פְּלוֹנִי אוֹ מִמַּעְיָן פְּלוֹנִי אֵין אָסוּר אֶלָּא בְּכָל הַנְּהָרוֹת הַנִּקְרָאוֹת עַל שְׁמוֹ:","הַנּוֹדֵר מִיּוֹרְדֵי הַיָּם מֻתָּר בְּיוֹשְׁבֵי הַיַּבָּשָׁה. מִיּוֹשְׁבֵי הַיַּבָּשָׁה אָסוּר בְּיוֹרְדֵי הַיָּם אַף עַל פִּי שֶׁהֵן מְפָרְשִׁים בְּאֶמְצַע הַיָּם הַגָּדוֹל. שֶׁיּוֹרְדֵי הַיָּם בִּכְלַל יוֹשְׁבֵי הַיַּבָּשָׁה. נָדַר מֵרוֹאֵי חַמָּה אָסוּר בְּסוּמִין שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא מִמִּי שֶׁהַחַמָּה רוֹאָה אוֹתוֹ. נָדַר מִשְּׁחוֹרֵי הָרֹאשׁ אָסוּר בְּקֵרְחִים וּבַעֲלֵי שֵׂיבוֹת וּמֻתָּר בְּנָשִׁים וּבִקְטַנִּים. וְאִם דַּרְכָּן לִקְרוֹת שְׁחוֹרֵי הָרֹאשׁ לַכּל אָסוּר בַּכּל:","נָדַר מִשּׁוֹבְתֵי שַׁבָּת אָסוּר בְּיִשְׂרָאֵל וּבְכוּתִים. נָדַר מֵעוֹלֵי יְרוּשָׁלַיִם אָסוּר בְּיִשְׂרָאֵל וּמֻתָּר בְּכוּתִים. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא לְמִי שֶׁמִּצְוָה עָלָיו לַעֲלוֹת לִירוּשָׁלַיִם. וְהַנּוֹדֵר מִבְּנֵי נֹחַ מֻתָּר בְּיִשְׂרָאֵל שֶׁאֵין נִקְרָאִים בְּנֵי נֹחַ אֶלָּא שְׁאָר הָאֻמּוֹת:","נָדַר מִזֶּרַע אַבְרָהָם מֻתָּר בִּבְנֵי יִשְׁמָעֵאל וּבְנֵי עֵשָׂו וְאֵינוֹ אָסוּר אֶלָּא בְּיִשְׂרָאֵל. שֶׁנֶּאֱמַר (בראשית כא יב) \"כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע\" וַהֲרֵי יִצְחָק אָמַר לְיַעֲקֹב (בראשית כח ד) \"וְיִתֶּן לְךָ אֶת בִּרְכַּת אַבְרָהָם\":","נָדַר מִן הָעֲרֵלִים אָסוּר בְּמוּלֵי עַכּוּ\"ם וּמֻתָּר בַּעֲרֵלֵי יִשְׂרָאֵל. נָדַר מִן הַמּוּלִים אָסוּר בְּעַרְלֵי יִשְׂרָאֵל וּמֻתָּר בְּמוּלֵי עַכּוּ\"ם. שֶׁאֵין הָעָרְלָה קְרוּיָה אֶלָּא לְשֵׁם עַכּוּ\"ם שֶׁנֶּאֱמַר (ירמיה ט כה) \"כִּי כָל הַגּוֹיִם עֲרֵלִים\" וְאֵין כַּוָּנָתוֹ שֶׁל זֶה אֶלָּא לְמִי שֶׁהוּא מְצֻוֶּה עַל הַמִּילָה וְלֹא לְמִי שֶׁאֵינוֹ מְצֻוֶּה עָלֶיהָ:","הַנּוֹדֵר מִיִּשְׂרָאֵל אָסוּר בְּגֵרִים. מִן הַגֵּרִים מֻתָּר בְּיִשְׂרָאֵל. הַנּוֹדֵר מִיִּשְׂרָאֵל אָסוּר בְּכֹהֲנִים וּלְוִיִּם. מִן הַכֹּהֲנִים וּמִן הַלְוִיִּם מֻתָּר בְּיִשְׂרָאֵל. הַנּוֹדֵר מִן הַכֹּהֲנִים מֻתָּר בִּלְוִיִּם. מֵהַלְוִיִּם מֻתָּר בְּכֹהֲנִים. הַנּוֹדֵר מִבָּנָיו מֻתָּר בִּבְנֵי בָּנָיו. וּבְכָל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן דִּין הַנּוֹדֵר וְהַנִּשְׁבָּע אֶחָד הוּא:"]} as Record<string, string[]>;
